window.ZNK_DATA={"schema":1,"book":"中医内科学（第六版）","chapters":[{"no":"第四章","name":"感冒","id":"d001"},{"no":"第五章","name":"咳嗽","id":"d002"},{"no":"第六章","name":"哮病","id":"d003"},{"no":"第七章","name":"喘证","id":"d004"},{"no":"第八章","name":"肺胀","id":"d005"},{"no":"第九章","name":"肺痈","id":"d006"},{"no":"第十章","name":"肺痨","id":"d007"},{"no":"第十一章","name":"肺痿","id":"d008"},{"no":"第十二章","name":"心悸","id":"d009"},{"no":"第十三章","name":"胸痹","id":"d010"},{"no":"第十四章","name":"心衰","id":"d011"},{"no":"第十五章","name":"不寐","id":"d012"},{"no":"第十六章","name":"头痛","id":"d013"},{"no":"第十七章","name":"眩晕","id":"d014"},{"no":"第十八章","name":"中风","id":"d015"},{"no":"第十九章","name":"痴呆","id":"d016"},{"no":"第二十章","name":"癫狂","id":"d017"},{"no":"第二十一章","name":"痫证","id":"d018"},{"no":"第二十二章","name":"胃痛","id":"d019"},{"no":"第二十三章","name":"胃痞","id":"d020"},{"no":"第二十四章","name":"呕吐","id":"d021"},{"no":"第二十五章","name":"呃逆","id":"d022"},{"no":"第二十六章","name":"噎膈","id":"d023"},{"no":"第二十七章","name":"腹痛","id":"d024"},{"no":"第二十八章","name":"泄泻","id":"d025"},{"no":"第二十九章","name":"痢疾","id":"d026"},{"no":"第三十章","name":"便秘","id":"d027"},{"no":"第三十一章","name":"胁痛","id":"d028"},{"no":"第三十二章","name":"黄疸","id":"d029"},{"no":"第三十三章","name":"积聚","id":"d030"},{"no":"第三十四章","name":"鼓胀","id":"d031"},{"no":"第三十五章","name":"瘿病","id":"d032"},{"no":"第三十六章","name":"疟疾","id":"d033"},{"no":"第三十七章","name":"水肿","id":"d034"},{"no":"第三十八章","name":"淋证","id":"d035"},{"no":"第三十九章","name":"癃闭","id":"d036"},{"no":"第四十章","name":"阳痿","id":"d037"},{"no":"第四十一章","name":"遗精","id":"d038"},{"no":"第四十二章","name":"郁证","id":"d039"},{"no":"第四十三章","name":"血证","id":"d040"},{"no":"第四十四章","name":"痰饮","id":"d041"},{"no":"第四十五章","name":"消渴","id":"d042"},{"no":"第四十六章","name":"汗证","id":"d043"},{"no":"第四十七章","name":"内伤发热","id":"d044"},{"no":"第四十八章","name":"厥证","id":"d045"},{"no":"第四十九章","name":"虚劳","id":"d046"},{"no":"第五十章","name":"癌病","id":"d047"},{"no":"第五十一章","name":"肥胖","id":"d048"},{"no":"第五十二章","name":"痹证","id":"d049"},{"no":"第五十三章","name":"痿证","id":"d050"},{"no":"第五十四章","name":"颤证","id":"d051"},{"no":"第五十五章","name":"痉证","id":"d052"},{"no":"第五十六章","name":"腰痛","id":"d053"}],"diseases":[{"id":"d001","name":"感冒","kind":"main","parent":null,"chapterNo":"第四章","chapterName":"感冒","yinbing":[{"t":"b","x":"1. 六淫病邪"},{"t":"p","x":"外感风、寒、暑、湿、燥、火六淫邪气，均可引发感冒，其中风为六淫之首，流动于四时之中，故感冒常以风邪为先导。"},{"t":"b","x":"2. 时行疫疠"},{"t":"p","x":"若四时六气失常，非其时而有其气，伤人致病者，一般较感受当令之气发病者为重。而非时之气夹时行疫毒伤人，则病情重而多变，往往相互传染，造成广泛流行，且不限于季节性。"},{"t":"p","x":"《诸病源候论·时气病诸候》所言：“夫时气病者，此皆因岁时不和，温凉失节，人感乖戾之气而生，病者多相染易。”"}],"bingji":[{"t":"p","x":"感冒的基本病机是邪犯肺卫，卫表不和，病位在肺卫。"},{"t":"p","x":"《素问·太阴阳明论》云：“伤于风者，上先受之。”"},{"t":"p","x":"《灵枢·百病始生》曰：“风雨寒热不得虚，邪不能独伤人。”"},{"t":"p","x":"也有素体虚弱，卫表不固，稍有不慎即易感邪者，发为虚体感冒。"},{"t":"p","x":"阳虚者感邪易从寒化，阴虚者感邪易从热化、燥化。"},{"t":"p","x":"感冒的病理性质以表实证居多，但久病反复或年老体弱，可见气虚、阴虚、阳虚等虚候或虚实夹杂之候。"},{"t":"p","x":"病理因素以风邪为核心，常兼夹寒、热、暑、湿、燥等外邪，或以时行疫毒为主导。"},{"t":"p","x":"感受风寒湿邪，则皮毛闭塞，邪郁于肺，肺气失宣；感受风热暑燥，邪热犯肺，肺失清肃。"},{"t":"p","x":"如感受时行疫毒则病情多重，甚或变生他病，在病程中可见寒与热的转化或错杂。"},{"t":"p","x":"一般而言，感冒属轻浅之疾，及时有效诊治，预后良好。"},{"t":"p","x":"但时行感冒或年老体弱者，病邪容易从表入里，迅速传变，临证时需加以重视，及时防治，以免恶化。"},{"t":"p","x":"此外，感冒病程的长短与感邪的类型、正气的强弱有关。"},{"t":"p","x":"风寒、风热容易疏散，但暑湿感冒较为缠绵，虚体感冒则迁延难愈或容易复感。"}],"zhenduan":[{"t":"ol","items":["1. 感冒以鼻塞、流涕、喷嚏、咽痒、咽痛、咳嗽、头痛、恶风或恶寒、发热、周身酸楚等鼻咽及卫表症状为主，可伴胸闷、脘痞、纳呆、便溏等其他症状。","2. 时行感冒多呈流行性，同一时期发病人数骤增，且病证相似，常表现为突然起病、恶寒、发热（高热多见）、周身酸痛、疲乏无力。病情一般较普通感冒重。","3. 病程一般3～7天，普通感冒不易传变，而时行感冒少数可传变入里，变生他病。","4. 四季皆可发病，而以冬、春两季为多。"]}],"jianbie":[{"t":"b","x":"1. 风温"},{"t":"p","x":"风温初起症状与感冒相似。"},{"t":"p","x":"但风温发病急骤，热势较高，汗出后热虽降，但脉数不静，身热旋即复起，咳嗽胸痛，头痛较剧，甚至出现神志昏迷、惊厥、谵妄等传变入里的证候。"},{"t":"p","x":"普通感冒发热一般不高或不发热，服解表药后，多能汗出热退，脉静身凉，病势轻，病程短，不传变，预后良好。"},{"t":"b","x":"2. 鼻渊"},{"t":"p","x":"鼻渊与感冒均有流涕、头痛等临床表现。"},{"t":"p","x":"但鼻渊多流浊涕腥臭，眉棱骨处胀痛、压痛明显，一般无恶寒发热，病程较长，反复发作，不易痊愈。"},{"t":"p","x":"感冒多流清涕，无腥臭异味，头痛范围不限于前额或眉棱骨处，寒热表证明显，病程较短，愈后症状消失。"}],"bianzheng":[{"t":"b","x":"1. 辨偏实与偏虚"},{"t":"p","x":"感冒虚实辨别见表 4-1。"},{"t":"table","caption":"表4-1 感冒虚实辨别表","head":["病性","偏实","偏虚"],"rows":[["病机","外邪侵袭，卫表不和，肺失宣肃","素体虚弱，卫外不固，易反复感邪"],["证候","有风寒束表、风热犯表、暑湿伤表之分","有气虚、阴虚、阳虚之别"]]},{"t":"table","caption":"表 4-2 风寒与风热感冒辨别表","head":["临床表现","风寒感冒","风热感冒"],"rows":[["恶寒","重","轻"],["发热","轻","重"],["口渴","口不渴","口渴"],["出汗","无汗","少汗或有汗"],["咽痛","无","有"],["舌苔","苔薄白","苔薄黄"],["脉象","浮紧","浮数"]]},{"t":"table","caption":"表 4-3 兼夹证辨别表","head":["兼夹证","好发时机","症状特点"],"rows":[["夹湿","长夏","身热不扬，头重如裹，肢体酸痛，胸闷脘痞，舌苔腻"],["夹暑","夏季","身热有汗，心烦口渴，小便短赤，舌苔薄黄"],["夹燥","秋季","身热头痛，咽干鼻燥，干咳无痰或有黏痰，口渴欲饮"],["夹食","饱食后","身热，脘痞纳呆，恶心欲呕，大便溏薄，脉滑"]]}],"zhize":"感冒的治疗应遵《素问·阴阳应象大论》“其在皮者，汗而发之”之意，因势利导，使从表而解，以解表达邪为基本治则。风寒证治以辛温散寒，风热证治以辛凉清解，暑湿夹杂者应当清暑祛湿解表，虚体感冒又当解表与扶正并施。","syndrome":[{"id":"s001","name":"风寒束表证","label":"1. 风寒束表证","group":"","clinic":"恶寒重，发热轻，无汗，头痛，肢体酸痛，鼻塞声重，喷嚏，流清涕，咽痒，咳嗽，痰白稀薄，舌淡红，苔薄白，脉浮紧。","analysis":"风寒之邪外束肌表，卫阳被遏，故见恶寒、发热、无汗；清阳不展，络脉失和，则见头痛、肢体酸痛；风寒上受，肺气不宣，而致鼻塞、喷嚏、流清涕、咽痒、咳嗽、痰白稀；舌淡红，苔薄白，脉浮紧，为表寒之象。","treat":"辛温解表，宣肺散寒。","formulaRaw":"荆防败毒散（《摄生众妙方》）加减。","formulaName":"荆防败毒散加减","fangjie":"荆芥、防风、生姜辛温散寒；柴胡、薄荷解表退热；羌活、独活、川芎祛风止痛；桔梗、枳壳、前胡、茯苓、甘草宣通肺气，化痰止咳。若恶寒甚，可加麻黄、桂枝等；若鼻塞流涕重者，可加辛夷、苍耳子等；若头项强痛，可加白芷、葛根等；若胸闷痞满，不思饮食，舌苔白腻，可加藿香、苍术、厚朴等。"},{"id":"s002","name":"风热犯表证","label":"2. 风热犯表证","group":"","clinic":"身热较著，微恶风，汗泄不畅，头胀痛，鼻塞，流黄稠涕，咽干甚至咽痛，咳嗽，痰黏色黄，口干欲饮，舌质红，苔薄黄，脉浮数。","analysis":"风热犯表，热郁肌腠，卫表失和，故见身热、微恶风、汗泄不畅；风热上扰，故头胀痛；风热熏蒸清窍，故见鼻塞、流黄稠涕、咽痛、口干；风热犯肺，肺失清肃，故见咳嗽、痰黏或黄；舌质红，苔薄黄，脉浮数，为风热犯表之征。","treat":"辛凉解表，疏风清热。","formulaRaw":"银翘散（《温病条辨》）加减。","formulaName":"银翘散加减","fangjie":"金银花、连翘、豆豉、薄荷辛凉解表，疏风清热；荆芥助疏解之力；竹叶、芦根清热生津；牛蒡子、桔梗、甘草宣利肺气，化痰利咽。若发热甚，可加黄芩、石膏、大青叶等；若头胀痛甚，可加桑叶、菊花、蔓荆子等；若咽喉肿痛，可加山豆根、玄参等；若咳嗽，痰黄稠，可加黄芩、浙贝母、瓜蒌皮等；若口渴多饮，可加天花粉、知母等。"},{"id":"s003","name":"暑湿伤表证","label":"3. 暑湿伤表证","group":"","clinic":"发热，微恶风，身热不扬，汗出不畅，肢体困重或酸痛，胸闷脘痞，纳呆，心烦口渴，大便溏薄，小便短赤，舌质红，舌苔腻，脉濡数或滑。","analysis":"暑湿伤表，卫表不和，故身热不扬、微恶风、汗出不畅、肢体困重；暑湿困阻，清阳不升，脾运失健，故头重如裹、胸闷脘痞、纳呆、便溏；暑热犯肺，肺气不清，热灼津伤，故鼻塞、流浊涕、心烦口渴、小便短赤；舌质红，舌苔腻，脉濡数或滑，为风暑夹湿之象。","treat":"清暑祛湿解表。","formulaRaw":"新加香薷饮（《温病条辨》）加减。","formulaName":"新加香薷饮加减","fangjie":"金银花、连翘清解暑热；香薷发汗解表；厚朴、鲜扁豆花化湿和中。若暑热偏盛，可加黄连、青蒿等；若肢体酸重疼痛较甚，可加广藿香、佩兰等；若胸闷脘痞，腹胀便糖，可加苍术、草豆蔻、陈皮等；若小便短赤较明显，可加滑石、甘草等。"},{"id":"s004","name":"肺气亏虚证","label":"1. 肺气亏虚证","group":"虚体感冒","clinic":"鼻塞，流涕，恶寒，或见发热，气短，乏力，自汗，平素神疲体弱，或易感冒，舌淡红，苔薄白，脉浮无力。","analysis":"平素肺气亏虚，故神疲体弱、气短乏力；卫外不固，故自汗、易感冒；风邪乘虚客表，故见恶寒发热、鼻塞流涕；舌淡红，苔薄白，脉浮无力，为气虚外感、邪在卫表之象。","treat":"益气解表，调和营卫。","formulaRaw":"参苏饮（《太平惠民和剂局方》）加减。","formulaName":"参苏饮加减","fangjie":"党参、茯苓、甘草补气以祛邪；紫苏叶、葛根发散表邪；半夏、前胡、桔梗化痰止咳；陈皮、木香、枳壳理气。若乏力，自汗，动则加重，可加黄芪、白术、防风等；若畏寒，四肢欠温，加细辛、附子（制）等。"},{"id":"s005","name":"肺阴不足证","label":"2. 肺阴不足证","group":"虚体感冒","clinic":"鼻塞，流涕，身热，微恶风寒，无汗或微汗或盗汗，口干，头昏，心烦，舌红少苔，脉细数。","analysis":"阴亏卫表失滋，风热乘虚犯表，故鼻塞、流涕、身热、微恶风寒；阴虚不能作汗，则无汗或微汗；虚火内扰，迫津外泄，则心烦、盗汗；虚火上炎，清窍失养，则头昏；津不上承，故口干；舌红少苔，脉细数，乃阴虚内热之象。","treat":"滋阴解表。","formulaRaw":"加减葳蕤汤（《重订通俗伤寒论》）加减。","formulaName":"加减葳蕤汤加减","fangjie":"葳蕤滋阴，以资汗源；薄荷疏散风热，清利咽喉；淡豆豉、葱白发表散邪；白薇清热益阴；桔梗、甘草、大枣宣肺止咳，甘润和中。若心烦口渴较甚，可加沙参、栀子、天花粉等；若盗汗明显，可加煅牡蛎、糯稻根等；若咳嗽痰少，可加百部、枇杷叶等。"},{"id":"s006","name":"阳气虚弱证","label":"3. 阳气虚弱证","group":"虚体感冒","clinic":"鼻塞，流清涕，恶寒重，发热轻，面色㿠白，语声低微，四肢不温，舌质淡胖，舌苔白，脉沉细无力。","analysis":"素体阳虚，风寒袭表，故鼻塞、流清涕、恶寒重而发热轻；阳气不足，失却温煦，则语声低微、面色㿠白、四肢不温；舌质淡胖，舌苔白，脉沉细无力，乃阳气虚弱之象。","treat":"助阳解表。","formulaRaw":"麻黄附子细辛汤（《伤寒论》）加减。","formulaName":"麻黄附子细辛汤加减","fangjie":"麻黄辛温散寒；附子（制）温阳祛邪；细辛助阳解表。若咳嗽痰白，咳痰无力，可加半夏、苦杏仁、干姜等；若全身酸痛，头重如裹，可加羌活、独活、苍术、薏苡仁等。"}],"linchuang":["重视特殊人群感冒和时行感冒。普通感冒病情较轻，全身症状不重，少有传变。但老年人、婴幼儿、体弱者，或因感受外邪较重，或是小儿感冒夹惊夹食，或原有宿疾复加新感，临床表现及其顺逆转归有别于其他人群，应当重视其特殊性。若感冒7日以上未愈，发热不退，或反见加重，应考虑继发他病。若为时行感冒，起病较急，全身症状明显，具有广泛的传染性、流行性，可发生传变入里，病情转重。","辨清病性，准确施治。感冒的病性有寒热之分，也有虚实之别。治疗上，风寒者应辛温解表，风热者宜辛凉解表，寒热二证不显者，可予辛平轻剂。若风寒外感，表尚未解，内郁化热，或肺有蕴热，复感风寒之证，可温清并施，取辛温与辛凉合用之法，以解表清里，表里双解。除虚体感冒兼顾扶正补虚外，实性感冒一般避免补益收敛，以免闭门留寇。素体正气不足、卫外不固而致感冒反复发作者，可根据正虚性质不同而分别益气、养阴、温阳等。","用药须考虑宜忌，煎服应注意方法。治疗感冒应当遵循“治上焦如羽，非轻不举”的原则，选用气薄味辛质轻之药以达轻清宣散之效，而过寒过热过润过燥之剂皆所不宜。若风寒之候误投辛凉之品，汗不易出，病邪难以外达，反碍速解，甚或发生变证；而风热之证误用辛温之剂，则有助热燥液动血之弊，或引起传变。此外，使用解表中药治疗感冒需注意煎药和服药方法。煎药时间宜短，不可过煮，取其气全以增疗效。风寒表实证趁温热服，服药后进热粥、米汤以助药力，或覆被以促汗解表，汗后及时更换干燥洁净衣物，并应避风以免再次受邪。"],"yufang":["预防感冒，生活上应起居有常，避免过劳；加强体育锻炼，增强体质。气候变化时适时增减衣服，防寒保暖；注意个人卫生，保持室内通风，空气清新，阳光充足。平素易感冒者，可坚持每天按摩迎香穴，并适当服用调理防治方药。在流行季节，室内可用食醋熏蒸法进行空气消毒，并尽量少去人口密集的公共场所，防止交叉感染。","感冒患者应适当休息，多饮温开水，饮食以清淡为主，忌肥甘厚味和辛辣酒食。对时行感冒重症患者、老年人、婴幼儿或平素体弱者，须密切观察，关注病情变化。"],"attachIds":[]},{"id":"d002","name":"咳嗽","kind":"main","parent":null,"chapterNo":"第五章","chapterName":"咳嗽","yinbing":[{"t":"p","x":"咳嗽的病因有外感与内伤两大类。外感咳嗽为六淫外邪侵袭肺系，内伤咳嗽为脏腑功能失调，内邪干肺。不论邪从外入，或邪自内生，均可引起肺失宣肃，肺气上逆，发为咳嗽。"},{"t":"b","x":"1. 外感六淫邪气"},{"t":"p","x":"六淫主要指风、寒、暑、湿、燥、火六种邪气，外邪从口鼻或皮毛而入，侵袭肺系，或吸入烟尘、异味气体，使肺失宣降，气机上逆，引起咳嗽。"},{"t":"p","x":"风为六淫之首，百病之长，外感咳嗽常以风邪为先导，夹寒、热、燥等外邪，表现为风寒、风热、风燥咳嗽，其中又以风邪夹寒者居多，即张介宾所谓“六气皆令人咳，风寒为主”。"},{"t":"b","x":"2. 内邪干肺"},{"t":"p","x":"（1）肺脏自病：肺系多种疾病迁延日久，或长期吸烟，耗伤肺气、肺阴，影响肺之宣降功能，致肺气上逆。"},{"t":"p","x":"（2）他脏及肺：饮食不节，嗜食生冷，烟酒过度，或过食辛辣肥甘之品，损伤脾胃，脾失健运，痰湿内生，上渍于肺；或情志不调，肝失疏泄，气郁化火，木火刑金；或年老体弱，肾精亏耗，气失摄纳。"}],"bingji":[{"t":"p","x":"咳嗽的基本病机为邪犯于肺，肺失宣降，肺气上逆。"},{"t":"p","x":"病位主要在肺，与肝、脾有关，久病及肾。"},{"t":"p","x":"若外邪未及时疏散，还可发生演变转化，如风寒入里化热，风热灼津化燥，肺热蒸液成痰等。"},{"t":"p","x":"内伤咳嗽迁延日久，脏器多虚，病理性质属邪实与正虚并见，病理因素主要为痰与火。"},{"t":"p","x":"痰火互为因果，痰可郁而化火（热），火热炼液灼津为痰。"},{"t":"p","x":"久病或热病伤阴，肺络失养，或体质虚弱，久咳伤气，病及于肾，肺虚不能主气，肾虚不能纳气，表现为咳嗽无力，气短声低，遇劳加重，甚则由咳致喘。"},{"t":"p","x":"咳嗽虽有外感与内伤之分，但可相互为病，互为因果。"},{"t":"p","x":"外感咳嗽迁延日久，邪伤肺气，更易反复感邪，而致咳嗽屡作，肺脏益伤，逐渐发展为内伤咳嗽。"},{"t":"p","x":"内伤咳嗽，肺气不足，卫外不固，易受外邪侵袭引发或加重，在天气变化时尤为明显，所谓“正气存内，邪不可干”，“邪之所凑，其气必虚”。"},{"t":"p","x":"一般而言，外感咳嗽其病尚浅而易治，但燥与湿二者较为缠绵。"},{"t":"p","x":"因湿邪困脾，久则脾虚而致积湿生痰，转为内伤之痰湿咳嗽。"},{"t":"p","x":"燥伤肺津，久则肺阴亏耗，成为内伤阴虚肺燥之咳嗽，故有“燥咳每成痨”之说。"},{"t":"p","x":"尤其老年高龄伴有基础病患者，病久反复发作，容易出现肺脾肾俱虚，甚至累及心脏，痰浊、水饮、血瘀互结，而演变为肺胀。"}],"zhenduan":[{"t":"p","x":"咳嗽以咳逆有声，或咳吐痰液为主症。外感咳嗽起病急，病程短，常伴恶寒、发热等表证；内伤咳嗽病程长，反复发作，多伴脏腑失调的症状。"}],"jianbie":[{"t":"b","x":"1. 风温肺热病"},{"t":"p","x":"二者均有咳嗽表现，风温肺热常以发热、恶寒为主症，伴有咳嗽、咳痰，且从胸部影像学来看，存在肺内感染性病变。"},{"t":"b","x":"2. 其他病证"},{"t":"p","x":"咳嗽还常见于肺痈、哮病、喘证、肺痨和肺胀等病中，在相关疾病中要与本病进行鉴别。"}],"bianzheng":[{"t":"b","x":"1. 辨外感与内伤"},{"t":"p","x":"外感咳嗽，多为新病，起病急，病程短，常伴有恶寒、发热、头痛、鼻塞流涕等肺卫表证。内伤咳嗽多为宿病，反复发作，迁延不愈，起病缓，病程长，常兼他脏症状，多属邪实正虚。"},{"t":"b","x":"2. 辨证候虚实"},{"t":"p","x":"外感咳嗽以风寒、风热、风燥为主，一般均属邪实。而内伤咳嗽多为虚实夹杂，本虚标实，其中痰湿、痰热、肝火多为邪实，脾虚湿盛、肺阴亏耗、肾气不足则属正虚，或虚中夹实。辨治时应分清标本主次缓急。"},{"t":"b","x":"3. 辨咳嗽的特点"},{"t":"p","x":"从咳嗽时间看，白天多于夜间，咳而急剧，声重，咽痒作咳，病势急而病程短者，多为外感风寒、风热、风燥引起；早晨咳嗽，阵发性加剧，咳嗽连声重浊，痰出咳减者，多为痰湿或痰热咳嗽；午后、黄昏咳嗽加重，或夜间时有咳嗽，咳声轻微短促者，多属肺燥阴虚；夜卧咳嗽较剧，持续不已，少气或伴气喘者，多为久咳致喘的虚寒证。"},{"t":"p","x":"从咳嗽声音辨，咳声重浊多属风寒、痰湿；咳声洪亮有力多属实热；咳声低怯多属气虚；咳声嘶哑多属燥热、阴虚。"},{"t":"p","x":"从诱发因素看，饮食肥甘、生冷加重者多属痰湿证；情志郁怒加重者属木火刑金、肝气犯肺证；劳累、受凉后加重者多为痰湿、虚寒证。"},{"t":"b","x":"4. 辨咳痰的特点"},{"t":"p","x":"宜从痰的色、质、量、味多方面辨别。咳而痰少者多属燥热、气火、阴虚；痰多者多属湿痰、痰热、虚寒。痰白而稀薄者多属风、属寒；痰黄而稠者属热；痰白质黏者属阴虚、燥热；痰白清稀、透明、呈泡沫样者属虚、属寒。咳吐血痰者多为肺热或阴虚；脓血相兼者多为痰热郁结成痈之候；咳嗽，咳粉红色泡沫痰，咳而气喘，呼吸困难者，多属心肺阳虚，气不摄血。咳痰有热腥味或腥臭气者为痰热，味甜者属痰湿，味咸者属肾虚。"}],"zhize":"咳嗽的治疗应分清邪正虚实。外感咳嗽，多为实证，应祛邪利肺，按病邪性质分风寒、风热、风燥论治。内伤咳嗽，多属邪实正虚。标实为主者，治以祛邪止咳，本虚为主者，治以扶正补虚，并按本虚标实的主次酌情兼顾。同时除直接治肺外，还应从整体出发，注意健脾、疏肝、补肾等。咳嗽初期一般忌敛涩留邪，当因势利导，肺气宣畅则咳嗽自止；咳嗽日久，当祛邪止咳，扶正补虚，标本兼顾。","syndrome":[{"id":"s007","name":"风寒袭肺证","label":"1. 风寒袭肺证","group":"","clinic":"咳嗽声重，气急咽痒，咳痰稀薄色白，鼻塞，流清涕，头痛，肢体酸楚，恶寒重，发热轻，无汗。舌苔薄白，脉浮或浮紧。","analysis":"风寒之邪外束肌表，内干于肺，肺卫失宣，肺气闭郁，不能宣发，故咳嗽声重，气急咽痒；寒邪郁肺，气不布津，凝聚为痰，故痰白清稀；风寒外束于表，皮毛闭塞，卫阳被遏，故兼有鼻塞、流清涕、头痛、肢体酸楚、恶寒、发热、无汗等风寒表证。舌苔薄白，脉浮或浮紧，均为风寒袭肺之象。","treat":"疏风散寒，宣肺止咳。","formulaRaw":"三拗汤（《太平惠民和剂局方》）合止嗽散（《医学心悟》）加减。","formulaName":"三拗汤合止嗽散加减","fangjie":"麻黄、荆芥疏风散寒，合杏仁宣降肺气；紫菀、百部、白前、陈皮理肺祛痰；桔梗、甘草利咽止咳。若痰黏胸闷，苔腻者，加半夏、厚朴；若风寒外束，里有郁热，咳嗽音哑，气急似喘，痰液黏稠，口渴，心烦，或有身热者，可加石膏、桑白皮、黄芩，或用麻杏石甘汤；若寒饮伏肺，风寒束表，可用小青龙汤。"},{"id":"s008","name":"风热犯肺证","label":"2. 风热犯肺证","group":"","clinic":"咳嗽频剧，气粗或咳声嘶哑，喉燥咽痛，咳痰不爽，痰黏稠或黄稠，咳时汗出，鼻流黄涕，口渴，头痛，四肢酸楚，身热，恶风。舌质红，苔薄黄，脉浮数或浮滑。","analysis":"风热犯肺，肺失清肃，而见咳嗽频剧，气粗或咳声音哑；肺热伤津，则见口渴，喉燥咽痛；肺热内郁，蒸液成痰，故痰黏而稠，咳吐不爽；风热犯表，卫表不和，而见鼻流黄涕、头痛、汗出、四肢酸楚、恶风、身热等表热证。舌质红，苔薄黄，脉浮数或浮滑，均为风热犯肺之象。","treat":"疏风清热，宣肺止咳。","formulaRaw":"桑菊饮（《温病条辨》）加减。","formulaName":"桑菊饮加减","fangjie":"桑叶清透肺络之热；菊花疏散上焦风热；薄荷辛凉透表；连翘清热解毒；杏仁、桔梗宣肺降气止咳；芦根清热生津止咳；甘草调和诸药。若肺热甚者，可加黄芩、金银花、鱼腥草；咽痛者，可加射干、青果、牛蒡子；热伤肺津，咽燥口干，舌质红者，可加沙参、天花粉；夏令夹暑湿，症见咳嗽胸闷，心烦口渴，尿赤者，可加鲜荷叶、六一散（滑石、甘草）。"},{"id":"s009","name":"风燥伤肺证","label":"3. 风燥伤肺证","group":"","clinic":"干咳无痰，或痰少而黏成丝，咳痰不爽，咽痒，或痰中带有血丝，唇鼻干燥，咽干而痛，口干，或兼鼻塞、头痛、微恶寒、身热等表证。舌质红而干，苔薄白或薄黄，脉浮数或小数。","analysis":"风燥伤肺，肺失清润，故见干咳无痰，或痰少而黏成丝，咳痰不爽，咽痒；燥热伤津，鼻咽失濡，则咽喉口鼻干燥，痰黏不易咳出；燥热伤肺，肺络受损，故痰中夹血丝；风燥外客，卫气不和，则见鼻塞、头痛、微恶寒、身热等表证。舌红而干，苔薄白或薄黄，脉浮数或小数，乃风燥伤肺之征。","treat":"疏风清肺，润燥止咳。","formulaRaw":"桑杏汤（《温病条辨》）加减。","formulaName":"桑杏汤加减","fangjie":"桑叶、淡豆豉疏风解表；杏仁、象贝母化痰止咳；沙参、梨皮生津润燥；栀子清热。若津伤较甚者，可加麦冬、玉竹；热重者，可酌加生石膏、知母；痰中夹血者，可加生地黄、白茅根。\n另有凉燥犯肺咳嗽，为风寒与燥邪相兼犯肺所致，表现为干咳少痰或无痰，咽干鼻燥，兼有恶寒发热，头痛无汗，舌苔薄白而干，治宜疏风散寒，润肺止咳，用药当以温而不燥、润而不凉原则，方取杏苏散（《温病条辨》），药用紫苏叶、杏仁、前胡辛温宣散，紫菀、款冬花、百部、甘草等以温润止咳。恶寒甚，无汗，配荆芥、防风以散寒解表。"},{"id":"s010","name":"风邪伏肺证","label":"4. 风邪伏肺证","group":"","clinic":"阵发性咳嗽或呛咳、咽痒，遇外界寒热变化、冷风、油烟、异味等因素刺激可诱使咳嗽突发或加重，干咳无痰或少痰，夜卧晨起咳剧，咳嗽反复发作或常年不愈。舌淡红，苔薄白，脉弦。","analysis":"风为阳邪，易袭阳位，肺为五脏六腑之华盖，易受风侵，风胜则动，故见阵发性咳嗽或呛咳；风性善行而数变，风邪入里，与气血搏结于咽喉，故见咽痒；肺之经气旺于寅时，风邪稽肺，肺气壅遏不宣而上逆，故见夜卧晨起咳剧；风邪伏肺，久而化热，灼伤肺阴，故见干咳无痰或少痰；外感风邪未尽，久之入里，内风暗生，同气相求，内外风合邪，故遇外界寒热变化、冷风、油烟、异味等因素刺激可诱使咳嗽突发或加重。舌淡红，苔薄白，脉弦，为风邪伏肺之象。","treat":"祛风解痉，宣肺止咳。","formulaRaw":"止嗽散（《医学心悟》）合华盖散（《太平惠民和剂局方》）加减。","formulaName":"止嗽散合华盖散加减","fangjie":"麻黄疏风宣肺，散寒止咳；杏仁、苏子、白前降气化痰，宣肺止咳；紫菀、百部下气化痰，理肺止嗽；桔梗开宣肺气，利咽化痰；橘红理气化痰；茯苓健脾化湿，培土生金；荆芥疏风解表；桑白皮泻肺利水以止咳，同时佐制辛温药物燥热之性；甘草、桔梗利咽止咳，甘草又能调和诸药。若咽痒甚者，可加蝉蜕、木蝴蝶、白蒺藜、地龙；痰多者，可加贝母、全瓜蒌、葶苈子；咳痰色黄者，可加生石膏、金荞麦、浙贝母；津液受损，口燥咽干者，可加沙参、麦冬；口干、口苦、口黏者，可加薏苡仁、佩兰、藿香、白豆蔻。"},{"id":"s011","name":"痰湿蕴肺证","label":"5. 痰湿蕴肺证","group":"","clinic":"咳声重浊，痰多色白黏腻，每于晨间咳痰尤甚，因痰而嗽，痰出则咳缓，胸闷，脘痞腹胀，呕恶食少，大便时溏。舌苔白腻，脉濡滑。","analysis":"痰湿蕴肺，肺失宣降，故咳嗽痰多，咳声重浊，痰白黏腻；湿痰中阻，脾为湿困，故见胸闷，脘痞腹胀，呕恶食少，大便时溏。舌苔白腻，脉濡滑，乃痰湿内蕴之象。","treat":"燥湿化痰，理气止咳。","formulaRaw":"二陈汤（《太平惠民和剂局方》）合三子养亲汤（《韩氏医通》）加减。","formulaName":"二陈汤合三子养亲汤加减","fangjie":"半夏、茯苓燥湿化痰；陈皮、甘草理气和中；白芥子温肺利气，快膈消痰；紫苏子降气行痰，使气降而痰不逆；莱菔子消食导滞，使气行则痰行。两方合用燥湿化痰，理气止咳。若咳而痰多稠厚，胸闷脘痞者，可加苍术、厚朴；若寒痰较重，痰黏白如沫，怕冷者，可加干姜、细辛；若久病脾虚者，可酌加党参、白术。"},{"id":"s012","name":"痰热壅肺证","label":"6. 痰热壅肺证","group":"","clinic":"咳嗽气息粗促，或喉中有痰声，痰多质黏色黄，痰液咳吐不利，或咳血痰，胸胁胀满，咳时引痛，面赤，或身热，口干欲饮。舌质红，苔黄腻，脉滑数。","analysis":"久咳不愈，或者素体痰湿蕴肺，久而化热，痰热互结，壅塞于肺，肺失清肃，故咳嗽气息粗促，痰多质黏色黄，咳吐不爽；热伤肺络，故胸胁胀满，咳时引痛，或咳血痰；肺热内郁，热邪耗伤津液，则面赤，身热，口干欲饮。舌质红，苔黄腻，脉滑数，为痰热内盛之象。","treat":"清热化痰，肃肺止咳。","formulaRaw":"清金化痰汤（《医学统旨》）加减。","formulaName":"清金化痰汤加减","fangjie":"桑白皮、黄芩、栀子、知母清泄肺热；贝母、全瓜蒌、桔梗清热化痰止咳；茯苓、甘草、橘红健脾理气化痰；麦冬养阴润肺以止咳。若痰热甚者，可加竹沥、天竺黄、竹茹；痰黄如脓者，可加鱼腥草、金荞麦、薏苡仁、冬瓜子；痰盛，胸满咳逆，便秘者，可加葶苈子、大黄；痰热伤津较重者，可加沙参、天门冬、天花粉。"},{"id":"s013","name":"肝火犯肺证","label":"7. 肝火犯肺证","group":"","clinic":"气逆作咳，咳则连声，咳时面红目赤，咽干口苦，常感痰滞咽喉，难以咳出，量少质黏，咳引胸痛，症状可随情绪波动增减。舌质红，苔薄黄少津，脉弦数。","analysis":"肝郁化火，上逆侮肺，以致气逆作咳，咳则连声；肝火上炎，故咳时面红，口苦咽干；木火刑金，炼液成痰，肺热津亏，则痰黏难以咳吐；肝肺络气不和，故咳而引痛。舌质红，苔薄黄少津，脉弦数，乃肝火犯肺之象。","treat":"清肝泻肺，化痰止咳。","formulaRaw":"黄芩泻白散（《症因脉治》）合黛蛤散（《医说》）。","formulaName":"黄芩泻白散合黛蛤散","fangjie":"桑白皮、地骨皮、黄芩清肺泻火，化痰止咳；青黛清肝火，泻肺火；蛤壳清肺热，化痰浊；甘草化痰止咳，调和诸药。若火热较盛，咳嗽频作，痰黄者，可加栀子、牡丹皮、枇杷叶；胸闷痰黏难咳者，可加贝母、竹茹、全瓜蒌、旋覆花；胸痛甚者，可加郁金、丝瓜络；火郁伤津，咽燥口干者，可加百合、沙参、麦冬、天花粉。"},{"id":"s014","name":"肺阴亏虚证","label":"8. 肺阴亏虚证","group":"","clinic":"干咳无痰，或痰少，咳吐不爽，咳声短促，痰黏或痰夹血丝，口干咽燥，或潮热盗汗，颧红，形瘦无华。舌质红，少苔，脉细数。","analysis":"肺阴亏虚，虚热内灼，肺失宣肃，则干咳，咳声短促；阴虚肺燥，故少痰，咳吐不爽，口干舌燥；肺损络伤，故痰夹血丝；阴虚火旺，故潮热盗汗，颧红；阴精不足，则形瘦无华。舌质红，少苔，脉细数，为阴虚内热之象。","treat":"养阴清热，润肺止咳。","formulaRaw":"沙参麦冬汤（《温病条辨》）加减。","formulaName":"沙参麦冬汤加减","fangjie":"沙参、麦冬、天花粉、玉竹滋养肺阴，润肺止咳；桑叶轻清宣透，疏散肺热；生扁豆、甘草甘缓和中，培土生金。若痰中带血者，可加牡丹皮、白茅根、仙鹤草、藕节；潮热甚者，可加功劳叶、银柴胡、青蒿、鳖甲、胡黄连；盗汗明显者，可加乌梅、生牡蛎、浮小麦；咳吐黄痰者，可加海蛤粉、知母、黄芩。"},{"id":"s015","name":"肺阳不足证","label":"9. 肺阳不足证","group":"","clinic":"咳嗽，气短，背寒如掌大，咳吐涎沫，质清稀而量多，形寒肢冷，自汗，易感寒，面白神疲，口不渴，腹胀纳差，大便溏。舌质淡胖，苔白润，脉迟缓或迟弦。","analysis":"肺主一身之气，气属阳，阳气虚，肺气虚寒，气不布津，水饮不化，肺失宣降，出现咳嗽，气短，咳吐涎沫，质清稀而量多，口不渴；肺阳亏虚，卫阳不足，故见背寒如掌大，形寒肢冷，自汗，易感寒，面白神疲；子盗母气，子病及母，脾阳不足，故见腹胀纳差，大便溏。舌质淡胖，苔白润，脉迟缓或迟弦，乃肺阳不足之征。","treat":"温肺化饮，止咳化痰。","formulaRaw":"苓甘五味姜辛汤（《金匮要略》）合止嗽散（《医学心悟》）加减。","formulaName":"苓甘五味姜辛汤合止嗽散加减","fangjie":"干姜扶阳祛寒，温化水饮；细辛宣肺散寒，助干姜温化痰饮；茯苓甘淡渗利，健脾祛湿；五味子收敛肺气，防止辛散药物耗气，兼敛阴生津；紫菀、百部下气化痰，理气止咳；荆芥、桔梗宣肺化痰；白前降气祛痰止咳；陈皮理气化痰；甘草合干姜辛甘化阳，助茯苓健脾益气，合桔梗利咽止咳，并可调和诸药。若脾虚，面白神疲者，可加白术、党参、黄芪；肺脾气滞，胸脘胀满者，可加厚朴、香附；表寒重者，可加麻黄、桂枝。\n临床上还有因肾阳虚，喘咳不能平卧，咳痰清稀，面浮肢肿，甚则一身悉肿者，可用真武汤加减治疗，附子（制）温肾助阳，茯苓淡渗利水，生姜温肾散寒行水，白术健脾利湿，芍药敛阴缓急止痛，通利小便，并制附子（制）之温燥。"}],"linchuang":["外感咳嗽与内伤咳嗽病因不同，用药当有不同禁忌。外感咳嗽以邪实为主，初起忌用敛肺、收涩留邪之品，若误用会导致肺气郁遏不得宣畅，邪恋不去，咳嗽迁延不愈，当因势利导，肺气宣畅，则咳嗽自止。内伤久咳，邪实与正虚并见，忌过用宣散之品，若误用会导致阴液耗伤，肺气亏损，正气愈虚，当标本兼顾。","咳嗽治疗重在辨证论治。咳嗽是人体驱邪外达的表现，治疗时不能单纯见咳止咳，注意审证求因，分清标本，因势利导。通常咳嗽的轻重可以反映病邪的微甚，但在某些情况下，因正虚不能驱邪外达，咳虽轻微，但病情却重，应加警惕，给予及时的检查和处理。","久咳需寻因。对于久咳不已，咽痒，常法治疗无效者，要注意进一步寻找久咳病因。"],"yufang":["关于咳嗽的预防，首先应注意气候变化，防寒保暖，避免受凉，戒烟酒。外感后咳嗽要及时治疗，内伤咳嗽在缓解期间，应坚守“缓则治其本”的原则，补虚固本以图根治。","在咳嗽调护方面，应避风邪，节制饮食，少食肥甘厚味，以免蕴湿生痰。风热、气火、风燥、肺阴虚咳嗽，忌食辛辣香燥之品及饮酒，以免伤阴化燥助热。痰多者应尽量将痰排出。咳而无力者，可翻身拍背等助痰排出。要保持心情舒畅，还要适当参加体育锻炼，以增强体质，提高抗病能力。"],"attachIds":[]},{"id":"d003","name":"哮病","kind":"main","parent":null,"chapterNo":"第六章","chapterName":"哮病","yinbing":[{"t":"b","x":"1. 外邪侵袭"},{"t":"p","x":"气候变化为哮病发作的主要诱因。"},{"t":"p","x":"外邪侵袭，内合于肺，“伏痰”遇感引触，痰随气升，气因痰阻，相互搏结，壅塞气道，而致痰鸣如吼，气息喘促。"},{"t":"p","x":"或因吸入花粉、烟尘、异味气体等，影响肺气的宣发，津液凝聚，痰浊内生，亦为致哮的常见诱因。"},{"t":"b","x":"2. 饮食不当"},{"t":"p","x":"或过食生冷，寒饮内停，或嗜食酸咸甘肥，积痰蒸热，或禀赋异常，进食海膻发物，以致脾失健运，痰浊内生，上干于肺，壅塞气道而发。"},{"t":"p","x":"清·何梦瑶《医碥·哮喘》曰：“哮者……得之食味酸咸太过，渗透气管，痰入结聚，一遇风寒，气郁痰壅即发。”"},{"t":"b","x":"3. 情志刺激"},{"t":"p","x":"忧郁恼怒、思虑过度等情志刺激，使肝失条达，气机不畅，气郁化火，气火循经上逆犯肺，或肝气郁结，疏泄失职，津液失布，凝而成痰，或肝郁化火，郁火灼津，炼液成痰，或肝气郁滞，横克脾土，脾失健运，酿液为痰，上贮于肺，以致肺失肃降，发为哮喘。"},{"t":"b","x":"4. 体虚病后"},{"t":"p","x":"体质虚弱，易发哮病。"},{"t":"p","x":"若病后体弱，如幼年患麻疹、顿咳，或反复感冒、咳嗽日久等，以致肺气亏虚，气不化津，痰饮内生，或病后阴虚火旺，热蒸液聚，痰热胶固而致哮。"}],"bingji":[{"t":"p","x":"哮病的基本病机是肺失宣降，引动伏痰。"},{"t":"p","x":"脏腑功能失调，肺不能布散津液，脾不能运化精微，肾不能蒸化水液，以致津液凝聚成痰，痰伏于肺，成为哮病发病的潜在“夙根”。"},{"t":"p","x":"哮病的病位主要在肺，同时与肝、脾、肾密切相关。"},{"t":"p","x":"肺为气之主，肾为气之根，哮病日久，肺虚及肾，摄纳失常，每可使病情发作加重。"},{"t":"p","x":"发作时痰阻气闭，表现为痰鸣气喘，以邪实为主。"},{"t":"p","x":"在缓解期以肺、脾、肾虚为主，表现为短气、疲乏，常有轻度哮喘。"},{"t":"p","x":"病理因素以痰为主，朱丹溪认为“哮喘专主于痰”。"},{"t":"p","x":"哮病发作时的基本病理变化为“伏痰”遇感引触，痰随气升，气因痰阻，相互搏结，壅塞气道，肺管狭窄，通畅不利，肺气宣降失常，而致痰鸣如吼，气息喘促。"},{"t":"p","x":"若长期反复发作，寒痰伤及脾肾之阳，痰热耗灼肺肾之阴，可从实转虚，表现肺、脾、肾等脏气虚弱之候。"},{"t":"p","x":"由于三脏之间的交互影响，可致合并同病，表现肺脾气虚或肺肾两虚之象。"},{"t":"p","x":"若哮病大发作，或发作呈持续状态，邪实与正虚错综并见，肺肾两虚而痰浊又复壅盛，严重者因肺不能治理调节心血的运行，命门之火不能上济于心，则心阳亦同时受累，甚至发生由哮致脱危候。"}],"zhenduan":[{"t":"ol","items":["1. 哮病以发作时喉中哮鸣有声为最基本的临床特征。伴呼吸困难，甚则张口抬肩，不能平卧，或口唇指甲发绀，数分钟、数小时后缓解。","2. 呈反复发作性。常因气候突变、饮食不当、情志失调、劳累等因素而诱发，发作前多有鼻痒、喷嚏、咳嗽、胸闷等症状。","3. 平时可一如常人，或稍感疲劳、纳差。但病程日久，反复发作，导致正气亏虚，常有轻度哮鸣，甚至在大发作时持续难平，出现喘脱。","4. 多与先天禀赋有关，家族中可有哮病史。"]}],"jianbie":[{"t":"b","x":"1. 咳嗽"},{"t":"p","x":"哮病与咳嗽都有咳嗽的表现。"},{"t":"p","x":"咳嗽主要表现为咳嗽、咳痰。"},{"t":"p","x":"哮病主要表现为痰气交阻，气道壅塞，呼吸不利，喉间痰鸣气吼，反复发作，常有过敏史或家族史。"},{"t":"b","x":"2. 其他"},{"t":"p","x":"哮证还应与喘证、支饮进行鉴别，详见喘证、痰饮章。"}],"bianzheng":[{"t":"b","x":"1. 辨发作期与缓解期"},{"t":"p","x":"见表 6-1。"},{"t":"table","caption":"表 6-1 哮证发作期与缓解期辨别","head":["","发作期","缓解期"],"rows":[["声息","哮喘气粗声高","哮喘气怯声低"],["呼吸","呼吸深长，呼出为快","呼吸短促难续，吸气不利"],["脉象","有力","沉细或细数"]]},{"t":"b","x":"2. 辨寒热"},{"t":"p","x":"见表 6-2。"},{"t":"table","caption":"表 6-2 寒哮与热哮辨别","head":["","寒哮","热哮"],"rows":[["症状","气促哮鸣，痰稀色白，面色晦暗，口不渴或渴喜热饮，形寒畏冷","气粗息涌，痰稠色黄，面赤口苦，渴喜冷饮，不恶寒"],["舌脉","舌苔薄白或白滑，脉弦紧或浮紧","舌红苔黄，脉滑数或弦滑"]]}],"zhize":"宗朱丹溪“未发以扶正气为主，既发以攻邪气为急”之说，哮病以“发时治标，平时治本”为基本原则。发作期以攻邪治标，祛痰利气为主。寒痰宜温化宣肺，热痰当清化肃肺，寒热错杂者，当温清并施，表证明显者兼以解表，风痰为主者又当祛风涤痰。反复日久，正虚邪实者，又当兼顾，不可单纯拘泥于祛邪。若发生喘脱危候，当急予扶正救脱。缓解期应扶正治本，阳气虚者应予温补，阴虚者则予滋养，分别采取补肺、健脾、益肾等法，通过补益肺脾肾，以冀预防和减少复发。","syndrome":[{"id":"s016","name":"寒痰阻肺证","label":"1. 寒痰阻肺证","group":"发作期","clinic":"呼吸急促，喉中哮鸣有声，胸膈满闷如塞，咳不甚，痰稀薄色白，咳吐不爽，面色晦滞带青，口不渴或渴喜热饮，天冷或受寒易发，形寒畏冷。初起多兼恶寒、发热、头痛等表证。舌苔白滑，脉弦紧或浮紧。","analysis":"寒痰伏肺，遇感触发，痰升气阻，壅塞气道，肺失宣降，故呼吸急促，喉中哮鸣有声；肺气闭郁，不得宣畅，故胸膈满闷如塞，咳不甚，咳吐不爽；痰从寒化饮，故痰稀薄色白；阴盛于内，阳气不得宣达，故面色晦滞带青，形寒畏冷；病因于寒，内无郁热，故口不渴或渴喜热饮；外寒引动伏饮，故天冷或受寒易发；舌苔白滑，脉弦紧或浮紧，为寒痰内阻之象。","treat":"宣肺散寒，化痰平喘。","formulaRaw":"射干麻黄汤（《金匮要略》）或小青龙汤（《伤寒论》）加减。前方长于降气祛痰，后方解表散寒力强。","formulaName":"射干麻黄汤或小青龙汤加减","fangjie":"麻黄、射干宣肺平喘，化痰利咽；干姜、细辛、半夏温肺化饮降逆；紫菀、款冬花化痰止咳；五味子收敛肺气；大枣、甘草和中。若表寒明显，寒热身痛，可加桂枝、生姜等；若痰涌气逆，不得平卧，可加葶苈子、苏子、杏仁、白前、橘皮等；若咳逆上气，汗多，可加白芍。中成药可服用冷哮丸。"},{"id":"s017","name":"痰热壅肺证","label":"2. 痰热壅肺证","group":"发作期","clinic":"气粗息涌，咳呛阵作，喉中哮鸣，胸高胁胀，烦闷不安，汗出，口渴喜饮，面赤口苦，咳痰色黄或色白，黏浊稠厚，咳吐不利，不恶寒，舌质红，苔黄腻，脉滑数或弦滑。","analysis":"痰热壅肺，肺失清肃，肺气上逆，阻塞气道，故喘而气粗息涌，喉中痰鸣如吼，胸高胁胀，咳呛阵作；热蒸液聚生痰，痰热胶结于肺，故咳痰黏浊稠厚，咳吐不利，或黄或白；痰火郁蒸，故烦闷不安，汗出，面赤，口苦；病因于热，肺无伏寒，故口渴喜饮，不恶寒；舌质红，苔黄腻，脉滑数或弦滑，为痰热内壅之象。","treat":"清热宣肺，化痰定喘。","formulaRaw":"定喘汤（《摄生众妙方》）加减。","formulaName":"定喘汤加减","fangjie":"麻黄宣肺平喘；黄芩、桑白皮清热肃肺；杏仁、半夏、款冬花、苏子化痰降逆；白果敛肺，并防麻黄过于耗散；甘草调和诸药。若表寒外束，肺热内郁，可加石膏、麻黄；若肺气壅实，痰鸣息涌，不得平卧，可加葶苈子、地龙；若肺热壅盛，咳痰稠黄，可加海蛤壳、射干、知母、鱼腥草等；若大便秘结，可加大黄、芒硝、全瓜蒌、枳实等；若病久热盛伤阴，气急难续，痰少质黏，口咽干燥，舌红少苔，脉细数，可加沙参、知母、天花粉。"},{"id":"s018","name":"寒包热哮证","label":"3. 寒包热哮证","group":"发作期","clinic":"喉中鸣息有声，胸膈烦闷，呼吸急促，喘咳气逆，咳痰不爽，痰黏色黄，或黄白相兼，烦躁，发热，恶寒，无汗，身痛，口干欲饮，大便偏干，舌苔白腻罩黄，舌尖边红，脉弦紧。","analysis":"痰热壅肺，复感风寒，客寒包火，肺失宣降，故喉中鸣息有声，呼吸急促，喘咳气逆；里热较盛，故烦躁，口干欲饮，便干；热郁蒸痰，气机不畅，故胸膈烦闷，咳痰不爽，痰黏色黄，或黄白相兼；舌苔白腻罩黄，舌尖边红，脉弦紧，为客寒包火之象。","treat":"解表散寒，清化痰热。","formulaRaw":"小青龙加石膏汤（《金匮要略》）或厚朴麻黄汤（《金匮要略》）加减。前方用于外感风寒，饮邪内郁化热，以表寒为主，喘咳烦躁者；后方用于饮邪迫肺，夹有郁热，咳逆喘满，烦躁，表寒不显者。","formulaName":"小青龙加石膏汤或厚朴麻黄汤加减","fangjie":"麻黄散寒解表，宣肺平喘，石膏清泄肺热，二药相合，辛凉配伍，外散风寒，内清里热；厚朴、杏仁平喘止咳；生姜、半夏化痰降逆；甘草、大枣调和诸药。若表寒重者，可加桂枝、细辛；若哮喘痰鸣气逆者，可加射干、葶苈子、苏子祛痰降气平喘；若痰吐稠黄胶黏者，可加黄芩、前胡、瓜蒌皮等。"},{"id":"s019","name":"风痰阻肺证","label":"4. 风痰阻肺证","group":"发作期","clinic":"喉中痰涎壅盛，声如拽锯，或鸣声如吹哨笛，喘急胸满，但坐不得卧，咳痰黏腻难出，或为白色泡沫痰液，无明显寒热倾向，面色青暗，起病多急，常倏忽来去，发前自觉鼻、咽、眼、耳发痒，喷嚏，鼻塞，流涕，胸部憋塞，随之迅即发作，舌苔厚浊，脉滑实。","analysis":"风痰阻肺，冲击声门，故喉中痰涎壅盛，声如拽锯，或鸣声如吹哨笛；风痰壅盛，故咳痰黏腻难出，或为白色泡沫痰液；肺气郁闭，升降失司，故喘急胸满，或胸部憋塞，但坐不得卧；舌苔厚浊，脉滑实，为风痰阻肺之象。","treat":"祛风涤痰，降气平喘。","formulaRaw":"三子养亲汤（《韩氏医通》）加减。","formulaName":"三子养亲汤加减","fangjie":"白芥子温肺利气涤痰；苏子降气化痰，止咳平喘；莱菔子行气祛痰；麻黄宣肺平喘；僵蚕祛风化痰；杏仁、厚朴、半夏、陈皮降气化痰；茯苓健脾化痰。若痰壅喘急，不能平卧，可加葶苈子、猪牙皂，必要时可暂予控涎丹泻肺祛痰；若感受风邪而发作者，可加苏叶、防风、苍耳草、蝉衣、地龙等。"},{"id":"s020","name":"肺肾两虚证","label":"5. 肺肾两虚证","group":"发作期","clinic":"喉中哮鸣如鼾，声低，气短息促，动则喘甚，发作频繁，甚则持续哮喘，口唇爪甲青紫，咳痰无力，痰涎清稀或质黏起沫，面色苍白或颧红唇紫，口不渴或咽干口渴，形寒肢冷或烦热，舌质淡或偏红，或紫暗，脉沉细或细数。","analysis":"哮病久发，肺肾两虚，摄纳失常，故喉中哮鸣如鼾，声低，气短息促，动则喘甚；肺不主气，肾不纳气，故发作频繁，甚则持续哮喘；肺失治节，瘀血内阻，故口唇爪甲青紫；气虚肺不布津，津凝为痰，故咳痰无力，痰涎清稀或质黏起沫；阳虚失温，故面色苍白，形寒肢冷，口不渴；阴虚内热，故颧红唇紫，咽干口渴，烦热；舌质淡或偏红，或紫暗，脉沉细或细数，为肺肾两虚之象。","treat":"补肺纳肾，降气化痰。","formulaRaw":"平喘固本汤（《南京中医学院验方》）加减。","formulaName":"平喘固本汤加减","fangjie":"党参、黄芪补益肺气；胡桃肉、沉香、脐带、冬虫夏草、五味子补肾纳气；苏子、半夏、款冬花、橘皮降气化痰。若肾阳虚，可加附子（制）、鹿角片、补骨脂、钟乳石等；若肺肾阴虚，可加沙参、麦冬、生地黄、当归等；若痰气瘀阻，口唇青紫，可加桃仁、苏木等；若气逆于上，动则气喘，可加紫石英、磁石等。"},{"id":"s021","name":"哮喘脱证","label":"6. 哮喘脱证","group":"发作期","clinic":"哮病反复久发，喘息鼻扇，张口抬肩，气短息促，烦躁，神志昏蒙，面青，四肢厥冷，汗出如油，舌质青暗，苔腻或滑，脉细数不清，或浮大无根。","analysis":"痰浊壅盛，上蒙清窍，故神志昏蒙；肺肾两亏，故喘息鼻扇，张口抬肩；气阴耗伤，故气短息促，汗出如油；心肾阳衰，故面青，四肢厥冷；舌质青暗，苔腻或滑，脉细数不清，或浮大无根，为喘脱之象。","treat":"补肺纳肾，扶正固脱。","formulaRaw":"回阳救急汤（《伤寒六书》）合生脉饮（《医学启源》）加减。前方长于回阳救逆，后方重在益气养阴。","formulaName":"回阳救急汤合生脉饮加减","fangjie":"人参、附子（制）、甘草益气回阳；山萸肉、五味子、麦冬固阴救脱；龙骨、牡蛎敛汗固脱；冬虫夏草、蛤蚧纳气归肾。若喘急面青，烦躁不安，汗出肢冷，舌淡紫，脉细，另送服黑锡丹镇纳虚阳，温肾平喘固脱；若阳虚甚，气息微弱，汗出肢冷，舌淡，脉沉细，可加肉桂、干姜；若气息急促，心烦内热，汗出粘手，口干舌红，脉沉细数，可加生地黄、玉竹，人参改用西洋参。"},{"id":"s022","name":"肺气虚证","label":"1. 肺气虚证","group":"缓解期","clinic":"喘促气短，语声低微，面色㿠白，自汗畏风，咳痰清稀色白，多因气候变化而诱发，发前喷嚏频作，鼻塞流清涕，舌淡苔白，脉细弱或虚大。","analysis":"卫气虚弱，卫阳不能充实腠理，故外邪易侵，多因气候变化而诱发；外邪犯肺，肺卫不宣，故发前喷嚏频作，鼻塞流清涕；肺虚不能主气，气不布津，痰饮内蕴，故喘促气短，语声低微，面色㿠白，咳痰清稀色白；肌表不固，故自汗畏风；舌淡苔白，脉细弱或虚大，为肺气虚之象。","treat":"补肺益气。","formulaRaw":"玉屏风散（《世医得效方》）加减。","formulaName":"玉屏风散加减","fangjie":"黄芪益气固表；白术健脾益肺，固表充卫；防风走表而散风邪，合黄芪、白术以益气祛邪。若恶风明显，可加用桂枝汤；若阳虚甚者，可加附子（制）；若痰多，可加前胡、杏仁；若气阴两虚，呛咳，痰少质黏，口咽干，舌质红，可用生脉散加沙参、玉竹、黄芪。"},{"id":"s023","name":"脾气虚证","label":"2. 脾气虚证","group":"缓解期","clinic":"倦怠无力，食少便溏，面色萎黄无华，痰多而黏，咳吐不爽，胸脘满闷，恶心纳呆，或食油腻易腹泻，每因饮食不当而诱发，舌质淡，苔白滑或腻，脉细弱。","analysis":"脾失健运，气血生化不足，故倦怠无力，面色萎黄无华；水饮运化失常，故食少便溏，胸脘满闷，恶心纳呆，或食油腻易腹泻；痰饮蕴肺，肺气上逆，故痰多而黏，咳吐不爽；舌质淡，苔薄滑或腻，脉细弱，为脾气虚有痰湿之象。","treat":"健脾益气。","formulaRaw":"六君子汤（《医学正传》）加减。","formulaName":"六君子汤加减","fangjie":"党参、白术健脾益气；山药、薏苡仁、茯苓甘淡补脾；半夏、橘皮燥湿化痰；五味子敛肺气；甘草补气调中。若表虚自汗，可加炙黄芪、浮小麦、大枣；若怕冷，畏风，易感冒，可加桂枝、白芍、附子（制）；若痰多，可加前胡、杏仁；若脾阳不振，形寒肢冷，可加附子（制）、干姜；若中虚哮喘，痰壅气滞者，可加三子养亲汤；若脾虚气陷，少气懒言，可改用补中益气汤加减治疗。"},{"id":"s024","name":"肾虚证","label":"3. 肾虚证","group":"缓解期","clinic":"平素息促气短，动则为甚，呼多吸少，咳痰质黏起沫，脑转耳鸣，腰酸腿软，心慌，不耐劳累，或五心烦热，颧红，口干，或畏寒肢冷，面色苍白，舌淡苔白质胖，或舌红少苔，脉沉细或细数。","analysis":"久病肾虚，摄纳失常，气不归原，故平素息促气短，动则为甚，呼多吸少；肾虚水泛，或虚火灼津为痰，故咳痰质黏起沫；肾虚水泛为痰，水饮凌心，故心慌；肾虚精气亏乏，失于充养，故脑转耳鸣，腰酸腿软，不耐劳累；肾阴不足，虚火内生，故五心烦热，颧红，口干；肾阳亏虚，失于温养，故畏寒肢冷，面色苍白；舌淡苔白质胖，或舌红少苔，脉沉细或细数，为肾虚之象。","treat":"补肾纳气。","formulaRaw":"金匮肾气丸（《金匮要略》）合七味都气丸（《张氏医通》）加减。前方偏于温肾助阳，后方偏于益肾纳气。","formulaName":"金匮肾气丸合七味都气丸加减","fangjie":"附子（制）、肉桂补火助阳，温肾纳气；熟地黄、山茱萸、山药滋补肾阴；泽泻、茯苓利水渗湿，防地黄之滋腻；丹皮调血分之滞；五味子敛肺补肾纳气。若阳虚甚，可加附子（制）、肉桂、补骨脂、淫羊藿、鹿角片；若阴虚甚，可加生地黄、冬虫夏草；若肾失潜纳，气不归原，可加蛤蚧、胡桃肉、沉香。"}],"linchuang":["注意寒热虚实之间的兼夹与转化。寒痰冷哮久郁可化热，尤其在感受外邪引发时，更易如此。小儿、青少年阳气偏盛者，多见热哮，但久延而至成年、老年，阳气渐衰，每可转从寒化，表现为寒哮。虚实之间也可在一定条件下互相转化，一般而言，新病多实，发时邪实，久病多虚，平时正虚，但实证与虚证可以因果错杂为患。实证包括寒热两证在内，如寒痰日久耗伤肺脾肾阳气，可以转化为气虚、阳虚证；痰热久郁耗伤肺肾阴液，则可转化为阴虚证。虚证属于阳气虚者，因肺脾肾不能温化津液，而致津液停积为痰，兼有寒痰标实之象；属于阴虚者，因肺肾阴虚火炎，灼津成痰，兼有痰热标实之象。兼腑实者，又当泻肺通腑，以恢复肺之肃降功能。因肝气侮肺，肺气上逆而致者，治当疏利肝气，清肝肃肺。","发时治标顾本，平时治本顾标。临证所见，哮病发作之时，虽以邪实为多，亦有以正虚为主者，缓解期常以正虚为主，但其痰饮留伏的病理因素仍然存在，因此对于哮病的治疗发时未必全从标治，当治标顾本，平时亦未必全恃扶正，当治本顾标。尤其是大发作有喘脱倾向者，更应重视回阳救脱，急固其本，若拘泥于“发时治标”之说，则错失救治良机。平时当重视治本，区别肺、脾、肾的主次，在抓住重点的基础上，适当兼顾，其中尤以补肾为要，因肾为先天之本、五脏之根，肾精充足则根本得固。但在扶正的同时，还当注意参入降气化痰之品，以祛除内伏之顽痰，方能减少复发。","重视虫类祛风通络药的应用。风邪致病者，为痰伏于肺，外感风邪触发，具有起病多急、病情多变等风邪“善行而数变”的特性，治当祛风解痉，药用麻黄、苏叶、防风、苍耳草等，特别是虫类祛风药擅长走窜入络，搜剔逐邪，可祛肺经伏邪，增强平喘降逆之功，且大多具有抗过敏、调节免疫功能作用，对缓解支气管痉挛、改善缺氧现象有显著疗效，药如僵蚕、蝉衣、地龙、露蜂房等。"],"yufang":["预防哮病发生，宜注意保暖，防止感冒，避免因寒冷空气的刺激而诱发。根据身体情况，进行适当的体育锻炼，以逐步增强体质，提高抗病能力。","哮病患者平素饮食宜清淡，忌肥甘油腻、辛辣甘甜，避免海腥发物，防止生痰生火生风。避免烟尘异味。保持心情舒畅，避免不良情绪的影响。劳逸适当，防止过度疲劳。平时可在医师指导下常服玉屏风散、金匮肾气丸等扶正固本药物，以调护正气，提高抗病能力。"],"attachIds":[]},{"id":"d004","name":"喘证","kind":"main","parent":null,"chapterNo":"第七章","chapterName":"喘证","yinbing":[{"t":"b","x":"1. 外邪侵袭"},{"t":"p","x":"外邪以风寒为常见，风寒袭表犯肺，肺卫为邪所伤，肺气不得宣畅，或因风热犯肺，肺为热壅，清肃失司，以致肺气上逆为喘。"},{"t":"p","x":"明·张介宾《景岳全书·喘促》曰：“实喘之证，以邪实在肺也，非风寒则火邪耳。”"},{"t":"b","x":"2. 饮食不当"},{"t":"p","x":"过食生冷肥甘，或嗜酒伤中，损伤脾胃，以致脾湿不运，痰浊内生，上干于肺，肺气壅阻，升降不利，发为喘促。"},{"t":"b","x":"3. 情志所伤"},{"t":"p","x":"情志不遂，忧思气结，气机不利，或郁怒伤肝，肝气上逆于肺，肺气不得肃降，则气逆而喘。"},{"t":"b","x":"4. 劳欲久病"},{"t":"p","x":"久咳伤肺，或病久肺虚，气失所主，气阴亏耗，因而短气喘促。"},{"t":"p","x":"故明·王肯堂《证治准绳·喘》曰：“肺虚则少气而喘。”"},{"t":"p","x":"若劳欲伤肾，精气内夺，真元损耗，根本不固，则气失摄纳，上出于肺，出多入少，气逆喘促。"}],"bingji":[{"t":"p","x":"喘证的基本病机是肺气上逆，宣降失职，或气无所主，肾失摄纳而成本病。"},{"t":"p","x":"病变部位主要在肺和肾，与肝、脾、心有关。"},{"t":"p","x":"病理性质有虚实之分。"},{"t":"p","x":"有邪者为实，因邪壅于肺，宣降失司所致；无邪者属虚，因肺不主气，肾失摄纳引起。"},{"t":"p","x":"本病的病变过程中常发生病机转化，实喘因外邪所致者，若失于表散，则可由表及里；因痰浊、肝郁所致者，则可化热化火；虚喘因肺虚所致者，反复发作，可累及脾肾二脏；因肾虚所致者，复感外邪，可转化为上盛下虚之证。"},{"t":"p","x":"若长期迁延，反复发作，可造成肺、脾、肾虚损严重，最后可累及心阳，导致心气、心阳衰惫，血行瘀滞，甚至出现面青唇绀、指甲青紫、大汗淋漓之喘脱危候。"}],"zhenduan":[{"t":"p","x":"喘证以喘促短气、呼吸困难甚至张口抬肩、鼻翼扇动、不能平卧、口唇发绀为特征，同时多有慢性咳嗽、哮病、肺痨、心悸等病史。每遇外感、情志刺激及劳累而诱发。"}],"jianbie":[{"t":"b","x":"1. 咳嗽"},{"t":"p","x":"咳嗽以喉间有声、咳痰或无痰为主，多由外邪或内伤导致肺失宣降；喘证则表现为呼吸急促，张口抬肩，甚则摇身撷肚，不能平卧，常因痰阻气道或肺肾气虚引发。"},{"t":"p","x":"两者可以单独出现或同时出现。"},{"t":"b","x":"2. 气短"},{"t":"p","x":"气短与喘证同为呼吸异常。"},{"t":"p","x":"喘证呼吸困难，张口抬肩，摇身撷肚，实证气粗声高，虚证气弱声低；短气亦即少气，主要表现呼吸浅促，或短气不足以息，似喘而无声，亦不抬肩撷肚。"},{"t":"p","x":"可见，气短不若喘证呼吸困难之甚，但气短进一步加重，亦可呈虚喘表现。"},{"t":"b","x":"3. 哮病"},{"t":"p","x":"喘证和哮病都有呼吸急促、困难的表现。"},{"t":"p","x":"喘指气息而言，为呼吸气促困难，甚则张口抬肩，摇身撷肚，是多种肺系疾病的一个症状；哮指声响而言，必见喉中哮鸣有声，常伴呼吸困难，是一种反复发作的独立性疾病。"},{"t":"p","x":"喘未必兼哮，而哮必兼喘。"}],"bianzheng":[{"t":"b","x":"1. 辨虚实"},{"t":"p","x":"实喘者呼吸深长有余，呼出为快，气粗声高，伴有痰鸣咳嗽，脉数有力，常见于新病，病势多急；虚喘者呼吸短促难续，深吸为快，气怯声低，少有痰鸣咳嗽，脉象微弱或浮大中空，多见于久病，病势徐缓，时轻时重，遇劳则甚。"},{"t":"b","x":"2. 实喘辨外感内伤"},{"t":"p","x":"外感起病急，病程短，多有表证；内伤病程久，反复发作，无表证。"},{"t":"b","x":"3. 虚喘辨病位"},{"t":"p","x":"肺虚者劳作后气短不足以息，喘息较轻，常伴有面色㿠白，自汗，易感冒；肾虚者静息时亦有气喘，动则更甚，伴有面色苍白，颧红，怕冷，腰酸膝软；心衰者喘息持续不已，难以平卧，伴有心悸，紫绀，浮肿，脉结代。"}],"zhize":"喘证的治疗应分清虚实邪正。实喘治肺，以祛邪利气为主，区别寒、热、痰、气的不同，分别采用温化宣肺、清化肃肺、化痰理气的方法；虚喘以培补摄纳为主，或补肺，或健脾，或补肾，阳虚则温补之，阴虚则滋养之。至于虚实夹杂、寒热互见者，又当根据具体情况分清主次，权衡标本，辨证选方用药。\n此外，由于喘证多继发于各种急慢性疾病，所以还应当注意积极地治疗原发病，不能见喘治喘。","syndrome":[{"id":"s025","name":"风寒犯肺证","label":"1. 风寒犯肺证","group":"实喘","clinic":"喘息咳逆，呼吸急促，胸部胀闷，痰多色白清稀，恶寒发热，无汗，头痛鼻塞，口不渴，舌苔薄白而滑，脉浮紧。","analysis":"风寒袭表，外伤皮毛，内壅肺气，肺气失宣，故咳喘气促，胸部胀闷；寒邪伤肺，气不布津，凝津成痰，故咳痰清稀色白；风寒袭表，卫表不和，故见恶寒发热等风寒表证；舌苔薄白而滑为寒湿之征，脉浮紧为表寒之象。","treat":"疏风散寒，宣肺平喘。","formulaRaw":"麻黄汤（《伤寒论》）合华盖散（《太平惠民和剂局方》）加减。前方宣肺平喘，解表散寒；后方宣肺化痰，降气化痰。","formulaName":"麻黄汤合华盖散加减","fangjie":"麻黄、桂枝宣肺平喘，散寒解表；杏仁降气平喘；苏子、桑白皮降气化痰；陈皮、茯苓健脾化痰；甘草调和诸药。若寒痰较重者，可加细辛、生姜；若咳喘重，胸满气逆者，可加射干、前胡、厚朴；若表证不重，可用三拗汤。"},{"id":"s026","name":"表寒肺热证","label":"2. 表寒肺热证","group":"实喘","clinic":"喘逆上气，胸胀或痛，息粗鼻扇，咳而不爽，痰液稠黏，伴恶寒发热，烦闷，身痛，有汗或无汗，口渴，舌边红，苔薄白或黄，脉浮数或滑。","analysis":"邪热郁肺，肺失宣降，故喘逆上气，息粗鼻扇，汗出；痰热郁肺，肺气不利，故烦闷，痰液稠黏，咳而不爽；热伤肺络，故胸胀或痛；风寒束表，经输不利，故见恶寒发热，身痛，无汗；舌边红，苔薄白或黄，脉浮数或滑，为表寒肺热之象。","treat":"解表清里，化痰平喘。","formulaRaw":"麻杏石甘汤（《伤寒论》）加减。","formulaName":"麻杏石甘汤加减","fangjie":"麻黄宣肺解表；石膏清泄肺热；杏仁降气化痰；甘草调和诸药。若表寒重，可加桂枝；若痰热重，痰黄黏稠量多，可加瓜蒌、贝母；若痰鸣息涌，可加葶苈子、射干。"},{"id":"s027","name":"痰热郁肺证","label":"3. 痰热郁肺证","group":"实喘","clinic":"喘咳气涌，胸闷胀痛，痰多质黏色黄，或夹有血色，伴胸中烦闷，身热，有汗，面赤咽干，渴喜冷饮，小便赤涩，大便秘结，舌质红，苔黄腻，脉滑数。","analysis":"邪热壅肺，炼津成痰，阻遏肺气，故喘咳气涌，胸闷胀痛，痰黄黏稠不易咳出；热伤肺络，则痰中夹血；痰热郁肺，故胸中烦闷，身热，汗出，面赤；痰热伤津，故见咽干，渴喜冷饮，小便赤涩，大便秘结；舌红，苔黄腻，脉滑数，为痰热之象。","treat":"清热化痰，宣肺平喘。","formulaRaw":"桑白皮汤（《景岳全书》）加减。","formulaName":"桑白皮汤加减","fangjie":"桑白皮、黄芩、黄连、栀子清泻肺热；贝母、杏仁、苏子、半夏降气化痰。若痰多黏稠，可加瓜蒌、海蛤粉、冬瓜仁、薏苡仁、鱼腥草；若身热甚，可加石膏、知母、金银花；若痰有血色或有腥味，可加鱼腥草、金荞麦、芦根、蒲公英。"},{"id":"s028","name":"痰浊阻肺证","label":"4. 痰浊阻肺证","group":"实喘","clinic":"喘咳痰鸣，胸中满闷，甚则胸盈仰息，痰多黏腻色白，咳吐不利，兼有呕恶，食少，口黏不渴，舌质淡，舌苔白腻，脉滑或濡。","analysis":"饮食伤脾，脾失健运，聚湿生痰，上壅于肺，肺气上逆，则喘咳痰多，咳吐不利；痰阻于肺，气机不畅，故喘而胸中满闷，甚则胸盈仰息；痰浊中阻，胃失和降，则呕恶食少；苔腻、脉滑均为痰湿之象。","treat":"祛痰降逆，宣肺平喘。","formulaRaw":"二陈汤（《太平惠民和剂局方》）合三子养亲汤（《韩氏医通》）加减。两方同治痰湿，前方重点在胃，痰多脘痞者较宜；后方重点在肺，痰涌气急者较宜。","formulaName":"二陈汤合三子养亲汤加减","fangjie":"半夏、陈皮化痰降气；茯苓健脾利湿；苏子降气化痰，止咳定喘；白芥子利气豁痰；莱菔子消食化痰；甘草和中。若痰从寒化，色白清稀，畏寒，可加干姜、细辛；若痰从热化，痰转黄稠，咽干，便秘，可加黄芩、桑白皮、竹茹，或按痰热郁肺论治。"},{"id":"s029","name":"肺气郁痹证","label":"5. 肺气郁痹证","group":"实喘","clinic":"每遇情志刺激而诱发，发时突然呼吸短促，息粗气憋，胸胁胀闷，咽中如窒，但喉中痰鸣不著，或无痰声，喘定后如常人。平素常多忧思抑郁，或失眠，心悸，或心烦易怒，面红目赤。舌质红，苔薄白或薄黄，脉弦。","analysis":"情志过极伤肝，肝郁气逆犯肺，肺失肃降，故因情志刺激而突发呼吸短促，息粗气憋；病位在肝，气郁为主，无痰湿之患，故胸胁胀闷，咽中如窒，咳嗽痰鸣不著，喘定后如常人；气机不畅则失眠，心悸；肝郁化火则急躁易怒，面红目赤；舌质红，苔薄白或薄黄，脉弦，为肝郁之象。","treat":"开郁降气平喘。","formulaRaw":"五磨饮子（《医方考》）加减。","formulaName":"五磨饮子加减","fangjie":"沉香降气平喘；枳实、木香、乌药疏肝理气；槟榔破气降逆。若肝气郁滞重，可加柴胡、郁金、青皮等；若气滞腹胀、便秘，可加大黄（即六磨汤）；若心悸失眠，可加百合、酸枣仁、合欢花、远志。"},{"id":"s030","name":"水凌心肺证","label":"6. 水凌心肺证","group":"实喘","clinic":"喘咳气逆，倚息难于平卧，咳痰稀白，心悸，全身浮肿，尿少，怯寒肢冷，面色瘀暗，唇甲青紫，舌淡胖或胖暗，或有瘀斑、瘀点，舌下青筋显露，苔白滑，脉沉细或涩。","analysis":"肺肾俱虚，肾不纳气，则喘咳气逆，倚息难于平卧；肺失通调，肾失开阖，则全身浮肿，尿少；肾阳虚无以温煦，故畏寒肢冷；心阳衰惫，鼓动血脉无力，则心悸，面色瘀暗，唇甲青紫；舌淡胖或胖暗，或有瘀斑、瘀点，舌下青筋显露，苔白滑，脉沉细或涩，为水凌心肺之象。","treat":"温阳利水，泻肺平喘。","formulaRaw":"真武汤（《伤寒论》）合葶苈大枣泻肺汤（《金匮要略》）加减。前方温阳利水，后方泻肺平喘。","formulaName":"真武汤合葶苈大枣泻肺汤加减","fangjie":"附子（制）温肾助阳；茯苓利水渗湿；白术健脾燥湿；生姜温阳散寒；白芍去水气，利膀胱；葶苈子泻肺气而利水，祛痰定喘；大枣补脾养心，缓和药性。若唇舌紫暗，瘀血内阻，可加丹参、当归、红花；若阳虚明显，可加肉桂、干姜；若全身浮肿，可合五皮饮。"},{"id":"s031","name":"肺虚证","label":"1. 肺虚证","group":"虚喘","clinic":"喘促短气，气怯声低，喉有鼾声，咳声低弱，痰吐稀薄，自汗畏风，或见咳痰少质黏，烦热而渴，咽喉不利，面颧潮红，舌质淡红，或有苔剥，脉软弱或细数。","analysis":"肺虚不能主气，则喘促短气，气怯声低，咳声低弱；气不化津，津停成痰，则痰吐清稀；肺虚卫外不固，则自汗畏风；舌苔剥，脉软弱，亦为肺气虚之象；肺阴虚津液亏虚，则痰少质黏，咽喉不利；阴虚火旺，则烦热，两颧潮红；舌质淡红，脉细数，亦是肺阴虚之象。","treat":"补肺益气养阴。","formulaRaw":"生脉散（《医学启源》）合补肺汤（《永类铃方》）加减。前方益气养阴，后方补肺益肾。","formulaName":"生脉散合补肺汤加减","fangjie":"人参、黄芪补肺益气；麦冬养阴生津，润肺止咳；五味子敛肺平喘；熟地黄、五味子补肾敛肺纳气；桑白皮、紫菀化痰止咳平喘。若咳逆，咳痰稀薄，可加紫菀、款冬花、苏子、钟乳石；若阴虚，可加沙参、玉竹、百合、诃子；若肾虚，喘促不已，动则尤甚，可加山萸肉、胡桃肉、蛤蚧等；若肺脾两虚，中气下陷，可合补中益气汤。"},{"id":"s032","name":"肾虚证","label":"2. 肾虚证","group":"虚喘","clinic":"喘促日久，动则喘甚，呼多吸少，呼则难升，吸则难降，气不得续，形瘦神惫，跗肿，汗出肢冷，面青唇紫，舌淡苔白或黑而润滑，脉微细或沉弱。或见喘咳，面红烦躁，口咽干燥，足冷，汗出如油，舌红少津，脉细数。","analysis":"久病肺虚及肾，肾虚气失摄纳，故呼多吸少，气不得续，动则气耗而喘甚；肾虚精气耗损，故形瘦神疲；肾阳虚衰，卫外不固，津液外泄，不能温养四肢，故汗出肢冷，面唇青紫；舌淡，脉微细或沉弱，为肾气（阳）虚之征；面红烦躁，口咽干燥，汗出如油，舌红少津，脉细数，为肾气（阴）虚之象。","treat":"补肾纳气。","formulaRaw":"金匮肾气丸（《金匮要略》）合参蛤散（《济生方》）加减。前方长于温阳，后方长于益气。","formulaName":"金匮肾气丸合参蛤散加减","fangjie":"熟地黄、山药、山萸肉滋补肾精；茯苓、泽泻健脾利水渗湿；丹皮清泻肝火；少量桂枝、附子（制）温补肾中之阳；蛤蚧、人参补肺益肾，止咳定喘。若肾阴虚，可用七味都气丸合生脉散加减；若肾阳不足，血脉瘀滞，可加桃仁、红花、川芎、水蛭、僵蚕；若肾虚于下，痰浊壅盛于上，喘咳痰多，气急胸闷，苔腻，可用苏子降气汤。"},{"id":"s033","name":"喘脱证","label":"3. 喘脱证","group":"虚喘","clinic":"喘逆剧甚，张口抬肩，鼻扇气促，不能平卧，稍动则咳喘欲绝，或有痰鸣，心慌动悸，烦躁不安，面青唇紫，汗出如珠，肢冷，舌质淡而无华或干瘦枯萎，少苔或者无苔，脉浮大无根，或脉微欲绝。","analysis":"肺肾衰竭，气失所主，则喘逆剧甚，张口抬肩，鼻翼扇动，不能平卧；心阳欲脱，虚阳躁动，则心悸，烦躁不安；阳脱血脉失于温运，则肢冷，面唇青紫；阳脱阴液外泄，则汗出如珠；舌质淡而无华或干瘦枯萎，少苔或无苔，脉浮大无根、脉微欲绝，皆为阳脱阴竭之象。","treat":"扶阳固脱，镇摄肾气。","formulaRaw":"参附汤（《济生方》）送服黑锡丹（《太平惠民和剂局方》）配合蛤蚧粉加减。前方扶阳固脱，后方镇摄肾气。","formulaName":"参附汤送服黑锡丹配合蛤蚧粉加减","fangjie":"人参、附子（制）扶助阳气，回阳固脱；黑锡丹镇摄肾气；蛤蚧温肾阳，散阴寒，降气逆，定虚喘。若阳虚甚，可加干姜；若阴虚甚，可加麦冬、玉竹，人参改用西洋参；若神昧不清，可加丹参、远志、菖蒲；若浮肿，可加茯苓、炙蟾皮、万年青根。"}],"linchuang":["注意寒热的转化与兼夹。喘证的证候之间，存在着一定的联系，临床辨证除分清实喘、虚喘之外，还应注意寒热的转化。如实喘中的风寒壅肺证，若风寒失于表散，入里化热，可出现表寒肺热；痰浊阻肺证，若痰郁化热，或痰阻气壅，血行瘀滞，又可呈现痰热郁肺，或痰瘀阻肺证。","掌握虚实的错杂。本病在反复发作过程中，每见邪气尚实而正气已虚，表现为肺实肾虚的下虚上实证。因痰浊壅肺，见咳嗽痰多，气急，胸闷，苔腻；肾虚于下，见腰酸，下肢欠温，脉沉细或兼滑。治疗宜化痰降逆，温肾纳气，以苏子降气汤为代表方，并根据上盛下虚的主次分别处理，上盛为主加用杏仁、白芥子、莱菔子，下虚为主加用补骨脂、胡桃肉、紫石英。","虚喘尤重治肾，扶正当辨阴阳。虚喘有补肺、补肾及健脾、养心等不同治法，且每多相关，应结合应用，但肾为气之根，必须重视治肾，纳气归原，使根本得固。扶正除辨别脏器所属外，须进一步辨清阴阳。阳虚者温养阳气，阴虚者滋阴填精，阴阳两虚者根据主次酌情兼顾，一般而论，以温阳益气为主。"],"yufang":["喘证的预防，重点在于慎风寒，适寒温，节饮食，少食生冷肥甘厚腻和辛热刺激之品，以免助湿生痰动火。","已患喘证，则应注意早期治疗，力求根治，尤需防寒保暖，不宜过度疲劳，防止受邪而诱发，忌烟酒，适房事，调情志，饮食清淡而富有营养。适当进行体育锻炼，增强体质，提高机体的抗病能力。"],"attachIds":[]},{"id":"d005","name":"肺胀","kind":"main","parent":null,"chapterNo":"第八章","chapterName":"肺胀","yinbing":[{"t":"p","x":"肺胀的发生多因久病肺虚，痰浊、水饮、血瘀互阻，肺气壅滞，气不敛降，还于肺间，胸膺胀满而成，逐渐损及脾、肾与心，每因复感外邪诱使病情发作或加剧。"},{"t":"b","x":"1. 久病肺虚"},{"t":"p","x":"内伤久咳、久哮、久喘、肺痨等慢性肺系疾患迁延失治，导致肺气亏虚，气不布津，痰浊内生，瘀血形成，成为发病的基础。"},{"t":"p","x":"此外，长期吸烟、吸入粉尘，亦是肺体损伤、肺失宣降的重要因素。"},{"t":"b","x":"2. 屡感外邪"},{"t":"p","x":"久病肺虚，痰瘀互结，卫外不固，易致六淫外邪反复侵袭，正虚邪恋，是肺胀日益加重的主要原因。"},{"t":"p","x":"外感之中以感受风寒、风热邪气多见，尤以风寒邪气最为常见，故肺胀冬春寒冷季节最易复发。"},{"t":"p","x":"此外，饮食不节，脾胃运化功能失调；劳欲过度，肾主纳气功能失司；情志失调，肝疏泄功能失调，亦可诱发肺胀发作。"}],"bingji":[{"t":"p","x":"肺胀的基本病机是肺气胀满，不能敛降。"},{"t":"p","x":"久病正虚，反复感邪，痰浊、水饮、血瘀互结于肺，气道壅塞，肺气胀满，不能敛降，发为肺胀。"},{"t":"p","x":"病位首先在肺，继则影响脾肾，后期病及于心。"},{"t":"p","x":"肺为气之主，肾为气之根，肺虚日久，金不生水，肾气衰惫，则气喘日益加重，吸气困难，气短难续，动则益甚。"},{"t":"p","x":"宗气贯于心肺，心阳根于命门真火，故肺肾虚弱，可进一步导致心之阳气虚衰，而呈现喘脱危候。"},{"t":"p","x":"肺胀的病理因素主要为痰浊、水饮与血瘀，且互为影响，兼见同病。"},{"t":"p","x":"病理因素之间相互影响和转化，如痰从寒化则成饮，饮溢肌表则为水；痰浊久留，肺气郁滞，心脉失畅，则血郁为瘀；瘀阻血脉，血不利则为水。"},{"t":"p","x":"但一般早期以痰浊为主，渐而痰瘀并见，终至痰浊、血瘀、水饮错杂为患。"},{"t":"p","x":"肺胀的病理性质虽为本虚标实，但有偏实、偏虚的不同，且多以标实为急。"},{"t":"p","x":"感邪时偏于邪实，平时偏于本虚。"},{"t":"p","x":"本虚早期多属气虚、气阴两虚，晚期气虚及阳虚，或阴阳两虚，但纯阴虚者罕见。"},{"t":"p","x":"正虚感邪，痰浊或痰热蒙蔽心窍，心神失主，则意识蒙胧、嗜睡甚至昏迷。"},{"t":"p","x":"肝火夹痰上扰，气逆痰升，肝风内动，则发生肢颤、抽搐。"},{"t":"p","x":"热迫血行，则动血而致出血。"},{"t":"p","x":"病情进一步发展可出现肢冷、汗出、脉微弱等元阳欲脱现象。"}],"zhenduan":[{"t":"ol","items":["1. 慢性肺系疾病史多年，反复发作。病程缠绵，时轻时重，经久难愈。多见于有吸烟史的中老年人。","2. 典型临床表现为喘息气促、咳嗽、咳痰、胸部膨满、憋闷如塞等。病久可见面色、唇甲青紫，心悸，脘腹胀满，肢体浮肿，甚至喘脱、昏迷等症。","3. 查体可见桶状胸、呼吸音减弱等。"]}],"jianbie":[{"t":"b","x":"1. 哮病"},{"t":"p","x":"哮病与肺胀均可见喘息、呼吸困难等症状，但哮病是一种发作性独立疾病，常突然发病，外邪引动伏痰，致痰阻气道，气道痉挛，以喉中哮鸣有声为主要临床表现，夜间发作多见，其缓解期如常人。"},{"t":"p","x":"而肺胀为多种慢性肺部疾病长期反复发作，迁延不愈发展而来，以喘促、咳嗽、咳痰、胸部膨满、憋闷如塞等为临床特征，二者有明显区别。"},{"t":"p","x":"哮病患者长期反复发作，也可发展为肺胀。"},{"t":"b","x":"2. 喘证"},{"t":"p","x":"喘证与肺胀二者均可出现喘促、呼吸困难、动则加重等症状。"},{"t":"p","x":"喘证多见于哮病、胸痹、水肿等多种急慢性疾病过程中。"},{"t":"p","x":"肺胀由多种慢性肺部疾病长期反复发作，迁延不愈而成，部分肺系疾病造成的喘证日久可发展为肺胀。"}],"bianzheng":[{"t":"b","x":"1. 辨病性"},{"t":"p","x":"总属本虚标实，但有偏实、偏虚的不同，因此应分清标本虚实的主次。一般发作时偏于标实，平时偏于本虚。偏实者须分清外邪、痰饮、瘀血的偏盛。早期以痰浊为主，渐而痰瘀并重，并可兼见气滞、水饮错杂为患。本虚为肺、脾、肾三脏虚损，后期累及心，但有偏重主次之不同。肺胀后期痰瘀壅盛，正气虚衰，本虚与标实并重。"},{"t":"b","x":"2. 辨病位"},{"t":"p","x":"早期以气虚为主，或气阴两虚为主，病位在肺、脾、肾；后期气虚及阳虚，甚至可见阴阳两虚，或阴竭阳脱之证，以肺、肾、心为主。"},{"t":"b","x":"3. 辨分期"},{"t":"p","x":"本病可分为急性发作期、临床缓解期及慢性迁延期。急性发作期以实证为主，表现为短期内咳嗽、咳痰和（或）呼吸困难加重，痰量增多，呈脓性或黏液脓性，可伴发热等急性加重的表现；临床缓解期及慢性迁延期以虚证或虚实夹杂证为主，其咳嗽、咳痰、呼吸困难等症状相对稳定。"}],"zhize":"急则治其标，缓则治其本。急性期以标实为主，治疗重在祛邪，根据外邪、水饮、痰浊、血瘀等病邪性质的不同分别采取宣肺、利水、化痰、祛瘀，甚或开窍、息风等法，或酌情数法兼用；临床缓解期以本虚为主，重在治本，针对脏腑病机不同，采用补肺、健脾、温肾、纳气、养阴等法，正气欲脱时则应扶正固脱，回阳救逆；慢性迁延期，虚实夹杂者，应扶正与祛邪共施。","syndrome":[{"id":"s034","name":"外寒内饮证","label":"1. 外寒内饮证","group":"","clinic":"咳逆喘满不得卧，气息短促，咳痰白稀量多，呈泡沫状，胸部膨满，口干不欲饮，面色青暗，周身酸楚，头痛，恶寒，无汗，舌质暗淡，舌苔白滑，脉浮紧。","analysis":"素有脾肾阳虚，水饮内停，复感风寒，外寒引动内饮，寒饮内停于肺，肺失宣肃，肺气上逆，则咳逆；肺气壅滞，不能敛降，故见胸部膨满，喘满不得卧，气息短促；肺气不宣，津液不布，聚而成痰，故见咳痰，痰稀色白量多；湿从寒化成饮，故见痰呈泡沫样；寒饮阻遏气机，津液不布，则口干不欲饮；阳郁不伸，血行瘀滞，则面色青暗；寒邪束表，故周身酸楚，头痛，恶寒，无汗；舌质暗淡，舌苔白滑，脉浮紧，为外寒内饮之象。","treat":"解表散寒，温肺化饮。","formulaRaw":"小青龙汤（《伤寒论》）加减。","formulaName":"小青龙汤加减","fangjie":"麻黄、桂枝发汗解表，宣肺平喘，温通经脉，共为君药；干姜、细辛温肺化饮，共为臣药，协助麻黄、桂枝解表祛邪；五味子敛肺止咳，与细辛、干姜相伍，散中有收，防止温散太过耗伤肺气；白芍养血敛阴，与桂枝配伍调和营卫，制约麻黄、桂枝之辛散，使散中有收；半夏燥湿化痰，和胃降逆；炙甘草调和诸药，益气和中，合桂枝辛甘化阳以助卫，合芍药酸甘化阴以益营。若咳而上气，喉中有水鸡声，可用射干麻黄汤；若饮郁化热，烦躁而喘，脉浮，可用小青龙加石膏汤；若唇甲青紫，舌质紫暗，可加桃仁、红花、丹参、当归。"},{"id":"s035","name":"痰浊阻肺证","label":"2. 痰浊阻肺证","group":"","clinic":"咳嗽，痰多色白易咳，喘息，呼吸气促，胸闷憋气，稍劳即著，畏风易汗，脘腹痞胀，纳呆食少，恶心欲吐，便溏，倦怠乏力，舌质淡或淡胖，苔薄腻或浊腻，脉细滑。","analysis":"肺脾气虚，痰浊内生，肺气壅塞，肺失宣降，则见咳嗽，痰多色白易咳，喘息，呼吸气促，胸闷憋气；肺气虚弱，气虚不固，故稍劳即著，畏风易汗；肺病及脾，脾气虚弱，脾主运化失职，故见脘腹痞胀，纳呆食少，恶心欲吐，便溏，倦怠乏力；舌质淡或淡胖，苔薄腻或浊腻，脉细滑，为痰浊阻肺之象。","treat":"燥湿化痰，降逆平喘。","formulaRaw":"苏子降气汤（《太平惠民和剂局方》）合三子养亲汤（《韩氏医通》）加减。","formulaName":"苏子降气汤合三子养亲汤加减","fangjie":"紫苏子善降肺气而消痰；半夏燥湿化痰；厚朴理气降气；前胡、白芥子化痰降逆平喘；莱菔子消食导滞，降气祛痰；肉桂温补肾元，纳气平喘；当归养血补虚，治咳逆上气；生姜和胃降逆；大枣、甘草益气和中，调和诸药。若痰涎壅盛，胸胁胀满，喘咳不能平卧，可加葶苈子；若痰壅气喘减轻，仍倦怠乏力，纳差，便溏，可加党参、黄芪、砂仁、木香；若畏风汗出明显，可加玉屏风散。若面唇晦暗，舌质紫暗，舌下脉络迂曲，舌苔浊腻，可用涤痰汤加丹参、地龙、红花、水蛭。"},{"id":"s036","name":"痰热郁肺证","label":"3. 痰热郁肺证","group":"","clinic":"咳逆喘息，胸满气粗，咳痰黄或白，黏稠难咳，身热，烦躁，目睛胀突，溲黄，便干，口渴欲饮，或发热微恶寒，咽痒疼痛，身体酸楚，汗出，舌红，苔黄腻，脉滑数。","analysis":"肺气亏虚，气不布津，加之脾虚生痰，郁而化热，痰热相搏，壅结于内，又复感外邪，外邪与痰热互结，郁遏肺气，清肃失司，故咳逆喘息，胸满气粗，咳痰黄或白，黏稠难咳；痰热扰心，则烦躁；热炽津伤，故身热，目睛胀突，口渴，便干，溲黄；风热侵袭肺卫，故见发热微恶寒，咽痒疼痛，身体酸楚，汗出；舌红，苔黄腻，脉滑数，为痰热内郁之象。","treat":"清肺化痰，降逆平喘。","formulaRaw":"越婢加半夏汤（《金匮要略》）合桑白皮汤（《景岳全书》）加减。","formulaName":"越婢加半夏汤合桑白皮汤加减","fangjie":"麻黄宣肺平喘，发散风邪；杏仁、半夏、苏子化痰降逆；桑白皮泻肺平喘，利水消肿；生石膏、知母、黄芩、黄连、山栀清泄肺热，热退则无以炼津生痰，咳喘自除。若痰热内盛，胸满气逆，痰胶黏不易咳出，可加鱼腥草、金荞麦、瓜蒌皮、海蛤粉；若喉中痰鸣，喘息不得平卧，可加射干、葶苈子；若腑气不通，腹满便秘，可加大黄、芒硝；若口干舌燥，可加天花粉、芦根、麦冬。"},{"id":"s037","name":"痰蒙神窍证","label":"4. 痰蒙神窍证","group":"","clinic":"神志恍惚，表情淡漠，嗜睡，或烦躁不安，谵妄，撮空理线，或昏迷，或肢体瞤动、抽搐，咳逆喘促，咳痰黏稠或黄黏不爽，或伴痰鸣，舌质淡或红，苔白腻或黄腻，脉细滑数。","analysis":"痰涎壅盛，痰浊上蒙心窍，则神志恍惚，表情淡漠，嗜睡；痰热扰神，则烦躁不安；痰热闭窍，则谵妄，撮空理线，昏迷；痰热内耗营阴，肝风内动，则肢体瞤动、抽搐；痰浊或痰热蕴肺，故喘咳，痰黏稠或黄黏，或伴痰鸣；舌质淡或红，苔白腻或黄腻，脉细滑数，乃痰浊内蕴之象。","treat":"涤痰，开窍，息风。","formulaRaw":"涤痰汤（《济生方》）加减。","formulaName":"涤痰汤加减","fangjie":"半夏、橘红、胆南星燥湿化痰，涤痰息风；竹茹、枳实清热化痰利膈；石菖蒲芳香化浊，开窍豁痰；人参、茯苓、甘草、生姜、大枣补脾助运，杜绝生痰之源。痰浊蒙窍者，可加至宝丹；痰热闭窍者，可加安宫牛黄丸；伴肝风内动，肢体抽搐者，可用紫雪丹，同时加用钩藤、全蝎、羚羊角粉；若热结大肠，腑气不通，可酌加大黄、芒硝；若热伤血络，见皮肤黏膜出血、咯血、便鲜血者，可加水牛角、生地黄、牡丹皮、紫珠草，或合用犀角地黄汤；若痰热内盛，喘咳痰黄，可加黄芩、桑白皮、葶苈子、天竺黄、竹沥。"},{"id":"s038","name":"肺肾气虚证","label":"5. 肺肾气虚证","group":"","clinic":"呼吸浅短难续，声低气怯，甚则张口抬肩，倚息不能平卧，动则尤甚，咳嗽，痰白如沫，咳吐不利，胸满闷窒，心慌，形寒汗出，面色晦暗，或腰膝酸软，小便清长，或尿后余沥，或咳则小便自遗，舌淡或暗紫，苔白润，脉沉细虚数无力，或有结、代。","analysis":"肺主气，司呼吸，肾主纳气，肺为气之主，肾为气之根。肺肾气虚，则肺气不降，肾气不纳，清气难入，浊气难出，故见呼吸浅短难续，声低气怯，甚则张口抬肩，倚息不能平卧；动则耗气，故呼吸困难加重；肾虚水泛，痰饮阻肺，故咳嗽，痰白如泡沫，咳吐不利，胸满闷窒；肺病及心，心阳不振，故心慌，形寒，汗出；腰膝酸软，乃肾气虚之征；肾虚不固，膀胱失约，故小便清长，或咳则小便自遗；气虚血瘀，则可见面色晦暗，舌质暗紫；舌淡，苔白润，脉沉细虚数无力，或有结、代，乃肺肾亏虚之象。","treat":"补肺纳肾，降气平喘。","formulaRaw":"补虚汤（《医略六书》）合参蛤散（《普济方》）加减。","formulaName":"补虚汤合参蛤散加减","fangjie":"人参、黄芪、白术、茯苓、甘草补益肺脾；蛤蚧、五味子补肾纳气，镇摄平喘；干姜、半夏温肺化饮；厚朴、陈皮理气化痰。若喘逆甚，可加磁石、沉香、紫石英；若怕冷，舌质淡，可加桂枝、细辛、钟乳石；若阴伤低热，舌红苔少，可加麦冬、玉竹、生地黄、知母；若颈脉动甚，面唇青紫明显，舌紫暗，可加当归、丹参、红花、地龙；若心动悸，脉结、代，可加炙甘草汤；若见面色苍白，冷汗淋漓，四肢厥冷，脉微欲绝，乃喘脱危象，可急用参附汤加沉香、紫石英、五味子。"},{"id":"s039","name":"阳虚水泛证","label":"6. 阳虚水泛证","group":"","clinic":"喘咳不能平卧，咳痰清稀，胸满气憋，面浮肢肿，甚则一身悉肿，尿少，脘痞，纳差，心悸，怕冷，面唇青紫，舌胖质暗，苔白滑，脉沉虚数，或见结、代。","analysis":"肺脾肾阳气衰微，气不化水，水邪泛滥，则面浮肢肿，甚则一身悉肿；水凌心肺，故心悸，胸闷气憋，喘咳，咳痰清稀；脾失健运，则脘痞，纳少；阳虚水寒内盛，膀胱气化不利，故怕冷，尿少。阳虚血脉失于温煦而瘀滞，则面唇青紫；舌胖质暗，脉结、代，提示瘀血阻络；苔白滑，脉沉虚数，或见结、代，乃阳虚水泛之象。","treat":"温肾健脾，化饮利水。","formulaRaw":"真武汤（《伤寒论》）合五苓散（《伤寒论》）加减。","formulaName":"真武汤合五苓散加减","fangjie":"附子（制）、桂枝温肾通阳；白术健脾燥湿；茯苓利水渗湿；猪苓、泽泻利水消肿；生姜温散水气；白芍敛阴和阳。若血瘀甚，发绀明显，可加泽兰、红花、丹参、赤芍、益母草、北五加皮；若水肿势剧，上渍心肺，心悸喘满，倚息不得卧，加沉香、牵牛子、椒目、葶苈子。本证实为标急，急则治其标，待水去饮化后，可参照肺肾气虚证论治。"}],"linchuang":["肺胀的标本虚实辨证尤为重要。本病是由多种慢性肺系疾病反复发作导致的，总的病理性质为本虚标实，因此，临证时当辨标本虚实，辨脏腑阴阳。先分发作期（标实为主）与缓解期（本虚为主），再按痰浊、痰热、水饮、血瘀、气虚、阳虚、阴阳欲脱等细辨。","对于急性发作期患者要注意分辨轻重缓急。肺胀患者若出现喘促、心悸、意识淡漠甚或昏迷等，说明已经发展到呼吸衰竭、肺心病、肺性脑病阶段，治疗时要遵循中西医结合原则。对于意识不清患者，要注意保持患者呼吸道通畅，防止痰液阻塞气道，严密观察血压、脉搏、神志等的变化，警惕内闭外脱等危笃病情的出现。"],"yufang":["肺胀的预防应重视调治原发病，积极治疗外感，尤其是老年、久病体虚的患者，凡近期内咳喘突然加剧，痰色变黄，舌质变红苔变黄，虽无发热恶寒表证，亦要考虑复感外邪病情加重的可能，应及时诊治，阻断病势的发展。","秋冬寒冷季节注意保暖，避免感受外邪。适当参加体育锻炼，如散步、做呼吸操、打太极拳、练气功等，增强体质。调节情志，保持乐观，使气血调和。避免劳欲过度，应顾护真精。平时应常服用扶正固本方药增强正气，以提高机体抗病能力。调节饮食，以清淡而富于营养之食物为主，忌食辛辣香燥、酸咸肥甘、生冷发物及醇酒等。戒烟是预防本病的重要措施之一。"],"attachIds":[]},{"id":"d006","name":"肺痈","kind":"main","parent":null,"chapterNo":"第九章","chapterName":"肺痈","yinbing":[{"t":"p","x":"肺痈的发生主要为外邪犯肺、痰热伤肺或他脏传变等引起。"},{"t":"p","x":"如素有痰热蕴肺，复加外感风热，内外合邪，则更易引发本病。"},{"t":"b","x":"1. 外邪犯肺"},{"t":"p","x":"风热上受，或风寒袭肺，未得及时表散，内蕴不解，在肺经痰热素盛或正气内虚的基础上，郁而化热，肺脏受邪热熏灼，肺气失于清肃，肺络阻滞，以致热壅血瘀，蕴毒化脓而成痈。"},{"t":"p","x":"《金匮要略·肺痿肺痈咳嗽上气病脉证治》云：“风伤皮毛，热伤血脉；风舍于肺，其人则咳，口干喘满，咽燥不渴，多唾浊沫，时时振寒。热之所过，血为之凝滞，蓄结痈脓。”"},{"t":"b","x":"2. 痰热伤肺"},{"t":"p","x":"嗜酒太过或恣食辛辣煎炸厚味，酿湿生痰化热，灼扰于肺，或宿有痰热蕴肺，复加外感风热，内外合邪，则更易引发本病。"},{"t":"p","x":"或其他脏腑痰浊瘀热蕴结，日久上灼于肺，终成肺痈。"}],"bingji":[{"t":"p","x":"肺痈的基本病机是邪热郁肺，蒸液成痰，邪阻肺络，血滞为瘀，致痰热与瘀血互结，酝酿成痈，血败肉腐化脓，肺损络伤，脓疡内溃外泄。"},{"t":"p","x":"成痈化脓的病理基础在于热壅血瘀，溃脓期是病情顺逆的转折点。"},{"t":"p","x":"病变部位在肺。"},{"t":"p","x":"病理性质属实、属热，主要表现为邪盛的实热证候，如痰热、瘀血郁结、血败肉腐、成痈化脓，脓疡溃后方见阴伤气耗之象。"},{"t":"p","x":"根据病情的发展，其病机演变分为初期、成痈期、溃脓期、恢复期四个阶段。"},{"t":"p","x":"若溃后脓毒不尽，邪恋正虚，则病情迁延，日久不愈而转成慢性。"}],"zhenduan":[{"t":"ol","items":["1. 肺痈发病急骤，常突然寒战高热，胸痛咳嗽，咳吐黏浊痰，继则咳痰量多如脓，有腥味，或脓血相兼。","2. 有感受外邪的病史，且往往有肺系其他痼疾。","3. 传统诊断方法："]},{"t":"p","x":"验痰法：脓血浊痰吐入水中，沉者是痈脓，浮者是痰。"},{"t":"p","x":"验口味：口嚼生黄豆或含生豆汁不觉有腥味。"},{"t":"p","x":"验爪甲：可见“爪甲紫而带弯”，指端呈鼓杵样。"}],"jianbie":[{"t":"b","x":"1. 风温"},{"t":"p","x":"肺痈初期与风温相似。"},{"t":"p","x":"风温起病多急，以发热、咳嗽、烦渴或伴气急胸痛为特征。"},{"t":"p","x":"肺痈以振寒、咳吐浊痰、喉中有腥味为特征。"},{"t":"p","x":"风温经正确及时治疗后，多在气分而解，如经一周身热不退，或退而复升，咳吐浊痰，应进一步考虑肺痈之可能。"},{"t":"b","x":"2. 咳嗽"},{"t":"p","x":"两者均可见发热、咳嗽、咳吐脓痰、胸痛等症状。"},{"t":"p","x":"但咳嗽痰热蕴肺证一般为气分邪热动血伤络，病情较轻，肺痈则为瘀热蕴结成痈酿脓溃破，病情较重。"},{"t":"p","x":"在病理表现上有血热与血瘀的区别，临床特征亦有不同，咳嗽痰热蕴肺证咳吐黄稠脓痰、量多，夹有血色，痰无腥臭味，肺痈则咳吐大量腥臭脓血浊痰。"},{"t":"p","x":"若咳嗽痰热蕴肺证迁延进展，邪热进一步瘀阻肺络，也可发展形成肺痈。"}],"bianzheng":[{"t":"b","x":"1. 辨病期"},{"t":"p","x":"根据病程的不同阶段和临床表现，可分为初期、成痈期、溃脓期、恢复期四个阶段。"},{"t":"p","x":"通过了解痰的量、色、质、味的变化及临床表现，辨其病程所属。初期痰白或黄，量少，质黏，无特殊气味，出现恶寒、发热、咳嗽等肺卫表证；成痈期痰呈黄绿色，量多，质黏稠，有腥臭，出现高热、振寒、咳嗽、气急、胸痛等痰热瘀毒蕴肺的证候；溃脓期表现为排出大量腥臭脓痰或脓血痰，质如米粥，气味腥臭异常；恢复期痰色较黄，量减少，其质清稀，臭味渐轻。若正气逐渐恢复，痈疡渐告愈合。若溃后脓毒不尽，邪恋正虚，则病情迁延。"},{"t":"b","x":"2. 辨顺逆"},{"t":"p","x":"溃脓期是病情顺逆的转折点。顺证为溃后声音清朗，脓血稀而渐少，臭味转淡，饮食知味，胸胁少痛，身体不热，脉象缓滑。逆证为溃后音哑无力，脓血如败卤，腥味异常，气喘鼻扇，胸痛，食少，身热不退，颧红，指甲青紫，脉弦涩或弦急，为肺叶腐败之恶候。"}],"zhize":"肺痈的治疗以祛邪为主，以清热解毒、化瘀排脓为基本治法。因热毒为其基本病邪，故整个病程都应重视清热解毒。血瘀是成痈的病理基础，化瘀有助于痈疡的消散，在成痈期尤为重要。脓已酿成则为热毒盘踞之根，脓净则毒去，故在溃脓期须遵“有脓必排”的原则。具体治疗又当审病程，分阶段施治。初期风热侵犯肺卫，宜清肺散邪；成痈期热壅血瘀，宜清热解毒，化瘀消痈；溃脓期血败肉腐，宜排脓解毒；恢复期阴伤气耗，宜养阴益气；若久病邪恋正虚者，则应扶正祛邪。","syndrome":[{"id":"s040","name":"初期","label":"1. 初期","group":"","clinic":"恶寒发热，咳嗽，胸痛，咳则痛甚，咳吐白色黏痰，痰量日渐增多，呼吸不利，口干鼻燥，舌尖红，苔薄黄或薄白少津，脉浮数而滑。","analysis":"肺卫受邪，正邪交争，则恶寒发热；邪热壅肺，肺气失于宣降，则咳嗽，呼吸不利；肺络阻滞，则胸痛；邪热煎熬津液成痰，故咳白色黏痰，痰量日渐增多；舌尖红，苔薄黄或薄白少津，脉浮数而滑，为风热表证之象。","treat":"疏散风热，清肺化痰。","formulaRaw":"银翘散（《温病条辨》）加减。","formulaName":"银翘散加减","fangjie":"银花、连翘、芦根、竹叶疏风清热解毒；薄荷、荆芥、豆豉、牛蒡子疏风散热宣肺；桔梗、甘草利肺化痰。若内热转甚，身热较重，咳痰黄，口渴，可加生石膏、黄芩；若咳甚痰多，可加杏仁、川贝母、前胡、桑白皮、枇杷叶；若胸痛，呼吸不利，可加瓜蒌皮、广郁金；若头痛，可加菊花、桑叶；若燥热伤津，可加麦冬、天花粉。"},{"id":"s041","name":"成痈期","label":"2. 成痈期","group":"","clinic":"身热转甚，汗出身热不解，胸满作痛，转侧不利，咳吐黄稠痰，或黄绿色痰，自觉喉间有腥味，咳嗽气急，口干咽燥，烦躁不安，舌质红，苔黄腻，脉滑数有力。","analysis":"热毒炽盛，壅阻肺气，瘀阻肺络，故见身热转甚，汗出身热不解，咳嗽气急，胸满作痛，转侧不利；瘀热内结成痈，故咳吐黄稠痰，或黄绿色痰，喉间有腥味；热邪耗津，故口干咽燥；热扰心神，故烦躁不安；舌质红，苔黄腻，脉滑数有力，为痰热瘀毒蕴肺之象。","treat":"清肺解毒，化瘀消痈。","formulaRaw":"苇茎汤（《备急千金要方》）合如金解毒散（《景岳全书》）加减。前方化痰泄热，通瘀散结消痈；后方降火解毒，清肺消痈。","formulaName":"苇茎汤合如金解毒散加减","fangjie":"苇茎甘寒轻浮，善清肺热；薏苡仁、冬瓜子、桃仁化浊行瘀，散结消痈；桔梗、甘草宣肺利咽，祛痰止咳；黄连、黄芩、黄柏、山栀清热燥湿，泻火解毒，消肿排脓。若热毒内盛，可加金银花、连翘、鱼腥草、金荞麦、蒲公英等；若痰热郁肺，咳痰黄稠，可加桑白皮、瓜蒌、射干、海蛤壳；若胸闷喘满，咳唾浊痰量多，可加瓜蒌、桑白皮、葶苈子；若便秘，可加大黄、枳实；若胸痛甚，可加枳壳、丹参、延胡索、郁金。"},{"id":"s042","name":"溃脓期","label":"3. 溃脓期","group":"","clinic":"咳吐大量脓血痰，或如米粥，腥臭异常，有时咳血，身热，面赤，烦渴喜饮，胸中烦满而痛，甚则气喘不能卧，舌质红，苔黄腻，脉滑数或数实。","analysis":"痈肿内溃，故排出大量腥臭脓血痰；肺中蓄脓，肺气不利，肺脉瘀阻，故胸中烦满而痛，气喘不能卧；热毒内蒸，故身热面赤；热耗津液，故烦渴喜饮；舌质红，苔黄腻，脉滑数或数实，为热盛肉腐，血败化脓之象。","treat":"排脓解毒。","formulaRaw":"加味桔梗汤（《医学心悟》）加减。","formulaName":"加味桔梗汤加减","fangjie":"桔梗、薏苡仁排脓解毒；橘红、贝母、甘草化痰止咳；银花清热解毒；葶苈子泻肺逐痰；白及凉血止血。可另加黄芩、鱼腥草、野荞麦根、败酱草、蒲公英。若脓出不畅，可加皂角；若气虚无力排脓，可加生黄芪；若咳血，可加白茅根、藕节、丹参、侧柏叶等。"},{"id":"s043","name":"恢复期","label":"4. 恢复期","group":"","clinic":"身热渐退，咳嗽减轻，咳吐脓血渐少，臭味亦减，痰液转为清稀，精神渐振，食欲改善，或见胸胁隐痛，难以久卧，气短乏力，自汗，盗汗，低热，午后潮热，心烦，口干咽燥，面色不华，形瘦神疲，舌质红或淡红，苔薄，脉细或细数无力。","analysis":"脓痰排出，邪去正安，故身热渐退，咳嗽减轻，全身症状趋于好转；肺损络伤，溃处未敛，故胸胁隐痛，难以久卧；肺气亏虚，故气短乏力，自汗；肺阴亏虚，故盗汗，潮热，心烦，口燥咽干。舌质红，苔薄，脉细或细数无力，为气阴两伤之象。","treat":"益气养阴清肺。","formulaRaw":"沙参清肺汤（验方）合竹叶石膏汤（《伤寒论》）加减。前方养阴清肺，后方清热生津益气。","formulaName":"沙参清肺汤合竹叶石膏汤加减","fangjie":"前方中北沙参养阴润肺；白及收敛止血；生黄芪、太子参益气生肌；桔梗、甘草、薏苡仁、冬瓜子、合欢皮化痰泄浊，排脓消痈。后方中竹叶、石膏清热除烦；人参、麦冬补气养阴生津；半夏、甘草、粳米和脾养胃。若溃处不敛，可加阿胶、白蔹；若脾虚食少便溏，可配伍白术、山药、茯苓；若有低热，可酌配功劳叶、青蒿、白薇、地骨皮；若邪恋正虚，咳痰腥臭脓浊，反复迁延，日久不净，可酌加鱼腥草、败酱草、金荞麦等。"}],"linchuang":["脓液能否排出是治疗成败的关键。在痈脓溃破时，蓄结之脓毒尚盛，邪气仍实，治当以排脓为主。桔梗常用为排脓的主药，可与薏苡仁、冬瓜仁、浙贝母、瓜蒌皮、桃仁等合用，且用量宜大。排脓不畅者，加皂角刺、金荞麦等。溃脓期气虚而无力排脓者，加生黄芪。脓毒去则正自易复，不可早予补敛，以免留邪，延长病程。恢复期虽属邪衰正虚，阴气内伤，应以清养补肺为主，扶正以托邪，但仍需防其余毒不净，适当佐以排脓之品。若溃后脓痰一度清稀而复转臭浊，或腥臭脓血迁延日久不尽，时轻时重，为邪恋正虚，脓毒未净，虚实错杂，提示邪毒复燃或转为慢性，仍须重视解毒排脓之法。","防止发生大咳血。成痈溃脓时，若病灶部位有较大肺络损伤，则可发生大量咳血，应警惕出现血块阻塞气道，或气随血脱的危象，应当按照“血证”治疗，采取相应的急救措施。","慎温补，宜通腑。本病不可滥用温补保肺药，尤忌发汗损伤肺气。还应注意保持大便通畅，因肺与大肠相表里，大便通可不致腑热上攻，以利肺气宣降，且热毒之邪亦得从大便而解。"],"yufang":["凡属肺虚或原有其他慢性疾患，肺卫不固，易感外邪者，当注意寒温适度，起居有节，以防受邪致病，并禁烟酒及辛辣炙煿食物，以免燥热伤肺。本病初期，一旦确诊，应及早治疗，力求在未成脓前得到消散，或减轻病情。截断疾病发展，多能痊愈而无后遗症。","肺痈患者的护理，应做到安静卧床休息，每天观察记录体温、脉象的变化，咳嗽情况，咳痰的色、质、量、味，注意室温的调节，做好防寒保暖。饮食宜清淡，多食蔬菜，高热者可予半流质饮食。多吃水果，如橘子、梨、枇杷等，均有润肺生津化痰的作用。每天可用薏米煨粥食之，并取鲜芦根煎汤代茶。忌油腻厚味及一切辛辣刺激、海腥之物，如辣椒、韭菜、海虾等。严禁烟酒。"],"attachIds":[]},{"id":"d007","name":"肺痨","kind":"main","parent":null,"chapterNo":"第十章","chapterName":"肺痨","yinbing":[{"t":"p","x":"肺痨的发生主要是由正气不足，感染痨虫引起的，痨虫蚀肺，耗损肺阴，进而导致阴虚火旺，或致气阴两虚，甚则阴损及阳。"},{"t":"b","x":"1. 感染痨虫"},{"t":"p","x":"肺痨具有传染性，感染痨虫是引发本病的外因。"},{"t":"p","x":"与患者直接接触，如饮食、问病、看护、家人相处等，感染痨虫，痨虫入肺，发为肺痨。"},{"t":"p","x":"宋·陈言《三因极一病证方论·痨瘵诸证》云：“诸证虽不同，其根多有虫。”"},{"t":"b","x":"2. 正气不足"},{"t":"p","x":"先天禀赋不足，或情志不遂，忧思过度，或嗜欲无节，酒色劳倦，或病后失调，营养不充，均可导致气血不足，正气虚弱，是引发本病的内因。"},{"t":"p","x":"清·沈金鳌《杂病源流犀烛·虚损痨瘵源流》云：“有思虑过度，心气不舒，郁热熏蒸胸中，因生内热，而成痨者。”"},{"t":"p","x":"感染痨虫和正气不足可互为因果。"},{"t":"p","x":"痨虫是发病的外因，正虚是发病的基础。"},{"t":"p","x":"正气强弱不仅是发病的关键，也是肺痨传变、转归的决定性因素。"},{"t":"p","x":"如正气较强，则能抗御痨虫，使病变局限，病势趋好。"},{"t":"p","x":"如正气虚弱，则往往由一脏之虚发展成多脏亏虚，病情由轻转重。"}],"bingji":[{"t":"p","x":"肺痨的基本病机是痨虫蚀肺，肺阴耗损，阴虚火旺，阴损及阳。"},{"t":"p","x":"病变部位主要在肺，久则可传脾肾，也可涉及心肝。"},{"t":"p","x":"病理性质以阴虚为主，亦可延及气阴两虚，甚或阴阳两虚。"},{"t":"p","x":"肺痨在发展过程中，常发生病机转化。"},{"t":"p","x":"肺主气，吸清呼浊，若肺脏本虚，卫外不强，或因其他脏腑病变耗伤肺气，导致肺虚，则易受痨虫侵蚀而发病。"},{"t":"p","x":"肺肾相生，肾为肺之子，肺虚肾失滋生之源，或肾虚相火灼金，上耗母气，致肺肾两虚，伴骨蒸、潮热、遗精、月经不调等症。"},{"t":"p","x":"脾为肺之母，肺虚子盗母气，则脾亦虚，脾虚不能运化水谷精微，上输以养肺，则肺亦虚，终致肺脾同病，伴见疲乏、食少、便溏等脾虚症状。"},{"t":"p","x":"肺痨久延而病重者，因精血亏损，可以发展到肺、脾、肾三脏俱亏。"},{"t":"p","x":"或因肺病及肾，肾虚不能助肺纳气；或因脾病及肾，脾不能化精以资肾；甚则肺虚不能佐心，不能治节血脉运行，而致气虚血瘀，出现气短、喘息、心慌、唇紫、浮肿、肢冷等重症。"},{"t":"p","x":"关于肺痨的预后转归，一般而言，凡正气较强，病情轻浅，为时短暂，早期治疗者，可获康复。"},{"t":"p","x":"若正气虚弱，或治疗不及时，迁延日久，每多演变恶化，难治难愈。"},{"t":"p","x":"少数患者可呈急性发病，出现剧烈咳嗽，喘促倚息，咳吐大量鲜血，寒热如疟等，俗称“急痨”“百日痨”，预后较差。"}],"zhenduan":[{"t":"ol","items":["1. 肺痨以咳嗽、咯血、潮热、盗汗、身体明显消瘦为主要临床特征。不典型者可仅感疲乏无力、微咳、食欲不振、身体逐渐消瘦。","2. 常有与肺痨患者的密切接触史。"]}],"jianbie":[{"t":"b","x":"1. 虚劳"},{"t":"p","x":"虚劳与肺痨都属于慢性虚损性疾病。"},{"t":"p","x":"虚劳是因脏腑亏损所致的多种慢性虚损性疾病的总称，病理性质为五脏虚损，可出现五脏气、血、阴、阳亏虚表现，一般无传染性。"},{"t":"p","x":"肺痨是一个独立病种，因体质虚弱，痨虫侵肺所致，病位主要在肺，病理性质以阴虚为主，主要表现为咳嗽、咯血、潮热、盗汗和身体消瘦等，具有传染性。"},{"t":"b","x":"2. 肺痿"},{"t":"p","x":"肺痿与肺痨的病位均在肺。"},{"t":"p","x":"肺痿以咳吐浊唾涎沫为主症，而肺痨以咳嗽、咯血、潮热、盗汗为特征。"},{"t":"p","x":"肺痿是肺部多种慢性疾患后期的病理转归，以肺叶痿弱不用为特点。"},{"t":"p","x":"肺痨晚期，如出现干咳、咳吐涎沫等症，则属肺痿。"}],"bianzheng":[{"t":"b","x":"1. 辨病变部位"},{"t":"p","x":"病变初期在肺，阴虚火旺者常肺肾两虚，气阴耗伤者多肺脾同病；久延病重，由气及阳，阴阳两虚者，属肺脾肾三脏皆损，并涉及心肝。"},{"t":"b","x":"2. 辨病理性质"},{"t":"p","x":"以肺阴虚为主。肺肾两伤，元阴受损，表现出阴虚火旺之象；肺损及脾，以气阴两虚为主；由气虚而致阳虚，表现为阴阳两虚之候。"}],"zhize":"肺痨的治疗以补虚培元和治痨杀虫为基本治则。根据肺痨“主乎阴虚”的基本病机，痨虫蚀肺，肺阴耗损者，治以滋阴润肺为主；阴虚火旺，虚火灼肺者，应滋阴降火，补益肺肾；阴伤气耗、肺脾两虚者，应养阴润肺，补土生金；阴伤及阳，阴阳俱虚者，应滋阴补阳，培元固本。在补虚的基础上针对痨虫侵染而给予杀虫治痨，对因治疗。","syndrome":[{"id":"s044","name":"肺阴亏损证","label":"1. 肺阴亏损证","group":"","clinic":"干咳，咳声短促，或咳少量黏痰，或痰中带血丝，色鲜红，胸部隐隐闷痛，午后手足心热，皮肤干灼，口干咽燥，或有轻微盗汗，舌边尖红，苔薄少津，脉细或兼数。","analysis":"痨虫蚀肺，耗伤肺阴，故干咳，咳声短促，或咳少量黏痰；阴虚肺燥，肺损络伤，故见痰中带血丝，色鲜红，胸部隐隐闷痛；肺失滋润，阴虚内热，故皮肤干灼，口干咽燥，午后手足心热，或有轻微盗汗；舌边尖红，苔薄少津，脉细或兼数，为肺阴亏虚之象。","treat":"滋阴润肺。","formulaRaw":"月华丸（《医学心悟》）加减。","formulaName":"月华丸加减","fangjie":"沙参、麦冬、天冬、生地黄、熟地黄滋阴润肺；百部抗痨杀虫；川贝母润肺止咳；阿胶、三七止血和营；茯苓、山药培土生金；桑叶、菊花清透内热。若痰中带血较多，可加仙鹤草、藕节、白茅根等；若低热不退，可加银柴胡、青蒿、胡黄连、地骨皮、功劳叶等；若咳久不已，声音嘶哑，可加诃子、木蝴蝶等。"},{"id":"s045","name":"虚火灼肺证","label":"2. 虚火灼肺证","group":"","clinic":"咳呛气急，痰少质黏，或咳痰黄稠量多，或时时咯血，血色鲜红，午后潮热，骨蒸，五心烦热，颧红，盗汗量多，口渴，心烦，失眠，性急易怒，胸胁掣痛，男子可见遗精，女子月经不调，形体日渐消瘦，舌质红而干，苔薄黄或剥，脉细数。","analysis":"肺病及肾，水亏火旺，灼津成痰，故咳呛气急，痰黏或黄稠；虚火灼络，故咯血鲜红；阴虚内热，故潮热，盗汗，口渴；心肝火旺，故心烦易怒，胸胁掣痛；阴精耗损，故男子遗精，女子月经不调，形体日渐消瘦；舌质红而干，苔薄黄或剥，脉细数，均为阴虚火旺之象。","treat":"补肺益肾，滋阴降火。","formulaRaw":"百合固金汤（《慎斋遗书》）合秦艽鳖甲散（《卫生宝鉴》）加减。前方滋养肺肾，后方滋阴清热除蒸。","formulaName":"百合固金汤合秦艽鳖甲散加减","fangjie":"百合、玄参、麦冬、生地黄、熟地黄滋肾润肺生津；鳖甲、知母、秦艽、银柴胡、地骨皮、青蒿滋阴清热除蒸；川贝母、桔梗、甘草润肺化痰止咳；当归、白芍养血柔肝。若火旺较甚，热象明显，可加胡黄连、黄芩等；若咳痰黄稠量多，可加桑白皮、海蛤壳、鱼腥草等；若咯血不止，可加牡丹皮、紫珠草、大黄炭或十灰散等；若盗汗较著，可加煅龙骨、煅牡蛎、浮小麦等。"},{"id":"s046","name":"气阴耗伤证","label":"3. 气阴耗伤证","group":"","clinic":"咳嗽无力，气短声低，痰中偶有夹血，血色淡红，午后潮热，面色㿠白，颧红，少量盗汗或自汗，纳少，神疲，便溏，舌质嫩红，边有齿印，苔薄白，脉细弱而数。","analysis":"肺脾同病，阴伤气耗，故咳嗽无力，气短声低；肺虚络损，故咯血色淡红；阴虚内热，故午后潮热，颧红，盗汗；肺卫不固，故自汗；脾失健运，故纳少，神疲，便溏；舌质嫩红，边有齿痕，苔薄白，脉细弱而数，为气阴耗伤之象。","treat":"益气养阴，补土生金。","formulaRaw":"保真汤（《十药神书》）加减。","formulaName":"保真汤加减","fangjie":"人参、黄芪、白术、茯苓、甘草补肺健脾；麦冬、天冬、生地黄、五味子滋阴润肺；当归、白芍、熟地黄滋补阴血；知母、黄柏、地骨皮、柴胡清退虚热；陈皮、厚朴理气健脾。若咳嗽，痰白量多，可加半夏、橘红、白前等；若咯血色红量多，可加仙鹤草、白及等；若纳少，腹胀，便溏，可加白扁豆、薏苡仁、莲子等。"},{"id":"s047","name":"阴阳两虚证","label":"4. 阴阳两虚证","group":"","clinic":"咳逆喘息少气，痰中或见夹血，血色暗淡，声嘶或失音，潮热，自汗，盗汗，面浮肢肿，心慌，唇紫，肢冷，形寒，或见五更泄泻，口舌生糜，大肉尽脱，男子滑精、阳痿，女子经少、经闭，舌质光红少津或淡胖边有齿痕，脉微细而数或虚大无力。","analysis":"阴伤及阳，肺脾肾俱虚，气逆失纳，故咳喘少气；气阴两伤，故声嘶失音，潮热汗出；阳气不足，故见面浮肢肿，心慌唇紫，形寒肢冷，五更泄泻；精气虚竭，故见口舌生糜，大肉尽脱，男子滑精阳痿，女子经少经闭；舌质光红少津或淡胖边有齿痕，脉微细而数或虚大无力，为阴阳俱损之象。","treat":"滋阴补阳，培元固本。","formulaRaw":"补天大造丸（《医学心悟》）加减。","formulaName":"补天大造丸加减","fangjie":"人参、黄芪、白术、茯苓、山药补益肺脾之气；熟地黄、枸杞子、当归、白芍补肾养血；阿胶、龟甲培补阴精；鹿角胶、紫河车助真阳、填精髓。若肾虚气逆喘息，可加冬虫夏草、诃子、紫石英等；若五更泄泻，可加肉豆蔻、补骨脂等；若阳痿、遗精，可加金樱子、芡实、莲须等；若月经不调或经闭，可加赤芍、牡丹皮、益母草等。"}],"linchuang":["病证结合，在辨证基础上加用抗结核杀虫药物。除按西医规范完成抗结核疗程外，可适当选用具有抗结核作用的中草药，如百部、白及、黄连、大蒜、冬虫夏草、功劳叶等。同时注意补益正气，有利于减轻抗结核药的毒副作用。","虚实结合，分清主次。本病因感染“痨虫”致病，根据“补虚不忘治实”的原则，须兼顾“杀虫抗痨”。补虚重在滋阴，兼火旺则佐以清火，兼气虚则配合益气，阴阳两虚则滋阴补阳并施。临证中还需分清咳嗽、咯血、盗汗、消瘦四大主症的轻重主次，有侧重地随证治疗。此外，如病情急重，表现为“急痨”“百日痨”特殊情况，或出现类似“湿温”“类疟”等证候者，临床上应予重视，尽早辨识，准确施治，以免贻误病情。","用药忌苦寒太过，以防伤阴败胃。本病可见火旺之象，但本质在于阴虚，故临证当以甘寒养阴为主，适当佐以清火。即使肺火标象明显，亦只宜暂予清降，中病即止，不可徒持苦寒逆折，过量或久用，以免苦燥伤阴，寒凉败胃伤脾。"],"yufang":["本病传染性强，防重于治，避免接触肺痨患者及其气道分泌物；需接触患者时，应佩戴口罩；饮食适宜，劳逸适度，提高自身抵抗力。","肺痨患者要耐心接受治疗，勿随地吐痰，病室经常通风。同时须重视摄生，避免劳累，禁烟酒，慎房事，怡情志，适当进行体育锻炼，加强饮食调养，忌食辛辣刺激、动火耗伤津液之物。"],"attachIds":[]},{"id":"d008","name":"肺痿","kind":"main","parent":null,"chapterNo":"第十一章","chapterName":"肺痿","yinbing":[{"t":"p","x":"肺痿的病因可分久病损肺和误治津伤两个方面，以前者为主，引起津气亏损，肺失濡养。"},{"t":"b","x":"1. 久病损肺"},{"t":"p","x":"如痰热久嗽，热灼阴伤，或肺痨久嗽，虚热内灼，耗伤阴津，或肺痈余毒未清，灼伤肺阴，或消渴津液耗伤，或热病之后，邪热伤津，津液大亏，以致热壅上焦，消灼肺津，变生涎沫，肺燥阴竭，肺失濡养，日渐枯萎。"},{"t":"p","x":"若大病久病之后，耗伤阳气，或内伤久咳，冷哮不愈，肺虚久喘等，肺气日耗，渐而伤阳，或虚热肺痿日久，阴损及阳，亦可致肺虚有寒，气不化津，津液失于温摄，反为涎沫，肺失濡养，肺叶渐痿不用。"},{"t":"b","x":"2. 误治津伤"},{"t":"p","x":"因医者误治，滥用汗、吐、下等治法，重亡津液，肺津大亏，肺失濡养，发为肺痿。"},{"t":"p","x":"《金匮要略·肺痿肺痈咳嗽上气病脉证治》云：“热在上焦者，因咳为肺痿。肺痿之病……或从汗出，或从呕吐，或从消渴，小便利数，或从便难，又被快药下利，重亡津液，故得之。”"}],"bingji":[{"t":"p","x":"肺痿的基本病机为肺失濡养，痿弱不用。"},{"t":"p","x":"因肺虚有热，热灼肺津，或肺虚有寒，气不化津，以致津气亏损，肺失濡养，肺叶弱而不用则痿。"},{"t":"p","x":"清·喻嘉言《医门法律·肺痈肺痿门》云：“肺痿者，肺气痿而不振也。”“其寒热不止一端，总由胃中津液不输于肺，肺失所养，转枯转燥”，“于是肺火日炽，肺热日深，肺中小管日窒”。"},{"t":"p","x":"其指出肺脏虚损，津液亡失，则肺叶枯萎而不用。"},{"t":"p","x":"病变部位在肺，与脾、胃、肾等脏腑密切相关。"},{"t":"p","x":"病理性质有肺燥津伤、肺气虚冷之分。"},{"t":"p","x":"清·尤在泾《金匮要略心典·肺痿肺痈咳嗽上气病脉证治》云：“盖肺为娇脏，热则气烁，故不用而痿；冷则气沮，故亦不用而痿也。”"},{"t":"p","x":"病理表现有虚热、虚寒两类。"},{"t":"p","x":"①虚热肺痿：一为本脏自病转归，一为失治误治或他脏之病导致。"},{"t":"p","x":"②虚寒肺痿：肺气虚冷，不能温化、固摄津液，由气虚导致津亏，或阴伤及阳，气不化津，以致肺失濡养，渐致肺叶痿弱不用。"},{"t":"p","x":"此外，肺痿无论虚寒、虚热或寒热错杂，病久由气及血，而有血瘀，为虚中夹实。"},{"t":"p","x":"肺痿虚寒、虚热之间可互相转化。"},{"t":"p","x":"如虚热肺痿日久不愈，阴损及阳，进一步发展，可转化为虚寒之候；虚寒肺痿，亦可由寒郁化热，或阳损及阴，从而转化为虚热之证。"},{"t":"p","x":"肺痿日久，迁延不愈，可以转化为虚劳。"},{"t":"p","x":"清·江涵暾《笔花医镜·虚劳论治》曰：“肺金痿者，其受病不同，及其成劳一也。”"}],"zhenduan":[{"t":"ol","items":["1. 以咳吐浊唾涎沫为主要症状。唾呈细沫稠黏，或白如雪，或带白丝，咳嗽，或不咳，气息短，或动则气喘。","2. 常伴有面色㿠白，或青苍，形体瘦削，神疲，头晕，或时有寒热等。","3. 有多种慢性肺系疾病史，久病体虚。"]}],"jianbie":[{"t":"p","x":"主要与肺痈鉴别。"},{"t":"p","x":"肺痈与肺痿均可见咳嗽、咳痰的临床表现，但肺痿多因久病肺虚、误治津气亏损致虚热肺痿或虚寒肺痿，以咳吐浊唾涎沫为主症，病性本虚标实而以本虚为主；肺痈多因外感风热、痰热内盛致热壅血瘀，酝酿成痈，血败肉腐化脓而成，以咳则胸痛、吐痰腥臭甚则咳吐脓血为主症，病性以实为主。"},{"t":"p","x":"若肺痈久延不愈，误治失治，痰热蕴结上焦，熏灼肺阴，可转成肺痿。"}],"bianzheng":[{"t":"p","x":"辨虚热、虚寒。症见咳吐涎沫，质地黏稠，咳声不爽，气逆喘息，口渴咽干，午后潮热，舌红而干，脉象虚数者，为虚热；症见咳吐涎沫，其质清稀量多，短气乏力，形寒食少，舌质淡，脉虚弱，日久病甚上不制下时，见小便频数或遗尿者，为虚寒。"}],"zhize":"本病以补肺生津为基本治则。虚热证，治当清热生津，以润其枯；虚寒证，治当温肺益气，以摄涎沫。应时刻注意保护津液，要重视调理脾肾，培土有助于生金，温肾可以助肺纳气。","syndrome":[{"id":"s048","name":"虚热","label":"1. 虚热","group":"","clinic":"咳吐浊唾，或咳痰带血，咳声不扬，甚则音嗄，气急喘促，口渴咽燥，可伴潮热盗汗，形体消瘦，皮毛干枯，舌红而干，脉虚数。","analysis":"肺阴亏耗，虚火内炽，灼津为痰，故咳吐浊唾；阴虚肺燥，咳伤肺络，故咳痰带血；肺金不足，金破不鸣，故咳声不扬，甚则音嗄；肺失滋润，宣降失职，肺气上逆，故气急喘促；虚火内盛，阴亏津伤，皮毛失荣，故口渴咽燥，潮热盗汗，形体消瘦，皮毛干枯；舌红而干，脉虚数，为肺虚有热之象。","treat":"滋阴清热，生津润肺。","formulaRaw":"麦门冬汤（《金匮要略》）合清燥救肺汤（《医门法律》）加减。前方润肺生津，降逆下气；后方养阴润燥，清金降火。","formulaName":"麦门冬汤合清燥救肺汤加减","fangjie":"太子参、甘草、大枣、粳米益气生津，甘缓补中；桑叶、石膏清泄肺经燥热；阿胶、麦冬、胡麻仁滋肺养阴；杏仁、枇杷叶、半夏化痰止咳，下气降逆。若肺胃火盛，虚烦呛咳，可加芦根、竹茹、竹叶；若咳唾浊痰，口干欲饮，可加天花粉、知母、川贝母等；若津伤较著，可加北沙参、天冬、玉竹等；若潮热较著，可加胡黄连、银柴胡、地骨皮、白薇等。"},{"id":"s049","name":"虚寒","label":"2. 虚寒","group":"","clinic":"咳吐涎沫，质清稀量多，不渴，短气不足以息，头眩，神疲乏力，食少，形寒，小便数，或遗尿，舌质淡，脉虚弱。","analysis":"肺气虚寒，气不化津，津反为涎，故咳吐涎沫，质稀量多；肺虚有寒，故口不渴；肺气亏虚，故短气不足以息；脾气亏虚，运化无力，精微不足，形体失养，故头眩，神疲乏力，食少；肺脾虚寒，故形寒；肺虚不能通调水道，故小便数，或遗尿；舌质淡，脉虚弱，为肺虚有寒之象。","treat":"温肺益气，生津润肺。","formulaRaw":"甘草干姜汤（《伤寒论》）或生姜甘草汤（《备急千金要方》）加减。前方辛甘化阳，温养肺胃；后方补脾助肺，益气生津。","formulaName":"甘草干姜汤或生姜甘草汤加减","fangjie":"甘草、干姜温肺脾；人参、大枣、白术、茯苓甘温补脾，益气生津。若肺虚失约，唾沫多而尿频，可加益智仁、白果等；若肾虚不能纳气，喘息，短气，可加钟乳石、五味子，另服蛤蚧粉。"}],"linchuang":["重视调补脾肾。脾胃为后天之本，肺金之母，培土有助于生金。阴虚者宜补胃津以润燥，使胃津能上输以养肺；气虚者宜补脾气以温养肺体，使脾能转输精气以上承。肾为气之根，司摄纳，补肾可以助肺纳气。","用药忌燥热、苦寒或祛痰峻剂。肺痿病属津枯，故应时刻注意保护其津，无论寒热，皆不宜妄用温燥之药，消灼肺津，即使虚寒肺痿，亦必须掌握辛甘合用的原则。肺痿属虚，故一般忌用峻剂攻逐痰涎，犯虚虚实实之戒，宜缓图取效。","注意病机演变，法随证转。肺痿有虚热、虚寒之分，二者不仅可以相互转化，甚则可相兼为病，既可见气阴两虚、阴阳互损，也可见虚实寒热错杂之证。病久者也可见血瘀，或兼见痰饮等。因此，在辨治过程中，应时刻注意病机演变，分清主次，抓住主证，兼顾次证，施治方可中的。"],"yufang":["预防的重点在于积极治疗咳喘等肺部疾患，防止其向肺痿转变，同时根据个人情况，加强体育锻炼。慎起居，生活规律，视气候随时增减衣服。时邪流行时，尽量减少外出，避免接触患者。","肺痿为慢性虚损性疾病，应避免急躁情绪，坚持长期调治。注意耐寒锻炼，适应气候变化，增强肺卫功能。戒烟，减少对呼吸道的刺激，以利肺气恢复。饮食宜清淡，忌寒凉油腻。居处要保持清洁，避免烟尘刺激。"],"attachIds":[]},{"id":"d009","name":"心悸","kind":"main","parent":null,"chapterNo":"第十二章","chapterName":"心悸","yinbing":[{"t":"p","x":"心悸的发生多因体虚劳倦、七情所伤、感受外邪及药食不当等，以致气血阴阳亏损，心神失养，心神不安，或痰、饮、火、瘀阻滞心脉，扰乱心神。"},{"t":"b","x":"1. 体虚劳倦"},{"t":"p","x":"禀赋不足，素体虚弱，或久病伤正，耗损心之气阴，或劳倦太过伤脾，生化之源不足，气血阴阳亏损，脏腑功能失调，致心神失养，发为心悸。"},{"t":"p","x":"《丹溪心法·惊悸怔忡》云：“人之所主者心，心之所养者血，心血一虚，神气不守，此惊悸之所肇端也。”"},{"t":"b","x":"2. 七情所伤"},{"t":"p","x":"平素心虚胆怯，突遇惊恐，忤犯心神，心神动摇，不能自主而发心悸。"},{"t":"p","x":"《严氏济生方·惊悸论治》云：“惊悸者，心虚胆怯之所致也。”"},{"t":"p","x":"此外，大怒伤肝，大恐伤肾，怒则气逆，恐则精却，阴虚于下，火逆于上，扰乱心神，亦可发为惊悸。"},{"t":"b","x":"3. 感受外邪"},{"t":"p","x":"痹证日久，复感外邪，内舍于心，痹阻心脉，心血运行受阻，发为心悸。"},{"t":"p","x":"或风、寒、湿热之邪，由血脉内侵于心，耗伤心气心阴，亦可引起心悸。"},{"t":"b","x":"4. 药食不当"},{"t":"p","x":"嗜食醇酒厚味、煎炸炙煿，蕴热化火生痰，痰火上扰心神则为悸。"},{"t":"p","x":"清·吴澄《不居集·怔忡惊悸健忘善怒善恐不眠》云：“心者，身之主，神之舍也。心血不足，多为痰火扰动。”"},{"t":"p","x":"或因药物过量或毒性较剧，耗伤心气，损伤心阴，引起心悸。"}],"bingji":[{"t":"p","x":"心悸的基本病机不外乎气血阴阳亏虚，心失所养，或邪扰心神，心神不宁。"},{"t":"p","x":"病变部位主要在心，与肝、脾、肾、肺等密切相关。"},{"t":"p","x":"病理性质主要有虚实两方面。"},{"t":"p","x":"虚者为气、血、阴、阳亏损，心失滋养，而致心悸；实者多由痰火扰心、水饮凌心或心血瘀阻，气血运行不畅，而发心悸。"},{"t":"p","x":"病理因素有痰、饮、火、瘀。"},{"t":"p","x":"实证日久，病邪伤正，可分别兼见气、血、阴、阳之亏损，而虚证也可因虚致实，兼见实证表现。"},{"t":"p","x":"心悸初起以心气虚为常见，表现为心气不足、心血不足、心脾两虚、心虚胆怯和气阴两虚等证。"},{"t":"p","x":"若阴损及阳，或阳损及阴，可出现阴阳俱损之候。"},{"t":"p","x":"若病情恶化，心阳暴脱，为病情危重的表现，可出现厥脱等危候，预后不佳。"}],"zhenduan":[{"t":"ol","items":["1. 自觉心中悸动不安，心搏异常，或快速，或缓慢，或跳动过重，或忽跳忽止，呈阵发性或持续不解，甚则不能自主。可见数、促、结、代、涩、缓、沉、迟等脉象。","2. 常伴有胸闷不舒、易激动、心烦寐差、颤抖乏力、头晕等症。中老年患者，可伴有心胸疼痛，甚则喘促，汗出肢冷，甚则晕厥。","3. 发病常与情志刺激（如惊恐、紧张）及劳倦、饮酒、饱食、服用特殊药物等有关。"]}],"jianbie":[{"t":"b","x":"1. 惊悸与怔忡"},{"t":"p","x":"心悸可分为惊悸与怔忡。"},{"t":"p","x":"惊悸发病，多与情绪因素有关，可由骤遇惊恐、忧思恼怒、悲哀过极或过度紧张诱发，多为阵发性，病来虽速，病情较轻，实证居多，可自行缓解，不发时如常人。"},{"t":"p","x":"怔忡多由久病体虚，心脏受损所致，无明显诱因亦可发生，常呈持续性，心中惕惕，不能自控，活动后加重，多属虚证，或虚中夹实，病来虽渐，病情较重，不发时亦可兼见脏腑虚损症状。"},{"t":"p","x":"惊悸日久不愈，亦可渐成怔忡。"},{"t":"b","x":"2. 奔豚"},{"t":"p","x":"心悸与奔豚皆可出现心中悸动不安、心慌的表现。"},{"t":"p","x":"但心悸为心中剧烈跳动，发自心。"},{"t":"p","x":"奔豚发作之时，亦觉心胸躁动不安，乃冲气上逆，发自少腹。"},{"t":"p","x":"《难经·五十六难》云：“发于少腹，上至心下，若豚状，或上或下无时。”"},{"t":"p","x":"并被称为肾积。"}],"bianzheng":[{"t":"b","x":"1. 辨虚实"},{"t":"p","x":"心悸应辨虚实，虚者为脏腑气血阴阳亏虚，实者多为水饮、瘀血、痰火上扰。临床也常见虚实夹杂者，宜分清虚实主次。"},{"t":"b","x":"2. 辨病位"},{"t":"p","x":"心悸的病位在心，心之病变可以导致其他脏腑功能失调或虚损，其他脏腑病变亦可以直接或间接影响心，故临床亦应分清心脏与他脏的病变情况，这有利于决定治疗的先后缓急。"}],"zhize":"心悸的治疗以安神定悸为基本治则，分虚实论治。虚证分别予以补气、养血、滋阴、温阳；实证则应祛痰、化饮、清火、行瘀。但本病以虚实错杂为多见，且虚实的主次、缓急各有不同，故治当虚实兼顾。同时，由于心悸均有心神不宁的病理特点，故应酌情配合安神宁心或镇心之法。","syndrome":[{"id":"s050","name":"心虚胆怯证","label":"1. 心虚胆怯证","group":"","clinic":"心悸不宁，善惊易恐，坐卧不安，不寐多梦而易惊醒，恶闻声响，食少纳呆，舌淡红，苔薄白，脉细数或细弦。","analysis":"心虚胆怯，突受惊吓，心惊神摇，心神不能自主，故见心悸不宁；心不藏神，心中惕惕，则善惊易恐，坐卧不安，恶闻声响，不寐多梦而易惊醒；心病及脾，脾失运化，则食少纳呆；舌淡红，苔薄白，脉细数或细弦，为心胆气虚、气血不足之象。","treat":"镇惊定志，养心安神。","formulaRaw":"安神定志丸（《医学心悟》）加减。","formulaName":"安神定志丸加减","fangjie":"龙齿、远志、茯神养心安神；石菖蒲宁心安神；人参、茯苓益气宁心。若气短乏力，头晕目眩，动则为甚，静则悸缓，为心气虚损明显，重用人参，加黄芪；心阳不振，加附子（制）；心血不足，加阿胶、制何首乌、龙眼肉；肝气郁结，心悸烦闷，精神抑郁，加柴胡、郁金、合欢皮、绿萼梅；气虚夹湿，加泽泻，重用白术、茯苓；气虚夹瘀，加丹参、川芎、红花、郁金。"},{"id":"s051","name":"心血不足证","label":"2. 心血不足证","group":"","clinic":"心悸气短，头晕目眩，失眠健忘，面色无华，倦怠乏力，纳呆食少，舌淡红，脉细弱。","analysis":"思虑过度，劳伤心脾，气血亏虚，心神失养，故见心悸气短，失眠健忘；脾虚运化无力，故纳呆食少；气血亏虚，无力上荣清窍，则头晕目眩，面色无华；倦怠乏力，舌淡红，脉细弱，为气血亏虚之象。","treat":"补血养心，益气安神。","formulaRaw":"归脾汤（《校注妇人良方》）加减。","formulaName":"归脾汤加减","fangjie":"黄芪、人参、白术、炙甘草益气健脾，以资气血生化之源；当归、龙眼肉补养心血；茯神、远志、酸枣仁宁心安神；木香理气醒脾，使补而不滞。阳虚而汗出肢冷，加附子（制）、煅龙骨、煅牡蛎；阴虚，重用地黄、阿胶，加北沙参、玉竹、石斛；纳呆腹胀，加陈皮、谷芽、麦芽、神曲、山楂、鸡内金、枳壳；失眠多梦，加合欢皮、夜交藤、五味子、柏子仁、莲子心。若五心烦热，自汗盗汗，胸闷心烦，舌淡红少津，苔少或无，脉细数或结代，为气阴两虚，用炙甘草汤加减。热病后期损及心阴而心悸者，用生脉散加减。"},{"id":"s052","name":"阴虚火旺证","label":"3. 阴虚火旺证","group":"","clinic":"心悸易惊，心烦失眠，五心烦热，口干，盗汗，思虑劳心则症状加重，伴耳鸣腰酸，头晕目眩，急躁易怒，舌红少津，苔少或无，脉细数。","analysis":"肾阴不足，水不济火，不能上济于心，阴虚火旺，扰动心神，故见心悸易惊，心烦失眠；阳扰于上，则耳鸣，头晕目眩，急躁易怒，遇劳加重；阴亏于下，则腰酸；五心烦热，口干，盗汗，舌红少津，苔少或无，脉细数，为阴虚火旺之象。","treat":"滋阴清火，养心安神。","formulaRaw":"天王补心丹（《校注妇人良方》）合朱砂安神丸（《内外伤辨惑论》）加减。前方滋阴养血，补心安神；后方清心降火，重镇安神。","formulaName":"天王补心丹合朱砂安神丸加减","fangjie":"生地黄、玄参、麦冬、天冬滋阴清热；当归、丹参补血养心；人参、炙甘草补益心气；黄连清热泻火；朱砂、茯苓、远志、酸枣仁、柏子仁安养心神；五味子收敛耗散之心气；桔梗引药上行，以通心气。若肾阴亏虚，虚火妄动，遗精腰酸者，加龟甲、熟地黄、知母、黄柏，或加服知柏地黄丸；阴虚而火热不明显者，单用天王补心丹；阴虚兼有瘀热者，加赤芍、牡丹皮、桃仁、红花、郁金等。"},{"id":"s053","name":"心阳不振证","label":"4. 心阳不振证","group":"","clinic":"心悸不安，胸闷气短，动则尤甚，面色苍白，形寒肢冷，舌淡苔白，脉虚弱或沉细无力。","analysis":"心阳虚衰，无力养神，故见心悸不安；胸中阳气不足，动则耗气，故胸闷气短，动则尤甚；心阳虚衰，血液运行迟缓，肢体失于温煦，则面色苍白，形寒肢冷；舌淡苔白，脉虚弱或沉细无力，为阳虚之象。","treat":"温补心阳，安神定悸。","formulaRaw":"桂枝甘草龙骨牡蛎汤（《伤寒论》）合参附汤（《正体类要》）加减。前方温补心阳，安神定悸，后方益心气，温心阳。","formulaName":"桂枝甘草龙骨牡蛎汤合参附汤加减","fangjie":"桂枝、附子（制）温振心阳；人参益气助阳；炙甘草益气养心；龙骨、牡蛎安魂定魄，重镇安神定悸。若形寒肢冷者，重用人参、黄芪、附子（制）、肉桂温阳散寒；大汗出者，重用人参、黄芪、煅龙骨、煅牡蛎、山萸肉益气敛汗，或用独参汤煎服，以急救心阳；水饮内停者，加葶苈子、五加皮、车前子、泽泻等；夹瘀血者，加丹参、赤芍、川芎、桃仁、红花；阴伤者，重用麦冬、枸杞子，加玉竹、五味子；心阳不振，以致心动过缓者，加麻黄、补骨脂，重用桂枝。"},{"id":"s054","name":"水饮凌心证","label":"5. 水饮凌心证","group":"","clinic":"心悸眩晕，胸闷痞满，渴不欲饮，小便短少，或下肢浮肿，形寒肢冷，伴恶心欲吐，流涎，舌淡胖，苔白滑，脉弦滑或沉细而滑。","analysis":"阳虚无力化水，水饮内停，上凌于心，故见心悸；阳气虚弱，无力外达四肢肌表，则见形寒肢冷；饮停中焦，清阳不升，则见眩晕；胸阳不振，气机不利，则胸闷痞满；水饮内停，气化不利，则渴不欲饮，小便短少，下肢浮肿；水饮上逆，则恶心欲吐，流涎；舌淡胖苔白滑，脉弦滑或沉细而滑，为水饮内停之象。","treat":"振奋心阳，化气行水，宁心安神。","formulaRaw":"苓桂术甘汤（《伤寒论》）加减。","formulaName":"苓桂术甘汤加减","fangjie":"茯苓淡渗利水；桂枝、炙甘草通阳化气；白术健脾益气助阳。若恶心呕吐，加半夏、陈皮、生姜；肺气不宣，肺有痰饮，咳喘，胸闷者，加杏仁、前胡、桔梗、葶苈子、五加皮、防己；有瘀血者，加当归、川芎、泽兰、益母草；因心衰而致浮肿、尿少、夜间咳喘或端坐呼吸者，重用温阳利水之品，以真武汤加减。"},{"id":"s055","name":"瘀阻心脉证","label":"6. 瘀阻心脉证","group":"","clinic":"心悸不安，胸闷不舒，心痛时作，痛如针刺，唇甲青紫，舌质紫暗或有瘀斑，脉涩或结或代。","analysis":"心脉瘀阻，心失所养，故见心悸；气滞血瘀，胸阳不振，故见胸闷不舒；心脉痹阻，不通则痛，则心痛时作，痛如针刺；唇甲青紫，舌质紫暗或有瘀斑，脉涩或结代，为血脉瘀阻之象。","treat":"活血化瘀，理气通络。","formulaRaw":"桃仁红花煎（《陈素庵妇科补解》）加减。","formulaName":"桃仁红花煎加减","fangjie":"桃仁、红花、丹参、赤芍、川芎活血化瘀；延胡索、香附、青皮理气通脉止痛；生地黄、当归养血活血。兼气滞，加柴胡、枳壳；兼气虚，加黄芪、党参、黄精；兼血虚，加制何首乌、枸杞子、熟地黄；兼阴虚，加麦冬、玉竹、女贞子；兼阳虚，加附子（制）、肉桂、淫羊藿；络脉痹阻，胸部窒闷，加沉香、檀香、降香；胸满闷痛，苔浊腻，加瓜蒌、薤白、半夏、陈皮；胸痛甚，加乳香、没药、五灵脂、蒲黄、三七粉。"},{"id":"s056","name":"痰火扰心证","label":"7. 痰火扰心证","group":"","clinic":"心悸时发时止，受惊易作，胸闷烦躁，失眠多梦，口干口苦，大便秘结，小便短赤，舌红，苔黄腻，脉弦滑。","analysis":"脾失健运，酿生痰湿，痰浊停聚，郁久化火，痰火扰心，故见心悸时发时止；痰火扰胆，则受惊易作；痰浊阻胸，气机不利，则胸闷；火扰心神，则烦躁，失眠多梦；湿热蕴胆，胆汁外溢，则口苦口干；痰火扰胃，胃热炽盛，则大便干结，小便短赤；舌红，苔黄腻，脉弦滑，为痰火壅盛之象。","treat":"清热化痰，宁心安神。","formulaRaw":"黄连温胆汤（《六因条辨》）加减。","formulaName":"黄连温胆汤加减","fangjie":"黄连苦寒泻火，清心除烦；竹茹、半夏、陈皮清化痰热，和胃降逆；茯苓健脾祛湿；枳实下气消痰。若痰热互结，大便秘结者，加生大黄；心悸重者，加珍珠母、石决明、磁石；火郁伤阴，加麦冬、玉竹、天冬、生地黄；脾虚者，加党参、白术、谷芽、麦芽、砂仁。"}],"linchuang":["心悸应辨病与辨证相结合。功能性心律失常多由自主神经功能失常所致，临床以快速型多见，辨证多为气阴两虚、心神不安、肝气郁结，治疗以益气养阴、重镇安神、疏肝解郁为法。器质性心律失常，临床以风湿性心脏病、冠心病、病毒性心肌炎为多见。冠心病伴心律失常者以气虚血瘀为主，常用益气活血之法；风湿性心脏病伴心律失常者，以“通”为主要治则，常用活血化瘀通络之品；病毒性心肌炎伴心律失常者，在益气养阴、活血通阳基础上可酌加清热解毒之剂。缓慢型心律失常病机主要为心气虚弱，推动气血运行无力，或肾阳不足，不能助心阳搏动，治疗应以补心气、温肾阳为法。关于用药，快速型心律失常可加益母草、苦参、莲子心、延胡索等，缓慢型心律失常可加麻黄、细辛、桂枝等。","根据“久病必虚”“久病入络”的理论，心悸日久，络虚不荣，治当补益与通络并用。","心悸与西医学的心律失常有关。西医学中的各型心律失常均可参照心悸辨证论治，但须重视西医的急危重症及时处理。临床上心律失常变化往往比较迅速。一般来说，室性早搏较房性早搏病情严重，室性早搏中多源性室早、频发室早、两个室早连发以及早搏的R波落在前一个心动周期的T波上，均被认为是危险征象，必须严密观察，及时处理。室性心动过速及室性扑动是严重的心律失常，必须立即处理以防室颤。室颤是快速型心律失常中最为严重的情况，必须争分夺秒处理。"],"yufang":["预防心悸发作，要注意保持心情愉快，精神乐观，情绪稳定，避免情志刺激以及思虑过度。居住环境宜安静，避免噪声、突然性声响等不良刺激。室内空气宜清新，温度适宜，避免外邪侵袭。","心悸轻者可适当参加锻炼，调畅气机，怡神养心。久病或心阳虚弱者以休息为主，避免过劳耗伤心气。在饮食方面，虚证患者需注意加强营养，补益气血，实证患者则需根据病情有所忌食。如痰浊盛者，忌食肥甘、辛辣、酒醴等；伴有水肿者，应当限制水摄入量并低盐饮食。病势缠绵者，应坚持长期治疗，增强抗病能力。"],"attachIds":[]},{"id":"d010","name":"胸痹","kind":"main","parent":null,"chapterNo":"第十三章","chapterName":"胸痹","yinbing":[{"t":"p","x":"胸痹的发生主要是由寒邪内侵、饮食失调、情志失节、劳倦内伤、年迈体虚等引起。寒凝、痰浊、气滞、血瘀，痹阻胸阳，阻滞心脉，气虚、阴伤、阳虚，肝、脾、肾亏虚，心脉失养，引起心脉挛急滞塞而成本病。"},{"t":"b","x":"1. 寒邪内侵"},{"t":"p","x":"寒主收引，暴寒折阳，既可抑遏阳气，又可使血行瘀滞，发为胸痹。"},{"t":"p","x":"《医学正传·胃脘痛》云：“有真心痛者，大寒触犯心君。”"},{"t":"p","x":"素体阳衰，胸阳不足，阴寒之邪乘虚侵袭，寒凝气滞，痹阻胸阳，而成胸痹。"},{"t":"p","x":"《类证治裁·胸痹论治》云：“胸痹，胸中阳微不运，久则阴乘阳位，而为痹结也。”"},{"t":"b","x":"2. 饮食不节"},{"t":"p","x":"过食肥甘厚味，或嗜烟酒成癖，脾胃损伤，运化失健，聚湿生痰，上犯心胸清旷之区，阻遏心阳，胸阳失展，气机不畅，心脉痹阻，而成胸痹。"},{"t":"b","x":"3. 情志失调"},{"t":"p","x":"气滞或痰阻可使血行失畅，脉络不利，气血瘀滞，或痰瘀交阻，胸阳不运，心脉痹阻，不通则痛，而发胸痹。"},{"t":"p","x":"七情失调可致气血耗逆，心脉失畅，痹阻不通，而发心痛。"},{"t":"b","x":"4. 劳倦内伤"},{"t":"p","x":"积劳伤阳，心肾阳微，鼓动无力，胸阳失展，阴寒内侵，血行涩滞，而发胸痹。"},{"t":"b","x":"5. 年迈体虚"},{"t":"p","x":"如肾阳虚衰，可致心气不足或心阳不振，血脉失于温运，痹阻不畅，发为胸痹；心肾阳虚，阴寒痰饮乘于阳位，亦可阻滞心脉。"},{"t":"p","x":"凡此导致寒凝、血瘀、气滞、痰浊，而致胸阳失运，心脉阻滞，发生胸痹。"}],"bingji":[{"t":"p","x":"胸痹的基本病机是胸脉痹阻，在气、血、阴、阳不足或肝、脾、肾功能失调的基础上，兼有寒凝、痰浊、气滞、血瘀等阻于心脉，在寒冷刺激、饱餐、情绪激动、劳累过度等诱因的作用下，使胸阳痹阻，心脉挛急滞塞而发。"},{"t":"p","x":"病变部位主要在心，与肝、脾、肾有关。"},{"t":"p","x":"病理性质为本虚标实，虚实夹杂。"},{"t":"p","x":"本虚有气虚、气阴两虚及阳气虚损；标实有寒凝、痰浊、气滞、血瘀。"},{"t":"p","x":"胸痹的病机转化可因实致虚，亦可因虚致实。"},{"t":"p","x":"此三者皆因实致虚。"},{"t":"p","x":"此三者皆由虚而致实。"},{"t":"p","x":"胸痹反复发作，病情如若骤变，可见心胸猝然大痛，出现真心痛，甚则“旦发夕死，夕发旦死”。"}],"zhenduan":[{"t":"ol","items":["1. 胸痹以胸部闷痛甚则胸痛彻背、喘息不得卧为临床特征，疼痛性质有闷痛、灼痛、绞痛、刺痛、隐痛等不同，也可仅表现为不适感而无明显疼痛，部位较广泛，有时可窜及肩背、左上臂内侧、咽喉、胃脘部等。","2. 常突然发病，多数在劳作时即刻发生，一般持续数分钟至十余分钟不等，休息或用药后可缓解。严重者可见胸痛剧烈，持续不解，汗出肢冷，面色苍白，唇甲青紫，脉散乱或微细欲绝等危候，可发生猝死。有的时作时止，反复发作。","3. 多见于中年以上患者，常因操劳过度、抑郁恼怒、暴饮暴食或气候变化而诱发，亦有无明显诱因或安静时发病者。"]}],"jianbie":[{"t":"p","x":"胸痹应与悬饮、胃脘痛进行鉴别。"},{"t":"b","x":"1. 悬饮"},{"t":"p","x":"胸痹与悬饮都有胸痛表现，但胸痹多于劳作当时发生，或因饱餐、寒冷刺激、情绪激动等诱发，呈阵作特点，历时短暂，经休息或含服药物多可缓解，且好发于中年以上人群。"},{"t":"p","x":"悬饮则表现为胸胁胀痛，持续不解，咳唾、转侧、呼吸则诱发或加重，且多伴咳嗽、咳痰等肺系症状，可发生于任何年龄。"},{"t":"b","x":"2. 胃脘痛"},{"t":"p","x":"胸痹部位之不典型者亦可表现为胃脘部的疼痛，极易与其混淆，但胸痹多呈阵发性，且多与劳作有关，虽也有饱餐后发生者，但多伴心悸、气短等症状，而且为时短暂，休息或药物可以缓解。"},{"t":"p","x":"胃痛则多为胀痛，胃脘局部有喜按或拒按的特点，空腹或餐后均可发生，多伴有嗳气、呃逆、呕吐、泛酸、腹胀等胃系症状。"}],"bianzheng":[{"t":"b","x":"1. 辨标本虚实"},{"t":"p","x":"胸痹乃本虚标实之证，发作期多以标实为主或虚实夹杂，缓解期多以本虚为主。标实当分寒凝、痰浊、气滞、血瘀之异，本虚应别气血阴阳亏虚不同，临证可根据疼痛特点和相关伴随症加以辨别。标实中，寒凝者多绞痛难忍，尤其是感寒或寒冷季节容易发生或加重，同时伴有面色苍白、四肢较冷；痰浊者多窒闷而痛，同时伴有气短喘促、肢体困重；气滞者多闷重而痛轻，容易走窜，情志变化可诱发或加重，或兼胸胁胀满；血瘀者多呈刺痛，固定不移，夜间多发。本虚中，气虚者多见气短乏力，少气懒言，心悸，舌质淡胖或有齿痕，脉濡，或沉细，或结代；血虚者则有心悸怔忡，失眠多梦，面色淡而无华，脉细或涩；阴虚者表现为心烦，口干，盗汗，舌质红，少苔，脉细数或促；阳虚者表现为畏寒肢冷，精神倦怠，自汗，面白，舌质淡或胖，脉沉细或沉迟。"},{"t":"b","x":"2. 辨病情轻重"},{"t":"p","x":"胸痹多是慢性病变，往往反复发生，但若发作已成规律，病证特点、诱因等相对稳定，多属轻症，而首次发生或病证特点和诱因较以往有明显变化者则属重症；疼痛程度较轻，持续时间短暂，休息可缓解者，多为轻症；疼痛程度较重，甚则心痛彻背、背痛彻心，持续不解者，多为重症；症状发作时伴汗出肢冷，气不得续，唇甲青紫，甚则晕厥者，多属危重。"},{"t":"b","x":"3. 辨真心痛之顺逆"},{"t":"p","x":"真心痛乃胸痹之危候，其诊治及预后与胸痹有较大区别。凡疼痛剧烈，持续不解，伴大汗、肢冷、面白、唇紫、手足清至节、脉微或结代者，多属真心痛。舌薄白苔常见于早期或恢复期，主气虚，一般病情较轻，预后较好；腻苔多见于急性期，为痰浊明显，病情较重；黑褐苔属阴液枯竭，多属病情危笃；舌质光红为阴津欲脱，病情危重，提示预后不良；舌紫暗、有瘀斑为血瘀，且瘀血与痰浊互结；舌淡暗或兼舌体胖大有齿痕多为气虚血瘀。脉沉滑见于痰浊内阻；脉沉细见于虚寒；痛甚者脉必伏，或短，或数，或涩；急性期左寸、右尺脉常呈细弱或沉细弱之象；脉微欲绝者见于阳脱。"},{"t":"p","x":"临床上需辨识真心痛病情顺逆。如疼痛不缓解或加重，提示病情较重或进展；疼痛逐渐缓解，病情好转；病程中出现躁动不安者，病情重，预后差；不烦不躁者，预后佳；苔由薄变为厚腻，颜色由浅变深者，病情进展，多属逆证；苔由厚腻变薄，颜色由深变浅者，病情好转，多属顺证；出现心悸、喘脱并病，说明病情重，预后差。"}],"zhize":"治疗原则一般为先治其标，后治其本，先从祛邪入手，然后再予扶正，必要时可根据虚实标本的主次，兼顾同治。标实当泻，根据病邪偏盛情况，分别予以散寒、豁痰、理气、活血之法，尤重活血通脉；本虚宜补，权衡心之阴阳气血之不足，有无兼见肝、脾、肾等脏之亏虚，补气温阳，滋阴益肾，纠正脏腑阴阳气血之偏衰，尤重补益心气。注重辨清证候之危重顺逆，一旦发现脱证之先兆，必须尽早投用益气固脱之品。","syndrome":[{"id":"s057","name":"寒凝心脉证","label":"1. 寒凝心脉证","group":"","clinic":"猝然心痛如绞，心痛彻背，喘不得卧，多因气候骤冷或外感风寒而诱发或加重，伴形寒，甚则手足不温，冷汗自出，胸闷气短，心悸，面色苍白，苔薄白，脉沉紧或沉细。","analysis":"阴寒之邪侵袭，凝滞心脉，气血痹阻不通，心阳被遏，故猝然心痛如绞；心脉通于背俞，阴寒痹阻心脉，故心痛彻背；胸阳痹阻，气机不畅，肺失宣降，故喘不得卧；气候骤冷或外感风寒时，阴寒之邪更盛，加重心脉凝滞，故病情诱发或加重；阳气被寒邪所遏，不能温煦周身，故形寒、手足不温；阴寒内盛，阳气虚损，固摄失司，故冷汗自出；胸阳不振，气机阻滞，心失所养，故胸闷气短、心悸；面色苍白为阳气不能上荣之征；舌苔薄白，脉沉紧或沉细，皆为寒凝心脉之征。","treat":"辛温散寒，宣通心阳。","formulaRaw":"枳实薤白桂枝汤（《金匮要略》）合当归四逆汤（《伤寒论》）加减。前方偏重理气通阳，后方重在温经散寒。","formulaName":"枳实薤白桂枝汤合当归四逆汤加减","fangjie":"桂枝、细辛温散寒邪，通阳止痛；薤白、瓜蒌化痰通阳，行气止痛；当归、芍药养血活血；枳实、厚朴理气通脉；通草行气利水、通利血脉；甘草、大枣养脾和营。若痛无休止，身寒肢冷，气短喘息，脉沉紧或沉微者，属阴寒极盛之胸痹重症，用乌头赤石脂丸加荜茇、高良姜、细辛等。痛剧而四肢不温，冷汗自出，即刻舌下含服苏合香丸或麝香保心丸。"},{"id":"s058","name":"痰浊闭阻证","label":"2. 痰浊闭阻证","group":"","clinic":"胸闷重而心痛轻，痰多气短，头身困重，形体肥胖，遇阴雨天易发作或加重，伴有倦怠乏力，纳呆便溏，咳吐痰涎，舌体胖大，边有齿痕，苔浊腻或白滑，脉滑。","analysis":"痰浊属阴邪，重浊黏滞，盘踞胸中，痹阻胸阳，胸阳不展则气机不畅，故胸闷明显而心痛较轻；痰浊阻滞，肺气不利，故痰多气短；痰浊上蒙清窍，困遏肢体，故头身困重；痰湿郁于腠理，津液输布失常，膏脂堆积，故形体肥胖；阴雨天湿气偏盛，易与体内痰浊相结，加重痹阻，故病情易发作或加重；痰浊困脾，脾失健运，清阳不升，故倦怠乏力、纳呆便溏；痰浊蕴肺，肺失宣降，故咳吐痰涎；舌体胖大，边有齿痕，苔浊腻或白滑，脉滑，皆为痰浊闭阻之征。","treat":"通阳泄浊，豁痰宣痹。","formulaRaw":"栝蒌薤白半夏汤（《金匮要略》）合涤痰汤（《奇效良方》）加减。前方偏于通阳行气，后方偏于健脾豁痰。","formulaName":"栝蒌薤白半夏汤合涤痰汤加减","fangjie":"瓜蒌、薤白化痰通阳，行气止痛；半夏、胆南星燥湿化痰；竹茹清化痰热；人参、茯苓、甘草健脾益气；石菖蒲、陈皮、枳实理气宽胸。有痰热者，加海浮石、海蛤壳、栀子、天竺黄、竹沥；大便干结，加桃仁、番泻叶、大黄。若口干口苦，为痰浊郁而化热，可选黄连温胆汤加郁金。"},{"id":"s059","name":"气滞心胸证","label":"3. 气滞心胸证","group":"","clinic":"心胸满闷，隐痛阵发，时欲太息，遇情志不遂时容易被诱发或加重，或兼有胸胁胀满，得嗳气或矢气则舒，苔薄或薄腻，脉细弦。","analysis":"肝失疏泄，气机郁滞，心脉挛急，故见心胸满闷、隐痛阵发；肝气郁结，欲求疏泄，则时欲太息；情志不遂时肝失疏泄更甚，气机郁滞加重，故病情易诱发或加重；肝脉循行于胸胁，气机郁滞，则胸胁胀满；嗳气或矢气可使郁滞之气暂时得以宣泄，故感觉稍舒；苔薄或薄腻，脉细弦，为气滞心胸之征。","treat":"疏肝理气，活血通络。","formulaRaw":"柴胡疏肝散（《景岳全书》）加减。","formulaName":"柴胡疏肝散加减","fangjie":"柴胡、枳壳疏肝理气；香附、陈皮理气解郁；川芎、白芍活血通脉；甘草和中。若胸闷心痛明显，兼有血瘀，合用失笑散，加丹参、薤白、苏木；便秘严重，加当归龙荟丸。心烦易怒，口干便秘，舌红苔黄，脉弦数者，为气郁化火，选丹栀逍遥散加减。"},{"id":"s060","name":"心血瘀阻证","label":"4. 心血瘀阻证","group":"","clinic":"心胸疼痛，如刺如绞，痛有定处，入夜为甚，甚则心痛彻背，背痛彻心，或痛引肩背，舌质紫暗或有瘀点、瘀斑，苔薄，脉弦涩。","analysis":"瘀血痹阻心脉，络脉不通，不通则痛，故见心胸疼痛，如刺如绞；瘀血有形，故痛有定处；血属阴，人夜阴盛，瘀血更甚，故入夜为甚；心之络脉支脉布两肩，通于背俞，瘀血阻滞心之脉络，故心痛彻背，背痛彻心，或痛引肩背；舌质紫暗或有瘀点、瘀斑，脉弦涩，皆为心血瘀阻之征。","treat":"活血化瘀，通脉止痛。","formulaRaw":"血府逐瘀汤（《医林改错》）加减。","formulaName":"血府逐瘀汤加减","fangjie":"川芎、桃仁、红花、赤芍活血化瘀，和营通脉；柴胡、桔梗、枳壳、牛膝调畅气机，行气活血；当归、生地黄补养阴血；甘草调和诸药。若胸痛剧烈，瘀血痹阻较重，加乳香、没药、丹参等；畏寒肢冷，兼有寒凝或阳虚，加肉桂、细辛、高良姜、薤白，或人参、附子（制）等。气短、乏力、自汗，兼有气虚者，可选用人参养荣汤合桃红四物汤加减，重用人参、黄芪。猝然心痛发作，可含服复方丹参滴丸、速效救心丸。"},{"id":"s061","name":"气阴两虚证","label":"5. 气阴两虚证","group":"","clinic":"心胸隐痛，时作时止，心悸气短，动则尤甚，伴神疲懒言，易汗，舌质淡红，舌体胖，边有齿痕，苔薄白，脉虚细缓或结代。","analysis":"气阴两虚，心气不足则推动血行无力，阴血亏耗则脉络失于濡养，均可致血行不畅，故心胸隐痛，时作时止；心气亏虚，心脉失养，故心悸气短，且活动时耗气更甚，症状加重；气虚不能推动精微物质输布，清阳不升，神明失养，故神疲懒言；气虚卫外不固，故易汗出；舌质淡红，舌体胖，边有齿痕，苔薄白，脉虚细缓或脉结代，为气阴两虚之征。","treat":"益气养阴，活血通脉。","formulaRaw":"生脉散（《医学启源》）合人参养荣汤（《太平惠民和剂局方》）加减。前方长于益气养阴，后方重在补气养血。","formulaName":"生脉散合人参养荣汤加减","fangjie":"人参、黄芪、甘草大补元气；肉桂温通心阳；麦冬、五味子滋养心阴，收敛心气；熟地黄、白芍、当归养血活血；陈皮、茯苓、白术健脾渗湿；远志安神益智；甘草和中。若胸闷、胁胀，兼有气滞血瘀者，加川芎、郁金；脘闷纳呆，舌苔白腻，痰浊明显者，加白蔻仁、胆南星、苍术；纳呆，失眠，兼有心脾两虚者，加茯神、半夏曲、柏子仁、酸枣仁。"},{"id":"s062","name":"心肾阴虚证","label":"6. 心肾阴虚证","group":"","clinic":"心痛憋闷，心悸盗汗，虚烦不寐，腰膝酸软，头晕耳鸣，口干便秘，舌红少津，苔薄或剥，脉细数或促代。","analysis":"心肾阴虚，水不济火，虚热内灼，耗伤津液，血行不畅，心脉失养，故心痛憋闷；阴虚内热扰动心神，故心悸；虚热迫津外泄，故盗汗；虚热扰心，心神不宁，故虚烦不寐；肾阴亏虚，腰膝失养，故腰酸膝软；肾精不足，髓海空虚，故头晕耳鸣；阴虚内热，耗伤津液，肠道失润，故口干便秘；舌红少津，苔薄或剥，脉细数或促代，为心肾阴虚之征。","treat":"滋阴清火，养心和络。","formulaRaw":"天王补心丹（《校注妇人良方》）合炙甘草汤（《伤寒论》）加减。前方偏重养心安神，后方重在养阴复脉。","formulaName":"天王补心丹合炙甘草汤加减","fangjie":"生地黄、玄参、天冬、麦冬滋水养阴，以降虚火；人参、甘草、大枣益心气，补脾气；桔梗载药上行；茯苓、远志交通心肾；柏子仁、酸枣仁、五味子敛心气，安心神；丹参、当归、火麻仁、阿胶、桂枝滋养心血，温通心脉。若头晕目眩，腰酸膝软，遗精盗汗，心悸不宁，口燥咽干，心肾阴虚较甚者，用左归饮；虚烦不寐，舌尖红少津者，为阴不敛阳，虚火扰心，用酸枣仁汤加减；头晕肢颤，风阳上扰者，合黄连阿胶汤或加珍珠母、灵磁石、石决明、琥珀等。"},{"id":"s063","name":"心肾阳虚证","label":"7. 心肾阳虚证","group":"","clinic":"心悸而痛，胸闷气短，动则尤甚，自汗，面色㿠白，四肢欠温或肿胀，神倦怯寒，舌质淡胖，边有齿痕，苔白或腻，脉沉细迟。","analysis":"心肾阳虚，阳气虚弱，则胸阳不振，气机痹阻，血行瘀滞，心脉失养，故心悸而痛、胸闷气短；活动时耗气更甚，阳气益虚，故动则尤甚；阳气虚不能固摄津液，故自汗；阳虚不能温煦肌肤，气血不能上荣，故面色㿠白、四肢欠温；阳虚水湿不化，泛溢肢体，故四肢肿胀；阳气亏虚，神机失用，故神倦怯寒；舌质淡胖，边有齿痕，苔白或腻，脉沉细迟，为心肾阳虚之征。","treat":"温补阳气，振奋心阳。","formulaRaw":"参附汤（《正体类要》）合右归饮（《景岳全书》）加减。前方重在温补心阳，后方重在温肾助阳。","formulaName":"参附汤合右归饮加减","fangjie":"人参大补元气；附子（制）温补真阳；肉桂振奋心阳；甘草益气复脉；熟地黄、山萸肉、杜仲、枸杞、山药滋阴益肾，阴中求阳；酌加淫羊藿、补骨脂温养肾气。若兼见水肿、喘促、心悸者，为肾阳虚衰，水饮凌心，用真武汤加黄芪、汉防己、猪苓、车前子；阳虚欲脱，四肢厥逆者，为急危重症，在中西医结合抢救的同时，用四逆加人参汤，或参附注射液静脉滴注。"}],"linchuang":["治疗应以通为补，通补结合。胸痹病机为本虚标实。临床治疗应以通为补，其通法包括：芳香温通法，如苏合香丸、冠心苏合丸、速效救心丸、麝香保心丸、复方丹参滴丸等；宣痹通阳法，如枳实薤白桂枝汤、乌头赤石脂丸等；活血化瘀法，如血府逐瘀汤、失笑散、复方丹参滴丸、冠心Ⅱ号方等，临证可加养血活血药，如鸡血藤、益母草、当归等，活血而不伤正；祛痰开郁法，如栝蒌薤白半夏汤、温胆汤加胆南星、石菖蒲、郁金等。补法包括：补气血，选用八珍汤、当归补血汤等；温肾阳选加仙茅、淫羊藿等；补肾阴选加首乌延寿丹、左归丸等。通与补是治疗胸痹不可分割的两大原则，应通补结合，交替应用。","活血化瘀法的配伍应用。胸痹瘀血多表现为气虚血瘀、痰瘀交阻、气滞血瘀等夹杂证，临床治疗应注意在活血化瘀中伍以益气、养阴、养血、理气之品，辨证用药，以加强祛瘀疗效。临床主要选用养血活血之品，如丹参、鸡血藤、当归、赤芍、郁金、川芎、红花、泽兰、牛膝、三七、益母草等。破血攻伐之品，虽有止痛作用，但易伤正气，应慎用，若必用，切不可久用、多用，痛止后须扶正养营，方可巩固疗效。如有出血倾向或征象，应立即停用，并予以相应处理。","芳香温通法的应用。寒邪内闭是导致胸痹发作的重要病机之一，临床以芳香走窜、温通行气类中药治疗胸痹源远流长，如桂心、干姜、吴茱萸、麝香、细辛、蜀椒、丁香、木香、安息香、苏合香等。实验研究证实，芳香温通类药大多含有挥发油，可解除冠脉痉挛，增加冠脉流量，减小心肌耗氧量，改善心肌供血，同时对血液流变性、心肌收缩力均有良好的影响。","临床转归预后。胸痹心痛病程较长，易反复发作。病之初多以实证为主，寒凝、痰浊、气滞、血瘀之间相互影响；在实证形成的过程中，则气、血、阴、阳渐虚，常交互出现，逐渐加重。若及时治疗，标本兼顾，去除诱因，可稳定病情，控制疾病的发展。若病情进一步进展，可致心脉痹阻，心胸猝然大痛，而发为真心痛；若心肾阳虚，水邪泛滥，凌心射肺，可见喘脱之危候，常危及生命。","真心痛急症的治疗。真心痛是胸痹进一步发展的严重病证，特点为剧烈而持久的胸骨后疼痛，伴心悸、水肿、肢冷、喘促、汗出、面色苍白等症状，可危及生命。常因寒凝气滞、血瘀痰浊痹阻心脉，心脉不通，出现心胸疼痛（心绞痛），甚至真心痛（心肌梗死）。若心气不足，运血无力，心脉瘀阻，心血亏虚，气血运行不利，可见心动悸，脉结代（心律失常）；若心肾阳虚，水邪泛滥，水饮凌心射肺，可出现心悸、水肿、喘促（心力衰竭）；进一步发展，或亡阳厥脱，或亡阴厥脱，或阴阳俱厥，最后导致阴阳离决。真心痛的病位在心，其本在肾，为本虚标实之证，急性期则尤以标实为主。真心痛患者病情危重，应立即卧床休息，给予患者心电、血压、呼吸及血氧饱和度监测，低流量给氧，保持情绪稳定，清淡饮食，保持大便通畅。在发作期须使用具有速效止痛作用的药物，可选舌下含服复方丹参滴丸、速效救心丸、麝香保心丸等，或宽胸气雾剂口腔喷雾给药。溶栓或经皮冠状动脉介入治疗（PCI），使闭塞冠脉再通，恢复心肌血流灌注，是当今治疗真心痛最有效的方法。疼痛缓解后予以辨证施治，常以补气活血、温阳通脉为法，可与胸痹辨证互参。可选用中药静脉滴注，如丹红注射液、丹参酮ⅡA磺酸钠注射液、注射用红花黄色素等，现代药理研究表明其具有保护血管内皮、抗血小板聚集作用，通过改善心肌能量代谢，减轻心肌缺血再灌注损伤。心脏康复可以改善真心痛患者远期预后，除中药汤剂及中成药外，还可通过八段锦、太极拳、针刺等方式，缓解患者临床症状，改善心功能，提高生活质量，降低再入院率。"],"yufang":["注意调摄精神，避免情绪波动。防治本病必须高度重视精神调摄，避免过于激动或喜怒忧思无度，保持心情平静、愉快，同时要多与患者沟通，使其明确焦虑、恐惧、紧张等不良情绪对疾病的影响，帮助患者树立战胜疾病的信心，提高疗效。注意生活起居，避免寒冷，居处除保持安静、通风外，还要注意寒温适宜，保证患者充分休息，避免过度劳累和环境嘈杂等不良因素的影响。同时应指导患者养成良好的睡眠习惯，如就寝前不做剧烈活动，避免过度兴奋等，做到生活有规律，劳逸结合，避免从事持续时间过长、注意力高度集中的工作。","胸痹患者应注意饮食调节，宜清淡低盐，食勿过饱，忌辛辣、肥腻等食物，多吃水果及富含纤维素的食物，保持大便通畅。晚餐不宜过饱，睡前不宜饮用浓茶、咖啡等饮品，可饮适量牛奶。戒烟限酒。在劳逸结合的基础上，坚持适度活动，如练太极拳、八段锦等，以增强体质，避免过度耗气。发作期患者应立即卧床休息，缓解期要注意适当休息，保证充足的睡眠，坚持力所能及的活动，做到动中有静。此外，发作期需密切监测患者心率（律）、血压、呼吸及胸痛性质、持续时间等变化；缓解期也应注意心率（律）、血压及胸痛情况，警惕病情反复或加重。"],"attachIds":[]},{"id":"d011","name":"心衰","kind":"main","parent":null,"chapterNo":"第十四章","chapterName":"心衰","yinbing":[{"t":"p","x":"心衰的发生，多因各种心系疾患，日渐加重，心气亏耗，又因复感外邪、情志刺激或劳倦过度，内外相因，心体受戕，心气、心阴、心阳渐次虚衰，行血无力，血脉瘀滞，痰浊内阻，水饮停聚，而成本病。"},{"t":"b","x":"1. 久病耗心"},{"t":"p","x":"心系疾病反复发作，迁延日久不愈，损及心之体用，或血脉瘀阻，心体失荣，或外邪留伏，中伤心体，或劳倦内伤，心气耗散，诸内外因均可致心之体用俱损，心气、心阴、心阳虚耗，心血瘀阻，痰浊内阻，水饮内停，发为心衰。"},{"t":"b","x":"2. 感受外邪"},{"t":"p","x":"外邪侵袭，肺失宣降，治节失司，通调失职，不能助心行血，血脉瘀滞，水饮内停，发为心衰。"},{"t":"p","x":"痹证日久，内舍于心，心脉痹阻，久则心衰。"},{"t":"p","x":"疫病之邪犯心，心体受损，心气耗伤，而致心衰。"},{"t":"p","x":"叶天士《温热论》云：“温邪上受，首先犯肺，逆传心包。”"},{"t":"b","x":"3. 情志失调"},{"t":"p","x":"气血运行受遏，心脉痹阻，心体失养，瘀血、痰浊、水饮内生，导致心衰日渐加重。"},{"t":"b","x":"4. 劳倦内伤"},{"t":"p","x":"劳倦内伤是心衰加重的关键诱因。"},{"t":"p","x":"劳倦伤脾，或房劳伤肾，进而心体失养，心气内耗，阴阳虚衰，引起瘀血、痰浊、水饮等停聚，导致心衰加重。"},{"t":"p","x":"《素问·举痛论》云：“劳则喘息汗出，外内皆越，故气耗矣。”"}],"bingji":[{"t":"p","x":"心衰的基本病机为心之气血阴阳亏损，血脉瘀阻，痰浊内阻，水饮停聚。"},{"t":"p","x":"病变部位在心，累及肺、脾、肾、肝。"},{"t":"p","x":"心衰病理性质为本虚标实，虚实夹杂，以虚为主。"},{"t":"p","x":"本虚主要为气虚、气阴两虚及阳气亏虚；标实主要为瘀血、痰浊、水饮。"},{"t":"p","x":"本虚是心衰的基本病机，决定心衰的发展趋势；标实是心衰的演化病机，影响心衰的病情变化。"},{"t":"p","x":"本虚和标实的病机转化决定了心衰的发展演变。"},{"t":"p","x":"总之，心衰的病机关键可用虚、瘀、痰、水四者概括，虚实之间可相互转化。"},{"t":"p","x":"早期主要为心肺气虚，行血无力，瘀血阻滞；中期因气虚难复，痰瘀积久，化赤生新不足，脏腑失荣，而呈气阴两虚之势，或气损及阳，心阳亏虚，瘀血加甚；后期阴损及阳，阳损及阴，阴阳互损，瘀血、痰浊、水饮等病理产物内聚，虚、痰、瘀、水恶性循环，虚实夹杂。"},{"t":"p","x":"心气虚衰是基础，逐渐发展为气阴两虚或心阳亏虚，进而导致阴阳两虚，甚至阴阳离决，出现危证。"},{"t":"p","x":"血瘀作为中心病理环节贯穿始终，痰浊和水饮是主要病理产物。"},{"t":"p","x":"《金匮要略·水气病脉证并治》云：“血不利则为水。”"},{"t":"p","x":"瘀、痰、饮三者相互胶结，整个病情随着心之气血阴阳的日渐虚衰而进展，随瘀血、痰浊、水饮的内聚而日渐加重。"}],"zhenduan":[{"t":"ol","items":["1. 心衰以乏力、心悸、气喘、肢体水肿等为主要临床特征。轻者可仅表现为气短、乏力，重者可见喘促心悸，不能平卧，或伴咳痰，尿少肢肿，或口唇发绀，胁下痞块，颈脉显露，甚至出现喘悸不休、汗出肢冷、表情淡漠或烦躁不安等厥脱危象。","2. 心衰患者常有心系疾患病史多年，时轻时重，经久难愈。","3. 心衰多见于中老年人，常因外感、劳倦、情志刺激等诱发或加重。"]}],"jianbie":[{"t":"b","x":"1. 喘证"},{"t":"p","x":"心衰和喘证均可见喘促气短的临床表现。"},{"t":"p","x":"但心衰因久患心系疾病而致，发作时除喘促外，可伴见心悸、浮肿、尿少等表现；喘证多由外感诱发而加重，为肺系疾病，实者起病急，多兼表证，虚者常反复发作，遇劳尤甚，平素亦可见气怯声低、脉弱等肺肾气虚之证，多伴咳嗽咳痰及不同程度的呼吸困难。"},{"t":"b","x":"2. 鼓胀"},{"t":"p","x":"心衰后期可出现胁下痞块坚硬或颈脉显露等瘀血阻滞之症，与鼓胀类似。"},{"t":"p","x":"但心衰病位在心，常伴喘促不能平卧、心悸、四肢水肿等症；鼓胀是气、血、水结于腹中，以腹大、肢细、腹壁脉络显露为临床特征，病在肝脾，晚期伴肢体浮肿和尿少等症。"},{"t":"p","x":"《金匮要略·水气病脉证并治》谓：“肝水者，其腹大，不能自转侧。”"},{"t":"b","x":"3. 水肿"},{"t":"p","x":"心衰后期可见浮肿、尿少等水饮内停之症，与水肿类似。"},{"t":"p","x":"但心衰病位在心，可累及肺、脾、肝、肾，水肿以肢体低垂部位为甚，兼有喘促、心悸等症。"},{"t":"p","x":"水肿是因肺、脾、肾功能失调，全身气化功能障碍，而致水湿泛溢，“肺水”“脾水”“肾水”可兼见，以身肿、腹大、小便难为主要症状，其肿多从眼睑或下肢开始，继及全身，皮肤光亮或按之如泥，病轻者无喘促、心悸表现，后期水凌心肺才并见喘、悸之症。"}],"bianzheng":[{"t":"b","x":"1. 辨轻重缓急"},{"t":"p","x":"轻者仅表现为气短、乏力，重者则可见喘息，心悸，不能平卧，尿少，肢肿，口唇发绀，甚至喘悸不休、汗出肢冷、表情淡漠或烦躁不安等危象。"},{"t":"b","x":"2. 辨标本虚实"},{"t":"p","x":"心衰的病位在心，属本虚标实之证，以心之气血阴阳虚衰为本，痰、瘀、水停聚为标，病理演变可从心、肺渐及脾、肾，并逐步损阴伤阳，但终以心虚为主。本虚需辨气血、阴、阳及脏腑之异，标实需明瘀血、痰浊的程度和饮邪的有无。随病情进展可渐次出现“瘀久成积”和“瘀血化水”的标实重症。"}],"zhize":"心衰的治疗原则为补虚泻实，常以益气、养阴、温阳、活血、化痰、利水为基本治法。根据邪正关系，权衡缓急，或补或攻，或攻补兼施。临床可结合病期随证治之，急性加重期多表现为本虚不支，标实邪盛，甚至阴竭阳脱，既要积极固护气、血、阴、阳以治本，更需加强活血、化痰、利水、解表、清热以治标，必要时回阳固脱；稳定期多以本虚为著，标实不甚，应以益气、养阴或温阳扶正为主，兼以活血化瘀、化痰利水以治标。","syndrome":[{"id":"s064","name":"气虚血瘀证","label":"1. 气虚血瘀证","group":"","clinic":"胸闷气短，喘息，心悸，活动后诱发或加重，神疲乏力，倦怠懒言，自汗，口唇发绀，或胸部闷痛，或肢肿时作，喘息不得卧，舌淡胖或淡暗，有瘀斑，脉沉细或涩、结、代。","analysis":"心气亏虚，胸阳不振，故胸闷气短、心悸；劳则气耗，故活动后加剧；气虚失于充养，故乏力懒言；气虚卫外不固，故自汗；血行瘀滞，故唇绀、胸闷；气化不利，水饮内停，甚或水饮凌心，故肢肿、喘息。舌淡胖或淡暗，有瘀斑，脉沉细或涩、结、代，皆为气虚血瘀之征。","treat":"益气温阳，活血祛瘀。","formulaRaw":"保元汤（《博爱心鉴》）合血府逐瘀汤（《医林改错》）加减。前方以补气温阳为主，后方重在活血行气。","formulaName":"保元汤合血府逐瘀汤加减","fangjie":"人参、黄芪补益元气，养心定悸；肉桂温通心阳；桃仁、红花、川芎、赤芍、牛膝活血化瘀；当归、生地黄养血和血；柴胡、枳壳、桔梗行气解郁；炙甘草顾护中焦，并调和诸药。气虚甚者，重用黄芪；血瘀阻络者，加丹参、三七、地龙、水蛭等；痰浊甚者，加瓜蒌、薤白、半夏、茯苓、陈皮等；痰热盛者，合用小陷胸汤、黄连温胆汤；水饮重者，加葶苈子、防己、茯苓皮、泽泻、车前子、大腹皮、五加皮等。"},{"id":"s065","name":"气阴两虚证","label":"2. 气阴两虚证","group":"","clinic":"胸闷气短，喘息，心悸，活动后诱发或加剧，神疲乏力，易汗，口干，五心烦热，两颧潮红，或胸痛入夜尤甚，或伴腰膝酸软，头晕耳鸣，舌暗红少苔或少津，脉细数无力或结、代。","analysis":"心气不足，心阴亏虚，濡养失司，故胸闷气短、心悸、神疲乏力、易汗；阴虚内热，故烦热颧红；津液亏耗，不能上承，故口干；肾阴不足，骨髓失养，故腰酸耳鸣；舌暗红少苔或少津，脉细数无力或结、代，为气阴两虚兼血瘀之征。","treat":"益气养阴，活血通脉。","formulaRaw":"生脉散（《医学启源》）合血府逐瘀汤（《医林改错》）加减。前方以益气养阴为主，后方重在活血行气。","formulaName":"生脉散合血府逐瘀汤加减","fangjie":"人参大补元气；麦冬养阴生津；五味子敛阴止汗；桃仁、红花、川芎、赤芍、牛膝活血化瘀；当归、生地黄养血和血；枳壳、柴胡、桔梗行气解郁；炙甘草调和诸药。若偏于阴虚者，加二至丸、黄精、石斛、玉竹等；内热明显或由外感诱发者，加连翘、白花蛇舌草、重楼等；肺热壅盛，咳吐黄痰者，合清金化痰汤或越婢加半夏汤。"},{"id":"s066","name":"阳虚水泛证","label":"3. 阳虚水泛证","group":"","clinic":"心悸，喘息不得卧，面浮肢肿，尿少，神疲乏力，畏寒肢冷，腹胀，便溏，口唇发绀，胸部刺痛，或胁下痞块坚硬，颈脉显露，舌淡胖，有齿痕，或有瘀点、瘀斑，脉沉细或结代、促。","analysis":"心阳不振，水饮上泛，凌心射肺，故心悸、喘息不得卧；阳虚气化不利，水饮泛溢，故尿少肢肿；阳虚温煦失司，故畏寒肢冷；脾阳虚衰，故腹胀便溏；血水同病，瘀血内停，故唇绀，胸痛，胁下痞硬，颈脉显露；舌淡胖，有齿痕，或有瘀点、瘀斑，脉沉细或结代、促，皆为阳虚水泛兼血瘀之征。","treat":"益气温阳，活血利水。","formulaRaw":"真武汤（《伤寒论》）合葶苈大枣泻肺汤（《金匮要略》）加减。前方偏重温阳利水，后方偏重泻肺行水。","formulaName":"真武汤合葶苈大枣泻肺汤加减","fangjie":"附子（制）、生姜温阳通脉，助阳化气；白术、茯苓益气健脾，渗湿利水；芍药活血利水；葶苈子泻肺行水；大枣甘缓补中。若饮邪暴盛，泛溢肌肤者，加猪苓、泽泻、椒目、防己、香加皮、大腹皮等；畏寒肢冷、腰膝酸软等中虚脏寒明显者，加仙茅、淫羊藿、鹿角霜等；胁下痞块坚硬，乃血瘀日久，积块已成，加丹参、川芎、鳖甲煎丸。"},{"id":"s067","name":"喘脱危证","label":"4. 喘脱危证","group":"","clinic":"喘悸不休，不能平卧，面色晦暗，表情淡漠，或烦躁不安，大汗淋漓，或额汗如油，四肢厥冷，尿少肢肿，舌淡苔白，脉微细欲绝或疾数无力。","analysis":"心肾阳衰，肺气欲绝，故见喘悸不休，不能平卧，面色晦暗；阴竭阳脱，故见表情淡漠，或烦躁不安，大汗淋漓，或额汗如油；阳脱不能气化温煦，故见肢冷尿少；舌淡苔白，脉微细欲绝或疾数无力，均为阴阳将欲离决之危征。","treat":"益气回阳固脱。","formulaRaw":"四逆加人参汤（《伤寒论》）。","formulaName":"四逆加人参汤","fangjie":"人参大补元气，复脉固脱；附子（制）温阳通脉，回阳救逆；炙甘草、干姜鼓舞心阳，顾护中焦。若大汗不止、下利无度者，加山茱萸、五味子；若肢冷如冰，为阳虚暴脱危象，急用参附注射液输注。"}],"linchuang":["益气活血法贯穿始终。心之气血阴阳亏虚为心衰之本，血瘀、痰浊、水饮等标实证多得之于本虚。《医林改错·论小儿抽风不是风》云：“元气既虚，必不能达于血管，血管无气，必停留而瘀。”水之行止，亦听命于气，气为血之帅，血为气之母，血脉瘀滞，水津外泄，发为水肿。血瘀和气虚均会影响水液运行而致水停留饮，导致疾病进展。水饮、血瘀日久又进一步损伤心阳，而使虚者更虚，实者更实，形成恶性循环。因此，气虚血瘀往往贯穿疾病始终，防治本病应以益气活血法为主，随证变通。","扶正养阴需要重视。《素问·阴阳应象大论》云：“年四十而阴气自半也。”心衰多发于中老年人，阴虚是该年龄段患者的常态。心生血，心气亏虚，无以奉心化赤，则新血难生，脏腑失荣；加之治疗过程每以利水大剂，加剧伤阴耗液。阴血为物质基础，《景岳全书·新方八阵·补略》云：“善补阳者，必于阴中求阳，则阳得阴助而生化无穷。”可见兼顾阴津是心阳得复的重要前提，治疗当重视养阴。","遣方用药当病证结合。心衰是多种慢性心系疾病反复发作，迁延不愈，日渐加重的终末期阶段。不同疾病导致的心衰有不同的演变规律和用药特点。胸痹引起的心衰常因心脉痹阻而出现胸痛时作，在辨证用药基础上，可酌情加入桂枝、降香、檀香、细辛等芳香温通之品；喘证、肺胀引起的心衰常因感受外邪诱发或加重，辨证时要注重祛邪；由痹证内舍脏腑发展为心痹进而发生的心衰，常有风、寒、湿邪留伏，应酌情加入威灵仙、豨签草、桑寄生等祛风除湿之品。","早期识别心衰，既病防变。既往认为喘、悸、肿是心衰的三大共性特征，但部分患者起病隐匿，病情初起之时临床特征不典型，仅表现为活动后气短、心悸、纳差、乏力、疲惫等轻症，早期准确识别心衰，积极控制病情，才能既病防变，阻遏疾病进展。"],"yufang":["心衰是多种慢性心系疾病的终末期阶段，患有其他心系疾病（如胸痹、心悸等）但尚无心衰表现的高危人群，应积极治疗心系疾病，预防其发展为心衰。心衰常因感受外邪、情志过极或劳倦过度等因素诱发或加重，故应调摄精神，避免情绪过激，保持心情平和；冬春季节交替，气候骤变时注意增减衣服，佩戴口罩，预防感冒；同时需劳逸适度，避免过度劳累造成心气骤然耗散。","心衰患者平素应饮食清淡，不过食咸味及膏粱之品，适当控制饮水量，戒烟限酒，并可适度运动，循序渐进，减少久坐，选择散步、太极拳、五禽戏等锻炼方式，以提高身体素质。做到勤监测（血压、心率、体重、呼吸、尿量）、慢调理、长维持，促使病情长期稳定。"],"attachIds":[]},{"id":"d012","name":"不寐","kind":"main","parent":null,"chapterNo":"第十五章","chapterName":"不寐","yinbing":[{"t":"b","x":"1. 饮食不节"},{"t":"p","x":"暴饮暴食，宿食停滞，脾胃受损，酿生痰热，壅遏于中，痰热上扰，胃气失和，而不得安寐；或脾运失健，气血生化不足，心失所养而不寐。"},{"t":"p","x":"此外，浓茶、咖啡、酒类等刺激性饮品亦可造成不寐。"},{"t":"p","x":"《张氏医通·不得卧》云：“脉数滑有力不眠者，中有宿滞痰火，此为胃不和则卧不安也。”"},{"t":"b","x":"2. 情志失常"},{"t":"p","x":"情志不遂，郁怒伤肝，肝气郁结，气郁化火，邪火扰动心神，神不安而不寐；或五志过极，心火内炽，扰动心神而不寐；或喜笑无度，心气涣散而不寐；或心虚胆怯，暴受惊恐，神魂不安，夜不能寐；或忧思伤脾，气血亏虚而不寐。"},{"t":"p","x":"《沈氏尊生书·不寐》云：“心胆俱怯，触事易惊，梦多不祥，虚烦不眠。”"},{"t":"p","x":"《类证治裁·不寐》曰：“思虑伤脾，脾血亏损，经年不寐。”"},{"t":"b","x":"3. 劳逸失调"},{"t":"p","x":"劳倦太过、过逸少动则伤及心脾，心伤则阴血暗耗，神不守舍；脾伤则食少纳呆，生化之源不足，营血亏虚，不能上奉于心，致心神失养而不寐。"},{"t":"p","x":"《景岳全书·不寐》云：“劳倦、思虑太过者，必致血液耗亡，神魂无主，所以不寐。”"},{"t":"b","x":"4. 病后体虚"},{"t":"p","x":"久病血虚，年迈血少，心血不足，心失所养，心神不安而不寐；亦可因年迈体虚，阴阳亏虚而致不寐；或素体阴虚，兼房劳过度，肾阴耗伤，阴衰于下，不能上奉于心，水火不济，心火独亢，火扰心神，心肾失交而不寐。"},{"t":"p","x":"正如《景岳全书·不寐》所说：“总属其阴精血之不足，阴阳不交，而神有不安其室耳。”“无邪而不寐者，必营气之不足也，营主血，血虚则无以养心，心虚则神不守舍。”"}],"bingji":[{"t":"p","x":"不寐的基本病机是阳盛阴衰，阴阳失交，一为阴虚不能纳阳，一为阳盛不得入阴。"},{"t":"p","x":"病变部位主要在心，与肝、胆、脾、胃、肾关系密切。"},{"t":"p","x":"饮食不节、思虑劳倦等伤及脾胃诸脏，精血内耗，心神失养，神不内守，阳不入阴，每致不寐。"},{"t":"p","x":"心虚胆怯，神魂不安，或暴饮暴食，食积胃脘，胃气不和，均可致不寐。"},{"t":"p","x":"病理性质有虚实之分。"},{"t":"p","x":"肝郁化火，或痰热内扰，邪扰心神，多属实证。"},{"t":"p","x":"心脾两虚，气血不足，或心胆气虚，或心肾不交，水火不济，心神失养，神不安宁，多属虚证。"},{"t":"p","x":"病久可致虚实兼夹，或兼血瘀。"},{"t":"p","x":"病理因素有肝火、痰热、瘀血。"},{"t":"p","x":"如肝郁化火证，易伤阴耗气，则由实转虚；心脾两虚，遇饮食不当，脾胃受戕，气血愈虚，食积内停，而见虚实夹杂；如温燥太过，易致阴虚火旺；属心肾不交，可进一步发展为心火独亢，肾水更虚之证。"},{"t":"p","x":"不寐的预后大多良好。"},{"t":"p","x":"如病因不除或治疗不当，易产生情志病变，使病情复杂，少部分不寐可转成郁证或癫证甚至狂证。"}],"zhenduan":[{"t":"ol","items":["1. 轻者入寐困难或寐而易醒，醒后不寐，重者彻夜难眠。","2. 常伴有多梦、心烦、心悸、健忘、头痛、头昏、神疲乏力等症状，并影响日间功能。","3. 本病证常有饮食不节、情志失常、劳逸失调、病后体虚等病史。","4. 排除睡眠呼吸紊乱、精神障碍等妨碍睡眠的病变和诱因。"]}],"jianbie":[{"t":"b","x":"1. 一过性失眠"},{"t":"p","x":"一过性失眠在日常生活中常见，可因一时性情志不舒、居住环境改变，或因饮用浓茶、咖啡和服用药物等导致。"},{"t":"p","x":"一般有明显诱因，且病程不长。"},{"t":"p","x":"一过性失眠不属病态，一般不需要任何治疗，可通过身体自然调节而恢复正常。"},{"t":"b","x":"2. 生理性少寐"},{"t":"p","x":"生理性少寐多见于老年人，虽少寐早醒，但无明显自觉痛苦或功能障碍，属生理现象。"}],"bianzheng":[{"t":"b","x":"1. 辨虚实"},{"t":"p","x":"不寐首先应辨虚实。本病轻者仅有少眠或不眠，病程短，以实证为主。重者则彻夜不眠，病程长，易反复发作，多以虚证或虚实夹杂为主。实证多为邪热扰心，心神不安。如心烦易怒，不寐多梦，兼见口苦咽干，便秘溲赤，为肝火扰心；如心烦不寐，痰多，胸闷脘痞，泛恶嗳气，头重目眩，为痰热扰心。虚证多为阴血不足，心失所养。虽能入睡，但睡间易醒，醒后不易再睡，兼见体质瘦弱，面色无华，神疲懒言，心悸健忘，多属心脾两虚；如心烦失眠，不易入睡，兼见心悸，五心烦热，潮热，多属心肾不交；如入睡后容易惊醒，平时善惊，多为心胆气虚。"},{"t":"b","x":"2. 辨受病脏腑"},{"t":"p","x":"不寐的主要病位在心，与肝、胆、脾、胃、肾等脏腑功能失调有关。若兼急躁易怒，多为肝火内扰；若有不思饮食，腹胀便溏，面色少华，多为脾虚不运；若有腰酸，心烦，心悸，头晕，健忘，多为肾阴亏虚，心肾不交；若有嗳腐吞酸，多为胃气不和；若有心烦不寐，触事易惊，多属心胆气虚。"}],"zhize":"不寐的治疗以补虚泻实、调整脏腑阴阳为基本原则。实证泻其有余，如疏肝泄热、清化痰热、消导和中；虚证补其不足，如益气养血、健脾、补肝、益肾；虚实夹杂者，应补泻兼顾。在此基础上安神定志，如养血安神、镇惊安神、清心安神，注意配合心理调适，消除紧张情绪，保持精神舒畅。","syndrome":[{"id":"s068","name":"肝火扰心","label":"1. 肝火扰心","group":"","clinic":"不寐多梦，急躁易怒，甚则彻夜不眠，伴头晕头胀，目赤耳鸣，口干而苦，不思饮食，便秘溲赤，舌红苔黄，脉弦而数。","analysis":"不寐多梦，急躁易怒，甚则彻夜不眠，为情志不舒，肝失条达，气郁化火，上扰于心所致；头晕头胀，目赤耳鸣，系肝火上扰清窍所致；口干口苦，乃肝火偏盛，胆气上逆所致；便秘溲赤，为热伤津液，热移大肠、膀胱所致；不思饮食，因肝郁乘脾；舌红苔黄，脉弦而数，为肝郁化火，肝火炽盛之象。","treat":"清肝泻火，镇心安神。","formulaRaw":"龙胆泻肝汤（《医方集解》）加减。","formulaName":"龙胆泻肝汤加减","fangjie":"龙胆草、黄芩、栀子清肝泻火；泽泻、车前子清利湿热；当归、生地黄滋阴养血柔肝；柴胡疏肝解郁，柴、归、地相配系疏肝与柔肝并举；甘草和中。\n若烦躁易怒，可加生龙骨、生牡蛎、磁石；若胸闷胁胀，善叹息，加香附、郁金、佛手。肝胆之火亢盛而彻夜不寐，头晕目眩，头痛欲裂，不寐躁怒，大便秘结，可服当归龙荟丸。"},{"id":"s069","name":"痰热扰心","label":"2. 痰热扰心","group":"","clinic":"心烦不寐，胸闷脘痞，泛恶嗳气，厌食吞酸，伴头重，目眩，口干口苦，舌红，苔黄腻，脉滑数。","analysis":"心烦不寐，胸闷脘痞，为痰浊宿食壅遏于中，郁积化热，痰热扰心所致；泛恶嗳气，厌食吞酸，为痰食中阻，气机不畅，胃失和降所致；头重目眩，为痰浊上扰，蒙蔽清窍之象；口干，系痰热伤津或痰阻气机津液不能上承所致；口苦乃火热本味；舌红，苔黄腻，脉滑数，为痰热之象。","treat":"清化痰热，和中安神。","formulaRaw":"黄连温胆汤（《六因条辨》）加减。","formulaName":"黄连温胆汤加减","fangjie":"半夏、陈皮、茯苓、枳实健脾化痰，理气和胃；黄连、竹茹清心降火化痰。\n若心悸动，惊惕不安，加龙齿、珍珠母、琥珀粉；胸闷嗳气，脘腹胀满，大便不爽，苔腻脉滑，重用半夏，加秫米；饮食停滞，嗳腐吞酸，脘腹胀痛，加神曲、焦山楂、莱菔子，或用保和丸；痰热盛，痰火上扰心神，彻夜不寐，大便秘结，加大黄或用礞石滚痰丸以泻火逐痰。临证需注意，五味子、酸枣仁、夜交藤等养心安神之品，酸收敛邪，不利于化痰清热。"},{"id":"s070","name":"心脾两虚","label":"3. 心脾两虚","group":"","clinic":"不易入睡，多梦易醒，心悸健忘，神疲食少，伴头晕目眩，面色少华，四肢倦怠、腹胀便溏，舌质淡，苔薄白，脉细无力。","analysis":"不易入睡，多梦易醒，为心脾亏虚，气血乏源，心神失养，神不守舍所致；心悸健忘，为血虚神失所养所致；神疲食少，四肢倦怠，腹胀便溏，为脾虚运化失健，形神失养所致；头晕目眩，面色少华，为气血亏虚，不能上荣头面清窍所致；舌质淡，脉细无力，为气虚血少之象。","treat":"补益心脾，养血安神。","formulaRaw":"归脾汤（《校注妇人良方》）加减。","formulaName":"归脾汤加减","fangjie":"人参、黄芪、白术、甘草益气健脾；当归、龙眼肉补血；远志、酸枣仁、茯神补益心脾，安神定志；木香行气舒脾。\n若心血不足较甚者，加熟地黄、白芍、阿胶；不寐较重者，加柏子仁、五味子、夜交藤、合欢皮；脘闷纳呆，苔腻者，重用白术，加苍术、半夏、陈皮、茯苓、厚朴。"},{"id":"s071","name":"心肾不交","label":"4. 心肾不交","group":"","clinic":"心烦不寐，入睡困难，心悸多梦，伴头晕耳鸣，健忘，腰膝酸软，潮热盗汗，五心烦热，咽干少津，男子遗精，女子月经不调，舌红少苔，脉细数。","analysis":"心烦不寐，入睡困难，心悸多梦，因肾阴亏虚，不能上济于心，心火炽盛，不能下交于肾，心神不安；头晕、耳鸣、健忘，为肾精亏耗，髓海空虚，清窍失养所致；腰膝酸软，为肾虚腰膝失养所致；潮热盗汗，五心烦热，咽干少津，为阴虚火旺所致；男子遗精，女子月经不调，为肾阴亏虚，虚火扰动精室，或冲任失养引起；舌红少苔，脉细数，为阴亏于下，虚火上炎之象。","treat":"滋阴降火，交通心肾。","formulaRaw":"六味地黄丸（《小儿药证直诀》）合交泰丸（《韩氏医通》）加减。六味地黄丸以滋补肾阴为主，交泰丸清心降火，引火归原。","formulaName":"六味地黄丸合交泰丸加减","fangjie":"熟地黄、山萸肉、山药滋补肝肾，填精益髓；泽泻、茯苓、丹皮健脾渗湿，清泄相火；黄连清心降火；肉桂引火归原。\n若心烦不寐，彻夜不眠者，加朱砂、磁石、龙骨、龙齿；若盗汗，可加浮小麦、糯稻根、煅龙骨、煅牡蛎。若心阴不足为主者，用天王补心丹；阴血不足，心火亢盛者，用朱砂安神丸。"},{"id":"s072","name":"心胆气虚","label":"5. 心胆气虚","group":"","clinic":"虚烦不寐，多梦易醒，触事易惊，胆怯心悸，终日惕惕，伴气短自汗，倦怠乏力，舌淡红，苔薄白，脉弦细。","analysis":"虚烦不寐，多梦易醒，触事易惊，为心胆虚怯所致；心失所养则神不安；胆气不足则志不宁；胆怯心悸，终日惕惕，为心胆俱怯，决断无权，神魂不安所致；气短自汗，倦怠乏力，小便清长，舌淡红，脉弦细，均为心胆气虚之象。","treat":"益气镇惊，安神定志。","formulaRaw":"安神定志丸（《医学心悟》）加减。","formulaName":"安神定志丸加减","fangjie":"人参益心胆之气；茯苓、茯神、远志化痰宁心；龙齿镇惊安神；石菖蒲通心气，化痰宁心。\n若心肝血虚，惊悸汗出者，重用人参，加白芍、当归、黄芪；木不疏土，胸闷，善太息，纳呆腹胀者，加柴胡、陈皮、山药、白术；心悸甚惊惕不安者，加生龙骨、生牡蛎、朱砂。若虚烦失眠，心悸不安，头晕目眩，咽干，舌红脉弦细，宜养血安神，清热除烦，可用酸枣仁汤。"}],"linchuang":["辨治不寐的三个原则：①注意调整脏腑气血阴阳的平衡。如补益心脾，应佐以少量醒脾运脾药，以妨碍脾；交通心肾，其引火归原的肉桂用量宜轻；益气镇惊，常须健脾，慎用滋阴之剂；疏肝泻火，注意养血柔肝，以体现“体阴用阳”之意；“补其不足，泻其有余，调其虚实”，使气血调和，阴平阳秘。②强调在辨证论治基础上施以安神镇静。安神的方法，有养血安神、清心安神、育阴安神、益气安神、镇惊安神、安神定志等不同，可随证选用。③注意精神治疗的作用。消除顾虑及紧张情绪，保持精神舒畅。","活血化瘀法的应用。长期顽固性不寐，临床多方治疗效果不佳，或伴有心烦、焦虑、舌质偏暗或有瘀点者，依据古训“顽疾多瘀血”，临床可从气血不和论治，方选血府逐瘀汤加减。"],"yufang":["预防不寐应养成良好的生活习惯，建立规律的作息制度，如按时睡觉，晚餐清淡，不宜过饱，睡前不饮浓茶、咖啡，不吸烟等，避免从事紧张和兴奋的活动，避免经常熬夜。不寐属心神病变，应重视精神调摄和讲究睡眠卫生。积极进行心理情志调整，克服过度紧张、兴奋、焦虑、抑郁、惊恐、愤怒等不良情绪，做到喜怒有节，保持精神舒畅，有助于良好的睡眠。","可以进行适当的体力活动或体育锻炼，增强体质，持之以恒，促进身心健康。注意睡眠环境的安静，床铺要舒适，卧室光线要柔和，努力减少噪音，去除各种可能影响睡眠的外在因素。尽量以放松的、顺其自然的心态对待不寐。"],"attachIds":["a001"]},{"id":"d013","name":"头痛","kind":"main","parent":null,"chapterNo":"第十六章","chapterName":"头痛","yinbing":[{"t":"b","x":"1. 感受外邪"},{"t":"p","x":"起居不慎，坐卧当风，感受风、寒、湿、热等外邪，上犯于脑，清阳之气受阻，气血不畅，发为头痛。"},{"t":"p","x":"其中以风邪为主。"},{"t":"p","x":"《素问·太阴阳明论》云：“故伤于风者，上先受之。”"},{"t":"p","x":"风为百病之长，易兼夹时气而致病。"},{"t":"b","x":"2. 情志失调"},{"t":"p","x":"忧郁恼怒，情志不遂，肝失条达，气滞血瘀，或气郁化火，上扰清窍，可发为头痛。"},{"t":"p","x":"若肝郁化火，日久伤阴，肝肾亏虚，阴虚阳亢，亦可引发头痛。"},{"t":"b","x":"3. 饮食劳伤"},{"t":"p","x":"饮食不节，或劳逸过度，或久病脾虚，气血化源不足，营血亏虚，或清阳不升，脑失所养，发为头痛。"},{"t":"b","x":"4. 先天不足或房事不节"},{"t":"p","x":"禀赋不足，或房劳过度，使肾精久亏，脑髓空虚，则会发生头痛。"},{"t":"b","x":"5. 头部外伤或久病入络"},{"t":"p","x":"跌仆损伤，或脑部外伤，或久病入络，瘀血阻于脑络，不通则痛，发为头痛。"}],"bingji":[{"t":"p","x":"外感头痛基本病机为外邪上扰清窍，壅滞经络，络脉不通。"},{"t":"p","x":"所谓“伤于风者，上先受之”，“高颠之上，惟风可到”，外感头痛以风邪为主，并与他邪合而为病。"},{"t":"p","x":"若风邪夹寒，凝滞血脉，络道不通；风邪夹热，风热炎上，清窍被扰；风邪夹湿，阻遏阳气，终致头部经气不通，不通则痛。"},{"t":"p","x":"内伤头痛基本病机多与肝、脾、肾三脏功能失调有关。"},{"t":"p","x":"头痛的病位在头，病理性质有虚实之分。"},{"t":"p","x":"外感头痛多责之于风、寒、湿、热等邪气，属表实证；内伤头痛多关乎气、血、痰、瘀、虚，其中气血亏虚、肾精不足属虚证，肝阳、痰浊、瘀血所致头痛多属实证。"},{"t":"p","x":"病机演变常可由实转虚或见本虚标实、虚实夹杂。"},{"t":"p","x":"如痰浊中阻日久，脾胃受损，气血生化不足，营血亏虚，脑窍失养，可转为气血亏虚之头痛；肝阳、肝火日久伤阴，肾虚精亏，可转为肾精亏虚之头痛，或阴虚阳亢，虚实夹杂之头痛。"},{"t":"p","x":"各种头痛迁延不愈，病久入络，又可转变为瘀血头痛。"}],"zhenduan":[{"t":"ol","items":["1. 以头部疼痛为主要临床特征。疼痛的部位可发生在前额、两颞、颠顶、枕项或全头等。疼痛的性质可为跳痛、刺痛、胀痛、灼痛、重痛、空痛、昏痛、隐痛等。头痛发作形式可为突然发作，或缓慢起病，或反复发作，时痛时止。疼痛的持续时间可长可短，可数分钟、数小时或数天、数周，甚则长期疼痛不已。","2. 头痛较甚者，可伴见恶心呕吐、畏光畏声、烦躁等症。","3. 外感头痛者多有起居不慎，感受外邪的病史，伴外感表证；内伤头痛者常有饮食、劳倦、房事不节、病后体虚等病史，常反复发作。"]}],"jianbie":[{"t":"p","x":"主要与真头痛鉴别。"},{"t":"b","x":"1. 真头痛"},{"t":"p","x":"真头痛为头痛的一种重症，二者均以头部疼痛为主要临床表现。"},{"t":"p","x":"真头痛的特点为起病急骤，多表现为突发的剧烈头痛，持续不解，阵发性加重，手足逆冷至肘膝，甚至呕吐如喷、肢厥、抽搐，本病凶险，应与一般头痛区别。"},{"t":"p","x":"《灵枢·厥病》曰：“真头痛，头痛甚，脑尽痛，手足寒至节，死不治。”"},{"t":"p","x":"《难经·六十难》亦云：“手三阳之脉受风寒，伏留而不去者，则名厥头痛；人连在脑者，名真头痛。”"}],"bianzheng":[{"t":"b","x":"1. 辨外感与内伤"},{"t":"p","x":"外感头痛多因外邪致病，一般起病较急，疼痛较剧，病程较短，多表现为掣痛、跳痛、灼痛、重痛，痛无休止，伴有外感表证，多属实证。内伤头痛多与肝、脾、肾等脏腑功能失调有关，一般起病较缓，反复发作，病程较长，多表现为胀痛、刺痛、隐痛、空痛、昏痛，其中气血亏虚或者肾精不足所致虚证头痛，多痛势绵绵，遇劳加重，时作时止；如因肝阳、痰浊、瘀血等引起的实证头痛，多表现为胀痛、重痛或刺痛，且常伴有相应脏腑的症状表现；临床亦可见本虚标实，虚实夹杂者。"},{"t":"b","x":"2. 辨头痛部位"},{"t":"p","x":"太阳头痛，痛在脑后，下连于项；阳明头痛，痛在前额部及眉棱骨处；少阳头痛，痛在头之两侧，并连及于耳；厥阴头痛，多在颠顶部位，或连目系；太阴、少阴头痛多以全头疼痛为主。偏头痛，也称“偏头风”，常以一侧头痛暴作为特点，痛势剧烈，可连及眼、齿，痛止则如常人，反复发作，经久不愈，多系肝经风火上扰所致。"},{"t":"b","x":"3. 辨头痛性质"},{"t":"p","x":"因于风寒者，头痛剧烈且连项背；因于风热者，头胀而痛；因于风湿者，头痛如裹；因于痰湿，头痛而重；因于肝阳，头痛而胀；因于肝火，头部跳痛、灼痛；因于瘀血，头部刺痛，痛处固定不移；因于虚者，多呈隐痛、空痛或昏痛。"}],"zhize":"外感头痛多属实证，以风邪为主，治疗当以祛风为主，兼以散寒、清热、祛湿。内伤头痛多属虚证或虚实夹杂证，虚证以补养气血或益肾填精为主，实证以平肝、化痰、行瘀为主，虚实夹杂者，宜标本兼顾，补虚泻实。此外，治疗头痛可在辨证论治的基础上加引经药有助于提高疗效。一般太阳头痛选用羌活、蔓荆子、川芎；阳明头痛选用葛根、白芷、知母；少阳头痛选用柴胡、黄芩、川芎；厥阴头痛选用吴茱萸、藁本；少阴头痛选用细辛；太阴头痛选用苍术。","syndrome":[{"id":"s077","name":"风寒头痛","label":"（1）风寒头痛","group":"外感头痛","clinic":"头痛连及项背，呈掣痛样，时有拘急收紧感，常伴恶风畏寒，遇风尤剧，头痛喜裹，口不渴，舌质淡红，苔薄白，脉浮或浮紧。","analysis":"太阳经主一身之表，其经脉上行颠顶，循项背，风寒最易侵犯，故其痛连及项背；风寒束于肌表，卫阳被遏，不得宣达周身，故恶风畏寒，遇风尤剧；寒属阴邪，寒性收引，故头痛有拘急收紧感；无热则口不渴；舌质淡红，苔薄白，脉浮或浮紧，均为风寒在表之象。","treat":"疏风散寒止痛。","formulaRaw":"川芎茶调散（《太平惠民和剂局方》）加减。","formulaName":"川芎茶调散加减","fangjie":"川芎善行头目，活血通窍，祛风止痛，为治疗头痛之要药；荆芥、羌活、细辛、白芷、防风疏风解表，散寒止痛；薄荷清利头目；炙甘草益气和中，调和诸药；清茶上清头目。若头痛，恶寒明显者，加麻黄、桂枝、制川乌等；颠顶头痛，干呕，吐涎沫，甚则四肢厥冷者，用吴茱萸汤去人参，加藁本、川芎、细辛、半夏；见头痛，足寒，气逆，背冷，脉沉细，用麻黄附子细辛汤加白芷、川芎。"},{"id":"s078","name":"风热头痛","label":"（2）风热头痛","group":"外感头痛","clinic":"头痛而胀，甚则头胀如裂，发热或恶风，面红目赤，口渴喜饮，便秘尿赤，舌质尖红，苔薄黄，脉浮数。","analysis":"热为阳邪，其性属火，风热上扰清窍，故头痛而胀，甚则头胀如裂；面红目赤，亦为火热上炎之征；风热之邪犯卫，郁于肌表，故发热恶风；热伤津液，则口渴欲饮，便秘溲黄；舌质红，苔黄，脉浮数，均为风热邪盛之象。","treat":"疏风清热和络。","formulaRaw":"芎芷石膏汤（《医宗金鉴》）加减。","formulaName":"芎芷石膏汤加减","fangjie":"菊花辛凉微寒，轻清上浮，疏散风热，通窍止痛；川芎活血通窍，祛风止痛；白芷、藁本、羌活散风通窍而止头痛；生石膏清热和络。若烦热口渴，舌红少津，重用石膏，配知母、天花粉、芦根，甚者加黄芩、栀子；大便秘结，口舌生疮，合用黄连上清丸；鼻流浊涕如脓，鼻根及鼻旁疼痛，加苍耳子、辛夷、鱼腥草、藿香等。"},{"id":"s079","name":"风湿头痛","label":"（3）风湿头痛","group":"外感头痛","clinic":"头痛如裹，肢体困重，胸闷纳呆，小便不利，大便或溏，舌质淡，苔白腻，脉濡。","analysis":"风湿外感，束于肌表，上蒙清窍，清阳不升，故头痛如裹；脾司运化而主四肢，湿浊中阻，脾阳为湿所困，故见四肢困重，纳呆胸闷；湿邪内蕴肠道，不能分清泌浊，故小便不利，大便或溏；舌质淡，苔白腻，脉濡，均为湿浊中阻之象。","treat":"祛风胜湿通窍。","formulaRaw":"羌活胜湿汤（《脾胃论》）加减。","formulaName":"羌活胜湿汤加减","fangjie":"羌活、独活、防风、藁本、蔓荆子祛风除湿，散寒止痛；川芎辛温通窍，祛风止痛；甘草调和诸药。若胸闷脘痞，腹胀便溏，加苍术、陈皮、砂仁；恶心，呕吐，加半夏、生姜、竹茹；纳呆食少，加麦芽、神曲、焦山楂；小便短少者，加茯苓、薏苡仁、淡竹叶；发于夏季，感受暑湿，见身热汗少或汗出不畅，心烦口渴，胸闷欲呕，加藿香、佩兰、荷叶。"},{"id":"s080","name":"肝阳头痛","label":"（1）肝阳头痛","group":"内伤头痛","clinic":"头胀痛而眩，以两侧为主，心烦易怒，口苦面红，或兼胁痛，舌质红，苔薄黄，脉弦数。","analysis":"肝失条达，气郁化火，肝阳偏亢，循经上扰清窍，故头痛而眩，以两侧为主；胁为肝之分野，肝胆火热，故胁痛，口苦面红；肝火偏亢，扰乱心神，则心烦易怒，夜眠不宁。舌质红，苔薄黄，脉弦有力，均为肝阳亢盛之象。","treat":"平肝潜阳息风。","formulaRaw":"天麻钩藤饮（《中医内科杂病证治新义》）加减。","formulaName":"天麻钩藤饮加减","fangjie":"天麻、钩藤、生石决明平肝潜阳息风；栀子、黄芩清泻肝火；桑寄生、杜仲补肾柔肝；牛膝、益母草活血调经，引血下行；首乌藤、茯神养心安神。若头痛剧烈，目赤口苦，急躁易怒，便秘尿黄者，加龙胆草、夏枯草、大黄；头晕目涩，腰膝酸软者，加生地黄、何首乌、枸杞子等。"},{"id":"s081","name":"血虚头痛","label":"（2）血虚头痛","group":"内伤头痛","clinic":"头痛而晕，心悸，神疲乏力，面色少华，舌质淡，苔薄白，脉细弱。","analysis":"营血不足，不能上荣头面及四肢，故头痛而晕，面色少华；气血亏虚，中气不足，故神疲乏力；血不足则心神失养，故心悸；舌质淡，苔薄白，脉细弱，均为血虚之象。","treat":"滋阴养血，和络止痛。","formulaRaw":"加味四物汤（《证治汇补》）加减。","formulaName":"加味四物汤加减","fangjie":"当归、生地黄、白芍养血滋阴；川芎、菊花、蔓荆子清利头目。若见神疲乏力，遇劳加重，气短懒言，汗出恶风等，加黄芪、党参、白术；阴血亏虚，阴不敛阳，肝阳上扰者，加天麻、白蒺藜、枸杞子、菊花、石决明等。"},{"id":"s082","name":"气虚头痛","label":"（3）气虚头痛","group":"内伤头痛","clinic":"头痛隐隐，时发时止，遇劳则加重，纳食减少，倦怠乏力，气短自汗，舌质淡，苔薄白，脉细弱。","analysis":"中气不足，清阳不升，脑失所养，故头痛隐隐，时发时止，遇劳加重；脾气亏虚，脾失健运，气血生化乏源，故纳食减少，倦怠乏力，气短；气虚不能固护肤表，故自汗；舌质淡红，或苔薄白，脉细弱，均为气虚之象。","treat":"健脾益气升清。","formulaRaw":"益气聪明汤（《东垣试效方》）加减。","formulaName":"益气聪明汤加减","fangjie":"黄芪、炙甘草、人参健脾益气；升麻、葛根引清气上升；蔓荆子、芍药养血祛风止痛。头痛绵绵不休，心悸，失眠，加当归、熟地黄、何首乌；畏寒怕冷，手足欠温，加附子（制）、肉桂、葱白等。"},{"id":"s083","name":"痰浊头痛","label":"（4）痰浊头痛","group":"内伤头痛","clinic":"头痛昏蒙沉重，胸脘痞闷，纳呆呕恶，舌质淡，苔白腻，脉滑或弦滑。","analysis":"脾失健运，痰浊中阻，上蒙清窍，清阳不升，故头痛昏蒙沉重；痰浊壅盛，阻碍气机，故胸脘痞闷，纳呆呕恶；舌质淡，苔白腻，脉滑或弦滑，均为痰浊内停之象。","treat":"健脾燥湿，化痰降逆。","formulaRaw":"半夏白术天麻汤（《医学心悟》）加减。","formulaName":"半夏白术天麻汤加减","fangjie":"半夏、橘红、甘草和中化痰；白术、茯苓健脾化湿；天麻平肝息风止痛；姜、枣调和脾胃，生姜兼制半夏之毒。若痰湿中阻，胸脘满闷甚者，加厚朴、枳壳、砂仁；口苦，大便不畅，舌苔黄腻，脉滑数，去白术，加黄连、枳实、竹茹，或选用黄连温胆汤。"},{"id":"s084","name":"肾虚头痛","label":"（5）肾虚头痛","group":"内伤头痛","clinic":"头痛且空，眩晕耳鸣，腰膝酸软，神疲乏力，少寐健忘，遗精带下，舌质红，苔少，脉细无力。","analysis":"肾虚精亏，不能上荣脑髓，故头痛且空，眩晕耳鸣；精血亏虚，则神疲乏力；阴血不足，心神不宁，则少寐健忘；腰为肾之府，肾虚则腰膝酸软；精关不固而遗精，女子则带脉不束而带下；舌红少苔，脉细无力，是肾精亏虚之象。","treat":"养阴补肾，填精生髓。","formulaRaw":"大补元煎（《景岳全书》）加减。","formulaName":"大补元煎加减","fangjie":"熟地黄、枸杞子滋肾填精；杜仲补益肝肾；山萸肉养肝涩精；山药、人参、当归补益气血；炙甘草调和诸药。若头痛而晕，面颊红赤，潮热汗出，去人参，加墨旱莲、知母、黄柏，或用知柏地黄丸加减；畏寒怕冷，四肢不温，腰膝酸软，舌淡苔白，脉沉细，加鹿角、附子（制），或用右归丸或金匮肾气丸加减。"},{"id":"s085","name":"瘀血头痛","label":"（6）瘀血头痛","group":"内伤头痛","clinic":"头痛经久不愈，痛处固定不移，痛如锥刺，或有头部外伤史，舌质紫暗，可见瘀斑、瘀点，苔薄白，脉细或细涩。","analysis":"久病入络，或头部外伤，瘀血阻窍，脉络不畅，不通则痛，故头痛经久不愈，痛有定处，且如锥刺；舌质紫暗，或有瘀点、瘀斑，脉细或细涩，为瘀血内阻之象。","treat":"活血化瘀，通窍止痛。","formulaRaw":"通窍活血汤（《医林改错》）加减。","formulaName":"通窍活血汤加减","fangjie":"赤芍、川芎行血活血；桃仁、红花活血通络；老葱通阳；麝香开窍；黄酒通络；大枣缓和芳香辛窜药物之性。若头痛较剧，加全蝎、蜈蚣、土鳖虫等虫类药；久痛不已，神疲乏力，少气懒言，脉细弱无力，加黄芪、党参、当归；畏寒明显，加桂枝、细辛、附子（制）等。"}],"linchuang":["临证应注意甄别真头痛。真头痛为头痛的一种特殊类型，多呈突发性剧烈头痛，持续不解，阵发加重，常伴有喷射性呕吐，或颈项强直，或偏瘫偏盲，或抽搐。如王肯堂认识到：“天门真痛，上引泥丸，夕发旦死，旦发夕死。盖脑为髓海，真气之所聚，卒不受邪，受邪则死不可治。”常见于西医学中高血压危象、蛛网膜下腔出血、硬膜下出血等危重病证。一旦出现上述表现，应行头颅CT或MRI检查或脑脊液检查，以免延误诊断治疗。","注意配伍风药。头痛时作时止，犹如风之善行而数变，又“高颠之上，惟风可到”，临证配伍风药，其性轻扬，易达病所，可直折痛势。故临床治疗头痛，无论外感内伤，均可酌情使用风药以提高疗效。常用风药有防风、白芷、蔓荆子等。但风药辛散，不宜久服。","重视虫类药的应用。若头痛反复发作，经年难愈，所谓“久病人络”，表现为头部刺痛，部位固定，面色暗滞，舌暗脉涩等症。治疗时可在辨证论治的基础上，选配全蝎、蜈蚣、僵蚕、地龙、土鳖虫等虫类药，以祛瘀通络，解痉定痛，平肝息风，可获良效。虫类药可入汤剂煎服，亦可研细末冲服。因其多有小毒，故应合理掌握用量，不可过用。","雷头风诊治。雷头风以头痛如雷鸣、头面起核为特点，多为湿热夹痰上冲，可用清震汤加味治疗。如头面起核，肿痛红赤，可合普济消毒饮以清热解毒。《张氏医通·卷五》云：“头痛而起核块者，雷头风也。或头中如雷之鸣，为风客所致。”"],"yufang":["外感头痛由外邪侵袭所致，故平时当顺应四时变化，起居有常，适避寒温，强健体魄，避免外邪侵袭，所谓“虚邪贼风，避之有时”。宜调畅情志，避免精神刺激，注意休息。各类头痛患者均应戒烟戒酒。此外，尚可选择合适的头部保健按摩法，以疏通经脉，调畅气血，防止头痛发生。","头痛剧烈者宜卧床休息，保持环境安静，光线不宜过强。伴有焦虑和抑郁者，宜辅以心理疏导及音乐疗法。风寒头痛者，应注意避邪保暖；肝阳上亢者，禁食肥甘厚腻、辛辣发物，以免生热动风；肝火头痛者，可用冷毛巾败头部；痰浊头痛者，宜清淡饮食，勿进肥甘之品，避免助湿生痰；精血亏虚者，应多进食血肉有情之品。"],"attachIds":[]},{"id":"d014","name":"眩晕","kind":"main","parent":null,"chapterNo":"第十七章","chapterName":"眩晕","yinbing":[{"t":"b","x":"1. 情志不遂"},{"t":"p","x":"长期忧恚恼怒，肝气郁结，气郁化火，肝阴暗耗，风阳扰动，上扰脑窍，发为眩晕。"},{"t":"p","x":"《临证指南医案·眩晕》华岫云按：“经云：诸风掉眩，皆属于肝。头为六阳之首，耳目口鼻皆系清空之窍。所患眩晕者，非外来之邪，乃肝胆之风阳上冒耳，甚则有昏厥跌仆之虞。”"},{"t":"b","x":"2. 年老体虚"},{"t":"p","x":"若年高肝肾亏虚，精血不足，无以充养于脑，或房事不节，阴精亏耗过甚，或体虚多病，耗伤精气，均可致肾精亏耗，髓海不足，脑窍失养，而发为眩晕。"},{"t":"b","x":"3. 饮食不节"},{"t":"p","x":"若平素嗜酒无度，暴饮暴食，或过食肥甘厚味，损伤脾胃，以致健运失司，水谷不化，聚湿生痰，痰湿中阻，则清阳不升，浊阴不降，致脑窍失养，而引发眩晕。"},{"t":"b","x":"4. 久病劳倦"},{"t":"p","x":"久病不愈，耗伤气血，或失血之后，气随血耗，或忧思劳倦，损伤脾胃，暗耗气血。气虚则清阳不升，血虚则脑窍失养，皆可发生眩晕。"},{"t":"b","x":"5. 跌仆坠损"},{"t":"p","x":"跌仆坠损而致头部外伤，或久病人络，瘀血停留，阻滞经脉，而使气血不能上荣于头目，脑窍失养，而发眩晕。"},{"t":"p","x":"此外，外感六淫之中，因“高颠之上，惟风可到”，风邪可与寒、热、湿、燥等诸邪兼夹，导致经脉运行失常，气血精髓不能上荣头目，使脑窍失养而发眩晕。"}],"bingji":[{"t":"p","x":"眩晕的基本病机是脑窍失养或邪扰脑窍，有虚实两端。"},{"t":"p","x":"虚者为脾胃虚弱，气血亏虚，或肝肾亏虚，髓海不足，脑窍失养；实者为风、火、痰、瘀扰乱脑窍。"},{"t":"p","x":"病变部位在脑窍，与肝、脾、肾三脏关系密切。"},{"t":"p","x":"关于病理性质，虚证多因气血两虚，肝肾阴虚，肾精亏虚，髓海不足，脑窍失养；实证多因肝阳上亢，风阳升动，或痰浊阻遏，升降失常，或痰火气逆，或瘀血阻窍，脑窍被扰。"},{"t":"p","x":"病理因素主要有风、火、痰、瘀，病理本质涉及虚（气血、肝肾、肾精亏虚）。"},{"t":"p","x":"在病变过程中，病因多彼此影响，病机常发生转化，兼夹复合为患。"},{"t":"p","x":"如脾胃虚弱，气血亏虚，脑窍失养，而发生眩晕，而脾虚又可聚湿生痰，二者相互影响，形成气血亏虚兼有痰湿中阻的证候；肝气郁结日久化火，气郁生痰，痰火为患，甚至火盛伤阴，形成阴亏于下，痰火上蒙的证候；肾精亏虚本属阴虚，若因阴损及阳，或精不化气，可转为肾阳不足或阴阳俱虚之证。"},{"t":"p","x":"此外，风阳每夹有痰火，肾虚可以导致肝旺，久病入络，形成瘀血，故临床常形成虚实夹杂之证候。"},{"t":"p","x":"眩晕频作，尤其是中老年患者多有罹患中风的可能，常称之为“中风先兆”，应慎防其病机传变。"}],"zhenduan":[{"t":"ol","items":["1. 眩晕以头晕目眩、视物旋转为主要临床特征，轻者闭目即止，重者如坐车船，甚至仆倒。","2. 眩晕可伴有恶心、呕吐、汗出、耳鸣、耳聋、心悸及面色苍白、眼球震颤等表现。","3. 眩晕多有情志不遂、年高体虚、饮食不节或跌仆损伤等病史。"]}],"jianbie":[{"t":"b","x":"1. 厥证"},{"t":"p","x":"厥证与眩晕严重者均存在仆倒的临床表现，但厥证以突然昏仆、不省人事或伴见四肢厥冷为特征。"},{"t":"p","x":"眩晕严重者无昏迷、不省人事等症，也无四肢厥冷表现。"},{"t":"b","x":"2. 中风"},{"t":"p","x":"中风与眩晕严重者均可见到仆倒的临床表现，但中风以猝然昏仆、不省人事，伴口眼歪斜、半身不遂、失语为特征。"},{"t":"p","x":"但眩晕严重者神志清楚或瞬间即清，且无半身不遂、口眼歪斜、言语謇涩等症。"},{"t":"p","x":"部分中风患者以眩晕、头痛为先兆表现，应注意二者的联系与区别。"}],"bianzheng":[{"t":"b","x":"1. 辨相关脏腑"},{"t":"p","x":"眩晕病在脑窍，与肝、脾、肾三脏功能密切相关。眩晕兼见头胀痛、面色潮红、急躁易怒、口苦脉弦等症状，病在肝；兼有纳呆、神疲乏力、面色萎黄，或纳呆呕恶、头痛、苔腻诸症，病在脾胃；兼有腰酸腿软、耳鸣如蝉等症，病在肾。"},{"t":"b","x":"2. 辨虚实兼夹"},{"t":"p","x":"凡眩晕病程较长，反复发作，症状较轻，遇劳即发，多属虚证。伴两目干涩、腰膝酸软，多由肝肾亏虚所致；或伴面色㿠白、神疲乏力、形羸体弱、脉偏细弱者，多由气血亏虚所致。凡眩晕病程短，突然发作，症状较重，多属实证。伴呕恶痰涎、头沉头痛、形体壮实、苔腻脉滑，多为痰湿所致；或头部外伤之后，或久病入络，伴头痛固定不移、唇舌紫暗、舌有瘀斑、脉涩，多为瘀血所致；伴面赤、口苦、烦躁易怒、肢麻震颤甚则昏仆，脉多弦数有力，多为肝阳风火所致。"},{"t":"b","x":"3. 辨轻重缓急"},{"t":"p","x":"老年、体虚、久病之人，病势绵绵，症状多较轻，多因虚而发；青壮年、肥人、初病之人，病势急骤，症状较重，多因实而发；若眩晕缠绵难愈，症状时轻时重，形成虚实夹杂状态，或有变生中风、厥证之虞。"}],"zhize":"眩晕以补虚泻实、调整阴阳为基本原则。虚者治当补益气血、滋补肝肾、填精益髓；实者治当潜阳息风、清肝泻火、化痰祛瘀；虚实夹杂者，宜标本兼顾。","syndrome":[{"id":"s086","name":"肝阳上亢证","label":"1. 肝阳上亢证","group":"","clinic":"眩晕，耳鸣，头目胀痛，急躁易怒，口苦，失眠多梦，遇烦劳郁怒而加重，甚则仆倒，颜面潮红，肢麻震颤，舌质红，苔黄，脉弦或数。","analysis":"肝阳上亢，扰动清窍，故眩晕、耳鸣、头目胀痛；肝阳上扰心神，心神不宁，故急躁易怒、失眠多梦；肝火内郁，故口苦；肝阳上亢，血随气逆，故颜面潮红；阳亢化风，甚至升发太过，故遇烦劳郁怒而加重，甚则仆倒，肢麻震颤；舌质红，苔黄，脉弦或数，为肝阳上亢之象。","treat":"平肝潜阳，清火息风。","formulaRaw":"天麻钩藤饮（《杂病证治新义》）加减。","formulaName":"天麻钩藤饮加减","fangjie":"天麻、石决明、钩藤平肝潜阳息风；黄芩、山栀子清肝泻火；益母草活血利水；牛膝、杜仲、桑寄生补肾养肝；茯神、夜交藤养血安神定志。口苦目赤，烦躁易怒甚者，加龙胆草、川楝子、夏枯草等；若目涩耳鸣，腰膝酸软，加枸杞子、生地黄、玄参；若目赤便秘，加大黄、芒硝，或佐用当归龙荟丸；若眩晕剧烈，手足麻木或震颤，加磁石、珍珠母、羚羊角粉等。"},{"id":"s087","name":"痰湿中阻证","label":"2. 痰湿中阻证","group":"","clinic":"眩晕，头重如裹，或伴视物旋转，胸闷，纳呆恶心，呕吐痰涎，食少寐多，舌苔白腻，脉濡滑。","analysis":"痰湿中阻，上蒙脑窍，故眩晕、头重如裹，伴视物旋转；痰浊中阻，气机不利，胃失和降，故胸闷、纳呆、恶心、呕吐痰涎；痰湿阻遏，脾阳不振，故食少寐多；舌苔白腻，脉濡滑，为痰湿之象。","treat":"化痰祛湿，健脾和胃。","formulaRaw":"半夏白术天麻汤（《医学心悟》）加减。","formulaName":"半夏白术天麻汤加减","fangjie":"半夏、橘红健脾燥湿化痰；白术健脾燥湿；天麻息风止眩；茯苓利水渗湿；甘草、生姜、大枣健脾和胃。若呕吐频作，加胆南星、天竺黄、竹茹、旋覆花；若耳鸣重听，加葱白、郁金、石菖蒲等。若头痛头胀，心烦口苦，渴不欲饮，用黄连温胆汤加减。"},{"id":"s088","name":"瘀血阻窍证","label":"3. 瘀血阻窍证","group":"","clinic":"眩晕，头痛，痛有定处，兼见健忘，失眠，心悸，精神不振，耳鸣耳聋，面唇紫暗，舌质暗，有瘀斑，多伴见舌下脉络迂曲增粗，脉涩或细涩。","analysis":"瘀血阻窍，气血不畅，不通则痛，故眩晕、头痛，痛有定处；心血瘀阻，心神失养，故健忘、失眠、心悸、精神不振；瘀血内阻，脑窍失用，故耳鸣耳聋；面唇紫暗，舌质暗，有瘀斑，舌下脉络迂曲增粗，脉涩或细涩，为瘀血内阻之象。","treat":"祛瘀生新，活血通窍。","formulaRaw":"通窍活血汤（《医林改错》）加减。","formulaName":"通窍活血汤加减","fangjie":"川芎、赤芍、桃仁、红花活血化瘀，通络止痛；麝香开窍通闭；生姜、老葱、黄酒通阳行血；大枣健脾益气。若神疲乏力，少气自汗，加黄芪、党参等；若心烦面赤，舌红苔黄，加栀子、连翘、薄荷、菊花；若畏寒肢冷，感寒加重，加附子（制）、桂枝等；若头颈部不能转动，加威灵仙、葛根、豨签草等；若瘀血重，加地龙、全蝎等。"},{"id":"s089","name":"气血亏虚证","label":"4. 气血亏虚证","group":"","clinic":"眩晕，动则加剧，劳累即发，面色㿠白，神疲自汗，倦怠懒言，唇甲不华，发色不泽，心悸少寐，纳少腹胀，舌质淡，苔薄白，脉细弱。","analysis":"气血亏虚，脑窍失养，劳则耗气，故眩晕，动则加剧，劳累即发；气血亏虚，不能上荣头面，故面色㿠白、唇甲不华、发色不泽；气血亏虚，形神失养，故神疲自汗、倦怠懒言；气血亏虚，心失所养，故心悸少寐；脾失健运，故纳少腹胀；舌质淡，苔薄白，脉细弱，为气血亏虚之象。","treat":"补益气血，调养心脾。","formulaRaw":"归脾汤（《济生方》）加减。","formulaName":"归脾汤加减","fangjie":"人参、白术、黄芪、当归健脾益气养血；龙眼肉、茯神、远志、酸枣仁养心安神；木香理气醒脾；甘草、生姜、大枣健脾和中。若自汗时出，易于感冒，当重用黄芪，加防风、浮小麦；若形寒肢冷，腹中隐痛，加肉桂、干姜；若血虚较甚，面色苍白，唇舌色淡，加熟地黄、阿胶；若脾虚湿盛，腹胀纳呆，加薏苡仁、白扁豆、泽泻；若心悸怔忡，少寐健忘，加柏子仁、首乌藤、龙骨、牡蛎。"},{"id":"s090","name":"髓海不足证","label":"5. 髓海不足证","group":"","clinic":"眩晕日久不愈，精神萎靡，腰膝酸软，少寐多梦，健忘，两目干涩，视力减退，遗精滑泄，耳鸣齿摇，舌质淡，苔薄白或少苔，脉沉细弱，尺脉尤甚。","analysis":"肾精亏虚，髓海不足，故眩晕日久不愈、精神萎靡、少寐多梦、健忘、耳鸣齿摇；肝肾阴亏，目窍失养，故两目干涩、视力减退；肾精亏虚，骨骼失养，故腰膝酸软；舌质淡，苔薄白或少苔，脉沉细弱，尺脉尤甚，为肾精不足之象。","treat":"滋补肝肾，填精益髓。","formulaRaw":"左归丸（《景岳全书》）加减。","formulaName":"左归丸加减","fangjie":"熟地黄补肾填精；山茱萸、菟丝子、枸杞子滋补肝肾，益精明目；山药滋阴补肾固精；龟甲胶与鹿角胶为血肉有情之品，峻补精髓，龟甲胶偏于补阴，鹿角胶偏于补阳，两者相合，阴阳双补，填精益髓；川牛膝强肾健骨。若颧红咽干，五心烦热，舌红少苔，脉细数，加鳖甲、知母、黄柏、丹皮；若失眠，多梦，健忘，加阿胶、鸡子黄、酸枣仁、柏子仁等；若面色㿠白，形寒肢冷，舌质淡嫩，苔白，脉沉细无力，尺脉尤甚，加巴戟天、淫羊藿、肉桂，或予右归丸加减；若下肢浮肿，尿少，加桂枝、茯苓、泽泻等；若便溏，腹胀少食，加白术、茯苓、薏苡仁等。"}],"linchuang":["眩晕多从肝论治。经曰：“诸风掉眩，皆属于肝。”肝木旺，风气甚，则头目眩晕，故眩晕之病，病位虽主要在脑窍，但五脏之中与肝关系最为密切。由于患者体质因素及病机演变不同，可表现肝阳上亢、内风上旋，水不涵木、虚阳上亢，阴血不足、血虚生风，肝郁化火、火性炎上等不同的证候，临证之时当根据病机的异同择用平肝、柔肝、养肝、疏肝、清肝诸法。此外，肝风又每多兼痰、兼瘀，又当虚实并治。王旭高《西溪书屋夜话录》谓：“肝气、肝火、肝风三者同出异名，其中侮脾、乘胃、冲心、犯肺、夹寒、夹瘀，本虚标实，种种不同，故肝病最杂，治法最广。”详述治肝之法，可供参考。","警惕“眩晕乃中风之渐”。临床上，肝肾阴亏，肝阳上亢导致的眩晕较为常见，若治不及时，可导致肝阳暴亢，阳亢化风，夹瘀化火，窜走经络，患者常见眩晕头胀、面赤头痛、肢麻震颤甚则昏倒等症状，甚至可以引发中风之变。必须严密监测血压、神志、肢体肌力、感觉等方面的变化，以防病情突变。"],"yufang":["预防眩晕发生，宜保持心情舒畅，防止七情内伤；起居有常，慎养人体精气神；饮食清淡有节，戒烟戒酒，防止脾胃损伤；注意劳逸结合，避免过度劳累；平素注意自我防护，勿使头部受跌仆之伤及六淫邪气。","眩晕发生后要及时治疗，轻者注意休息，重者应卧床休息；注意饮食适宜，情绪稳定，劳逸适度，避免突然、剧烈的体位改变和头颈部运动，以防眩晕症状加重，或发生昏仆。有眩晕史的患者，应当避免剧烈体力活动，避免高空作业。"],"attachIds":[]},{"id":"d015","name":"中风","kind":"main","parent":null,"chapterNo":"第十八章","chapterName":"中风","yinbing":[{"t":"p","x":"中风主要是由内伤积损、情志过极、饮食不节、劳欲过度等引起，肝阳暴张，或痰热内生，或气虚痰湿，引起内风旋动，气血逆乱，横窜经络，直冲犯脑，导致血瘀脑脉或血溢脉外，而成本病。"},{"t":"b","x":"1. 内伤积损"},{"t":"p","x":"年老体衰，正气自虚，或久病迁延，损伤五脏之气阴，气虚则无力运血，脑脉瘀滞，阴虚则不能制阳，内风动越，而致本病发生。"},{"t":"p","x":"张介宾《景岳全书·非风》指出：“此证多见卒倒，卒倒多由昏愦。本皆内伤积损颓败而然，原非外感风寒所致。”"},{"t":"b","x":"2. 情志过极"},{"t":"p","x":"七情所伤，肝气郁结，气郁化火，或暴怒伤肝，肝阳暴张，内风动越，或心火暴甚，风火相扇，血随气逆，引起气血逆乱，上冲犯脑，血溢脉外或血瘀脑脉，发为中风，以暴怒伤肝引发本病者为多见。"},{"t":"b","x":"3. 饮食不节"},{"t":"p","x":"嗜食肥甘厚味、辛辣刺激之物，或饮酒过度，致使脾失健运，酿生痰热，痰瘀互阻，积热生风，导致脑脉瘀滞而发中风。"},{"t":"p","x":"张山雷《中风诠·论昏瞀猝仆之中风无一非内因之风》言：“肥甘太过，酿痰蕴湿，积热生风，致为暴仆偏枯，猝然而发，如有物击使之仆者，故曰仆击而特著其病源，名以膏粱之疾。”"},{"t":"b","x":"4. 劳欲过度"},{"t":"p","x":"烦劳过度，耗气伤阴，致使阳气暴张，风阳内动，气血上逆，壅阻清窍，而致血瘀脑脉或血溢脉外，发为中风。"},{"t":"p","x":"或恣情纵欲，房劳不节，肾水不济，引动心火，阳亢风动而致中风。"},{"t":"p","x":"《素问·生气通天论》云：“阳气者，烦劳则张。”"}],"bingji":[{"t":"p","x":"中风的基本病机是阴阳失调，气血逆乱。"},{"t":"p","x":"病变部位主要在脑，与心、肝、脾、肾密切相关。"},{"t":"p","x":"病理性质多属本虚标实，气血不足或肝肾阴虚是致病之本，风、火、痰、气、瘀是发病之标，两者可互为因果。"},{"t":"p","x":"病理因素主要有风（肝风、外风）、火（肝火、心火）、痰（风痰、湿痰）、气（气逆）、瘀（血瘀），如遇到烦劳、恼怒、房事不节、醉酒饱食等诱因，阴阳严重失调，气血发生逆乱而致中风。"},{"t":"p","x":"急性期以风、火、痰、瘀等标实为主，如病情剧变，邪气亢盛，正气急速溃败，可以正虚为主，甚则出现正气虚脱。"},{"t":"p","x":"恢复期和后遗症期多表现为虚实夹杂，以风痰瘀阻与气虚、肝肾阴虚兼夹为多见，也可见气血不足、阳气虚衰。"},{"t":"p","x":"若肝风夹痰，横窜经络，血脉瘀阻，气血不能濡养机体，则见中经络之证，病位较浅，表现为半身不遂，口眼㖞斜，言语不利，不伴神志障碍。"},{"t":"p","x":"若风阳痰火蒙蔽清窍，气血逆乱，上冲于脑，则见中脏腑之证，病位较深，络损血溢或脑络瘀阻，而致猝然昏倒，不省人事。"},{"t":"p","x":"因邪正虚实的不同，又有闭脱之分及由闭转脱的演变。"},{"t":"p","x":"恢复期和后遗症期因脑髓损伤，肝肾阴虚，气虚未复，风、火、痰、瘀之邪留滞经络，气血运行不畅，而仍留有半身不遂、口歪或不语等后遗症，一般恢复较慢，甚则出现种种变证。"},{"t":"p","x":"若痰蒙神窍，神机失用，可渐发展为痴呆；风痰瘀血，流窜经络，风阳内动，可发为痫证；调摄不当，阴血亏虚，阴不敛阳，可致复中。"}],"zhenduan":[{"t":"ol","items":["1. 以猝然昏仆、不省人事、半身不遂、口眼㖞斜、言语謇涩为主症。病轻者可无昏仆而仅见口眼㖞斜及半身不遂等症。","2. 一般急性起病，渐进加重。发病前多有情志失调、饮食不节或劳累等诱因。","3. 发病前常有先兆症状，如头晕、头痛、耳鸣，或一过性言语不利，或肢体麻木、视物昏花等，一日内发作数次，或几日内多次发作。","4. 常有眩晕、头痛、心悸等病史。好发年龄为40岁以上。"]},{"t":"p","x":"根据病情程度，可分为中经络和中脏腑；根据病程时间，可分为急性期（发病后2周以内，中脏腑可至1个月）、恢复期（2周至6个月）和后遗症期（6个月以上）。"}],"jianbie":[{"t":"b","x":"1. 口僻"},{"t":"p","x":"口僻俗称吊线风。"},{"t":"p","x":"口僻与中风均存在口角歪斜、言语不清的临床表现。"},{"t":"p","x":"但口僻多伴外感表证或耳后疼痛，口角流涎，并无半身不遂、神志障碍等症状，多因正气不足，风邪入络，气血痹阻所致。"},{"t":"b","x":"2. 厥证"},{"t":"p","x":"厥证与中风均可见突然昏仆、不省人事的临床表现。"},{"t":"p","x":"但厥证神昏时间短暂，发作时常伴有面色苍白、四肢逆冷，一般移时苏醒，醒后无半身不遂、口眼㖞斜、言语謇涩等症状。"},{"t":"b","x":"3. 痉证"},{"t":"p","x":"痉证也可见神昏，与中风闭证类似。"},{"t":"p","x":"痉证以四肢抽搐、颈项强直甚至角弓反张为主症，但神昏多出现在抽搐之后，并无半身不遂、口眼㖞斜等症状。"},{"t":"p","x":"中风多在起病时即有神昏，而后可见抽搐。"},{"t":"b","x":"4. 痿证"},{"t":"p","x":"痿证与中风后遗症期均可表现为肢体瘫软无力。"},{"t":"p","x":"痿证一般起病缓慢，多表现为双下肢痿躄不用，或四肢肌肉萎缩，痿软无力。"},{"t":"p","x":"中风肢体瘫痪多起病急骤，肢体肌肉萎缩多见于后遗症期，为半身不遂废用所致，称为“偏枯”。"}],"bianzheng":[{"t":"b","x":"1. 辨中经络与中脏腑"},{"t":"p","x":"主要鉴别点是有无神志障碍。无神志昏蒙或恍惚者属于中经络，病位较浅，病情较轻；有神志昏蒙或恍惚者属于中脏腑，病位较深，病情较重。"},{"t":"b","x":"2. 辨闭证与脱证"},{"t":"p","x":"中脏腑有闭证和脱证之分。闭证是邪闭于内，多为实证，症见神志昏蒙，牙关紧闭，口噤不开，肢体强痉。阳闭为痰热闭阻清窍，兼面赤身热，气粗口臭，烦躁不安，舌红苔黄腻，脉弦滑而数；阴闭为痰浊闭阻清窍，兼面白唇暗，四肢不温，静卧不烦，喉中痰鸣，舌淡苔白腻，脉沉滑或缓。脱证是阳脱于外，多为虚证，症见昏愦不语，目合口开，四肢瘫软，手撒肢冷汗多，鼻息低微，二便自遗，舌痿，脉微欲绝。"},{"t":"b","x":"3. 辨顺势与逆势"},{"t":"p","x":"中风急性期中脏腑者有顺势和逆势。若神志转清，病情由中脏腑向中经络转化，病势为顺，预后多好。若中经络渐进加重，出现神志障碍，可发展为中脏腑，属病势逆转，预后较差。起病即中脏腑，或突然神昏、四肢抽搐不已，或背腹骤然灼热而四肢发凉，甚至手足厥逆，或见戴阳及呕血，均属逆象，病情危重，预后不良。"}],"zhize":"中风急性期，急则治其标，以祛邪为主，常用平肝息风、化痰通腑、活血通络等治法。如中脏腑者，当以醒神开窍为治则，闭证宜清热开窍或化痰开窍，脱证则回阳固脱。如内闭外脱并存，则醒神开窍与扶正固本兼用。中风恢复期和后遗症期，多为虚实兼夹，当扶正祛邪，标本兼顾，常用平肝息风、化痰祛瘀与滋养肝肾、益气养血并用。","syndrome":[{"id":"s091","name":"风痰入络证","label":"1. 风痰入络证","group":"","clinic":"肌肤不仁，甚则半身不遂，口眼㖞斜，言语不利，或謇涩或不语，平素头晕、目眩，舌质暗淡，苔白腻，脉弦滑。","analysis":"脉络空虚，风痰乘虚入中，气血闭阻，故肌肤不仁，偏身麻木，甚则半身不遂，口眼㖞斜，言语不利，或謇涩或不语；风痰扰动清阳，故见头晕目眩；舌质暗淡，苔白腻，脉弦滑，为内有痰湿及瘀血之象。","treat":"息风化痰，活血通络。","formulaRaw":"半夏白术天麻汤（《医学心悟》）合桃仁红花煎（《陈素庵妇科补解》）加减。","formulaName":"半夏白术天麻汤合桃仁红花煎加减","fangjie":"天麻平肝息风，化痰通络；半夏、茯苓、陈皮、甘草补脾益气，燥湿化痰；白术、生姜、大枣健脾化湿；桃仁、红花逐瘀行血；香附、青皮、延胡索理气行血。若风痰较盛而见头晕、目眩者，可加胆南星、天竺黄、石决明等；若痰涎壅盛，口噤不语，半身不遂者，可用真方白丸子加减；若舌强不利，言语謇涩者，可加石菖蒲、远志；若便秘热结，可加大黄、黄芩、栀子清热通便，或合星蒌承气汤加减。"},{"id":"s092","name":"风阳上扰证","label":"2. 风阳上扰证","group":"","clinic":"半身不遂，肌肤不仁，口眼㖞斜，言语謇涩，或舌强不语，平素急躁易怒，头痛，眩晕耳鸣，面红目赤，口苦咽干，尿赤，便干，舌质红或红绛，苔薄黄，脉弦有力。","analysis":"肝阳暴张，风阳上扰，血随气逆，故半身不遂，肌肤不仁；风阳上扰，舌络瘀滞，故舌强謇涩或不语，或口眼㖞斜；阳亢化风，经脉不利，故急躁易怒，头痛，眩晕耳鸣，面红目赤，口苦咽干，尿赤便干；舌质红或红绛，苔薄黄，脉弦有力，为风火上扰之象。","treat":"清肝泻火，息风潜阳。","formulaRaw":"天麻钩藤饮（《中医内科杂病证治新义》）加减。","formulaName":"天麻钩藤饮加减","fangjie":"天麻、钩藤平肝息风；珍珠母、石决明镇肝潜阳；桑叶、菊花、夏枯草清肝泻热；黄芩、栀子清肝泻火；川牛膝活血化瘀，引气血下行。若肝阳暴张而头痛较重者，可加羚羊角、夏枯草、决明子、龙胆草等；若急躁易怒明显，加牡丹皮、生白芍、柴胡、郁金等；若下肢重滞者，加杜仲、桑寄生、枸杞子、女贞子等；若夹有痰浊，见胸闷、恶心、苔腻者，加胆南星、郁金、半夏、白术等。"},{"id":"s093","name":"阴虚风动证","label":"3. 阴虚风动证","group":"","clinic":"半身不遂，一侧手足沉重麻木，口舌歪斜，舌强语謇，平素头晕头痛，耳鸣目眩，双目干涩，腰酸腿软，心烦躁热，手足心热，少眠多梦，舌质红绛或暗红，苔少或无，脉细弦或细弦数。","analysis":"肝肾阴亏，阴不敛阳，阳亢化风，脑髓损伤，故半身不遂，偏身麻木，口眼㖞斜，眩晕头痛；肝肾阴亏，失于濡养，故耳鸣，双目干涩，腰酸腿软；阴虚内热，扰及心神，故见心烦躁热，手足心热，失眠；舌质红绛或暗红，苔少或无，脉细弦或细弦数，为阴虚风动之象。","treat":"滋养肝肾，潜阳息风。","formulaRaw":"镇肝息风汤（《医学衷中参西录》）加减。","formulaName":"镇肝息风汤加减","fangjie":"天麻、钩藤平肝息风；白芍、天冬、玄参、枸杞子滋阴柔肝息风；龙骨、牡蛎、龟甲育阴潜阳；代赭石镇肝潜阳；牛膝、当归活血化瘀，且引血下行。若痰热壅盛者，去龟甲，加胆南星、竹沥、天竺黄、浙贝母等；若虚火上炎，心烦、失眠、咽干口燥明显者，加黄连、莲子心、栀子、首乌藤等；若肢体麻木、疼痛明显者，加全蝎、蜈蚣、地龙、僵蚕等；若气虚而见乏力、倦怠、言语低微者，加太子参、党参、黄芪、西洋参等。"},{"id":"s094","name":"痰热腑实证","label":"1）痰热腑实证","group":"","clinic":"突然发病，半身不遂，口眼㖞斜，舌强语謇或不语，神志欠清或昏蒙，肢体强急，痰多而黏，平素头痛眩晕，心烦易怒，伴腹胀，按之有痛感，便秘，舌质暗红，或有瘀点瘀斑，苔黄腻，脉弦滑或弦涩。","analysis":"阳明热结，腑热痰浊上扰，闭阻清窍，故神志欠清或昏蒙，头痛眩晕；风痰上扰，横窜经络，脑髓损伤，故半身不遂，口眼㖞斜，舌强语謇或不语，肢体强急；痰热阻滞阳明，故腹胀，按之有痛感，便秘；舌质暗红，或有瘀点瘀斑，苔黄腻，脉弦滑或弦涩，为内有痰热及血瘀之象。","treat":"通腑泄热，息风化痰。","formulaRaw":"桃仁承气汤（《伤寒论》）加减。","formulaName":"桃仁承气汤加减","fangjie":"大黄、芒硝、枳实通腑泄热，凉血化瘀；胆南星、黄芩、全瓜蒌清热化痰；桃仁、红花、牡丹皮凉血化瘀；牛膝引气血下行。若肝阳暴张，风动不止，肢体强痉者，加钩藤、地龙、僵蚕、石决明等；若热象明显，见身热、面赤、口臭者，加黄芩、栀子、生石膏等；若热盛伤津，口干唇裂，舌焦黑者，加天花粉、知母、麦冬、玄参等；若大便已通，痰热得减者，减量或去掉大黄、芒硝等峻下之品，防止过泻伤正。"},{"id":"s095","name":"痰火瘀闭证","label":"2）痰火瘀闭证","group":"","clinic":"突然昏仆，不省人事，牙关紧闭，口噤不开，两手握固，大小便闭，肢体强痉，面赤身热，气粗口臭，躁扰不宁，苔黄腻，脉弦滑而数。","analysis":"肝阳暴亢，阳亢风动，痰火壅盛，气血上逆，神窍闭阻，故突然昏仆，不省人事；肝风夹痰夹火，横窜经络，故牙关紧闭，口噤不开，肢体强痉；痰火闭塞腑气，故大小便闭；风火相扇，痰热内闭，故面赤身热，气粗口臭，躁扰不宁；苔黄腻，脉弦滑而数，为痰火内蕴之象。","treat":"息风清火，豁痰开窍。","formulaRaw":"羚角钩藤汤（《通俗伤寒论》）加减。另可服至宝丹（《灵苑方》）或安宫牛黄丸（《温病条辨》）以清心开窍。","formulaName":"羚角钩藤汤加减","fangjie":"羚羊角、钩藤、珍珠母、石决明平肝息风；胆南星、竹沥、半夏、天竺黄、黄连清热化痰；石菖蒲、郁金化痰开窍。若痰热阻于气道，喉间痰鸣辘辘者，可加服竹沥水、猴枣散等；若肝火旺盛，面红目赤，脉弦有力者，可加龙胆草、山栀子、夏枯草、代赭石、磁石等；若腑实热结，腹胀便秘，苔黄厚者，可加生大黄、桃仁、赤芍、元明粉、枳实等；若痰瘀互阻，舌紫有瘀斑者，可加丹参、桃仁、红花、赤芍等。"},{"id":"s096","name":"痰浊瘀闭证","label":"3）痰浊瘀闭证","group":"","clinic":"突然昏仆，不省人事，牙关紧闭，口噤不开，两手握固，肢体强痉，大小便闭，面色晦暗，静卧不烦，四肢不温，痰涎壅盛，苔白腻，脉沉滑缓。","analysis":"痰浊偏盛，上壅清窍，神机闭塞，故神昏，不省人事；肝风夹痰，窜扰经络，故牙关紧闭，口噤不开，两手握固，肢体强痉；风痰壅塞气道，故痰涎壅盛；痰浊闭塞腑气，故大小便闭；阳虚于内，故面色晦暗，静卧不烦，四肢不温；苔白腻，脉沉滑缓，为痰浊内蕴之象。","treat":"化痰息风，宣郁开窍。","formulaRaw":"涤痰汤（《奇效良方》）加减。另可服苏合香丸（《太平惠民和剂局方》）宣郁开窍。","formulaName":"涤痰汤加减","fangjie":"半夏、茯苓、橘红、竹茹化痰；郁金、丹参、石菖蒲、制南星活血豁痰开窍；僵蚕息风化痰。若肝风内动，肢体抽搐惊厥者，可加天麻、钩藤、僵蚕等；若阳虚寒盛，四肢厥冷，痰液清稀者，可加附子（制）、桂枝、干姜、肉桂等；若有化热之象，症见由静卧不烦转为微微烦躁，痰液黏稠者，可加黄芩、黄连、竹茹、淡豆豉等；若见戴阳证，为阴闭证向脱证转化的危重状态，立即停用涤痰汤及苏合香丸，急进参附汤、白通加猪胆汁汤救治。"},{"id":"s097","name":"脱证（阴竭阳亡证）","label":"（2）脱证（阴竭阳亡证）","group":"","clinic":"突然昏仆，不省人事，目合口张，肢体软瘫，鼻鼾息微，肢冷汗多，大小便自遗，舌痿，脉细弱或脉微欲绝。","analysis":"正不胜邪，元气衰微，阴阳欲绝，故突然昏仆，不省人事，目合口张，鼻鼾息微；精气耗竭，筋脉失养，故肢体软瘫；阳气亡脱，失于温煦固摄，故肢冷汗多；肾气败绝，二关不固，故大小便自遗；舌痿，脉细弱或脉微欲绝，为阴阳气血俱虚，元气衰败之象。","treat":"回阳救逆，益气固脱。","formulaRaw":"参附汤（《济生续方》）合生脉散（《内外伤辨惑论》）加减。","formulaName":"参附汤合生脉散加减","fangjie":"人参、附子（制）、干姜补气回阳；麦冬、五味子、山茱萸滋阴敛阳。若汗出不止者，可加炙黄芪、生龙骨、煅牡蛎、麻黄根、浮小麦等；若舌干，脉微者，可加玉竹、黄精、天花粉等；若面赤足冷，烦躁不安，脉极弱或突然脉大无根，为真阴亏损，阳无所附，而致虚阳上浮欲脱之证，可用地黄饮子，或用参附注射液或生脉注射液静脉滴注。\n中风病急性阶段经积极治疗，神志渐清，痰火渐平，风退瘀除，饮食稍进，渐入恢复期。恢复期和后遗症期有半身不遂、口歪、言语謇涩或失音等症状，也有郁病、痴呆等并发症，仍须积极进行康复治疗和训练。针灸与药物治疗并进可以提高疗效。药物治疗根据病情可采用标本兼顾或先标后本之法。"},{"id":"s098","name":"风痰瘀阻证","label":"1. 风痰瘀阻证","group":"","clinic":"舌强语謇或失语，口眼㖞斜，半身不遂，肢体麻木，舌质紫暗或有瘀斑，苔滑腻，脉弦滑或涩。","analysis":"风痰瘀互结，阻滞经脉，脑髓损伤，气血运行不利，故半身不遂，肢体麻木；阻于舌络，清窍失聪，故舌强语謇或失语；风邪夹痰瘀上扰头面，阻滞阳明经络，故口眼㖞斜；舌质紫暗或有瘀斑，苔滑腻，脉弦滑或涩，为痰浊、瘀血阻滞之象。","treat":"搜风化痰，行瘀通络。","formulaRaw":"神仙解语丹（《妇人大全良方》）加减。","formulaName":"神仙解语丹加减","fangjie":"天麻、胆南星、天竺黄、半夏、陈皮息风化痰；地龙、僵蚕、全蝎搜风通络；远志、菖蒲化痰宣窍；豨莶草、桑枝、鸡血藤、丹参、红花祛风活血通络。若痰热偏盛者，可加全瓜蒌、竹茹、川贝母等；若肝阳上亢，头晕头痛，面赤，舌质红，苔黄，脉弦有力者，可加钩藤、石决明、夏枯草、天麻等；若咽干口燥者，可加天花粉、天冬、玄参、生地黄等。"},{"id":"s099","name":"气虚络瘀证","label":"2. 气虚络瘀证","group":"","clinic":"偏枯不用，肢软无力，面色萎黄，舌质淡紫或有瘀斑，苔薄白，脉细涩或细弱。","analysis":"气虚血滞，脉络瘀阻，脑髓损伤，故偏枯不用；气虚失养，肌肉懈怠，故患侧肢体弛缓、瘫软、无力；气虚血少，失于荣润，故面色萎黄；舌质淡紫或有瘀斑，苔薄白，脉细涩或细弱，为气虚络瘀之象。","treat":"益气养血，化瘀通络。","formulaRaw":"补阳还五汤（《医林改错》）加减。","formulaName":"补阳还五汤加减","fangjie":"黄芪补气以行血；桃仁、红花、赤芍、当归尾养血活血，化瘀通经；地龙、牛膝引血下行兼以通络。若血虚明显，面色无华、头晕心悸者，可加白芍、熟地黄、枸杞子、首乌藤等；若肢冷、畏寒者，阳失温煦，可加桂枝、附子（制）、干姜、巴戟天等；若腰膝酸软者，可加续断、桑寄生、杜仲、山茱萸等；若脾胃虚弱，食少便溏者，可加党参、白术、山药、茯苓等。"},{"id":"s100","name":"肝肾亏虚证","label":"3. 肝肾亏虚证","group":"","clinic":"半身不遂，患肢僵硬拘挛变形，舌强不语，或偏瘫，肢体肌肉萎缩，舌质红，脉细，或舌质淡红，脉沉细。","analysis":"肝肾亏虚，阴血不足，脑髓损伤，筋骨失养，故见半身不遂，患肢僵硬拘挛变形，肢体肌肉萎缩；肾精亏虚，不能上承，舌络失养，故见舌强不语；舌质红，脉细，为肝肾阴虚之象；舌质淡红，脉沉细，为阴阳两虚之象。","treat":"滋养肝肾。","formulaRaw":"左归丸（《景岳全书》）合地黄饮子（《黄帝素问宣明论方》）加减。","formulaName":"左归丸合地黄饮子加减","fangjie":"干地黄、制首乌、枸杞子、山萸肉补肾益精；麦冬、石斛养阴生津；当归、鸡血藤养血和络。若腰酸腿软较甚者，可加杜仲、桑寄生、牛膝等；若肾阳虚者，可加巴戟天、肉苁蓉、淫羊藿等；若阳虚虚火上浮，可加附子（制）、肉桂、干姜等；若夹有痰浊，可加石菖蒲、远志、茯苓等。"}],"linchuang":["详辨中风之缺血与出血。中风急性期应及时借助头颅MRI或CT等检查，明确是缺血性中风还是出血性中风，制订急性期合理的辨治方案。出血性中风急性期，大多数表现为中脏的风阳痰火闭证或中腑之腑实瘀热证，有的可表现为脱证，一般超早期应慎用活血化瘀法。缺血性中风急性期多见中经络的重症，早期即可采用活血化瘀法治疗。对于风阳痰火证，虽然神志清楚，仍应防其病情恶化，临证时须严密观察。","出血性中风可配凉血化瘀法。脑出血或蛛网膜下腔出血恢复期，除痰热阻窍外，尚因气血逆乱，络热血溢，而致瘀热阻窍，临床可见面唇青紫，舌绛或紫暗或暗红，可配合凉血化瘀止血法，以犀角地黄汤与桃仁承气汤为基础方治疗，以行瘀热，也有助于止血。","正确使用通下之法。中腑因瘀热内阻，腑气不通，邪热上扰，神机失用，应及时使用通腑泄热之法，有助于邪从下泄。中脏阳闭证，风阳痰火炽盛，内闭神机，因邪热搏结，亦可出现腹满，便秘，小溲不通，苔黄腻，脉弦实有力，亦应配用通下之法，使大便通畅，痰热下泄，则神志可清。但正虚明显、元气欲脱者忌用。","正确使用虫类药。虫类药作为攻窜通络之品，具有活血化瘀、搜风息风、通络止痛及化痰散结之功，在中风恢复期和后遗症期的治疗中有着独特优势。此阶段风、痰、瘀等邪气深入筋骨经络，顽固难除，虫类药以其“搜剔经络之邪”和“破逐凝滞之瘀”之力，对于改善后遗症期偏瘫、肢体疼痛麻木、言语不利等症状效果显著，是中医药治疗中风的一大特色和利器。但此类药多力猛性峻，适用于中风实证或虚实夹杂者，对于虚证、体质极度虚弱者慎用。多数虫类药具有一定毒性（如全蝎、蜈蚣），需经过严格炮制以减毒，严格控制剂量。临证时常需与益气养血、滋补肝肾等扶正药物并用，做到“攻邪而不伤正”。","预防中风并发症及复发。中风经过救治后，部分患者可逐渐出现近事遗忘、反应迟钝者，应注意防治中风后痴呆，以滋补肝肾、化痰开窍、活血通络等法治疗。并发中风后抑郁者，按郁证治疗。若患者在中风恢复期再次出现眩晕、头痛、肢体麻木等，应积极采取措施，可选用息风化痰、活血通络法治疗，防止中风复作。"],"yufang":["预防中风发生，针对危险因素采取干预措施，如避免内伤积损，减少情志过极，改变不良饮食习惯，戒烟酒，保持大便通畅，控制体重，坚持体育锻炼等，以降低中风的发生风险。重视中风先兆症状，如中老年人出现眩晕、头痛、一过性视物不清、言语不利、手足麻木或无力等，应及时诊治，防止病情进展。","中风急性期调护，密切观察病情及情绪变化，注意神志、瞳孔、脉搏、血压等情况，对中风后情绪低落或波动者及时识别与干预。保持良肢位，加强肢体、呼吸道、口腔及皮肤护理，防治压疮、肺部感染等并发症。恢复期调护，尽早进行言语、吞咽及肢体功能康复训练，可配合针灸、推拿、理疗等，以循序渐进为原则。后遗症期调护，给予患者社会回归支持，逐步恢复社会功能。"],"attachIds":[]},{"id":"d016","name":"痴呆","kind":"main","parent":null,"chapterNo":"第十九章","chapterName":"痴呆","yinbing":[{"t":"p","x":"本病的发病多因先天不足，或后天失养，或年迈体虚，或久病不复，导致脾气亏虚，气血生化乏源，痰湿内生，上扰清窍，或肾虚精少，髓海失养，或兼气滞、痰阻、血瘀互结于脑络，伤及脑髓，髓减脑消，元神失养，而渐致痴呆。或因久郁不解，或中风、外伤，或外感热病等，导致损伤脑络脑髓，脑气不通，神明不清，而突发痴呆。"},{"t":"b","x":"1. 禀赋不足"},{"t":"p","x":"先天禀赋不足，髓海本虚，延至成年，以致髓海渐空，元神失养，发为痴呆。"},{"t":"b","x":"2. 后天失养"},{"t":"p","x":"起居失宜，或饮食失节，或劳逸失度等，导致脾胃虚弱，痰湿内生，上蒙清窍，而发为痴呆。"},{"t":"b","x":"3. 年老肾虚"},{"t":"p","x":"年老肾衰，肾精日亏，不能生髓，髓海空虚，髓减脑消，则神机失用，而成痴呆。"},{"t":"p","x":"年高气血运行迟缓，血脉瘀滞，脑络瘀阻，亦可使神机失用而发生痴呆。"},{"t":"b","x":"4. 情志所伤"},{"t":"p","x":"郁怒伤肝，肝气郁结，肝气乘脾，或久思伤脾，脾虚气血生化乏源，气血不足，脑失所养，或脾失健运，聚湿生痰，蒙蔽清窍，神明被扰，神机失用；肝郁日久化火，上扰神明，则性情烦乱，哭笑无常；或惊恐伤肾，肾虚精亏，髓海失充，脑失所养，皆致神机失用，神情失常，发为痴呆。"},{"t":"b","x":"5. 久病耗损"},{"t":"p","x":"患中风、眩晕等病日久，或失治误治，耗伤正气，肝肾亏损，气血虚极，致脑髓失养或脑窍不荣；久病入络，血行不畅，血瘀、痰浊郁久化火，痰瘀火毒炽盛，犯于脑脉，伤及脑髓，神机失用，而发为痴呆。"},{"t":"p","x":"此外，颅脑损伤或外感热毒，损伤脑络，而发为痴呆。"}],"bingji":[{"t":"p","x":"痴呆的基本病机为髓减脑消，元神失养，神机失用。"},{"t":"p","x":"病变部位在脑，与心、肝、脾、肾功能失调相关，尤其与肾虚关系密切。"},{"t":"p","x":"病理性质属本虚标实。"},{"t":"p","x":"病理因素主要为痰、瘀、火。"},{"t":"p","x":"三者多相互影响，发生病机转化，如痰浊、瘀血相兼致痰瘀互结，使病情缠绵难愈。"},{"t":"p","x":"而肝郁、痰浊、血瘀可以化热，而形成肝火、痰热、瘀热，上扰清窍。"},{"t":"p","x":"若进一步发展，痰瘀所化之火郁而成毒，可耗伤肝肾之阴，致水不涵木，阴不制阳，肝阳上亢，虚风内动，上扰清窍，损伤脑髓，使痴呆加重。"},{"t":"p","x":"虚实之间可相互转化。"},{"t":"p","x":"痰浊、瘀血日久，若损及心脾，则气血不足，或耗伤心脾之阴，元神失养，或伤及肝肾，则阴精不足，脑髓失养，可转化为痴呆虚证。"},{"t":"p","x":"而虚证病久，气血亏乏，脏腑功能受累，气血运行失畅，痰瘀加重，又可因虚致实，虚实兼夹，而成难治之证。"},{"t":"p","x":"痴呆总体预后不佳，多呈渐进性加重，早期识别和干预可一定程度上延缓痴呆进展。"}],"zhenduan":[{"t":"ol","items":["1. 痴呆早期多见善忘，包括短期记忆减退与长期记忆减退。","2. 智能缺损，包括失语（如找词困难、语言不连贯、错语）、失认（如不能辨认熟人或物体）、失用（如系错纽扣、不会使用熟悉的电器设备等）、执行不能（如完成买菜、缴费等任务困难）等1项或1项以上损害。","3. 日常生活及工作能力下降，即生活或工作能力部分或完全丧失。","4. 除外引起智能缺损的其他原因，如癫狂、谵妄、郁病等。","5. 阿尔茨海默病一般多发于女性，起病隐匿，进行性发展，早期常无症状，或表现为轻度记忆力下降等认知障碍；而血管性痴呆在男性中更常见，呈波动性进展，早期记忆损害不明显，常见执行功能受损。"]}],"jianbie":[{"t":"b","x":"1. 健忘"},{"t":"p","x":"健忘既是一种独立疾病，又是痴呆的早期表现或首发症状，需要鉴别。"},{"t":"p","x":"健忘是遇事善忘、部分能回忆的一种病证，一般无渐进性加重，也无智能减退，生活能力始终正常。"},{"t":"p","x":"痴呆的健忘症状通常有渐进性加重，且伴有智能减退，生活能力同时受损。"},{"t":"p","x":"跟踪随访有助于鉴别诊断。"},{"t":"b","x":"2. 癫狂"},{"t":"p","x":"痴呆和癫狂病程中均可存在形神失常、智能缺损症状。"},{"t":"p","x":"但癫狂早期即以沉闷寡言，情感淡漠，语无伦次，或喃喃自语，静而少动等情志失常为主，或以喧扰不宁、烦躁不安、妄见妄闻、妄思奇行甚至狂越等形神失控症状为主，迁延至后期，也会发生智能缺损。"},{"t":"p","x":"痴呆早期即以善忘、智能缺失、生活失能等症状为主，中后期会有烦躁不安、急躁易怒、妄见妄闻、妄思离奇等形神失常症状，少见喧扰不宁、妄行狂越等严重形神失控症状。"},{"t":"b","x":"3. 郁病"},{"t":"p","x":"痴呆和郁病均可能存在抑郁情绪表现。"},{"t":"p","x":"但郁病以抑郁症状为主，如心境不佳、哭泣、少言寡语，也常主诉记忆减退、注意力不集中等类似痴呆的症状，但无智能缺损和生活失能情况，抗抑郁治疗通常有明显效果。"},{"t":"p","x":"痴呆以智能缺失症状为主，如善忘、智能缺损、生活失能，早期可有情绪异常，晚期抑郁情绪消失，以淡漠多见。"}],"bianzheng":[{"t":"b","x":"1. 辨虚实"},{"t":"p","x":"本病乃本虚标实之证，因而辨证时需辨明标本虚实。本虚者，应辨明精、气、血之别；标实者，应辨明痰、瘀、火之异。本虚主要以神气不足、面色失荣、形体消瘦、言行迟钝为特征，标实常有因邪蒙神窍而引起的情志、性格方面或亢奋或抑制的明显改变。临床上本病以虚实夹杂者多见，或以正虚为主，兼有邪实，或以邪实为主，兼有正虚。疾病后期多见虚极毒盛，智能丧失殆尽，应分清虚实，辨明主次。"},{"t":"b","x":"2. 辨脏腑"},{"t":"p","x":"本病病位在脑，但与肾、心、肝、脾相关。若年老体衰、头晕目眩、记忆认知能力减退、神情呆滞、齿枯发焦、腰酸腿软、步履艰难，为病在脑与肾；若兼见双目无神、筋惕肉瞤、毛甲无华，为病在脑与肝肾；若兼见食少纳呆、气短懒言、口涎外溢、四肢不温、五更泄泻，为病在脑与脾肾；若兼见失眠多梦、五心烦热，为病在脑与心肾。"}],"zhize":"痴呆的治疗以补虚泻实为基本治则。补虚常用补肾填精益髓、健脾补益气血等法以治其本，泻实常用开郁逐痰、活血通窍、平肝泻火等法以治其标。\n虚证者多以肾虚为主，重在补肾；实证者多痰浊、血瘀、火邪并现，应化痰、祛瘀、泻火交替或并行。如各证相互交叉或重叠，治法、方药应随机调整。如痰盛常因脾虚，化痰时须兼补脾。疾病后期因虚极而毒盛，应用解毒化浊重剂时，勿忘大补元气。此外，移情易性、认知康复与功能锻炼亦有助于本病的康复。","syndrome":[{"id":"s101","name":"髓海不足证","label":"1. 髓海不足证","group":"","clinic":"忘失前后，兴趣缺失，起居怠惰，或倦怠嗜卧，行走缓慢，动作笨拙，甚则振掉，腰膝酸软，齿枯发焦，脑转耳鸣，目无所见，舌瘦质淡，脉沉细。","analysis":"先天禀赋不足或老年肾精亏虚，髓海生化乏源，神机失用，故见忘失前后，兴趣缺失；肾虚髓亏，齿骨失充，故见行动迟缓，腰膝酸软，齿枯发焦，甚则振掉；肾精不足，不能上荣清窍，故见脑转耳鸣；舌瘦质淡，脉沉细，为髓海不足之象。","treat":"滋补肝肾，填精补髓。","formulaRaw":"七福饮（《景岳全书》）加减。","formulaName":"七福饮加减","fangjie":"熟地黄、枸杞子、山茱萸、杜仲滋补肝肾，填精益髓；人参、山药、白术、炙甘草益气健脾；石菖蒲化痰宣窍；当归养血补肝；远志安神益智。若病情较重，加肉苁蓉、知母、鹿角胶、龟甲胶、阿胶等；头晕耳鸣，目眩或视物不清，加天麻、钩藤、珍珠母、煅牡蛎、生地黄；心烦溲赤，舌红少苔，脉细而弦数，用知柏地黄丸加丹参、莲子心等；舌质红，苔黄腻者，加清心滚痰丸，俟痰热化净，再投滋补之品。"},{"id":"s102","name":"脾肾亏虚证","label":"2. 脾肾亏虚证","group":"","clinic":"迷惑善忘，兴趣缺失，反应迟钝，易惊善恐，食少纳呆，或呃逆不食，口涎外溢，四肢不温，小便浑浊，夜尿频多，或二便失禁，舌质淡，舌体胖大，有齿痕，苔白或腻，脉沉细弱，两尺尤甚。","analysis":"脾肾两虚，精微不化，髓海失养，神机失用，故见迷惑善忘、反应迟钝等；脾阳失运，则食少纳呆，呃逆不食；阳虚失于温煦，则四肢不温；肾阳虚，则固摄无权，故见涎溢，尿频，或二便失禁；舌淡胖，有齿痕，脉沉弱，为脾肾亏虚之象。","treat":"温补脾肾，养元安神。","formulaRaw":"还少丹（《洪氏集验方》）加减。","formulaName":"还少丹加减","fangjie":"熟地黄、枸杞子、山茱萸补肾填精；肉苁蓉、巴戟天、小茴香助命火，补肾气；杜仲、牛膝补益肝肾；人参、白术、茯苓、山药益气健脾；石菖蒲开窍；远志安神益智。若呃逆不食，口涎外溢，加黄芪、清半夏、炒麦芽；夜尿频多，加菟丝子、锁阳。"},{"id":"s103","name":"气血不足证","label":"3. 气血不足证","group":"","clinic":"善忘茫然，找词困难，不识人物，言语颠倒，多梦易惊，少言寡语，倦怠少动，面唇无华，爪甲苍白，纳呆食少，大便溏薄，舌质淡，苔白，脉细弱。","analysis":"气血亏虚，无以上荣于脑，髓海失养，神机失用，故见善忘茫然，找词困难，言语颠倒等；血不养心，则多梦易惊；气虚，则倦怠少动，少言寡语；血虚不荣，则面唇爪甲无华；脾失健运，则纳呆便溏；舌淡苔白，脉细弱，乃气血不足之象。","treat":"益气健脾，养血安神。","formulaRaw":"归脾汤（《严氏济生方》）加减。","formulaName":"归脾汤加减","fangjie":"人参、黄芪、白术、炙甘草益气健脾；龙眼肉、当归养血；炒枣仁、茯神、远志安神益智。若脾虚日重，加茯苓、山药；入睡困难或夜间行为异常，加柏子仁、首乌藤、珍珠母、煅牡蛎。"},{"id":"s104","name":"痰浊蒙窍证","label":"4. 痰浊蒙窍证","group":"","clinic":"多忘不慧，表情呆滞，迷路误事，不言不语，忽歌忽笑，洁秽不分，亲疏不辨，口吐痰涎，纳呆呕恶，体肥懒动，舌苔黏腻浊，脉弦而滑。","analysis":"痰浊内阻，上蒙清窍，神机失用，故见表情呆滞、多忘不慧等；脾为生痰之源，痰阻中焦，故呕恶、纳呆、多涎；体肥为痰湿素盛之体；舌苔黏腻，脉弦滑，为痰浊蒙窍之象。","treat":"化痰开窍，健脾醒神。","formulaRaw":"洗心汤（《辨证录》）加减。","formulaName":"洗心汤加减","fangjie":"石菖蒲、郁金、远志化痰开窍；人参、白术、甘草健脾益气；半夏、陈皮、枳实、竹茹、生姜理气化痰泄浊；茯神、酸枣仁宁心安神；神曲、麦芽消食和胃。若脾虚明显，加黄芪、山药、砂仁等；头重如裹，哭笑无常，喃喃自语，口多涎沫者，重用陈皮、半夏，加胆南星、佩兰、白豆蔻、全瓜蒌等。言语颠倒，歌笑不休，甚至反喜污秽者，改用转呆丹。"},{"id":"s105","name":"瘀阻脑络证","label":"5. 瘀阻脑络证","group":"","clinic":"喜忘，神呆不慧或不语，反应迟钝，动作笨拙，或妄思离奇，头痛难愈，面色晦暗，舌质紫或有瘀斑，脉细弦或沉迟。","analysis":"瘀血内结，脑络痹阻，神机失用，故见神呆善忘；瘀血内停，络脉不通，故头痛位置固定，缠绵不愈；血行不畅，不能上荣于面，故面色晦暗；舌质紫或有瘀斑，脉细弦，为瘀阻脑络之象。","treat":"活血化瘀，通窍醒神。","formulaRaw":"通窍活血汤（《医林改错》）加减。","formulaName":"通窍活血汤加减","fangjie":"桃仁、红花、赤芍、川芎、丹参活血化瘀；地龙、水蛭通络逐瘀；石菖蒲、郁金芳香开窍；老葱、生姜通阳宣窍；珍珠母、柏子仁安神定惊；白芍、大枣敛阴，以防辛散太过。如气血不足，加当归、生地黄、党参、黄芪；久病血瘀化热，加牡丹皮、生地黄、夏枯草、栀子等；瘀血阻窍动风者，加全蝎、蜈蚣、天麻、三七。"},{"id":"s106","name":"心肝火旺证","label":"6. 心肝火旺证","group":"","clinic":"急躁易怒，烦躁不安，妄闻妄见，妄思奇行，或举止异常，多梦，或梦幻游离，或梦寐喊叫，头晕目眩，头痛，耳鸣如潮，口臭口疮，小便短赤，大便干结，舌质红或绛，苔黄或黄腻，脉弦滑或弦数。","analysis":"肝火亢盛，则急躁易怒；心火扰神，则烦躁不安；火热扰神，故出现多梦、幻觉、妄想及各种异常行为；肝火上炎，则头晕、头痛、耳鸣；心胃火盛，则口臭、口疮；热盛伤津，则尿赤便干；舌红苔黄，脉弦数，为心肝火旺之象。","treat":"清心平肝，安神定志。","formulaRaw":"天麻钩藤饮（《中医内科杂病证治新义》）加减。","formulaName":"天麻钩藤饮加减","fangjie":"栀子、黄芩、黄连、丹皮苦寒直折心肝之火；天麻、钩藤、石决明平肝潜阳；牛膝、益母草、白芍活血调血，引火下行；夜交藤、茯神养心安神。若妄闻妄见、妄思奇行，加生地黄、山茱萸、珍珠母；苔黄黏腻，加天竺黄、郁金、胆南星；便秘，加酒大黄、枳实、厚朴；烦躁不安，为热毒炽盛，加安宫牛黄丸。"},{"id":"s107","name":"热毒内盛证","label":"7. 热毒内盛证","group":"","clinic":"无欲无语，迷蒙昏睡，不识人物，神呆遗尿，或二便失禁，身体蜷缩不动，或躁扰不宁，甚则狂越，或谵语妄言，肢体僵硬，或颤动，或痫痉，舌质红绛，苔少，或苔黏腻浊，或腐秽厚积，脉数。","analysis":"火热久蕴，内生浊毒，败坏脑络脑髓，形神俱损，故见神昏无语、不识人物等；毒扰神明，或见蜷卧不动，或见躁扰狂越；热极生风，而躁扰、痫痉，表现多变；舌红绛，脉数，乃毒盛之危候。","treat":"清热解毒，通络达邪。","formulaRaw":"黄连解毒汤（《外台秘要》）加减。","formulaName":"黄连解毒汤加减","fangjie":"此方具有清泻三焦热毒之效。黄连清泻心火，黄芩清上焦之火，黄柏泻下焦之火，栀子清泻三焦之火，导热下行，引邪热从小便而出。若痰迷热闭，神惫如寐，加石菖蒲、郁金、天竺黄，或合用至宝丹；阴虚内热，虚极生风，加生地黄、天麻、地龙、全蝎、蜈蚣等，或合紫雪丹。泻火之品苦寒之性峻利，若用药后患者出现腹痛、腹泻等症状，可酌情减量或停药，以防元气被伤。"}],"linchuang":["首重补肾以治本。肾藏精，精充髓，髓荣脑，“脑为髓之海”。清·程国彭《医学心悟》谓：“肾主智，肾虚则智不足。”年老肾衰，肾虚不能化精以充髓海，脑失所养，则神机不用，而发为痴呆。故肾虚是痴呆的核心病机，治疗首应补肾。临证时应注意阴阳双补，可根据肾阴阳之偏衰有所侧重，并酌用血肉有情之品。补肾温阳常用仙茅、淫羊藿、巴戟天、补骨脂、益智仁等，滋肾填精常用熟地黄、山茱萸、枸杞子、菟丝子、女贞子、黄精、鹿角胶、龟甲胶、五味子等。临床应注意缓补而非峻补，或补中寓通，补而不腻，以免滋生痰浊。","化痰活血以治标。痴呆病程长且病情缠绵难解，难以治愈，怪病多痰，久病多瘀，痰瘀在本病的发病机制中具有重要的作用。痰瘀不除，本病难愈。化痰活血是临床治疗本病的常用方法。化痰常用浙贝母、胆南星、天竺黄、陈皮、茯苓、半夏等；活血常用赤芍、丹参、红花、大黄、桃仁、川芎、三七、葛根、土鳖虫、地龙等。根据标本虚实轻重，将化痰活血法与补虚法联合应用。","活用开窍醒神法及祛风药。痴呆多由痰瘀蒙窍而致神机失用，故可以芳香之品开窍醒神，以增强临床疗效，常用冰片、石菖蒲、远志、郁金等。另外，应注意祛风药的运用，一则脑居颠顶，为诸阳之会，惟风药辛宣，方可疏通经脉，升发清阳之气贯注于脑，以壮髓海；二则阳升气旺，有助于化痰逐瘀。常用祛风药有羌活、防风、藁本、白芷、苍耳子、柴胡、升麻、蝉蜕等。","痴呆晚期病情深重，病势难以逆转，为目前治疗难点，临床以预防感染、营养支持、日常护理为主，故痴呆治疗应注重及早筛查，及早干预，预防其发展。"],"yufang":["年老体弱或久病者，饮食宜清淡，少食肥甘厚味，戒烟酒，多食具有补肾益精作用的食物。均衡饮食、适当体育锻炼等具有预防或延缓痴呆的作用。","精神调理、认知康复、饮食调节、身体运动等对痴呆患者治疗与康复非常重要。帮助患者维持或恢复有规律的生活习惯。指导患者正确认识和对待疾病，解除情志因素刺激，进行耐心细致的认知康复。对重症患者，应进行生活照料，防止因大小便自遗及长期卧床引发压疮、感染等。要防止患者自伤或他伤，防止跌倒而发生骨折。注意照护患者防止外出走失等。"],"attachIds":[]},{"id":"d017","name":"癫狂","kind":"main","parent":null,"chapterNo":"第二十章","chapterName":"癫狂","yinbing":[{"t":"p","x":"癫狂的发生与七情内伤、饮食失节、禀赋异常相关，这些因素损及脏腑功能，导致阴阳失衡，“重阳者狂，重阴者癫”。火热扰窍，神明错乱而发狂；痰气郁结，蒙蔽脑窍，或心肝脾虚，神明失养而发癫。"},{"t":"b","x":"1. 禀赋不足"},{"t":"p","x":"禀赋异常，或胎儿在母腹中有所大惊，胎气被扰，升降失调，阴阳失衡，致使元神虚损，生后一有所触，则气机逆乱，发为本病。"},{"t":"b","x":"2. 七情内伤"},{"t":"p","x":"恼怒郁愤，肝郁不解，气郁痰结，或血行凝滞，气血不能上荣脑髓，神机失用，或肝郁化火，火窜扰神，气机逆乱，或情志过激，勃然大怒，引动肝胆木火，冲心犯脑，神明失其主宰，或猝受惊恐，神明失主，神机逆乱，发为本病。"},{"t":"b","x":"3. 饮食不节"},{"t":"p","x":"过食肥甘膏粱之品，损伤脾胃，酿成痰浊，复因心火暴张，痰随火升，或贪杯好饮，素有内湿，郁而化热，充斥胃肠，腑热上冲，扰动元神而发病。"},{"t":"p","x":"明·张介宾《景岳全书·癫狂痴呆》云：“癫病多由痰气，凡气有所逆，痰有所滞，皆能壅闭经络，格塞心窍。”"}],"bingji":[{"t":"p","x":"癫狂的基本病机为阴阳失调，神机逆乱。"},{"t":"p","x":"脏腑功能失调，产生气滞、痰结、火郁、血瘀等病理因素，蒙蔽脑窍，阴阳失衡，神明逆乱，而引起精神异常。"},{"t":"p","x":"《难经·二十难》谓“重阳者狂，重阴者癫”，重阳者乃言火热亢盛而致狂证，重阴者乃言痰气郁结或心肝脾虚而致癫证。"},{"t":"p","x":"病变部位主要在脑，累及肝、心、胆、脾，久而伤肾。"},{"t":"p","x":"癫证属阴，狂证属阳，二者有所不同。"}],"zhenduan":[{"t":"ol","items":["1. 癫证以神情抑郁、表情淡漠、沉默呆钝、语无伦次或喃喃自语、静而少动或静而多喜为常见症状；狂证以神情亢奋、狂躁刚暴、喧扰不宁、毁物打骂、动而多怒为常见症状。","2. 不同年龄和性别均可发病，但青壮年多见。","3. 有癫狂家族史，或脑外伤史，或久郁、久思、易怒病史。","4. 近期可有暴受惊恐或突遭变故等诱因。","5. 排除药物、中毒、外感原因所致。"]}],"jianbie":[{"t":"b","x":"1. 痫证"},{"t":"p","x":"均可有神志异常。"},{"t":"p","x":"但痫证是以突然仆倒、昏不知人、两目上视、口吐涎沫、四肢抽搐为特征的发作性病证，与本病不难鉴别。"},{"t":"b","x":"2. 谵语、郑声"},{"t":"p","x":"均可有神志异常、言语错乱等症状。"},{"t":"p","x":"谵语是以神志不清、胡言乱语为特征的急性重症，郑声是疾病晚期出现的神志不清、不能自主、语声低怯、断续重复而语不成句的垂危征象，与癫狂之神志错乱、喃喃自语、出言无序或躁狂骂詈自有不同。"}],"bianzheng":[{"t":"b","x":"1. 辨癫与狂"},{"t":"p","x":"癫证以精神抑郁、表情淡漠、沉默呆钝、语无伦次或喃喃自语、静而少动为主要症状。狂证以精神亢奋、狂躁刚暴、喧扰不宁、毁物打骂、动而多怒为主要症状。"},{"t":"b","x":"2. 辨虚实"},{"t":"p","x":"癫证初发，多为痰气郁结，属实。病久痰气结甚，正气渐耗，以虚实夹杂为主。狂证初起，由痰火实邪扰乱神明而成，属实。病久则火灼阴液，渐成阴虚火旺之证，属虚。一般而言，亢奋症状突出、舌苔黄腻、脉弦滑数者，以痰火实邪为主，而焦虑、不眠、精神疲惫、舌红少苔或无苔、脉细数者，以正虚为主。"},{"t":"b","x":"3. 辨轻重"},{"t":"p","x":"癫证初发，起病较缓，病情较轻。若病情迁延日久，正气渐耗，痰气郁结日深，则愈发愈频，正气愈衰，痰气郁结日重，虚实互为因果，病深难复。癫狂至晚期，正气大亏，邪气犹存，极为难治。狂证初起，病情相对较急，出现精神亢奋、狂躁、喧扰不宁、毁物大骂等症，病情尚轻；若病情未及时控制，可发展为登高而歌、弃衣而走、不避亲疏、不避水火等。"}],"zhize":"癫狂的治疗总以调整阴阳为基本治则，以平为期。初期多以实邪为主，治当理气解郁、泻火豁痰、化瘀通窍；后期以正虚为主，治当补益心脾、滋阴养血、调整阴阳。明·吴昆《医方考·癫狂》云：“初病者，宜泻其实；久病者，宜安其神。”同时，移情易性，加强护理，既是治病的需要，也是防止发生意外的必要措施。","syndrome":[{"id":"s108","name":"痰气郁结证","label":"1. 痰气郁结证","group":"","clinic":"精神抑郁，表情淡漠，沉默痴呆，时时太息，言语无序，或喃喃自语，多疑多虑，喜怒无常，秽洁不分，不思饮食，舌质红，苔白腻，脉弦滑。","analysis":"情志不遂，肝气郁结，横逆犯脾，津液失于布散，滞而为痰，气郁痰结，蒙蔽清窍，故出现表情淡漠、沉默痴呆等种种精神异常的证候。痰浊中阻，故不思饮食，舌苔腻，脉弦滑。","treat":"疏肝解郁，化痰醒神。","formulaRaw":"逍遥散（《太平惠民和剂局方》）合涤痰汤（《奇效良方》）加减。前方重在疏肝解郁，后方重在化痰开窍。","formulaName":"逍遥散合涤痰汤加减","fangjie":"柴胡、白芍、当归疏肝养血柔肝；茯苓、白术健脾益气；枳实、香附、木香理气解郁；半夏、陈皮、竹茹、制南星理气化痰；石菖蒲、郁金解郁醒神。若痰浊甚者，加控涎丹，临卧姜汤送下；痰浊壅盛，胸膈瞀闷，口多痰涎，脉滑大有力，形体壮实者，暂用三圣散取吐，劫夺痰涎，因药性猛悍，自当慎用；神思迷惘，表情呆钝，言语错乱，目瞪不瞬，舌苔白腻，为痰迷心窍，加苏合香丸；不寐易惊，烦躁不安，舌红苔黄，脉滑数者，为痰郁化热，痰热互结，干扰心神所致，加黄连、黄芩、栀子；病程日久，舌质紫暗，或有瘀点、瘀斑，脉弦涩，加丹参、郁金、红花、川芎等。"},{"id":"s109","name":"心脾两虚证","label":"2. 心脾两虚证","group":"","clinic":"神思恍惚，魂梦颠倒，心悸易惊，善悲欲哭，肢体困乏，言语无序，面色苍白，舌质淡，苔薄白，脉细弱无力。","analysis":"癫病日久，心血内亏，心神失养，故见心悸易惊，神思恍惚，善悲欲哭。血少气衰，脾失健运，故饮食量少，肢体困乏。舌色淡，苔薄白，脉细弱无力，均为心脾两亏，气血亏虚之象。","treat":"健脾养心，解郁安神。","formulaRaw":"养心汤（《证治准绳》）合越鞠丸（《丹溪心法》）加减。前方健脾养心安神，后方行气解郁，调畅气机。","formulaName":"养心汤合越鞠丸加减","fangjie":"人参、黄芪、甘草补脾益气；香附、川芎行气解郁，神曲、苍术、茯苓运脾化湿，以绝生痰之源；当归养心血；茯苓、远志、柏子仁、酸枣仁、五味子宁心安神。若畏寒蜷缩，卧姿如弓，小便清长，下利清谷，属肾阳不足，加补骨脂、巴戟天、肉苁蓉等；心气耗伤，营血内亏，悲伤欲哭者，仿甘麦大枣汤之意加小麦、大枣。"},{"id":"s110","name":"痰火扰神证","label":"1. 痰火扰神证","group":"","clinic":"性情急躁，头痛失眠，两目怒视，面红目赤，突然狂暴无知，逾垣上屋，骂詈不避亲疏，或毁物伤人，或哭笑无常，登高而歌，弃衣而走，不食不眠，舌质红绛，苔多黄腻，脉弦滑数。","analysis":"暴怒伤肝，肝火暴张，鼓动阳明痰热，上扰神明，故性情急躁，头痛失眠；蒙蔽清窍，则狂暴无知，骂詈不避亲疏；阳盛则四肢实，实则能登高而气力逾常；肝火暴盛，上扰清窍，故头痛，目赤，面红。火属阳，阳主动，故发病急剧，狂暴不休；舌质红绛，苔黄腻，脉弦滑数，均为痰火之象。","treat":"镇心涤痰，清肝泻火。","formulaRaw":"生铁落饮（《医学心悟》）加减。","formulaName":"生铁落饮加减","fangjie":"生铁落、钩藤平肝重镇，降逆泻火；胆南星、川贝母、橘红祛痰化浊；石菖蒲、远志、茯神、辰砂宣窍宁心安神；天冬、麦冬、玄参养阴清热。若痰火壅盛而舌苔黄腻垢，加礞石、黄芩、大黄，或加安宫牛黄丸；脉弦实，肝胆火盛者，加当归龙荟丸。"},{"id":"s111","name":"痰热瘀结证","label":"2. 痰热瘀结证","group":"","clinic":"癫狂日久不愈，面色晦滞而秽，情绪躁扰不安，多言无序，恼怒不休，甚至登高而歌，弃衣而走，妄见妄闻，妄思离奇，头痛，心悸而烦，舌质紫暗或有瘀斑，苔少或薄黄而干，脉弦细或细涩。","analysis":"癫狂日久入络，郁而化火，痰热郁结，扰乱神明，故情绪躁扰，多言无序；痰浊上泛，则面色晦秽；痰热蒙窍，乃见妄闻妄见，妄思离奇；痰热上扰，清阳不升，遂致头痛；心神被扰，故心悸而烦；舌脉亦为痰热瘀结之象。","treat":"豁痰化瘀，调畅气血。","formulaRaw":"癫狂梦醒汤（《医林改错》）加减。","formulaName":"癫狂梦醒汤加减","fangjie":"半夏、胆南星、陈皮理气豁痰；柴胡、香附、青皮疏肝理气；桃仁、赤芍、丹参活血化瘀。若蕴热重，加黄连、黄芩；蓄血内结者，加服大黄䗪虫丸；不饥不食者，加白金丸。"},{"id":"s112","name":"火盛伤阴证","label":"3. 火盛伤阴证","group":"","clinic":"狂证日久，病势较缓，时作时止，精神疲惫，情绪焦虑，烦躁不眠，形瘦面红，五心烦热，舌质红，少苔或无苔，脉细数。","analysis":"狂病不已，耗气伤阴，气不足则狂势渐减，精神疲惫，阴不足则不能制心火，虚火上炎，故见烦躁，形瘦，面红，舌红。心神失养，又为虚火所扰，故多言善惊。脉细数，亦为阴虚有热之象。","treat":"滋阴降火，安神定志。","formulaRaw":"二阴煎（《景岳全书》）合琥珀养心丹（《证治准绳》）加减。前方重在滋阴降火，安神宁心，后方偏于滋养肾阴，镇惊安神。","formulaName":"二阴煎合琥珀养心丹加减","fangjie":"黄连、黄芩清心泻火，生地黄、麦冬、玄参、阿胶、白芍滋阴养血，共奏泻南补北之用；人参、茯神、酸枣仁、柏子仁、远志、石菖蒲交通心肾，安神定志；生龙齿、琥珀、朱砂镇心安神。若痰火未平，舌苔黄腻，质红，加胆南星、天竺黄；心火亢盛者，加朱砂安神丸；睡不安稳者，加孔圣枕中丹。"}],"linchuang":["注意癫狂的先兆症状。癫狂患者在发病前，往往有精神异常的先兆。如患者平素性格内向，心情抑郁，遇有志意不遂或猝受惊恐而出现神情淡漠，沉默不语，或喜怒无常，坐立不安，睡眠障碍，饮食变化等症状者，均应考虑癫狂的可能，应及时就诊，力争早诊断，早治疗，可避免病情发展及复发。","掌握吐下逐痰法的应用。癫狂的基本病理因素为痰，或痰凝气滞，或痰郁化火。故初病体实，饮食不衰者，可予吐下劫夺，荡涤痰浊，用药如大黄、礞石、芒硝、芫花之类。若痰浊壅盛，胸膈瞀闷，口多痰涎，脉滑大有力，形体壮实者，可先用三圣散取吐，劫夺痰涎，以吐为度，不必尽剂，以免中毒。倘吐后形神俱乏，宜及时饮食调养，亦可用人参扶正。必要时可用验方龙虎丸（牛黄、巴豆霜、辰砂、白矾、米粉），使痰涎吐下而出，临床有经吐下而神清志定者。无论涌吐或攻下，皆应中病即止，以免伤正。此法现虽罕用，但不可不知。","注意活血化瘀法在癫狂病中的应用。癫狂日久，气滞痰凝，影响血行，形成痰瘀胶结，痰为瘀之基，瘀亦能变生痰浊，痰夹瘀血，形成宿疾，潜伏脏腑经络之中，每因触动而发，遂致神机逆乱，神志失常。为此学者将癫狂责之痰浊血瘀为主而加以辨证论治，选用活血化瘀法治疗，常用破血下瘀的桃核承气汤、理气活血的血府逐瘀汤、癫狂梦醒汤、通窍活血汤等，并常配合化痰宣窍的涤痰汤等。","注意开窍法的应用。本病总由痰闭心窍，蒙蔽神志所致，故开窍法的应用十分重要。癫属痰气为主，可予温开，药用苏合香丸；狂属痰火上扰，可予凉开，药用安宫牛黄丸、至宝丹等。"],"yufang":["癫狂之病多由内伤七情引起，故注意精神调摄最为关键，重视精神呵护，避免精神刺激。对有明显阳性家族史者，建议咨询专业医生，评估遗传风险后再做生育决策。同时注意幼儿的发育成长，一旦发现有精神异常表现，应尽早找专科医生诊治，早期治疗。","鼓励患者参加社会活动，保持愉悦心情。对于有适应环境能力的患者，其合理要求尽量满足，其不合理要求应耐心解释，注意采用七情相胜法调节。若患者拒食，先找出原因并解决，若反复劝导、督促、喂食后，患者仍拒绝，可采取鼻饲饮食，以保证营养。对重症患者应严密观察和看护，及早采取防护措施，防止意外发生。"],"attachIds":[]},{"id":"d018","name":"痫证","kind":"main","parent":null,"chapterNo":"第二十一章","chapterName":"痫证","yinbing":[{"t":"p","x":"痫证的发生，大多由于禀赋异常、情志失调、饮食不节、脑部外伤或患他病之后脑窍损伤，造成脏腑失调，痰浊阻滞，气机逆乱，风阳内动所致，尤以痰邪为患最为重要。"},{"t":"b","x":"1. 禀赋异常"},{"t":"p","x":"痫证之始于幼年者多见，与先天因素有密切关系，所谓“羊痫风，系先天之元阴不足”。"},{"t":"p","x":"胎儿在母腹时，母亲突受惊恐而致气机逆乱，精伤肾亏，或妊娠期间母体多病、过度劳累、服药不当等原因损及胎儿，使胎气受损，胎儿出生后发育异常，发为本病。"},{"t":"b","x":"2. 情志失调"},{"t":"p","x":"《证治汇补·痫病》云：“或因卒然闻惊而得，惊则神出舍空，痰涎乘间而归之。”"},{"t":"p","x":"由于突受惊恐，致气机逆乱，痰浊随气上逆，蒙蔽清窍，或五志过极，或肝郁日久，化火生风，风火夹痰上犯清窍，元神失控，发为本病。"},{"t":"b","x":"3. 饮食不节"},{"t":"p","x":"过食肥甘厚味，损伤脾胃，脾失健运，聚湿生痰，痰浊内蕴，或气郁化火，火邪炼津成痰，积痰内伏，一遇诱因，痰浊蒙蔽元神清窍，发为本病。"},{"t":"b","x":"4. 脑窍损伤"},{"t":"p","x":"跌仆撞击，或出生时难产，或患他病，如温病、中风、中毒等导致脑脉瘀阻或脑窍损伤，而致经脉不畅，脑神失养，猝遇诱因而致神志逆乱，昏不知人，发为本病。"}],"bingji":[{"t":"p","x":"痫证的基本病机为气机逆乱，元神失控。"},{"t":"p","x":"病位在脑，与心、肝、脾、肾等脏腑密切相关。"},{"t":"p","x":"本病主要为先天或后天因素造成脏腑功能失调，脏气不平，阴阳失衡，而致气机逆乱，风、火、痰、瘀等邪闭塞清窍而发病，病理性质为虚实夹杂。"},{"t":"p","x":"痫证发作期多实或实中夹虚，休止期多虚或虚中夹实。"},{"t":"p","x":"病理因素涉及风、火、痰、瘀等，其中尤以痰邪作祟最为重要。"},{"t":"p","x":"明·楼英《医学纲目·癫痫》所云：“癫痫者，痰邪逆上也。”"},{"t":"p","x":"若风阳痰火逆而不降，则见痫证大发作。"},{"t":"p","x":"发病初期，痰瘀阻窍，肝郁化火生风，风痰闭阻或痰火炽盛等，因正气尚足，痰邪尚浅，瘀血尚轻，易于康复；若日久不愈，痰瘀胶结凝滞，损伤正气，可转为虚实夹杂之证，痰邪深伏难去，治愈较难。"},{"t":"p","x":"顽痰难除，则痫证反复发作，乃成痼疾。"}],"zhenduan":[{"t":"ol","items":["1. 慢性、反复发作性、短暂性神情恍惚，甚则突然仆倒，昏不知人，口吐涎沫，两目上视，肢体抽搐，或口中怪叫，移时苏醒，一如常人，且苏醒后对发作时情况全然不知。","2. 发作前可有眩晕、胸闷、叹息等先兆症状，发作后常伴疲乏无力。","3. 多有家族史或产伤史或脑部外伤史，老年人可有中风史，每因惊恐、劳累、情志过极等诱发。","4. 任何年龄、性别均可发病，但多在儿童期、青春期或青年期发病。"]}],"jianbie":[{"t":"b","x":"1. 中风"},{"t":"p","x":"痫证典型大发作与中风均有突然仆倒、昏不知人等症状，但痫证有慢性、反复发作史，发时口吐涎沫，两目上视，四肢抽搐，口中怪叫，可自行苏醒，醒后无半身不遂、口舌歪斜等症状，而中风无口吐涎沫、两目上视、四肢抽搐、口中怪叫等典型表现，醒后常有半身不遂等后遗症。"},{"t":"b","x":"2. 厥证"},{"t":"p","x":"两者均可见突然仆倒、昏不知人等症状，但厥证面色苍白，四肢厥冷，而无痫证之口吐涎沫、两目上视、四肢抽搐和口中怪叫等症状，临床上不难区别。"}],"bianzheng":[{"t":"b","x":"1. 辨病情轻重"},{"t":"p","x":"判断本病之轻重要注意两个方面：一是病发持续时间之长短，一般持续时间长则病重，短则病轻；二是发作间隔时间之久暂，即间隔时间短暂则病重，间隔时间长久则病轻。其临床表现的轻重与痰浊之浅深和正气之盛衰密切相关。"},{"t":"b","x":"2. 辨病性虚实"},{"t":"p","x":"痫证发病初期多属实证，反复发作日久则多虚实夹杂。发作期多实或实中夹虚，休止期多虚或虚中夹实。实者当辨风、痰、火、瘀之别。如来势急骤，神昏猝倒，不省人事，口噤牙紧，颈项强直，四肢抽搐者，属风；发作时口吐涎沫，气粗痰鸣，呆木无知，发作后或有情志错乱，幻听错觉，或有梦游者，属痰；如猝倒啼叫，面赤身热，口吐血沫，平素或发作后有大便秘结，口臭苔黄者，属火；发作时面色潮红、紫红，继则青紫，口唇发绀，或有颅脑外伤、产伤等病史者，属瘀。虚者则当区分脾虚不运、心脾两虚、心肾两虚、肝肾阴虚等不同。"},{"t":"b","x":"3. 辨阳痫阴痫"},{"t":"p","x":"痫证发作时有阳痫、阴痫之分。发作时牙关紧闭，伴面红、痰鸣声粗、舌红、脉数有力者多为阳痫；面色晦暗或萎黄、肢冷、口无怪叫或叫声低微者多为阴痫。阳痫多实，阴痫多虚。"}],"zhize":"痫证的治疗首当分清标本虚实，轻重缓急。发作期病急，开窍醒神定痫以治其标，治宜清泻肝火、豁痰息风、开窍定痫；休止期病缓，祛邪补虚以治其本，治宜健脾化痰、滋补肝肾、养心安神等。","syndrome":[{"id":"s113","name":"阳痫证","label":"（1）阳痫证","group":"发作期","clinic":"突然昏仆，不省人事，面色潮红、紫红，继之转为青紫或苍白，口唇青紫，牙关紧闭，两目上视，项背强直，四肢抽搐，口吐涎沫，或喉中痰鸣，或发怪叫，甚则二便自遗，移时苏醒。病发前多有眩晕，头痛而胀，胸闷乏力，喜欠伸等先兆症状；平素多情绪急躁，心烦失眠，口苦咽干，便秘尿黄。舌质红，苔白腻或黄腻，脉弦数或弦滑。","analysis":"本证由肝火偏亢，化风内动，夹痰热上扰清窍所致。肝风夹痰，闭阻清窍，故猝然昏仆，神志不清；风痰窜扰筋脉，故目睛上视，四肢抽搐，项背强直；痰涎壅盛，故口吐涎沫，喉中痰鸣；肝火内盛，故面红，口苦，便秘，脉弦数；苔黄腻，脉滑，为痰热内蕴之象。","treat":"急以开窍醒神，继以泻热涤痰息风。","formulaRaw":"黄连解毒汤（《外台秘要》）合定痫丸（《医学心悟》）加减。前方清上、中、下三焦之火，后方化痰开窍，息风定痫。","formulaName":"黄连解毒汤合定痫丸加减","fangjie":"黄芩、黄连、黄柏、栀子清泻肝火；贝母、胆南星清化热痰；半夏、茯苓、陈皮健脾燥湿化痰；天麻、全蝎、僵蚕息风止痉；石菖蒲辛温芳香，与远志相合，能增强化痰开窍之功；琥珀、石决明、牡蛎重镇安神。若热甚，加安宫牛黄丸，或紫雪丹；大便秘结，加生大黄、芒硝、枳实、厚朴等。"},{"id":"s114","name":"阴痫证","label":"（2）阴痫证","group":"发作期","clinic":"突然昏仆，不省人事，面色晦暗青灰而黄，手足清冷，双眼半开半合，肢体拘急，或抽搐时作，口吐涎沫，一般口不啼叫，或声音微小，醒后周身疲乏，或如常人，或仅表现为一过性呆木无知，不闻不见，不动不语，数秒至数分钟即可恢复，恢复后对上述症状全然不知，多则一日数次或十数次发作。平素神疲乏力，恶心泛呕，胸闷咳痰，纳差便溏。舌质淡，苔白腻，脉多沉细或沉迟。","analysis":"本证多因阳痫病久，耗伤阳气，或素体脾肾阳虚，痰湿内盛所致。痰湿属阴，蒙蔽清窍，故昏仆，神昏，呆木；阳虚不能温煦，故面色晦暗，四肢厥冷；痰湿内盛，故口吐涎沫，苔白腻；脾虚气弱，故神疲乏力，纳差便溏，脉沉细迟。","treat":"急以开窍醒神，继以温化痰涎，顺气定痫。","formulaRaw":"五生饮（《世医得效方》）合二陈汤（《太平惠民和剂局方》）加减。前方温阳散寒化痰，后方理气化痰。","formulaName":"五生饮合二陈汤加减","fangjie":"白附子、川乌辛温散寒，祛痰除湿；茯苓、白术健脾化痰；陈皮、半夏、白豆蔻、砂仁燥湿理气化痰；石菖蒲、远志化痰开窍；全蝎、僵蚕搜风止痉；生黑豆补肾利湿。若恶心欲呕，加生姜、苏梗、竹茹；胸闷痰多，加瓜蒌、枳实、胆南星；纳差便溏，加党参、炮姜、诃子。\n昏仆者急以针刺人中、十宣开窍醒神，继而灌服汤药。痫证重症，持续不省人事，频频抽搐者，属病情危重，应予以中西医结合抢救治疗，注意及时防治其急性并发症。偏阳衰者，见面色苍白、汗出肢冷、鼻鼾息微、脉微欲绝等表现，可辅以参附注射液静脉滴注；偏阴虚者，见面红身热、躁动不安、息粗痰鸣、呕吐频频等表现，辅以参麦注射液静脉滴注；抽搐甚者，予紫雪丹，或配合针灸疗法，促其苏醒。"},{"id":"s115","name":"肝火痰热证","label":"（1）肝火痰热证","group":"休止期","clinic":"平时急躁易怒，面红目赤，心烦失眠，咳痰不爽，口苦咽干，便秘溲黄；发作时昏仆抽搐，吐涎，或有吼叫；舌红，苔黄腻，脉弦滑而数。","analysis":"本证由肝火痰热内盛所致。肝火亢盛，故急躁易怒，面红目赤，口苦；火热扰心，故心烦失眠；火热灼津为痰，故咳痰不爽；痰热互结，伏匿于内，为痫证发作之夙根；舌红，苔黄腻，脉弦滑而数，为肝火痰热内盛之象。","treat":"清肝泻火，化痰宁心。","formulaRaw":"龙胆泻肝汤（《兰室秘藏》）合涤痰汤（《奇效良方》）加减。前方以清泻肝火为主，后方涤痰开窍见长。","formulaName":"龙胆泻肝汤合涤痰汤加减","fangjie":"龙胆草、黄芩、栀子直入肝经而泻肝火；泽泻、木通、车前子清利肝经湿热；浙贝母、瓜蒌、竹茹、胆南星清热化痰；茯苓、橘红、枳实健脾理气化痰；石菖蒲、远志化痰开窍；石决明、牡蛎重镇安神。若肝火动风，加天麻、钩藤、地龙、全蝎；大便秘结，加大黄、芒硝；彻夜难寐，加酸枣仁、柏子仁、五味子。"},{"id":"s116","name":"脾虚痰盛证","label":"（2）脾虚痰盛证","group":"休止期","clinic":"平素神疲乏力，少气懒言，胸脘痞闷，纳差便溏；发作时面色晦滞或㿠白，四肢不温，蜷卧拘急，呕吐涎沫，叫声低怯；舌质淡，苔白腻，脉濡滑或弦细滑。","analysis":"本证由脾虚健运失职，水湿内停，聚湿生痰所致。脾虚气血生化无源，故神疲乏力，面色不华；脾失健运，故纳差，便溏，脘痞；痰浊内盛，故苔腻、脉滑。","treat":"健脾化痰。","formulaRaw":"六君子汤（《医学正传》）加减。","formulaName":"六君子汤加减","fangjie":"党参、茯苓、白术、炙甘草健脾益气助运；陈皮、半夏、竹茹理气化痰降逆；白豆蔻、砂仁醒脾化湿；石菖蒲、远志、琥珀化痰开窍，宁心安神。若恶心呕吐痰涎，加胆南星、瓜蒌、旋覆花；便溏，加薏苡仁、炒扁豆、炮姜等；脘腹饱胀，饮食难下，加神曲、谷芽、麦芽。心脾气血两虚，改用归脾汤加减；精神不振，久而不复，当大补精血，益气养神，宜服河车大造丸。"},{"id":"s117","name":"肝肾阴虚证","label":"（3）肝肾阴虚证","group":"休止期","clinic":"痫证频发，神思恍惚，面色晦暗，头晕目眩，伴两目干涩，耳轮焦枯不泽，健忘失眠，腰膝酸软，大便干燥，舌红，苔薄白或薄黄少津，脉沉细数。","analysis":"本证多因痫证反复发作，或肝火痰热耗伤肝肾之阴所致。肝肾阴虚，脑髓失养，故神思恍惚，头晕健忘；阴虚不能制阳，虚火内扰，故失眠，五心烦热，舌红，脉细数；肝开窍于目，肾开窍于耳，主骨生髓，故见目涩，耳鸣，腰酸；阴液不足，肠失濡润，故大便干燥；舌红，苔薄少津，脉沉细数，为肝肾阴虚之象。","treat":"滋养肝肾，填精益髓。","formulaRaw":"大补元煎（《景岳全书》）加减。","formulaName":"大补元煎加减","fangjie":"熟地黄、枸杞子、山茱萸、杜仲补益肝肾，滋阴养血；人参、炙甘草、山药补气健脾；鹿角胶、龟甲胶填精益髓；牡蛎、鳖甲滋阴潜阳安神；石菖蒲、远志宣窍安神。若神思恍惚，持续时间长，合酸枣仁汤，加阿胶、龙眼肉；若恐惧、焦虑、忧郁，合甘麦大枣汤；水不制火，心肾不交，合交泰丸；大便干燥，加玄参、肉苁蓉、火麻仁。"},{"id":"s118","name":"瘀阻脑络证","label":"（4）瘀阻脑络证","group":"休止期","clinic":"平素头晕头痛，痛有定处，常伴单侧肢体抽搐，或一侧面部抽动，颜面口唇青紫，舌质暗红或有瘀斑，苔薄白，脉涩或弦。多继发于中风、颅脑外伤、产伤、颅内感染等疾病后。","analysis":"本证由外伤或久病入络，导致瘀血阻滞脑窍，神机失灵所致。瘀血阻滞，清窍不利，故头痛，头晕，痛处固定；瘀阻脑脉，元神失控，筋脉挛急，故见局部或单侧抽搐；面色、唇甲、舌质紫暗，脉涩，均为瘀血内阻之象。","treat":"活血化瘀，息风通络。","formulaRaw":"通窍活血汤（《医林改错》）加减。","formulaName":"通窍活血汤加减","fangjie":"石菖蒲、远志芳香开窍；老葱通阳开窍；赤芍、川芎、桃仁、红花、地龙活血通络；天麻、僵蚕、全蝎息风止痉；龙骨、牡蛎镇心安神。若肝阳上亢，加钩藤、石决明、白芍；痰涎偏盛，加半夏、胆南星、竹茹；纳差乏力，少气懒言，肢体瘫软，加黄芪、党参、白术。"}],"linchuang":["遵循“间者并行，甚者独行”原则。发作时应“急则治其标”，“甚者独行”，采用豁痰顺气法，顽痰胶固需辛温开导，痰热胶着需清化降火，治疗着重在风、痰、火、虚四个字上。当控制病情后，一般不应随意更改方药，否则易致大发作。在痫证发作缓解后应“缓则治其本”，“间者并行”，坚持标本并治，守法守方，坚持服药，服药3～5年后，待发作完全控制，病情稳定后，再逐步减量，方能避免或减少发作。","巧用辛热开破法。痰浊闭阻，气机逆乱是本病的主要病机，故治疗多以涤痰、行痰、豁痰为大法。然痫证之痰，异于一般痰邪，具有深遏潜伏、胶固难化、随风气而聚散之特征，非一般祛痰与化痰药物所能涤除。辛热开破法是针对痫证顽痰难化这一特点而确定的治法，采用大辛大热的川乌、半夏、南星、白附子等具有振奋阳气、推动气化作用的药物，以开气机之闭塞，破痰邪之积聚，捣沉痼之胶结，从而促进顽痰消散，痫证缓解。","注重虫类药及芳香开窍药的应用。虫类药多能入络搜风，有祛风化痰止痉之功，其力非草本药所能代替，具有良好减轻和控制痫证发作的效果。可在辨证的基础上酌情加虫类药，如全蝎、蜈蚣、地龙、僵蚕、蝉蜕等，并可配合应用平肝镇潜药物，如钩藤、石决明等。如另取研粉服效果尤佳，每服1~1.5g，每日2次，小儿剂量酌减。芳香开窍类药物性多辛散走窜，能通善开，是醒神开窍佳品，其气味芳香，且有解内生痰毒之功，临证时应酌情选用，尤其是在发作期需紧急缓解病情时，常用药有麝香、冰片、人工牛黄、菖蒲等。"],"yufang":["保持精神愉快，避免精神刺激，怡养性情，劳逸适度。妇女在怀孕前应积极治疗原发病，产时产后避免胎儿头颅外伤、颅内感染等发生。休止期患者应避免近水、近火、近电、高空作业及驾驶车辆，以免突然发病时发生危险。调理饮食、情志和起居，饮食宜清淡，多吃素菜，少食肥甘之品，切忌过冷过热、辛辣刺激的食物。","患病之后，针对正虚可适当参以调补，调脾胃，和气血，健脑髓，顺气涤痰，活血化瘀等，切忌不加辨证，一概投人参、鹿茸大补之品或其他温燥补品。对昏仆抽搐的患者，注意保持呼吸道通畅，凡有义齿者均应取出，放置牙垫，以防窒息和咬伤，加用床栏以免翻坠下床。"],"attachIds":[]},{"id":"d019","name":"胃痛","kind":"main","parent":null,"chapterNo":"第二十二章","chapterName":"胃痛","yinbing":[{"t":"p","x":"胃痛的发生，主要是由感受外邪、内伤饮食、情志失调、久病体虚及药物损害等引起，致使脏腑功能失调，脾胃虚弱，不荣则痛，或胃气郁滞，失于和降，不通则痛。"},{"t":"b","x":"1. 感受外邪"},{"t":"p","x":"外感寒、热、湿诸邪，内客于胃，皆可致胃脘气机阻滞，不通则痛。"},{"t":"p","x":"其中以寒邪犯胃最为多见，寒邪收引、凝滞，易使气机郁滞，致胃气不和而胃痛暴作。"},{"t":"p","x":"《素问·举痛论》云：“寒气客于肠胃之间，膜原之下，血不能散，小络急引，故痛。”"},{"t":"b","x":"2. 内伤饮食"},{"t":"p","x":"饮食不节，暴饮暴食，或者过食生冷寒凉，嗜酒，嗜食辛辣、肥甘厚味等，内生寒湿或者湿热，阻滞气机，胃失和降，发生胃痛。"},{"t":"p","x":"此外，过服寒凉、温燥药物，伤胃体、耗胃气，损胃阴，使脾失健运，胃失和降，不通而痛。"},{"t":"p","x":"《证治汇补·心痛》云：“服寒药过多，致脾胃虚弱，胃脘作痛。”"},{"t":"b","x":"3. 情志失调"},{"t":"p","x":"忧思恼怒，所愿不遂，损伤肝脾，肝失疏泄，脾失健运，气机郁滞，横逆犯胃，致胃失和降，而发胃痛。"},{"t":"p","x":"《沈氏尊生书·胃痛》指出：“胃痛，邪干胃脘病也。……惟肝气相乘为尤甚，以木性暴，且正克也。”"},{"t":"p","x":"气滞日久不愈，或久痛入络，可致胃络血瘀。"},{"t":"p","x":"《临证指南医案·胃脘痛》云：“胃痛久而屡发，必有凝痰聚瘀。”"},{"t":"b","x":"4. 久病体虚"},{"t":"p","x":"若素体脾胃虚弱，或劳倦过度，或饮食损伤，导致脾胃虚弱，运化失职，气机不畅；或中焦虚寒，胃失温养；或胃阴亏虚，胃失濡养；或久病正虚，使脾胃虚弱，也可导致胃痛。"}],"bingji":[{"t":"p","x":"胃痛的基本病机是胃气失和，气机不利，不通则痛，或者不荣则痛。"},{"t":"p","x":"病变部位在胃，与肝、脾关系密切。"},{"t":"p","x":"若忧思恼怒，肝气横逆，气机郁滞，乘脾犯胃，胃失和降，而发为胃痛；肝气久郁，既可因肝郁化火，导致肝胃郁热，而发为胃痛，又可因肝郁气滞导致瘀血内结，出现瘀血胃痛。"},{"t":"p","x":"病理性质分为虚实两类，病机演变主要是虚实、寒热、气血之间的演变和转化。"},{"t":"p","x":"病理因素以气滞为主，并见食积、寒凝、热郁、湿阻、血瘀等。"},{"t":"p","x":"胃痛初发由外邪、饮食、情志所伤者，常表现为实证；久痛不愈，或反复发作，可由实证转为虚证，多呈虚实夹杂之候。"},{"t":"p","x":"若失治误治，邪热壅盛，水热互结，腑气不通，可致结胸，甚或引发厥脱危证，或日久脾胃衰败，或瘀结成毒，气机壅塞，胃失和降，胃气上逆，可致反胃或者噎膈，预后不良。"}],"zhenduan":[{"t":"ol","items":["1. 以上腹胃脘部疼痛为主症，可表现为胀痛、刺痛、灼痛、隐痛、剧痛、闷痛等不同。","2. 常伴食欲不振、恶心呕吐、嘈杂、泛酸、嗳腐吞酸等症状。","3. 以中青年居多，起病或急或缓、多有反复发作史，发病前多有明显的诱因，如气候变化、情志刺激、劳倦过度、饮食不节，或有不合理用药史等。"]}],"jianbie":[{"t":"b","x":"1. 真心痛"},{"t":"p","x":"真心痛是胸痹心痛的严重证候，多见于老年人，常有胸痹病史，典型症状为胸膺部闷痛、刺痛或绞痛，疼痛剧烈，痛引肩背，常伴心悸气短、汗出肢冷、唇甲发绀等症状，病情危急。"},{"t":"p","x":"《灵枢·厥论》曰：“真心痛，手足清至节，心痛甚，旦发夕死，夕发旦死。”"},{"t":"p","x":"提示真心痛病情危急，预后险恶。"},{"t":"p","x":"其病史、诊断要点、临床表现以及预后等方面，与胃痛有明显的区别。"},{"t":"p","x":"临床可借助于心电图、心肌酶谱等检查进行鉴别诊断。"},{"t":"b","x":"2. 胁痛"},{"t":"p","x":"胁痛病位在肝胆，与脾胃有关，临床表现以一侧或者两侧胁肋部疼痛为主，可兼有胃脘部不适，甚至胃脘疼痛，多伴有厌食油腻、胸胁满闷、口苦，或发热恶寒等症。"},{"t":"p","x":"胃痛病位在胃，与肝、脾有关，以胃脘部位疼痛为主，部分患者可涉及胸胁疼痛不适，常伴有脘腹痞闷胀满、吞酸嘈杂等症。"}],"bianzheng":[{"t":"b","x":"1. 辨虚实"},{"t":"p","x":"虚者多病程长，痛处喜温喜按，饥时痛著，食后痛减，体弱脉虚。属虚者应进一步辨气虚、阳虚和阴虚。实者多病程较短，痛处拒按，饥时痛轻，食后痛增，体壮脉盛。属实者应进一步辨别不同的病理因素。"},{"t":"b","x":"2. 辨寒热"},{"t":"p","x":"胃痛遇寒加重，得温痛减，泛吐清水者，为寒证；胃脘灼痛，痛势急迫，喜凉恶热，泛吐酸水者，为热证。寒与热均有虚实之分。"},{"t":"b","x":"3. 辨气血"},{"t":"p","x":"一般初病在气，久病在血。气滞者，多见攻窜胀痛，痛无定处，或牵扯两胁，疼痛多与情志因素密切相关；血瘀者，呈刺痛，疼痛部位固定不移，疼痛持续，入夜加重，舌质紫暗或有瘀斑，或兼见呕血、便血。"}],"zhize":"胃痛的治疗以理气和胃止痛为基本治法。疏通气机，“通则不痛”，运用“通”法，不能局限于狭义的“通”之一法，应根据不同证候，采取相应治法。如实证者，应区别寒凝、食积、气滞、郁热、湿热、血瘀，分别给予散寒止痛、消食和胃、疏肝解郁、疏肝泻热、清热利湿、通络化瘀治法；虚证者当辨虚寒与阴虚，分别给予温胃建中或滋阴养胃等治法。对于胃脘拘急而痛者，可用缓急止痛法。","syndrome":[{"id":"s119","name":"寒邪客胃证","label":"1. 寒邪客胃证","group":"","clinic":"胃痛暴作，拘急冷痛，恶寒喜暖，得温痛减，遇寒加重，口不渴，喜热饮，有感受寒邪或饮食生冷病史，舌淡红，苔薄白，脉弦紧。","analysis":"寒邪客胃，暴遏阳气，气机凝滞不通，故胃脘疼痛暴作，拘急冷痛，恶寒喜暖，遇寒加重；寒邪不伤津液，故口不渴；舌淡红，苔薄白，脉弦紧，均为寒邪客胃的表现。","treat":"温胃散寒，理气止痛。","formulaRaw":"良附丸（《良方集腋》）合香苏散（《太平惠民和剂局方》）加减。前方温胃散寒、行气止痛，后方解表散寒、理气和中。","formulaName":"良附丸合香苏散加减","fangjie":"高良姜、砂仁温胃散寒；香附、苏梗、陈皮行气止痛。若寒邪较著，加荜茇、川椒、吴茱萸、肉桂；兼恶寒、头痛等风寒表证者，加苏叶、桂枝、荆芥、防风；兼宿食积滞者，可加焦神曲、炒麦芽、炒鸡内金。寒邪郁久化热，寒热错杂，用半夏泻心汤加减。"},{"id":"s120","name":"饮食伤胃证","label":"2. 饮食伤胃证","group":"","clinic":"胃脘疼痛，胀满拒按，嗳腐吞酸，或呕吐不消化食物，其味腐臭，吐后痛减，不思饮食，大便不爽，得矢气及便后稍舒，有暴饮暴食病史，舌淡红，苔厚腻，脉滑。","analysis":"饮食积滞，壅阻胃气，故胃脘疼痛，胀满拒按；胃失和降，胃中腐败谷物夹腐浊之气上泛于口，故嗳腐吞酸，或呕吐不消化食物，其味腐臭，不思饮食；吐后或者便后邪气得消，故吐后痛减，或得矢气及便后稍舒；有暴饮暴食病史，舌淡红，苔厚腻，脉滑，均为饮食伤胃的表现。","treat":"消食导滞，和中止痛。","formulaRaw":"保和丸（《丹溪心法》）加减。","formulaName":"保和丸加减","fangjie":"神曲、山楂、莱菔子消食导滞；茯苓、半夏、陈皮和胃化湿；连翘散结清热。若脘腹胀甚者，加枳实、木香、槟榔；食积化热，嗳腐酸臭者，加黄连、栀子；胃脘胀痛而便秘者，加生白术、枳实、厚朴；胃痛急剧而拒按，伴见苔黄燥，便秘者，为食积化热成燥，则合大承气汤。"},{"id":"s121","name":"肝气犯胃证","label":"3. 肝气犯胃证","group":"","clinic":"胃脘胀痛，或攻撑窜动，牵引背胁，情绪波动诱发或导致疼痛加重，嗳气、矢气则痛舒，胸闷叹息，大便不畅，舌淡红，苔薄白，脉弦。","analysis":"肝气郁滞，横逆犯胃，胃气阻滞，故胃脘胀痛，或攻撑窜动，牵引背胁；气机不畅，故胸闷叹息，大便不畅；嗳气、矢气后气机稍舒，故胃痛减轻；舌淡红，苔薄白，脉弦，均为肝郁气滞的表现。","treat":"疏肝理气，和胃止痛。","formulaRaw":"柴胡疏肝散（《景岳全书》）加减。","formulaName":"柴胡疏肝散加减","fangjie":"柴胡、川芎、香附、陈皮散郁和中；白芍、甘草缓急止痛；枳壳、佛手、绿萼梅理气解郁而不伤阴。若伴有胁痛者，加川楝子、延胡索；嗳气较频者，加半夏、旋覆花、代赭石等；泛酸者，加乌贼骨、浙贝母、煅瓦楞子。"},{"id":"s122","name":"肝胃郁热证","label":"4. 肝胃郁热证","group":"","clinic":"胃脘灼痛，烦躁易怒，烦热不安，胁胀不舒，泛酸嘈杂，口干口苦，舌质红，苔黄，脉弦或弦数。","analysis":"肝郁化火，横逆犯胃，胃气阻滞，故胃脘灼热疼痛；肝经有火，故烦躁易怒，烦热不安，胁胀不舒；肝火犯胃，故胃脘泛酸嘈杂，口干口苦；舌质红，苔黄，脉弦或弦数，均为肝胃郁热的表现。","treat":"疏肝泻热，和胃止痛。","formulaRaw":"丹栀逍遥散（《内科摘要》）加减。","formulaName":"丹栀逍遥散加减","fangjie":"丹皮、栀子清泻肝火；白芍、甘草、当归柔肝缓急止痛；柴胡、陈皮疏肝和胃；白术、茯苓健脾益气；黄连、吴茱萸泻肝和胃。若胸胁胀满，烦躁易怒甚者，加香附、川芎等；若口苦、口干者，加黄芩、太子参、麦冬。胃热壅盛，胃脘灼痛、胀满，大便不畅者，用大黄黄连泻心汤加减。"},{"id":"s123","name":"湿热中阻证","label":"5. 湿热中阻证","group":"","clinic":"胃脘灼痛，吐酸嘈杂，脘痞腹胀，纳呆恶心，口渴不欲饮水，小便黄，大便不畅，舌质红，苔黄腻，脉滑数。","analysis":"湿热蕴结中焦，胃气壅滞，气机不畅，故胃脘灼热疼痛，吐酸嘈杂，脘痞腹胀；胃失和降，故纳呆恶心；湿热中阻，津液输布失常，故口渴不欲饮水；湿热交阻下迫，故小便黄，大便不畅；舌质红，苔黄腻，脉滑数，均为湿热中阻的表现。","treat":"清化热湿，理气和胃。","formulaRaw":"清中汤（《证治准绳》）加减。","formulaName":"清中汤加减","fangjie":"黄连、栀子清热燥湿；半夏、茯苓、草豆蔻祛湿健脾；陈皮、甘草理气和中。湿邪偏重者，加苍术、藿香；热邪偏重者，加蒲公英、黄芩、连翘；伴恶心呕吐者，加竹茹、苏梗；大便秘结不通者，加生大黄；气滞腹胀者，加厚朴、枳实。"},{"id":"s124","name":"瘀血停滞证","label":"6. 瘀血停滞证","group":"","clinic":"胃脘刺痛，痛有定处，按之痛甚，疼痛延久屡发，食后加剧，入夜尤甚，甚至出现黑便或呕血，舌质紫暗或有瘀斑，脉涩。","analysis":"瘀停胃络，脉络壅滞，气机不畅，故胃脘刺痛，痛有定处，按之痛甚；夜间阳气入脏，阴气用事，阴血凝滞更甚，故胃痛入夜尤甚；瘀血阻滞，脉络不通，血不归经而外溢，故出现黑便或呕血；舌质紫暗或有瘀斑，脉涩，均为瘀血停滞的表现。","treat":"化瘀通络，理气和胃。","formulaRaw":"失笑散（《太平惠民和剂局方》）合丹参饮（《时方歌括》）加减。前方活血行瘀，散结止痛，后方调气化瘀。","formulaName":"失笑散合丹参饮加减","fangjie":"蒲黄、五灵脂、丹参化瘀定痛；檀香、砂仁理气和胃而止痛。胃痛甚者，加延胡索、郁金、九香虫、木香、枳壳；见呕血及黑便等出血现象者，当以止血为先，宜去檀香、砂仁，加大黄、茜草根、三七。"},{"id":"s125","name":"脾胃虚寒证","label":"7. 脾胃虚寒证","group":"","clinic":"胃脘隐痛，绵绵不休，空腹痛甚，得食则缓，喜温喜按，劳累或受凉后发作或加重，泛吐清水，食少纳呆，大便溏薄，神疲倦怠，四肢不温，舌质淡，苔薄白，脉虚缓无力。","analysis":"中焦虚寒，胃失温养，故胃脘隐痛，绵绵不休，空腹痛甚，得食则缓，喜温喜按；水湿内盛，脾胃不能运化，流注肠中，故大便溏薄；脾气虚弱，四肢失养，故神疲倦怠，四肢不温；舌质淡，苔薄白，脉虚缓无力，均为脾胃虚寒的表现。","treat":"温中健脾，和胃止痛。","formulaRaw":"黄芪建中汤（《金匮要略》）加减。","formulaName":"黄芪建中汤加减","fangjie":"黄芪、白术补气健脾；桂枝温胃散寒；白芍、生姜、大枣、甘草缓急止痛。泛吐酸水者，加吴茱萸、煅瓦楞子、乌贼骨、浙贝母；泛吐清水较多，或胃中有振水音，加干姜、半夏、陈皮、茯苓，或合用苓桂术甘汤；寒盛痛甚，呕吐肢冷，合理中丸，或改用大建中汤加减。脾胃虚寒，胃痛，食欲不振，恶心呕吐者，用香砂六君子汤加减。"},{"id":"s126","name":"胃阴不足证","label":"8. 胃阴不足证","group":"","clinic":"胃脘隐隐灼痛，有时嘈杂似饥，或饥不欲食，口干咽燥，大便干结，舌质红少津，或光剥无苔，脉弦细无力。","analysis":"胃阴不足，润降失司，胃失濡养，故胃脘隐隐灼痛，嘈杂，饥不欲食；胃阴不足，上不能滋润咽喉，则口干咽燥，下不能濡润大肠，则大便干结；舌质红少津，或光剥无苔，脉弦细无力，均为胃阴不足、阴虚内热的表现。","treat":"养阴益胃，和中止痛。","formulaRaw":"益胃汤（《温病条辨》）加减。","formulaName":"益胃汤加减","fangjie":"北沙参、麦冬、生地黄、玉竹、石斛甘凉以滋养胃阴；佛手、绿萼梅调气止痛。若见胃脘灼热疼痛，嘈杂不适，加生牡蛎、煅瓦楞子、乌贼骨，或者合用左金丸加减；若胃脘胀满疼痛较剧，加佛手、苏梗、厚朴花、川楝子、延胡索；若气阴两虚，倦怠乏力，不思饮食，加太子参、石斛；若热结便秘，加火麻仁、炒莱菔子、全瓜蒌、蒲公英；胃痛反复发作，缠绵难愈，阴虚毒结者，加连翘、浙贝母、莪术、半枝莲、白花蛇舌草。"}],"linchuang":["肝胃同治。肝失疏泄，也是导致胃痛发生的常见病机，故临床用药常常强调“治肝可以安胃”。肝胃失调主要有以下三种情况：一为疏泄太过，木旺克土，治疗以抑肝气、泻肝火为主，并应用酸甘之品以柔肝缓急；二为疏泄不及，木郁土壅，治疗宜用辛散之品，疏肝理气；三为脾胃亏虚，土虚木乘，通过健脾益气、益养胃阴以培土，酌配酸敛以抑肝。治肝诸法在运用时应相互配合，疏敛有度，补泻适宜，方合肝脾疏运之性。调肝之药多具有辛散理气的功效，同时可以行气消胀止痛，最适宜用于胃痛的治疗。","刚柔并用。理气和胃止痛为治疗胃痛的大法，但是临床也不可过用辛香理气之剂，尤其是在肝胃郁热、胃阴不足胃痛患者的治疗中，过用辛香热燥、苦寒清热的药物，易损伤胃气、耗伤胃阴。如治疗胃阴不足胃痛，应在养阴清热基础上疏肝调气，如用太子参、麦冬、石斛、玉竹、沙参、生山药等甘凉濡润之品以养阴清热，配用乌梅、木瓜、白芍、山楂、甘草等酸甘之品以养阴柔肝，加玫瑰花、佛手、绿萼梅、香橼、厚朴花等辛平之品以疏肝调气。","活血化瘀。由于“久病入络”“胃痛久而屡发，必有凝痰聚瘀”，在治疗慢性胃痛的过程中，注意合理使用活血化瘀的中药，常用丹参、郁金、延胡索、三七、莪术、三棱、红花、生蒲黄、五灵脂等。","健脾养胃。慢性胃痛，病情缠绵难愈，多在脾胃虚弱的基础上发病。脾胃虚弱贯穿慢性胃痛的整个过程，治疗要以补虚固本，健脾养胃。具体辨证又有脾气虚弱和胃阴不足的区别。中年以上患者，胃痛经久不愈，当注意久痛防变，应该及时检查，积极调治。"],"yufang":["本病治疗过程中需要重视饮食调摄和精神调摄两个方面。","养成良好的饮食习惯，忌暴饮暴食、饥饱无常；忌饮食生冷、肥甘厚味、醇酒、炙煿等物；忌过用苦寒、燥热伤胃的药物。患病后以少食多餐、清淡易消化饮食为宜，避免进食浓茶、咖啡和辛辣刺激性食物。","需保持乐观的情绪，精神愉快，性情开朗，避免忧思恼怒等情志内伤。要劳逸结合，起居有常，避免外邪内侵。"],"attachIds":["a002","a003"]},{"id":"d020","name":"胃痞","kind":"main","parent":null,"chapterNo":"第二十三章","chapterName":"胃痞","yinbing":[{"t":"p","x":"饮食不节、情志失调、久病体虚、药毒误治等可引起中焦气机不利，脾胃升降失常，而发生胃痞。"},{"t":"b","x":"1. 饮食不节"},{"t":"p","x":"饥饱失常，或恣食生冷，或嗜食辛辣，或过食肥甘厚味，损伤脾胃，纳运失常，食滞内停，痰湿中阻，胃气壅塞，升降失司，而成痞满。"},{"t":"p","x":"《伤寒论·辨太阳病脉证并治》云：“谷不化，腹中雷鸣，心下痞硬而满。”"},{"t":"b","x":"2. 情志失调"},{"t":"p","x":"忧思恼怒，所愿不遂，肝气郁滞，失于疏泄，横逆乘脾犯胃，脾胃升降失常，或脾胃受损，运化不利，胃腑失和，气机不畅，发为胃痞。"},{"t":"p","x":"《景岳全书·痞满》云：“怒气暴伤，肝气未平而痞。”"},{"t":"p","x":"《诸病源候论》云：“由忧恚气积，或坠堕内损所致。”"},{"t":"b","x":"3. 久病体虚"},{"t":"p","x":"久病脾胃虚弱，中焦升降无力，或气虚日久渐至阳虚，寒邪伤中，中焦失于温运，或痰湿之邪、肝气郁滞日久，化火伤阴，阴津伤则胃失运化，受纳、腐熟无权，而成虚痞。"},{"t":"p","x":"《兰室秘藏·中满腹胀门》云：“或多食寒凉，及脾胃久虚之人，胃中寒则胀满，或脏寒生满病。”"},{"t":"b","x":"4. 药毒误治"},{"t":"p","x":"因病长期误用、滥用药物，损伤脾胃，或因感受外邪，复因失治误治，邪气内陷，结于胃脘，阻塞中焦，气机不利，升降失司，遂成胃痞。"},{"t":"p","x":"《伤寒论·辨太阳病脉证并治》曰：“伤寒大下后，复发汗，心下痞。”"},{"t":"p","x":"《太平圣惠方·治乳石发动心膈痞满腹痛诸方》谓：“因服冷药太过，致心膈痞满。”"}],"bingji":[{"t":"p","x":"胃痞的基本病机是中焦气机不利，脾胃升降失职。"},{"t":"p","x":"病变部位主要在胃，与脾、肝有关。"},{"t":"p","x":"病理性质有虚实之分，初期以实证为多，久病则为虚，或见虚实夹杂之证。"},{"t":"p","x":"病理因素有食滞、痰湿、湿热、气滞。"},{"t":"p","x":"而实邪内阻，又会进一步损伤脾胃，或由于痰湿困脾日久，使正气日渐消耗，损伤脾胃，或素体脾胃虚弱者，均可致中焦运化无力而成气虚之痞；湿热之邪或肝胃郁热日久伤阴，导致胃阴亏损，胃失濡养，和降失司，而成阴虚之痞。"},{"t":"p","x":"各种病邪使实者愈实，虚者愈虚，正虚邪实，虚实夹杂，各因相兼，互相转化，是胃痞的病机特点。"},{"t":"p","x":"胃痞日久不愈，可因脾胃虚弱，水谷精微失于输布，痰湿浊瘀郁结，化热伤阴，气血津液亏虚，后天失养，转为胃痛、虚劳等。"}],"zhenduan":[{"t":"ol","items":["1. 以上腹胃脘部满闷不舒为主症，并有触之无形、按之柔软、压之不痛的特点。","2. 起病可急可缓，时轻时重，病程可长可短，常反复发作。","3. 发病前多有明显的诱因，如气候变化、情志刺激、劳倦过度、饮食不节，或有不合理用药史等，或继发于久病体虚者。"]}],"jianbie":[{"t":"b","x":"1. 胃痛"},{"t":"p","x":"胃痞与胃痛病位同在脘腹部，常相兼出现。"},{"t":"p","x":"胃痛以疼痛为主症，胃痞以脘腹痞满胀闷不适为主症。"},{"t":"b","x":"2. 鼓胀"},{"t":"p","x":"胃痞与鼓胀均可自觉脘腹胀满，胃痞为中焦气机不利，脾胃升降失司所致，以自觉满闷不舒、外无胀形为特征；鼓胀基本病理变化为肝、脾、肾受损，气滞、血瘀、水停腹中，以腹部胀大如鼓、皮色苍黄、脉络暴露为主症。"},{"t":"b","x":"3. 积聚"},{"t":"p","x":"胃痞与积聚均可见脘腹满闷，胃痞为中焦气机不利，脾胃升降失司所致，积聚的病机主要为气机阻滞，瘀血内结。"},{"t":"p","x":"胃痞自觉脘腹满闷不适，无腹部包块；积聚的临床特征是腹内结块，或伴有腹痛或腹胀。"}],"bianzheng":[{"t":"b","x":"1. 辨虚实"},{"t":"p","x":"实痞多见于体壮者，自觉脘腹痞满，按之加重，食后为甚，舌苔厚腻，脉实有力；实证多由饮食内停、痰湿中阻、湿热阻胃、肝胃不和所致。虚痞多见于体虚者，脘腹痞满，反复发作，喜揉喜按，食少纳呆，舌象可见少苔，脉虚无力；虚证多由脾胃虚弱、胃阴不足所致。"},{"t":"b","x":"2. 辨寒热"},{"t":"p","x":"寒痞遇寒则甚，口淡不渴，或渴不欲饮，舌淡苔白，脉沉迟。热痞可见烦热满闷，常口渴喜饮，舌红苔黄，脉滑数。"}],"zhize":"胃痞的治疗以调理脾胃升降、行气除痞消满为基本原则。根据其虚实分治，实者泻之，施以清热祛湿、消食导滞、除湿化痰、理气解郁等法；虚者补之，施以健脾益气、养阴益胃等法；虚实夹杂者补泻并用。\n治疗中应注意无论补泻，用药不可过于峻猛，以免重伤脾胃，尤其需要注意顾护胃阴。在治疗实痞时，常用辛温燥湿之品，用量太过则易伤胃阴；湿热蕴结或肝气郁久均易化火伤阴，谨防用药太过，伤及胃阴；对于胃阴亏虚者，选用理气消痞的药物时，宜以轻清为原则，可适当选用理气而不伤阴的药物；滋阴养胃用药不可过于滋腻，以防阻滞气机。","syndrome":[{"id":"s132","name":"饮食内停证","label":"（1）饮食内停证","group":"实痞","clinic":"脘腹满闷而胀，进食尤甚，嗳腐吞酸，厌食呕吐，或大便不调，矢气频作，气味臭秽如败卵，舌苔厚腻，脉滑。","analysis":"饮食停滞，胃腑失和，气机壅塞，故胃脘痞满；胃失和降，胃中腐浊之气上逆，故嗳腐吞酸，厌食呕吐；食积气滞，食湿下移大肠，故大便不调，矢气频作，气味臭秽如败卵；正气抗邪，气血充盛，故脉象滑利有力。","treat":"消食和胃，行气消痞。","formulaRaw":"保和丸（《丹溪心法》）加减。","formulaName":"保和丸加减","fangjie":"山楂、神曲、莱菔子消食导滞，行气除胀；半夏、陈皮和胃降逆，行气消痞；茯苓健脾渗湿，和中止泻；连翘清热散结。若食积较重，食欲减退者，加鸡内金、谷芽、麦芽、鸡矢藤；胀满明显者，加枳实、厚朴、大腹皮；食积化热，大便秘结者，加生枳实、生白术、生大黄、槟榔，或用枳实导滞丸加减；脾虚便溏者，加炒白术、炒扁豆、炒山药，或用枳实消痞丸加减。"},{"id":"s133","name":"痰湿中阻证","label":"（2）痰湿中阻证","group":"实痞","clinic":"脘腹痞塞不舒，胸膈满闷，身重困倦，头昏纳呆，嗳气呕恶，口淡不渴，舌淡红，苔白厚腻，脉沉滑。","analysis":"痰湿阻滞，脾失健运，气机不和，故胃脘痞满，胸膈满闷，纳呆；胃气上逆，故见嗳气呕恶；痰湿阻滞，清阳不升，故见头昏；湿邪重浊，痰湿中阻，故见身重困倦。舌淡红，苔白厚腻，脉沉滑，均为痰湿中阻的表现。","treat":"除湿化痰，理气和中。","formulaRaw":"平胃散（《太平惠民和剂局方》）合二陈汤（《太平惠民和剂局方》）加减。前方燥湿运脾，行气和胃，后方燥湿化痰，理气和中。","formulaName":"平胃散合二陈汤加减","fangjie":"苍术、厚朴燥湿除满；半夏、陈皮化痰理气；茯苓健脾利湿；甘草健脾和胃。若痰湿盛而满闷者，加紫苏梗、桔梗、藿香；痰阻气逆，心下痞硬，嗳气不止者，加旋覆花、代赭石，或用旋覆代赭汤加减；渴不欲饮，水入即吐，合五苓散；脾胃虚弱者，加党参、白术、砂仁、木香。痰湿郁久化热而口苦、舌苔黄者，改用黄连温胆汤加减。"},{"id":"s134","name":"湿热阻胃证","label":"（3）湿热阻胃证","group":"实痞","clinic":"脘腹胀闷不舒，灼热嘈杂，恶心呕吐，口干不欲饮，口苦，纳少，大便干结或黏滞不畅，舌质红，苔黄腻，脉滑数。","analysis":"湿热内蕴，困阻脾胃，升降失常，气机不利，故胃脘痞满，恶心呕吐；湿热中阻，灼伤胃络，故胃脘灼热嘈杂；湿热内阻，下迫大肠，故大便黏滞不畅；舌质红，苔黄腻，脉滑数，均为湿热阻胃的表现。","treat":"清热化湿，和胃消痞。","formulaRaw":"泻心汤（《金匮要略》）合连朴饮（《霍乱论》）加减。前方泻热破结，后方清热燥湿，理气化浊。","formulaName":"泻心汤合连朴饮加减","fangjie":"大黄泻热散痞，和胃开结；黄连、黄芩苦降泻热和中；厚朴理气燥湿；石菖蒲芳香化湿，醒脾开胃；半夏和胃燥湿；芦根清热和胃，止呕除烦；栀子、豆豉清热除烦。若胃中灼热，嘈杂明显者，加蒲公英、连翘、瓦楞子、乌贼骨；恶心呕吐明显者，加竹茹、白蔻仁、生姜；大便黏滞不畅者，加蚕砂、皂荚子、泽泻、生薏苡仁；津液受伤明显，口干舌燥者，加天花粉、沙参。若寒热错杂，心下痞，呕利肠鸣者，用半夏泻心汤加减。"},{"id":"s135","name":"肝胃不和证","label":"（4）肝胃不和证","group":"实痞","clinic":"脘腹痞闷不舒，胸胁胀满，心烦易怒，善太息，呕恶嗳气，或吐苦水，大便不爽，舌质淡红，苔薄白，脉弦。","analysis":"肝气郁结，乘脾犯胃，肝胃气滞，故胃脘痞满，胸胁胀满，善太息；肝火犯胃，胃失和降，故心烦易怒，呕恶嗳气，或吐苦水；气机不畅，故大便不爽；舌质淡红，苔薄白，脉弦，均为肝胃不和的表现。","treat":"疏肝解郁，和胃消痞。","formulaRaw":"越鞠丸（《丹溪心法》）合枳术丸（《脾胃论》）加减。前者长于疏肝解郁，善解气、血、痰、火、湿、食六郁；后者消补兼施，长于健脾消痞。","formulaName":"越鞠丸合枳术丸加减；后者消补兼施，长于健脾消痞","fangjie":"香附、川芎疏肝散结，行气活血；苍术、神曲燥湿健脾，消食化滞；栀子泻火解郁；枳实行气消痞；白术健脾益胃；荷叶清香升散，和胃醒脾。若胀满较甚者，加柴胡、厚朴、大腹皮、青皮，或用五磨饮子加减；心烦不寐者，加合欢皮、酸枣仁、郁金、石菖蒲；郁而化火，嘈杂反酸者，加黄连、吴茱萸、刺猬皮；痞满日久不愈，舌暗脉涩，加丹参、莪术、三棱、生蒲黄。心下痞满，伴见胸胁苦满、心烦喜呕、口苦、咽干者，用小柴胡汤加减。"},{"id":"s136","name":"脾胃虚弱证","label":"（1）脾胃虚弱证","group":"虚痞","clinic":"脘腹满闷，时轻时重，喜温喜按，纳呆便溏，神疲乏力，少气懒言，语声低微，舌质淡，苔薄白，脉细弱。","analysis":"脾胃虚弱，健运失职，升降失司，故脘腹满闷不舒；脾胃阳气不足，阴寒内生，故脘腹喜温喜按；脾胃虚弱，运化失司，水湿不化，流注肠中，故纳呆便溏；脾气不足，四肢肌肉失养，故神疲乏力，少气懒言，语声低微；舌质淡，苔薄白，脉细弱，均为脾胃虚弱证的表现。","treat":"补气健脾，升清降浊。","formulaRaw":"补中益气汤（《脾胃论》）加减。","formulaName":"补中益气汤加减","fangjie":"黄芪、党参、白术、炙甘草益气健脾，鼓舞脾胃清阳之气；升麻、柴胡协同升举清阳；当归养血和营以助脾；陈皮理气消痞。若胀闷较重者，加枳壳、木香、厚朴、苏梗；纳呆厌食者，加砂仁、神曲、炒麦芽行气消食；心下坚，大如盘者，加大枳实用量，或合枳术丸加减；阳虚明显，痞满夜甚，遇寒加重，四肢不温者，加附子（制）、干姜，或合理中丸加减；舌苔厚腻，湿浊内蕴者，加半夏、茯苓，或改香砂六君子汤加减。"},{"id":"s137","name":"胃阴不足证","label":"（2）胃阴不足证","group":"虚痞","clinic":"脘腹痞闷，嘈杂不舒，饥不欲食，恶心嗳气，口燥咽干，大便秘结，舌质红，苔少，脉细数。","analysis":"胃阴亏虚，胃失濡养，胃失和降，故脘腹痞闷，嘈杂不舒，饥不欲食，恶心嗳气；胃阴不足，上不能滋润咽喉，则口燥咽干，下不能濡润大肠，则大便干结；舌质红，少苔，脉细数，均为胃阴不足的表现。","treat":"养阴益胃，调中消痞。","formulaRaw":"益胃汤（《温病条辨》）加减。","formulaName":"益胃汤加减","fangjie":"生地黄、麦冬、沙参、玉竹滋阴养胃；冰糖濡养肺胃，调和诸药；香橼疏肝理气，消除脘腹痞满。若阴虚较重，火旺嘈杂者，加太子参、石斛、天花粉、百合；食欲不振者，加山楂、谷芽、麦芽；胀满明显者，加佛手、枸橘、厚朴花、玫瑰花；便秘者，加火麻仁、炒莱菔子、玄参；神疲乏力，气短懒言者，加太子参、石斛、莲子、黄精。"}],"linchuang":["重视脾胃，调畅气机。胃痞病位在胃，与脾、肝关系密切，以行气除痞消满为基本治法，需要注意两个方面：一是要重视脾升胃降。脾胃同居中焦，易互相影响，胃病日久，可累及脾，脾虚失运，清气不升，浊气不降，也易致胃痞。常用黄芪、党参、升麻、柴胡、白术等升清阳、降浊阴。二是要使肝气条达。肝主疏泄，对脾胃升降又有调节作用，尤其是忧思恼怒，情志不遂，更易加重肝脾不调，而致胃痞。常用枳实、枳壳、青皮、香附、佛手、陈皮、厚朴等药疏肝行气。因此，治疗胃痞之行气包括脾胃升降之气和肝主疏泄之气两端，且各有虚实的区别。","温清并用，辛开苦降。一般而言，虚者补之，实者泻之，寒者热之，热者寒之。但是临床胃痞的发生、发展，病情缠绵，多为虚实夹杂、寒热并见，治当温清并用，补泻同施。治疗以《伤寒论》半夏泻心汤为基础，温清并用，辛开苦降，消补兼施。此外，若部分胃痞病情迁延日久难愈，久病入络，留痰留瘀，瘀结成毒，可产生诸多复杂变证，治疗应重视化痰散结、祛瘀解毒诸法。"],"yufang":["本病治疗过程中需要重视饮食调摄和精神调摄两个方面。","养成良好的饮食习惯。饮食有节，避免暴饮暴食，同时注意饮食清淡，避免过食肥甘厚味、辛辣醇酒以及生冷之品。避免进食浓茶、咖啡、粗纤维食物。慎用大热、大寒、有毒等易损伤脾胃的药物。","患者应注意精神调摄，需保持乐观的情绪，精神愉快，性情开朗，避免忧思恼怒等情志内伤。注意劳逸结合，适当参加体育锻炼。注意腹部保暖，尤其是在季节交替阶段。"],"attachIds":[]},{"id":"d021","name":"呕吐","kind":"main","parent":null,"chapterNo":"第二十四章","chapterName":"呕吐","yinbing":[{"t":"b","x":"1. 外邪犯胃"},{"t":"p","x":"风、寒、暑、湿及秽浊之邪侵犯胃腑，胃失和降，水谷随胃气上逆而出，即发生呕吐。"},{"t":"p","x":"《古今医统大全·呕吐哕门》云：“卒然而呕吐，定是邪客胃腑，在长夏暑邪所干，在秋冬风寒所犯。”"},{"t":"b","x":"2. 饮食不节"},{"t":"p","x":"暴饮暴食，过食生冷、辛辣、肥甘、油腻之品，嗜饮酒浆，或误食不洁之物，停滞不化，伤及胃腑，致胃气不能下行，上逆而为呕吐。"},{"t":"p","x":"或脾胃受伤，水谷不归正化，变生痰饮，停积胃中，饮邪上逆，发为呕吐。"},{"t":"b","x":"3. 情志失调"},{"t":"p","x":"恼怒抑郁，肝失条达，横逆犯胃，或气郁化火，胃气上逆，而为呕吐。"},{"t":"p","x":"《景岳全书·呕吐》云：“气逆作呕者，多因郁怒，致动肝气，胃受肝邪，所以作呕。”"},{"t":"p","x":"忧思伤脾，脾失健运，食停难化，胃失和降，亦可发生呕吐。"},{"t":"b","x":"4. 脾胃虚弱"},{"t":"p","x":"素体虚弱，或劳倦太过，耗伤中气，或久病中阳不振，纳运失常，胃气不降则吐；亦有胃阴不足，失其润降，引起呕吐。"},{"t":"p","x":"《古今医统大全·呕吐哕门》云：“久病而吐者，胃气虚不纳谷也。”"}],"bingji":[{"t":"p","x":"呕吐的基本病机为胃失和降，胃气上逆。"},{"t":"p","x":"邪气犯胃，或胃虚失和，气逆于上，则出现呕吐。"},{"t":"p","x":"正如《圣济总录·呕吐门》所说：“呕吐者，胃气上而不下也。”"},{"t":"p","x":"病变部位在胃，与肝、脾两脏关系密切。"},{"t":"p","x":"病理性质有虚实之分。实者因邪气所干，虚者由于胃虚不降，其中又有阴虚、阳虚之别。"},{"t":"p","x":"病理因素有外邪、食滞、痰饮、气滞等。"},{"t":"p","x":"在本病病变过程中，病性虚实可相互转化与兼夹。"},{"t":"p","x":"如实证呕吐剧烈，津气耗伤，或呕吐不止，饮食水谷不能化生精微，每易转为虚证。"},{"t":"p","x":"虚证呕吐，复因饮食、外感时邪犯胃，可呈急性发作，表现为虚实夹杂之证。"},{"t":"p","x":"暴病呕吐一般多属邪实，治疗较易，预后良好。"},{"t":"p","x":"久病呕吐，多属正虚，故虚证或虚实夹杂者，病程较长，且易反复发作，较为难治。"},{"t":"p","x":"若呕吐不止，饮食难进，易变生他症，预后不良。"}],"zhenduan":[{"t":"ol","items":["1. 以呕吐食物、痰涎、水液或黄绿色液体，或干呕无物为主症，一日数次或数日一次不等，持续或反复发作，常伴有恶心、纳呆、泛酸、嘈杂、胸脘痞闷等症状。","2. 起病或急或缓，多由感受外邪、饮食不节（洁）、情志不遂以及闻及特殊气味等因素而诱发，或有服用药物、误食毒物史。"]}],"jianbie":[{"t":"b","x":"1. 反胃"},{"t":"p","x":"二者均表现为胃内容物从口中吐出，但反胃是指食物入胃，不能纳化而复吐出的病证，临床上以朝食暮吐、暮食朝吐、宿食不化为主要临床表现。"},{"t":"p","x":"呕吐多为食已即吐，或不食亦吐，吐无定时，吐出食物或痰涎清水。"},{"t":"b","x":"2. 噎膈"},{"t":"p","x":"二者均涉及胃失和降、胃气上逆的病机，临床可出现胃内容物上逆的表现。"},{"t":"p","x":"噎膈是指饮食吞咽受阻，阻塞不顺，甚或汤水不进，食入即吐的病证，病情呈进行性加剧，预后较差。"},{"t":"p","x":"而呕吐多吐无定时，进食顺畅，一般预后较好。"},{"t":"b","x":"3. 呃逆"},{"t":"p","x":"二者都有胃气上逆的病机。"},{"t":"p","x":"呕吐以胃失和降、胃气上逆为病机要点，以胃内容物从口而出为特点。"},{"t":"p","x":"呃逆则以胃气上逆动膈为病机要点，以气冲喉间、呃呃连声、声短而频、不能自止为临床特点。"}],"bianzheng":[{"t":"b","x":"1. 辨虚实"},{"t":"p","x":"呕吐的辨证以虚实为纲。实证多由外邪、饮食所伤，病程短，来势急，吐出物较多；虚证多为脾胃运化功能减退，病程较长，来势徐缓，吐出物较少，或伴有倦怠乏力等症。虚者又有脾胃虚寒和胃阴不足之区别。"},{"t":"b","x":"2. 辨呕吐特点"},{"t":"p","x":"若发病急，伴有表证者，属于外邪犯胃；呕吐酸腐量多，气味难闻者，为宿食留胃；呕吐清水痰涎，胃脘如囊裹水者，属痰饮内停；呕吐泛酸，抑郁善怒者，多属肝气郁结；呕吐苦水者，多因胆热犯胃；反复发作，纳多即吐者，属脾胃虚寒；干呕嘈杂，或伴有口干、似饥而不欲食者，为胃阴不足。"}],"zhize":"呕吐以和胃降逆为基本治则，但应根据虚实之不同分别给予治疗。偏于实者，治宜祛邪为主，分别采用解表、消食、化痰、理气之法，邪去则呕吐自止。偏于虚者，治宜扶正为主，分别采用健脾益气、温中散寒、养阴和胃等法，正复则呕吐自愈。虚实夹杂者，当标本兼顾，审其标本缓急之主次而治之。在辨证基础上，辅以和胃降逆之品，以止呕治标，可提高疗效。","syndrome":[{"id":"s138","name":"外邪犯胃证","label":"1. 外邪犯胃证","group":"","clinic":"突然呕吐，频频泛恶，胸脘满闷，或心中懊侬，伴有恶寒发热，头身疼痛，舌质淡，苔白腻，脉濡。","analysis":"外受风寒之邪，或夏令暑湿秽浊之气，内扰胃腑，浊气上逆，故突然呕吐；邪束肌表，营卫失和，故发热恶寒，头身疼痛；湿浊中阻，气机不利，故胸脘满闷；舌质淡，苔白腻，脉濡，为湿浊蕴阻之象。","treat":"疏邪解表，化浊和中。","formulaRaw":"藿香正气散（《太平惠民和剂局方》）加减。","formulaName":"藿香正气散加减","fangjie":"藿香、苏梗解表化浊，和胃止呕；半夏、生姜降逆止吐；厚朴、白豆蔻、陈皮、茯苓理气降逆，祛湿和胃。如表邪偏重，可加荆芥、防风；宿食积滞，脘胀嗳腐，可加神曲、鸡内金、莱菔子；气机阻滞，脘闷腹胀，可加木香、枳壳；感受暑湿，身热心烦，可去生姜，加黄连、香薷、荷叶；秽浊犯胃，胸脘痞闷，舌苔白腻，可加玉枢丹。"},{"id":"s139","name":"饮食停滞证","label":"2. 饮食停滞证","group":"","clinic":"呕吐酸腐量多，或吐出未消化的食物，嗳气厌食，脘腹胀满，大便秽臭，或秘结或溏泻，舌苔厚腻，脉滑实。","analysis":"食滞内阻，浊气上逆，故呕吐酸腐量多，或吐出未消化食物；食滞中焦，气机不利，故嗳气厌食，脘腹胀满；升降失司，传导失常，则大便秽臭，或秘或溏；舌苔厚腻，脉滑实，为食滞内停之象。","treat":"消食化滞，和胃降逆。","formulaRaw":"保和丸（《丹溪心法》）加减。","formulaName":"保和丸加减","fangjie":"生姜、半夏降逆止呕；山楂、神曲、莱菔子消食和胃；陈皮、枳实理气；连翘散结清热。若伤于肉食而吐，重用山楂；伤于米食而吐，可加谷芽；伤于面食而吐，重用莱菔子，加麦芽；伤于豆制品而吐，可加生萝卜汁；酒积者，重用神曲，可加白豆蔻、枳椇子、葛花；鱼蟹积者，可加紫苏叶、生姜。因食物中毒呕吐，若邪在上脘，用烧盐方探吐；食滞在肠，腹胀拒按或便秘，可加小承气汤；胃中积热上冲，食已即吐，口臭而渴，苔黄脉数，加黄芩、黄连，或改用大黄甘草汤合橘皮竹茹汤。"},{"id":"s140","name":"痰饮内阻证","label":"3. 痰饮内阻证","group":"","clinic":"呕吐清水痰涎，或胃部如囊裹水，脘痞满闷，纳谷不佳，头眩，心悸，或逐渐消瘦，舌质淡，舌苔白滑或腻，脉沉弦滑。","analysis":"痰饮内停，胃失和降，故呕吐清水痰涎，或胃部如囊裹水；饮阻中焦，气机不畅，故见脘痞满闷，纳谷不佳；饮邪上犯清阳，水气凌心，久耗正气，故见头眩，心悸，或逐渐消瘦；舌淡，苔白滑或腻，脉沉弦滑，为痰饮内停之象。","treat":"温化痰饮，和胃降逆。","formulaRaw":"小半夏汤（《金匮要略》）合苓桂术甘汤（《金匮要略》）加减。前方和胃降逆，后方温阳化饮。","formulaName":"小半夏汤合苓桂术甘汤加减","fangjie":"半夏、生姜和胃降逆；茯苓、白术、陈皮、甘草健脾利水化湿；桂枝温化痰饮。若湿阻中焦，气机不利，脘痞胀满，苔厚，加苍术、厚朴、枳实；脘闷不食，加白豆蔻、砂仁。胸膈烦闷，口苦，心烦不寐，舌苔黄腻，痰郁化热，可改用黄连温胆汤加减。"},{"id":"s141","name":"肝气犯胃证","label":"4. 肝气犯胃证","group":"","clinic":"呕吐吞酸，或干呕泛恶，脘胁胀痛，烦闷不舒，嗳气频频，每遇情志失调而发作或加重，舌边红，苔薄腻或微黄，脉弦。","analysis":"肝气不疏，横逆犯胃，胃失和降，故呕吐吞酸，干呕泛恶；肝失疏泄，气机郁滞，故见脘胁胀痛，烦闷，嗳气，遇情志失调而发作或加重；舌边红，苔薄腻或微黄，脉弦，为肝气郁结，肝郁化热之象。","treat":"疏肝和胃，降逆止呕。","formulaRaw":"半夏厚朴汤（《金匮要略》）合左金丸（《丹溪心法》）加减。前方行气开郁，化痰降逆；后方辛开苦降，泻肝和胃。","formulaName":"半夏厚朴汤合左金丸加减","fangjie":"厚朴、紫苏、香附、佛手疏肝解郁，理气和胃；半夏、生姜、旋覆花降逆止呕；吴茱萸、黄连辛开苦降，泻肝安胃；茯苓渗湿健脾。若肝郁化热，心烦口渴，可加竹茹、黄芩、芦根；口苦嘈杂，大便秘结，可加大黄、枳实；口燥咽干，胃中灼热，可去厚朴、紫苏等香燥药，加沙参、麦冬、石斛；呕吐日久，诸药无效，胸胁刺痛，舌有瘀斑，可加桃仁、红花等。呕吐苦水甚或黄绿水，属于“胆呕”，多由胆热犯胃所致，可改用黄连温胆汤合左金丸加黄芩、连翘、代赭石等。"},{"id":"s142","name":"脾胃虚寒证","label":"5. 脾胃虚寒证","group":"","clinic":"饮食稍有不慎，即易呕吐，时发时止，食入难化，胸脘痞闷，不思饮食，面色㿠白，倦怠乏力，四肢不温，口干不欲饮，大便溏薄，舌质淡，苔薄白，脉濡弱。","analysis":"脾胃虚弱，中阳不振，水谷腐熟运化不及，故饮食稍有不慎即吐，时发时止，食入难化；脾虚运化失司，气机阻滞，而见胸脘痞闷，不思饮食；脾阳不足，温煦运化失职，而见面色㿠白，倦怠乏力，四肢不温，便溏；中焦虚寒，气不化津，则口干不欲饮；舌质淡，苔薄白，脉濡弱，为脾胃虚寒之象。","treat":"温中健脾，和胃降逆。","formulaRaw":"理中丸（《伤寒论》）加减。","formulaName":"理中丸加减","fangjie":"人参、白术、炙甘草健脾益气；干姜、吴茱萸温中和胃；半夏、砂仁和胃理气，降逆止呕。若胃虚气逆，呕恶频繁，嗳气频作，中脘痞硬，可加代赭石、旋覆花、枳壳；阳虚水饮内停，呕吐清水，胃脘冷胀，四肢清冷，加附子（制）、川椒、桂枝等。"},{"id":"s143","name":"胃阴不足证","label":"6. 胃阴不足证","group":"","clinic":"呕吐反复发作，或时作干呕，恶心，似饥而不欲食，胃脘嘈杂，口干咽燥，舌红少津，苔少，脉细数。","analysis":"胃阴不足，胃失濡润，气失和降，故呕吐反复发作，或时作干呕恶心；胃阴亏虚，失于腐熟，虚热内扰，而见似饥不欲食，胃脘嘈杂；阴液亏虚，不能上承，则口干咽燥；舌红少津，苔少，脉细数，为阴虚内热之象。","treat":"滋养胃阴，降逆止呕。","formulaRaw":"麦门冬汤（《金匮要略》）加减。","formulaName":"麦门冬汤加减","fangjie":"北沙参、麦冬、石斛、乌梅养阴生津；太子参、谷芽、甘草益气和胃；半夏降逆止呕。若呕吐甚，可加竹茹、橘皮、枇杷叶；阴虚重，大便燥结，舌红无苔者，可加生地黄、天花粉、火麻仁、白蜜等。"}],"linchuang":["合理使用和胃降逆药物。胃气上逆是呕吐发病的关键，治疗呕吐当以和胃降逆为基本治法，故在审因论治中，不论何种治法，皆应配合和胃降逆药物，以顺应胃气以下行为顺的正常生理功能，呕吐始能得止。处方宜精，选药宜少，常用降逆药如半夏、生姜、苏梗、黄连、砂仁、丁香、旋覆花、代赭石等。历代医家认为，降逆止呕药中，半夏、代赭石效力最著。而于辛开苦降一法中，生姜味辛，黄连味苦，为该治法的代表性配伍，临床可参用。","辨可吐与止吐。由于呕吐既是病态，又是人体驱除胃中病邪的一种保护性反应，如遇饮食腐秽，停饮积痰，或误吞毒物，邪停上脘，欲吐不能或吐而未净者，不应止吐，当因势利导，给予探吐以驱除病邪。《备急千金要方》云：“宿食在上脘，宜吐之。”此外，由于呕吐可涉及外感内伤多种疾病，在辨证施治的同时，应结合辨病，明确发病原因，对因治疗，以消除致吐之源。","辨可下与禁下。一般而论，呕吐不宜用下法，因呕吐病位在胃，不应用下药攻肠。若呕吐属虚者，下之更有虚虚之弊。若呕吐属外邪者，当逐邪外达，其呕自止。亦不宜攻里，恐引邪深入。《金匮要略》有“病人欲吐者，不可下之”之训。《医宗金鉴》谓：“初吐切不可下，恐逆病势也。”但下法又并非所有呕吐都绝对禁忌，如呕吐因于胃肠实热，又兼大便秘结者，必要时就可用下法，通其大便可折其上逆之势。《金匮要略》就有“食已即吐者，大黄甘草汤主之”的记载。可见呕吐可下与否，当因证而异。","用药禁忌。《丹溪心法》曾谓：“呕吐药忌栝蒌、杏仁、桃仁、萝卜子、山栀，皆要作吐。”认为呕吐要忌用苦寒、滑腻或性味重浊等容易伤胃、碍胃之品。此外，治疗呕吐在服药时也应少量频服，并根据病情采取热服或冷服，或加入少量生姜或姜汁，以免格拒难下。","注意呕吐变证。剧烈呕吐或顽固性呕吐日久，多伤津损液，甚至引起气随津脱等变证，应采取纠正脱水、调整水及电解质平衡等措施，防治变证。"],"yufang":["预防呕吐发生，要注意饮食卫生，避免进食腥秽之物，不饥饱无度，脾胃虚寒者应忌食生冷之品，胃中积热或胃阴不足者应忌食辛辣、香燥之品。要注意精神调摄，心情要舒畅，避免精神刺激，可防止因情志因素引起的呕吐。","发生呕吐时，要注意适当休息，注意寒温适宜。食物要易于消化，宜清淡，少量多餐，忌食生冷油腻之物。若呕吐剧烈，粥汤入胃即吐出之危重病者，系胃气衰败，可用《景岳全书》“人参煮粥食之”法。重症、昏迷或体力差的患者要侧卧，防止呕吐物进入气道。"],"attachIds":[]},{"id":"d022","name":"呃逆","kind":"main","parent":null,"chapterNo":"第二十五章","chapterName":"呃逆","yinbing":[{"t":"b","x":"1. 寒邪犯胃"},{"t":"p","x":"外感寒凉之邪，内客脾胃，寒遏中阳，胃气失和，寒气上逆动膈，导致呃逆之证。"},{"t":"p","x":"《景岳全书·呃逆》云：“寒气犯胃，中焦虚冷，气逆为哕。”"},{"t":"b","x":"2. 饮食不当"},{"t":"p","x":"过食生冷，或过用寒凉药物，寒气客胃，循经犯膈，膈间不利，胃气不降，肺失宣肃，气逆上冲咽喉而呃；过食辛热厚味，滥用温补之剂，燥热内盛，腑气不行，气逆动膈，上冲为呃。"},{"t":"p","x":"《景岳全书·呃逆》曰：“皆其胃中有火，所以上冲为呃。”"},{"t":"b","x":"3. 情志不遂"},{"t":"p","x":"情志不遂，致肝气郁结，进而逆气动膈，或气郁化火，灼津成痰，痰火蕴胃，或肝郁乘脾，或忧思伤脾，运化失职，滋生痰浊，或素有痰饮内停，复因恼怒气逆，逆气夹痰浊上逆动膈，发为呃逆。"},{"t":"p","x":"《古今医统大全·咳逆》曰：“凡有忍气郁结积怒之人，并不得行其志者，多有咳逆之证。”"},{"t":"b","x":"4. 体虚久病"},{"t":"p","x":"素体不足，年高体弱，或大病久病，正气未复，或吐下太过，虚损误攻，均可损伤中气，或胃阴耗伤，胃失和降，发生呃逆。"},{"t":"p","x":"甚则病深及肾，肾气失于摄纳，浊气上冲，上逆动膈，发生呃逆。"},{"t":"p","x":"大病久病出现呃逆，多提示预后不良。"},{"t":"p","x":"《证治汇补·呃逆》曰：“伤寒及滞下后，老人、虚人、妇人产后多有呃症者，皆病深之候也。若额上出汗，连声不绝者，危殆难治。”"}],"bingji":[{"t":"p","x":"呃逆的基本病机是胃失和降，膈间气机不利，气逆动膈。"},{"t":"p","x":"病变部位在膈，病变脏腑的关键在胃，且常与肺、肾、肝、脾有关。"},{"t":"p","x":"病理性质有虚实之分。实证多为胃寒、胃热、气滞、痰阻致胃失和降，虚证常因脾胃阳虚或胃阴不足等正虚气逆，更有虚实夹杂之证。"},{"t":"p","x":"病理因素有寒凝、火郁、气滞、痰饮、血瘀、虚损。"},{"t":"p","x":"呃逆的病机转化取决于病邪性质和正气强弱。"},{"t":"p","x":"热邪为病者，如胃中积热或肝郁日久化火，易于损阴耗液而转化为胃阴亏虚。"},{"t":"p","x":"气郁、食滞、痰饮为病者，皆能伤及脾胃，转化为脾胃虚弱证。"},{"t":"p","x":"顽固性呃逆患者，常可出现胃气衰败、气阴两虚或邪毒内陷所致的各种危候，且随病程迁延不愈而加重。"},{"t":"p","x":"当出现呃逆频急不止、声低气怯（或声高气促）、烦躁不安、神识昏蒙、高热不退、大汗淋漓、气息急促、脉象疾数或微细欲绝等症状时，为病情急剧恶化、正气欲脱或邪气炽盛的凶险征兆，常预后不佳。"}],"zhenduan":[{"t":"ol","items":["1. 呃逆以气逆上冲，喉间呃呃连声，声短而频，不能自止为主症。其呃声或高或低，或疏或密，间歇不定。","2. 常伴有胸膈痞闷，胃脘不适，或情绪不定。","3. 多有饮食不当、情志不遂、感受寒凉、胸腹手术等诱发因素，或有体虚久病病史。"]}],"jianbie":[{"t":"b","x":"1. 噎膈"},{"t":"p","x":"噎膈重症与顽固性呃逆均可出现食饮难下、胸膈阻塞感。"},{"t":"p","x":"呃逆为气逆呃声，虽影响进食，但无吞咽梗阻，食入不阻。"},{"t":"p","x":"噎膈为吞咽梗塞疼痛，食物难入或格拒吐出，进行性加重，后期骨瘦如柴，与呃声无关。"},{"t":"b","x":"2. 干呕与嗳气"},{"t":"p","x":"三者同属胃气上逆的表现。"},{"t":"p","x":"呃逆为胃气上逆动膈，气从膈间上逆，气冲喉间，呃呃连声，声短而频，不能自止。"},{"t":"p","x":"干呕乃胃气上逆，发出呕吐之声，属于有声无物的呕吐，其声长短不一，呈不规则性发作。"},{"t":"p","x":"嗳气乃饮食不消化，胃中浊气蕴积上逆，冲咽而出，发出沉缓的嗳气声，常伴酸腐气味，多在饱餐后出现，故张介宾称之为“饱食之息”，又称为“噫气”，与呃逆频频发出的呃呃响声有显著区别。"},{"t":"p","x":"在预后方面，干呕与嗳气只是脾胃疾病的症状，与疾病转归无明显关联，而呃逆若出现在危重患者时，常为临终先兆。"}],"bianzheng":[{"t":"b","x":"1. 辨虚实"},{"t":"p","x":"呃逆有虚实之分。实证多为寒凝、火郁、气滞、痰阻等致胃失和降而产生，其呃声响亮有力，连续发作；虚证每由胃阴耗损或脾胃亏虚等使正虚气逆引起，其呃声时断时续，气怯乏力。"},{"t":"b","x":"2. 辨寒热"},{"t":"p","x":"寒证因寒邪犯胃，胃失和降，上逆动膈，呃声沉缓有力，遇寒凉更甚；热证属燥热伤胃，阳明腑气不顺，胃气上逆，呃声高响且短，气涌而出。"}],"zhize":"呃逆的治疗以理气和胃、降逆止呃为基本治则。治疗要分清寒、热、虚、实，分别施以祛寒、清热、补虚、泻实之法。同时可辅以降逆止呃之品，以利膈间之气。对于重危病证中出现的呃逆，可予补益元气，急救胃气，或施益气、救阴、温阳等法，以固其本。","syndrome":[{"id":"s144","name":"胃中寒冷证","label":"1. 胃中寒冷证","group":"","clinic":"呃声沉而有力，胃脘部及膈间不舒，得热则减，遇寒则甚，进食减少，喜食热饮，口淡不渴，舌质淡，苔白，脉迟缓。","analysis":"寒邪客胃，胃气上逆，冲膈动呃，故呃声沉而有力，胃脘及膈间不舒；寒性凝敛，得热则缓，遇寒则剧；寒邪壅盛，内伤脾胃，故见进食减少，喜食热饮；津液未伤，则口淡不渴；舌质淡，苔白，脉迟缓，均为胃中寒冷之象。","treat":"温中散寒，降逆止呃。","formulaRaw":"丁香散（《三因极一病证方论》）加减。","formulaName":"丁香散加减","fangjie":"丁香、柿蒂温胃降逆止呃；高良姜温中散寒助阳；炙甘草调和诸药。若寒气较重者，可加吴茱萸、肉桂、乌药；寒凝气滞，脘腹痞满者，可加枳壳、厚朴；寒凝食滞，脘闷嗳腐者，可加炒莱菔子、半夏、槟榔；有表寒之邪者，可加紫苏、荆芥、防风、生姜。"},{"id":"s145","name":"胃火上逆证","label":"2. 胃火上逆证","group":"","clinic":"呃声洪亮有力，冲逆而出，口臭烦渴，多喜冷饮，脘腹满闷，大便秘结，小便短黄，舌质红，苔黄或燥，脉滑数。","analysis":"胃火炽盛，腑气不通，胃气壅滞，夹火上逆冲膈，故呃声洪亮有力，冲逆而出；火热内盛，灼伤胃津，可见口臭烦渴，多喜冷饮；胃热气滞，中焦壅塞，则脘腹满闷；热盛津伤，可见大便秘结，小便短黄；舌质红，苔黄或燥，脉滑数，均为胃火炽盛，津液耗伤之象。","treat":"清胃泻热，降逆止呃。","formulaRaw":"竹叶石膏汤（《伤寒论》）加减。","formulaName":"竹叶石膏汤加减","fangjie":"竹叶、生石膏清热除烦，生津止渴；沙参、麦冬益气养阴，生津润燥；半夏降逆止呕，兼防滋腻；甘草、粳米益气和胃。若呃逆甚，可加竹茹、柿蒂，或用橘皮竹茹汤；若腑气不通，脘腹痞满者，可加生大黄、厚朴、枳实。若胸膈烦热，大便秘结者，可用凉膈散。"},{"id":"s146","name":"气机郁滞证","label":"3. 气机郁滞证","group":"","clinic":"呃逆连声，常因情志不畅而诱发或加重，胸胁满闷，脘腹胀满，或有嗳气纳呆，肠鸣矢气，苔薄腻，脉弦。","analysis":"肝失疏泄，横逆犯胃，胃气上逆动膈，故呃逆连声；因情志不遂，气滞更甚，故常因情志不畅而诱发或加重；肝郁乘脾，升降失司，故胸胁满闷，脘腹胀满，或有嗳气纳呆；气滞肠道，则肠鸣矢气；苔薄腻，脉弦，均为肝郁气滞之象。","treat":"顺气解郁，降逆止呃。","formulaRaw":"五磨饮子（《医方考》）加减。","formulaName":"五磨饮子加减","fangjie":"木香、乌药行气解郁，疏肝调中；沉香、槟榔降气导滞，破结下气；枳实破气消积，化痰除痞。可酌加丁香、代赭石降逆止呃。若肝郁明显者，可加川楝子、郁金；若心烦口苦，气郁化火者，可加栀子、丹皮；若痰蕴化热者，加黄连、竹茹、瓜蒌；若肝气动风者，可加钩藤，合芍药甘草汤等。若气逆痰阻，心下痞硬，嗳气者，可用旋覆代赭汤加陈皮、茯苓；气滞日久成瘀，瘀血内结，胸胁刺痛，久呃不止者，可用血府逐瘀汤加减。"},{"id":"s147","name":"脾胃阳虚证","label":"4. 脾胃阳虚证","group":"","clinic":"呃声低长无力，气不得续，泛吐清水，脘腹不舒，喜暖喜按，手足不温，食少乏力，大便溏薄，舌质淡，苔薄白，脉沉细。","analysis":"中阳不足，胃失温养，气逆动膈，故呃声低长无力，气不得续；寒饮停聚，胃气上逆，则泛吐清水；阳虚寒凝，气机不畅，可见脘腹不舒，喜暖喜按，手足不温；脾虚失运，胃纳无权，则食少乏力，大便溏薄；舌质淡，苔薄白，脉沉细，皆为脾胃阳虚之象。","treat":"温补脾胃，和中止呃。","formulaRaw":"理中丸（《伤寒论》）加减。","formulaName":"理中丸加减","fangjie":"人参、白术补气健脾，助运中州；干姜温中祛寒，扶阳抑阴；炙甘草益气和中，调和诸药。可酌加吴茱萸、丁香、柿蒂温胃止呃。若脾虚气滞者，可加半夏、陈皮；若呃声难续，气短乏力，中气大亏者，可加黄芪、党参；肾阳亏虚，形寒肢冷，腰膝酸软，呃声难续者，可加肉桂、紫石英、补骨脂、山萸肉，或用四逆加人参汤加减。"},{"id":"s148","name":"胃阴不足证","label":"5. 胃阴不足证","group":"","clinic":"呃声短促而不连续，口干咽燥，不思饮食，或有烦渴，或食后饱胀，大便干结，舌红苔少而干，脉细数。","analysis":"胃阴亏虚，虚热内生，胃失濡润，气逆动膈，故呃声短促断续；阴津不足，则口干咽燥，不思饮食；虚热扰胃，可见烦渴；胃虚气滞，则食后饱胀；津亏肠燥，故大便干结；舌红少苔，脉细数，均为胃阴不足之象。","treat":"养胃生津，降逆止呃。","formulaRaw":"益胃汤（《温病条辨》）合橘皮竹茹汤（《金匮要略》）加减。前方养胃生津，后方益气清热，和胃降逆。","formulaName":"益胃汤合橘皮竹茹汤加减","fangjie":"沙参、麦冬、玉竹、生地黄滋养胃阴，生津润燥；橘皮、竹茹、生姜、柿蒂和胃降气，降逆止呃。若阴虚火旺，胃火上炎，咽喉不利者，可加知母、芦根、石斛；若神疲乏力，气阴两虚者，可加党参或西洋参、山药；大便干结者，加玄参、火麻仁、蜂蜜。若病情危重，烦热咽干，神疲汗出者，可用生脉散加减。"}],"linchuang":["辨清共病脏腑。因胃居膈下，以降为顺，“动膈”既是指膈间气机不利，又为胃气之逆所触动，故本病病变部位在胃和膈，二者又与肺、脾、肝、肾相关。如肺处膈上，主肃降，手太阴肺之经脉还循胃口，上膈属肺，肺之宣肃影响胃气和降，膈居肺胃之间，肺胃受影响时，膈间气机不利，气逆上冲于喉间，而为呃逆；胃之和降有赖于脾气健运和肝之条达，若脾失健运或肝失条达，则胃失和降，气逆动膈，遂成呃逆；肺之肃降与胃之和降，亦有赖肾之摄纳，若肾气不足，肾失摄纳，肺胃之气，失于和降，浊气上冲，夹胃气上逆动膈，亦可形成呃逆之病。","活用降逆止呃法。胃气上逆动膈是呃逆发病的关键，呃逆当以理气和胃、降逆止呃为基本治法。首先，无论寒热虚实，皆可酌加降逆止呃之品，如柿蒂、丁香、制半夏、竹茹、旋覆花、刀豆子等。其次，因肃降肺气亦有助于胃气和降，可随证加入枇杷叶、杏仁等。再次，膈肌痉挛多与肝气郁结，气机逆乱相关，若气机逆乱致筋脉失养，可参照肝风内动之缓急治法，轻则可选芍药甘草汤以缓急止痉，甚则加钩藤、全蝎、僵蚕等平肝息风之品，常可提高疗效。","重视应用针灸等其他疗法。《黄帝内经》谓“圣人杂合以治，各得其所宜”，这是中医治病的特色，呃逆尤为适用。除内服汤药外，针灸、穴位注射等也常有疗效，常用穴位如内关、攒竹、翳风、膻中、中脘、气海、足三里等。另外，取嚏、眼眶按压、牵舌、耳穴贴压、推拿点穴以及中药敷贴等疗法，皆为临床常用且行之有效的方法。","临证应辨病情轻重。呃逆一证在诊断时首先应分清是生理现象还是疾病状态。若一时性气逆而作呃，无持续或反复发作者，属生理现象，可不药而愈。若呃逆持续或反复发作，难以自制，则需要治疗。对于久病、重病、大病或年老正虚患者发生呃逆，表现为断续不继，呃声低微，饮食难进，且脉沉细伏者，俗称“败呃”，是胃气衰败之危笃证候，提示胃气衰败，预后不良。正如严用和《济生方·咳逆论治》云：“大抵老人、虚人、久病人及妇人产后，有此症者，皆是病深之候，非佳兆也。”务须悉心观察病情变化，慎重处置。"],"yufang":["预防呃逆的发生，首当顾护胃气，谨避外邪侵袭。另需注重调节情志，避免忧思恼怒扰动肝胃之气；饮食宜温软有节，忌暴饮暴食、过食生冷辛辣，以防寒热直中胃腑；素体虚寒者尤需避风寒，慎用苦寒药物。既病防变则贵在早治，短暂呃逆可饮温水、深呼吸以平逆气；若呃逆反复或迁延，当深究病因，积极治疗其原发病，截断胃气衰败之传变。","呃逆调护以安胃降逆为纲。饮食宜温热流食，少食多餐，细嚼慢咽；忌豆类、薯类等易滞气之物。情志宜宁神定志，消除焦躁。起居避风寒，腹背部保暖，危重患者取半卧位，以减轻膈肌牵动。若见顽固呃逆昼夜不休，当密切观察病情变化。"],"attachIds":[]},{"id":"d023","name":"噎膈","kind":"main","parent":null,"chapterNo":"第二十六章","chapterName":"噎膈","yinbing":[{"t":"b","x":"1. 饮食不节"},{"t":"p","x":"嗜酒无度，恣食膏粱厚味、辛辣炙煿，或喜烫食，灼伤食管，损伤脾胃，胃肠积热，津液耗损，痰热内结，或食物粗糙，或常食腐烂霉变之物，或喜食腌制熏烤食物，损伤食管、胃脘而致。"},{"t":"p","x":"《临证指南医案·噎膈反胃》云：“酒湿厚味，酿痰阻气，遂令胃失下行为顺之旨，脘窄不能纳物，噎膈所由作矣。”"},{"t":"b","x":"2. 情志内伤"},{"t":"p","x":"忧思伤脾，脾伤则气结，健运失职，滋生痰浊；抑郁恼怒伤肝，肝失疏泄，气机郁滞，水液、血液运行不畅，痰浊、瘀血阻滞食管、胃脘，成为噎膈。"},{"t":"p","x":"《素问·通评虚实论》指出噎膈与突然的忧愁情绪有关。"},{"t":"p","x":"《景岳全书·噎膈》指出：“噎膈一证，必以忧愁思虑，积劳积郁，或酒色过度，损伤而成。”"},{"t":"b","x":"3. 久病年高"},{"t":"p","x":"如胃痛、呕吐等久病，耗伤气血，不能濡养咽嗌，胃脘枯槁，或年老体弱，精血亏虚，不能滋养脾胃，致脾胃气阴渐伤，气虚津气失布，日久痰气瘀阻于食管，发为噎膈；胃阴不足，不能濡养食管，致其干涩，发为噎膈；纵欲太甚，真精亏耗，阴虚液竭，食管干涩，造成噎膈。"},{"t":"p","x":"《景岳全书·噎膈》云：“此证惟中衰耗伤者多有之。”“正以命门无火，气不化精，所以凝结于下而治节不行……即噎膈之属也。”"},{"t":"p","x":"《医贯·噎膈》谓：“惟男子年高者有之，少无噎膈。”"},{"t":"p","x":"这些均说明噎膈的发生与年老体弱密切相关。"}],"bingji":[{"t":"p","x":"噎膈的基本病机是气、痰、瘀交结，阻隔于食管、贲门，引起食管、贲门拘急、狭窄，吞咽食物哽噎不顺，或不能下咽至胃，食入即吐。"},{"t":"p","x":"病变部位在食管，为胃所主，与肝、脾、肾密切相关。"},{"t":"p","x":"病理性质有虚实两方面，常为本虚标实之证。本虚与脾肾亏虚，津液枯槁，不能濡养，或阳虚失于温煦有关；标实为气滞、痰结、血瘀或瘀结成毒，阻隔于食管、贲门，致使哽噎不顺，饮食难下或食而即吐，发为噎膈。"},{"t":"p","x":"病理因素主要为气滞、痰结、瘀血。"},{"t":"p","x":"本病病机转化是由噎至膈的过程。"},{"t":"p","x":"疾病初期，以痰气交阻为主，阻遏于食管、贲门，常为实证，病情较轻，日久则发展为瘀血内结，形成痰、气、瘀互结，或瘀结成毒，造成食管狭窄，进而伤及阴液，使病情由轻转重。"},{"t":"p","x":"病程迁延日久，阴津耗竭殆尽，胃腑失于濡养，胃阴枯竭，进而阴损及阳，脾肾阳气衰败，运化、温煦功能失常，最终可形成气痰瘀毒俱阻于内、阴阳气血俱虚于内的重症格局。"}],"zhenduan":[{"t":"ol","items":["1. 轻症患者主要表现为自觉胸骨后不适，有烧灼感或疼痛，食物通过时有滞留感或轻度梗阻感，咽部干燥或有异物感。重症患者见持续性、进行性吞咽困难，咽下梗阻，食入即吐，吐出黏液或夹白色泡沫，严重时伴有胸骨后或背部肩胛区持续性钝痛。","2. 常伴有胃脘不适、精神疲惫、肌肤甲错等，表现为进行性消瘦，形体枯槁，大肉尽脱，或出现水肿胀满等。","3. 患者可有情志不畅、酒食不节、进食腌制和霉变食物等病史。常见于年老体弱或久病患者。"]}],"jianbie":[{"t":"b","x":"1. 反胃"},{"t":"p","x":"反胃和噎膈均有食入即吐的表现。"},{"t":"p","x":"噎膈的发病部位在食管、贲门，基本病机为气、痰、瘀互结；反胃的病位在胃，基本病机为脾胃衰败，胃中无火，难于腐熟食入之谷物。"},{"t":"p","x":"噎膈主要表现为吞咽食物困难，哽噎难下，旋食旋吐，或徐徐吐出，吐出物往往未能进入胃；反胃则无吞咽障碍，饮食可下，食在胃中，宿食不化，常表现为朝食暮吐，暮食朝吐，吐尽方舒，吐出物为胃中食物。"},{"t":"b","x":"2. 梅核气"},{"t":"p","x":"二者均有咽中不舒感。"},{"t":"p","x":"噎膈是气、痰、瘀交结，有形之邪阻隔于食管、贲门所致；梅核气是气郁痰阻，无形之邪阻结于咽部所致。"},{"t":"p","x":"噎膈主要表现为吞咽困难，食不能下，旋食旋吐，或徐徐吐出，日久体重减轻，日渐消瘦；梅核气主要表现为自觉咽中有异物感，吐之不出，咽之不下，但饮食可顺利咽下，无噎塞感，不影响体重。"},{"t":"p","x":"噎膈多见于中老年人，嗜食肥甘厚味、醇酒、腌制食品者；梅核气多见于性格内向者或女性患者。"}],"bianzheng":[{"t":"b","x":"1. 辨虚实标本"},{"t":"p","x":"本病初期，多以实证为主，常因情志失调、饮食不节所致，久病多为本虚标实，虚中夹实之证。标实为气滞、痰凝、血瘀或瘀结成毒，阻隔于食管、贲门。本虚与脾肾亏虚，阴津枯槁，失于濡养，或阳虚不能温煦有关，致使吞咽哽噎不顺，饮食难下或食而复出。"},{"t":"b","x":"2. 辨病理属性"},{"t":"p","x":"一般由忧思恼怒等引起，表现为吞咽之时哽噎不顺，胸胁胀痛，嗳气频作，常在情志不遂时加重者，属气郁；若吞咽困难，胸膈满闷，泛吐痰涎者，属痰湿；若饮食梗阻难下，胸膈疼痛，痛如针刺，痛处不移，面色晦暗，肌肤甲错者，属血瘀；若病情进展迅速，噎膈症状日益加重，吐出物为黏液或夹白沫，体重下降，甚至大肉尽脱，形销骨立者，多为瘀结成毒。"}],"zhize":"噎膈的治疗以“急则治标，缓则治本”为基本原则，分清标本虚实，主次兼顾。初期本病以标实为主，重在治标，宜理气、化痰、消瘀、解毒，并可少佐滋阴养血润燥之品。晚期以正虚为主，重在治本，宜滋阴养血，或温补脾肾，益气温阳，少佐理气、化痰、消瘀之药。虚实夹杂者，当标本同治，攻补兼施，权衡用药。","syndrome":[{"id":"s149","name":"痰气交阻证","label":"1. 痰气交阻证","group":"","clinic":"吞咽食物哽噎不顺，胸膈满闷，或见疼痛，病情与情志变化密切相关，嗳气呃逆，善太息，泛吐痰涎，口干咽燥，大便秘结，舌质红，苔薄腻，脉弦滑。","analysis":"痰气交阻，闭塞胸膈，食管气机不利，故见吞咽食物哽噎不顺，胸膈满闷，泛吐痰涎；因情志不舒，肝气郁结，故嗳气呃逆，善太息，与情志关系密切；日久气郁化火，口咽干燥，大便秘结；舌质红，苔薄腻，脉弦滑，为气郁痰阻之象。","treat":"开郁化痰，润燥降气。","formulaRaw":"启膈散（《医学心悟》）加减。","formulaName":"启膈散加减","fangjie":"沙参、贝母润燥化痰，泻热散结；郁金、砂仁、丹参开郁利气，活血化痰；茯苓健脾和中，渗湿化痰；杵头糠开胃下气；荷叶蒂醒脾和胃。若嗳气呕吐，心下痞硬明显，加沉香、旋覆花、代赭石、刀豆壳，或用旋覆代赭汤加减；呕吐痰涎量多者，加法半夏、陈皮、全瓜蒌，或含化玉枢丹；胸胁胀痛明显者，加香附、佛手；若咽喉干燥、吞咽时自觉食管灼痛，加沙参、麦冬、玉竹；心烦口干，气郁化火者，加山豆根、栀子、金果榄。"},{"id":"s150","name":"津亏热结证","label":"2. 津亏热结证","group":"","clinic":"吞咽食物梗塞而痛，食物难进，入而复出，甚则水饮难进，口干咽燥，五心烦热，形体消瘦，小便短赤，大便干结如羊屎，舌质光红，干裂少津，脉细数。","analysis":"气、痰、瘀酿毒化热生火，食管失于濡润而干涩，故吞咽食物哽噎而痛，食物难进；日久伤阴，失于濡养，故见口咽干燥，五心烦热，小便短赤，大便干结如羊屎；饮食不下，生化乏源，故见形体消瘦；舌质光红，干裂少津，脉细数，为津亏热结之象。","treat":"滋阴清热，润燥生津。","formulaRaw":"沙参麦冬汤（《温病条辨》）加减。","formulaName":"沙参麦冬汤加减","fangjie":"沙参、麦冬、玉竹清热滋阴，润肺胃之燥；桑叶、天花粉养阴泻热；扁豆、甘草健脾和胃。若兼有胸闷胸痛，加郁金、枳壳、川芎、参三七；胃火偏盛者，加栀子、黄连；大便干结，坚如羊粪者，加火麻仁、郁李仁、白蜜、何首乌；阴津亏虚，食管干涩，口燥咽干者，加银柴胡、玄参、知母，或饮五汁安中饮。烦渴咽燥，噎食难下，或食入即吐，吐物酸热者，改用竹叶石膏汤加大黄。"},{"id":"s151","name":"瘀血内结证","label":"3. 瘀血内结证","group":"","clinic":"饮食难下，食入即吐，呕出物如赤豆汁，胸膈疼痛，固定不移，面色晦暗，肌肤甲错，形体羸瘦，舌质紫暗，有瘀点或瘀斑，脉细涩。","analysis":"瘀血内结，阻遏于食管，食管狭窄、干涩，故饮食难下，食入即吐；食管络脉受损，故呕吐物如赤豆汁，胸膈疼痛；长期饮食不下，生化无源，机体失养，故肌肤甲错，形体羸瘦；舌质紫暗，有瘀点、瘀斑，脉细涩，为瘀血内结之象。","treat":"破结行瘀，滋阴养血。","formulaRaw":"通幽汤（《脾胃论》）加减。","formulaName":"通幽汤加减","fangjie":"生地黄、熟地黄、当归滋阴养血；桃仁、红花、丹参活血化瘀；升麻升清降浊；炙甘草益脾和中；五灵脂、乳香、没药、蜣螂活血破瘀止痛；海藻、昆布、浙贝母软坚化痰。若瘀阻显著者，加水蛭、三棱、莪术、急性子；呕吐痰涎较甚者，加半夏、瓜蒌、莱菔子、贝母；呕吐物如赤豆汁者，可加仙鹤草、白及，或另服云南白药；夹热毒者，可加半枝莲、白花蛇舌草、天花粉；若阴虚内热明显者，可加玄参、知母；服药即吐，难于下咽者，可先含化玉枢丹，随后再服汤药。"},{"id":"s152","name":"气虚阳微证","label":"4. 气虚阳微证","group":"","clinic":"吞咽受阻，饮食不下，泛吐黏液白沫，面浮足肿，畏寒肢冷，面色㿠白，形瘦神衰，腹胀便溏，舌质淡，苔白，脉细弱。","analysis":"噎膈后期，阴损及阳，脾胃阳虚，不能受纳、运化，浊气上逆，故吞咽受阻，饮食不下，泛吐黏液白沫；脾肾衰败，阳气亏虚，气化无权，不能温煦，故面浮足肿，畏寒肢冷，面色㿠白，腹胀便溏；日久生化乏源，故形瘦神衰；舌质淡，苔白，脉细弱，为气虚阳微之象。","treat":"温补脾肾。","formulaRaw":"补气运脾汤（《证治准绳》）合右归丸（《景岳全书》）加减。前方补气健脾，和胃降逆，后方温补肾阳，补肾填精。","formulaName":"补气运脾汤合右归丸加减","fangjie":"黄芪、党参、白术、茯苓、甘草、大枣补脾益气；陈皮、半夏、砂仁、生姜降逆祛痰，和中养胃；附子（制）、肉桂温肾助阳；熟地黄、鹿角胶补血滋阴，益精填髓；山药、山茱萸、枸杞子、菟丝子、杜仲、当归补肝肾，益精血。胃虚气逆，呕吐不止者，加旋覆花、代赭石、丁香、柿蒂；泛吐白沫者，加吴茱萸、丁香、白蔻仁；形寒肢冷甚者，加巴戟天、淫羊藿；乏力明显，食少便溏者，加陈皮、补骨脂、肉豆蔻、炒山药。若中阳不足，痰凝瘀阻，用理中汤加姜汁、竹沥。"}],"linchuang":["重视顾护津液及胃气。噎膈的病位在食管，为胃所主，与肝、脾、肾密切相关。阴津亏耗是噎膈之本，胃气衰败为其常见转归。临证必须明辨标本虚实，并处理好治本与治标的关系。本虚包括阴虚、气虚、阳虚，标实可表现为气滞、痰阻、血瘀，临床更有顽症瘀结成毒者。治疗常需标本同治，虚实两顾，治疗过程中要时刻以顾护津液及胃气为中心。","辨别气痰瘀毒病机主次。噎膈的病机复杂，多为气、痰、瘀交结，阻隔于食管、贲门所致，常易化热伤阴，或酿生瘀毒，治疗应处理好气滞、痰阻、血瘀、瘀毒之间的关系。若气机阻滞，胸膈痞满者，酌用枳实、陈皮、香附、莱菔子等顺气和胃。若顽痰凝结，酌用浙贝母、海藻、昆布、牡蛎、海蛤壳、瓦楞子等以化痰消积。若久病瘀结，酌用三棱、莪术、丹参、桃仁、红花活血化瘀，或配合全蝎、蜂房、蜈蚣、鳖甲、壁虎、蟾皮搜剔散结。若瘀结成毒者，加白花蛇舌草、山慈菇、半枝莲、山豆根、白英等清热解毒。若食管狭窄，吞咽困难者，可加青黛、硼砂、硇砂、冰片等对藕粉冲服破坚。若食管拘挛者，加威灵仙、白芍、甘草等缓急。","及早检查，确定病性。噎膈的病变范围较广，应及早做相关检查，明确疾病的性质，如食管痉挛属于功能性疾病，食管炎、贲门炎属于炎症性疾病，食管癌、贲门癌则为恶性肿瘤。这三种情况疾病性质不同，治疗方法不同，预后转归也不同，须把握病性，区别对待。"],"yufang":["养成良好的饮食习惯，保持心情愉快，有助于噎膈预防。应注意不过快进食，不吃过烫、辛辣、变质、发霉食物，忌常食腌制食品，忌饮烈性酒。多吃新鲜蔬菜、水果。","噎膈患者应进食营养丰富的食物，进固体食物困难者，可进半流质饮食或软食，如藕粉、菜泥、米糊，少量多次缓慢进食，避免一次进食过多导致呕吐；若噎塞加重，可食牛奶、羊奶、肉汁、蜂蜜、藕汁、梨汁等流质饮食；若完全不能进食，需在医生指导下通过鼻饲或静脉营养补充，防止“津气衰竭”，时刻以顾护胃气为念。做好心理护理工作，帮助患者克服悲观、紧张、恐惧等不良情绪，使其积极配合治疗。鼓励患者适当锻炼身体，增强体质，预防变证。"],"attachIds":["a004"]},{"id":"d024","name":"腹痛","kind":"main","parent":null,"chapterNo":"第二十七章","chapterName":"腹痛","yinbing":[{"t":"b","x":"1. 外感时邪"},{"t":"p","x":"外感风、寒、暑、湿、热之邪，侵入腹中，气机阻滞，气血经脉受阻，不通则痛。"},{"t":"b","x":"2. 饮食不节"},{"t":"p","x":"暴饮暴食，食滞内停，或误食馊腐不洁之物，或过食肥甘厚腻辛辣之品、酿生湿热，蕴结肠胃，或过食生冷，寒湿内停，脾阳受损，皆可伤及脾胃，影响脾胃之健运，气机失于调畅，腑气通降不利，发生腹痛。"},{"t":"p","x":"《素问·痹论》曰：“饮食自倍，肠胃乃伤。”说明饮食不节是导致腹痛的重要因素。"},{"t":"b","x":"3. 情志失调"},{"t":"p","x":"情志不畅，恼怒伤肝，肝失条达，气机阻滞而腹痛。"},{"t":"p","x":"《证治汇补·腹痛》曰：“暴触怒气，则两胁先痛而后入腹，怒气泄则痛止。”"},{"t":"b","x":"4. 阳气素虚"},{"t":"p","x":"素体脾阳亏虚，或过服寒凉，损伤脾阳，虚寒内生，气血不足，不能温养脏腑，遂致腹痛。"},{"t":"p","x":"《诸病源候论·腹病诸候》云：“久腹痛者，脏腑虚而有寒，客于腹内，连滞不歇，发作有时。”"},{"t":"b","x":"5. 跌仆损伤、腹部手术"},{"t":"p","x":"跌仆损伤，或腹部手术，导致血络受损，血溢脉外，脏器粘连，可形成腹中瘀血，经络不畅，中焦气机阻滞，不通则痛。"}],"bingji":[{"t":"p","x":"腹痛的基本病机为脏腑气机阻滞，气血运行不畅，络脉痹阻，“不通则痛”，或脏腑经络失养，“不荣则痛”。"},{"t":"p","x":"病变部位涉及脾、胃、肝、胆、肾、大小肠等多个脏腑，腹部又是足三阴经、足少阳经、手足阳明经、冲脉、任脉、带脉等经络循行之处，上述诸脏腑和经络之病变，皆可导致腹中脏腑气机郁滞，络脉痹阻，不通则痛，或脏腑经络失养，不荣则痛。"},{"t":"p","x":"病理性质不外寒、热、虚、实四方面，且可相互转化。"},{"t":"p","x":"四者往往相互错杂，或寒热夹杂，或虚实互见，或为虚寒，或为实热，亦可互为因果，互相转化。"},{"t":"p","x":"如寒痛缠绵发作，可能寒郁化热；热痛日久，失治误治，复感寒邪，可成为寒热夹杂之证；素体脾虚不运，加之饮食不节，食滞内停，可成虚中夹实之证。"},{"t":"p","x":"腹痛的病理因素主要有寒凝、火郁、食积、气滞、血瘀五个方面。"},{"t":"p","x":"若急性暴痛，治不及时，或治不得当，气血逆乱，可致厥脱之证；若湿热蕴结肠胃，虫邪内扰，或术后气滞血瘀，可致腑气不通之阳明腑实证；气滞血瘀日久，还可变生积聚。"}],"zhenduan":[{"t":"ol","items":["1. 腹痛以胃脘以下、耻骨毛际以上部位疼痛为主症。其疼痛若因外感，突然剧痛，伴发症状明显者，属于急性腹痛；若因内伤，起病缓慢，痛势缠绵者，则为慢性腹痛。","2. 疼痛性质可为胀痛、绞痛、刺痛、钝痛、灼痛、牵扯痛、隐痛等。","3. 常伴有恶心呕吐、泄泻或便秘、腹胀、纳呆等。","4. 腹痛发作或加剧常与饮食、情志、受凉等因素有关。","5. 结合病史、起病经过、诱发因素及伴发症状等，辨别病变脏腑、病理性质，区分内科腹痛与外科腹痛、妇科腹痛。"]}],"jianbie":[{"t":"b","x":"1. 胃痛"},{"t":"p","x":"腹痛与胃痛均以腹部疼痛为主要症状，胃处腹中，与肠相连，腹痛常伴有胃痛的症状，胃痛亦时有腹痛的表现，常需鉴别。"},{"t":"p","x":"胃痛是以胃脘疼痛为主症，病位在胃，与肝脾相关，常伴有脘腹痞闷胀满、吞酸嘈杂等症。"},{"t":"p","x":"腹痛是以胃脘以下、耻骨毛际以上部位疼痛为主症，疼痛范围比较广，发病与脾胃、肝胆、大小肠等多脏腑相关，常伴有腹部胀满、大便不通或腹泻等。"},{"t":"b","x":"2. 其他内科疾病中的腹痛"},{"t":"p","x":"许多内科疾病常见腹痛的表现，但均以该病特征为主。"},{"t":"p","x":"如痢疾之腹痛，伴有里急后重，下痢赤白脓血；积聚之腹痛，以腹中包块为特征；霍乱之腹痛，伴有吐泻交作；鼓胀之腹痛，以腹部外形胀大为特征。"},{"t":"p","x":"而腹痛病证，当以腹部疼痛为主要表现。"},{"t":"b","x":"3. 外科腹痛"},{"t":"p","x":"内科腹痛疼痛一般不剧烈，压痛不明显，痛无定处，一般无发热，或常先发热后腹痛；外科腹痛多先腹痛后发热，疼痛剧烈且拒按，痛有定处，压痛明显，伴肌紧张和反跳痛。"},{"t":"b","x":"4. 妇科腹痛"},{"t":"p","x":"妇科腹痛多位于小腹，与经、带、胎、产有关，如痛经、先兆流产、宫外孕、输卵管破裂等，应及时进行妇科相关检查，以明确诊断。"}],"bianzheng":[{"t":"b","x":"1. 辨腹痛性质"},{"t":"p","x":"腹痛拘急，疼痛暴作，痛无间断，坚满急痛，遇冷痛剧，得热则减者，为寒痛；腹痛急迫，痛处有热感，或伴有便秘，得凉痛减者，为热痛；腹痛时轻时重，痛处不定，攻冲作痛，伴胸胁不舒，腹胀，嗳气或矢气则胀痛减轻者，为气滞痛；腹部刺痛，痛无休止，痛处不移，痛处拒按，夜间加剧，伴面色晦暗者，为血瘀痛；因饮食不慎，脘腹胀痛，嗳腐吞酸，暖气频作，暖气后腹痛稍减，痛而欲便，便后痛减者，为伤食痛；腹痛时作时止，手足厥冷，或伴有吐蛔，为蛔厥腹痛；暴痛多实，伴腹胀，呕逆，拒按等；久痛多虚，痛势绵绵，喜揉喜按。"},{"t":"b","x":"2. 辨腹痛部位"},{"t":"p","x":"腹痛在胁腹、两侧少腹部，或牵引睾丸疼痛，多属肝经病证；胃脘部疼痛，多为脾胃病证；脐腹痛多属大小肠病证或虫积；脐以下小腹痛多属肾、膀胱及胞宫病证。"}],"zhize":"腹痛的治疗多以“通”为治疗原则，临证应根据寒热虚实，在气在血，确立相应治法。如《医学真传·心腹痛》云：“夫通则不痛，理也，但通之之法，各有不同。调气以和血，调血以和气，通也；下逆者使之上行，中结者使之旁达，亦通也。虚者，助之使通，寒者，温之使通，无非通之之法也。若必以下泄为通，则妄矣。”在通法的基础上，结合审证求因，标本兼治，用药不可过于辛燥，应中病即止。属实证者，重在祛邪疏导；如属虚证，应温中补虚，益气养血，不可滥施攻下。对于久痛人络，绵绵不愈之腹痛，可采取辛润活血通络之法。","syndrome":[{"id":"s154","name":"寒邪内阻证","label":"1. 寒邪内阻证","group":"","clinic":"腹痛拘急，急迫剧烈，得温痛减，遇寒痛甚，手足不温，口淡不渴，形寒肢冷，大便清稀或秘结，小便清长，舌淡苔白，脉沉紧。","analysis":"寒邪入侵，阳气不运，气血被阻，故腹痛拘急，急迫剧烈，得温痛减，遇冷痛甚；中阳不足，故手足不温，形寒肢冷；无里热，故口淡不渴；中阳不足，运化失司，故大便稀溏；寒邪内阻，凝滞于肠，故大便秘结；小便清长，舌淡苔白，脉沉紧，皆为里寒之象。","treat":"散寒温里，理气止痛。","formulaRaw":"良附丸（《良方集腋》）合正气天香散（《保命歌括》）加减。前方温里散寒，后方理气温中。","formulaName":"良附丸合正气天香散加减","fangjie":"高良姜、干姜、紫苏温中散寒；乌药、香附、陈皮理气止痛。若感受寒湿，见恶心呕吐，胸闷纳呆，身重倦怠，舌苔白腻者，可加藿香、苍术、厚朴、豆蔻、半夏。若腹中雷鸣切痛，胸胁逆满，呕吐，属寒气上逆，可用附子粳米汤；若腹中冷痛，手足逆冷，且身体疼痛，为内外皆寒，可用乌头桂枝汤；若少腹拘急冷痛，苔白，脉沉紧，为下焦受寒，厥阴之气失于疏泄，可用暖肝煎；若寒实积聚，腹痛拘急，大便不通，可用大黄附子汤。"},{"id":"s155","name":"湿热壅滞证","label":"2. 湿热壅滞证","group":"","clinic":"腹痛拒按，胀满不舒，烦渴引饮，大便秘结或溏滞不爽，身热汗出，小便短赤，舌质红，苔黄燥或黄腻，脉滑数。","analysis":"湿热内结，气机壅滞，腑气不通，故腹痛拒按，胀满不舒；湿热之邪耗伤津液，故烦渴引饮；大肠传导功能失司，故大便秘结或溏滞不爽；湿热交蒸，热迫津液外出，故身热汗出；小便短赤，舌红，苔黄燥或黄腻，脉滑数，皆为实热之征。","treat":"泻热通腑，行气导滞。","formulaRaw":"大承气汤（《伤寒论》）加减。","formulaName":"大承气汤加减","fangjie":"大黄苦寒泄热，攻下燥屎；芒硝咸寒润燥，软坚散结；厚朴、枳实破气导滞，消痞除满。若燥热不甚，湿热偏重，大便不爽，可去芒硝，加栀子、黄芩、黄柏；若痛引两胁，可加郁金、柴胡。如少阳阳明合病，腹痛剧烈，寒热往来，恶心呕吐，大便秘结，可改用大柴胡汤。"},{"id":"s156","name":"饮食积滞证","label":"3. 饮食积滞证","group":"","clinic":"脘腹胀满，疼痛拒按，嗳腐吞酸，厌食呕恶，痛则欲泻，泻后痛减，或大便秘结，舌苔厚腻，脉滑。","analysis":"宿食停滞肠胃，故脘腹胀满，疼痛拒按；宿食不化，浊气上逆，故嗳腐吞酸，厌食呕恶；食滞中阻，运化无权，故痛则欲泻；泻后宿食消减，故泻后痛减；宿食燥结，郁而化热，腑气不行，故大便秘结；舌苔厚腻，脉滑，为食积之象。","treat":"消食导滞，理气止痛。","formulaRaw":"枳实导滞丸（《内外伤辨惑论》）加减。","formulaName":"枳实导滞丸加减","fangjie":"大黄、枳实、神曲消食导滞；黄芩、黄连、泽泻清热化湿；白术、茯苓健脾和胃。还可加木香、莱菔子、槟榔以助消食理气之力。若腹痛胀满甚，可加厚朴、木香；兼大便自利，恶心呕吐，可去大黄，加陈皮、半夏、苍术；若属寒食积滞者，可去黄连、黄芩，加干姜。若食滞不重，腹痛较轻者，可用保和丸。"},{"id":"s157","name":"肝郁气滞证","label":"4. 肝郁气滞证","group":"","clinic":"脘腹胀痛，痛无定处，或痛引少腹，或痛窜两胁，善太息，时作时止，得嗳气或失气则舒，遇忧思恼怒则剧，舌质红，舌苔薄白，脉弦。","analysis":"肝气郁结，气机不畅，故脘腹胀痛；胁腹、两侧少腹属肝经循行部位，故痛引少腹，或痛窜两胁；肝气郁结，故善太息；气属无形，走窜游移，故痛无定处；嗳气或矢气后，气机稍得通畅，故疼痛减轻；遇忧思恼怒气郁更甚，故疼痛加剧；苔薄白，脉弦，乃气滞之象。","treat":"疏肝解郁，理气止痛。","formulaRaw":"柴胡疏肝散（《景岳全书》）加减。","formulaName":"柴胡疏肝散加减","fangjie":"柴胡、枳壳、香附、陈皮疏肝理气；芍药、甘草缓急止痛；川芎行气活血。若气滞较重，胸胁胀痛者，可加郁金、川楝子；若痛引少腹睾丸者，可加橘核、荔枝核、川楝子；肝郁日久化热者，可加丹皮、栀子、川楝子。若腹痛肠鸣，气滞腹泻者，可用痛泻要方；若少腹绞痛，阴囊寒疝者，可用天台乌药散。"},{"id":"s158","name":"瘀血内停证","label":"5. 瘀血内停证","group":"","clinic":"腹痛较剧，痛如针刺，痛处固定，甚至腹部包块，经久不愈，入夜尤甚，或见大便色黑，舌质紫暗，脉细涩。","analysis":"瘀血内停，气机阻滞，脉络不通，故腹痛较剧，痛如针刺；血属有形，其性属阴，故痛处固定，入夜尤甚；日久积聚不散而成包块；瘀停于肠者，则可见大便色黑；舌质紫暗，脉细涩，均为瘀血之象。","treat":"活血化瘀，和络止痛。","formulaRaw":"少腹逐瘀汤（《医林改错》）加减。","formulaName":"少腹逐瘀汤加减","fangjie":"当归、川芎、赤芍养血活血；蒲黄、五灵脂、延胡索、没药化瘀止痛；小茴香、肉桂、干姜温经止痛。可加香附、乌药、青皮理气止痛，桃仁、红花增强活血化瘀作用。若腹部术后疼痛，或外伤致痛，可加泽兰、红花、三七；若瘀血日久发热，可加丹参、丹皮、王不留行。若兼有寒象，腹痛喜温，胁下积块，疼痛拒按，可用膈下逐瘀汤；若下焦蓄血，大便色黑，可用桃核承气汤。"},{"id":"s159","name":"中虚脏寒证","label":"6. 中虚脏寒证","group":"","clinic":"腹痛绵绵，时作时止，喜温喜按，饥饿或劳累后加重，得食或休息后减轻，形寒肢冷，神疲乏力，面色无华，气短懒言，胃纳不佳，大便溏薄，舌质淡，苔薄白，脉沉细。","analysis":"中阳虚衰，失于温养，故腹痛绵绵，时作时止；寒得温而散，气得按则行，故喜温喜按；饥饿或劳累后伤正助邪，故痛加重；得食或休息后正气恢复故痛减轻；脾阳虚失温养，故形寒肢冷；气血不足，故神疲乏力，面色无华，气短懒言；脾胃虚寒受纳运化失常，故胃纳不佳；脾虚生湿，故大便溏薄；舌质淡，苔薄白，脉沉细，皆为虚寒之象。","treat":"温中补虚，缓急止痛。","formulaRaw":"小建中汤（《伤寒论》）加减。","formulaName":"小建中汤加减","fangjie":"桂枝、饴糖、生姜、大枣温中补虚；芍药、炙甘草缓急止痛；可加党参、白术、茯苓助健脾益气，附子（制）助温运中阳。若血气虚弱，腹中拘急冷痛，困倦，短气，纳少，自汗，可加当归、黄芪；若脐中冷痛，连及少腹，可加川椒、荜澄茄。若腹中大寒，呕吐肢冷，可用大建中汤；若腹痛下利，脉微肢冷，脾肾阳虚者，可用附子理中汤；若大肠虚寒，积冷便秘者，可用温脾汤；若中气大虚，少气懒言，可用补中益气汤。"}],"linchuang":["灵活运用温通之法治疗腹痛。温通法是以辛温或辛热药为主体，能动能通，以收通则不痛之效。","温通法每需与他药合用：一是与理气药为伍，如良附丸中高良姜与香附同用，用于寒凝而致气滞引起的腹痛。二是与活血祛瘀药配用，如少腹逐瘀汤，在活血化瘀的同时使用小茴香、干姜、肉桂等辛香温热之品，以化解滞留于少腹的瘀血。三是与补气药相配，如附子理中汤，既用党参、白术，又用附子（制）、干姜，切中中虚脏寒的腹痛病机。四是与养阴补血药相合，如当归四逆汤中桂枝、细辛与当归、白芍同用，小建中汤中桂枝与白芍同用等。五是与甘缓药同用，常用甘草、大枣、饴糖等味甘之品，一方面制约辛燥温热太过，使其温通而不燥烈，另一方面有缓急止痛而不碍邪之效。","正确应用清热通腑法。清热通腑法以清热药（如金银花、黄连、黄芩等）与通腑药（如大黄、虎杖、枳实、芒硝等）为主体，以收通则不痛之效。但应用该法要中病即止，以免损伤正气。","警惕腹痛危症，多科协作。腹痛剧烈者临床须密切观察患者的面色、腹痛部位、性质、程度、时间、二便及其伴随症状，如出现腹痛剧烈、拒按、冷汗淋漓、四肢不温、呕吐不止等症状，须警惕出现厥脱证，应立即处理，必要时转外科或妇科治疗，以免贻误病情。"],"yufang":["预防腹痛发生，应饮食有节，忌暴饮暴食，忌过食生冷、不洁之物，少食辛辣、油腻之品。起居有常，劳逸结合，避风寒，畅情志。","腹痛患者宜解除思想顾虑，疼痛剧烈者宜卧床休息，食积腹痛者宜暂禁食1～2餐，或少食。若湿热蕴结成实，燥屎形成，腑气不通，而成肠结者，宜转外科治疗。腹痛虚寒证或寒实证，可予热敷疗法，以减轻疼痛。对急性腹痛，医生须密切观察，出现厥脱证应及时处理。"],"attachIds":[]},{"id":"d025","name":"泄泻","kind":"main","parent":null,"chapterNo":"第二十八章","chapterName":"泄泻","yinbing":[{"t":"b","x":"1. 感受外邪"},{"t":"p","x":"外感寒、湿、暑、热之邪，伤及脾胃，均可引起泄泻。"},{"t":"p","x":"《难经》谓：“湿多成五泄。”清·沈金鳌《杂病源流犀烛·泄泻源流》曰：“是泄虽有风、寒、热、虚之不同，要未有不源于湿者也。”"},{"t":"b","x":"2. 饮食内伤"},{"t":"p","x":"饮食不洁，使脾胃受伤，或饮食不节，暴饮暴食，或恣食生冷、辛辣、肥甘，使脾失健运，脾不升清，小肠清浊不分，大肠传导失司，发生泄泻。"},{"t":"p","x":"明·张介宾《景岳全书·泄泻》曰：“若饮食失节，起居不时，以致脾胃受伤，则水反为湿，谷反为滞，精华之气不能输化，乃致合污下降，而泻痢作矣。”"},{"t":"b","x":"3. 情志失调"},{"t":"p","x":"抑郁恼怒，易致肝失条达，肝气郁结，横逆克脾，或长期忧思伤脾，均可致脾失健运，清阳不升，水谷不化，发生泄泻。"},{"t":"p","x":"明·张介宾《景岳全书·泄泻》曰：“凡遇怒气便作泄泻者，必先以怒时夹食，致伤脾胃。”"},{"t":"b","x":"4. 体虚久病"},{"t":"p","x":"禀赋不足，脾胃素虚，或年老体弱，或大病久病，失治误治，脾肾阳气受损，水谷失于运化，积谷为滞，湿滞内生，遂成泄泻。"},{"t":"p","x":"明·张介宾《景岳全书·泄泻》曰：“肾为胃关，开窍于二阴，所以二便之开闭，皆肾脏之所主，今肾中阳气不足，则命门火衰，而阴寒独盛，故于子丑五更之后，当阳气未复、阴气盛极之时，即令人洞泄不止也。”"}],"bingji":[{"t":"p","x":"泄泻的基本病机是脾虚湿盛，肠道传化失司。"},{"t":"p","x":"诚如明·张介宾《景岳全书·泄泻》所言：“泄泻之本，无不由于脾胃。”"},{"t":"p","x":"病变部位主要在脾胃、大小肠，脾失健运是关键，与肝、肾也有着密切关系。"},{"t":"p","x":"若脾运失职，水谷不化，小肠无以分清泌浊，大肠传化失常，水反为湿，谷反为滞，混杂而下，则发生泄泻。"},{"t":"p","x":"病理性质初起以邪实为主，久病多虚或虚实夹杂。"},{"t":"p","x":"暴泻多属实证，久泻多属虚证。"},{"t":"p","x":"病理因素主要是湿。"},{"t":"p","x":"湿为阴邪，易困脾阳，脾受湿困，则运化不健，故明·李中梓《医宗必读·泄泻》有“无湿不成泻”之说。"},{"t":"p","x":"泄泻的病机转化，暴泻迁延日久，每可由实转虚而成久泻；久泻复因外感、饮食所伤，亦可急性发作，表现为虚中夹实证候。"},{"t":"p","x":"一般而言，急性暴泻病情较轻者，多能治愈；若病情较重，大便清稀如水而直下无度者，损气伤津耗液，极易发生亡阴亡阳之险证，造成厥、脱、闭、痉等危症。"},{"t":"p","x":"久泻脾病及肾，肾阳亏虚，脾失温煦，不能腐熟水谷，可成命门火衰之五更泻。"}],"zhenduan":[{"t":"ol","items":["1. 以大便粪质溏稀为主症，或粪如水样，或完谷不化，或大便次数增多。","2. 常伴有腹胀、腹痛、肠鸣、纳呆。","3. 起病或急或缓。暴泻起病急，泻下急迫而量多；久泻起病缓，泻下势缓而量少，且有反复发作病史。与感受外邪、饮食内伤、情志失调有关。"]}],"jianbie":[{"t":"p","x":"主要与霍乱相鉴别。"},{"t":"p","x":"泄泻与霍乱均表现为排便次数增多，大便稀溏。"},{"t":"p","x":"但泄泻为脾虚湿盛，肠道传化失司所致，发病可急可缓，多数预后相对较好；霍乱为湿浊邪毒内伤脾胃，气机逆乱，升降失司所致，表现为吐泻交作，甚至泻如米泔水，或伴有剧烈腹痛，可迅速出现皮肤松弛，目眶凹陷，下肢痉挛转筋，精神萎靡，少尿或尿闭，面色苍白，汗出肢冷等津竭阳脱危候，来势急骤，变化迅速，病情凶险，预后险恶。"}],"bianzheng":[{"t":"b","x":"1. 辨轻重缓急"},{"t":"p","x":"泄泻而饮食如常，说明脾胃未败，多为轻症，预后较好；泄泻而不能食，形体消瘦，或暴泻无度，或久泻滑脱不禁，津液耗伤，阴阳衰竭，可转为厥脱，则为重症。暴泻者起病较急，病程较短，泄泻次数每日3次以上；久泻者起病较缓，病程较长，持续时间多在两个月以上甚至数年，泄泻呈间歇性发作。"},{"t":"b","x":"2. 辨虚实寒热"},{"t":"p","x":"暴泻病势急骤，脘腹胀满，腹痛拒按，泻后痛减，小便不利者，多属实证；久泻病势较缓，病程较长，反复发作，腹痛不甚，喜暖喜按，神疲肢冷，多属虚证。大便色黄褐而臭，泻下急迫，肛门灼热者，多属热证；大便清稀甚至水样，气味腥秽者，多属寒证。"},{"t":"b","x":"3. 辨证候特征"},{"t":"p","x":"外感所致泄泻，多兼表证，可有寒湿、湿热、暑湿之分；食滞肠胃泄泻，以腹痛肠鸣、粪便臭如败卵、泻后痛减、嗳腐酸臭为特点；肝气乘脾泄泻，以胸胁胀闷、嗳气食少、每因情志郁怒而加剧为特点；脾胃虚弱泄泻，大便时溏时泻，夹有水谷不化，稍进油腻之物，则大便次数增多，面黄肢倦，食少纳呆；肾阳虚衰泄泻，多发于黎明之前，以腹痛肠鸣、泻后则安、形寒肢冷、腰膝酸软为特点。"}],"zhize":"泄泻的治疗以运脾化湿为基本原则。急性暴泻以湿盛为主，应着重化湿，参以淡渗利湿，根据寒湿、湿热与暑湿的不同，分别采用温化寒湿、清化湿热和清暑祛湿之法，结合健运脾胃。慢性久泻以脾虚为主，当以健运脾气为要，佐以化湿利湿。若夹有肝郁者，宜配合抑肝扶脾；肾阳虚衰者，宜补火暖土；虚实夹杂者，标本兼顾；寒热错杂者，更当寒热并用。明·李中梓《医宗必读》提出治泻九法，值得在临床治疗中借鉴。","syndrome":[{"id":"s160","name":"寒湿内盛证","label":"1.寒湿内盛证","group":"","clinic":"泄泻清稀，甚则如水样，脘闷食少，腹痛肠鸣，或兼恶寒，发热，头痛，肢体酸痛，舌质淡，苔白或白腻，脉濡缓。","analysis":"外感寒湿之邪，侵袭胃肠，或内伤生冷瓜果，损及脾运，水谷不化，清浊不分，肠腑传导失司，故泄泻清稀，甚则如水样；寒湿阻滞，肠腑气机不利，故腹痛肠鸣；湿困脾胃，故脘闷食少；若兼风寒袭表，则见寒热、头痛、身楚等症；舌质淡，苔白或白腻，脉濡缓，为寒湿内盛之象。","treat":"芳香化湿，疏表散寒。","formulaRaw":"藿香正气散（《太平惠民和剂局方》）加减。","formulaName":"藿香正气散加减","fangjie":"香辛温散寒，芳香化湿；白术、茯苓、陈皮、半夏健脾除湿；厚朴、大腹皮理气消满，疏利气机；紫苏、白芷解表散寒；桔梗宣肺利膈，既解表，又助化湿；生姜、大枣内调脾胃，外和营卫；甘草调和药性，协姜枣以和中。若表邪较重，周身困重而骨节酸楚者，可加荆芥、防风等，或用荆防败毒散加减；若湿邪偏重，胸闷腹胀，肢体倦怠，苔白腻者，用胃苓汤加减。"},{"id":"s161","name":"湿热中阻证","label":"2.湿热中阻证","group":"","clinic":"泄泻腹痛，泻下急迫，或泻而不爽，粪色黄褐臭秽，肛门灼热，烦热口渴，脘痞纳呆，小便短黄，舌质红，苔黄腻，脉滑数或濡数。","analysis":"感受湿热之邪，或夏令暑湿时邪伤及肠胃，运化失常，发生泄泻；热邪类火，火性急迫，邪热下迫大肠，肠腑传导失常，故见泻下急迫；湿热壅结大肠，腑气通降不利，则泻下不爽，腹痛拒按；湿热下注，故粪色黄褐臭秽，肛门灼热，小便短黄；湿热内蒸而水津渐耗，故见烦热口渴；湿热郁于中焦，故脘痞纳呆；舌质红，苔黄腻，脉滑数或濡数，为湿热之象。","treat":"清热利湿，分消止泻。","formulaRaw":"葛根芩连汤（《伤寒论》）加减。","formulaName":"葛根芩连汤加减","fangjie":"葛根解表清热，升清止泻；黄芩、黄连苦寒清热燥湿；甘草甘缓和中，调和诸药。若湿重于热，胸腹满闷，口不渴，或渴不欲饮，舌苔微黄厚腻，脉濡缓者，合平胃散加减；若夹食滞者，加神曲、麦芽、山楂等。在夏暑期间，症见发热头重，烦渴自汗，小便短赤，脉濡数等，是暑湿入侵，表里同病，用新加香薷饮合六一散加减。"},{"id":"s162","name":"食滞肠胃证","label":"3.食滞肠胃证","group":"","clinic":"腹痛肠鸣，泻下粪便臭如败卵，泻后痛减，脘腹胀满，嗳腐酸臭，不思饮食，舌质淡红或红，苔垢浊或厚腻，脉滑。","analysis":"饮食不节，宿食内停，阻滞肠胃，传化失常，湿滞混杂而下，发为泄泻；食滞胃肠，气机不利，故脘腹痞满，腹痛肠鸣；浊气上泛，故嗳腐酸臭，不思饮食；浊气下趋肠道，故泻下粪便臭如败卵；泻后则腐浊之邪得以外出，故腹痛减轻；舌质淡红或红，苔垢浊或厚腻，脉滑，为宿食内停，湿浊上熏之象。","treat":"消食导滞，和中止泻。","formulaRaw":"保和丸（《丹溪心法》）加减。","formulaName":"保和丸加减","fangjie":"山楂、神曲、莱菔子消导食滞，宽中除满；陈皮、半夏、茯苓和胃祛湿；连翘消食滞之郁热。若食滞较重，脘腹胀满，泻下不爽，可加大黄、枳实、槟榔等，或用枳实导滞丸加减；若积滞化热者，可加黄连、黄芩等；若呕吐甚者，可加生姜、刀豆子、竹茹等。\n2. 久泻"},{"id":"s163","name":"肝气乘脾证","label":"1.肝气乘脾证","group":"","clinic":"肠鸣攻痛，腹痛即泻，泻后痛缓，每因忧思恼怒或情绪紧张而发泄泻，伴有胸胁胀闷，嗳气食少，腹痛攻窜，肠鸣矢气，舌淡红，苔白，脉弦。","analysis":"忧思恼怒或情绪紧张，致肝气不舒，失于条达，横逆犯脾，脾运无权，气滞中焦，而见肠鸣攻痛，腹痛即泻，泻后痛缓；肝失疏泄，脾虚不运，故见胸胁胀闷，嗳气食少；舌淡红，苔白，脉弦，为肝旺脾虚之象。","treat":"抑肝扶脾。","formulaRaw":"痛泻要方（《丹溪心法》）加减。","formulaName":"痛泻要方加减","fangjie":"白芍养阴柔肝以治肝体；防风胜湿，且可散肝以助肝用；白术化湿健脾；陈皮理气和中。若肝郁气滞，胸胁脘腹胀痛，可加枳壳、香附、延胡索、川楝子等；若兼有湿热，大便夹有黏液，可加黄连、黄芩等。若脾虚明显，神疲食少，用逍遥散合参苓白术散加减。"},{"id":"s164","name":"脾胃虚弱证","label":"2.脾胃虚弱证","group":"","clinic":"大便时溏时泻，迁延反复，稍进油腻食物，则大便溏稀，次数增加，或完谷不化，伴食少纳呆，脘闷不舒，面色萎黄，倦怠乏力，舌质淡，苔白，脉细弱。","analysis":"脾胃虚弱，运化无权，水谷不归正化，下趋肠腑，故大便时溏时泻，迁延反复；饮食稍有不慎，则脾胃之气更伤，故大便溏稀，次数增多或完谷不化；脾失健运，胃不受纳，故食少纳呆，脘闷不舒；久泻不已，脾胃虚弱，气血生化乏源，不能上荣于面，故面色萎黄；气血无以充养四肢，则肢倦乏力；舌淡苔白，脉细弱，为脾胃虚弱之象。","treat":"健脾益气，化湿止泻。","formulaRaw":"参苓白术散（《太平惠民和剂局方》）加减。","formulaName":"参苓白术散加减","fangjie":"人参、茯苓、白术、甘草、大枣平补脾胃之气；扁豆、薏苡仁、山药、莲子肉既可和胃理气健脾，又能渗湿而止泻，标本兼顾；砂仁芳香醒脾，促进中焦运化，畅通气机；桔梗载药上行，培土生金。若泄泻日久，脾虚夹湿，肠鸣辘辘，大便溏黏，舌苔厚腻难化，或食已即泻，加防风、羌活、苍术、厚朴等，或改用升阳益胃汤加减。若脾阳虚衰，阴寒内盛，腹部冷痛，完谷不化，用附子理中丸加吴茱萸、肉桂等；若久泻不愈，中气下陷，脱肛，用补中益气汤加减。"},{"id":"s165","name":"肾阳虚衰证","label":"3.肾阳虚衰证","group":"","clinic":"黎明前腹部作痛，肠鸣即泻，泻后痛减，完谷不化，腹部喜暖喜按，形寒肢冷，腰膝酸软，舌淡苔白，脉沉细。","analysis":"肾阳虚衰，不能温煦脾土，腐熟水谷，致脾运失司，水谷下趋肠道而泻；黎明五更前后，阴寒较盛，阳气未振，故见腹部作痛，喜暖喜按，肠鸣即泻，又称为“五更泻”；泻后腑气通利，故腹痛得减；脾寒不能运化谷食，故泻下完谷不化；肾阳虚衰，失于温煦，故形寒肢冷；腰为肾府，肾阳衰惫，故腰膝酸软；舌淡苔白，脉沉细，为脾肾阳虚之象。","treat":"温肾健脾，固涩止泻。","formulaRaw":"四神丸（《内科摘要》）加减。","formulaName":"四神丸加减","fangjie":"吴茱萸辛热散寒，补骨脂温肾助阳，肉豆蔻温中暖脾，五味子酸收止泻，生姜、大枣温补脾胃，鼓舞运化。若肾阳虚衰明显，加附子（制）、肉桂等；若脾阳不足为著，加干姜、莲子、芡实等；若内寒腹痛，加川椒、茴香等；若泻次频多，加乌梅、石榴皮、五倍子等；若滑脱不禁者，合桃花汤或真人养脏汤加减；虽为五更泻，但脾肾阳虚不显，反见心烦嘈杂，而有寒热错杂之症者，改用乌梅丸加减。"}],"linchuang":["健脾与运脾灵活应用。湿是导致泄泻的主要病理因素，临床治疗泄泻尤应注意两个方面：①健脾化湿：脾虚失健则运化失常，湿邪内生，故当健脾以化湿，方如参苓白术散、四君子汤之类。②运脾化湿：脾为湿困，则气化遏阻，清阳不升，清浊不分，此时应以运脾胜湿为务。运脾者，燥湿之谓，即芳香化湿、燥能胜湿之意，药如苍术、厚朴、藿香、白豆蔻等。临床因脾虚致泻者宜健脾，因湿邪困脾致泻者宜运脾，两者灵活应用最为关键。脾为湿困，中气下陷，则需振兴脾气，加入升阳药，使气机流畅，恢复转枢，如升麻、柴胡、羌活、防风、葛根之类，少少与之，轻可去实，若用量大则反而疏泄太过而泄泻更甚。","久泻的治疗宜忌。一般认为久泻多虚，但在病程中也常见寒热错杂、虚实互见者。治疗要把握标本缓急，常用辛开苦降、调和肝脾、寒热同调、虚实并治等法，方如乌梅丸、连理汤、柴芍六君汤、黄连汤等。久泻若夹有食滞、湿热等实邪，还可取“通因通用”法。此外还应注意两点：一是不可轻易采用补涩之法。因久泻虽缠绵时日，但湿邪未尽，或兼夹他邪，如匆忙补涩，容易出现“炉烟虽熄，灰中有火”现象，变证接踵而至。二是不可过于分利小便。利小便而实大便之法主要适用于暴泻。久泻多为脾虚失运或脏腑克制所致，虽有水湿，乃暂积而成，非顷刻之病变，故迁延难愈，轻者宜芳香化湿，重者宜苦温燥湿，若过于分利小便则伤正气。","重视用风药治疗泄泻。脾气不升是久泻发病的主要病理环节之一，而风性轻扬升散，不仅可以化湿，而且常有疏肝解郁之用，所以合理运用风药，有利于泄泻临床疗效的提高。金·李东垣曾谓“诸风药皆是风能胜湿也”，常用药如荆芥、防风、藿香、佩兰、苏叶、白芷、葛根、升麻、柴胡、蝉蜕、羌活、藁本等，方如藿香正气散、荆防败毒散、羌活胜湿汤等。"],"yufang":["避风寒，节饮食，调情志。注意保暖，以防寒湿伤脾；避免过嗜生冷油腻、肥甘厚味，或暴饮暴食，以防湿邪内生，或食滞胃肠；调畅情志，勿悲恐忧伤，以免肝郁伤脾。","暴泻者，减少进食量，可予米粥以养胃，泻止则给予清淡饮食。虚寒久泻者，可予姜汤暖胃，并适当进食山药、莲子、芡实等。如泄泻严重，甚至一日十次以上者，应及时就医，防止发生厥脱重症。"],"attachIds":[]},{"id":"d026","name":"痢疾","kind":"main","parent":null,"chapterNo":"第二十九章","chapterName":"痢疾","yinbing":[{"t":"b","x":"1. 外感时邪疫毒"},{"t":"p","x":"若起居不慎，劳作不休，湿热或暑湿之邪内侵肠道，湿热郁蒸，气血壅滞，化为脓血而成湿热痢。"},{"t":"p","x":"疫毒之邪充斥全身，内陷营血，而致急重之疫毒痢。"},{"t":"p","x":"素体阳虚之人感受寒湿，或感受湿邪后，湿从寒化，寒湿伤中，胃肠不和，气血壅滞，发为寒湿痢。"},{"t":"p","x":"明·张介宾《景岳全书·痢疾》云：“痢疾之病，多病于夏秋之交，古法相传，皆谓炎暑大行，相火司令，酷热之毒蓄积为痢。”"},{"t":"b","x":"2. 内伤饮食"},{"t":"p","x":"平素嗜食肥甘厚味者，酿生湿热，在夏秋季节内外湿热交蒸之时，饮食不洁，或暴饮暴食，湿热毒邪与气血搏结，腐败化为脓血，则成湿热痢或疫毒痢。"},{"t":"p","x":"若湿热邪毒留恋，易伤阴血，形成阴虚痢。"},{"t":"p","x":"若其平素恣食生冷瓜果，伤及脾胃，中阳不足，湿从寒化，寒湿内蕴，复贪凉饮冷或饮食不洁，寒湿食积壅塞肠中，邪蕴肠腑，气血壅滞，化为脓血，而成寒湿痢。"},{"t":"p","x":"脾胃素弱之人，屡伤寒湿，或湿热痢过服寒凉之品，克伐中阳，每成虚寒痢。"},{"t":"p","x":"《景岳全书·痢疾》云：“因热贪凉者，人之常事也，过食生冷，所以致痢。”"}],"bingji":[{"t":"p","x":"痢疾的基本病机是邪蕴肠腑，气血壅滞，肠道传导失司，脂膜血络受伤。"},{"t":"p","x":"湿热、疫毒、寒湿、食滞等内蕴肠腑，与肠中气血相搏结，大肠传导功能失司，通降不利，气血壅滞，腐败化为脓血，而痢下赤白；气机阻滞，腑气不通，故见腹痛，里急后重。"},{"t":"p","x":"病变部位在肠，与脾、胃相关，久病可累及肾。"},{"t":"p","x":"清·何梦瑶《医碥·痢》云：“不论何脏腑之湿热，皆得以入肠胃，以胃为中土，主容受而传之肠也。”"},{"t":"p","x":"痢疾日久，不但损伤脾胃，而且影响及肾，导致肾气虚惫或脾肾阳虚，下痢不止。"},{"t":"p","x":"病理性质有寒、热、虚、实之分。"},{"t":"p","x":"初期多为实证，暴痢多属实证。"},{"t":"p","x":"下痢日久可由实转虚，或虚实夹杂，寒热并见。"},{"t":"p","x":"病理因素有湿热、寒湿、食滞和疫毒，病机演变多端。"},{"t":"p","x":"如疫毒热盛伤津，或湿热内郁不清，日久伤气、伤阴，或素体阴虚邪恋，发为阴虚痢；久痢伤正，胃虚气逆，胃不纳食者，发为噤口痢虚证；脾胃素虚而感寒湿患痢，或湿热痢过服寒凉药物致脾虚中寒，日久累及肾阳，关门不固，下痢滑脱，发为虚寒痢。"},{"t":"p","x":"如痢疾失治，迁延日久，或收涩太早，关门留寇，正虚邪恋，可发展为下痢时发时止、日久难愈的休息痢。"},{"t":"p","x":"若痢疾疫毒较盛，邪盛正衰，或失治误治，可出现危重变证或转为久痢。"},{"t":"p","x":"休息痢、阴虚痢、虚寒痢因正虚不足，每见病情缠绵，如失治误治，常可转为久痢。"}],"zhenduan":[{"t":"ol","items":["1. 以腹痛、里急后重、下痢赤白脓血为主症，可伴大便次数增多。","2. 急性痢疾起病急骤，可伴有恶寒发热；慢性痢疾则反复发作，迁延不愈。","3. 常见于夏秋季节，多有饮食不洁史。"]}],"jianbie":[{"t":"p","x":"主要与泄泻鉴别。"},{"t":"p","x":"痢疾与泄泻皆多发于夏秋季节，表现为大便次数增多，或伴腹痛等。"},{"t":"p","x":"痢疾为邪蕴肠腑，气血壅滞，腐败为脓，肠道传导失司所致，大便次数虽多而量少，排赤白脓血便，腹痛，伴里急后重感明显。"},{"t":"p","x":"而泄泻为脾虚湿盛，肠道传化失司所致，表现为大便溏薄，粪便清稀，或如水样，或完谷不化，而无赤白脓血便，腹痛多伴肠鸣，少有里急后重感。"},{"t":"p","x":"正如《景岳全书·泄泻》所言：“泻浅而痢深，泻轻而痢重。泻由水谷不分，出于中焦；痢以脂血伤败，病在下焦。”"}],"bianzheng":[{"t":"b","x":"1. 辨久暴"},{"t":"p","x":"暴痢发病急，病程短，多实证，相对易治，多数患者预后良好；久痢腹痛绵绵，时轻时重，病程长，多虚证，或虚实夹杂证，治疗相对困难。"},{"t":"b","x":"2. 辨虚实寒热"},{"t":"p","x":"初病多实，久病多虚，或为虚实夹杂、寒热错杂之候。实证腹痛胀满，痛而拒按，痛时窘迫欲便，便后里急后重暂时减轻；虚证腹痛绵绵，痛而喜按，便后里急后重不减，坠胀明显。热证大便排出脓血，色鲜红，甚则紫黑，稠厚腥臭，腹痛，里急后重明显，口渴，口臭，小便黄赤，舌红苔黄腻，脉滑数；寒证大便排出赤白清稀，白多赤少，腹痛喜按，里急后重不明显，面白肢冷形寒，舌淡苔白，脉沉细。"},{"t":"b","x":"3. 辨伤气伤血"},{"t":"p","x":"下痢白多赤少，邪伤偏于气分；赤多白少，或以血为主者，邪伤偏于血分。"}],"zhize":"痢疾的治疗应以祛邪导滞、调和气血为基本原则。根据寒热虚实主次不同，热痢清之，寒痢温之，寒热交错者清温并举，虚实夹杂者攻补兼施。初起之时，实证、热证多见，宜清热化湿解毒，兼表证者更可行疏风解表之法，以导邪外出。久痢寒证、虚证多见，宜补虚温中，调理脾胃，兼以清肠，收涩固脱。\n痢疾不论虚实寒热，肠中多有积滞，可配消导之品。刘完素云：“调气则后重自除，行血则便脓自愈。”一般赤多重用血药，白多重用气药。此外，顾护胃气应贯穿治痢过程的始终。","syndrome":[{"id":"s166","name":"湿热痢证","label":"1. 湿热痢证","group":"","clinic":"腹痛，里急后重，下痢赤白脓血，赤多白少，或纯下赤冻，肛门灼热，小便短赤，或发热恶寒，头痛身楚，口干口渴，舌质红，苔黄腻，脉滑数或浮数。","analysis":"湿热之邪壅滞肠中，气机不畅，传导失常，故腹痛，里急后重；湿热熏蒸肠道，气血壅滞，腐败为脓，故下痢赤白；湿热下注，则肛门灼热，小便短赤；舌质红，苔黄腻，脉滑数，为湿热之象；发热恶寒，头痛身楚，口干口渴，脉浮数，为湿热痢初起兼表之象。","treat":"清肠化湿，调气和血。","formulaRaw":"芍药汤（《素问病机气宜保命集》）加减。","formulaName":"芍药汤加减","fangjie":"芍药、当归、甘草和营理血，缓急止痛；黄芩、黄连清热燥湿解毒；木香、槟榔、大黄行气导滞，以除后重；肉桂辛温大热，辛能散结，热可防其苦寒太过。若热重下痢，可加白头翁汤；若瘀热较重，痢下鲜红，可加地榆、桃仁、丹皮；若夹食滞，见痢下不爽，腹痛拒按，苔黄腻，脉滑，可加焦山楂、枳壳、炒莱菔子等，或加枳实导滞丸。若痢疾初起，兼有表证，用人参败毒散；若身热汗出，脉急促，表邪未解而里热已盛，可用葛根芩连汤。"},{"id":"s167","name":"疫毒痢证","label":"2. 疫毒痢证","group":"","clinic":"起病急骤，痢下鲜紫脓血，腹痛剧烈，里急后重明显，或壮热口渴，恶心呕吐，头痛烦躁，甚者神昏惊厥，或痉厥抽搐，或面色苍白，汗冷肢厥，舌质红绛，舌苔黄燥，脉滑数或脉微欲绝。","analysis":"疫毒之性猛烈，故起病急骤；熏灼肠络，腐败气血，故痢下鲜紫脓血；直犯肠道，气机壅滞，故腹痛剧烈，里急后重明显；正邪剧争，热毒伤津，可见壮热口渴；热毒上攻清窍，扰乱心神，可见头痛烦躁；疫毒弥漫，脾胃升降失常，可见恶心呕吐；疫毒炽盛，热入心包，热极生风，可见神昏惊厥，或痉厥抽搐；下血过多，阳随阴脱，可见面色苍白，汗冷肢厥；舌质红绛，舌苔黄燥，脉滑数，为热毒之象；脉微欲绝，为危重之候。","treat":"清热解毒，凉血止痢。","formulaRaw":"白头翁汤（《伤寒论》）合芍药汤（《素问病机气宜保命集》）加减。前方清热凉血解毒为主，后方清热止痢，并有调气行血导滞作用。","formulaName":"白头翁汤合芍药汤加减","fangjie":"白头翁清热解毒，凉血止痢；黄连、黄柏、秦皮清热解毒，燥湿止痢；金银花、生地黄、赤芍、丹皮清热凉血解毒；木香、槟榔行气导滞。若热极动风，痉厥抽搐，加羚羊角、钩藤、石决明，送服紫雪丹；若热毒秽浊壅塞肠道，腹中满痛拒按，大便滞涩，臭秽难闻，或表现为高热神昏，四肢厥冷，大便不通，加大承气汤。若神昏谵语，高热，甚则痉厥，舌质红，苔黄糙，脉细数，属热毒深入营血，用犀角地黄汤、紫雪丹；若暴痢致脱，则急服参附汤或独参汤。"},{"id":"s168","name":"寒湿痢证","label":"3. 寒湿痢证","group":"","clinic":"腹痛拘急，痢下赤白黏冻，白多赤少，或为纯白冻，里急后重，口淡乏味，脘胀腹满，头身困重，舌质淡，舌苔白腻，脉濡缓。","analysis":"寒湿为阴邪，留着肠中，气机阻滞，传导失常，故下痢腹痛，里急后重；寒湿伤于气分，故痢下白多赤少或纯白冻；寒湿中阻，运化失常，故口淡乏味，脘胀腹满；脾主肌肉，寒湿困脾，清阳不升，故头身困重；舌质淡，舌苔白腻，脉濡缓，为寒湿之象。","treat":"温化寒湿，调气和血。","formulaRaw":"不换金正气散（《太平惠民和剂局方》）加减。","formulaName":"不换金正气散加减","fangjie":"苍术、厚朴、陈皮、炙甘草、生姜、大枣燥湿运脾，行气和胃；藿香芳香化湿；半夏燥湿化痰，消痞散结。若痢下白中兼赤，加芍药、当归；若脾虚纳呆，加白术、神曲；若寒湿气滞明显，加槟榔、木香、炮姜。"},{"id":"s169","name":"阴虚痢证","label":"4. 阴虚痢证","group":"","clinic":"痢下赤白，日久不愈，脓血黏稠，或下鲜血，脐下灼痛，虚坐努责，食少，心烦口干，至夜转剧，舌红绛少津，苔少或花剥，脉细数。","analysis":"素体阴虚，感邪而病痢，或久痢伤阴，而成阴虚痢。邪滞肠间，阴血不足，故痢下赤白，脓血黏稠；阴亏热灼，则脐下灼痛；营阴不足，则虚坐努责；胃阴亏虚，故食少口干；虚热扰心，故心烦；至夜阳入于阴，阴虚则阳亢，故虚热转剧；舌红绛少津，苔少或花剥，脉细数，为阴虚之象。","treat":"养阴和营，清肠止痢。","formulaRaw":"黄连阿胶汤（《伤寒论》）合驻车丸（《备急千金要方》）加减。前方滋阴降火安神，后方滋阴清热，固肠止痢。","formulaName":"黄连阿胶汤合驻车丸加减","fangjie":"黄连、黄芩、阿胶滋阴降火，厚肠止痢；阿胶、当归、白芍、鸡子黄养阴和血；少佐炮姜以制黄连苦寒太过；白芍、甘草酸甘化阴，和营止痛。若口干口渴明显，可加石斛、沙参、天花粉；若阴虚火旺，湿热内盛，下痢鲜血黏稠，可加黄柏、秦皮、白头翁、丹皮、赤芍、槐花。"},{"id":"s170","name":"虚寒痢证","label":"5. 虚寒痢证","group":"","clinic":"腹部隐痛，缠绵不已，喜按喜温，痢下赤白清稀，无腥臭，或为白冻，甚则滑脱不禁，肛门坠胀，形寒畏冷，四肢不温，食少神疲，腰膝酸软，舌淡，苔薄白，脉沉细弱。","analysis":"痢久脾虚中寒，寒湿留滞肠中，故痢下赤白清稀；寒盛正虚，肠中失于温养，故腹部隐痛；胃气虚弱，脾阳不振，故食少神疲，四肢不温；脾胃虚寒，则化源不足，久痢精微外流，致肾阳亦虚，关门不固，故形寒畏冷，滑脱不禁，肛门坠胀；舌淡苔白，脉沉细弱，为虚寒之象。","treat":"温补脾肾，收涩固脱。","formulaRaw":"桃花汤（《伤寒论》）合真人养脏汤（《太平惠民和剂局方》）加减。前方温中涩肠，后方兼能补虚固脱。","formulaName":"桃花汤合真人养脏汤加减","fangjie":"赤石脂、肉豆蔻、诃子暖脾温中，涩肠止泻；干姜、肉桂温肾暖脾；人参、白术、粳米益气健脾和中；当归、白芍养血和血；甘草缓急止痛；木香理气醒脾。若积滞未尽，可加枳壳、山楂、神曲等；若痢久脾虚气陷，导致少气脱肛，可加黄芪、柴胡、升麻、党参，亦可用补中益气汤加减；若脾肾阳虚重，手足不温，可少佐附子（制）。"},{"id":"s171","name":"休息痢证","label":"6. 休息痢证","group":"","clinic":"下痢时发时止，迁延不愈，常因饮食不当、受凉、劳累而发，发时大便次数增多，夹有赤白黏冻，腹胀食少，倦怠嗜卧，舌质淡，苔腻，脉濡软或虚数。","analysis":"下痢日久，正虚邪恋，寒热夹杂，肠胃传导失司，故下痢时发时止，迁延不愈，饮食不当、感受外邪或劳累即诱发；脾胃虚弱，健运失常，湿热流连，故发则腹胀，大便夹赤白黏冻，食少倦怠；舌质淡，苔腻，脉濡软或虚数，乃湿热未尽，正气虚弱之象。","treat":"温中清肠，调气化滞。","formulaRaw":"连理汤（《证治要诀类方》）加减。","formulaName":"连理汤加减","fangjie":"人参、干姜、白术、茯苓、炙甘草温中健脾；黄连清除肠中湿热余邪。若急性发作期，里急后重明显，可加槟榔、木香、枳实；若便血突出，或纯下血便，可加三七、白及、赤石脂等。若脾阳虚，寒热错杂，症见腹痛绵绵，下痢稀溏，时夹少量黏冻，兼胃脘灼热，烦渴，或烧心泛酸，四肢不温，舌质淡红，苔黄腻，脉沉缓，用乌梅丸加减；若久病夹瘀，症见腹部刺痛，拒按，固定不移，夜间加重，面色晦暗，或腹部结块，舌质紫暗或有瘀斑，脉细涩，用少腹逐瘀汤加减。针对久痢，还可以配合中药保留灌肠疗法，选用清热化湿、解毒凉血、敛疮生肌、活血止血等药，如锡类散、云南白药等。"}],"linchuang":["“逆流挽舟”法的应用。喻嘉言“逆流挽舟”之法用于痢疾初起兼有表证者，以下痢、憎寒壮热、头身重痛、咳嗽、鼻塞声重、脉浮为辨证要点。代表方为人参败毒散。该方出自宋代《太平惠民和剂局方》，喻嘉言用以治疗痢疾兼表证者，其以解表之剂，疏表救里，逆挽下陷之清阳，恢复其升发之机，使邪从表散，不治痢而痢自止。","重视清热除湿解毒与调气和血药物的应用。湿热、寒湿、疫毒均可导致痢疾，但湿热更为多见，清热除湿解毒法最为常用，药物如白头翁、黄连、黄柏、秦皮、金银花、马齿苋等。因痢疾存在邪蕴肠腑，气血壅滞的病机，调气和血法为治疗所必用，常用调气药如木香、槟榔、枳实、枳壳、陈皮、炒莱菔子等，和血药如当归、白芍等。","痢疾治疗宜忌。古人有“无积不成痢”“痢无止法”之说，提示痢疾发病常存在肠胃积滞，临床常用消导、化滞法，药如山楂、枳实、陈皮、神曲、麦芽之类。偏湿者可加苍术、茯苓；偏寒者可加肉桂、干姜；因积滞而腹痛甚者，更可佐大黄、槟榔等以泻下积滞，乃通因通用之法；寒热错杂者，可用乌梅丸加减。至于古今医家提出的治疗痢疾若干禁忌，如忌过早补涩、忌峻下攻伐、忌分利小便等，均可供临床用药之时参考借鉴。","噤口痢的治疗。痢疾不能进食，或呕不能食者，称为噤口痢。实证多由湿热、疫毒蕴结肠中，上攻于胃，胃失和降所致，宜用开噤散，煎汤少量多次服用，不拘时，徐徐咽下，可苦辛通降，泻热和胃。若汤剂不受，可先用玉枢丹磨汁少量服用，再予前方徐徐咽下。若胃阴大伤，频繁呕吐，舌质红绛无苔，脉细数，可在方中酌加人参、麦冬、石斛、沙参以扶养气阴，并用人参与姜汁炒黄连同煎，频频呷之，再吐再呷，以开噤为止。若素体脾胃虚弱或久痢以致胃虚气逆，出现呕恶不食或食入即吐，口淡不渴，舌质淡，脉弱，治宜健脾和胃为主，用六君子汤加石菖蒲、姜汁以醒脾开胃。若下痢无度，饮食不进，肢冷脉微，为病势危重，急用独参汤或参附汤或参附注射液以益气回阳救逆。"],"yufang":["预防痢疾发生，首先注意饮食卫生，避免过食生冷和进食不洁食物。痢疾流行期间，远离痢疾患者，可适当食用生蒜、马齿苋等以预防。","痢疾患者应避免摄入生冷、寒凉、辛辣、油腻食物，宜进适量新鲜低纤维、低脂肪、高维生素、高蛋白饮食。重视饮食卫生，避免肠道感染性疾病。宜调整生活方式，戒烟戒酒。调养身心，保持心情愉快，避免过大的心理压力；劳逸适度，充分休息，避免过度疲劳。尽量做到早期诊断、早期治疗，防止病情加重。"],"attachIds":[]},{"id":"d027","name":"便秘","kind":"main","parent":null,"chapterNo":"第三十章","chapterName":"便秘","yinbing":[{"t":"p","x":"饮食不节、情志失调、久病体虚、感受外邪或失治误治等，均可引起热结、气滞、寒凝及气血阴阳亏虚，导致肠道传导失司，发为便秘。"},{"t":"b","x":"1. 饮食不节"},{"t":"p","x":"饮酒过多，过食辛辣厚味，过服热药，均可致肠胃积热，耗伤津液，肠道干涩失润，粪质干燥，难以排出，形成热秘。"},{"t":"p","x":"反之，若恣食生冷，过用苦寒之药，致阴寒凝滞，肠胃传导失司，导致冷秘。"},{"t":"p","x":"《景岳全书·秘结》曰：“阳结者，必因邪火有余，以致津液干燥。”"},{"t":"b","x":"2. 情志失调"},{"t":"p","x":"忧愁思虑，脾伤气结，或抑郁恼怒，肝郁气滞，或久坐少动，气机不利，均可导致腑气郁滞，通降失常，传导失职，糟粕内停，不得下行，或欲便不出，或出而不畅，或大便干结而成气秘。"},{"t":"p","x":"《金匮翼·便秘》曰：“气秘者，气内滞而物不行也。”"},{"t":"b","x":"3. 久病体虚"},{"t":"p","x":"素体虚弱，或病后、产后及年老体虚之人，阴阳气血亏虚，阳气虚则温煦传送无力，阴血虚则润泽荣养不足，皆可导致大便不畅。"},{"t":"p","x":"《景岳全书·秘结》曰：“凡下焦阳虚，则阳气不行，阳气不行，则不能传送，而阴凝于下，此阳虚而阴结也。”"},{"t":"p","x":"《医宗必读·大便不通》曰：“更有老年津液干枯，妇人产后亡血，及发汗利小便，病后血气未复，皆能秘结。”"},{"t":"b","x":"4. 感受外邪"},{"t":"p","x":"外感寒邪，直中肠胃，导致阴寒内盛，凝滞胃肠，传导失常，糟粕不行，而成冷秘。"},{"t":"p","x":"《金匮翼·便秘》曰：“冷秘者，寒冷之气，横于肠胃，凝阴固结，阳气不行，津液不通。”"},{"t":"p","x":"或外感风热，耗伤津液，大肠失润，而致大便干燥，排便困难。"}],"bingji":[{"t":"p","x":"便秘的基本病机是大肠传导失司。"},{"t":"p","x":"《素问·灵兰秘典论》曰：“大肠者，传导之官，变化出焉。”"},{"t":"p","x":"而六腑以通为用，胃肠以通降为顺，若邪结肠腑，或气血阴阳不足，肠道传送无力，或失于濡润，致大肠传导失司，糟粕内停，发为便秘。"},{"t":"p","x":"病变部位主要在大肠，涉及脾、胃、肺、肝、肾等多个脏腑。"},{"t":"p","x":"病理性质包括虚实两个方面。"},{"t":"p","x":"热秘、气秘、冷秘属实，气血阴阳亏虚所致者属虚。"},{"t":"p","x":"病理因素为热结、气滞、寒凝。"},{"t":"p","x":"便秘不同证候之间常常相互兼夹、转化，可以因实致虚，也可以因虚致实。"},{"t":"p","x":"转化者，如气秘日久，久而化火，则可转化为热秘。"},{"t":"p","x":"而热秘久延不愈，津液渐耗，损及肾阴，致阴津亏虚，肠失濡润，由实转虚。"},{"t":"p","x":"阳虚便秘，如误用苦寒泻下，或误食生冷，可导致寒邪凝滞，转为冷秘，由虚转实。"},{"t":"p","x":"便秘日久，肠胃气机阻滞，可致脘腹胀满，食欲减退，嗳气泛恶，甚则腹痛呕吐。"},{"t":"p","x":"大便燥结日久不愈，过度用力努挣，可引起肛裂、痔疮、疝气，甚则诱发胸痹、中风等。"},{"t":"p","x":"本病预后一般良好，调摄得法，辨证得当，大多可以痊愈。"}],"zhenduan":[{"t":"ol","items":["1. 排便次数每周少于3次，或间隔时间虽短，但粪质干结，排出艰难，或粪质不硬，虽频有便意，但排便不畅。","2. 常伴腹胀、口臭、纳差及神疲乏力等。","3. 常有饮食不节、情志内伤、运动减少等病因，多见于年老久病体虚者。"]}],"jianbie":[{"t":"b","x":"1. 肠结"},{"t":"p","x":"便秘与肠结均可见排便不畅。"},{"t":"p","x":"便秘多为慢性久病，因大肠传导失常所致，表现为大便干结难行，可伴腹胀，饮食减少，有正常矢气排出。"},{"t":"p","x":"而肠结可继发于便秘患者，急性起病，常为燥屎内结，腑气不通所致，表现为腹部胀满疼痛拒按，无正常矢气排出，常需结合外科措施治疗。"},{"t":"b","x":"2. 积聚"},{"t":"p","x":"便秘与积聚皆可见腹胀及大便不畅。"},{"t":"p","x":"便秘为大肠传导失司所致，以粪质干结，排出艰难，或粪质不硬，虽频有便意，但排便不畅为主症。"},{"t":"p","x":"积聚为肝脾同病，气滞痰阻血瘀结聚而成，以腹部出现包块为典型表现，可伴有腹痛、腹胀。"}],"bianzheng":[{"t":"b","x":"1. 辨虚实"},{"t":"p","x":"实证便秘，可见大便干硬，或黏滞不爽，排出困难，伴有烦热口渴，腹胀腹痛，面赤口臭等，多见于年轻体壮者。虚证便秘，可见大便干结，或大便不干，排出无力，可伴有头晕眼花，咽干，乏力气短，有汗，畏寒肢冷等，多见于老年人、妇女产后及久病体虚者。"},{"t":"b","x":"2. 辨便秘证候特点"},{"t":"p","x":"热秘表现为大便干结，数日不行，肛门灼热，或伴便血；气秘表现为排便困难，欲便不出，腹胀满突出；冷秘表现为大便不通，腹胀腹痛，畏寒。气虚便秘，可无大便干结，但无力排便，气短汗出，虚坐努责不下；血虚便秘，大便干结，面色无华，头晕心悸；阴虚便秘，大便干结，数日不行，咽干口渴；阳虚便秘，大便不干，但排出无力，腰膝酸冷。"}],"zhize":"便秘的治疗以通下为主，以恢复大肠传导功能，保持大便通畅为基本原则，但绝不可单纯使用泻下药，应针对不同的病因采取相应的治法，具体当辨虚实而治。实证邪滞大肠，大肠传导失司，以祛邪为主，分别施以泻热、温通、理气之法，辅以导滞之品；虚证肠道传送无力，或失于濡润，治以养正为先，用益气、养血、滋阴、温阳之法，酌用甘补滋润之药。《景岳全书·杂证谟·秘结》曰：“阳结者，邪有余，宜攻宜泻者也；阴结者，正不足，宜补宜滋者也。知斯二者，即知秘结之纲领矣。”","syndrome":[{"id":"s172","name":"热秘证","label":"1.热秘证","group":"","clinic":"大便干结，腹胀或痛，口干口臭，面红心烦，或有身热，小便短赤，舌质红，苔黄燥，脉滑数。","analysis":"肠胃积热，津液耗伤，肠道干涩，燥屎内停，腑气不通，故大便干结，腹胀或痛；阳明热盛，蓄热上蒸，则见口干口臭，面红身热，心烦；热结津伤，则小便短赤；舌质红，苔黄燥，脉滑数，为热盛津伤之象。","treat":"泻热导滞，润肠通便。","formulaRaw":"麻子仁丸（《伤寒论》）加减。","formulaName":"麻子仁丸加减","fangjie":"大黄、枳实、厚朴通腑泄热；麻子仁、杏仁、白蜜润肠通便；芍药养阴和营。若大便干结而坚硬，加芒硝；若口干舌燥，加生地黄、玄参、麦冬；若咳喘便秘，加瓜蒌仁、苏子、知母；若有痔疮、便血，加槐花、地榆。若燥热不甚，或药后大便不爽，用青麟丸；若热势较盛，痞满燥实坚兼有者，可用大承气汤。"},{"id":"s173","name":"气秘证","label":"2.气秘证","group":"","clinic":"大便干结，或不甚干结，欲便不得出，或便而不爽，肠鸣矢气，嗳气频作，胁腹痞满胀痛，舌质淡，苔薄腻，脉弦。","analysis":"情志失和，肝脾气机郁滞，肠腑传导失常，腑气不通，故大便干结，或不甚干结，欲便不得出，或便而不爽；肝气不疏，脾气郁结，胃气不和，肠腑气滞，故胁腹痞满胀痛，嗳气频作，肠鸣矢气；舌质淡，苔薄腻，脉弦，为气滞湿阻之象。","treat":"顺气导滞，降逆通便。","formulaRaw":"六磨汤（《世医得效方》）加减。","formulaName":"六磨汤加减","fangjie":"木香调气；乌药顺气；沉香降气；大黄、槟榔、枳壳破气行滞通便。若腹部胀痛甚，可加赤芍、柴胡、厚朴等；若肠鸣粪软，黏腻不畅，可加皂角子、蚕砂等；若七情郁结，忧郁寡言，可加白芍、柴胡、合欢皮等；若气郁化火，便秘腹痛，舌红苔黄，可加栀子、龙胆草等；若跌仆损伤或腹部术后，气滞血瘀，便秘不通，可加红花、赤芍、桃仁等。"},{"id":"s174","name":"冷秘证","label":"3.冷秘证","group":"","clinic":"大便艰涩，腹痛拘急，胀满拒按，胁下偏痛，手足不温，呃逆呕吐，舌质淡，苔白腻，脉弦紧。","analysis":"外感寒邪，恣食生冷，或过服寒凉药物，阴寒内盛，凝滞胃肠，大肠传导失司，糟粕不行，故大便艰涩，手足不温；阴寒凝滞肠腑，气机不畅，见腹痛拘急，胀满拒按；阴寒之邪犯胃，胃失和降，则呃逆呕吐；寒邪凝聚于厥阴部位，故胁下偏痛；舌质淡，苔白腻，脉弦紧，为阴寒凝滞之象。","treat":"温里散寒，通便止痛。","formulaRaw":"大黄附子汤（《金匮要略》)加减。","formulaName":"大黄附子汤加减","fangjie":"附子（制）、细辛温里散寒止痛，大黄荡涤积滞。若腹痛较甚，可加枳实、厚朴、芍药、甘草等；若腹部冷痛，手足不温，可加高良姜、花椒、小茴香、当归、乌药等。\n2. 虚秘"},{"id":"s175","name":"气虚便秘证","label":"1.气虚便秘证","group":"","clinic":"大便干或不干，虽有便意，但排出困难，用力努挣则汗出短气，便后乏力，面白神疲，肢倦懒言，舌质淡，苔白，脉弱。","analysis":"肺脾气虚，大肠传导无力，故虽有便意，却努挣不出，排便困难；肺气虚，故努挣则汗出气短，便后疲乏；脾气虚，化源不足，故面白神疲，肢倦懒言；舌质淡，苔白，脉弱，为气虚之象。","treat":"补脾益肺，润肠通便。","formulaRaw":"黄芪汤（《金匮翼》)加减。","formulaName":"黄芪汤加减","fangjie":"黄芪补脾肺之气；火麻仁、白蜜润肠通便；陈皮理气。若排便困难，腹部坠胀，合补中益气汤加减；若气阴两虚，气短懒言，多汗少动，口干面赤，加生脉散；若脘腹痞满，纳呆便溏，舌苔白腻，可加扁豆、生薏苡仁、蚕砂等，或重用生白术。若肢倦腰酸，用大补元煎加减。"},{"id":"s176","name":"血虚便秘证","label":"2.血虚便秘证","group":"","clinic":"大便干结，面色无华，皮肤干燥，头晕目眩，心悸气短，健忘少寐，口唇色淡，舌淡，苔少，脉细。","analysis":"血虚津少，肠腑失于濡润，故大便干结；血虚不能上荣，故面色无华，口唇色淡；肌肤失养，故皮肤干燥；血虚心失所养，故心悸气短，健忘少寐；清窍失养，故头晕目眩；舌淡，苔少，脉细，为血虚之象。","treat":"养血滋阴，润燥通便。","formulaRaw":"润肠丸（《丹溪心法》）加减。","formulaName":"润肠丸加减","fangjie":"当归、生地黄滋阴养血；麻仁、桃仁润肠通便；枳壳引气下行。若大便干结如羊屎，可加蜂蜜、柏子仁、黑芝麻等；若面白，咳晕甚，可加何首乌、熟地黄、枸杞子等；若气短乏力，排便无力，可加黄芪、人参、生白术等；若阴血已复，便仍干燥，用五仁丸。"},{"id":"s177","name":"阴虚便秘证","label":"3.阴虚便秘证","group":"","clinic":"大便干结，形体消瘦，头晕耳鸣，两颧红赤，心烦少寐，潮热盗汗，腰膝酸软，舌质红，苔少，脉细数。","analysis":"阴津亏虚，肠道失濡，故见大便干结；阴虚则形体消瘦；阴虚清窍失养，则头晕耳鸣；腰府失养，则腰膝酸软；阴虚火旺，故两颧红赤，心烦少寐，潮热盗汗；舌质红，苔少，脉细数，为阴虚之象。","treat":"滋阴增液，润肠通便。","formulaRaw":"增液汤（《温病条辨》）加减。","formulaName":"增液汤加减","fangjie":"玄参滋阴润燥兼清热，麦冬养阴生津，生地黄凉血养阴。若口干面红，心烦盗汗，可加白芍、知母等；若阴亏燥结，热盛伤津，大便干结，数日不行，可加大黄等，或用增液承气汤加减；若胃阴不足，口渴纳减者，合益胃汤加减；若肾阴不足，腰膝酸软，合六味地黄丸加减。"},{"id":"s178","name":"阳虚便秘证","label":"4.阳虚便秘证","group":"","clinic":"大便干或不干，排出困难，面色㿠白，四肢不温，腹中冷痛，腰膝酸冷，小便清长，舌质淡，苔白，脉沉迟。","analysis":"本证多见于老年、病久之人。阳气虚衰，大肠传导无力，故大便干；阳虚温煦无权，故面色㿠白，四肢不温；阳虚阴寒内盛，寒凝气滞，故腹中冷痛；肾虚失摄，故小便清长；腰失温养，故腰膝酸冷；舌质淡，苔白，脉沉迟，为阳虚内寒之象。","treat":"补肾温阳，润肠通便。","formulaRaw":"济川煎（《景岳全书》）加减。","formulaName":"济川煎加减","fangjie":"肉苁蓉温补肾阳，润肠通便；牛膝补肾强腰，性善下行；当归养血润肠；升麻、泽泻升清降浊；枳壳宽肠下气。若神疲纳差，可加黄芪、党参、白术等；若腹中冷痛，便意频频，排出困难，可加肉桂、白芍、甘草、锁阳等；老人虚冷便秘顽症，合半硫丸。"}],"linchuang":["通下法的应用。对于通下法，不能简单地理解为使用泻下药。首先，应分虚实论治，虚中有实，实中有虚，虚实夹杂的患者，又当标本兼顾。常用寒下、温下、润下等法。寒下法应用于肠胃积热，燥屎内结之实证，如气滞较甚，则需配理气之品，体素虚弱者，则可佐扶正之味，攻补兼施。如有下焦阳虚阴盛者，则不宜徒用攻下，以防更损阳气，但若单用温阳之法，又会便结难开，故宜温阳与攻下并投，以温下法治之，方可奏效。润下法适用于“无水舟停”之肠燥便秘，在应用中应考虑患者多有津血不足存在，可配以益气或滋阴养血之品。其次，如长期滥用单纯泻下之品，不仅可产生不良反应，也可使患者产生耐受性。在此过程中同时进行生活调摄，消除致病因素，方有望彻底治愈便秘。","合理应用外治法。对于年老体虚，便结较甚，服药不应的便秘患者，应从多方面调治，不可单纯依赖内服药物，可配合应用外治法。如张仲景的蜜煎导及猪胆汁导法。《医宗金鉴·杂病心法要诀·大便燥结总括》云：“直肠结，即燥屎巨硬，结在肛门难出之燥也，从导法治之。”此外，对平素津血不足，时常便秘之人，可常服黑芝麻、杏仁、蜂蜜等养阴润肠之品，以防微杜渐。"],"yufang":["注意饮食以清淡为主，避免过食辛辣厚味或饮酒无度，亦不可过食寒凉生冷，多吃粗粮果蔬，多饮水。避免久坐少动，养成定时排便的习惯。避免过度精神刺激，保持心情舒畅。加强身体锻炼。","对于年老体弱及便秘日久的患者，为防止过度用力努挣而诱发痔疮、便血甚至真心痛等病证，可采用食饵疗法，如黑芝麻、胡桃肉、松子仁等份，研细，稍加白蜜冲服。对阴血不足之便秘，也可配合灌肠等外治法治疗。"],"attachIds":[]},{"id":"d028","name":"胁痛","kind":"main","parent":null,"chapterNo":"第三十一章","chapterName":"胁痛","yinbing":[{"t":"p","x":"胁痛主要由情志不遂、饮食不节、跌仆损伤和久病体虚等因素，引起肝络失和，或肝络不通，或络脉失养所致。"},{"t":"b","x":"1. 情志不遂"},{"t":"p","x":"情志所伤，或暴怒伤肝，或抑郁忧思，皆可致肝失条达，疏泄不利，气阻络痹，发为肝郁胁痛。"},{"t":"p","x":"如清·尤在泾《金匮翼·胁痛统论》云：“肝郁胁痛者，悲哀恼怒，郁伤肝气。”"},{"t":"p","x":"气郁日久，血行不畅，瘀血渐生，阻于胁络，不通则痛，引起瘀血胁痛。"},{"t":"p","x":"清·叶天士《临证指南医案·胁痛》云：“久病在络，气血皆窒。”"},{"t":"b","x":"2. 跌仆损伤"},{"t":"p","x":"跌仆外伤，或因强力负重，使胁络受伤，瘀血停留，阻塞胁络，发为胁痛。"},{"t":"p","x":"如《金匮翼·胁痛统论》谓：“污血胁痛者，凡跌仆损伤，污血必归胁下故也。”"},{"t":"b","x":"3. 饮食不节"},{"t":"p","x":"过食肥甘，损伤脾胃，脾失健运，湿热内生，郁于肝胆，肝胆失于疏泄，发为胁痛。"},{"t":"p","x":"如《景岳全书·杂证谟·胁痛》曰：“以饮食劳倦而致胁痛者，此脾胃之所传也。”"},{"t":"b","x":"4. 外邪内侵"},{"t":"p","x":"湿热之邪外袭，郁结少阳，枢机不利，肝胆经气失于疏泄，可致胁痛。"},{"t":"p","x":"《素问·缪刺论》云：“邪客于足少阳之络，令人胁痛不得息。”"},{"t":"b","x":"5. 劳欲久病"},{"t":"p","x":"久病耗伤，或劳欲过度，精血亏虚，肝阴不足，血虚不能养肝，故脉络失养，拘急而痛。"},{"t":"p","x":"《景岳全书·杂证谟·胁痛》云：“凡房劳过度，肾虚羸弱之人，多有胸胁间隐隐作痛，此肝肾精虚。”"},{"t":"p","x":"《金匮翼·胁痛统论》谓：“肝虚者，肝阴虚也。阴虚则脉绌急，肝之脉贯膈布胁肋，阴血燥则经脉失养而痛。”"}],"bingji":[{"t":"p","x":"胁痛的基本病机是肝络失和。"},{"t":"p","x":"病理变化可分为“不通则痛”与“不荣则痛”两类。"},{"t":"p","x":"病位主要在肝、胆，与脾、胃及肾有关。"},{"t":"p","x":"病理性质有虚实之分。"},{"t":"p","x":"因肝郁气滞、瘀血停着、湿热蕴结所致的胁痛多属实证，为“不通则痛”；因阴血不足、肝络失养所致的胁痛则为虚证，属“不荣则痛”。"},{"t":"p","x":"病理因素为气滞、血瘀和湿热，又以气滞为先。"},{"t":"p","x":"以气滞为先，气机不畅致胁痛。"},{"t":"p","x":"气滞日久，则血行不畅，津液瘀滞，可由气滞转为血瘀、湿热，或气滞、血瘀、湿热并见。"},{"t":"p","x":"实证日久，因肝郁化火，耗伤肝阴，或肝胆湿热，耗伤阴津，或瘀血不去，新血不生，致精血虚少，可由实转虚。"},{"t":"p","x":"同时，阴血不足、肝络失养之虚证，又可在情志、饮食等因素的影响下，产生虚中夹实的变化，表现为虚实夹杂之证。"},{"t":"p","x":"如湿热瘀阻肝胆之胁痛，若湿热交蒸，胆汁外溢，可并见黄疸；肝郁气滞或瘀血停着之胁痛，可转化为积聚；肝失疏泄，脾失健运，病久及肾，致气血水停于腹中，可转化为鼓胀。"}],"zhenduan":[{"t":"ol","items":["1. 以一侧或两侧胁肋部疼痛为主要表现，疼痛性质可以表现为刺痛、胀痛、灼痛、隐痛、钝痛等。","2. 部分患者可伴见胸闷、腹胀、嗳气、呃逆、急躁易怒、口苦纳呆、厌食恶心等症。","3. 常有饮食不节、情志内伤、感受外湿、跌仆闪挫或劳欲久病等病史。"]}],"jianbie":[{"t":"p","x":"主要与悬饮相鉴别。"},{"t":"b","x":"1. 悬饮"},{"t":"p","x":"悬饮与胁痛均可见胁肋疼痛，但悬饮表现为饮留胁下，胸胁胀痛，持续不已，伴见咳嗽、咳痰，呼吸时疼痛加重，常喜向患侧卧，患侧肋间饱满，叩诊呈浊音，或兼见发热。"}],"bianzheng":[{"t":"b","x":"1. 辨在气在血"},{"t":"p","x":"胁痛在气，以胀痛为主，且游走不定，痛无定处，时轻时重，症状随情志变化而起伏；胁痛在血，以刺痛为主，且痛处固定不移，疼痛持续不已，局部拒按，入夜尤甚。"},{"t":"p","x":"《景岳全书·杂证谟·胁痛》云：“但察其有形无形，可知之矣。盖血积有形而不移，或坚硬而拒按，气痛流行而无迹，或倏聚而倏散。”"},{"t":"b","x":"2. 辨属虚属实"},{"t":"p","x":"实证之中以气滞、血瘀、湿热为主，多病程短，来势急，疼痛较重而拒按，脉实有力。虚证多因阴血不足，脉络失养，其痛隐隐，绵绵不休，病程长，来势缓，伴见全身阴血亏耗表现。久病胁痛每多虚实夹杂。"}],"zhize":"胁痛的治疗以疏肝和络止痛为基本治则，应结合肝胆的生理特点，灵活运用。实证以祛邪疏通为主，宜采用理气、活血、清热、利湿之法；虚证以扶正柔肝为要，宜补中寓通，采用滋阴、养血、柔肝之法，适当加入疏肝理气之品。","syndrome":[{"id":"s179","name":"肝郁气滞证","label":"1. 肝郁气滞证","group":"","clinic":"胁肋胀痛，走窜不定，甚则引及胸背肩臂，疼痛每因情志变化而增减，胸闷腹胀，嗳气频作，得嗳气而胀痛稍舒，纳少口苦，舌淡红，苔薄白，脉弦。","analysis":"肝气失于条达，气机郁滞，络脉失和，故胁肋胀痛；气属无形，时聚时散，聚散无常，故疼痛走窜不定；情志变化与气之郁结关系密切，故疼痛随情志变化而增减；肝经气机不畅，故胸闷气短；肝气横逆，易犯脾胃，故腹胀纳少，口苦嗳气；舌淡红，苔薄白，脉弦，为肝郁气滞之象。","treat":"疏肝理气。","formulaRaw":"柴胡疏肝散（《医学统旨》）加减。","formulaName":"柴胡疏肝散加减","fangjie":"柴胡、香附、枳壳、陈皮疏肝理气，解郁止痛；白芍、甘草养血柔肝，缓急止痛；川芎活血行气，通络止痛。若胁痛甚，可加青皮、郁金、延胡索；气郁化火，见胁肋掣痛，口干口苦，烦躁易怒，溲黄便秘，舌红苔黄者，可加山栀、丹皮、黄芩、夏枯草等；肝气横逆犯脾，见肠鸣、腹泻、腹胀者，可合逍遥散加减。"},{"id":"s180","name":"肝胆湿热证","label":"2. 肝胆湿热证","group":"","clinic":"胁肋胀痛或灼热疼痛、剧痛，口苦口黏，胸闷纳呆，恶心呕吐，小便黄赤，大便不爽，或兼有身热恶寒，身目发黄，舌红，苔黄腻，脉弦滑数。","analysis":"湿热蕴结，肝胆失疏，络脉失和，故胁肋胀痛或灼痛；湿热中阻，升降失常，故胸闷纳呆，恶心呕吐，口苦，大便黏滞；湿热交蒸，胆汁不循常道而外溢，出现目黄，身黄，小便黄赤；舌红，苔黄腻，脉弦滑数，为肝胆湿热之象。","treat":"清热利湿。","formulaRaw":"龙胆泻肝汤（《医方集解》）加减。","formulaName":"龙胆泻肝汤加减","fangjie":"龙胆草上清肝胆实火，下泻肝胆湿热；黄芩、栀子泻火解毒，燥湿清热；车前子、木通、泽泻导湿热下行；生地黄养阴，当归补血；柴胡疏畅肝胆；甘草防苦寒之品伤胃，并调和诸药。伴黄疸者，加茵陈、黄柏；大便不通，腹胀腹满者，可合大柴胡汤；砂石阻滞胆道，胁肋连及肩背者，加金钱草、海金沙、鸡内金、郁金、川楝子等；胸胁苦满疼痛，寒热往来，口苦咽干，心烦喜呕者，为邪郁少阳，用小柴胡汤加减；胁肋剧痛，呕吐蛔虫者，先以乌梅丸安蛔，再予驱蛔。"},{"id":"s181","name":"瘀血阻络证","label":"3. 瘀血阻络证","group":"","clinic":"胁肋刺痛，痛有定处，痛处拒按，入夜痛甚，肋下或见有癥块，舌紫暗，苔薄白，脉沉涩。","analysis":"肝郁日久，气滞血瘀，或跌仆损伤，致瘀血停着，痹阻胁络，故胁痛如刺，痛处不移，入夜痛甚；瘀结停滞，积久不散，则渐成癥块；舌紫暗，苔薄白，脉沉涩，为瘀血阻络之象。","treat":"祛瘀通络。","formulaRaw":"血府逐瘀汤（《医林改错》）或复元活血汤（《医学发明》）加减。前方活血化瘀，行气止痛；后方祛瘀通络，消肿止痛。","formulaName":"血府逐瘀汤或复元活血汤加减","fangjie":"当归、川芎、赤芍、桃仁、红花活血化瘀；穿山甲破瘀通络；大黄祛瘀生新；牛膝祛瘀血，通血脉，引瘀血下行；柴胡疏肝解郁，升达清阳；桔梗开宣肺气，载药上行；生地黄凉血清热；天花粉消瘀散结，清热润燥；甘草调和诸药。如胁肋下有癥块，正气未衰者，加三棱、莪术、土鳖虫，或合鳖甲煎丸；若属气滞痰瘀阻滞，症见咳嗽、胸胁疼痛者，可合香附旋覆花汤（《温病条辨》）加减。"},{"id":"s182","name":"肝络失养证","label":"4. 肝络失养证","group":"","clinic":"胁肋隐痛，悠悠不休，遇劳加重，口干咽燥，心中烦热，头晕目眩，舌红，少苔，脉细弦而数。","analysis":"肝郁日久化热，耗伤肝阴，或久病体虚，精血亏损，不能濡养肝络，故胁肋隐痛，悠悠不休，遇劳加重；阴虚易生内热，故口干咽燥，心中烦热；精血亏虚，不能上荣，故头晕目眩；舌红，少苔，脉细弦而数，为肝络失养之象。","treat":"养阴柔肝。","formulaRaw":"一贯煎（《续名医类案》）加减。","formulaName":"一贯煎加减","fangjie":"生地黄、北沙参、麦冬、当归、枸杞子滋阴养血柔肝；川楝子疏肝泄热，理气止痛。若阴亏过甚，舌红而干，口渴多饮者，加石斛、玉竹、玄参、天冬；心神不宁，心烦不寐者，加酸枣仁、五味子、栀子、合欢皮；肝肾阴虚，头目失养，见头晕目眩、视物昏花者，加女贞子、墨旱莲、黄精、熟地黄、桑椹、菊花；阴虚火旺，加黄柏、知母、地骨皮；神疲乏力明显者，加太子参。"}],"linchuang":["胁痛部位勿拘于右侧。胁痛一病，不能因肝胆的解剖部位而拘泥于右侧。《灵枢·五邪》谓：“邪在肝，则两胁中痛。”明言胁痛可为双侧胁肋疼痛。《素问·刺禁论》云：“肝生于左，肺藏于右。”指出肝气主升，升发于左，肺气主降，肃降于右。后世“左升右降”之说认为，肝肺气机一升一降，调节着人体气机升降运动。如《诸病源候论·胸胁支满候》谓：“肺之积气在于右胁，肝之积气在于左胁。”程国彭《医学心悟·胁痛》谓：“伤寒胁痛，属少阳经受邪，用小柴胡汤。杂证胁痛，左为肝气不和，用柴胡疏肝散；七情郁结，用逍遥散；若兼肝火、痰饮、食积、瘀血，随证加药；右为肝移邪于肺，用推气散。凡治实证胁痛，左用枳壳，右用郁金，皆为的剂，然亦有虚寒作痛，得温则散，按之则止者，又宜温补，不可拘执也。”此说可资参考。","治疗胁痛宜疏肝柔肝并举。胁痛的基本病机是肝络失和，疏肝解郁、理气止痛为常用治法。然肝为刚脏，体阴而用阳，治疗宜柔肝而不宜伐肝。疏肝理气药大多辛温香燥，若久用或配伍不当，易耗伤肝阴，甚则助热化火。故临证使用疏肝理气药时，一要选用轻灵平和之品，如香附、苏梗、佛手、绿萼梅之类，二要注意配伍柔肝养阴药物，以顾护肝阴，以利肝体。如仲景之四逆散中柴胡与白芍并用，薛己之滋水清肝饮中柴胡与生地黄配伍，均是疏肝柔肝并用的范例。","胆道疾病所致胁痛的用药思路。如胁痛兼有砂石结聚者，治疗当注意通腑、化石、排石药的配伍应用。辨证属湿热阻滞证，肝胆气机失于通降，出现右胁肋部绞痛难忍，恶心呕吐，口苦纳呆，治疗当清利肝胆，通降排石，常用大柴胡汤加减。通腑泻下常用大黄、芒硝；化石、排石药物可选用鸡内金、海金沙、金钱草、郁金、茵陈、枳壳、莪术、皂角刺、煅瓦楞子等。"],"yufang":["预防胁痛，情绪应保持稳定，避免过怒、过悲、过劳及过度紧张；同时注意饮食清淡，忌食辛辣肥甘和过度饮酒；动静有度，避免因外伤引起胁痛。","对胁痛患者要通过安慰、鼓励等方式稳定情绪，可缓解和消除躯体疼痛感，减少因疼痛带来的情绪波动。注意劳逸结合，起居有常，顺应四时变化。适当参加体育活动，如散步、打太极拳等，有利于气血运行，恢复正气。"],"attachIds":[]},{"id":"d029","name":"黄疸","kind":"main","parent":null,"chapterNo":"第三十二章","chapterName":"黄疸","yinbing":[{"t":"p","x":"黄疸的病因分为外感、内伤两类，外感多属湿热所致，内伤常与饮食、劳倦、病后有关，内外病因互有关联，引起湿邪困遏脾胃，壅塞肝胆，疏泄失常，胆汁泛溢，发生黄疸。"},{"t":"b","x":"1. 感受外邪"},{"t":"p","x":"夏秋季节，暑湿当令，或因湿热偏盛，由表入里，内蕴中焦，湿郁热蒸，不得泄越，而致发黄。"},{"t":"p","x":"若湿热夹时邪疫毒伤人，则病势暴急，热毒炽盛，内及营血，发为急黄。"},{"t":"p","x":"《诸病源候论·急黄候》谓：“脾胃有热，谷气郁蒸，因为热毒所加，故猝然发黄，心满气喘，命在顷刻，故云急黄也。”"},{"t":"b","x":"2. 饮食所伤"},{"t":"p","x":"长期嗜酒无度，或过食肥甘厚腻，或饮食不洁，或药毒伤肝，脾胃损伤，运化失职，湿浊内生，郁而化热，湿热熏蒸，胆汁泛溢，而发为黄疸。"},{"t":"p","x":"如《金匮要略·黄疸病脉证并治》云：“谷气不消，胃中苦浊，浊气下流，小便不通，阴被其寒，热结膀胱，身体尽黄，名曰谷疸。”"},{"t":"b","x":"3. 脾胃虚寒"},{"t":"p","x":"长期饥饱失常，或恣食生冷，或劳倦太过，或病后脾阳受损，都可导致脾虚寒湿内生，困遏中焦，壅塞肝胆，致使胆液不循常道，外溢肌肤，而为黄疸。"},{"t":"p","x":"如清·林珮琴《类证治裁·黄疸》云：“阴黄系脾脏寒湿不运，与胆液浸淫，外渍肌肉，则发而为黄。”"},{"t":"b","x":"4. 病后续发"},{"t":"p","x":"胁痛、癥积或其他病证，损肝伤脾，湿遏瘀阻，胆汁泛溢肌肤，出现黄疸。"},{"t":"p","x":"如清·张璐《张氏医通·杂门》指出：“以诸黄虽多湿热，然经脉久病，不无瘀血阻滞也。”“有瘀血发黄，大便必黑，腹胁有块或胀，脉沉或弦。”"},{"t":"b","x":"5. 其他"},{"t":"p","x":"亦有因砂石、虫体阻滞胆道而导致胆汁外溢而发黄者。"}],"bingji":[{"t":"p","x":"黄疸的基本病机是湿邪困遏脾胃，肝胆疏泄失常，胆汁泛溢肌肤，其关键是湿邪为患。"},{"t":"p","x":"病位主要在脾胃、肝胆。"},{"t":"p","x":"由于湿邪壅阻中焦，脾胃失健，肝气郁滞，疏泄不利，致胆汁输泄失常，胆液不循常道，外溢肌肤，下注膀胱，而见目黄、肤黄、小便黄。"},{"t":"p","x":"病理性质以实证多见，久病则为虚实夹杂。"},{"t":"p","x":"病理因素有湿邪、热邪、寒邪、瘀血、气滞和疫毒六种，但以湿邪为主。"},{"t":"p","x":"如因湿热所伤，或过食甘肥酒醴，或素体胃热偏盛，则湿从热化，湿热交蒸，瘀热在里，发为阳黄。"},{"t":"p","x":"邪盛谓之毒，若湿热瘀滞，蕴积化火，热毒炽盛，充斥三焦，深入营血，内陷心肝，可见猝然发黄，出现神昏、谵妄、痉厥、出血等危症，则为急黄。"},{"t":"p","x":"若因寒湿伤人，或素体脾胃虚寒，或病久脾阳受伤，则湿从寒化，寒湿瘀滞，中阳不振，脾虚失运，胆液为湿邪所阻，则发为阴黄。"},{"t":"p","x":"阳黄、急黄、阴黄在一定条件下可以相互转化。"},{"t":"p","x":"急黄若救治得当，亦可转危为安。"},{"t":"p","x":"若阳黄误治失治，迁延日久，脾阳损伤，湿从寒化，则可转为阴黄。"},{"t":"p","x":"黄疸以速退为顺，如经久不愈，湿浊瘀滞，可转为积证；肝络瘀阻，血不利则为水，水停于腹，则为鼓胀；络热血溢，可见吐衄、发斑之血证；久病耗伤气血，脏腑失养，又可为虚劳。"}],"zhenduan":[{"t":"ol","items":["1. 目黄，肤黄，小便黄，其中目睛黄染为本病的重要特征。","2. 常伴食欲减退、恶心呕吐、胁痛腹胀等症状。","3. 常有外感湿热疫毒，内伤酒食不节，或有胁痛、癥积、鼓胀等病史。"]}],"jianbie":[{"t":"p","x":"主要与萎黄相鉴别。"},{"t":"b","x":"1. 萎黄"},{"t":"p","x":"萎黄与黄疸均有肤黄的表现。"},{"t":"p","x":"黄疸发病与感受外邪、饮食劳倦或病后有关，病机为湿滞脾胃，肝胆失疏，胆汁外溢，主症为身黄、目黄、小便黄，尤以目睛黄染为特征。"},{"t":"p","x":"萎黄之病因与饥饱劳倦、食滞虫积或病后失血有关，病机为脾胃虚弱，气血不足，肌肤失养，主症为肌肤萎黄不泽，目睛及小便不黄，常伴头昏倦怠、心悸少寐、纳少便溏等。"}],"bianzheng":[{"t":"b","x":"1. 辨阳黄、急黄与阴黄"},{"t":"p","x":"阳黄多由湿热、瘀热所致，发病急，病程短，其黄色泽鲜明如橘，伴发热，口干苦，小便短赤，大便燥结，舌红，苔黄腻，脉弦滑数。急黄为阳黄之重症，热毒炽盛，营血耗伤，病情急骤，疸色如金，可见神昏、谵语、发斑、出血等危象。阴黄由脾胃虚寒，寒湿瘀滞所致，病程长，病势缓，其色虽黄，但色泽晦暗，伴脘腹痞闷，神疲乏力，纳少便溏，舌淡而暗，苔白腻，脉濡缓。"},{"t":"b","x":"2. 辨阳黄之湿热轻重"},{"t":"p","x":"阳黄虽由湿热所致，但有湿热轻重之分。热重于湿者，身目俱黄，色泽鲜明，发热口渴，大便燥结，舌苔黄腻，脉弦数；湿重于热者，色泽不如热甚者鲜明，头身困重，胸满脘痞，舌苔白腻微黄，脉弦滑。"}],"zhize":"黄疸的治疗大法为化湿邪，利小便。《金匮要略》云：“诸病黄家，但利其小便。”故治疗黄疸首当化湿。如阳黄湿热，应清热化湿；湿热与瘀热互结者，应清热化湿与凉血泻热并用。黄疸初起兼见表证，可一方面发汗解表，使湿从汗解，另一方面利小便，通过淡渗利湿，达到退黄的目的。急黄当以清热化湿解毒、凉营开窍为主。阴黄属寒湿者，应予温中化湿；属脾虚湿滞者，治以健脾和血，利湿退黄。","syndrome":[{"id":"s183","name":"热重于湿证","label":"1.热重于湿证","group":"","clinic":"身目俱黄，黄色鲜明，发热口渴，或见心中懊侬，腹部胀闷，口干而苦，恶心呕吐，小便短少黄赤，大便秘结，舌红，苔黄腻，脉弦数。","analysis":"湿热熏蒸，困遏脾胃、壅滞肝胆，胆汁泛溢，故见身目黄色鲜明，发热口渴；湿热蕴结、脾胃运化失健，气机阻滞，见纳差，恶心，脘胀胁痛；湿热下注，腑气不通，则小便短赤，大便秘结；舌红、苔黄腻，脉弦数，为热重于湿之象。","treat":"清热利湿，凉血泄热。","formulaRaw":"茵陈蒿汤（《伤寒论》）加减。","formulaName":"茵陈蒿汤加减","fangjie":"茵陈蒿清热利湿退黄，为治黄疸的第一要药；栀子清利三焦之热，又有凉血之功；大黄凉血通腑泄热。若胁痛较甚，可加柴胡、郁金、赤白芍、延胡索等；若热毒内盛，心烦懊侬，加黄连、龙胆草等；恶心呕吐，加橘皮、竹茹、半夏等；瘀热偏重者，可加赤芍、生地黄、丹皮、虎杖、茜草等。"},{"id":"s184","name":"湿重于热证","label":"2.湿重于热证","group":"","clinic":"身目俱黄，黄色不及前者鲜明，头重身困，胸脘痞满，食欲减退，恶心呕吐，腹胀，大便溏垢，舌红，苔厚腻微黄，脉濡数或濡缓。","analysis":"湿遏热伏，困遏中焦，胆汁不循常道，故见身目色黄而不鲜；湿困中焦，脾胃运化失常，则食欲减退，胸脘痞满，恶心呕吐，腹胀，大便溏垢；湿邪内阻，见头重身困；舌红，苔厚腻微黄，脉濡数或濡缓，为湿重于热之象。","treat":"化湿利小便，佐以清热。","formulaRaw":"茵陈五苓散（《金匮要略》）合甘露消毒丹（《医效秘传》）加减。前方清热利湿以退黄，后方利湿化浊，清热解毒。","formulaName":"茵陈五苓散合甘露消毒丹加减","fangjie":"藿香、白蔻仁、石菖蒲辟秽化浊，行气悦脾；泽泻、茯苓、猪苓、木通利水渗湿；白术健脾化湿；桂枝温阳化气；茵陈蒿、滑石、黄芩利湿清热；连翘、射干、贝母、薄荷解毒散结。若湿阻气机，胸腹痞胀，呕恶纳差，加入苍术、厚朴、半夏等。邪郁肌表，寒热头痛，用麻黄连轺赤小豆汤。本证不可过用苦寒药，以免脾阳受损，转为阴黄。"},{"id":"s185","name":"胆腑郁热证","label":"3.胆腑郁热证","group":"","clinic":"身目发黄，黄色鲜明，上腹、右胁胀闷疼痛，牵引肩背，身热不退，或寒热往来，口苦咽干，呕吐，尿黄赤，大便秘结，舌红，苔黄，脉弦滑数。","analysis":"湿热或砂石阻滞胆腑，通降失司，胆汁不循常道，身目发黄而胁痛；胆经热炽，则身热，口苦，咽干，或见寒热往来；胆胃不和，则呕吐；腑气不通，膀胱不利，则腹胀，便秘，尿赤；舌红，苔黄，脉弦滑数，为胆腑郁热之象。","treat":"疏肝泄热，利胆退黄。","formulaRaw":"大柴胡汤（《伤寒论》）加减。","formulaName":"大柴胡汤加减","fangjie":"柴胡、黄芩和解少阳；半夏、生姜和胃降逆；大黄、枳实通腑泄热；白芍缓急止痛；大枣和中，调和诸药。若砂石阻滞，可加金钱草、海金沙、鸡内金、郁金、元明粉等；恶心呕逆明显，加厚朴、竹茹、陈皮等。"},{"id":"s186","name":"热毒炽盛证（急黄）","label":"4.热毒炽盛证（急黄）","group":"","clinic":"发病急骤，黄疸迅速加深，其色如金，皮肤瘙痒，高热口渴，胁痛腹满，神昏谵语，烦躁抽搐，或衄血、便血，或肌肤瘀斑，舌红绛，苔黄而燥，脉弦滑或数。","analysis":"湿热毒蕴，深入营血，熏灼肝胆，则黄疸迅速加深，身黄如金，胁痛腹满；热盛灼津，故见高热烦渴，尿闭；邪陷营血，迫血妄行，则见衄血、便血，或肌肤瘀斑；热毒内陷心包，神明失用，则神昏谵语；热毒引动肝风，则肢体抽搐；舌红绛，苔黄而燥，脉弦滑或数，为热毒炽盛之象。","treat":"清热解毒，凉血开窍。","formulaRaw":"犀角地黄汤（《备急千金要方》）加减。","formulaName":"犀角地黄汤加减","fangjie":"水牛角（代犀角）清热解毒凉血；生地黄清热凉血，养阴生津；赤芍凉血化瘀，泄热和营；丹皮凉血散瘀。若神昏谵语，配安宫牛黄丸、至宝丹；动风抽搐者，可加羚羊角粉或紫雪；衄血、便血、肌肤瘀斑重者，加地榆炭、侧柏叶炭、紫草、茜草炭等；腹大有水，小便短少不利，加马鞭草、白茅根、车前草、大腹皮、猪苓、泽泻等；大便不通，腹满烦痛者，乃热毒炽盛所致，加大黄、芒硝、枳实、木香、槟榔等。\n2. 阴黄"},{"id":"s187","name":"寒湿阻遏证","label":"1.寒湿阻遏证","group":"","clinic":"身目俱黄，黄色晦暗，或如烟熏，脘腹痞胀，纳谷减少，大便不实，神疲畏寒，口淡不渴，舌淡红，苔腻，脉濡缓或沉迟。","analysis":"中阳不振，寒湿滞留，肝胆失于疏泄，影响胆汁排泄，身目发黄而晦暗；寒湿困中，运化失司，纳减，脘闷腹胀，便溏；寒湿损伤中阳，气血不足，神疲乏力，畏寒；舌淡红，苔腻，脉濡缓或沉迟，为寒湿阻遏之象。","treat":"温中化湿，健脾和胃。","formulaRaw":"茵陈术附汤（《医学心悟》）加减。","formulaName":"茵陈术附汤加减","fangjie":"茵陈、附子（制）并用温化寒湿退黄；白术、干姜、甘草健脾温中。若湿邪较重而便溏明显，加车前子、茯苓、泽泻、猪苓等；脘腹胀满，胸闷、呕恶显著，加苍术、厚朴、半夏、陈皮等；胁腹疼痛作胀，肝脾同病者，加柴胡、香附、姜黄、延胡索等；湿浊不清，气滞血结，胁下结痛，腹部胀满，肤色苍黄或黧黑，加丹参、三七、赤芍，或合硝石矾石散。"},{"id":"s188","name":"脾虚湿滞证","label":"2.脾虚湿滞证","group":"","clinic":"面目及肌肤淡黄，甚则晦暗不泽，肢软乏力，心悸气短，大便溏薄，舌淡，苔薄，脉濡细。","analysis":"黄疸日久，或素体脾虚，脾失健运，气血亏虚，湿滞残留，故面目及肌肤淡黄，晦暗不泽，大便溏薄；气血亏虚，则肢软乏力，心悸气短；舌淡，苔薄，脉濡细，为脾虚湿滞之象。","treat":"健脾和血，利湿退黄。","formulaRaw":"黄芪建中汤（《金匮要略》)加减。","formulaName":"黄芪建中汤加减","fangjie":"黄芪、桂枝、生姜益气温中；饴糖补虚缓中，生津润燥；白芍、大枣、甘草和血健脾。如气虚乏力明显，重用黄芪，加党参；畏寒，肢冷，舌淡胖者，加附子（制）；心悸不宁，脉细而涩者，加熟地黄、丹参等。\n3. 黄疸消退后的调治"},{"id":"s189","name":"湿热留恋证","label":"1.湿热留恋证","group":"","clinic":"脘痞腹胀，胁肋隐痛，饮食减少，口中干苦，小便黄赤，舌红，苔腻，脉濡数。","analysis":"湿热留恋，余邪未清，下注膀胱，故小便黄赤；湿困中焦，脾胃运化失常，故脘痞腹胀，胁肋隐痛，饮食减少；热灼津液，故口中干苦；舌红，苔腻，脉濡数，为湿热流连之象。","treat":"清热利湿。","formulaRaw":"茵陈四苓散（《杏苑生春》)加减。","formulaName":"茵陈四苓散加减","fangjie":"茵陈清热利湿退黄；茯苓、猪苓、泽泻、白术健脾化湿，淡渗分利。若热较盛，加黄芩、黄柏等；湿邪较重，加萆薢、车前草等。"},{"id":"s190","name":"肝脾不调证","label":"2.肝脾不调证","group":"","clinic":"脘腹痞闷，肢倦乏力，胁肋隐痛不适，纳谷不馨，大便不调，舌淡，苔薄白，脉细弦。","analysis":"肝脾不调，疏运失职，故脘腹痞闷，胁肋隐痛不适；脾虚运化失司，故纳谷不馨，大便不调，肢倦乏力；舌淡，苔薄白，脉细弦，为肝脾不调之象。","treat":"调和肝脾，理气助运。","formulaRaw":"柴胡疏肝散（《医学统旨》）或归芍六君子汤（《笔花医镜》）加减。前方偏重疏肝理气，后方偏重调养肝脾。","formulaName":"柴胡疏肝散或归芍六君子汤加减","fangjie":"当归、白芍、柴胡、枳壳、香附养血疏肝；党参、白术、茯苓益气健脾；陈皮、半夏理气消痞助运；川芎行气活血；甘草调和诸药。"},{"id":"s191","name":"气滞血瘀证","label":"3.气滞血瘀证","group":"","clinic":"胁下结块，隐痛、刺痛不适，胸胁胀闷，面、颈部见有赤丝红纹，舌有紫斑或紫点，苔薄，脉涩。","analysis":"气滞血瘀，积块留着，不通则痛，故胁下结块，隐痛、刺痛不适，胸胁胀闷；血瘀阻络，故面、颈部见有赤丝红纹；舌有紫斑或紫点，苔薄，脉涩，为气滞血瘀之象。","treat":"疏肝理气，活血化瘀。","formulaRaw":"逍遥散（《太平惠民和剂局方》）合鳖甲煎丸（《金匮要略》）加减。","formulaName":"逍遥散合鳖甲煎丸加减","fangjie":"柴胡疏肝理气；白芍、当归养血柔肝；白术、茯苓、甘草健脾益气；鳖甲煎丸软坚消积。"}],"linchuang":["辨别病因，审证求机。临证时除根据黄疸的色泽、症状、病史辨别其阴阳属性外，应进行有关理化检查，区分肝细胞性、阻塞性或溶血性黄疸等不同性质，明确病毒性肝炎、胆囊炎、胆结石、消化道肿瘤或蚕豆黄等疾病诊断，以便采取相应的治疗措施。同时，在黄疸的治疗过程中，应区别病证偏表与偏里、湿重与热重、阳证与阴证。应及时掌握阴黄与阳黄之间的转化，以做相应的处理。","常用退黄药物。临床以茵陈为退黄要药，无论阴黄阳黄皆可使用。张仲景创制的茵陈蒿汤中用茵陈与大黄配伍，退黄效果较好。吴又可谓“退黄以大黄为专功”，如大便干结者，可重用生大黄；大便溏烂不爽者，可用制大黄。大黄除有清热解毒、通下退黄作用外，还有凉血止血、消瘀化癥之功。此外，现代名医经验又多主张重用赤芍，以凉血利胆、泄热退黄，常与丹参、茜草、虎杖等配伍。","淤胆型肝炎的治疗。淤胆型肝炎病机特点为湿热瘀结，或兼痰阻，肝络阻滞。初期多属阳黄，多系湿热与瘀热蕴结，胆汁泛溢；后期多属阴黄，为寒湿瘀结，正气渐损。治疗常加凉血活血、祛湿化痰、利胆通络之品。常用药如茵陈、赤芍、桃仁、莪术、丹参、虎杖、莱菔子、苍术、黄柏、胆南星、龙胆草、郁金、金钱草、鸡内金、山楂等。正虚者加黄芪、白术、女贞子、墨旱莲等。"],"yufang":["本病的预防应避免进食不洁食物，注意饮食节制，勿过嗜辛热甘肥食物，戒酒；起居有常，不妄作劳，以免损伤正气；避免接触传染病患者。","发病初期应卧床，恢复期或慢性久病患者可适当参加体育活动，如散步、打太极拳等。患者应保持心情舒畅，有助于病情康复。黄疸后常见食欲减退、恶心欲吐、腹胀等症，饮食宜清淡，不可过食生冷、膏粱厚味，以防损伤脾胃。应密切观察病情变化，若黄疸加深或见斑疹吐衄、神昏痉厥，属病情恶化之兆，须及时救治。"],"attachIds":["a005"]},{"id":"d030","name":"积聚","kind":"main","parent":null,"chapterNo":"第三十三章","chapterName":"积聚","yinbing":[{"t":"p","x":"积聚的发生，多因情志失调、饮食所伤、外邪侵袭及病后体虚所致，或黄疸、疟疾等经久不愈而成，且交错夹杂，混合致病，以致肝脾受损，脏腑失和，气机阻滞，瘀血搏结，或兼痰湿凝滞，而成积聚。"},{"t":"b","x":"1. 情志失调"},{"t":"p","x":"情志抑郁，或思虑过度，肝失疏泄，脏腑失和，气机阻滞，血行不畅，气滞血瘀，日积月累，而成积聚。"},{"t":"p","x":"金·张从正《儒门事亲·五积六聚治同郁断》云：“积之成也，或因暴怒、喜、悲、思、恐之气。”"},{"t":"b","x":"2. 饮食失调"},{"t":"p","x":"酒食不节，饥饱失宜，或嗜食肥甘厚味、辛辣生冷，脾胃受损，运化失健，水谷精微不布，湿浊凝聚成痰，气机壅结，则成聚证；病久入络，痰浊与气血相搏，结为积块，而成积证。"},{"t":"p","x":"宋·王怀隐《太平圣惠方·治食癥诸方》云：“夫人饮食不节，生冷过度，脾胃虚弱，不能消化，与脏气相搏，结聚成块，日渐生长，盘牢不移。”"},{"t":"b","x":"3. 外邪侵袭"},{"t":"p","x":"寒、湿、热等外感六淫之邪，或感染虫毒，邪毒侵袭人体，稽留不去，均可导致受病脏腑失和，气血运行不畅，痰浊内生，气滞血瘀痰凝，日久形成积聚。"},{"t":"p","x":"唐·王焘《外台秘要·寒疝积聚方四首》曰：“夫积聚者，由寒气在内所生也，血气虚弱，风邪搏于脏腑，寒多则气涩，气涩则生积聚也。”"},{"t":"b","x":"4. 他病续发"},{"t":"p","x":"黄疸、胁痛病后，湿浊流连，气血蕴结；或久疟不愈，湿痰凝滞，脉络痹阻；或感染虫毒，阻滞脉道，气血不畅，脉络瘀阻；虚劳日久，或久泻、久痢之后，脾气虚弱，营血运行涩滞等，皆可导致积聚的形成。"}],"bingji":[{"t":"p","x":"积聚的基本病机为气机阻滞，瘀血内结。"},{"t":"p","x":"病变部位主要在于肝、脾，病久及肾。"},{"t":"p","x":"故积聚后期多表现为肝、脾、肾三脏功能失调。"},{"t":"p","x":"本病初起，气滞血瘀，邪气壅实，正气未虚，多属实；积聚日久，病势较深，正气耗伤，可转为虚实夹杂之证；病至后期，气血衰少，体质赢弱，则往往转变为正虚为主。"},{"t":"p","x":"同时因寒、湿、热、痰、食滞、虫积或病后体虚等致病因素之间往往互为因果，多因复合，或因实致虚，或因虚致实，气血津液运行失常，导致气滞血瘀结成积聚，故气滞、血瘀、痰结是形成积聚的主要病理因素。"},{"t":"p","x":"积聚的病机转化，如聚证日久不愈，由气入血，可转化成积证。"},{"t":"p","x":"癥积日久，瘀阻气滞，聚湿生痰，耗伤正气，因实致虚，可导致气虚、血虚，甚或气阴双亏。"},{"t":"p","x":"故积聚与黄疸、鼓胀、血证、癌病等病证有较密切的关系。"}],"zhenduan":[{"t":"ol","items":["1. 腹内结块，或胀或痛为本病的主要症状。","2. 聚证以腹中气聚，聚散无常，聚时结块，散则无形，攻窜胀痛，以胀为主，痛无定处，时作时止为临床特征。","3. 积证以腹内积块，触之有形，固定不移，以痛为主，痛有定处为临床特征。","4. 本病常有情志抑郁、饮食不节、外邪侵袭，或黄疸、胁痛、虫毒、久疟、久泻、久痢、虚劳等病史。"]}],"jianbie":[{"t":"b","x":"1. 胃痞"},{"t":"p","x":"积聚与胃痞均可因情志失调而导致气滞痰阻，出现腹部胀满等症，但胃痞是指自觉脘腹部痞塞胀满，而外无形征可见，更无包块可及，其病变部位主要在胃，而积聚除腹部胀满外，更有聚证发时有形可见，积证可扪及腹内积块，其病变部位重在肝、脾。"},{"t":"b","x":"2. 鼓胀"},{"t":"p","x":"两者均可出现腹满等症，积聚的基本病机为肝脾气机阻滞，瘀血内结，而鼓胀的基本病机主要为肝、脾、肾三脏受损，气滞、血瘀、水停腹中。"},{"t":"p","x":"鼓胀虽同见腹部胀大，但触之常未见有形肿块，常伴水液停聚。"},{"t":"p","x":"积聚迁延日久可转化为鼓胀。"}],"bianzheng":[{"t":"b","x":"1. 辨积与聚"},{"t":"p","x":"积聚虽常相兼为患，然病机、主症皆有不同。聚证病在气分，多属于腑，病机以气机逆乱为主，腹内结块虽望之有形，但按之无块，聚散无常，痛无定处，病程较短，病情一般较轻，治疗较易；积证则病在血分，多属于脏，病机以痰凝血瘀为主，腹内结块望之无形，但触之有积块，固定不移，痛有定处，病程较长，病情一般较重，治疗较难。"},{"t":"b","x":"2. 辨积证分期"},{"t":"p","x":"积证在临床上可分为初、中、末三期。初期正气尚盛，邪气虽实而不盛，表现为积块形小，按之不坚；中期正气已虚，邪气渐甚，表现为积块增大，按之较硬；末期正气大伤，邪盛已极，表现为积块明显，按之坚硬。辨积证初、中、末三期，可知正邪之盛衰，从而选择攻补之法。"},{"t":"b","x":"3. 辨部位"},{"t":"p","x":"积块的部位不同，标志着所病的脏腑不同，临床症状、治疗方药也不尽相同，故有必要加以鉴别。如右胁腹内积块，伴见胁肋刺痛、黄疸、纳差、腹胀等症状者，病在肝；左胁腹积块，伴见患处胀痛、疲乏无力、出血者，病在肝脾；胃脘部有积块，并伴见反胃、呕吐、呕血、黑便等症状者，病在胃；腹部积块伴便秘或腹泻、消瘦乏力或便下脓血者，病在肠。"},{"t":"b","x":"4. 辨标本缓急"},{"t":"p","x":"在积聚的病程中，由于病情的发展，常可出现一些危急重症。如出现血热妄行、气不摄血或瘀血内积而吐血、便血；因胃失和降，胃气上逆而剧烈呕吐；因肝胆郁滞，胆汁外溢而出现黄疸等。这些证候对积聚本病而言，属于标，应按照急则治其标或标本兼顾的原则及时处理。"}],"zhize":"聚证病在气分，重在调气，以疏肝理气、行气消聚为基本治则；积证病在血分，重在活血，以活血化瘀、软坚散结为基本治则。要注意依据病情发展、病机演变，区分不同阶段，适当调整攻补策略。如积证初期属邪实，应予消散之法；中期邪实正虚，予攻补兼施；后期以正虚为主，应予扶正消积。明·李中梓《医宗必读·积聚》指出：“初者，病邪初起，正气尚强，邪气尚浅，则任受攻；中者，受病渐久，邪气较深，正气较弱，任受且攻且补；末者，病魔经久，邪气侵凌，正气消残，则任受补。”","syndrome":[{"id":"s192","name":"肝郁气滞证","label":"1.肝郁气滞证","group":"","clinic":"腹中气聚，攻窜胀痛，时聚时散，脘胁之间时或不适，常随情绪波动而起伏，舌淡红，苔薄，脉弦。","analysis":"肝失疏泄，气机阻滞，故腹中气聚，攻窜胀痛；气聚则成形，气散则形消，故时聚时散；肝气郁结，横逆犯胃，脘胁气机不畅，故脘胁之间时或不适，症状常随情绪波动而起伏；舌淡红，苔薄，脉弦，为肝郁气滞之象。","treat":"疏肝解郁，行气散结。","formulaRaw":"逍遥散（《太平惠民和剂局方》）加减。","formulaName":"逍遥散加减","fangjie":"柴胡、当归、白芍、薄荷疏肝解郁；白术、茯苓、煨生姜、炙甘草益气健脾。若兼瘀象者，加延胡索、莪术；兼有热象者，加左金丸。寒湿中阻，脘腹痞满，舌苔白腻者，可用木香顺气散。"},{"id":"s193","name":"食滞痰阻证","label":"2.食滞痰阻证","group":"","clinic":"腹胀或痛，腹部时有条索状物聚起，重按则胀痛更甚，便秘，纳呆，舌苔腻，脉弦滑。","analysis":"食积内停，痰湿阻滞，气机不畅，故腹胀或痛；食痰互结，聚而成形，故腹部时有条索状物聚起，重按胀痛更甚；脾胃运化失职，大肠传导失常，故纳呆，便秘；舌苔腻，脉弦滑，为食滞痰阻之象。","treat":"导滞通便，理气化痰。","formulaRaw":"六磨汤（《世医得效方》）加减。","formulaName":"六磨汤加减","fangjie":"大黄、枳壳、槟榔攻积导滞，通腑泻下；沉香、木香、乌药疏肝行气，理气导滞。若痰浊中阻，呕恶苔腻者，加半夏、陈皮、生姜；痰湿较重，兼有食滞，腑气虽通，苔腻不化者，加苍术、厚朴；兼脾虚，便溏纳差者，加党参、白术、炒麦芽；因蛔虫结聚，阻于肠道而引起者，可配服乌梅丸。\n2. 积证"},{"id":"s194","name":"气滞血阻证","label":"1.气滞血阻证","group":"","clinic":"积块软而不坚，固定不移，胁肋疼痛，脘腹痞满，舌暗，苔薄白，脉弦。","analysis":"气滞血瘀，脉络阻滞，积而成块，初起邪浅，故积块软而不坚；瘀血内停，凝聚不散，故固定不移，胁肋疼痛，脘腹痞满；舌暗，苔薄白，脉弦，均为气滞血阻之象。","treat":"理气活血，通络消积。","formulaRaw":"柴胡疏肝散（《医学统旨》）合失笑散（《太平惠民和剂局方》）加减。前方侧重于疏肝行气，后方偏于活血止痛。","formulaName":"柴胡疏肝散合失笑散加减","fangjie":"柴胡、香附、川芎疏肝行气；陈皮、枳壳理气行滞；芍药、甘草养血柔肝；蒲黄、五灵脂活血散瘀。兼有烦热、口干、舌红、脉细弦者，加丹皮、山栀、黄芩等；气滞血阻较甚，兼有寒象者，可用大七气汤，或加肉桂、吴茱萸、当归等；兼湿热壅积者，可合小温中丸等。"},{"id":"s195","name":"瘀血阻络证","label":"2.瘀血阻络证","group":"","clinic":"腹部积块明显，硬痛不移，消瘦乏力，纳差，时有寒热，面色晦暗黧黑，面、颈、胸、臂或有血痣赤缕，女子可见月事不下，舌质紫暗或有瘀点，脉细涩。","analysis":"瘀血日久内结，气血凝滞，故积块明显，硬痛不移；瘀结成块，正气渐损，脾运不健，生化乏源，故见消瘦乏力，纳差，面色晦暗黧黑；瘀血久郁，营卫失调，故时有寒热；瘀血阻络，血不循经，故面、颈、胸、臂或有血痣赤缕；瘀血内结，胞脉阻滞，故女子月事不下；舌质紫暗或有瘀点，脉细涩，为瘀血阻络之象。","treat":"祛瘀软坚，健脾益气。","formulaRaw":"膈下逐瘀汤（《医林改错》）加减。","formulaName":"膈下逐瘀汤加减","fangjie":"红花、桃仁、赤芍、牡丹皮活血通经；延胡索、川芎行瘀止痛；香附、乌药、枳壳调气疏肝；当归、五灵脂养血散瘀。痰瘀互结者，加白芥子、半夏、苍术，或合鳖甲煎丸。"},{"id":"s196","name":"正虚瘀积证","label":"3.正虚瘀积证","group":"","clinic":"积块坚硬，疼痛逐渐加剧，面色萎黄或黧黑，形脱骨立，饮食大减，神疲乏力，或呕血、便血、衄血，舌质淡紫，舌光无苔，脉细数或弦细。","analysis":"癥积日久，气血瘀结，故积块坚硬，面色黧黑，疼痛逐渐加剧；气血耗伤，中虚失运，机体失养，故面色萎黄，形脱骨立，饮食大减，神疲乏力；瘀血阻滞，血不循经，溢于脉外，故见呕血、便血、衄血；舌质淡紫，舌光无苔，脉细数或弦细，为正气亏虚、瘀血内滞之象。","treat":"补益气血，活血化瘀。","formulaRaw":"八珍汤（《正体类要》）合化积丸（《杂病源流犀烛》）加减。前方侧重于补气养血，后方偏于化瘀消积。","formulaName":"八珍汤合化积丸加减","fangjie":"人参、白术、茯苓、甘草健脾益气；当归、白芍、熟地黄、川芎滋阴养血；三棱、莪术、香附、苏木、五灵脂、瓦楞子活血祛瘀；阿魏、雄黄消痞去积；海浮石化痰软坚散结；槟榔行气化滞。若阴伤较甚，头晕目眩，舌光无苔，脉象细数，加生地黄、玄参、枸杞子、石斛；牙龈出血，鼻衄者，加丹皮、白茅根、茜草、三七；畏寒肢肿，舌淡苔白，脉沉细者，加黄芪、附子（制）、肉桂、泽泻。"}],"linchuang":["抓住主证，确定治则。临证时，应遵循《素问·至真要大论》所谓“坚者削之”“结者散之”“留者攻之”“逸者行之”“衰者补之”法则，贯穿调气理血的基本大法。积聚各个证型往往兼有郁热、湿热、寒湿、痰浊等病理表现，临床常见湿热瘀毒郁结证。同时，对于正气亏虚，亦有气血阴阳虚损之不同，病性多为本虚标实。因此，临证应根据病理因素兼夹与复合的不同和阴阳气血亏虚的差异，采用扶正祛邪并举，复法制方。","明确病位，随证加减。积聚除按气血虚实辨证外，尚须根据结块部位、脏腑所属综合考虑，明确积聚的性质，并适时加减药物。若病位在胃肠，多加导滞通便、散结化瘀之品如大黄、枳实等；若病在肝胆，则可加用行气散结之品如柴胡、枳壳、姜黄等。在明确性质的基础上，根据积聚的病位，选用恰当的药物，对治疗和预后均有重要意义。","扶正为本，顾护脾胃。积聚的治疗始终要注意顾护正气，攻伐药物不可过用，如《素问·六元正纪大论》所言：“大积大聚，其可犯也，衰其大半而止。”聚证以实证居多，但如反复发作，脾气易损，此时需用香砂六君子汤加减，以培脾运中。积证系日积月累而成，其消亦缓，切不可急功近利。如过用、久用攻伐之品，易于损正伤胃；过用破血、逐瘀之品，易于损络出血；过用香燥理气之品，则易耗气伤阴，加重病情。要把握好攻与补的关系及主次轻重，注意“治实当顾虚”“补虚勿忘实”，可根据具体情况，或先攻后补，或先补后攻，或寓补于攻，或寓攻于补。","病证结合，杂合以治。在对积证的治疗中，可根据病情需要，选用不同治法或不同疗法，此即《素问·异法方宜论》所谓：“故圣人杂合以治，各得其所宜。”如祛邪消积可选用软坚之药和虫类药，以破瘀消积；配合外治法如敷贴阿魏膏、水红花膏等，有助于活血散结，软坚消积；部分积聚需要内科外科协同治疗，如积证转为癌病，更当综合治疗。"],"yufang":["本病的预防应注意饮食有节，起居有时，注意冷暖，调畅情志，使正气存内，则邪不可干。此外，在血吸虫病流行区域，要整治疫水，做好防护工作。","积聚患者，心理调护尤为重要，应当经常进行心理劝导，嘱患者心胸开阔，避免精神刺激，消除顾虑，保持心情舒畅。饮食上，要忌食肥甘厚味及辛辣刺激之品。注意保暖，以免寒湿损伤脾胃，凝滞气血。劳逸适度。另外，可适当配合外治法、针灸等进行治疗，有助于病情康复。"],"attachIds":[]},{"id":"d031","name":"鼓胀","kind":"main","parent":null,"chapterNo":"第三十四章","chapterName":"鼓胀","yinbing":[{"t":"p","x":"鼓胀病因复杂，主要是由酒食不节、虫毒感染、他病继发转化、情志刺激等因素引发，致肝、脾、肾俱损或功能失调，气血搏结，水湿内停。"},{"t":"b","x":"1. 酒食不节"},{"t":"p","x":"如嗜酒过度，或恣食肥甘厚味，酿湿生热，蕴阻中焦，壅滞气机，水谷精微失于输布，湿浊内聚，脾土壅滞，则肝之疏泄失常，气血郁滞，湿邪与气血交阻日久，便成鼓胀。"},{"t":"b","x":"2. 虫毒感染"},{"t":"p","x":"多因血吸虫感染，虫毒阻塞经隧，脉道不通，日久失治，肝脾两伤，形成癥积；气滞络瘀，清浊相混，水液停聚，乃成鼓胀。"},{"t":"b","x":"3. 他病继发"},{"t":"p","x":"他病损伤肝脾，致肝脾失调，水湿积聚者，均有继发鼓胀的可能，常见如黄疸、积聚等。黄疸日久，湿邪阻滞，肝脾受损，气滞血瘀，水停腹中，或癥积不愈，气滞血结，脉络壅塞，正气耗伤，痰瘀不化，水湿停聚等，终致鼓胀。"},{"t":"b","x":"4. 情志刺激"},{"t":"p","x":"忧思郁怒，损伤肝脾。肝为藏血之脏，性喜条达，若情志不舒，肝失疏泄，气机不利，则血液运行不畅，致肝脉瘀阻；肝气郁结，气机不畅，气不行水，或横逆犯脾胃，脾胃受克，运化失司，以致水湿停留，水湿与血瘀蕴结，日久不化，痞塞中焦，便成鼓胀。"}],"bingji":[{"t":"p","x":"鼓胀的基本病机主要为肝、脾、肾三脏受损，气滞、血瘀、水停于腹中。"},{"t":"p","x":"病变部位先在肝脾，久则及肾。"},{"t":"p","x":"病理因素无外乎气滞、血瘀、水液停聚。"},{"t":"p","x":"清·喻嘉言《医门法律·胀病论》云：“胀病亦不外水裹、气结、血凝。”"},{"t":"p","x":"病理性质总属本虚标实。"},{"t":"p","x":"初起，肝脾先伤，肝失疏泄，脾失健运，两者相因，乃致气滞湿阻，清浊相混，以实为主；进而，湿浊内蕴中焦，阻滞气机，可郁而化热，致水热蕴结，或因湿从寒化，出现水湿困脾之候；久则，气血凝滞，隧道壅塞，瘀结水留更甚。"},{"t":"p","x":"因肝、脾、肾三脏俱虚，运行蒸化水湿的功能更差，气滞、水停、血瘀三者错杂为患，壅结更甚，其胀日重，由于邪愈盛而正愈虚，故本虚标实，更为错综复杂，病势日益深重。"},{"t":"p","x":"鼓胀的病机演变复杂，如失治误治，或饮食不节，或服药不当，或劳倦过度，或正虚感邪等，每致变证多端。"},{"t":"p","x":"末期多见邪陷正虚，气阴耗竭，由闭转脱，病情极为险恶。"}],"zhenduan":[{"t":"ol","items":["1. 初期脘腹作胀，食后尤甚，叩之如鼓，继而腹部胀大如鼓，重者腹壁青筋显露，脐孔突起。","2. 常伴有乏力、纳差、尿少及齿衄、鼻衄、皮肤紫斑等出血现象，可见面色苍黄，皮肤或巩膜黄染，手掌股红，面颈胸部红丝赤缕、血痣及蟹爪纹。","3. 本病常有情志内伤、酒食不节、虫毒感染或黄疸、积聚久病不愈等病史。"]}],"jianbie":[{"t":"p","x":"要与肠蕈相鉴别。"},{"t":"b","x":"1. 肠蕈"},{"t":"p","x":"肠蕈与鼓胀均可见腹部胀大。"},{"t":"p","x":"肠蕈主要因湿热瘀毒流连肠道，阻滞气机而致，常见下腹部肿块，早期肿块局限，大如鸡卵，而后逐渐增大，可如怀胎之状，按之坚硬，推之可移，无水液波动感。"},{"t":"p","x":"肠蕈为慢性耗损性疾病，早期以实证居多，若不积极治疗，预后不佳。"},{"t":"p","x":"而鼓胀触之一般不见有形肿块，常伴水液停聚。"}],"bianzheng":[{"t":"ol","items":["1. 鼓胀早期"]},{"t":"b","x":"（1）辨病性"},{"t":"p","x":"腹部膨隆，腹皮绷急，按之空空然，叩之如鼓，喜太息、嗳气，嗳气或失气后胀减，口苦脉弦，病性偏于气滞；腹部胀大，状如蛙腹，按之如囊裹水，尿少肢肿，周身困乏无力，苔白腻者，病性偏寒湿；脘腹撑急，灼热口苦，小便短赤，大便秘结，苔黄腻者，病性偏湿热；腹大坚满，或脐心外突，脉络怒张，面色黧黑，面、胸、臂红痣血缕，手掌赤痕，舌质暗或有瘀斑，病性偏血瘀。"},{"t":"b","x":"(2)辨病位"},{"t":"p","x":"鼓胀主要涉及肝、脾、肾三脏。腹大胀满，按之不坚，胁部或胀或痛，攻窜不定者，病变在肝；腹大胀满，食少脘痞，四肢困重，疲倦无力者，病变在脾；腹大胀满，精神委顿，肢冷怯寒，下肢浮肿，尿少者，病变在肾。"},{"t":"ol","items":["2. 鼓胀晚期"]},{"t":"b","x":"(1）辨阴阳"},{"t":"p","x":"腹胀满不舒，朝宽暮急，面色苍黄，神疲乏力，四肢不温，舌淡紫，脉沉细者，病性偏阳虚；腹大胀满，心烦失眠，口燥，衄血，形体消瘦，小便短赤，舌红绛少津，脉弦细数者，病性偏阴虚。"},{"t":"b","x":"(2)辨危候"},{"t":"p","x":"鼓胀后期，常并发危重证候。如骤然大量呕血，血色鲜红，大便下血，暗红或油黑，伴手足震颤、狂躁、神志昏迷及尿闭，脉数不静或脉大弦紧者，证属浊毒闭窍，生风动血；若神志昏迷，烦躁不安，甚则怒目狂叫，四肢抽搐颤动，口臭便秘，溲赤尿少，舌红苔黄，脉弦滑者，证属痰热扰神；若神志昏迷，汗出肢冷，气促，撮空，两手抖动，脉细弱者，证属正气衰败，真阳欲脱之危候。"}],"zhize":"鼓胀的治疗以攻补兼施，祛邪不伤正，扶正不留邪为基本治则。初期一般以实证居多，治疗以祛邪为主，根据气滞、血瘀、水停之偏重，分别侧重于理气、活血、祛湿利水，或暂用逐水之法，同时配合健脾疏肝之品。后期一般以虚证为主，治疗以补虚为要，根据阴阳的不同，分别采用温补脾肾或滋养肝肾之法，同时配合行气活血利水。鼓胀后期伴有出血、昏迷、阳气虚脱等危重证候者，应“急则治其标”，予以迅速止血、开窍醒神、回阳固脱等急救法，病情稳定后，再从根本治疗。","syndrome":[{"id":"s197","name":"气滞湿阻证","label":"1.气滞湿阻证","group":"","clinic":"腹胀按之不坚，胁下胀满或疼痛，饮食减少，食后胀甚，得嗳气、矢气稍减，小便短少，舌淡红，苔薄白或白腻，脉弦。","analysis":"肝郁气滞，脾运不健，湿浊中阻，浊气充塞，故腹部胀满而不坚；肝失条达，络气痹阻，则胁下胀痛，得嗳气、矢气稍减；脾胃运化失健，则食少易胀；气壅湿阻，水道不利，故小便短少；舌淡红，苔薄白或白腻，脉弦，为气滞湿阻之象。","treat":"疏肝理气，运脾利湿。","formulaRaw":"柴胡疏肝散（《医学统旨》）合胃苓汤（《丹溪心法》）加减。前方以疏肝理气为主，后方以运脾利湿消胀为主。","formulaName":"柴胡疏肝散合胃苓汤加减","fangjie":"柴胡、枳壳、芍药、川芎、香附疏肝理气，宽中解郁；白术、猪苓、茯苓、泽泻健脾利水；桂枝辛通温阳，助膀胱之气化而增强利水之效；苍术、厚朴、陈皮理气除湿；甘草调和诸药。若胸脘痞闷，腹胀，噫气为快，气滞偏甚者，加佛手、沉香；尿少，腹胀，苔腻者，加砂仁、大腹皮、车前子；神倦，便溏，舌淡者，加党参、黄芪、附子（制）、干姜、川椒。"},{"id":"s198","name":"水湿困脾证","label":"2.水湿困脾证","group":"","clinic":"腹大胀满，按之如囊裹水，甚则颜面微浮，下肢浮肿，脘腹痞胀，得热则舒，精神困倦，怯寒懒动，小便少，大便溏，舌淡，苔白腻，脉缓。","analysis":"湿邪困遏，脾阳不振，寒水内停，故腹大胀满，按之如囊裹水；寒水相搏，中阳不运，则脘腹痞胀，得热稍舒，精神困倦，怯寒懒动，小便少，大便溏，下肢浮肿；舌淡，苔白腻，脉缓，为水湿困脾之象。","treat":"温中运脾，行气利水。","formulaRaw":"实脾散（《重订严氏济生方》）加减。","formulaName":"实脾散加减","fangjie":"白术、附子（制）、干姜振奋脾阳，温化水湿；厚朴、大腹皮、木香、草果行气运脾除湿；茯苓利水渗湿；木瓜化湿祛浊；甘草、生姜、大枣调和胃气。若浮肿较甚，小便短少，加肉桂、猪苓、车前子；胸闷咳喘，加葶苈子、苏子、半夏；胁腹痛胀，加郁金、香附、青皮、砂仁；脘闷纳呆，神疲，便溏，下肢浮肿，加党参、黄芪、山药。"},{"id":"s199","name":"湿热蕴结证","label":"3.湿热蕴结证","group":"","clinic":"腹大坚满，脘腹胀急，烦热口苦，渴不欲饮，小便赤涩，大便秘结或溏垢，舌边尖红，苔黄腻或兼灰黑，脉弦数。","analysis":"湿热壅盛，蕴结中焦，浊水内停，则腹大坚满，脘腹胀急；湿热上蒸，故烦热口苦，渴不欲饮；湿热下注，气化不利，则小便赤涩；湿热阻滞气机，传导失司，故见大便异常；舌边尖红，苔黄腻或兼灰黑，脉弦数，为湿热蕴结之象。","treat":"清热利湿，攻下逐水。","formulaRaw":"中满分消丸（《兰室秘藏》）加减。","formulaName":"中满分消丸加减","fangjie":"黄芩、黄连、泽泻、猪苓、茯苓清热利湿；厚朴、砂仁、枳实行气化湿；人参、甘草、白术培土制水；橘皮、姜黄行气燥湿；干姜、法半夏温中和胃降逆；知母滋阴清热。若热势较重，加连翘、龙胆草、半边莲、半枝莲；小便赤涩不利，加陈葫芦、蟋蟀粉；胁痛明显，加柴胡、川楝子；见面、目、皮肤发黄，合茵陈蒿汤。"},{"id":"s200","name":"肝脾血瘀证","label":"4.肝脾血瘀证","group":"","clinic":"脘腹坚满，青筋显露，胁下癥结痛如针刺，面色晦暗黧黑，或见赤丝血缕，面、颈、胸、臂出现血痣或蟹爪纹，口干不欲饮水，或见大便色黑，舌质紫暗或有紫斑，脉细涩。","analysis":"肝脾瘀结，隧道不通，水气停留，故腹大坚满，脉络怒张，胁腹刺痛；瘀热蕴阻下焦，病邪日深，入肾则面色晦暗黧黑，入血则赤丝血缕，面、颈、胸、臂出现血痣或蟹爪纹；络伤血溢，可见大便色黑；舌质紫暗或有紫斑，脉细涩，为血瘀之象。","treat":"活血化瘀，行气利水。","formulaRaw":"调营饮（《证治准绳》）加减。","formulaName":"调营饮加减","fangjie":"川芎、赤芍、大黄、莪术、延胡索、当归活血化瘀；瞿麦、槟榔、葶苈子、赤茯苓、桑白皮、大腹皮、陈皮行气利水；肉桂、细辛温经通阳，以助活血利水；白芷散结止痛；生姜、大枣、甘草调胃和中。若胁下癥积肿大明显，加土鳖虫、牡蛎；病久体虚，气血不足，或攻逐之后，正气受损、加黄芪、党参；大便色黑，加三七、茜草、侧柏叶；病势恶化，大量吐血、下血，或出现神志昏迷等危象，当辨阴阳之衰脱予以生脉注射液或参附注射液滴注。"},{"id":"s201","name":"脾肾阳虚证","label":"5.脾肾阳虚证","group":"","clinic":"腹大胀满，形似蛙腹，朝宽暮急，面色苍黄，或呈苍白，脘闷纳呆，神倦怯寒，肢冷浮肿，小便短少不利，舌体胖，质紫，苔淡白，脉沉细无力。","analysis":"脾肾阳虚，温运失常，水湿内聚，故腹大胀满不舒，入暮尤甚，脘闷纳呆，神倦怯寒，肢冷，小便短少，下肢浮肿；脾肾阳虚，则见面色苍黄或㿠白；舌体胖，质紫，苔淡白，脉沉细无力，为阳虚水盛之象。","treat":"温补脾肾，化气利水。","formulaRaw":"附子理苓汤（《内经拾遗》）加减。","formulaName":"附子理苓汤加减","fangjie":"附子（制）、干姜、人参、白术温补脾肾；茯苓、泽泻、猪苓利水消胀；桂枝通阳利水；甘草补脾益气。神疲乏力，少气懒言，食少腹胀，便溏者，加黄芪、山药、薏苡仁、扁豆；面色苍白，怯寒肢冷，腰膝酸冷，脉弱无力者，加肉桂、仙茅、淫羊藿；腹筋暴露者，加赤芍、泽兰、三棱、莪术。若腰膝酸重，肢肿，小便不利，痰饮咳喘者，用济生肾气丸。"},{"id":"s202","name":"肝肾阴虚证","label":"6.肝肾阴虚证","group":"","clinic":"腹大胀满，或见青筋暴露，面色晦滞，唇紫，口干而燥，心烦失眠，时或鼻衄，牙龈出血，小便短少，舌质红绛少津，苔少或光剥，脉弦细数。","analysis":"肝肾阴虚，津液失布，水湿内停，故腹大胀满，甚至青筋暴露，面色晦滞，小便短少；阴虚内热，热伤阳络，故心烦失眠，衄血；舌质红绛少津，苔少或光剥，脉弦细数，为虚热之象。","treat":"滋肾柔肝，养阴利水。","formulaRaw":"一贯煎（《续名医类案》）合六味地黄丸（《小儿药证直诀》）加减。前方侧重养阴柔肝，后方重在滋养肾阴。","formulaName":"一贯煎合六味地黄丸加减","fangjie":"熟地黄、山茱萸、山药滋养肝肾；茯苓、泽泻、丹皮淡渗利湿；生地黄、沙参、麦冬、枸杞子滋肾柔肝；当归、川楝子养血活血疏肝。若津伤，口干明显者，加石斛、玄参、芦根；青筋显露，唇舌紫暗，小便短少者，加丹参、益母草、泽兰、马鞭草；阴虚阳浮，耳鸣，面赤颧红者，加龟甲、鳖甲、牡蛎；湿热留恋不清，溲赤涩少者，加知母、黄柏、金钱草、茵陈；腹内积聚痞块，痛处不移者，加膈下逐瘀汤。\n2. 变证"},{"id":"s203","name":"黄疸","label":"（1）黄疸","group":"","clinic":"身目黄染如金，倦怠乏力，烦躁不宁，纳食欠佳或不欲食，恶心厌油，肝区胀痛，腹部膨隆，双下肢水肿，尿少如浓茶，大便溏，舌暗红，苔黄腻，脉弦滑。","analysis":"热毒壅滞肝胆，胆汁泛溢肌肤目窍，故身目黄染如金；湿困脾胃失运，致纳差恶心，便溏，倦怠乏力；热毒扰心则烦躁；壅滞肝络则肝区胀痛；湿热壅盛，蕴结中焦，浊水内停，则腹部膨隆，双下肢水肿；湿热下注膀胱，则尿少如浓茶；舌暗红，苔黄腻，脉弦滑，均为湿热瘀毒之象。","treat":"清热解毒，利湿退黄。","formulaRaw":"甘露消毒丹（《医效秘传》）加减。","formulaName":"甘露消毒丹加减","fangjie":"滑石、茵陈、黄芩利湿退黄；石菖蒲、藿香、白豆蔻、木通行气和中；连翘、射干、贝母、薄荷清热散结。若神志不清，目不识人者，加水牛角、郁金；气虚乏力，少气懒言者，加黄芪、党参、山药、白术；腹部胀大，小便不出者，加车前子、通草、猪苓、泽泻；湿困脾胃，便溏尿少，口中甜者，加厚朴、苍术；纳呆，无食欲者，加炒麦芽、鸡内金。临证可参见黄疸病证进行辨治。"},{"id":"s204","name":"出血","label":"（2）出血","group":"","clinic":"轻者可见牙龈出血、鼻衄或肤下瘀斑，重者病势突变，大量呕吐鲜血或大便下血，舌质红，苔黄，脉弦数。","analysis":"火热熏灼，瘀毒互结，热迫血溢，故见衄血、呕血、便血；舌质红，苔黄，脉弦数，为热盛动血之象。","treat":"泻火解毒，凉血止血。","formulaRaw":"犀角地黄汤（《备急千金要方》）加减。","formulaName":"犀角地黄汤加减","fangjie":"水牛角、生地黄泻火解毒；赤芍、丹皮凉血止血。若实热较甚者，加黄连、黄芩、黄柏、栀子；骤然大量呕血，血色鲜红，大便下血，暗红或油黑者，加三七、仙鹤草、地榆炭、大黄炭、白浆根、侧柏叶、茜草；大出血后，气随血脱，阳气衰微，汗出如珠，四肢厥冷，呼吸低微，脉细微欲绝者，用大剂独参汤加山茱萸；疾病后期，气阴两虚者，加沙参、西洋参、太子参、山药。临证可参见血证进行辨治。"},{"id":"s205","name":"神昏","label":"（3）神昏","group":"","clinic":"神昏谵语，昏不识人，发热，黄疸，烦躁不宁，口臭便秘，溲赤尿少，舌质红绛，苔黄燥，脉细数。","analysis":"邪热内陷，热毒互结，蒙蔽心窍，故神昏谵语，昏不识人；热毒内盛，内扰心神，则发热，烦躁不宁；热毒内结胃肠，壅滞下焦，故口臭便秘，溲赤尿少；舌红绛，苔黄燥，脉细数，为热毒内盛之象。","treat":"清热解毒，醒脑开窍。","formulaRaw":"清营汤（《温病条辨》）合安宫牛黄丸（《温病条辨》）加减。前方清热凉血，后方清热解毒开窍。","formulaName":"清营汤合安宫牛黄丸加减","fangjie":"水牛角、生地黄、玄参、麦冬清热凉血；金银花、连翘、竹叶凉营解毒；黄连、丹参凉血散瘀；安宫牛黄丸清热解毒，开窍镇惊。若痰浊壅盛，蒙蔽清窍，见神志昏迷较甚，静卧嗜睡，神情淡漠，舌苔厚腻者，加郁金、菖蒲；出血严重者，加大蓟、栀子炭、血余炭；痰涎壅盛，烦躁不安者，加竹沥、瓜蒌、胆南星；热动肝风而痉厥抽搐者，改用紫雪丹；痰浊偏盛而昏迷较重者，改用至宝丹；病情恶化，昏迷甚，汗出肤冷，气促，撮空理线，两手抖动，脉细微弱者，应急予生脉散、参附龙牡汤。"}],"linchuang":["鼓胀阳虚易治，阴虚难调。水为阴邪，得阳则化，故阳虚患者使用温阳利水药物，腹水较易消退。若是阴虚鼓胀，温阳易伤阴，滋阴又助湿，治疗颇为棘手。临证可选用甘寒淡渗之品，如沙参、麦冬、白茅根、茯苓、猪苓等药，以达到滋阴生津而不黏腻助湿的效果。此外，在滋阴药中少佐温化之品〔少量桂枝、附子（制)），既有助于通阳化气，又可防止滋腻太过。","逐水法应用。鼓胀患者病程较短，正气尚未过度消耗，而腹胀甚，腹水不退，尿少便秘，脉实有力者，酌情使用逐水法，以缓其苦急，减轻痛苦，缩短病程。主要适用于湿热蕴结和水湿困脾证。常用逐水方药如牵牛子粉、舟车丸、控涎丹、十枣汤等方。临床使用注意事项：①中病即止：在使用过程中，药物剂量不可过大，攻逐时间不可过久，遵循“衰其大半而止”的原则，以免损伤脾胃，引起昏迷、出血之变。②严密观察：服药时必须严密观察病情，注意药后反应，加强调护。一旦发现有严重呕吐、腹痛、腹泻者，即应停药，并进行相应处理。③明确禁忌证：鼓胀日久，正虚体弱，或发热，黄疸日渐加深，或有消化道溃疡，曾并发消化道出血，或见出血倾向者，均不宜使用。对正虚者，要先补后攻或攻补兼施。","疑难杂症，预后不良。鼓胀为古代中医“风、痨、鼓、膈”四大难症之一，因气、血、水互结，邪盛而正衰，表现为湿热瘀毒互结与肝脾肾虚损并见，治疗较为棘手。若病在早期，正虚不著，经适当调治，腹水可以消失，病情可趋缓解。如延至晚期，邪实正虚，腹水反复发生，病情不易稳定，则预后较差。","腹水消退后治疗。经过治疗，腹水可能消退，但此时肝、脾、肾正气未复，气滞血络不畅，腹水仍然可能再次出现，此时应抓住时机，疏肝健脾，活血利水，培补正气，以巩固疗效。若并发消化道出血、黄疸、神昏者，病情甚笃，应查明病情，配合现代医学方法及时处理。"],"yufang":["预防鼓胀发生，宜增强体质，避免与血吸虫疫水接触，注重保护胃气，忌饮酒及生冷寒凉。调节情志，起居有常，顺应四时。注意早期诊治，积极治疗黄疸、积聚等原发病，防止病邪传变。","鼓胀患者应避免情绪波动及精神刺激，注意卧床休息。腹水较多者可取半卧位，腹水明显而小便少者宜低盐饮食，寒湿证忌生冷，阳虚证可予腹部热敷，可配合外治法或针灸。后期兼见发热、大出血甚至昏迷者，应采取相应护理措施，防止正虚邪袭。"],"attachIds":[]},{"id":"d032","name":"瘿病","kind":"main","parent":null,"chapterNo":"第三十五章","chapterName":"瘿病","yinbing":[{"t":"p","x":"瘿病的发生主要是由情志内伤、饮食及水土失宜、体质因素等引起，肝郁则气滞，脾伤则气结，气滞则津停，脾虚则酿生痰湿，痰气交阻，血行不畅，则气、血、痰壅结而成本病。"},{"t":"b","x":"1. 情志内伤"},{"t":"p","x":"忿郁恼怒或忧愁思虑日久，肝气失于条达，气机郁滞，则津液不得正常输布，易于凝聚成痰，气滞痰凝，壅结颈前，则形成瘿病。"},{"t":"p","x":"《济生方·瘿瘤论治》云：“夫瘿瘤者，多由喜怒不节，忧思过度，而成斯疾焉。大抵人之气血，循环一身，常欲无滞留之患，调摄失宜，气凝血滞，为瘿为瘤。”"},{"t":"b","x":"2. 饮食水土失宜"},{"t":"p","x":"饮食失调，或居住在高山地区，水土失宜，一是影响脾胃的功能，使脾失健运，不能运化水湿，聚而生痰；二是影响气血的正常运行，致气滞、痰凝、血瘀壅结颈前则发为瘿病。"},{"t":"p","x":"《圣济总录》所谓的“泥瘿”即由此所致。"},{"t":"p","x":"《杂病源流犀烛·颈项病源流》云：“西北方依山聚涧之民，食溪谷之水，受冷毒之气，其间妇女，往往生结囊如瘿。”"},{"t":"p","x":"这些均说明瘿病的发生与水土因素有密切关系。"},{"t":"b","x":"3. 体质因素"},{"t":"p","x":"妇女以肝为先天，妇女的经、孕、产、乳等生理特点与肝经气血有密切关系，遇有情志、饮食等致病因素，常引起气郁痰结、气滞血瘀及肝郁化火等病理变化，故女性易患瘿病。另外，素体阴虚之人，痰气郁滞之后易于化火，更加伤阴，常使病程缠绵。"}],"bingji":[{"t":"p","x":"瘿病的基本病机是气滞、痰凝、血瘀壅结颈前。"},{"t":"p","x":"初期多为气机郁滞，津停痰聚，痰气搏结，日久则可引起血脉瘀阻，进而气、痰、瘀三者合而为患。"},{"t":"p","x":"病变部位主要在肝、脾，与心有关。"},{"t":"p","x":"病理性质以实证居多，久病由实致虚，可见气虚、阴虚等虚候或虚实夹杂之候。"},{"t":"p","x":"病理因素有气滞、痰凝、血瘀。"},{"t":"p","x":"如痰气郁结日久可化火，形成肝火亢盛证；"},{"t":"p","x":"气滞或痰气郁结日久，则深入血分，血液运行不畅，形成痰结血瘀之候。"},{"t":"p","x":"若肿块在短期内迅速增大，质地坚硬，结节高低不平者，可能恶变，预后不佳。"}],"zhenduan":[{"t":"ol","items":["1. 瘿病以颈前喉结两旁瘿肿结块为最基本的临床特征，望诊和触诊有助于本病的诊断。颈前肿块，可随吞咽动作而上下移动；初见如樱桃或指头大小，一般生长缓慢；大小程度不一，大者可如囊如袋；触之多柔软、光滑，病程日久则质地较硬，或可扪及结节。","2. 瘿病早期多无明显伴随症状，发生阴虚火旺的病机转化时，可见怕热、多汗、心悸、眼突、手抖、多食易饥、面赤、脉数，或有低热。瘿块发展较大时，可因压迫气管而引起胸闷、发憋、咳嗽。","3. 瘿病多发于女性，常有情志不舒或饮食不节病史，或发病有地域性特征。"]}],"jianbie":[{"t":"b","x":"1. 瘰疬"},{"t":"p","x":"瘰疬与瘿病均存在颈部肿块的临床表现，但瘿病的肿块在颈部前方，肿块一般较大。"},{"t":"p","x":"瘰疬的患病部位是在颈项的两侧或颌下，肿块一般较小，每个约黄豆大，数目多少不等。"},{"t":"b","x":"2. 瘿囊与瘿瘤"},{"t":"p","x":"瘿囊与瘿瘤均可表现为颈前肿块。"},{"t":"p","x":"但瘿囊颈前肿块较大，两侧比较对称，肿块光滑、柔软，主要病机为气郁痰阻，若日久兼瘀血内停者，局部可出现结节。"},{"t":"p","x":"而瘿瘤表现为颈前肿块偏于一侧，或一侧较大，或两侧均大，瘿肿大小如桃核，质较硬。"},{"t":"p","x":"病情严重者，肿块迅速增大，质地坚硬，表面高低不平。"},{"t":"p","x":"主要病机为气滞、痰结、血瘀。"}],"bianzheng":[{"t":"b","x":"1. 辨在气与在血"},{"t":"p","x":"颈前肿块光滑、柔软，属气郁痰阻，病在气分；病久肿块质地较硬，甚则质地坚硬，表面高低不平，属痰结血瘀，病在血分。"},{"t":"b","x":"2. 辨火旺与阴伤"},{"t":"p","x":"本病常表现为肝火旺盛及阴虚火旺之证。如兼见烦热，易汗，性情急躁易怒，眼球突出，手指颤抖，面部烘热，口苦，舌红苔黄，脉数者，为火旺；如见心悸不宁，心烦少寐，易出汗，手指颤动，两目干涩，头晕目眩，倦怠乏力，舌红，脉弦细数者，为阴虚。"}],"zhize":"瘿病的治疗以理气化痰、消瘿散结为基本治则。实证阶段，若气郁痰阻，病在气分，则应以理气疏郁、化痰消瘿为重；若进一步表现为痰结血瘀，瘿肿质地较硬及有结节者，应加重活血化瘀；虚证或虚实夹杂阶段，肝火旺盛者，应注意清肝泻火；火郁阴伤而表现为阴虚火旺者，以滋阴降火为主。","syndrome":[{"id":"s206","name":"气郁痰阻证","label":"1. 气郁痰阻证","group":"","clinic":"颈前喉结两旁结块肿大，质软不痛，颈部觉胀，胸闷，喜太息，或兼胸胁窜痛，病情常随情志波动，舌淡红，苔薄白，脉弦。","analysis":"气机郁滞，痰浊壅阻，凝结颈前，故颈前喉结两旁结块肿大，质软不痛，颈部觉胀；因情志不舒，肝气郁结，故胸闷，善太息，胸胁窜痛，且病情随情志波动；舌淡红，苔薄白，脉弦，为肝郁气滞之象。","treat":"理气疏郁，化痰消瘿。","formulaRaw":"四海舒郁丸（《疡医大全》)加减。","formulaName":"四海舒郁丸加减","fangjie":"昆布、海带、海藻、海螵蛸、海蛤粉化痰软坚，消瘿散结；青木香、陈皮疏肝理气。若肝气不疏明显而见胸闷、胁痛者，可加柴胡、枳壳、香附、延胡索、川楝子等；若咽部不适，声音嘶哑者，可加桔梗、牛蒡子、木蝴蝶、射干等。"},{"id":"s207","name":"痰结血瘀证","label":"2. 痰结血瘀证","group":"","clinic":"颈前喉结两旁结块肿大，按之较硬或有结节，肿块经久未消，胸闷，纳差，舌质暗或紫，苔薄白或白腻，脉弦或涩。","analysis":"痰气交阻，血脉瘀滞，搏结成瘿，故颈前喉结两旁结块肿大，且因气痰瘀壅结颈前，故瘿肿较硬，或有结节，经久不消；气郁痰阻，脾失健运，故见胸闷，纳差；舌质暗或紫，苔薄白或白腻，脉弦或涩，为内有痰湿及气滞血瘀之象。","treat":"理气活血，化痰消瘿。","formulaRaw":"海藻玉壶汤（《外科正宗》）加减。","formulaName":"海藻玉壶汤加减","fangjie":"海藻、昆布、海带化痰软坚，消瘿散结；青皮、陈皮疏肝理气；半夏、浙贝母、连翘、甘草理气化痰散结；当归、川芎、独活行气活血。若胸闷不舒，加郁金、香附、枳壳等；若郁久化火，烦热，舌红苔黄，脉数，加夏枯草、丹皮、玄参、栀子等；若结块较硬或有结节，加黄药子、三棱、莪术、露蜂房、僵蚕等；若结块坚硬且不可移，加土贝母、莪术、山慈菇、天葵子、半枝莲、犀（西）黄丸等。"},{"id":"s208","name":"肝火旺盛证","label":"3. 肝火旺盛证","group":"","clinic":"颈前喉结两旁轻度或中度肿大，一般柔软光滑，烦热，容易出汗，性情急躁易怒，眼球突出，手指颤抖，面部烘热，口苦，舌质红，苔薄黄，脉弦数。","analysis":"痰气交阻，气郁化火，壅结颈前，故颈前喉结两旁轻度或中度肿大，质地柔软光滑；郁而化火，肝火炽盛，故见烦躁易怒，烦热汗出，面部烘热，口苦；肝火上炎，风阳内盛，而见手指震颤，眼球突出；舌质红，苔薄黄，脉弦数，为肝火旺盛之象。","treat":"清肝泻火，消瘿散结。","formulaRaw":"栀子清肝汤（《类证治裁》）合消瘰丸（《医学心悟》）加减。前方清肝泻火，后方清热化痰，软坚散结。","formulaName":"栀子清肝汤合消瘰丸加减","fangjie":"柴胡疏肝解郁；栀子、丹皮清泻肝火；当归养血活血；白芍柔肝；牛蒡子散热利咽消肿；生牡蛎、浙贝母化痰软坚散结；玄参滋阴降火。若肝火旺盛，烦躁易怒，脉弦数，可加龙胆草、黄芩、青黛、夏枯草；若手指颤抖，可加石决明、钩藤、白蒺藜、天麻等；若胃热内盛，症见多食易饥，可加生石膏、知母。若火郁伤阴，阴虚火旺，症见烦热，多汗，消瘦乏力，舌红少苔，脉细数，可用二冬汤合消瘰丸加减。"},{"id":"s209","name":"心肝阴虚证","label":"4. 心肝阴虚证","group":"","clinic":"颈前喉结两旁结块或大或小，质软，病起较缓，心悸不宁，心烦少寐，易出汗，手指颤动，眼干，目眩，倦怠乏力，舌质红，苔少或无苔，舌体颤动，脉弦细数。","analysis":"气火郁结于颈前，故渐起痰肿；火盛伤阴，心阴亏虚，而见心悸不宁，心烦少寐；虚热日久，气阴两虚，可见倦怠乏力；心液不守则汗出；阴虚风动则指颤；肝阴虚，肝血不足，则眼干目眩；舌质红，苔少或无苔，舌体颤动，脉弦细数，为心肝阴虚之象。","treat":"滋阴降火，宁心柔肝。","formulaRaw":"天王补心丹（《校注妇人良方》）合一贯煎（《续名医类案》)加减。前方滋阴清热，宁心安神，后方养阴疏肝。","formulaName":"天王补心丹合一贯煎加减","fangjie":"生地黄、沙参、玄参、麦冬、天冬养阴清热；人参、茯苓益气宁心；当归、枸杞子养肝补血；丹参、酸枣仁、柏子仁、五味子、远志养心安神；川楝子疏肝理气。若虚风内动，手指及舌体颤抖，可加钩藤、白蒺藜、鳖甲、白芍等；若肾阴亏虚，耳鸣，腰酸膝软，可加龟甲、桑寄生、牛膝、女贞子等；若病久正气伤耗，精血不足，而见消瘦乏力，妇女月经量少或经闭，男子阳痿，可加黄芪、太子参、山茱萸、熟地黄、枸杞子、制首乌等。"}],"linchuang":["不同疾病阶段用药有所不同。瘿病早期出现眼突者，证属肝火痰气凝结，应治以化痰散结，清肝明目，药用夏枯草、生牡蛎、菊花、青葙子、蒲公英、石决明等。后期出现眼突者，为脉络涩滞，瘀血内阻所致，应治以活血散瘀，益气养阴，药用丹参、赤芍、泽兰、生牡蛎、山慈菇、黄芪、枸杞子、谷精草等。","谨慎应用含碘药物。许多消瘿散结的药物，如四海舒郁丸中的海带、海藻、海螵蛸、海蛤壳等含碘量都较高，临证时须注意。若患者确系碘缺乏引起的单纯性甲状腺肿大，此类药物可以大量使用；若属甲状腺功能亢进症，则使用时需慎重。","谨慎应用有毒药物。黄药子具有消瘿散结、凉血降火之功效，治疗痰结血瘀证和肝火旺盛证时可配合应用。但黄药子有小毒，长期服用对肝脏损害较大，必须慎用，用量一般不宜超过10g。"],"yufang":["预防瘿病发生，宜保持精神愉快，防止情志内伤，并针对水土因素调节饮食。在容易发生缺碘性甲状腺肿的地区，可经常食用海带，或采用碘化食盐预防。","瘿病患者应避免情绪波动及精神刺激，防止情志内伤。注意饮食适宜，劳逸适度。在病程中，要密切观察瘿肿的形态、大小、质地软硬及活动度等方面的变化。如瘿肿经治不消，增大变硬，应高度重视，防止恶变。"],"attachIds":[]},{"id":"d033","name":"疟疾","kind":"main","parent":null,"chapterNo":"第三十六章","chapterName":"疟疾","yinbing":[{"t":"b","x":"1. 感受疟邪"},{"t":"p","x":"夏秋暑湿当令之际，正是蚊毒疟邪肆虐之时，人体被疟蚊叮咬，疟邪侵入，这是致病的主要原因。"},{"t":"p","x":"《诸病源候论·山痰疟候》明确指出：“此病生于岭南，带山瘴之气。”"},{"t":"b","x":"2. 饮食所伤、起居失宜"},{"t":"p","x":"因饮食所伤，脾胃受损，痰湿内生；或起居失宜，劳倦太过，元气耗伤，营卫空虚，疟邪乘袭，即可发病。"}],"bingji":[{"t":"p","x":"疟疾的基本病机为疟邪入侵，伏于半表半里之间，内搏五脏，横连募原，出与营卫相搏，正邪相争则疟病发作；至正胜邪退，与营卫相离，疟邪伏藏则发作停止；当疟邪再次与营卫相搏时，则再次发作。"},{"t":"p","x":"休作时间的长短，与疟邪所伏深浅相关，每日一发或间日一发则邪伏尚浅，间二日一发即三日疟则邪伏较深，临床以间日一发最为常见。"},{"t":"p","x":"病变部位主要在少阳，所谓“疟不离少阳”。"},{"t":"p","x":"病理性质总体以邪实为主，日久常兼有气血亏虚之象。"},{"t":"p","x":"因疫毒热邪内盛，蒙蔽心神，则为热瘁；因瘴毒湿浊内盛，蒙蔽心神，则为冷瘴，为病情危重的表现。"},{"t":"p","x":"或久疟不愈，气血亏虚，痰瘀互结，结于胁下，则成疟母。"}],"zhenduan":[{"t":"ol","items":["1. 疟疾以周期性发作的寒战、发热、出汗为最基本的临床特征，在间歇期症状消失。","2. 疟疾发作时可伴头痛、周身酸痛、恶心呕吐；久疟者可见面色萎黄、消瘦乏力，甚至胁下出现痞块。可见脾大及贫血表现。","3. 多发于夏秋季节，有传染性及流行病学史，居住或近期到过疟疾流行地区，或近两周内有输血史。"]}],"jianbie":[{"t":"b","x":"1. 风温"},{"t":"p","x":"疟疾与风温初起均可表现为寒战发热。"},{"t":"p","x":"但疟疾以寒热往来、汗出热退、休作有时为特征，无肺系症状。"},{"t":"p","x":"风温初起，邪在卫分时，可见寒战发热，多伴有咳嗽、气急、胸痛等肺系症状；若邪热壅盛，转入气分，则卫分症状消失，可见壮热，有汗不解，兼见咳、口渴、烦躁、便秘等肺胃两经症状。"},{"t":"p","x":"风温多见于冬春季节，疟疾多发于夏秋季节。"},{"t":"b","x":"2. 淋证"},{"t":"p","x":"疟疾与淋证发热均可表现为寒战发热，但疟疾表现为周期性的寒热交替，而淋证发热多为持续性或伴寒战，多兼小便频急、滴沥刺痛、腰部酸胀疼痛等症，可与疟疾鉴别。"}],"bianzheng":[{"t":"b","x":"1. 辨寒热"},{"t":"p","x":"寒热休作有时，以周期性的寒战-高热-汗出-热退为发作特征，且寒热均等，为正疟。虽呈周期性发作，但热多寒少，或但热不寒，为温疟。而寒多热少，或但寒不热，为寒疟。"},{"t":"b","x":"2. 辨虚实"},{"t":"p","x":"正疟初起，邪盛正不虚，病属标实为主。疟疾迁延日久，耗伤气血，遇劳则发，为劳疟，或见正虚邪恋之候。疟疾久治不愈，痰浊瘀血互结于胁下，形成痞块，则为疟母。"},{"t":"b","x":"3. 辨病情轻重"},{"t":"p","x":"若发病急骤，病势凶险，伴神昏谵语或昏蒙嗜睡等神志异常者，为瘴疟，其中热重于湿，或湿从热化者为热瘴，而湿重于热，或湿从寒化，瘴毒湿浊壅闭于内者为冷瘴。"}],"zhize":"疟疾的治疗以祛邪截疟为基本治则，区别寒与热的偏盛进行辨治。温疟宜兼清，寒疟宜兼温，瘴疟宜解毒除瘴，劳疟则以扶正为主，疟母又当祛瘀化痰软坚。","syndrome":[{"id":"s210","name":"正疟","label":"1. 正疟","group":"","clinic":"寒战壮热，休作有时，先有呵欠乏力，继则寒栗鼓颔，寒罢则内外皆热，头痛面赤，口渴引饮，终则遍身汗出，热退身凉，舌红，苔薄白或黄腻，脉弦。","analysis":"疟邪侵入人体，伏于少阳，出入于营卫之间，故见寒战壮热，休作有时；邪正相争时，阴阳相移，阴盛阳衰，则寒栗鼓颔；正邪剧烈交争，阳气亢奋，故表现为高热，头痛面赤，口渴引饮；若正气能暂时战胜疟邪，疟邪伏藏，阳气得以宣泄，故汗出热退身凉；舌红，苔薄白或黄腻，脉弦，为邪郁少阳之象。","treat":"祛邪截疟，和解表里。","formulaRaw":"柴胡截疟饮（《医宗金鉴》）或截疟七宝饮（《杨氏家藏方》）加减。前方和解表里，导邪外出；后方偏重化痰散结，理气和中。","formulaName":"柴胡截疟饮或截疟七宝饮加减","fangjie":"柴胡、黄芩和解少阳；常山、草果、槟榔、半夏化痰截疟；生姜、大枣调和营卫；人参、山药益气健脾，扶正以祛邪；乌梅、桃仁活血化瘀消积；青皮、陈皮、厚朴燥湿健脾，理气化痰；甘草调和诸药。若口渴甚，可加葛根、石斛；若胸脘痞闷，苔腻，去参、枣，加苍术；若烦渴，苔黄，脉弦数，去参、姜、枣，加石膏、天花粉。"},{"id":"s211","name":"温疟","label":"2. 温疟","group":"","clinic":"热多寒少，汗出不畅，头痛，骨节酸痛，口渴引饮，便秘尿赤，舌红、苔黄、脉弦数。","analysis":"疟邪伏于半表半里，正邪交争剧烈，热邪内盛，故热多寒少；热邪内盛，耗伤津液，故汗出不畅，口渴引饮；热邪上扰清空，故头痛；热邪痹阻经络，气血运行不畅，郁而作痛，故见骨节酸痛；热移膀胱则尿黄，肠道失润则便干；舌红，苔黄，脉弦数，为热邪亢盛之象。","treat":"清热解表，和解祛邪。","formulaRaw":"白虎加桂枝汤（《金匮要略》)或白虎加人参汤（《伤寒论》）加减。前方清热生津，解肌发表；后方清热益气生津。","formulaName":"白虎加桂枝汤或白虎加人参汤加减","fangjie":"石膏、知母清泻里热，透热生津；人参、粳米益气生津，护胃安中；桂枝解肌发表；甘草益气缓急；可加柴胡清解少阳，青蒿、常山祛邪截疟。若表邪已解，里热较盛，发热，汗多，无骨节酸痛者，去桂枝；热势较盛而气津两伤者，去桂枝，加北沙参；若津伤较甚，口渴引饮，酌加生地黄、麦冬、石斛、玉竹。"},{"id":"s212","name":"寒疟","label":"3. 寒疟","group":"","clinic":"热少寒多，口不渴，神疲体倦，胸脘痞闷，苔白腻，脉弦。","analysis":"疟邪兼感寒邪，或素体阳虚，疟邪伏于半表半里，寒邪偏盛，故见热少寒多，口不渴；寒邪久伏，耗伤阳气，阳气虚衰，推动无力，故神疲乏力；寒邪犯胃，胃失和降，气机阻滞，故胸脘痞闷；舌苔白腻，脉弦，为寒湿内盛之象。","treat":"和解表里，温阳达邪。","formulaRaw":"柴胡桂枝干姜汤（《伤寒论》）合截疟七宝饮（《杨氏家藏方》)加减。前方和解表里，温阳达邪，后方截疟化痰，运脾和胃。","formulaName":"柴胡桂枝干姜汤合截疟七宝饮加减","fangjie":"柴胡、黄芩和解少阳；桂枝、干姜温阳达邪；瓜萎根清热生津；牡蛎软坚散结；甘草益气和中，调和诸药；常山、草果、槟榔驱虫截疟；青皮、陈皮、厚朴燥湿健脾，理气化痰。若汗出不畅，去牡蛎；但寒不热者，去黄芩；若寒郁日久化热，心烦口干，去桂枝、草果，加石膏、知母。"},{"id":"s213","name":"热瘴","label":"（1）热瘴","group":"瘴疟","clinic":"热甚寒微，或壮热不寒，头痛，肢体烦痛，面红目赤，胸闷呕吐，烦渴饮冷，大便秘结，小便热赤，甚至神昏谵语，舌质红绛，苔黄腻或垢黑，脉洪数或弦数。","analysis":"瘴毒热邪内陷，热毒炽盛，充斥表里，内扰心神，故见热甚寒微，或壮热不寒，神昏谵语；热毒之性蒸腾，循经上炎，上扰清空，痹阻经脉，故头痛，面红目赤，肢体烦痛；热毒炽盛，耗伤津液，故烦渴饮冷；热毒阻滞中焦，气机逆乱，故胸闷呕吐；热移膀胱则尿黄，肠道失润则大便秘结；舌质红绛，苔黄腻或垢黑，脉洪数或弦数，为热毒内盛之象。","treat":"解毒除瘴，清热保津。","formulaRaw":"清瘴汤（验方）加减。","formulaName":"清瘴汤加减","fangjie":"黄芩、黄连、知母、柴胡清热解毒除瘁；青蒿、常山祛邪截疟；竹茹、枳实、半夏、陈皮、茯苓清胆和胃化痰；益元散清利湿热。壮热烦渴者，去半夏，加生石膏；若热盛津伤，口渴心烦，舌红少津者，加生地黄、玄参、石斛、玉竹；若神昏谵语，则加紫雪丹或至宝丹。"},{"id":"s214","name":"冷瘴","label":"（2）冷瘴","group":"瘴疟","clinic":"寒甚热微，或但寒不热，或呕吐腹泻，甚则神昏不语，嗜睡昏蒙，舌淡，苔白厚腻，脉弦。","analysis":"瘴毒寒邪内陷，直中三阴，凝滞阳气，使阳气不能外达温煦肢体，故见寒甚热微，或但寒不热；寒湿瘴毒阻滞中焦，脾胃气机不畅，故呕吐腹泻；寒瘴浊邪，蒙蔽心窍，则神昏不语，嗜睡昏蒙；舌淡，苔白厚腻，脉弦，为寒湿内盛之象。","treat":"解毒除瘴，芳化湿浊。","formulaRaw":"加味不换金正气散（验方）加减。","formulaName":"加味不换金正气散加减","fangjie":"苍术、厚朴燥湿运脾；藿香、半夏、佩兰、菖蒲芳香化湿，醒脾开胃；荷叶化湿，升发清阳；陈皮行气理气，调和脾胃气机；草果、槟榔驱虫截疟；甘草调和诸药。若嗜睡昏蒙，神昏不语，加苏合香丸；若呕吐较甚，加玉枢丹。"},{"id":"s215","name":"劳疟","label":"5. 劳疟","group":"","clinic":"疟疾迁延日久，遇劳则发，寒热时作，倦怠乏力，短气懒言，纳少自汗，面色萎黄，形体消瘦，舌质淡，脉细无力。","analysis":"疟邪久羁，耗伤气血阴阳，故遇劳则发；邪恋不去，正邪时有交争，故寒热时作；脾虚气弱，运化失职，功能减退，则倦怠乏力，短气懒言，纳少；气虚卫气不固，津液外泄，故自汗；气血亏虚，不能充养形体、濡养肌肉，故面色萎黄，形体消瘦；舌质淡，脉细无力，为气血亏虚之象。","treat":"益气养血，扶正祛邪。","formulaRaw":"何人饮（《景岳全书》）加减。","formulaName":"何人饮加减","fangjie":"何首乌养血截疟；人参益气扶正；当归养血和营；陈皮、生姜理气和中，助补药之运行。疟疾发作之时，加青蒿、常山。若气虚、自汗显著，加黄芪、浮小麦；若午后或傍晚低热，偏于阴虚，舌质绛红，加生地黄、鳖甲、白薇；若胸闷脘痞，大便稀溏，苔浊腻，去何首乌，加半夏、草果。此外，久疟不愈，气机郁滞，血行不畅，痰浊瘀血互结于左胁之下，形成痞块，此即《金匮要略》所称之疟母，治宜软坚散结，祛瘀化痰，用鳖甲煎丸。若兼气血亏虚者，可配合八珍汤或十全大补汤治疗。"}],"linchuang":["病证结合，加用截疟中药。治疗本病可在辨证的基础方上，加用具有祛邪截疟作用的中药，如青蒿、常山、槟榔、马鞭草、豨签草、乌梅等，其中常山、槟榔等截疟药易伤正气，体虚者需配伍益气扶正药。青蒿宜鲜用或后下，以保留有效成分。现代研究证实，青蒿素类药物抗疟有特效，以青蒿类药物为基础的联合疗法已被世界卫生组织（WHO）向世界各国推荐用于疟疾的治疗，被评价为“目前世界范围内治疗恶性疟疾惟一真正有效的药物”。此外，服药时间一般以疟发前2小时为宜。若在疟发之际服药，容易发生呕吐不适，且难以控制发作。","重视扶正与祛邪主次。疟疾的发生多因外感疟邪，同时与人体正气强弱密切相关。发作期应以祛邪为主，兼顾扶正。休止期以扶正为主，兼以祛邪，重症或特殊类型应扶正与祛邪并重。","警惕危重症（瘴疟）。若出现高热不退、神昏谵语、抽搐厥脱等危重病情，需及时中西医结合抢救，中药可开窍醒神（如安宫牛黄丸、紫雪丹)，配合补液、抗休克等治疗。"],"yufang":["预防疟疾的关键在于避免蚊虫叮咬，尤其是在疟疾高发地区。睡觉时宜使用蚊帐，户外活动时宜穿长袖衣裤、涂抹驱蚊剂等。减少夜间户外活动。居住环境应保持清洁，消除积水，减少蚊虫滋生。应坚持锻炼，增强体质。","疟疾患者应注意休息，保持室内空气流通，避免受凉。应注意冷暖适宜，多饮开水，寒战加衣盖被，发热时减去衣被。若高热不退，可用物理降温，或针刺大椎、陶道、合谷等穴。瘴疟神志昏迷者，应密切观察其神志、瞳神、气息、脉象等情况。发作间歇期可适当进行户外运动，进食易于消化的食物，注意休息。"],"attachIds":[]},{"id":"d034","name":"水肿","kind":"main","parent":null,"chapterNo":"第三十七章","chapterName":"水肿","yinbing":[{"t":"b","x":"1. 风邪外犯"},{"t":"p","x":"风为六淫之首，风寒、风热或风湿之邪侵袭，肺气失于宣降，风水相搏，发为水肿。"},{"t":"p","x":"《景岳全书·肿胀》云：“凡外感毒风，邪留肌肤，则亦能忽然浮肿。”"},{"t":"b","x":"2. 疮毒内陷"},{"t":"p","x":"肌肤痈疡疮毒，火热内攻，损伤肺脾肾，致津液气化失常，发为水肿。"},{"t":"p","x":"《严氏济生方·水肿门》曰：“年少血热生疮，变为肿满，烦渴，小便少，此为热肿。”"},{"t":"b","x":"3. 水湿浸渍"},{"t":"p","x":"久居湿地，冒雨涉水，水湿内侵，困遏脾阳，脾胃失于健运，水无所制，发为水肿。"},{"t":"b","x":"4. 饮食失调"},{"t":"p","x":"饮食不节，过食生冷肥甘，或嗜食辛辣，久则湿热中阻，损伤脾胃，或因饮食不足、脾气失养，以致脾虚失运，水湿内停，发为水肿。"},{"t":"b","x":"5. 体虚劳倦"},{"t":"p","x":"先天禀赋薄弱，肾气亏虚，膀胱开阎不利，气化失常，水泛肌肤，发为水肿。或因久病体虚，劳倦过度，纵欲无节，生育过多，久病产后，损伤脾肾，以致脾失健运，肾失气化，水湿输布失常，发为水肿。"}],"bingji":[{"t":"p","x":"水肿的基本病机是肺失通调，脾失转输，肾失开阎，三焦气化不利，以致水液积聚，泛溢肌肤。"},{"t":"p","x":"病变部位主要在肺、脾、肾三脏，关键在肾。"},{"t":"p","x":"先天禀赋不足，或久病劳倦，损及肾脏，则肾失蒸化，开阖不利，水液泛溢肌肤，则为水肿。"},{"t":"p","x":"《景岳全书·肿胀》云：“盖水为至阴，故其本在肾；水化于气，故其标在肺；水惟畏土，故其制在脾。今肺虚则气不化精而化水，脾虚则土不制水而反克，肾虚则水无所主而妄行。”"},{"t":"p","x":"水肿的病理性质有阳水、阴水之分，二者之间可发生病机转化或兼夹。"},{"t":"p","x":"病理因素有风邪（风寒、风热及风湿）、疮毒、水湿、湿热、气滞、瘀血等。"},{"t":"p","x":"阳水迁延不愈，反复发作，正气渐衰，脾肾阳虚，或因失治、误治，损伤脾肾，阳水可转为阴水。"},{"t":"p","x":"水肿久病不愈或失治误治，可导致肺、脾、肾三脏功能严重受损，后期还可影响到心、肝。"},{"t":"p","x":"若水湿蕴久成浊，浊邪阻闭三焦，阻滞气机升降出入，则终成关格、呕逆危候。"}],"zhenduan":[{"t":"ol","items":["1. 水肿先从眼睑或下肢开始，继及四肢全身。","2. 轻者仅眼睑或足胫浮肿，重者全身皆肿，甚则腹大胀满，气喘不能平卧，更严重者可见尿闭或尿少，恶心呕吐，口有秽味，鼻衄牙宣，头痛，抽搐，神昏谵语等危象。","3. 水肿发病可急可缓。阳水，尤其是风水发病急，病程短，多发生于青少年；阴水多隐匿发病，病程长，常发生于久病体虚者。","4. 常因外感、疮毒、饮食失调、劳欲过度等诱发，或继发于紫斑、痹证、消渴病等。"]}],"jianbie":[{"t":"p","x":"主要与鼓胀相鉴别。"},{"t":"p","x":"水肿与鼓胀均可见四肢水肿，腹部膨隆。"},{"t":"p","x":"鼓胀的主症是单腹胀大，面色苍黄，腹壁青筋暴露，四肢多不肿，反见瘦削，后期或可伴见轻度肢体浮肿。"},{"t":"p","x":"而水肿则头面或下肢先肿，继及全身，面色㿠白，腹壁亦无青筋暴露。"},{"t":"p","x":"鼓胀是由于肝、脾、肾功能失调，导致气滞、血瘀、水湿聚于腹中。"},{"t":"p","x":"水肿乃肺、脾、肾三脏气化失调，而导致水液泛溢肌肤。"}],"bianzheng":[{"t":"b","x":"1. 辨阳水阴水"},{"t":"p","x":"阳水多由感受外邪、疮毒、水湿而致。阳水发病较急，每成于数日之间，浮肿由面目开始，自上而下，继及全身，肿处皮肤绷急光亮，按之凹陷，身热烦渴，小便短赤，大便秘结，脉滑有力，多为实证、热证，可见表证。阴水多因饮食失调、体虚劳倦，或阳水失治、误治转化所致。阴水发病缓慢，浮肿由足踝开始，自下而上，继及全身，肿处皮肤松弛，按之凹陷不易恢复，甚则按之如泥，畏寒，不渴，小便少但不赤涩，大便溏薄，脉沉细无力，多为虚证、寒证、里证。"},{"t":"b","x":"2. 辨病邪性质"},{"t":"p","x":"水肿以头面为主，恶风头痛者，多属风；水肿以下肢为主，纳呆身重者，多属湿；水肿伴有咽痛、溲赤者，多属热；因疮痍、烂喉丹痧而致水肿者，多属疮毒；水肿病情反复，伴肢节疼痛、伸屈不利者，多为风湿；水肿病势缠绵，伴腰腿酸困，大便不爽，小便黄赤者，多为湿热。"},{"t":"b","x":"3. 辨病变脏腑"},{"t":"p","x":"若颜面水肿突出，伴咽痛、咳嗽，或水肿较甚，咳喘胸闷者，病变部位多在肺；身体困重，脘腹满闷而食少，苔腻者，病变部位多在脾；水肿反复，腰以下尤甚，伴腰膝酸软者，病变部位多在肾；水肿下肢明显，伴心悸、胸闷气短，甚则不能平卧者，病变多累及心。久病者可见多脏同病。"},{"t":"b","x":"4. 辨标本虚实"},{"t":"p","x":"水肿初起标实证为多，久病则多虚实夹杂，常表现为本虚标实之证。年轻体壮，病程短，发病迅速，肿势急剧，咽喉肿痛或皮肤疮疡，小便短赤或不通，大便秘结，多属实；年老体衰，病程长，浮肿按之如泥，畏寒肢冷，腰膝酸软，小便清长，大便稀溏，多属虚。阳水病久，或失治、误治形成阴水，由实转虚；阴水复感外邪而致水肿加剧，则兼夹阳水证候，属本虚标实。"}],"zhize":"发汗、利尿、泻下逐水为治疗水肿的三条基本原则，具体应用视阴阳虚实不同而异。阳水以祛邪为主，应予发汗、利水或攻逐，同时配合祛风、解毒、行气、活血等法；阴水当以扶正为主，健脾温肾，同时配以补气、养阴、利水、活血等法。对于虚实夹杂者，当视病情标本缓急，或攻补兼施，或先攻后补，不可见水利水，切忌草率攻下。","syndrome":[{"id":"s216","name":"风水相搏证","label":"1.风水相搏证","group":"","clinic":"眼睑浮肿，继则四肢及全身皆肿，来势迅速，可兼恶寒，发热，肢节酸楚，小便不利等症。偏于风热者，伴咽喉红肿疼痛，舌质红，苔薄黄，脉浮滑数。偏于风寒者，兼恶寒，咳喘，舌淡，苔薄白，脉浮滑或浮紧。","analysis":"风邪袭表，营卫失和，内舍于肺，肺失宣降，不能通调水道，下输膀胱，则恶寒、发热，肢节酸楚，小便不利，全身浮肿；风为阳邪，其性轻扬，善行数变，风水相搏，故水肿起于而目，迅即遍及全身；若风邪兼热，则咽喉红肿热痛，舌质红，苔薄黄，脉浮滑数；若风邪兼寒，邪在肌表，卫阳被遏，肺气不宣，则恶寒，咳喘，舌淡，苔薄白，脉浮滑或浮紧。","treat":"疏风清热，宣肺行水。","formulaRaw":"越婢加术汤（《金匮要略》）加减。","formulaName":"越婢加术汤加减","fangjie":"麻黄、杏仁、防风、浮萍疏风宣肺；白术、茯苓、车前子淡渗利水；石膏、桑白皮、黄芩清热宣肺。若风热偏盛，加银花、连翘、桔梗、板蓝根、鲜芦根，或用银翘散加减；风寒偏盛，去石膏，加苏叶、荆芥、防风，或用荆防败毒散加减；夹有风湿，肢体关节疼痛，屈伸不利者，加羌活、独活、穿山龙，或用羌活胜湿汤加减；一身悉肿，胸闷腹满，小便不利，加猪苓、大腹皮。"},{"id":"s217","name":"湿毒浸淫证","label":"2.湿毒浸淫证","group":"","clinic":"眼睑浮肿，延及全身，皮肤光亮，尿少色赤，身发疮痰，甚则溃烂，恶风发热，舌质红，苔薄黄，脉浮数或滑数。","analysis":"肌肤疮痍，湿毒未能及时清解消散，内归脏腑，使脾胃不能运化水湿，失其升清降浊之能，使肺不能通调水道，而小便不利，眼睑浮肿，延及全身；风为百病之长，故病之初起多兼风邪，有恶风发热之象；舌质红，苔薄黄，脉浮数或滑数，为风邪夹湿毒之象。","treat":"宣肺解毒，利湿消肿。","formulaRaw":"麻黄连轺赤小豆汤（《伤寒论》）合五味消毒饮（《医宗金鉴》）加减。前方宣肺利湿，后方清热解毒。","formulaName":"麻黄连轺赤小豆汤合五味消毒饮加减","fangjie":"麻黄、杏仁、桑白皮、赤小豆宣肺利水；金银花、连翘、野菊花、蒲公英、紫花地丁、紫背天葵清热解毒；丹参凉血活血。脓肿毒甚者，重用蒲公英、紫花地丁；疮痍糜烂流水者，加土茯苓、草、石韦、苦参；皮肤瘙痒者，加白鲜皮、地肤子、蝉蜕、白蒺藜；疮疡色红肿痛或小便红赤者，加丹皮、赤芍、生地黄、泽兰；大便不通者，加大黄、葶苈子。"},{"id":"s218","name":"水湿浸渍证","label":"3.水湿浸渍证","group":"","clinic":"起病缓慢，病程较长，全身水肿，下肢为甚，按之没指，小便短少，身体困重，胸闷，纳呆，泛恶，舌淡，苔白腻，脉沉缓。","analysis":"湿为黏腻之邪，不易骤化，故起病缓慢，病程较长。水湿之邪，浸渍肌肤，壅滞不行.以致肢体浮肿不退；水湿内聚，三焦决渎失司，膀胱气化失常，故见小便短少；水湿日增而无出路，横溢肌肤，则肿势日甚，按之没指；水湿之邪下趋，故肿以下肢为甚；脾为湿困，阳气不得舒展，可见身重，胸闷，纳呆，泛恶；舌淡，苔白腻，脉沉缓，为湿盛脾弱之象。","treat":"运脾化湿，通阳利水。","formulaRaw":"五皮饮（《三因极一病证方论》）合胃苓汤（《丹溪心法》）加减。前方理气化湿利水，后方通阳利水，燥湿运脾。","formulaName":"五皮饮合胃苓汤加减","fangjie":"桑白皮、陈皮、大腹皮、茯苓皮、生姜皮化湿行水；苍术、厚朴、陈皮、草果燥湿健脾；桂枝、白术、茯苓、猪苓通阳化气行水。若外感风邪，肿甚而喘，加麻黄、杏仁、苏叶；面肿，胸满，不得卧，加苏子、葶苈子；湿困中焦，脘腹胀满，加椒目、大腹皮、砂仁、木香、槟榔；三焦气机不利，胸闷腹胀，小便不利，一身尽肿，用导水茯苓汤加减；夹有郁热，口苦咽干，头晕，胸胁满闷者，合柴苓汤加减。"},{"id":"s219","name":"湿热壅盛证","label":"4.湿热壅盛证","group":"","clinic":"遍体浮肿，皮肤绷急光亮，胸脘痞闷，烦热口渴，小便短赤，或大便干结，舌红，苔黄膩，脉沉数或濡数。","analysis":"水湿之邪，郁而化热，或湿热之邪壅于肌肤之间，则遍身浮肿，皮肤绷急光亮；湿热壅滞，气机升降失常，则胸脘痞闷；热盛消耗津液，则见烦渴，小便短赤，大便干结；舌红，苔黄腻，脉沉数或濡数，为湿热之象。","treat":"分利湿热。","formulaRaw":"疏凿饮子（《济生方》)加减。","formulaName":"疏凿饮子加减","fangjie":"羌活、秦艽、防风、大腹皮、茯苓皮、生姜皮疏风解表，发汗消肿；猪苓、茯苓、土茯苓、石韦、半枝莲、白花蛇舌草、白木通、椒目、赤小豆清利湿热，利尿消肿；槟榔、大黄通便逐水消肿。若腹满不减，大便不通，合已椒劳黄丸；肿势严重，兼见喘促不得平卧，加葶劳子、桑白皮；肢体关节肿痛，或屈伸不利，加青风藤、独活、威灵仙等；湿热久羁，化燥伤阴，口燥咽干，腰膝酸软，五心烦热，加生地黄、知母、黄柏、白茅根、芦根；严重水肿，体质壮实，必要时用甘遂、莞花、大戟等，注意中病即止，或边攻边补，或攻补结合。\n2. 阴水"},{"id":"s220","name":"脾阳亏虚证","label":"1.脾阳亏虚证","group":"","clinic":"身肿日久，腰以下为甚，按之凹陷不易恢复，脘腹胀闷，纳减便溏，面色不华，神疲乏力，四肢倦怠，小便短少，舌质淡或胖，苔白腻或白滑，脉沉缓或沉弱。","analysis":"脾虚失运，中阳不足，气不化水，以致下焦水邪泛滥，故身肿，腰以下为甚，按之凹陷不易恢复；脾虚运化乏力，故脘闷纳减，腹胀便溏；脾虚气血不足，故面色萎黄；阳不温煦，则神疲肢冷；阳不化气，则水湿不行，小便短少；舌质淡或胖，苔白腻或白滑，脉沉缓或沉弱，为脾阳亏虚之象。","treat":"健脾温阳，行气利水。","formulaRaw":"实脾散（《济生方》）加减。","formulaName":"实脾散加减","fangjie":"干姜、附子（制）、草果、桂枝温阳利水；白术、炙甘草、生姜、大枣健脾补气；茯苓、泽泻、车前子、木瓜利水消肿；木香、厚朴、大腹皮理气行水。肾气不固，腰酸腰痛，尿有余沥，舌淡胖，脉沉者，加芡实、枸杞子、菟丝子、山茱萸等，或配合五子衍宗丸、水陆二仙丹。若肺脾气虚，自汗易感，乏力体倦者，用防已黄芪汤加减；小便短少，用防已茯苓汤加减。"},{"id":"s221","name":"肾阳衰微证","label":"2.肾阳衰微证","group":"","clinic":"水肿反复消长不已，面浮身肿，腰以下甚，按之凹陷不起，尿量减少或反多，腰酸冷痛，四肢厥冷，怯寒神疲，面色㿠白，甚者心悸胸闷，喘促难卧，腹大胀满，舌质淡胖，苔白，脉沉细或沉迟无力。","analysis":"肾阳虚衰，开阎、蒸腾失司，阴盛于下，水湿潴留难去，而致水肿反复消长不已，面浮身肿，腰以下为著，往往按之凹陷久久不复；肾阳虚，则腰酸冷痛，四肢厥冷，怯寒神疲；舌质胖淡，苔白，脉沉细或沉迟无力，皆为阳虚水盛之候。","treat":"温肾助阳，化气行水。","formulaRaw":"济生肾气丸（《严氏济生方》）合真武汤（《伤寒论》）加减。前方温补肾阳，后方温阳利水。","formulaName":"济生肾气丸合真武汤加减","fangjie":"附子（制）、肉桂、巴戟天、淫羊藿温补肾阳；熟地黄、山萸肉、山药补肾摄精；白术、茯苓、猪苓、牛膝、车前子通利小便。若肾气不固，夜尿频多，去车前子，加芡实、菟丝子、补骨脂；肾虚肝旺，头昏头痛，心慌腿软，加鳖甲、牡蛎、杜仲、桑寄生、菊花、夏枯草，或用建瓴汤加减。肾阳亏虚，水肿久治不愈，神疲乏力，腰膝酸冷，夜尿频多，舌淡胖，脉沉细，用右归丸加减；肾阴亏虚，水肿反复发作，精神疲惫，腰酸遗精，咽干口渴，五心烦热，舌质红，脉细弱，用左归丸加减。"},{"id":"s222","name":"瘀水互结证","label":"3.瘀水互结证","group":"","clinic":"水肿迁延不退，肿势轻重不一，四肢或全身浮肿，以下肢为主，皮肤瘀斑，腰部刺痛，或伴血尿，或妇女月经不调，经血色暗，有血块，肌肤甲错，舌紫暗，苔白，脉沉细涩。","analysis":"水肿延久不退，气虚、阳虚、阴虚、气滞皆可导致血行缓慢不畅，甚则停滞。血脉凝涩而成血瘀，久病入络，常致瘀血内生。而血水同源，瘀血积于脉中，水液也蓄于脉道，脉络胀滞，进而水液潴留，渗溢肌肤，而发为水肿。瘀血内阻，络脉不通，血不循经，外溢则见瘀斑，内渗则见血尿；瘀阻肾络，则腰部刺痛；瘀血内停，冲任受阻，故经行不畅，经血色暗夹块；瘀血久滞，肌肤失养，故肌肤甲错；舌紫暗，苔白，脉沉细涩，为瘀血内结、水湿内停之象。","treat":"活血祛瘀，化气行水。","formulaRaw":"桃红四物汤（《医宗金鉴》）合五苓散（《伤寒论》）加减。前方活血化瘀，后方温阳化气行水。","formulaName":"桃红四物汤合五苓散加减","fangjie":"当归、赤芍、川芎、丹参养血活血；益母草、红花、凌霄花、路路通、桃仁活血通络；桂枝通阳化气；茯苓、泽泻、车前子利水消肿。若气虚血瘀，乏力体倦，肌肤甲错，加黄芪、地龙、丹参、赤芍，或用补阳还五汤、黄芪赤风汤。宗气虚陷，心悸气短，动则加重，下肢浮肿者，用升陷汤、葶苈大枣泻肺汤；妇女颜面肢体浮肿，伴有月经不调，经血紫暗，甚至经闭，舌暗者，用当归芍药散加减。"}],"linchuang":["辨病邪性质，重视祛风、解毒法。风寒、风热、风湿、热毒等外邪，常是影响水肿病情进展的重要因素。湿热邪毒瘀滞，或风湿之邪内伏，邪伤肾络，多是水肿久治不愈的病理基础。祛风与解毒法常贯穿水肿治疗始终。祛风有疏风清热、疏风散寒、祛风除湿、搜风通络等不同；解毒包括疏风清热解毒、清热解毒、利湿解毒、利湿清热解毒、泄浊解毒等。","正确使用峻下逐水法。峻下逐水法是治疗阳水的一种方法，即《黄帝内经》“去菀陈莝”之法，宜用于病初体实肿甚，正气尚旺，用发汗、利水法无效，症见全身高度浮肿，气喘，心悸，腹水，小便不利，脉沉而有力者。使用该法，宜抓住时机，以逐水为急，使水邪从大小便而去，可用十枣汤治疗，但应中病即止，以免过用伤正。待水肿消退后，即行调补脾胃，以善其后。病至后期，脾肾两亏而水肿甚者，峻下逐水药应慎用。","重视活血利水和行气利水治法。《金匮要略》谓：“血不利则为水。”《伤寒论》指出：“大病癌后，腰以下肿，牡蛎泽泻散主之。”临床常用活血化瘀与清热解毒法结合，或配合益气温阳法等治疗水肿常有卓效。此外，水肿常伴气机阻滞，临床上还应重视行气利水治法，即《金匮要略》“大气一转，其气乃散”之意。","慎用肾毒性药物。水肿日久，脾肾多虚，分清泌浊功能失司，湿浊、水毒、瘀血内停，尤其是肾性水肿，大多伴有肾功能下降。对于此类患者，须考虑药物对肾脏的毒副作用，合理选择药物、调整剂量及用药时间，避免使用氨基糖苷类抗生素、非甾体类抗炎药等肾毒性药物。此外，含有马兜铃酸的中药，如马兜铃、关木通、广防已、青木香、细辛等，亦有一定肾毒性，应尽量避免大剂量、长时间使用。"],"yufang":["水肿常因感受外邪、饮食失调、体倦劳累而发病或加重。预防水肿发生，应注意适寒温，防外感；注意调摄饮食，平素宜清淡；劳逸结合，房事有节，调畅情志。避免使用肾毒性药物。","水肿患者应注意低盐饮食，进食清淡、易消化、营养丰富的食物。因营养障碍而致水肿者，应注意适当补充富含优质蛋白质的食物。水肿而尿少者，应每日记录液体出入量。高度水肿患者，要保持皮肤干燥，勤翻身，以免压疮发生。"],"attachIds":[]},{"id":"d035","name":"淋证","kind":"main","parent":null,"chapterNo":"第三十八章","chapterName":"淋证","yinbing":[{"t":"b","x":"1. 外感湿热"},{"t":"p","x":"下阴不洁，湿热秽浊之邪从下侵人机体，上犯膀胱，发为淋证。"},{"t":"b","x":"2. 饮食不节"},{"t":"p","x":"多食辛热肥甘之品，或嗜酒太过，脾胃运化失常，积湿生热，下注膀胱，发为淋证。"},{"t":"p","x":"宋·严用和《济生方·淋闭论治》云：“此由饮酒房劳，或动役冒热，或饮冷逐热，或散石发动，热结下焦，遂成淋闭。亦有温病后，余热不散，霍乱后，当风取凉，亦令人淋闭。”"},{"t":"p","x":"说明了淋证的发病多由湿热而致。"},{"t":"b","x":"3. 情志失调"},{"t":"p","x":"情志不遂，肝失疏泄，或气郁化火，气火郁于膀胱，发为淋证。"},{"t":"p","x":"如明·李中梓《医宗必读·淋证》言：“妇女多郁，常可发为气淋和石淋。”"},{"t":"b","x":"4. 禀赋不足或劳伤久病"},{"t":"p","x":"禀赋不足，肾与膀胱先天畸形；或久病缠身，劳伤过度，房事不节，多产多育；或久淋不愈，耗伤正气，妊娠、产后脾肾气虚，膀胱易于感受外邪，而致本病。"}],"bingji":[{"t":"p","x":"淋证的基本病机是湿热蕴结下焦，肾与膀胱气化不利。"},{"t":"p","x":"病变部位在膀胱与肾，与肝、脾相关。"},{"t":"p","x":"膀胱湿热则气化失司，肾虚则固摄无权，肝郁则三焦通调失常，或气郁化火，脾伤则积湿生热，脾虚则中气下陷，湿热蕴结下焦，肾与膀胱气化不利，均可导致水道不利，或统摄失常，发为淋证。"},{"t":"p","x":"病理性质有实、有虚，且多见虚实夹杂之证。"},{"t":"p","x":"但淋久湿热伤正，由肾及脾，每致脾肾两虚，而由实转虚。"},{"t":"p","x":"如邪气未尽，正气渐伤，或虚体受邪，则成虚实夹杂之证，常见阴虚夹湿热、气虚夹水湿等。"},{"t":"p","x":"因此，淋证多以肾虚为本，膀胱湿热为标。"},{"t":"p","x":"病理因素主要为湿热之邪。"},{"t":"p","x":"如实证的热淋、血淋、气淋可转化为虚证的劳淋。"},{"t":"p","x":"而当湿热未尽，正气已伤，处于实证向虚证的移行阶段，则表现虚实夹杂的证候。"},{"t":"p","x":"若热毒入营血，出现高热、神昏等症，病情危重。"},{"t":"p","x":"若久淋脾肾衰败，可致水肿、癃闭、关格、虚劳等。"}],"zhenduan":[{"t":"ol","items":["1. 小便频数、淋沥涩痛、小腹拘急引痛为最基本的临床特征。","2. 淋证病久或反复发作后，常伴有低热、腰痛、小腹坠胀、疲劳等。","3. 淋证多发于已婚女性，每因疲劳、情志变化、不洁房事而诱发。"]}],"jianbie":[{"t":"b","x":"1. 癃闭"},{"t":"p","x":"淋证与癃闭均有小便量少、排尿困难的临床表现，但淋证尿频而尿痛，每日排尿总量多为正常，癃闭则无尿痛，每日排尿量少于正常，严重时甚至无尿。"},{"t":"p","x":"《医学心悟·小便不通》云：“癃闭与淋证不同，淋则便数而茎痛，癃闭则小便点滴而难出。”"},{"t":"p","x":"但癃闭复感湿热，常可并发淋证，而淋证日久不愈，亦可发展成癃闭。"},{"t":"b","x":"2. 尿血"},{"t":"p","x":"淋证之血淋与尿血均有小便出血，尿色红赤，甚至溺出纯血等临床表现，其鉴别的要点是有无尿痛感，即如《丹溪心法·淋》所云：“痛者为血淋，不痛者为尿血。”"},{"t":"b","x":"3. 尿浊"},{"t":"p","x":"淋证之膏淋与尿浊在小便浑浊症状上相似，但后者在排尿时无疼痛滞涩感，可资鉴别。"},{"t":"p","x":"《临证指南医案·淋浊》言：“大凡痛则为淋，不痛为浊。”"}],"bianzheng":[{"t":"b","x":"1. 辨六淋主症"},{"t":"p","x":"六种淋证均有小便频涩，滴沥刺痛，小腹拘急引痛。热淋起病多急骤，小便赤热，溲时灼痛，或伴有发热，腰痛拒按；石淋以小便排出砂石为主症，或排尿时突然中断，尿道窘迫疼痛，或腰腹绞痛难忍；气淋小腹胀满较明显，伴小便艰涩疼痛，尿后余沥不尽；血淋为溺血而痛；膏淋见小便浑浊如米泪水或滑腻如膏脂；劳淋小便不甚赤涩，溺痛不甚，但淋沥不已，时作时止，遇劳即发。"},{"t":"b","x":"2. 辨淋证虚实"},{"t":"p","x":"根据病程、症状、脉象等辨别淋证的虚实。初起或在急性发作阶段属实，由于膀胱湿热、砂石结聚、气机郁滞，膀胱气化不利，表现为小便涩痛，舌红苔黄，脉实数；久病多虚，病在脾肾，由于脾肾亏虚，膀胱气化无权，表现为小便频急，痛涩不甚，舌淡苔薄，脉细弱。此外，气淋实证由于气滞不利，虚证源于气虚下陷。血淋由于湿热下注，热盛伤络者，属实；由于阴虚火旺，扰动阴血者，属虚。热淋经过治疗后，有时湿热尚未祛尽，常与肾阴不足或气阴两伤等并见。石淋日久亦可伤及正气，阴血亏虚，表现为气血俱虚的证候。在淋证虚实转化中，每多虚实夹杂，故必须分清标本虚实的主次和证情之缓急。"}],"zhize":"淋证的基本治则为实则清利，虚则补益。初起多实，重在祛邪。以膀胱湿热为主者，治以清热利湿；热灼血络为主者，治以凉血止血；砂石结聚为主者，治以通淋排石；气滞不利为主者，治以利气疏导。虚证以脾虚为主者，治以健脾益气；肾虚为主者，治以补虚益肾。对虚实夹杂者，又当通补兼施，审其主次缓急，兼顾治疗。","syndrome":[{"id":"s223","name":"热淋","label":"1. 热淋","group":"","clinic":"小便频数短涩，灼热刺痛，溺色黄赤，少腹拘急胀痛，寒热起伏，口苦，呕恶，腰痛拒按，大便秘结，舌质红，苔黄腻，脉滑数。","analysis":"湿热蕴结下焦，膀胱气化不利，故见小便频数短涩，灼热刺痛，小腹拘急胀痛；湿热郁蒸，少阳枢机不利，故见寒热起伏，口苦；湿热困阻中焦，胃气上逆，则呕恶；腑气不通，肠道传导失司，则便秘；气血壅滞，则腰痛拒按；舌质红，苔黄腻，脉滑数，皆为湿热内蕴、热势亢盛之象。","treat":"清热利湿通淋。","formulaRaw":"八正散（《太平惠民和剂局方》）加减。","formulaName":"八正散加减","fangjie":"瞿麦、篇蓄、车前子、滑石、木通利湿通淋；栀子清热泻火，清利三焦湿热；大黄荡涤邪热，通利肠腑；甘草调和诸药，兼以清热缓急；煎加灯心草以增利水通淋之力。若大便秘结，腹胀，重用生大黄，加枳实；伴寒热、口苦、呕恶等邪郁少阳者，加黄芩、柴胡；湿热伤阴，见口干、舌红少苔、脉细者，去大黄，加生地黄、知母、白茅根。"},{"id":"s224","name":"石淋","label":"2. 石淋","group":"","clinic":"尿中夹砂石，排尿涩痛，或排尿时突然中断，尿道窘迫疼痛，少腹拘急，往往突发一侧腰腹绞痛难忍，甚则牵及外阴，尿中带血，舌红，苔薄黄，脉弦或数。","analysis":"湿热蕴结下焦，煎尿液浊质，日久结为砂石，故尿中时有砂石；砂石阻滞尿道，膀胱气化失司，故小便艰涩，或排尿时中断，尿道窘迫疼痛，少腹拘急，腰腹绞痛难忍；砂石损伤血络，故尿中带血；舌红，苔薄黄，脉弦或数，提示湿热蕴结，气机阻滞。","treat":"清热利湿，排石通淋。","formulaRaw":"石韦散（《外台秘要》引《集验方》)加减。","formulaName":"石韦散加减","fangjie":"瞿麦、车前子、滑石清热利湿通淋；冬葵子滑利窍道；石韦排石化石。若腰腹绞痛，加芍药、甘草；尿中带血，加小蓟、生地黄、藕节；舌质紫，加桃仁、红花、皂角刺。绞痛缓解后多无明显自觉症状，可用金钱草煎汤代茶；若结石过大，阻塞尿路，肾盂严重积水，宜手术治疗。"},{"id":"s225","name":"血淋","label":"3. 血淋","group":"","clinic":"小便热涩刺痛，尿色深红，或夹有血块，小腹疼痛胀满拘急，心烦，舌尖红，苔黄，脉滑数。","analysis":"湿热下注膀胱，膀胱气化不利，故小便滞涩不畅；湿热之邪灼伤膀胱及溺窍血络，迫血妄行，血溢脉外，随尿而出，故见尿血，尿色深红，甚或夹有血块；血块阻塞溺窍，不通则痛，故排尿时刺痛；心与小肠相表里，下焦湿热循经上扰于心，致使心火亢盛，故见心烦；舌尖红，苔黄，脉滑数，为里热炽盛、湿热内蕴之象。","treat":"清热通淋，凉血止血。","formulaRaw":"小蓟饮子（《济生方》）加减。","formulaName":"小蓟饮子加减","fangjie":"小蓟、生地黄凉血止血；木通、生甘草梢、山栀、滑石、淡竹叶清热泻火通淋；蒲黄、当归、藕节通络止血。若有瘀血征象，见舌暗或有瘀点，脉细涩者，加三七、牛膝、桃仁；出血不止，加仙鹤草、琥珀粉。尿痛涩滞不显著，腰膝酸软，神疲乏力，舌淡红，脉细数，治当滋阴清热，补虚止血，用知柏地黄丸加减。"},{"id":"s226","name":"气淋","label":"4. 气淋","group":"","clinic":"郁怒之后，小便涩滞，淋沥不已，少腹胀满疼痛，舌淡红，苔薄白，脉弦。","analysis":"肝气郁结，疏泄失常，气机阻滞于下焦，通调不畅，膀胱气化失司，则小便涩滞，淋沥不畅，少腹胀满疼痛；舌淡红，苔薄白，脉弦，为肝气郁结之象。","treat":"理气疏导，通淋利尿。","formulaRaw":"沉香散（《金匮翼》）加减。","formulaName":"沉香散加减","fangjie":"沉香行气止痛；石韦、滑石清热利湿，通淋止痛；当归、王不留行活血化瘀；冬葵子、白芍利水通淋，柔肝缓急；甘草调和诸药，缓急和中。若少腹胀满，上及于胁，加川棟子、小茴香、郁金；兼有瘀滞者，加红花、赤芍、益母草。久病少腹坠胀，尿有余沥，面色萎黄，舌质淡，脉虚细无力，用补中益气汤加减。"},{"id":"s227","name":"膏淋","label":"5. 膏淋","group":"","clinic":"小便浑浊，或如米泪水，上有浮油，置之沉淀，或有絮状凝块，尿道热涩疼痛，尿时阻塞不畅，口干，舌质红，苔黄腻，脉濡数。","analysis":"湿热蕴结下焦，导致泌别失职，清浊不分，膏脂外泄，故见小便浑浊，或如米泔水，上有浮油，置之沉淀，或有絮状物；湿热蕴结，灼伤尿道，故尿道有热涩疼痛之感；热伤津液则口干；舌质红，苔黄腻，脉濡数，均为湿热内蕴之象。","treat":"清热利湿，分清泄浊。","formulaRaw":"草薜分清饮（《医学心悟》)加减。","formulaName":"草薜分清饮加减","fangjie":"草薜利湿，分清化浊；黄柏、车前子清热利湿泄浊；石菖蒲芳香化浊，分利小便；茯苓、白术健脾渗湿；莲子心、丹参清心泻热。若小腹胀，尿涩不畅，加乌药、青皮；伴有血尿，加小蓟、侧柏叶、藕节、白茅根；小便黄赤，热痛明显，加甘草梢、竹叶、通草；兼肝火者，加龙胆草、山栀；病久湿热伤阴者，加生地黄、麦冬、知母。\n膏淋病久不已，反复发作，淋出如脂，涩痛不甚，形体日渐消瘦，头昏无力，腰膝酸软，舌淡，苔腻，脉细无力，此为脾肾两虚，气不固摄，用膏淋汤补脾益肾固涩。偏于脾虚，中气下陷者，配用补中益气汤。偏于肾阴虚者，配用七味都气丸。偏于肾阳虚者，用金匮肾气丸加减。伴有血尿者，加仙鹤草、阿胶补气摄血；夹瘀者，加三七、当归活血通络。"},{"id":"s228","name":"劳淋","label":"6. 劳淋","group":"","clinic":"小便不甚赤涩，溺痛不甚，但淋沥不已，时作时止，遇劳即发，病程缠绵，面色萎黄，少气懒言，神疲乏力，小腹坠胀，大便时小便点滴而出，腰膝酸软，肾阳虚见畏寒肢冷，肾阴虚见面色潮红、五心烦热，舌质淡，脉细弱。","analysis":"湿热留恋，正气耗伤，脾肾两虚，膀胱气化无权，故小便淋沥不已，赤涩疼痛不甚，时轻时重；脾虚，故见神疲乏力，面色萎黄，少气懒言，遇劳即发或加重，病情缠绵难愈；脾虚气陷，故小腹坠胀，小便失于固摄而点滴溢出；腰为肾之府，肾精亏虚，故见腰膝酸软；肾阳虚衰，温煦失职，故见畏寒怕冷；肾阴亏虚，阴不制阳，虚火上炎，则面色潮红，五心烦热；舌质淡，脉细弱，为脾肾不足，气血两虚之象。","treat":"补脾益肾。","formulaRaw":"无比山药丸（《备急千金要方》)加减。","formulaName":"无比山药丸加减","fangjie":"山药健脾益肾；熟地黄、山茱萸、五味子滋补肾阴；肉苁蓉、菟丝子、杜仲、巴戟天温补肾阳；赤石脂涩精止遗；泽泻、茯苓泄肾浊，利水湿；牛膝引药下行。若中气下陷，症见少腹坠胀，尿频涩滞，余沥难尽，不耐劳累，面色无华，少气懒言，舌淡，脉细无力，用补中益气汤加减。肾阴虚，舌红苔少，加生地黄、龟甲；阴虚火旺，面红烦热，尿黄赤，伴有灼热不适者，用知柏地黄丸；低热者，加青蒿、鳖甲；肾阳虚者，加附子（制）、肉桂、鹿角片等。"}],"linchuang":["辨轻重缓急，重标本虚实。淋证有轻重不同，轻者尿急、尿频、尿痛，而无恶寒、发热、腰痛等，治以清热利湿通淋，用药1周即可。若见发热、恶寒，当加以清热解毒之品，且需服药2周以上，以免湿热留恋。体虚者感受湿热之邪，先祛其邪，之后扶正。年老体虚甚者，或淋证日久，须兼顾祛邪与扶正，不可一味苦寒清热，避免邪虽去而正亦伤，正伤而邪易侵，反复发作。对老年患者尤其注意补益脾肾，根据肾虚膀胱热的病机，攻补兼施，温清并用。各种淋证之间亦每多兼夹出现，如石淋、膏淋、血淋每多兼有热淋，当辨标本虚实缓急论治。","淋证当补则补、当汗则汗。对于淋证的治法，古有忌汗、忌补之说，如《金匮要略·消渴小便不利淋病脉证并治》言“淋家不可发汗”。《丹溪心法·淋》谓：“最不可用补气之药，气得补而愈胀，血得补而愈涩，热得补而愈盛。”临床实际未必都是如此。若淋证确因外感诱发，或淋家新感外邪，症见恶寒、发热、鼻塞流涕、咳嗽、咽痛者，仍可适当配合运用辛散解表之剂。因淋证为膀胱有热，阴液不足，即使感受寒邪，亦容易化热，故应避免辛温之品。至于淋证忌补之说，是指实热之证而言，诸如脾虚中气下陷、肾虚下元不固，自当运用健脾益气、补肾固涩等法治之，不必禁忌。"],"yufang":["预防淋证发生，需注意外阴清洁，不憋尿，多饮水，每2～3小时排尿1次。房事后即行排尿，防止秽浊之邪从下阴上犯膀胱。妇女在月经期、妊娠期、产后更应注意外阴卫生，以免虚体受邪。避免纵欲过劳，保持心情舒畅。","淋证发病后应注意休息，忌房事，饮食宜清淡。热淋、血淋者忌肥腻辛辣醇酒之品，石淋者多饮水，久淋患者忌劳累。初起尿频、尿痛，继之出现高热、寒战、腰痛者，须及时诊治。"],"attachIds":["a006"]},{"id":"d036","name":"癃闭","kind":"main","parent":null,"chapterNo":"第三十九章","chapterName":"癃闭","yinbing":[{"t":"b","x":"1. 外邪侵袭"},{"t":"p","x":"下阴不洁，湿热秽浊之邪上犯膀胱，或湿热素盛，热结下焦，肾移热于膀胱，发为癃闭。"},{"t":"p","x":"或外感热毒犯肺，肺热壅滞，肺气闭塞，肃降失司，水道通调失职，津液不能下输膀胱而成癃闭；或因燥热犯肺，肺燥津伤，水源枯竭，而成癃闭。"},{"t":"b","x":"2. 饮食不节"},{"t":"p","x":"过食辛辣香燥、肥甘厚味之品，或嗜酒过度，导致脾失运化，酿湿生热，湿热伤肾或下注膀胱，气化不利，而发为癃闭；或饥饱失常，损伤脾胃，中焦气虚，甚或下陷，清阳不升，浊阴不降，气化无力，而生癃闭。"},{"t":"p","x":"《灵枢·口问》所谓：“中气不足，溲便为之变。”"},{"t":"p","x":"或因误用、误食或过用、过食药物、毒物，损伤脾肾，形成癃闭。"},{"t":"b","x":"3. 情志失调"},{"t":"p","x":"如惊恐、忧思、郁怒、紧张等引起肝气郁结，疏泄失司，三焦水液的运行及气化功能失常，则上焦肺不能敷布津液、中焦脾不能运化水湿、下焦肾不能蒸腾气化水液，以致水道通调受阻，形成癃闭。"},{"t":"b","x":"4. 尿路阻塞"},{"t":"p","x":"如瘀血败精、痰瘀积块或内生砂石阻塞尿路，以致排尿困难，或点滴而出，或点滴全无，而形成癃闭。"},{"t":"b","x":"5. 体虚久病"},{"t":"p","x":"如劳倦太过，久病体虚，或年老体弱，致脾肾阳衰，肾阳不足，命门火衰，蒸化无力，气不化水，故尿不得出，此乃“无阳则阴无以生”。"},{"t":"p","x":"或因消渴、热病日久，耗损津液，以致肾阴耗竭，此即“无阴则阳无以化”，以致水府枯竭而无尿。"}],"bingji":[{"t":"p","x":"癃闭的基本病机是肾与膀胱气化功能失调，导致尿液的生成或排泄障碍。"},{"t":"p","x":"初起多表现为膀胱气化不利，水道不畅；若湿热蕴结，或肺热气壅，则可致小便涩滞，点滴而下；病情进展，气滞日久，水停为浊，浊瘀互结，阻塞水道，则小便全然不通；病至后期，由实转虚，或脾虚清阳不升，浊阴不降，或肾虚命门火衰，气化无权，则可见小便无力，排尿困难，甚则癃闭不通，发为重症。"},{"t":"p","x":"病变部位主要在膀胱与肾，与肺、脾、肝和三焦有关。"},{"t":"p","x":"若肾阳不足，命门火衰，气化不及州都，则膀胱气化无权，可发为癃闭。"},{"t":"p","x":"病理性质以实证居多，久病由实致虚，可见气虚、阴虚等虚候或虚实夹杂之候。"},{"t":"p","x":"病机演变及预后转归与病情轻重、治疗是否得当有关。"},{"t":"p","x":"尿闭不通，水液潴留体内，溢于肌肤，则伴发水肿；水气内停，上凌心肺，可并发喘证、心悸；湿浊上逆犯胃，则成呕吐；脾肾衰败，气化不利，湿浊内壅，则可致关格，预后多差。"}],"zhenduan":[{"t":"ol","items":["1. 以小便不利，点滴不畅，甚或小便闭塞，点滴全无，每日小便总量明显减少为主要依据，起病急骤或逐渐加重。","2. 严重者可伴有恶心呕吐、胸闷气喘、水肿、头痛头晕甚至神昏等症状。","3. 凡小腹胀满，小便欲解不出，触叩小腹部膀胱区明显膨隆，为尿潴留；小便量少或不通，无排尿感，小腹胀满，触叩小腹部膀胱区无明显充盈征象，多属少尿或无尿。","4. 多见于老年男性、产后妇女及腹部手术后患者，或患有水肿、淋证、消渴等病迁延日久不愈患者。"]}],"jianbie":[{"t":"b","x":"1. 淋证"},{"t":"p","x":"癃闭与淋证均属膀胱气化不利，故皆有排尿困难、点滴不畅的表现。"},{"t":"p","x":"但癃闭无尿道刺痛，每日尿量少于正常，甚或无尿排出。"},{"t":"p","x":"淋证则小便频数短涩，滴沥刺痛，欲出未尽，而每日排尿量正常。"},{"t":"p","x":"《医学心悟·小便不通》云：“癃闭与淋证不同，淋则便数而茎痛，癃闭则小便点滴而难通。”"},{"t":"p","x":"淋证日久不愈，可发展为癃闭；而癃闭易感外邪，常并发淋证。"},{"t":"b","x":"2. 关格"},{"t":"p","x":"关格和癃闭都以小便量少或闭塞不通为主要特点。"},{"t":"p","x":"但关格常由水肿、淋证、癃闭等经久不愈发展而来，是小便不通与呕吐并见的病证，常伴有皮肤瘙痒、口中尿味、四肢搐搦甚或昏迷等症状。"},{"t":"p","x":"癃闭不伴有呕吐，部分患者有水蓄膀胱之证候，可以此鉴别。"},{"t":"p","x":"癃闭进一步恶化，可转变为关格。"}],"bianzheng":[{"t":"ol","items":["1. 辨膀胱有尿与无尿见表39-1。"]},{"t":"table","caption":"表 39-1 膀胱有尿无尿辨别","head":["","有尿","无尿"],"rows":[["腹部特征","小腹胀满膨隆","小腹无胀满或胀满不甚，外形如常"],["小便情况","小便欲解不得或点滴而下","无排尿意，尿量少或无"],["病机特点","水蓄膀胱","津伤液涸，肾元衰竭"],["病情程度","病情较轻","病情较重"]]},{"t":"ol","items":["2. 辨虚实 起病较急，病程较短，体质较好，尿意急迫，小便短少色黄，涩滞不畅，苔黄腻，脉弦数，多为实证，与湿热、肺热、肝郁、浊瘀有关，病机多为膀胱湿热、肺热壅盛、肝郁气滞、尿路阻塞等。起病较缓、病程较长，体质较弱，排尿无力，神疲乏力，舌质淡，脉沉细，多为虚证，病机多属中气虚陷、肾阳虚衰、膀胱气化无权等。"]},{"t":"ol","items":["3. 辨病情轻重一般初起病“癃”，后来转成“闭”，为病势由轻转重；初起病“闭”，后转成“癃”，为病势由重转轻。如见小腹胀满疼痛、胸闷、气喘、呕吐等症，则病情较重；如见神昏烦躁、抽风痉挛等症，则病情危笃。"]}],"zhize":"癃闭的治疗以“通利”为基本原则。具体治法需根据证候虚实不同而异，实证宜清邪热、利气机、散瘀结，虚证应益脾肾、助气化，虚实夹杂者，应标本同治，切忌滥用通利小便之品。必要时采用提壶揭盖法，取“上窍开则下窍自通”之意。若小腹胀急，小便点滴不下，水蓄膀胱者，可配合热敷、导尿、针灸、取嚏等法急通小便。","syndrome":[{"id":"s232","name":"膀胱湿热证","label":"1. 膀胱湿热证","group":"","clinic":"小便点滴不通，或量极少而短赤灼热，小腹胀满，口苦口黏，或口渴不欲饮，或大便不畅，舌质红，苔黄腻，脉数。","analysis":"湿热之邪蕴结膀胱，阻滞气机，故小便点滴不通或量少短赤灼热；膀胱气闭，水蓄不行，故小腹胀满；湿热内蕴，津液不布，则口苦口黏，口渴而不欲饮；湿热下注大肠，传导失司，故大便不畅；舌质红，苔黄腻，脉数，均为湿热内蕴之象。","treat":"清利湿热，通利小便。","formulaRaw":"八正散（《太平惠民和剂局方》）加减。","formulaName":"八正散加减","fangjie":"黄柏、山栀、大黄、滑石清热利湿；瞿麦、萹蓄、茯苓、泽泻、车前子通利小便。心烦，口舌生疮糜烂者，加生地黄、生甘草梢、竹叶；口干咽燥，潮热盗汗，手足心热，舌光红者，加知母、生地黄、牛膝等。"},{"id":"s233","name":"肺热壅盛证","label":"2. 肺热壅盛证","group":"","clinic":"小便不畅或点滴不通，咽干，烦渴欲饮，呼吸急促，或有咳嗽，舌红，苔薄黄，脉数。","analysis":"肺热壅盛，宣发肃降失司，不能通调水道，下输膀胱受阻，故见小便不畅或点滴不通；热邪灼伤肺津，津液不能上承，故咽干，烦渴欲饮；肺气上逆，则呼吸急促或咳嗽；舌红，苔薄黄，脉数，均为肺热内盛之征。","treat":"清泄肺热，通利水道。","formulaRaw":"清肺饮（《证治汇补》）加减。","formulaName":"清肺饮加减","fangjie":"黄芩、桑白皮、鱼腥草清泄肺热；麦冬、芦根、天花粉、地骨皮清肺生津养阴；车前子、茯苓、泽泻、猪苓通利小便。有鼻塞、头痛、脉浮等表证者，加薄荷、桔梗；肺阴不足者，加沙参、黄精、石斛；大便不通者，加大黄、杏仁。"},{"id":"s234","name":"肝郁气滞证","label":"3. 肝郁气滞证","group":"","clinic":"小便不通或通而不畅，情志抑郁，或多烦善怒，胁腹胀满，舌红，苔薄黄，脉弦。","analysis":"肝失疏泄，气机郁滞，三焦水道不利，膀胱气化失常，故见小便不通或通而不畅；肝气不疏，故情志抑郁，多烦善怒；肝经循行于胁腹，气滞则经气不畅，故胁腹胀满；舌红，苔薄黄，脉弦，均为肝郁化热之象。","treat":"疏利气机，通利小便。","formulaRaw":"沉香散（《金匮翼》）加减。","formulaName":"沉香散加减","fangjie":"沉香、陈皮、柴胡、郁金、青皮、乌药、香附疏肝理气；王不留行、当归行下焦气血；石韦、车前子、冬葵子、茯苓通利小便。若肝郁气滞症状严重，合六磨汤；气郁化火，见舌红、苔薄黄者，加丹皮、山栀。"},{"id":"s235","name":"浊瘀阻塞证","label":"4. 浊瘀阻塞证","group":"","clinic":"小便点滴而下，或尿如细线，甚则阻塞不通，小腹胀满疼痛，舌紫暗，或有瘀点，脉涩。","analysis":"瘀血败精搏结，阻塞尿道，水道不通，故小便点滴而下，或尿线细如丝线，甚则闭塞不通；尿液蓄积膀胱，气机阻滞，故小腹胀满疼痛；舌质紫暗，有瘀点，脉涩，均为瘀血内阻征象。","treat":"行瘀散结，通利水道。","formulaRaw":"代抵当丸（《证治准绳》）加减。","formulaName":"代抵当丸加减","fangjie":"当归尾、炮山甲、桃仁、莪术活血化瘀；大黄、芒硝、郁金通瘀散结；肉桂、桂枝助膀胱气化。若瘀血较重，加红花、川牛膝；病久气血两虚，面色无华，加黄芪、丹参、当归；尿路结石，加金钱草、海金沙、冬葵子、瞿麦、石韦；尿血，加服三七粉、琥珀粉。"},{"id":"s236","name":"脾气不升证","label":"5. 脾气不升证","group":"","clinic":"小腹坠胀，时欲小便而不得出，或量少而不畅，神疲乏力，食欲不振，气短声低，舌质淡，苔薄，脉细弱。","analysis":"脾虚运化无力，清气不能上升，浊阴难以下降，膀胱气化无权，故见小腹坠胀，时欲小便而不得出，或量少而不畅；脾虚气血化生不足，四肢百骸失于濡养，故见神疲乏力，气短声低；脾失健运，受纳失常，故食欲不振；舌质淡，苔薄，脉细弱，皆为脾气虚弱之象。","treat":"升清降浊，化气行水。","formulaRaw":"补中益气汤（《内外伤辨惑论》）合春泽汤（《证治要诀类方》）加减。前方益气升清，后方益气通阳利水。","formulaName":"补中益气汤合春泽汤加减","fangjie":"人参、党参、黄芪、白术益气健脾；桂枝通阳以助膀胱气化；升麻、柴胡升提中气；茯苓、猪苓、泽泻、车前子利水渗湿。血虚者，加熟地黄、当归、鸡血藤；心悸多汗者，加麦冬、五味子、酸枣仁。气虚及阴，气阴两虚，改用参苓白术散加减。"},{"id":"s237","name":"肾阳衰惫证","label":"6. 肾阳衰惫证","group":"","clinic":"小便不通或点滴不爽，排出无力，面色㿠白，神气怯弱，畏寒肢冷，腰膝酸软无力，舌淡胖，苔薄白，脉沉细或弱。","analysis":"肾阳亏虚，命门火衰，气化无权，故小便不通或点滴不爽，排出无力；元阳虚衰，机体失于温煦，故畏寒肢冷；肾主骨生髓，腰为肾之府，肾虚则腰膝酸软无力；阳气衰惫，无力振奋神采、荣润面庞，故面色㿠白，神气怯弱；舌淡胖，苔薄白，脉沉细或弱，均为肾阳衰惫之象。","treat":"温补肾阳，化气利水。","formulaRaw":"济生肾气丸（《济生方》）加减。","formulaName":"济生肾气丸加减","fangjie":"附子（制）、肉桂温肾通阳；地黄、山药、山茱萸补肾滋阴；车前子、茯苓、泽泻利尿。若形神委顿，腰脊酸痛，为精血俱亏，病及督脉，多见于老人，治宜香茸丸。"},{"id":"s238","name":"肾阴亏耗证","label":"7. 肾阴亏耗证","group":"","clinic":"小便量少或全无，口咽干燥，腰膝酸软，烦躁不安，潮热盗汗，头晕耳鸣，舌绛红，少苔，脉细数。","analysis":"肾阴亏虚，无阴则阳无以化，气化无源，则小便量少或全无；阴津不能上承，濡润失职，故口咽干燥；肾主骨生髓，腰为肾之府，肾阴不足，髓减骨弱，故腰膝酸软；阴虚则生内热，虚火内扰，故见烦躁不安，潮热盗汗；髓海不足，清窍失养，故头昏耳鸣；舌绛红，少苔，脉细数，均为肾阴亏耗，虚火内扰之征。","treat":"滋补肾阴，育阴利水。","formulaRaw":"六味地黄丸（《小儿药证直诀》）合猪苓汤（《伤寒论》）加减。前方补肾滋阴，后方养阴清热利水。","formulaName":"六味地黄丸合猪苓汤加减","fangjie":"熟地黄、山药、山茱萸滋补肾阴；茯苓、猪苓、泽泻、滑石祛湿利水，寓泻于补。若下焦有热，加知母、黄柏；阴虚及气，用滋肾通关丸。"}],"linchuang":["重视病证互参。癃闭临床可见于前列腺疾病、肾功能衰竭等多种疾病。临证应明确是否存在尿潴留，判断有无肾功能损伤及全身病情严重程度，确定癃闭的轻重缓急。癃闭早期，多因膀胱湿热、肺热壅盛或尿路阻塞等所致，多为膀胱气化不利，治疗重点在通利；晚期，脾气不升或肾阳衰惫，多为膀胱气化无权，治疗重点在补益脾肾，以助气化，气化则水行。如晚期伴有恶心呕吐，口中有尿臭，甚则神昏谵语，属湿热蕴结三焦，气化不利，浊毒内陷，宜用黄连温胆汤加车前子、通草、制大黄。晚期癃闭进一步恶化，可转变为关格。","急则治标，速予通利。癃闭多属临床急重病证。水蓄膀胱，欲排不能，小腹胀痛难忍，甚是急迫；小便不通，水毒蓄于内，喘证、心悸、关格、神志昏厥等危重变证相继而生。因此，癃闭的治疗，必须急则治标，缓则治本。对水蓄膀胱之证，内服药缓不济急，可急用导尿、针灸、热敷等法，通利小便。对膀胱无尿之证，可用中药灌肠法。本法重在治标，病情缓解后，应针对不同病因，或排石，或祛瘀，或疏肝，或温补脾肾，缓图其本，防止旧病复发。","下病上治，欲降先升。《丹溪心法·小便不通》中载有提壶揭盖法，即在内服药物的同时，加用探吐法。癃闭的形成与肾、肺、脾有关，尿的生成与排泄，除肾的气化外，尚有赖于肺的通调和脾的转输。急性尿潴留，小便点滴不下时，可在辨证论治的基础上稍加开宣肺气、升提中气之桔梗、杏仁、升麻、柴胡等，以寓下病上治、提壶揭盖、升清降浊之意。除了内服药，取嚏法、探吐法均有此意。"],"yufang":["预防癃闭发生，宜保持心情舒畅，忌忧思恼怒，积极锻炼身体，注意起居饮食，勿过食肥甘、辛辣、醇酒，勿忍尿、纵欲，避免久坐少动。避免外邪入侵和湿热内生的有关因素。老年人应尽量不使用抗胆碱类药物，如阿托品、颠茄等，以免癃闭发生。","淋证、水肿、尿路肿块及结石等疾患应及时治疗。尿潴留需进行导尿的患者，必须严格消毒，规范操作。保留导尿管的患者，应保持会阴部清洁，并鼓励患者多饮水，保证每日尿量；当患者能主动解出小便时，应尽快拔除导尿管。"],"attachIds":["a007"]},{"id":"d037","name":"阳痿","kind":"main","parent":null,"chapterNo":"第四十章","chapterName":"阳痿","yinbing":[{"t":"b","x":"1. 情志失调"},{"t":"p","x":"情志不遂，忧思郁怒，致肝失条达，疏泄不利，气机不畅，脉络不张，血液不充，宗筋弛纵，则病阳痿。"},{"t":"p","x":"或猝受惊恐，突遭不测，心肾不交，宗筋失主，导致痿软不用。"},{"t":"p","x":"或忧思气结，伤及脾胃，水谷不化，精微不布，无以“散精于肝，淫气于筋”，致宗筋失养而阳痿。"},{"t":"b","x":"2. 劳逸失度"},{"t":"p","x":"劳心劳力，操劳太过，致劳伤心脾，伤精耗气，气血不足，宗筋失荣，故阳痿难举。"},{"t":"p","x":"或过度安逸，多食少劳，多坐少动，气血不运，或身体虚胖，痰湿壅盛，阳事不旺。"},{"t":"b","x":"3. 饮食不节"},{"t":"p","x":"过食醇酒厚味，损伤脾胃，致脾胃虚弱，气血生化不足，不能输布精微以养宗筋，则宗筋不举而痿软。"},{"t":"p","x":"或脾胃运化失常，聚湿生热，湿热下注肝肾，经络阻滞，气血不荣宗筋，乃成阳痿。"},{"t":"b","x":"4. 禀赋不足或劳欲过度"},{"t":"p","x":"禀赋不足，或恣情纵欲，房事过度，或少年手淫，或早婚多育，或久病及肾，以致肾精亏损，命门火衰、宗筋失于温养，则痿软不兴。"},{"t":"p","x":"或肾阴损伤太过，相火偏亢，火热内生、灼伤宗筋，导致阴茎痿软不用。"},{"t":"p","x":"或久病劳伤，损及脾胃，气血化源不足，致宗筋失养，而成阳痿。"},{"t":"p","x":"此外，生活不洁，湿热内侵，蕴结肝经，下注宗筋，气机受阻，也可发为阳痿。"}],"bingji":[{"t":"p","x":"阳痿的基本病机是脏腑气血阴阳失调，精血不足，阴络失荣，或邪气郁阻，经络失畅，宗筋失养而不用。"},{"t":"p","x":"病变部位在宗筋，与肝、肾、心、脾关系密切。"},{"t":"p","x":"如肝失疏泄，气机阻滞，气血不达宗筋，则宗筋不聚，阳事难举。"},{"t":"p","x":"病理性质有虚实之分，且多虚实相兼。"},{"t":"p","x":"病理因素为气滞、湿热、寒湿、痰浊、血瘀。"},{"t":"p","x":"肝郁不疏、湿热下注属实，多责之于肝。"},{"t":"p","x":"命门火衰、心脾两虚、惊恐伤肾属虚，多与心、脾、肾有关。"},{"t":"p","x":"久病不愈，常可因实致虚，或因病致郁，加重病情。"},{"t":"p","x":"如湿热下注，湿阻阳气，可致脾肾阳虚之证；湿热灼伤阴精，或肝郁化火伤及肝肾，而成肝肾阴虚之证。"},{"t":"p","x":"如脏腑功能失调，又可因虚致实，如脾虚痰湿内生，或久病入络夹瘀，可致脾虚夹湿夹痰、肾虚夹痰夹瘀之证。"},{"t":"p","x":"久病阳痿，心脾肾虚损，常因欲求不遂，抑郁不欢，久之大多兼夹肝郁不疏之实证，也为本虚标实，病情更加错综复杂。"}],"zhenduan":[{"t":"ol","items":["1. 阳痿以成年男子性交时，阴茎痿而不举，或举而不坚，或坚而不久，无法进行正常性生活为主要临床特征。","2. 常伴有性欲下降，神疲乏力，腰酸膝软，畏寒肢冷，夜寐不安，精神苦闷，胆怯多疑，或小便不畅，滴沥不尽等症。","3. 常有操劳过度、房事不节、手淫频繁，或有肥胖、消渴、惊悸、郁证等病史。"]}],"jianbie":[{"t":"p","x":"主要与早泄相鉴别。"},{"t":"p","x":"阳痿是指欲性交时阴茎不能勃起，或举而不坚，或坚而不久，不能进行正常性生活的病证；"},{"t":"p","x":"早泄是同房时，阴茎能勃起，但因过早射精，射精后阴茎痿软的病证。"},{"t":"p","x":"二者在临床表现上有明显差别，但在病因病机上有相同之处，若早泄日久不愈，可进一步导致阳痿。"},{"t":"p","x":"一般阳痿病情重于早泄。"}],"bianzheng":[{"t":"ol","items":["1. 辨虚实见表 40-1。"]},{"t":"table","caption":"表 40-1 阳痿虚实病机辨别","head":["","实证","虚证"],"rows":[["病因","七情所伤，饮食不节，邪气郁阻","恣情纵欲，思虑惊恐，久病体衰"],["病机","肝气郁结，湿热下注，痰湿阻滞","心脾两虚，惊恐伤肾，命门火衰"],["发病人群","多见于中青年","多见于中老年"],["转化","阳痿久病，每多虚实夹杂或久病入络，常见湿热伤肾、肾虚痰瘀",""]]}],"zhize":"阳痿的治疗以补肾疏肝、宁心健脾、行气活血，恢复前阴宗筋气血正常运行为基本原则。实证者治肝治心，以清利湿热或祛痰化瘀通络为主。虚证者以治脾肾为主，心脾两虚者当健脾养心，命门火衰者当温肾填精，阴精亏虚者当滋阴养筋，惊恐伤肾者宜益肾宁神。阳痿早期切勿滥用补肾壮阳之药。对于因郁致痿或因痿致郁者，适当加入解郁安神、行气活血之品，可提高疗效。同时注重运用心理疏导方法。","syndrome":[{"id":"s242","name":"肝气郁结证","label":"1. 肝气郁结证","group":"","clinic":"临房不举，睡中自举，或举而不坚，情志抑郁，喜太息，胸胁胀痛，嗳气，脘闷不适，食少便溏，舌质淡，苔薄白，脉弦或弦细。","analysis":"肝气郁滞，血行不畅，宗筋所聚无能，可致阳痿；肝主疏泄，疏泄不及，则肝气郁结，情怀抑郁，喜太息；肝为刚脏，性喜条达，肝气郁结，气机紊乱，则胸胁胀痛，脘闷不适；肝木克土，故见食少便溏；舌质淡，苔薄，脉弦或弦细，为肝郁之象。","treat":"疏肝解郁，行气起痿。","formulaRaw":"柴胡疏肝散（《医学统旨》）加减。","formulaName":"柴胡疏肝散加减","fangjie":"柴胡、香附疏肝解郁、调理气机；芍药助柴胡和肝解郁，养血柔肝；陈皮、枳壳、川芎行气活血。口干口苦，急躁易怒，头晕目胀者，加丹皮、栀子、夏枯草；久病血瘀者，加丹参、当归、鸡血藤，重者加蜈蚣；腰酸肢软者，加沙苑子、枸杞子、淫羊藿；便溏者，加炒白术、山药、茯苓、木香；失眠、心理压力较大者，加酸枣仁、五味子、合欢皮、石菖蒲、郁金、夜交藤。"},{"id":"s243","name":"湿热下注证","label":"2. 湿热下注证","group":"","clinic":"阳痿不举，阴茎痿软弛长，睾丸坠胀作痛，阴囊瘙痒或潮湿多汗，泛恶口苦，胁胀腹闷，肢体困倦，尿黄灼痛，大便不爽，口黏口苦，舌质红，苔腻黄，脉滑数。","analysis":"湿热下注肝经，宗筋经络失畅，故阴茎痿软弛长，睾丸坠胀作痛，阴囊瘙痒或潮湿多汗；湿热蕴结于下焦，下注膀胱，湿热阻于肾与膀胱，致肾与膀胱气化失常，则胁胀腹闷，肢体困倦，尿黄灼痛，大便不爽，口黏口苦；舌红苔黄腻，脉滑数，乃湿热下注之象。","treat":"清利湿热。","formulaRaw":"龙胆泻肝汤（《医方集解》）加减。","formulaName":"龙胆泻肝汤加减","fangjie":"龙胆草、黄芩、山栀子清肝泻火；木通、车前子、泽泻、土茯苓清利湿热；柴胡、香附疏肝理气；当归、生地黄活血凉血坚阴。阴部湿痒者，加地肤子、黄柏、苦参、蛇床子；小腹胀痛者，加延胡索、川楝子；热势不甚，湿浊困遏，阳气不振者，加厚朴、苍术、陈皮、砂仁，或用三仁汤；湿热伤肾，阴虚火旺者，合知柏地黄丸；湿热酿痰者，改用黄连温胆汤加胆南星、僵蚕、露蜂房。"},{"id":"s244","name":"命门火衰证","label":"3. 命门火衰证","group":"","clinic":"阳痿不举，性欲减退，或举而不坚，精薄清冷，神疲倦怠，畏寒肢冷，面色㿠白，头晕耳鸣，腰膝酸软，夜尿清长，五更泄泻，阴器冷缩，舌淡胖，苔薄白，脉沉迟或细。","analysis":"恣情纵欲，斫丧太过，精气亏虚，命门火衰，故见阳痿不举，性欲减退，或举而不坚，精薄清冷；腰为肾之府，精气亏乏，故见神疲倦怠，畏寒肢冷，腰膝酸软；肾精亏耗，髓海空虚，故头晕耳鸣；五脏精气不能上荣于面，故见面色㿠白；舌淡苔白，脉沉迟或细，均为命门火衰之象。","treat":"温肾填精，壮阳起痿。","formulaRaw":"赞育丹（《景岳全书》）加减。","formulaName":"赞育丹加减","fangjie":"肉苁蓉、巴戟天、蛇床子、韭菜子、淫羊藿、仙茅、肉桂、杜仲温肾壮阳补火；枸杞子、山茱萸、熟地黄、当归滋阴养血，从阴求阳；白术健脾以补后天。滑精频繁，精薄清冷者，加覆盆子、金樱子、益智仁；阴茎痿软，小腹冷痛，得温则舒，遇寒加重者，多属寒凝肝脉，合暖肝煎加减；久病人络，经络瘀阻者，加蜈蚣、水蛭、九香虫等。火衰不甚，精血薄弱，予左归丸或金匮肾气丸加减；阴阳两虚者，用还少丹加减。"},{"id":"s245","name":"心脾亏虚证","label":"4. 心脾亏虚证","group":"","clinic":"阳痿不举，遇劳加重，心悸，失眠多梦，神疲乏力，面色萎黄，食少纳呆，腹胀便溏，舌淡，边有齿痕，苔薄白，脉细弱。","analysis":"心主血脉，脾为气血生化之源，心脾亏虚，则气血生化不足，无法滋养宗筋，导致阳痿不举；心藏神，心脾亏虚，心血不足，心神失养，故见心悸，失眠多梦；脾气虚弱，运化失常，则食少纳呆，腹胀便溏；气血亏虚，机体失于濡养，则神疲乏力，面色萎黄；舌淡苔白，脉细弱，乃心脾两虚，气血乏源之象。","treat":"健脾养心，益气起痿。","formulaRaw":"归脾汤（《济生方》）加减。","formulaName":"归脾汤加减","fangjie":"党参、黄芪、白术、茯苓、炙甘草健脾益气；酸枣仁、远志养心安神；熟地黄、当归、龙眼肉养血生血；木香、香附理气解郁。气郁血瘀者，加川芎、合欢皮、延胡索；脾肾阳虚者，加淫羊藿、补骨脂、九香虫、露蜂房等；形体肥胖者，加泽泻、荷叶、薏苡仁、苍术、陈皮。"},{"id":"s246","name":"惊恐伤肾证","label":"5. 惊恐伤肾证","group":"","clinic":"临房不举，时有自举，兼见胆怯多疑，言迟声低，心悸惊惕，夜寐多梦，舌质淡，苔白，脉弦细。","analysis":"恐为肾所主，恐则气下，耗伤肾气，故临房不举；心藏神，主血脉，肾藏精，猝受惊恐，突遭不测，心伤则神不守舍，出现胆怯多疑，心悸惊惕，夜寐多梦；舌淡，苔白，脉弦细，乃肾气不足之象。","treat":"益肾宁神。","formulaRaw":"启阳娱心丹（《辨证录》）加减。","formulaName":"启阳娱心丹加减","fangjie":"人参、菟丝子、当归、白芍补益肝肾；远志、茯神、石菖蒲、酸枣仁宁心安神，交通心肾；柴胡、香附、郁金理气疏郁。惊惕不安甚者，加龙齿、磁石；失眠多梦者，加五味子、琥珀、合欢皮；心肾不交者，加黄连、肉桂；腰膝酸软者，加杜仲、肉苁蓉、海马、锁阳。有手淫史，伴有遗精、早泄、心悸、烦热、腰膝酸软、头晕耳鸣等症状，用知柏地黄丸。"}],"linchuang":["注重调养心神，整体调治。阳痿的病因复杂，非独肾虚可以致痿，也与多脏腑、多系统以及社会、心理等诸多因素有关。其中心理、情志因素是影响性功能的重要原因。心藏神，为五脏六腑之大主，心主神明正常，脏腑功能协调，气血畅顺，性功能才能正常发挥。不良情绪可以诱发和加重性功能障碍，性功能障碍亦可诱发和加重不良情绪。同时，精神紧张，情志内伤，肝气郁结引起阳痿，属“因郁致痿”；而阳痿日久，患者忧郁、悲观、焦虑等心理情绪，亦可加重阳痿，属“因痿致郁”。二者常相互影响，往往形成恶性循环。因此，疏肝开郁、养心安神是阳痿的重要治法。","用药不可过于温补。部分医家习用温肾壮阳法治疗阳痿，但若过用温燥之品，非但疗效不佳，反致肝肾阴伤，内生燥热。因肾为水火之脏，治疗应水中补火或补中有清，寓清于补，乃可使水火得其养。如确需温肾，应选用温而不燥或燥性较小的血肉有情之品，如巴戟天、肉苁蓉、菟丝子、鹿角胶，并加黄精、熟地黄等从阴引阳。此外，牛膝入肝肾，常作为引经药，蜈蚣、僵蚕、露蜂房、水蛭、灵芝等治疗阳痿有一定疗效，可适当选用。"],"yufang":["预防阳痿发生，应加强性教育，培养正确的性意识，树立良好的性道德。夫妻关系应融洽，应互相理解。节制性欲，避免恣情纵欲、房事过频、手淫过度。清心寡欲，摒除杂念，怡情养性。起居有常，饮食有节，避免过食醇酒肥甘。切忌讳疾忌医，隐瞒病情，贻误治疗时机。","阳痿患者患病之后，应正确对待疾病，树立信心，要消除顾虑，调畅情志，怡悦心情，防止精神紧张。调饮食，节房劳，适劳逸，勤锻炼，增强体质，提高整体机能。在感到情绪不快、身体不适、过度疲劳、性能力下降时，应暂停性生活一段时间，使性中枢和性器官得以调节和休息。积极治疗易造成阳痿的原发病。避免长期服用某些可能影响性功能的药物。"],"attachIds":[]},{"id":"d038","name":"遗精","kind":"main","parent":null,"chapterNo":"第四十一章","chapterName":"遗精","yinbing":[{"t":"b","x":"1. 劳神太过"},{"t":"p","x":"劳烦伤神，心阴亏虚，心阳独亢，肾水亏虚，心肾不交，虚火妄动，扰动精室而遗精。"},{"t":"p","x":"或思虑太过，损伤心脾，导致脾气下陷，心神失养，气不摄精，产生遗精。"},{"t":"b","x":"2. 欲念不遂"},{"t":"p","x":"少年气盛，情动于中，意淫于外，或心有恋慕，所欲不遂，或壮夫久旷，思慕色欲，阴精暗耗，皆令心动神摇，君相火旺，扰动精室，而成遗精。"},{"t":"b","x":"3. 恣情纵欲"},{"t":"p","x":"房事不节，或少年无知，频犯手淫，或酒醉入房，纵欲无度，日久肾精虚亏，水不制火，相火扰动精室，肾不固精，乃成遗精。"},{"t":"p","x":"如《证治要诀·遗精》所言：“有色欲过度，而滑泄不禁者。”"},{"t":"b","x":"4. 饮食不节"},{"t":"p","x":"嗜食醇酒厚味，损伤脾胃，湿浊内生，蕴而生热，湿热循经下注，或郁于肝胆，迫精下泄，均可致遗精。"},{"t":"p","x":"《张氏医通·遗精》谓：“脾胃湿热之人，及饮食厚味太过，与酒客辈，痰火为殃，多致不梦而遗泄。”"}],"bingji":[{"t":"p","x":"遗精的基本病机为肾气不固，或热扰精室，而致肾失封藏，精关不固。"},{"t":"p","x":"病变部位在肾，与心、肝、脾三脏密切相关。"},{"t":"p","x":"肾为封藏之本，受五脏六腑之精而藏之，如肾脏自病，或其他因素影响肾之封藏功能，则精关不固，精液外泄，发生遗精。"},{"t":"p","x":"若劳心太过，心有欲念，以致君火摇于上，心失主宰，则精自遗。"},{"t":"p","x":"或思虑伤脾，脾气虚弱，气不摄精，而成遗精。"},{"t":"p","x":"病理性质有虚实之别，且多虚实夹杂，病理因素有湿与火。"},{"t":"p","x":"君相火旺，湿热下注，扰动精室而遗者多属实；肾脏亏损，封藏失职而泄者多属虚。"},{"t":"p","x":"初起多因于火旺、湿热，以实证为主；久病则相火、湿热伤阴，而致肾阴亏虚，甚或阴损及阳而成阴阳两虚，或肾阳衰惫，或气阴两虚。"}],"zhenduan":[{"t":"ol","items":["1. 男子梦中遗精，每周超过2次，或清醒时，不因性生活而遗泄精液。","2. 常伴有情绪不稳、精神不振、体倦乏力、腰膝酸软、头晕心悸、失眠多梦、记忆力减退等症状。","3. 常有恣情纵欲、情志内伤、久嗜醇酒厚味等病史。"]}],"jianbie":[{"t":"b","x":"1. 早泄"},{"t":"p","x":"早泄与遗精均存在精液不自主外泄的表现，但早泄是性交时精液过早泄出，影响性生活，而遗精则为非性交时精液自行遗泄，多见于睡眠或清醒状态下。"},{"t":"p","x":"《沈氏尊生书》所言“未交即泄，或乍交即泄”明确指出了早泄的特征，以此可与遗精鉴别。"},{"t":"b","x":"2. 精浊"},{"t":"p","x":"精浊与遗精均可见尿道有精液或类似分泌物溢出的症状，但精浊常在大便时或排尿终了时发生，尿道口有米泔样或糊状分泌物溢出，并伴有阴茎作痒作痛，痛甚如刀割火灼，而遗精多为精液自然遗泄，一般不伴明显疼痛。"}],"bianzheng":[{"t":"ol","items":["1. 辨虚实新病遗精有虚有实，多虚实并见。久病精滑则虚多实少。由君相火旺所致者，为本虚标实；由心脾两虚、肾虚不藏所致者，以虚证为主；由湿热下注所致者，以实证为主。前人尚有梦遗多火、滑精多虚的认识。"]},{"t":"p","x":"《医学心悟》曰：“大抵有梦者，由于相火之强；不梦者，由于心肾之虚。”"},{"t":"p","x":"但临床也有部分遗精无梦属实、有梦属虚者，因此，辨别遗精虚实应当四诊合参。"},{"t":"ol","items":["2. 辨病位劳神过度，邪念妄想梦遗者，多责于心；精关不固，无梦滑泄者，多责于肾。对肾虚不藏者还应辨别肾阴虚、肾阳虚的主次。"]},{"t":"p","x":"《医宗必读·遗精》云：“若夫五脏各得其职，则精藏而治。苟一脏不得其正，甚者则必害心肾之主精者焉……如心病而遗者，必血脉空虚，本纵不收；肺病而遗者，必皮革毛焦，喘息不利；脾病而遗者，色黄肉消，四肢懈惰；肝病而遗者，色青而筋痿；肾病而遗者，色黑而髓空。”"}],"zhize":"实证治以清泄为主，针对君火、相火、湿热等不同，采用清心安神、清泄相火、清利湿热等法；虚证宜以补益固涩为主，如滋阴温肾、调补心脾、固涩精关等法；虚实夹杂者，治疗当补泻兼施。此外，久病夹瘀者，调补之中佐以祛瘀。阴虚湿热者，用药宜化湿不伤阴，养阴不助湿。","syndrome":[{"id":"s247","name":"君相火旺证","label":"1. 君相火旺证","group":"","clinic":"多梦遗精，阳事易举易泄，心烦，潮热，颧红，腰酸，头晕耳鸣，口干多饮，溲黄，便结，舌红苔少或薄黄，脉细数。","analysis":"肾阴不足，虚火内生，扰动精室，则多梦遗精；阴虚火旺，相火亢盛，故阳事易举；火热内扰，精室不固，则易泄；肾阴亏虚，不能上滋头目，清窍失养，故头晕耳鸣；腰为肾之府，肾阴不足，腰膝失养，故腰酸；阴虚内热，虚火上扰心神，则心烦，潮热，颧红；阴液亏耗，则口干多饮；肠道失润则便结；阴虚火旺，灼伤津液，故溲黄；舌红苔少或薄黄，脉细数，为肾阴亏虚、虚火内扰之象。","treat":"清心泻肝。","formulaRaw":"黄连清心饮（《内经拾遗》）合三才封髓丹（《医学发明》）加减。","formulaName":"黄连清心饮合三才封髓丹加减","fangjie":"黄连清心泻火，生地黄滋阴清热，当归、酸枣仁和血安神，茯神、远志宁神养心，人参、甘草益气和中，莲子补益心脾，收摄肾气；天冬、熟地黄滋肾养阴，黄柏清热泻火坚阴，砂仁行滞悦脾。心火亢盛者，加栀子、竹叶；心肾不交者，加少量肉桂。"},{"id":"s248","name":"湿热下注证","label":"2. 湿热下注证","group":"","clinic":"遗精频作，小溲黄赤，热涩不畅，口苦而黏，舌质红，苔黄腻，脉濡数或滑数。","analysis":"湿热循经扰动精室，迫精外泄，故遗精频作；湿热蕴结膀胱，气化不利，水道失畅，则见小溲黄赤，热涩不畅；湿热内蕴，胆汁上溢，故口苦而黏；舌质红，苔黄腻，脉濡数或滑数，为湿热内盛之候。","treat":"清热利湿。","formulaRaw":"草分清饮（《医学心悟》）加减。","formulaName":"草分清饮加减","fangjie":"草薜利湿化浊；车前子、白茯苓淡渗利湿；菖蒲芳香化浊；白术健脾燥湿；黄柏苦寒坚阴，清泻相火；莲子心清心；丹参行血祛瘀。口苦口黏甚者，加茵陈、佩兰、草果。肝经湿热，阴囊湿痒，小溲短赤，口苦胁痛者，用龙胆泻肝汤；痰湿郁热者，用苍术二陈汤加黄柏。"},{"id":"s249","name":"劳伤心脾证","label":"3. 劳伤心脾证","group":"","clinic":"遗精时作，劳则加重，失眠健忘，心悸气短，四肢倦怠，纳少腹胀，面色萎黄，大便溏薄，舌质淡胖，边有齿痕，舌苔薄白，脉细弱。","analysis":"脾气虚弱，运化失司，气血生化不足，肢体失养，故四肢倦怠，面色萎黄；气血亏虚，心神失养，故失眠健忘，心悸气短；脾主升清，脾虚气陷，固摄无权，精关不固，故遗精时作，劳则耗气，故劳累后加重；脾虚运化无力，故纳少腹胀；水湿不运，清浊不分，故大便溏薄；舌质淡胖，边有齿痕，苔薄白，脉细弱，为脾气虚弱之象。","treat":"调补心脾，益气摄精。","formulaRaw":"妙香散（《太平惠民和剂局方》）加减。","formulaName":"妙香散加减","fangjie":"山药益阴清热，兼能涩精；人参、黄芪固气；远志、茯苓、茯神宁神利水，泻肾中之邪火；桔梗清肺散滞；木香疏肝和脾；朱砂镇心安神；麝香通窍解郁、辟邪；甘草和中。遗精频繁者，加鸡内金、莲子、山药、芡实；中气下陷者，加升麻、柴胡、糯稻根，或用补中益气汤加减。若心脾血虚显著，可改用归脾汤治疗。"},{"id":"s250","name":"肾气不固证","label":"4. 肾气不固证","group":"","clinic":"遗精频作，多为无梦而遗，甚而滑精不禁，伴见头昏，腰膝酸软，形寒肢冷，面色㿠白，阳痿早泄，精液清冷，夜尿清长，舌质淡胖而嫩，苔白滑，脉沉细。","analysis":"肾阳不足，命门火衰，封藏失职，精关不固，故遗精频作，无梦而遗，甚则滑精不禁；阳虚失温，腰膝失养，故腰膝酸软；形寒肢冷，面色㿠白，夜尿清长，为肾阳亏虚，温煦失职，水液失司之象；肾阳不足，宗筋失养，故阳痿早泄；肾阳亏虚，精失温煦，故精液清冷；舌质淡胖而嫩，苔白滑，脉沉细，为肾阳亏虚，水湿内停之征。","treat":"补肾益精，固涩止遗。","formulaRaw":"金锁固精丸（《医方集解》）加减。","formulaName":"金锁固精丸加减","fangjie":"方中沙苑子补肾固精止遗；莲肉、芡实固肾涩精；莲须收敛固精；龙骨、牡蛎收敛固涩，涩精止遗。因情志失调，肾失固摄所致者，治应疏肝益肾，合逍遥散加减；肾阳虚为主者，加枸杞子、菟丝子、杜仲、鹿角胶、肉桂、锁阳、附子（制）；肾阴虚为主者，加熟地黄、黄柏、金樱子、龟甲、阿胶，或合左归丸。遗精日久，阴阳失调者，用桂枝加龙骨牡蛎汤；阴损及阳，阴阳两虚者，用右归丸。"}],"linchuang":["辨虚实主次，把握用药宜忌。君相火动、心肾不交之遗精，治疗以育阴潜阳、清泻君相、清热利湿为主，但养阴不可过于滋腻，以免助湿生热，清热不宜过于苦泄，以免伤阴损脾；湿热下注之遗精，不宜过早固涩，以免留邪；精滑致虚者，需视虚实、先后酌情施治，既不宜专事固涩，恐碍湿之泄化，又不能太过寒凉，以防苦寒败胃；脾胃虚弱者，益气之中调理气机升降，有助于提高疗效；肾虚不固者，需从阴中求阳，以达阴平阳秘；阳虚者当阴阳两调，不宜单纯使用温肾助阳之品，避免刚燥劫阴。","久遗不愈，标本兼顾，强化祛湿通络法。久病遗精，病机多为虚实夹杂，虚者多为脾肾不足或气阴两虚，实者常见湿热浊瘀阻滞精窍等。临证可在补益脾肾、养阴清热、育阴潜阳基础上，结合清热利湿、活血通络、养心安神等法组方。凡有忍精史，或手淫过频，少腹、会阴及睾丸坠胀疼痛，射精不畅或疼痛，精液黏稠或有硬颗粒状物夹杂其中等症，多为败精阻窍，精道瘀阻，可酌情加水蛭、蜈蚣等活血通络，通因通用。"],"yufang":["注意精神调养，排除杂念，不接触不健康影像信息，不贪恋女色。避免过度劳神，做到劳逸结合。饮食有节，起居有常，不可以酒为浆，少食醇酒厚味及辛辣刺激性食品。避免恣情纵欲，手淫过度，保持外阴清洁。","已病者应注意消除恐惧心理，生活起居规律，节制性欲。戒除手淫。晚间进食不宜过饱，睡前用温水足疗，被褥不宜过厚、过暖，衬裤不宜过紧，养成侧卧习惯。发生遗精时不可强忍或挤压阴茎，遗精后不可立即用冷水洗浴以免寒邪内侵。包茎、包皮过长或外生殖器有炎症时及早就医。"],"attachIds":["a008"]},{"id":"d039","name":"郁证","kind":"main","parent":null,"chapterNo":"第四十二章","chapterName":"郁证","yinbing":[{"t":"b","x":"1. 情志内伤"},{"t":"p","x":"七情过极，尤其愤恨恼怒、忧思疑虑，超过机体的调节能力，气机郁滞，导致郁证发生。"},{"t":"p","x":"清·尤在泾《金匮翼·积聚统论》云：“凡忧思郁怒，久不得解者，多成此疾。”"},{"t":"b","x":"2. 体质因素"},{"t":"p","x":"体质素弱，机体的调节能力低下，如遇情志刺激，多易发为郁证。如罹患重症顽疾，脏腑气血失调，因病而郁，也可导致郁证的发生。"},{"t":"p","x":"清·沈金鳌《杂病源流犀烛·诸郁源流》云：“诸郁，脏气病也。其原本由思虑过深，更兼脏气弱，故六郁之病生焉。”"}],"bingji":[{"t":"p","x":"郁证的基本病机为气机郁滞，脏腑功能失调。"},{"t":"p","x":"病变部位主要在肝，与心、脾、肾相关。"},{"t":"p","x":"病理性质初起以六郁邪实为主，日久转虚或虚实夹杂。"},{"t":"p","x":"郁证初起多以气滞为主，进而引起化火、血瘀、痰结、食滞、湿阻等病机变化，多为实证；日久伤及心、脾、肾等，致使脏腑功能失调，出现心脾两虚、心神失养、心肾阴虚，由实转虚。"},{"t":"p","x":"气郁化火多因火热伤阴，阴不涵阳，易转化为心肾阴虚。"},{"t":"p","x":"病理因素以气、血、痰、湿、食、火为主。"},{"t":"p","x":"本病多为情志所伤，始于肝失条达，气失疏泄，故以气郁为先。"},{"t":"p","x":"郁证日久不愈，病机演变多端，在因郁而病、因病而郁的过程中，每多因果错杂，从无形之气到有形之痰瘀，痰瘀胶结，耗伤脏腑精气，甚则酿毒。"}],"zhenduan":[{"t":"ol","items":["1. 以心情抑郁、情绪不宁、善太息、胁肋胀满疼痛为主要临床表现，或伴易怒易哭，或伴咽中有异物感，吞之不下，咯之不出等症状。","2. 有愤怒、忧愁、焦虑、恐惧、悲哀等情志内伤病史，病情常随情志波动而变化。","3. 多发于中青年女性，无其他病证的症状及体征。"]}],"jianbie":[{"t":"b","x":"1. 梅核气与虚火喉痹"},{"t":"p","x":"梅核气与虚火喉痹均有咽中异物感的表现。"},{"t":"p","x":"梅核气是郁证的特殊类型，多见于中年女性，自觉咽中有物梗塞，咽之不下，咯之不出，但无咽痛，进食无阻塞，不影响吞咽，其症状轻重与情绪波动有关。"},{"t":"p","x":"虚火喉痹以中年男性发病较多，多因感冒、长期吸烟饮酒及嗜食辛辣食物等引发，咽部除有异物感外，尚觉咽干、灼热、咽痒，咽部症状与情绪无关，过度辛劳或感受外邪则易加剧。"},{"t":"b","x":"2. 梅核气与噎膈"},{"t":"p","x":"梅核气与噎膈均有咽中不舒感。"},{"t":"p","x":"但噎膈主要表现为吞咽困难，食不能下，旋食旋吐，或徐徐吐出，是有形之邪阻隔于食管、贲门所致。"},{"t":"b","x":"3. 脏躁与癫证"},{"t":"p","x":"脏躁与癫证均有神志异常表现。"},{"t":"p","x":"脏躁多在精神因素刺激下呈间歇性发作，在不发作时可如常人，主要表现为烦躁不宁、易激惹、易怒易哭、时作欠伸等情绪不稳定症状，但有自知自控能力。"},{"t":"p","x":"癫证主要表现为表情淡漠，沉默痴呆，出言无序或喃喃自语，静而多喜，缺乏自知自控能力，病程迁延，症状极少自行缓解。"}],"bianzheng":[{"t":"b","x":"1. 辨受病脏腑"},{"t":"p","x":"郁证的症状纷杂，临床应根据病史及主症特点，辨明其受病脏腑侧重。六郁皆以气郁为主，但有兼血瘀、化火、痰结、湿阻、食积等不同。一般来说，气郁、血郁、火郁主要关系肝；食郁、湿郁、痰郁主要关系脾；而虚证则与心、肾的关系最为密切。"},{"t":"b","x":"2. 辨证候虚实"},{"t":"p","x":"实证病程较短，症见精神抑郁，胸胁胀痛，咽中梗塞，时欲太息，脉弦或滑。虚证病已久延，症见精神不振，心神不宁，虚烦不寐，悲忧善哭。如气血不足，或阴精亏虚，同时又伴有气滞、血瘀、痰结、火郁等病变，则成为虚实夹杂之证。"}],"zhize":"郁证以理气开郁、调畅气机、移情易性为基本治则。实证，首当理气解郁，并应根据是否兼有血瘀、火郁、痰结、湿滞、食积等，分别采用活血、降火、祛痰、化湿、消食等法。虚证，则应根据损及的脏腑及气、血、阴精亏虚的不同情况而补之，或养心安神，或补益心脾，或滋养肝肾。对于虚实夹杂者，则又当视虚实的偏重而虚实兼顾。除药物治疗外，精神调摄、心理治疗对郁证亦有极为重要的作用。","syndrome":[{"id":"s255","name":"肝气郁结证","label":"1. 肝气郁结证","group":"","clinic":"精神抑郁，情绪不宁，善太息，胸闷胁痛，痛无定处，脘闷嗳气，不思饮食，大便溏结，女子月事不调，舌质淡红，苔薄白，脉弦。","analysis":"情志所伤，肝失条达，故精神抑郁，情绪不宁；肝气郁滞，气机不畅，肝络失和，故胸闷胁痛，痛无定处，女子月事不调；肝郁气滞，胃失和降，故嗳气，不思饮食；肝气乘脾，则大便溏结；舌质淡红，舌苔薄白，脉弦，为肝气郁结之象。","treat":"疏肝解郁，理气畅中。","formulaRaw":"柴胡疏肝散（《证治准绳》）加减。","formulaName":"柴胡疏肝散加减","fangjie":"柴胡、香附、枳壳、陈皮疏肝解郁，理气畅中；川芎、芍药、甘草活血行气，柔肝缓急。若肝气犯胃，胃气上逆，见嗳气频作、脘闷不舒者，加旋覆花、代赭石、苏梗、半夏；肝气犯胃，食积不化，为兼有食郁，可合保和丸；肝脾不调，每多兼有湿郁，合平胃散；肝气郁结，气滞血瘀，妇女见经前乳胀腹痛者，加当归、丹参、益母草、红花，或改用血府逐瘀汤加减。"},{"id":"s256","name":"气郁化火证","label":"2. 气郁化火证","group":"","clinic":"急躁易怒，胸闷胁胀，口苦而干，或头痛、目赤、耳鸣，或嘈杂吞酸，或大便秘结，舌质红、苔黄，脉弦数。","analysis":"肝气郁结，郁而化火，故急躁易怒，胸闷胁胀；气郁化火，火性炎上，循经上行，则头痛、目赤、耳鸣；肝火犯胃，胃失和降，故嘈杂吞酸；气机郁滞，胃肠积热，故口苦而干，大便秘结；舌质红，苔黄，脉弦数，为肝火有余之象。","treat":"疏肝解郁，清肝泻火。","formulaRaw":"丹栀逍遥散（《内科摘要》）加减。","formulaName":"丹栀逍遥散加减","fangjie":"柴胡疏肝解郁；当归、白芍养血柔肝；白术、茯苓、甘草健脾和中；薄荷、丹皮、栀子清肝泻火。若热势较甚，见口苦、大便秘结者，加龙胆草、生大黄；肝火犯胃，肝胃郁热明显，见胁肋疼痛、嘈杂吞酸、嗳气、呕吐者，加黄连、吴茱萸，即合左金丸；肝火上炎明显，见头痛、目赤、耳鸣者，加白菊花、夏枯草、钩藤；热盛伤阴，见舌红少苔、脉细数者，去当归、白术，加生地黄、麦冬、山药、或改用滋水清肝饮。"},{"id":"s257","name":"痰气郁结证","label":"3. 痰气郁结证","group":"","clinic":"精神抑郁，胸部闷塞，胁肋胀满，咽中如有异物梗阻，吞之不下，咯之不出，舌质淡红，苔白腻，脉弦滑。","analysis":"肝气郁结，气机不畅，故精神抑郁，胸部闷塞；肝郁乘脾，脾运不健，生湿聚痰，痰气郁结于胸膈之上，故咽中如有异物梗阻，咯之不出，咽之不下；舌质淡红，苔白腻，脉弦滑，为痰气郁结之象。","treat":"行气开郁，化痰散结。","formulaRaw":"半夏厚朴汤（《金匮要略》）加减。","formulaName":"半夏厚朴汤加减","fangjie":"厚朴、紫苏理气宽胸，开郁畅中；半夏、茯苓、生姜化痰散结，和胃降逆。若湿郁气滞，见胸脘痞闷、嗳气、苔白腻者，加香附、佛手、苍术、木蝴蝶；痰郁化热，见烦躁、舌红苔黄者，加竹茹、郁金、石菖蒲、胆南星、黄芩、黄连；病久入络，见胸胁刺痛、舌质偏暗或有瘀点瘀斑、脉涩者，加郁金、丹参、降香、姜黄。"},{"id":"s258","name":"心神失养证","label":"4. 心神失养证","group":"","clinic":"精神恍惚，心神不宁，多疑易惊，悲忧善哭，喜怒无常，时时欠伸，舌质淡，苔薄白，脉弦细。","analysis":"忧郁不解，阴血内耗，神不守舍，故精神恍惚，心神不宁；心血不足，心神不安，故悲忧善哭；心火上炎，情志不宁，故喜怒无常；脾虚神疲，故时时欠伸；舌质淡，苔薄白，脉弦细，为营阴暗耗，心神失养之征。","treat":"甘润缓急，养心安神。","formulaRaw":"甘麦大枣汤（《金匮要略》）加减。","formulaName":"甘麦大枣汤加减","fangjie":"甘草甘润缓急，小麦补益心气，大枣益脾养血。若血虚生风，见手足蠕动或抽搐者，加当归、生地黄、珍珠母、钩藤；心血不足，见心悸失眠者，加酸枣仁、柏子仁、茯神；情志抑郁，气逆不降，见喘促气逆者，加木香、沉香、槟榔、枳实、乌药，即合五磨饮子。"},{"id":"s259","name":"心脾两虚证","label":"5. 心脾两虚证","group":"","clinic":"多思善虑，心悸胆怯，失眠健忘，头晕神疲，面色少华，腹胀纳差，女子月经量少色淡，淋沥不尽，舌质淡，苔薄白，脉细弱。","analysis":"思虑太过，暗耗阴血，或脾虚气血生化无源，心失所养，故心悸胆怯，少寐健忘；脾不健运，气血生化不足，故头晕神疲，面色少华；脾虚不运，胃失受纳，故腹胀纳差；脾虚不能摄血，血不归经，故女子月经量少色淡，淋沥不尽；舌质淡，苔薄白，脉细弱，为脾虚血亏之象。","treat":"健脾养心，益气补血。","formulaRaw":"归脾汤（《济生方》）加减。","formulaName":"归脾汤加减","fangjie":"党参、白术、甘草健脾益气；黄芪、当归补气养血；酸枣仁、远志、茯神、龙眼肉养心安神；木香理气醒脾，并使诸药补而不滞。若肝气郁滞，见胸胁胀满、情志不舒者，加合欢花、郁金、佛手；血虚失养，见头晕头痛者，可加川芎、熟地黄、白芍，即合四物汤；阴虚有热，见舌质红、口干、心烦者，加生地黄、麦冬、黄连。"},{"id":"s260","name":"心肾阴虚证","label":"6. 心肾阴虚证","group":"","clinic":"虚烦少寐，心悸盗汗，头晕耳鸣，五心烦热，口干咽燥，腰膝酸软，男子遗精，女子月经不调，舌质红，苔少或无苔，脉细数。","analysis":"心阴不足，虚热扰神，故虚烦少寐；阴虚内热，故心悸盗汗，五心烦热，口干咽燥；肾阴不足，髓海失充，腰府失养，故头晕耳鸣，腰膝酸软；阴虚火旺，扰动精室，精关不固，故遗精；肾阴不足，水不涵木，肝肾阴虚，故月经不调；舌质红，苔少或无苔，脉细数，为阴虚内热之象。","treat":"滋养心肾。","formulaRaw":"天王补心丹（《校注妇人良方》）加减。","formulaName":"天王补心丹加减","fangjie":"生地黄、天冬、麦冬、玄参滋阴补血，壮水以制虚火；柏子仁、酸枣仁、远志、五味子、朱砂养心安神；人参、茯苓、当归、丹参益气养血；桔梗为舟楫，载药上行，以使药力缓留于上部心经。若心肾不交，见心烦失眠、多梦遗精者，加黄连、肉桂，即合交泰丸；精关不固，见遗精较甚者，加芡实、莲须、金樱子，即合水陆二仙丹。"}],"linchuang":["重视精神调摄。本病主要由情志刺激引起，在辨证论治的基础上，重视精神治疗对于本病具有重要意义。《临证指南医案·郁》云：“盖郁证全在病者能移情易性。”努力去除致病原因，保持心情舒畅，增加户外运动，对促进疾病的好转乃至痊愈大有裨益。","治法以理气解郁为先，用药宜轻灵。《黄帝内经》谓“木郁达之”，郁证的治疗多以理气解郁为先，但理气药多辛香燥烈，久用耗气伤血，在临证选药时宜选用香橼、佛手、青皮、合欢花、玫瑰花、绿萼梅等药性平和、理气而不伤阴之品，无论郁证新久，均可选用。","郁证的调治切忌急于求成。郁证一般病程较长，用药不宜峻猛，否则欲速则不达。郁证实证的治疗，应注意理气而不耗气，活血而不破血，清热而不败胃，祛痰而不伤正，燥湿而不伤阴，消食而不伤脾；郁证虚证的治疗，应注意补益心脾而不过燥，滋养肝肾而不过腻。此外，郁证的治疗尚可配合针灸、推拿、运动、音乐及七情疗法等。"],"yufang":["素体肝郁或心脾两虚之人，尤当重视修身养性，可通过静坐、诵读、香等颐养。指导其正确对待各种事物，以良好心态处理人际关系，增强体质，规律运动，重视饮食调摄，避免忧思郁怒，对情志刺激应尽量防患于未然，未病先防。","对于已病者，医者应熟悉患者的病史，细致解释病情，使患者能正确认识和对待疾病，增强信心，解除情志致病的原因，促进郁证的好转乃至痊愈。患者应饮食清淡，忌生冷、辛辣、油腻、烟酒等。练习太极拳、八段锦等，静心养神，有利于疾病康复。"],"attachIds":[]},{"id":"d040","name":"血证","kind":"main","parent":null,"chapterNo":"第四十三章","chapterName":"血证","yinbing":[{"t":"b","x":"1. 感受外邪"},{"t":"p","x":"外邪侵袭以风、热、燥、火之邪为主，如损伤上部脉络（阳络），则引起衄血、咳血、吐血；热邪或湿热之邪损伤下部脉络（阴络），则引起尿血、便血。"},{"t":"b","x":"2. 饮食不节"},{"t":"p","x":"饮酒过多或过食辛辣厚味，滋生湿热，热伤脉络，引起衄血、吐血、便血，或损伤脾胃，脾胃气虚，血失统摄，而引起吐血、便血。"},{"t":"b","x":"3. 情志过极"},{"t":"p","x":"恼怒过度，肝郁化火，上逆犯肺，灼伤肺络，则引起衄血、咳血；肝火横逆犯胃，灼伤胃络，则引起吐血或便血。"},{"t":"p","x":"赵献可《医贯》云：“郁则火不得泄，血随火而妄行。部于经络，则从鼻而出；郁于胃脘，则从吐而出。”"},{"t":"b","x":"4. 劳欲太过"},{"t":"p","x":"神劳伤心，体劳伤脾，房劳伤肾、劳欲过度，可导致心、脾、肾气阴的损伤。若损伤于气，则气虚不能摄血，以致血液外溢，而形成衄血、吐血、便血、紫斑；若损伤于阴，则阴虚火旺、虚火迫血妄行，而致衄血、尿血、紫斑。"},{"t":"b","x":"5. 久病体虚"},{"t":"p","x":"久病阴精伤耗，阴虚火旺，迫血妄行，而致出血；或久病正气亏损，气虚不摄，血溢脉外，而致出血；或久病入络，血脉瘀阻，血不循经，而致出血。"}],"bingji":[{"t":"p","x":"血证的基本病机可归结为火热熏灼、迫血妄行，气虚不摄、血溢脉外两大类。"},{"t":"p","x":"张介宾《景岳全书·血证》云：“血本阴精，不宜动也，而动则为病。血主荣气，不宜损也，而损则为病。盖动者多由于火，火盛则迫血妄行；损者多由于气，气伤则血无以存。”"},{"t":"p","x":"病变部位主要在肺、胃、脾、肾、小肠、大肠、膀胱等脏腑，与肝有关。"},{"t":"p","x":"久病入络，血脉瘀阻，血不循经而致者，为虚实夹杂。"},{"t":"p","x":"病理因素有火热、气虚、阴虚、瘀血等。"},{"t":"p","x":"如始为火盛气逆，迫血妄行，在反复出血之后，则会导致阴血亏损，虚火内生，或因出血过多，血去气伤，以致气虚阳衰，不能摄血。"},{"t":"p","x":"出血量少者病轻，出血量多者病重，甚至可导致气随血脱的危急重症。"}],"zhenduan":[{"t":"ol","items":["1. 鼻衄凡血自鼻道外溢，而非因外伤、倒经所致者为鼻衄。鼻衄可因鼻腔局部疾病及全身疾病引起。内科范围的鼻衄主要见于某些传染病、发热性疾病、血液病、风湿热、高血压、维生素缺乏症、化学药品及药物中毒等。至于鼻腔局部病变引起者，属于五官科范畴。","2. 齿衄血自齿龈或齿缝外溢，且排除外伤所致者为齿衄。内科范围的齿衄，多由血液病、维生素缺乏症及肝硬化等疾病引起。至于齿龈局部病变引起者，属于口腔科范围。","3. 咳血血由肺、气道而来，经咳嗽而出，或觉喉痒胸闷，一咯即出，血色鲜红，或夹泡沫，或痰血相兼，痰中带血。多有慢性咳嗽、痰喘、肺痨等病史。内科范畴主要见于支气管扩张、急慢性支气管炎、肺炎、肺结核、肺癌等。肺结核、肺癌所致者需参考肺痨、癌病章。外感温热病所致者，属温病学范畴。","4. 吐血发病急骤，吐血前多有恶心、胃脘不适、头晕等症。血随呕吐而出，常夹有食物残渣。血色多为咖啡色或紫暗，亦可鲜红，大便色黑如柏油。常有胃痛、胁痛、黄疸、癥积等病史。本病主要见于上消化道出血，最常见于消化性溃疡及肝硬化所致食管胃底静脉曲张破裂，亦见于食管炎、急慢性胃炎、胃黏膜脱垂以及血液病、尿毒症等。","5. 便血大便色鲜红、暗红或紫暗，或呈柏油样，次数增多。常有胃肠病或肝病病史。内科范畴多见于胃肠道炎症、溃疡、肿瘤、息肉及憩室炎等。便血有远近之别：远血指病位在上消化道（食管、胃、十二指肠）、血便相混，色如黑漆或暗紫；近血指病位在下消化道（结肠、直肠、肛门)，血便分离或便外裹血，色多鲜红或暗红。","6. 尿血小便中混有血液或夹有血丝，而排尿无疼痛。出血量多，肉眼可见者称“肉眼血尿”；量少，需借显微镜检查可见者称“镜下血尿”，均属本病范畴。多见于尿路感染、肾结核、肾小球肾炎、泌尿系肿瘤及血液病、结缔组织病等。","7. 紫斑以肌肤出现青紫斑点或斑块，压之不褪色为主要特征。好发于四肢，尤以下肢为甚，常反复发作，可伴见鼻衄、齿衄、尿血、便血等。病因有外感、内伤之别。外感温热病热入营血之发斑属温病学范畴；本章所论内科杂病之紫斑，多见于原发性血小板减少性紫癜及过敏性紫癜，药物等因素所致的继发性血小板减少性紫癜亦属本病范畴。"]}],"jianbie":[{"t":"b","x":"1. 鼻衄与经行衄血"},{"t":"p","x":"二者均表现为鼻出血。"},{"t":"p","x":"经行衄血又名倒经、逆经，其发生与月经周期有密切关系，多于经行前期或经期出现，与内科所论鼻衄机理不同。"},{"t":"b","x":"2. 齿衄与舌衄"},{"t":"p","x":"皆属口腔出血证候。"},{"t":"p","x":"齿衄为血自齿缝、牙龈溢出，舌衄为血出自舌面，舌面上常有如针眼样出血点，与齿衄不难鉴别。"},{"t":"b","x":"3. 咳血与吐血、口腔出血"},{"t":"p","x":"三者血液均从口而出。"},{"t":"p","x":"咳血之血由肺而来，咳血之前多有咳嗽、胸闷、喉痒等症，血色多鲜红，经气道随咳嗽而出，常混有痰液；大量咳血后，可见痰中带血数天；少量咳血或没有将较多咳到口腔的血吞咽入胃则粪便不呈黑色。"},{"t":"p","x":"吐血之血自胃而来，吐血之前多有胃脘不适或胃痛、恶心等症，血经呕吐而出，常夹有食物残渣，色鲜红或紫暗，粪便多呈黑色，吐血之后无痰中带血。"},{"t":"p","x":"口腔出血是口腔部位的出血，常为纯血或随唾液而出，血量少，并有口腔、鼻咽部病变相应症状可寻，不伴咳嗽。"},{"t":"b","x":"4. 吐血与鼻腔、口腔及咽喉出血"},{"t":"p","x":"皆可见血由口出。"},{"t":"p","x":"吐血经呕吐而出，血色紫暗，常夹有食物残渣，多有胃病史。"},{"t":"p","x":"鼻腔、口腔及咽喉出血，血色鲜红，不夹食物残渣，做五官科相关检查即可明确具体部位。"},{"t":"b","x":"5. 便血与痢疾、痔疮"},{"t":"p","x":"三者均表现为下血。"},{"t":"p","x":"痢疾为脓血相兼，且有腹痛、里急后重、肛门灼热等症，初起有发热、恶寒等。"},{"t":"p","x":"便血无腹痛、里急后重、脓血相兼，与痢疾不同。"},{"t":"p","x":"痔疮属外科疾病，其大便下血的特点为便时或便后出血，常伴有肛门异物感或疼痛，做肛门直肠检查时，可发现内痔或外痔。"},{"t":"b","x":"6. 远血与近血"},{"t":"p","x":"两者均属便血。"},{"t":"p","x":"便血之远近是指出血部位距肛门的远近而言。"},{"t":"p","x":"清·吴谦《医宗金鉴·订正仲景全书·金匮要略·惊悸吐衄下血胸满瘀血病脉证并治》云：“先便后血，此远血也，谓血在胃也，即古之所谓结阴，今之所谓便血也；先血后便，此近血也，谓血在肠也，即古之所谓肠为痔下血，今之所谓脏毒、肠风下血也。”"},{"t":"b","x":"7. 肠风与脏毒"},{"t":"p","x":"两者均属近血。"},{"t":"p","x":"肠风血色鲜泽清稀，其下如溅，属风热为患。"},{"t":"p","x":"脏毒血色暗浊猛稠，点滴不畅，因湿热（毒）所致。"},{"t":"p","x":"明·戴思恭《证治要诀·大小腑门·肠风脏毒》曰：“血清而色鲜者为肠风，浊而暗者为脏毒。”"},{"t":"b","x":"8. 尿血与血淋、石淋"},{"t":"p","x":"三者均有血随尿出，但尿血与血淋以小便时痛与不痛为鉴别要点，不痛者为尿血，痛（滴沥刺痛）者为血淋。"},{"t":"p","x":"石淋则为尿中时有砂石夹杂，小便涩滞不畅，时有小便中断，尿道窘迫疼痛，或伴腰腹绞痛等症，可与二者相鉴别。"},{"t":"b","x":"9. 紫斑与出疹"},{"t":"p","x":"紫斑与出疹均有局部肤色的改变，紫斑呈点状者需与出疹的疹点区别。"},{"t":"p","x":"紫斑隐于皮内，压之不褪色，触之不碍手；疹高出于皮肤，压之褪色，摸之碍手。"},{"t":"p","x":"且两者成因、病位均有不同。"},{"t":"b","x":"10. 紫斑与温病发斑、丹毒"},{"t":"p","x":"三者均有局部肤色改变。"},{"t":"p","x":"温病发斑发病急骤，常伴有高热烦躁、头痛如劈、昏狂谵语、四肢抽搐、鼻衄、齿衄、便血、尿血、舌质红绛等，病情险恶多变。"},{"t":"p","x":"杂病发斑（紫斑）不如温病发斑急骤，常有反复发作史，也有突然发生者，虽时有热毒亢盛表现，但不具有温病传变急速的特点。"},{"t":"p","x":"丹毒属外科皮肤病，以皮肤色红如涂丹而得名，轻者压之褪色，重者压之不褪色，其局部皮肤灼热肿痛，与紫斑皮肤无灼热肿痛有别。"}],"bianzheng":[{"t":"b","x":"1. 辨病证的不同"},{"t":"p","x":"血证以出血为主症，但由于引起出血的原因以及出血部位不同，应注意辨清不同的病证。从口中而出的血液，有吐血与咳血之分；小便出血有尿血与血淋之别；大便下血则有便血、痔疮、痢疾之异。应根据临床表现、病史等加以鉴别。"},{"t":"b","x":"2. 辨脏腑病位异同"},{"t":"p","x":"同一血证，可以由不同的脏腑病变引起。如同属鼻衄，病变脏腑有在肺、在胃、在肝的不同；吐血有病在胃、在肝之别；齿衄有病在胃、在肾之分；尿血则有病在膀胱、在肾、在脾的不同；咳血则有病在肺、在肝之别；便血有病在胃、在肠、在脾之分。"},{"t":"b","x":"3. 辨证候之虚实"},{"t":"p","x":"一般初病多实，久病多虚。由火热迫血所致者属实，由阴虚火旺、气虚不摄甚至阳气虚衰所致者属虚。实热证，病势急，病程短，血色鲜红或深红，质浓稠，血涌量多，体质多壮实，兼见实热症状。阴虚证，病势缓，病程长，血色鲜红或淡红，时作时止，血量一般不多，形体偏瘦，兼见阴虚内热症状。气（阳）虚证，病多久延不愈，血色暗淡，质稀，出血量少，亦可暴急量多，体质虚弱，伴阳气亏虚症状。"}],"zhize":"治疗血证，应针对各种出血的病因、病机及相关脏腑，结合证候虚实及病情轻重而辨证论治。《景岳全书·血证》云：“凡治血证，须知其要，而血动之由，惟火惟气耳。故察火者但察其有火无火，察气者但察其气虚气实，知此四者而得其所以，则治血之法无余义矣。”概而言之，血证的治疗可归纳为治火、治气、治血三个原则。\n1. 治火火热熏灼，损伤脉络，是血证最常见的病机。根据证候虚实的不同，实火当清热泻火，虚火当滋阴降火，并应结合受病脏腑的不同，分别选用适当的方药。\n2. 治气气为血之帅，气能统血。《医贯·血症论》云：“血随乎气，治血必先理气。”实证当清气降气，虚证当补气益气。\n3. 治血在治血过程中，当遵循《血证论》提出的止血、消瘀、宁血、补虚“治血四法”。要达到治血的目的，必须根据各种证候的病因病机进行辨证论治，并适当选用凉血止血、收敛止血或祛瘀止血的方药。血止之后，还要消除离经之瘀血，并注意宁血，预防再次出血。最后是补虚，补养虚损的气血以善后。","syndrome":[{"id":"s261","name":"热邪犯肺证","label":"1. 热邪犯肺证","group":"鼻衄","clinic":"鼻燥衄血，其色鲜红，口干咽燥，或伴恶风身热，咳嗽头痛，口干痰少，舌红，苔薄，脉数。","analysis":"燥热伤肺，血热妄行，上溢清窍，故鼻燥衄血，其色鲜红；肺热壅盛，故口干咽燥，咳嗽头痛；风热外袭，故恶风身热；舌红，苔薄，脉数，为热邪犯肺之象。","treat":"清泄肺热，凉血止血。","formulaRaw":"桑菊饮（《温病条辨》）加减。","formulaName":"桑菊饮加减","fangjie":"桑叶、菊花、薄荷、连翘辛凉轻透，宣散风热；桔梗、杏仁、甘草宣降肺气，利咽止咳；芦根清热生津；牡丹皮、白茅根、墨旱莲、侧柏叶凉血止血。若肺热盛而无表证，可去薄荷、桔梗，加黄芩、栀子等；若阴伤较甚，口、鼻、咽干燥显著，可加玄参、麦冬、生地黄等。"},{"id":"s262","name":"胃热炽盛证","label":"2. 胃热炽盛证","group":"鼻衄","clinic":"鼻干衄血，血色鲜红，或兼齿衄，伴口渴欲饮，口中臭秽，烦躁便秘，舌红，苔黄，脉数。","analysis":"胃火上炎，迫血妄行，故鼻干衄血，血色鲜红，或兼齿衄；胃热炽盛，津液受损，故口渴欲饮，口中臭秽；热扰心神，故烦躁；腑气不通，故便秘；舌红，苔黄，脉数，为胃热炽盛之象。","treat":"清胃泻火，凉血止血。","formulaRaw":"玉女煎（《景岳全书》）加减。","formulaName":"玉女煎加减","fangjie":"石膏、知母清胃泻火；生地黄、麦冬养阴清热；牛膝引血下行；大蓟、小蓟、白茅根、藕节凉血止血。若大便秘结，可加生大黄等；若阴伤较甚，口渴，舌红苔少，脉细数，可加天花粉、石斛、玉竹等。"},{"id":"s263","name":"肝火上炎证","label":"3. 肝火上炎证","group":"鼻衄","clinic":"鼻衄，血色鲜红，伴口苦，烦躁易怒，两目红赤，耳鸣目眩，舌红，苔黄，脉弦数。","analysis":"肝火上炎，迫血妄行，上溢清窍，故鼻衄，血色鲜红；肝火内盛，故口苦，烦躁易怒；肝开窍于目，故两目红赤；肝火上扰清窍，故耳鸣目眩；舌红，苔黄，脉弦数，为肝火上炎之象。","treat":"清肝泻火，凉血止血。","formulaRaw":"龙胆泻肝汤（《医方集解》）加减。","formulaName":"龙胆泻肝汤加减","fangjie":"龙胆草、柴胡、栀子、黄芩清肝泻火；泽泻、车前子清利湿热；生地黄、当归、甘草滋阴养血；白茅根、蒲黄、大蓟、小蓟、藕节凉血止血。若阴液亏耗，口鼻干燥，舌红少津，脉细数，可去车前子、泽泻、当归，加玄参、麦冬、女贞子、墨旱莲等；若阴虚内热，手足心热，可加玄参、龟甲、地骨皮、知母等。"},{"id":"s264","name":"气血两虚证","label":"4. 气血两虚证","group":"鼻衄","clinic":"鼻血淡红，时作时止，或兼齿衄、肌衄，伴神疲乏力，面色㿠白，头晕心悸，夜寐不宁，舌质淡，脉细无力。","analysis":"气虚不摄，血溢清窍，故鼻血淡红，时作时止；脾虚不能统血，故或兼齿衄、肌衄；气血两虚，故神疲乏力，面色㿠白；血不养心，故头晕心悸，夜寐不宁；舌质淡，脉细无力，为气血两虚之象。","treat":"补气摄血。","formulaRaw":"归脾汤（《济生方》）加减。","formulaName":"归脾汤加减","fangjie":"党参、茯苓、白术、甘草补气健脾；当归、黄芪益气生血；酸枣仁、远志、龙眼肉补益心脾，安神定志；木香理气醒脾；阿胶、仙鹤草、茜草养血止血。"},{"id":"s265","name":"胃火炽盛证","label":"1. 胃火炽盛证","group":"齿衄","clinic":"齿龈出血，血色鲜红，伴齿龈红肿疼痛，口渴口臭，舌红，苔黄，脉洪数。","analysis":"胃火炽盛，循经上攻，灼伤血络，血溢于外，故齿龈出血，血色鲜红；胃热壅盛，上攻口齿，故见齿龈红肿疼痛，口渴口臭；舌红，苔黄，脉洪数，为里热炽盛之象。","treat":"清胃泻火，凉血止血。","formulaRaw":"加味清胃散（《校注妇人良方》）合泻心汤（《金匮要略》）加减。前方清胃凉血，后方泻火解毒。","formulaName":"加味清胃散合泻心汤加减","fangjie":"生地黄、牡丹皮、水牛角清热凉血；大黄、黄连、黄芩、连翘清热泻火；当归、甘草养血和中；白茅根、大蓟、小蓟、藕节凉血止血。若身热口渴，可加石膏、知母等；若齿龈红肿疼痛剧烈，可加升麻、玄参、大青叶等。"},{"id":"s266","name":"阴虚火旺证","label":"2. 阴虚火旺证","group":"齿衄","clinic":"齿龈出血，血色淡红，起病较缓，常因受热及烦劳而诱发，伴齿摇不坚，舌红，苔少，脉细数。","analysis":"肾阴亏虚，虚火上炎，灼伤齿龈血络，故齿龈出血，血色淡红，起病缓慢；虚火内炽，齿失濡养，故齿摇不坚；阴虚失养，故见头晕耳鸣，腰膝酸软；舌红，苔少，脉细数，为阴虚内热之象。","treat":"滋阴降火，凉血止血。","formulaRaw":"六味地黄丸（《小儿药证直诀》）合茜根散（《济生方》）加减。前方滋阴补肾，后方养阴清热，凉血止血。","formulaName":"六味地黄丸合茜根散加减","fangjie":"熟地黄、山药、山茱萸、茯苓、丹皮、泽泻养阴补肾，滋阴降火；茜草根、黄芩、侧柏叶凉血止血；阿胶养血止血。若齿衄频发，出血量多，可加白茅根、仙鹤草、藕节等；若虚火较甚，见低热，五心烦热，可加地骨皮、白薇、知母等。"},{"id":"s267","name":"燥热伤肺证","label":"1. 燥热伤肺证","group":"咳血","clinic":"喉痒咳嗽，痰中带血，血色鲜红，伴口干鼻燥，或有身热，舌红，苔薄黄少津，脉数。","analysis":"燥热之邪犯肺，肺失清肃，肺气上逆，故喉痒咳嗽；燥热灼伤肺络，则痰中带血，血色鲜红；肺津受伤，不能上润，故口干鼻燥；燥热内盛，正邪相争，可见身热；舌红，苔薄黄少津，脉数，均为燥热伤津、肺热内蕴之象。","treat":"清热润肺，宁络止血。","formulaRaw":"桑杏汤（《温病条辨》）加减。","formulaName":"桑杏汤加减","fangjie":"桑叶、栀子、淡豆豉清宣肺热；沙参、梨皮养阴清热；贝母、杏仁肃肺止咳；白茅根、茜草、藕节、侧柏叶凉血止血。若见发热，头痛，咳嗽，咽痛等症，可加金银花、连翘、牛蒡子等；若干咳无痰，或痰黏不易咳出，苔少舌红乏津，可加麦冬、玄参、天冬、天花粉等；若痰热壅肺，肺络受损，见发热，面红，咳嗽，咳血，咳痰黄稠，舌红苔黄，脉数者，可加桑白皮、黄芩、知母、大蓟、小蓟；若热势较甚，咳血较多者，可加连翘、黄芩、芦根，冲服三七粉。"},{"id":"s268","name":"肝火犯肺证","label":"2. 肝火犯肺证","group":"咳血","clinic":"咳嗽阵作，痰中带血或咳血鲜红，伴胸胁胀痛，烦躁易怒，口苦目赤，舌红苔黄，脉弦数。","analysis":"肝火亢盛，上逆犯肺，木火刑金，肺失清肃，故咳嗽阵作；火热灼伤肺络，则见痰中带血或纯血鲜红；肝经布于胸胁，火灼经络，气机不畅，故胸胁胀痛；肝火内扰，心神不宁，故烦躁易怒；肝火上炎，则口苦目赤；舌红苔黄，脉弦数，为肝火亢盛之象。","treat":"清肝泻肺，凉血止血。","formulaRaw":"泻白散（《小儿药证直诀》）合黛蛤散（《医说》）加减。前方清泻肺热，后方清肝凉血。","formulaName":"泻白散合黛蛤散加减","fangjie":"青黛、黄芩清肝凉血；桑白皮、地骨皮清泻肺热；海蛤壳、甘草清肺化痰；墨旱莲、白茅根、大小蓟凉血止血。若肝火较甚，头晕目赤，心烦易怒，可加牡丹皮、栀子等；若痰黄黏稠，咳之不畅，可加鱼腥草等；若咳血量较多，纯血鲜红，可用犀角地黄汤（以水牛角替代犀角）加三七粉（冲服）。"},{"id":"s269","name":"阴虚肺热证","label":"3. 阴虚肺热证","group":"咳血","clinic":"咳嗽痰少，痰中带血，或反复咳血，血色鲜红，伴口干咽燥，颧红，潮热盗汗，舌红苔少，脉细数。","analysis":"虚火灼肺，肺络受损，故见咳嗽痰少，痰中带血，或反复咳血，血色鲜红；肺阴亏虚，失于濡润，故口干咽燥；虚火上炎，则颧红；阴虚内热，逼津外泄，故见潮热盗汗；舌红苔少，脉细数，为阴虚有热之象。","treat":"滋阴润肺，宁络止血。","formulaRaw":"百合固金汤（《慎斋遗书》）加减。","formulaName":"百合固金汤加减","fangjie":"百合、麦冬、玄参、生地黄、熟地黄滋阴清热，养阴生津；当归、白芍柔润养血；贝母、甘草肃肺化痰止咳；白及、藕节、白茅根、茜草止血。本证常合用十灰散。若反复咳血，且咳血量较多，可加阿胶珠、三七等；若潮热甚，可加青蒿、鳖甲、地骨皮、白薇等；若盗汗甚，可加糯稻根、浮小麦、五味子、牡蛎等。"},{"id":"s270","name":"胃热壅盛证","label":"1. 胃热壅盛证","group":"吐血","clinic":"吐血色红或紫暗，常夹有食物残渣，伴脘腹胀闷，嘈杂不适，甚则作痛，口臭便秘，大便色黑，舌红，苔黄，脉滑数。","analysis":"胃热内郁，灼伤胃络，血溢脉外，随胃气上逆而出，故见吐血色红或紫暗，夹有食物残渣；热壅气滞，胃失和降，则脘腹胀闷，嘈杂不适；胃热上蒸则口臭；热盛伤津，腑气不通，故便秘；舌红，苔黄，脉滑数，均为胃中热炽之象。","treat":"清胃泻火，化瘀止血。","formulaRaw":"泻心汤（《金匮要略》）合十灰散（《十药神书》）加减。前方清胃泻火，后方清热凉血，收涩止血。","formulaName":"泻心汤合十灰散加减","fangjie":"黄芩、黄连、大黄苦寒泻火；牡丹皮、栀子清热凉血；大蓟、小蓟、侧柏叶、茜草根、白茅根清热凉血止血；棕榈炭收敛止血。且大蓟、小蓟、茜草根、大黄、牡丹皮兼有活血化瘀作用，止血而不留瘀。若胃气上逆，见恶心呕吐，可加代赭石、竹茹、旋覆花等；若热伤胃阴，见口渴，舌红而干，脉细数，可加麦冬、石斛、天花粉等。"},{"id":"s271","name":"肝火犯胃证","label":"2. 肝火犯胃证","group":"吐血","clinic":"吐血色红或紫暗，伴口苦，胁痛，心烦易怒，寐少梦多，舌红，苔黄，脉弦数。","analysis":"肝火横逆犯胃，灼伤胃络，血热妄行，故见吐血色红或紫暗；肝火内炽，循经上扰，则见口苦，胁痛；火扰心神，故心烦易怒，寐少梦多；舌红，苔黄，脉弦数，均为肝火亢盛之象。","treat":"泻肝清胃，凉血止血。","formulaRaw":"龙胆泻肝汤（《医方集解》）加减。","formulaName":"龙胆泻肝汤加减","fangjie":"龙胆草、柴胡、黄芩、栀子清肝泻火；泽泻、车前子清热利湿；生地黄、当归滋阴养血。若胁痛甚，可加郁金、制香附等；若见有积块，可加鳖甲、龟甲、牡蛎等；若血热妄行，吐血量多，可加水牛角、白茅根、赤芍、茜草、大黄炭等。"},{"id":"s272","name":"气虚血溢证","label":"3. 气虚血溢证","group":"吐血","clinic":"吐血缠绵不止，时轻时重，血色暗淡，伴神疲乏力，心悸气短，面色苍白，舌淡，脉细弱。","analysis":"中气亏虚，统摄无权，血溢胃外，故吐血缠绵；气虚不能摄血，故吐血反复发作，血色暗淡；气虚则脏腑失养，故见神疲乏力，心悸气短，面色苍白；舌淡，脉细弱，均为气虚不足、血失统摄之象。","treat":"健脾益气摄血。","formulaRaw":"归脾汤（《济生方》）加减。","formulaName":"归脾汤加减","fangjie":"人参、茯神、白术、甘草补气健脾；当归、黄芪益气生血；酸枣仁、远志、龙眼肉补心益脾，安神定志；木香理气醒脾。若气损及阳，脾胃虚寒，症见肤冷、畏寒、便溏，可改用柏叶汤；若吐血量多，易致气随血脱，出现面色苍白、汗出肢冷、脉微欲绝等症，急当用独参汤等，并结合西医方法积极救治。"},{"id":"s273","name":"肠道湿热证","label":"1. 肠道湿热证","group":"便血","clinic":"大便状若柏油，或色红黏稠，伴大便黏滞不爽，或有腹痛，口苦口臭，舌红，苔黄腻，脉濡数。","analysis":"湿热蕴结肠道，脉络受损，血溢肠中，故大便状如柏油，或色红黏稠；湿热阻滞气机，故大便黏滞不爽，或有腹痛；湿热上蒸，故口苦口臭；舌红，苔黄腻，脉濡数，为肠道湿热之象。","treat":"清化湿热，凉血止血。","formulaRaw":"地榆散（《太平圣惠方》）合槐角丸（《太平惠民和剂局方》）加减。前方清化湿热，凉血止血；后方清热止血，疏风理气。","formulaName":"地榆散合槐角丸加减","fangjie":"地榆、茜草、槐角凉血止血；栀子、黄芩、黄连清热燥湿，泻火解毒；茯苓淡渗利湿；防风、枳壳、当归疏风理气活血。若便血日久，湿热未尽而营阴已亏，可选用清脏汤或脏连丸。"},{"id":"s274","name":"热灼胃络证","label":"2. 热灼胃络证","group":"便血","clinic":"便色如柏油，或稀或稠，常有饮食伤胃史，伴胃脘疼痛，口干尿赤，舌红苔黄，脉数。","analysis":"胃热内郁，灼伤胃络，血溢肠道，故便色如柏油；热结中焦，气机不畅，故胃脘疼痛；热邪伤津，则见口干尿赤；舌红苔黄，脉数，为胃热炽盛之象。其饮食伤胃之病史，常为胃热蕴结之诱因。","treat":"清胃止血。","formulaRaw":"泻心汤（《金匮要略》）合十灰散（《十药神书》）加减。前方清胃泻火，后方清热凉血，收涩止血。","formulaName":"泻心汤合十灰散加减","fangjie":"黄芩、黄连、大黄苦寒泻火；牡丹皮、栀子清热凉血；大蓟、小蓟、侧柏叶、茜草根、白茅根清热凉血止血；棕榈炭收敛止血。若出血较多，可增加大小蓟的用量，加仙鹤草、白及、地榆、紫草、三七等；亦可选用生大黄粉调和蜂蜜口服。"},{"id":"s275","name":"气虚不摄证","label":"3. 气虚不摄证","group":"便血","clinic":"便血淡红或紫暗不稠，伴倦怠食少，面色萎黄，心悸少寐，舌质淡，脉细弱。","analysis":"中气亏虚，统摄无权，血溢胃肠，故便血淡红或紫暗；脾虚失运，故倦怠食少；气血生化不足，不能上荣于面，故面色萎黄，心悸少寐；舌质淡，脉细弱，为气血两虚之象。","treat":"益气摄血。","formulaRaw":"归脾汤（《济生方》）加减。","formulaName":"归脾汤加减","fangjie":"人参、茯神、白术、甘草补气健脾；当归、黄芪益气生血；酸枣仁、远志、龙眼肉补心益脾，安神定志；木香理气醒脾。若中气下陷，神疲气短，肛坠，可加柴胡、升麻等。"},{"id":"s276","name":"脾胃虚寒证","label":"4. 脾胃虚寒证","group":"便血","clinic":"便血紫暗，甚则色黑状如柏油，反复发作，伴脘腹隐痛，素喜热饮，面色不华，神倦懒言，平素便溏，舌淡，苔白滑，脉细。","analysis":"中焦虚寒，脾胃失于温摄，统血无力，血溢胃肠，故便血紫暗，色如柏油，反复发作；阳虚失煦，故脘腹隐痛，得温则舒，喜热饮；脾虚失运，水谷不化，故平素便溏；气血不足，故面色不华，神倦懒言；舌淡，苔白滑，脉细，为脾胃虚寒之象。","treat":"健脾温中，养血止血。","formulaRaw":"黄土汤（《金匮要略》）加减。","formulaName":"黄土汤加减","fangjie":"灶心土、炮姜温中止血；白术、附子（制）、甘草温中健脾；地黄、阿胶珠养血止血；黄芩苦寒坚阴以反佐；白及、乌贼骨收敛止血；三七、花蕊石活血止血。若阳虚甚，畏寒肢冷，可去黄芩、地黄，加鹿角霜、艾叶，炮姜易干姜。"},{"id":"s277","name":"下焦湿热证","label":"1. 下焦湿热证","group":"尿血","clinic":"小便黄赤灼热，尿血鲜红，伴心烦口渴，面赤口疮，夜寐不安，舌红，脉数。","analysis":"湿热蕴结下焦，灼伤血络，血渗膀胱，故见小便黄赤灼热，尿血鲜红；热扰心神，故心烦，夜寐不安；热盛伤津，故口渴；湿热上炎，故面赤口疮；舌红，脉数，皆为湿热内蕴、热盛于里之象。","treat":"清热利湿，凉血止血。","formulaRaw":"小蓟饮子（《济生方》）加减。","formulaName":"小蓟饮子加减","fangjie":"小蓟、生地黄、藕节、蒲黄凉血止血；栀子、通草、竹叶清热泻火；滑石、甘草利水清热，导热下行；当归养血活血。热盛而心烦口渴者，可加黄芩、天花粉等；若尿血较甚，可加槐花、白茅根等；若尿中夹有血块，可加桃仁、红花、牛膝等；若大便秘结，可加大黄。"},{"id":"s278","name":"肾虚火旺证","label":"2. 肾虚火旺证","group":"尿血","clinic":"小便短赤带血，时作时止，伴头晕耳鸣，颧红潮热，腰膝酸软，舌红苔少，脉细数。","analysis":"肾阴亏虚，虚火内炽，灼伤脉络，故小便短赤带血，时作时止；肾精不足，髓海失养，故头晕耳鸣；阴虚内热，故颧红潮热；腰为肾之府，肾虚失养，故腰膝酸软；舌红苔少，脉细数，为阴虚火旺之象。","treat":"滋阴降火，凉血止血。","formulaRaw":"知柏地黄丸（《医宗金鉴》）加减。","formulaName":"知柏地黄丸加减","fangjie":"生地黄、山药、山茱萸、茯苓、泽泻、牡丹皮滋补肾阴，“壮水之主，以制阳光”，其中生地黄、牡丹皮又可凉血化瘀以止血；知母、黄柏滋阴降火；墨旱莲、大蓟、小蓟、藕节、蒲黄凉血止血。若颧红潮热，可加地骨皮、白薇等。"},{"id":"s279","name":"脾不统血证","label":"3. 脾不统血证","group":"尿血","clinic":"久病尿血，量多色淡，甚或兼见齿衄、肌衄，伴食少便溏，体倦乏力，气短声低，面色不华，舌质淡，脉细弱。","analysis":"脾虚气弱，统血无权，血渗膀胱，故尿血量多色淡；溢于龈络则为齿衄，外渗肌肤则发肌衄；脾失健运，故食少便溏；气血不足，故体倦乏力，气短声低，面色不华；舌质淡，脉细弱，为脾虚气血不足之象。","treat":"补中健脾，益气摄血。","formulaRaw":"归脾汤（《济生方》）加减。","formulaName":"归脾汤加减","fangjie":"党参、茯苓、白术、甘草补气健脾；当归、黄芪益气生血；酸枣仁、远志、龙眼肉补心益脾，安神定志；木香理气醒脾；熟地黄、阿胶、仙鹤草、槐花养血止血。若气虚下陷而少腹坠胀，可加升麻、柴胡等。"},{"id":"s280","name":"肾气不固证","label":"4. 肾气不固证","group":"尿血","clinic":"久病尿血，血色淡红，伴头晕耳鸣，精神困惫，腰脊酸痛，舌淡，脉沉弱。","analysis":"肾气亏虚，封藏失职，血失固摄，故见久病尿血，血色淡红；肾精不足，髓海失养，故头晕耳鸣；肾阳亏虚，无以振奋神机，故精神困惫；肾主骨生髓，腰为肾之府，肾虚则腰脊失养，故腰脊酸痛；舌淡，脉沉弱，为肾气不足之象。","treat":"补益肾气，固摄止血。","formulaRaw":"无比山药丸（《太平惠民和剂局方》）加减。","formulaName":"无比山药丸加减","fangjie":"熟地黄、山药、山茱萸、怀牛膝补肾益精；肉苁蓉、菟丝子、杜仲、巴戟天温肾助阳；茯苓、泽泻健脾利水；五味子、赤石脂固涩止血；仙鹤草、蒲黄、槐花、紫珠草止血。若尿血严重，可加牡蛎、金樱子、补骨脂等；若腰脊酸痛，畏寒神怯，可加鹿角片、狗脊等。"},{"id":"s281","name":"血热妄行证","label":"1. 血热妄行证","group":"紫斑","clinic":"皮肤出现青紫斑点或斑块，斑色偏红，甚则鼻衄、齿衄、便血、尿血，伴发热口渴，便秘尿赤，舌红苔黄，脉弦数。","analysis":"热邪炽盛，壅遏脉络，迫血妄行，血溢肌肤，则见紫斑色红，伤及他处络脉，则见鼻衄、齿衄、便血、尿血；里热蒸腾，故见发热；热盛伤津，则口渴、便秘、尿赤；舌红苔黄，脉弦数，均为血热妄行之象。","treat":"清热解毒，凉血止血。","formulaRaw":"犀角地黄汤（《千金要方》）合十灰散（《十药神书》）加减。前方重在清热解毒，凉血散瘀，后方偏于凉血止血。","formulaName":"犀角地黄汤合十灰散加减","fangjie":"水牛角、生地黄、赤芍、牡丹皮、栀子清营凉血；大蓟、小蓟、侧柏叶、茜草根、白茅根清热凉血止血；棕榈皮收敛止血；大黄通腑泄热。若热毒炽盛，发热，出血广泛，可加生石膏、龙胆草、紫草，冲服紫雪丹等；若热壅胃肠，气血郁滞，症见腹痛、便血，可加白芍、甘草、地榆、槐花等；若邪热阻滞经络，关节肿痛，可加秦艽、木瓜、桑枝等。"},{"id":"s282","name":"阴虚火旺证","label":"2. 阴虚火旺证","group":"紫斑","clinic":"皮肤出现青紫斑点或斑块，时发时止，斑色偏暗，常兼鼻衄、齿衄，或月经量多，色红质稠，伴颧红头晕，口渴心烦，手足心热，或潮热盗汗，舌红苔少，脉细数。","analysis":"阴虚内热，虚火灼络，血溢肌肤，故见皮肤青紫斑点或斑块，时发时止；虚火上炎，灼伤鼻络、龈络，故见鼻衄、齿衄；扰动冲任，则月经量多，色红质稠；虚火内扰，故见心烦口渴，手足心热；阴不敛阳，故潮热盗汗；阴精亏虚，清窍失养，故见头晕；舌红少苔，脉细数，均为阴虚火旺之象。","treat":"滋阴降火，宁络止血。","formulaRaw":"茜根散（《济生方》）加减。","formulaName":"茜根散加减","fangjie":"茜草根、黄芩、侧柏叶清热凉血止血；生地黄、阿胶滋阴养血止血；甘草和中解毒。若阴虚较甚，可加玄参、龟甲、女贞子、墨旱莲等；若潮热较甚，可加地骨皮、白薇、秦艽等。若肾阴亏虚而虚火不甚，症见腰膝酸软，头晕乏力，手足心热，舌红少苔，脉细数，可用六味地黄丸，加茜草根、大蓟、槐花、紫草等。"},{"id":"s283","name":"气不摄血证","label":"3. 气不摄血证","group":"紫斑","clinic":"皮肤青紫斑点或斑块反复发作，其色偏淡，伴神疲乏力，头晕目眩，面色苍白或萎黄，食欲不振，舌淡，脉细弱。","analysis":"中气亏虚，统摄无权，血失固摄而溢于肌肤，故见青紫斑点或斑块，反复发作；脾虚失运，气血生化不足，清窍失养，则神疲乏力，头晕目眩；气血不足，不能上荣于面，故面色苍白或萎黄；脾失健运，则食欲不振；舌淡，脉细弱，皆为气虚不足、统摄无力之象。","treat":"补气摄血。","formulaRaw":"归脾汤（《济生方》）加减。","formulaName":"归脾汤加减","fangjie":"人参、茯苓、白术、甘草补气健脾；当归、黄芪益气生血；酸枣仁、远志、龙眼肉补心益脾，安神定志；木香理气醒脾；仙鹤草、棕榈炭、地榆、蒲黄、茜草根、紫草止血消斑。若肾气不足而见腰膝酸软，可加山茱萸、菟丝子、续断等。"}],"linchuang":["“治吐血三要法”与“治血四法”。缪希雍《先醒斋医学广笔记·吐血》提出“宜行血不宜止血”“宜补肝不宜伐肝”“宜降气不宜降火”的治吐血三要法，强调行血、补肝、降气在治疗吐血中的重要作用。这是对吐血治法的新发展，并带有补偏救弊的性质。应根据病情辩证地对待行血-止血、补肝-伐肝、降气-降火这三对治法。唐容川《血证论·吐血》认为治疗血证时“惟以止血为第一要法。血止之后，其离经而未吐出者，是为瘀血，既与好血不相合，反与好血不相能……必亟为消除，以免后来诸患，故以消瘀为第二治法。止血消瘀之后，又恐血再潮动，则须用药安之，故以宁血为第三法。邪之所凑，其正必虚，去血既多，阴无有不虚者矣。阴者阳之守，阴虚则阳无所附，久且阳随而亡，故又以补虚为收功之法。四者乃通治血证之大纲”。他提出止血、消瘀、宁血、补虚的“治血四法”，是通治血证之大纲，值得临床借鉴。","注意辨证与辨病互参。血证涉及西医学中的多种疾病，尤其是一些危重疾病，在诊治过程中宜辨证与辨病相结合，以提高疗效。此外，临床可将大便隐血试验阳性者归入便血，将尿液镜下见红细胞者归入尿血。","大黄治疗上消化道出血。现代药理研究证实，大黄具有多方面的止血作用。治疗急性上消化道出血，大黄常作为首选药物，可取生大黄粉，每次3～5g，每日4次，温水调服；或用蜂蜜调成浆液状口服，可以起到很好的止血消瘀作用，且蜂蜜可以减少大黄苦寒伤正之弊。","根据出血部位有针对性地选用止血药。鼻衄的主要原因是火热与瘀血，在辨证的基础上加川牛膝、白茅根、仙鹤草等，可起到引血归经、活血止血作用；亦须重视局部外治以急止其血，可用云南白药外敷、青黛粉棉球塞鼻等法。咳血可选白茅根、藕节。齿衄可选茜草根、墨旱莲。紫斑兼齿衄且出血较甚者，可用漱口药（生石膏30g，黄柏15g，五倍子15g，儿茶6g，浓煎）漱口，每次5～10分钟。吐血和便血（远血）除用大黄粉外，还可选白及、三七、地榆、灶心土等中药或云南白药等中成药。便血（近血）选生槐花、生地榆。尿血选用白茅根、小蓟、石韦、琥珀等药，既有止血作用，又能利小便。"],"yufang":["预防血证发生，宜注意气候变化，秉持“虚邪贼风，避之有时”的理念。保持精神愉快，劳逸适度，避免情志过极，防止气机郁滞。同时，应注意养护正气，以预防外邪侵袭或内伤化火而导致病证发生。","对血证患者应根据病情轻重缓急辨证施护。注意饮食有节，宜进食清淡、易于消化、富含营养的食物，如新鲜蔬菜、水果、瘦肉及蛋类，忌食辛辣香燥、油腻炙煿之品。注意消除血证患者的紧张、恐惧、忧虑等不良情绪。注意休息，密切观察病情的发展和变化，若出现头昏、心慌、出汗、面色苍白、四肢湿冷、脉微或细数等症状时，应及时救治。对吐血、便血者，应暂予禁食，积极进行抢救。"],"attachIds":[]},{"id":"d041","name":"痰饮","kind":"main","parent":null,"chapterNo":"第四十四章","chapterName":"痰饮","yinbing":[{"t":"p","x":"痰饮的发生，主要因外感寒湿、饮食不当或劳欲体虚等，导致肺、脾、肾三脏气化功能失调，三焦水道不利，津液失于正常输布与代谢，停聚于身体局部，形成有形或无形的痰饮病证。"},{"t":"b","x":"1. 外感寒湿"},{"t":"p","x":"外湿内侵，阻滞气机，致使肺失宣肃，脾失健运，水津不布，积而成饮、成痰。"},{"t":"b","x":"2. 饮食不当"},{"t":"p","x":"暴饮过量，恣饮冷水，过食生冷，或因暑热炎热后骤饮冷凉，因热贪凉，中阳猝被遏阻，脾失健运，湿从内生，水液停积成痰饮。"},{"t":"p","x":"张仲景《金匮要略·痰饮咳嗽病脉证并治》云：“夫病人饮水多，必暴喘满。凡食少饮多，水停心下，甚者则悸，微者短气。”"},{"t":"b","x":"3. 劳欲体虚"},{"t":"p","x":"阳气亏虚，水液失于温化输布，遂停蓄为痰饮。"},{"t":"p","x":"年老、久病体虚者，阳气渐衰，尤易为水湿所伤。"}],"bingji":[{"t":"p","x":"痰饮的基本病机主要为三焦气化失职，肺、脾、肾功能失调，阳虚阴盛，水液停聚。"},{"t":"p","x":"若三焦失通失宣，阳虚水液不运，必致水饮停积为患。"},{"t":"p","x":"病变部位主要在肺、脾、肾三脏，其中尤以脾为关键。"},{"t":"p","x":"此三脏之中，以脾运失司最为关键。"},{"t":"p","x":"病理性质总属阳虚阴盛，输化失调，因虚致实，水饮停积。"},{"t":"p","x":"病理因素以水饮为主。"},{"t":"p","x":"本病初期或慢性期急性发作时，多以饮邪壅盛的标实为主；久病之后，则多表现为阳气衰微的本虚为主，或虚实夹杂。"},{"t":"p","x":"若饮郁日久，可化热而成饮热相杂之证；饮阻气机，血行不畅，可兼见血瘀；饮邪内停，亦可进一步妨碍气化，加重阳虚，形成恶性循环。"},{"t":"p","x":"若因气滞、血瘀而生痰、积饮，可见痰气相搏、痰瘀互结。"},{"t":"p","x":"此外，也有虚实错杂，或貌实而本虚，或因实致虚，虚实错杂者。"}],"zhenduan":[{"t":"ol","items":["1. 痰饮心下满闷，呕吐清水痰涎，胃脘有振水音，或肠间沥沥有声，形体昔肥今瘦，属饮停胃肠。","2. 悬饮胸胁饱满，咳唾引痛（呼吸、转侧时加剧)，喘促不能平卧，或有肺痨病史，属饮流胁下。","3. 溢饮身体疼痛而沉重，甚则肢体浮肿，汗当出而不出，或伴咳喘，属饮溢肢体。","4. 支饮咳逆倚息，短气不得平卧，其形如肿，属饮邪支撑胸肺。"]}],"jianbie":[{"t":"b","x":"1. 痰饮与痰证"},{"t":"p","x":"二者皆属痰邪为患，可见咳吐痰涎。"},{"t":"p","x":"狭义痰饮其病位在胃肠，主要表现是心下满闷，呕吐清水痰涎，胃肠沥沥有声。"},{"t":"p","x":"而其他疾病中所兼夹的痰证，则以相应原发病的特有表现为主，痰证常作为阶段性病情而出现，病位也不局限在胃肠。"},{"t":"b","x":"2. 溢饮与风水证"},{"t":"p","x":"二者均可出现肢体浮肿、身体疼痛沉重，病位均涉及肌表。"},{"t":"p","x":"表实者，水肿而无汗，身体痛重，与水泛肌表之溢饮基本相同。"},{"t":"p","x":"如见肢体浮肿而汗出恶风，则属表虚，与溢饮有异。"},{"t":"b","x":"3. 支饮、伏饮与肺胀、喘证、哮病"},{"t":"p","x":"这些病证均可出现咳逆上气、喘满、咳痰等肺系症状。"},{"t":"p","x":"其发生、发展、转归均有不同，但其间亦有一定联系。"},{"t":"p","x":"如肺胀在急性发病阶段，可以表现为支饮证候；喘证的肺寒、痰饮两证，又常具支饮特点；哮证又属于伏饮范围。"}],"bianzheng":[{"t":"ol","items":["1. 辨四饮从病位而言，痰饮（狭义）病在中焦胃肠，悬饮病在肝肺所主之胸胁，溢饮病在肌表四肢，支饮病在上焦肺脏。从临床表现来看，痰饮以脘痞、腹满、肠鸣、呕吐痰涎或肠间沥沥有声为主；悬饮以胸胁胀满、咳嗽、转侧或呼吸时引起胸胁疼痛为特点；溢饮以四肢肌肤肿胀、酸困重痛甚或伴有恶寒、无汗为主症；支饮以胸闷憋喘、咳逆倚息、短气不得卧、其形如肿为主要表现。","2. 辨虚实痰饮为病，本虚标实，虚多实少。本虚为阳气不足，标实指水饮留聚。因饮为阴邪，易于困遏阳气，常表现为阳虚阴盛之证候。又有偏于阳虚，或偏于阴盛饮聚，或阳虚与阴盛俱显之不同，此与患者平素正气的强弱有关。","3. 辨寒热本病临床所见以畏寒、肢冷、口不渴、舌淡、苔白滑、脉弦紧或沉弦等寒证居多，但也有郁久化热者，可见口干不欲饮、烦热、舌苔黄腻、脉滑数等寒热错杂之象。初起若有寒热见症，为夹表邪；饮积不化，气机升降受阻，常兼气滞，进而饮郁化热，形成饮热互结之证。"]}],"zhize":"痰饮的治疗以温化为核心原则。因饮为阴邪，遇寒易聚，得温则行，通过温阳以化气，则饮易化且水易行，饮随水散。《金匮要略·痰饮咳嗽病脉证并治》提出“病痰饮者，当以温药和之”治疗原则。具体治法须根据表里虚实之不同，灵活运用温、清、消、补等法。如水饮壅盛者，应祛饮以治标；邪在表者，当温散发汗；在里者，应温化利水；正虚者补之；邪实者攻之；邪实正虚，则当消补兼施；饮邪化热，饮热相杂，又当温清并用。","syndrome":[{"id":"s284","name":"脾阳虚弱证","label":"1.脾阳虚弱证","group":"痰饮","clinic":"胸胁支满，心下痞闷，胃中有振水声，伴脘腹喜温畏冷，泛吐清水痰涎，饮人易吐，口渴不欲饮，头晕目眩，心悸气短，食少，大便或溏，形体逐渐消瘦，舌质淡，苔白滑，脉弦细而滑。","analysis":"饮停胃脘，气机阻滞，则胸胁支满，心下痞闷，胃中有振水声；阳虚寒凝，胃气上逆，则脘腹畏冷，泛吐清水，饮入易吐；津不化气，饮邪上泛，则口渴不欲饮，头晕心悸；脾虚失养，则食少，便溏，形瘦；舌质淡，苔白滑，脉弦细而滑，为阳虚湿盛、饮停正虚之象。","treat":"温脾化饮。","formulaRaw":"苓桂术甘汤（《金匮要略》)合小半夏加茯苓汤（《金匮要略》）加减。前方温阳化饮，健脾利水，后方止呕降逆，温胃蠲饮。","formulaName":"苓桂术甘汤合小半夏加茯苓汤加减","fangjie":"桂枝、生姜温脾化饮；茯苓、白术淡渗利水；甘草补气和中；陈皮、半夏理气化痰降逆。胸满痞闷者，加薤白、瓜蒌；泛吐清水者，加吴茱萸；心悸气短者，加黄芪；便溏者，加薏苡仁；苔灰滑，气短者，加附子（制）。"},{"id":"s285","name":"饮留胃肠证","label":"2.饮留胃肠证","group":"痰饮","clinic":"心下坚满或痛，自利，利后反快，或虽利，但心下续坚满，或水走肠间，沥沥有声，腹满，排便不畅，口干，舌质红，苔膩，色白或黄，脉沉弦或伏。","analysis":"饮停胃肠，气滞不通，则心下坚满或痛；饮邪下泄，则利后暂快，然饮未尽，故续坚满；水走肠间，则沥沥有声；津不布，则口干；舌质红，苔腻，色白或黄，脉沉弦或伏，为湿浊内蕴或寒热错杂、饮热互结之象。","treat":"攻下逐饮。","formulaRaw":"甘遂半夏汤（《金匮要略》)或己椒苈黄丸（《金匮要略》)加减。前方化痰逐饮，散结通脉，后方涤饮泻热，前后分消。","formulaName":"甘遂半夏汤或己椒苈黄丸加减","fangjie":"甘遂、半夏逐饮降逆；白芍、蜂蜜酸甘缓中，以防伤正；甘草与甘遂相反相激，驱逐留饮；大黄、葶苈子攻坚决壅，泻下逐水；防己、椒目辛宣苦泄，通利小便。心下坚而满者，加陈皮、厚朴、枳实；肠鸣腹满者，加桔梗、大腹皮；口干舌燥者，加天花粉、葛根。"},{"id":"s286","name":"邪犯胸肺证","label":"1.邪犯胸肺证","group":"悬饮","clinic":"咳痰胸痛，咳甚气急，伴寒热往来，身热起伏，汗少，或发热不恶寒，有汗而热不解，咳嗽，痰少，呼吸、转侧则疼痛加重，心下痞硬，舌质红，苔薄白或黄，脉弦数。","analysis":"邪犯少阳，枢机不利，故咳痰胸痛，寒热往来；热郁胸肺，津液失布，见身热起伏，汗少热不解；饮停气阻，见心下痞硬，转侧痛增；舌红苔黄，脉弦数，为少阳郁热之象。","treat":"和解宣利。","formulaRaw":"柴枳半夏汤（《医学入门》）加减。","formulaName":"柴枳半夏汤加减","fangjie":"柴胡、黄芩清解少阳；瓜蒌、半夏宽胸化痰；青皮、枳壳理气开结；赤芍和络止痛；桔梗、杏仁宣肺止咳。咳逆气急者，加白芥子、桑白皮；咳嗽而痰难出者，加浙贝母、鲜竹沥；胁痛较甚者，加郁金、桃仁、延胡索；心下痞硬，口苦，干呕者，加黄连，以配半夏、瓜蒌；身热盛而汗出，咳嗽气粗者，去柴胡，加麻黄、石膏。"},{"id":"s287","name":"饮停胸胁证","label":"2.饮停胸胁证","group":"悬饮","clinic":"胸胁疼痛，咳唾引痛，痛势较前减轻，而呼吸困难加重，伴咳逆气喘，息促不能平卧，或仅能偏卧于停饮一侧，病侧肋间胀满，甚则可见偏侧胸廓隆起，舌淡苔白，脉沉弦或弦滑。","analysis":"饮停气阻，肺气不利，则胸胁疼痛，咳唾引痛，痛减喘甚；肺失宣降，则咳逆喘促，不得平卧；水饮迫肺，则肋间胀满，胸廓隆起；舌淡苔白，主阳虚饮停；脉沉弦或弦滑，为饮聚于里之征。","treat":"泻肺祛饮。","formulaRaw":"椒目瓜蒌汤（《医醇腾义》）合十枣汤（《伤寒论》）加减。前方泻肺降气，化痰逐饮，后方攻逐水饮。","formulaName":"椒目瓜蒌汤合十枣汤加减","fangjie":"葶苈子、桑白皮泻肺逐饮；苏子、瓜蒌皮、杏仁、枳壳降气化痰；椒目、茯苓、猪苓、泽泻、冬瓜皮、车前子利水导饮；甘遂、大戟、芫花攻逐水饮。胸部满闷，舌苔浊腻者，加薤白、杏仁；水饮久停难去，胸胁支满，体弱食少者，加桂枝、白术、甘草；咳喘不减者，加桔梗、枇杷叶、杏仁。"},{"id":"s288","name":"络气不和证","label":"3.络气不和证","group":"悬饮","clinic":"胸胁疼痛，如灼如刺，伴胸闷不舒，呼吸不畅，或有闷咳，甚则迁延，经久不已，阴雨天更甚，可见病侧胸廓变形，舌暗苔薄，脉弦。","analysis":"饮郁气滞，络脉痹阻，则胸胁灼刺痛；肺气失宣，见呼吸不畅，闷咳；湿助饮邪，则阴雨加重；舌暗，脉弦，为气滞血瘀之象。","treat":"理气和络。","formulaRaw":"香附旋覆花汤（《温病条辨》）加减。","formulaName":"香附旋覆花汤加减","fangjie":"旋覆花、半夏、苏子降气化痰；柴胡、香附、枳壳疏肝理气解郁；郁金、当归、赤芍、延胡索活血止痛；茯苓、薏苡仁健脾祛饮。痰气郁阻，胸闷苔腻者，加瓜蒌、陈皮；痛势如刺者，加桃仁、红花、乳香、没药；胁痛迁延，经久不已者，加通草、路路通、冬瓜皮；正虚者，加黄芪、人参。"},{"id":"s289","name":"阴虚内热证","label":"4.阴虚内热证","group":"悬饮","clinic":"咳呛时作，胸胁闷痛，咳吐少量黏痰，伴口干咽燥，或午后潮热，颧红，心烦，手足心热，盗汗，或病久不复，形体消瘦，舌质偏红，少苔，脉细数。","analysis":"肺失濡润，气逆于上，则咳呛时作，咳吐黏痰；饮阻气机，则胸胁闷痛；虚火灼津，则口干咽燥；阴虚内热，则潮热颧红，五心烦热，盗汗形瘦；舌红少苔，脉细数，为阴虚之象。","treat":"滋阴清热。","formulaRaw":"沙参麦冬汤（《温病条辨》）合泻白散（《小儿药证直诀》）加减。前方清肺润燥，养阴生津；后方泻肺清热，止咳平喘。","formulaName":"沙参麦冬汤合泻白散加减","fangjie":"沙参、麦冬、玉竹、白芍滋养肺阴；桑白皮、桑叶、地骨皮、甘草清肺降火止咳。潮热甚者，加鳖甲、功劳叶；咳嗽黏痰者，加百部、川贝母；胸胁闷痛者，加瓜蒌皮、郁金、丝瓜络；积液未尽者，加牡蛎、泽泻；神疲气短，易出汗者，加太子参、黄芪、五味子。"},{"id":"s290","name":"表寒里饮证","label":"表寒里饮证","group":"溢饮","clinic":"身体沉重而疼痛，甚则肢体浮肿，伴恶寒无汗，或有咳喘，痰多白沫，胸闷，干呕，口不渴，舌淡苔白，脉弦紧。","analysis":"外寒闭表，卫阳被遏，则恶寒无汗，身痛；内饮犯肺则咳痰沫，阻气机则胸闷，溢肌肤则浮肿；饮逆胃脘，则干呕；津未伤，故不渴；舌淡苔白，脉弦紧，为表寒里饮之象。","treat":"解表化饮。","formulaRaw":"小青龙汤（《伤寒论》）加减。","formulaName":"小青龙汤加减","fangjie":"麻黄、桂枝解表散寒；半夏、干姜、细辛温化寒饮；五味子、芍药收敛肺气，以缓和麻、桂辛散太过；炙甘草甘缓和中。若表寒外束，内有郁热，伴有发热、烦躁、苔白兼黄者，加石膏；水饮内聚，见肢体浮肿明显、尿少者，加茯苓、猪苓、泽泻；喘息痰鸣不得卧者，加杏仁、射干、葶苈子。"},{"id":"s291","name":"寒饮伏肺证","label":"1.寒饮伏肺证","group":"支饮","clinic":"咳逆喘满不得卧，伴痰吐白沫量多，经久不愈，天冷受寒加重，甚至引起面浮跗肿，或平素伏而不作，遇寒即发，发则寒热，背痛，腰痛，目泣自出，身体振振腘动，舌质淡，苔白滑或白腻，脉弦紧。","analysis":"寒饮伏肺，肺失宣降，故咳喘痰多；饮溢肌表，则面浮跗肿；寒束卫阳，则身晌寒热；舌淡苔白滑，脉弦紧，为寒饮内伏之象。","treat":"宣肺化饮。","formulaRaw":"小青龙汤（《伤寒论》）加减。","formulaName":"小青龙汤加减","fangjie":"麻黄、桂枝解表散寒；干姜、细辛温肺化饮；半夏、厚朴、苏子、杏仁化痰降气；五味子收敛肺气。若饮邪壅实，咳逆喘急，胸痛烦闷者，加甘遂、大戟；肺虚易汗者，用苓甘五味姜辛汤；饮多寒少，外无表证，喘咳痰稀，或不得息，胸满气逆者，用葶苈大枣泻肺汤加白芥子、莱菔子；久病邪实正已虚，饮郁化热，喘满胸闷，心下痞坚，烦渴，面色黧黑，苔黄而腻，脉沉紧，或经吐下而不愈者，用木防己汤；水邪结实者，去石膏，加茯苓、芒硝。"},{"id":"s292","name":"脾肾阳虚证","label":"2.脾肾阳虚证","group":"支饮","clinic":"喘促动则为甚，心悸气短，或咳而气怯，痰多胸闷，伴怯寒肢冷，神疲，少腹拘急不仁，脐下动悸，小便不利，足跗浮肿，或吐涎沫，头目昏眩，舌质淡胖，苔白润或腻，脉沉细而滑。","analysis":"阳虚饮停，饮凌心肺，则喘悸；阳虚失却温煦，则怯寒肢冷；水饮上泛，则浮肿昏眩；舌淡胖，苔白腻，脉沉细滑，为阳虚饮停之象。","treat":"温脾补肾，以化水饮。","formulaRaw":"金匮肾气丸（《金匮要略》）合苓桂术甘汤（《金匮要略》）加减。前方温肾化气行水，后方温阳健脾利水。","formulaName":"金匮肾气丸合苓桂术甘汤加减","fangjie":"桂枝、附子（制）温阳化饮；黄芪、山药、白术、炙甘草补气健脾；苏子、干姜、款冬花化饮降逆；钟乳石、沉香、补骨脂、山茱萸补肾纳气；泽泻、茯苓利水化饮。若痰涎壅盛，食少痰多者，加半夏、陈皮；水湿偏盛，足肿，小便不利，四肢沉重疼痛者，加薏苡仁、猪苓、泽兰；津血同源，痰瘀互生，久病唇舌发绀者，加泽兰、川牛膝、益母草。脐下悸，吐涎沫，头目昏眩，是饮邪上犯，虚中夹实之候者，用五苓散。"}],"linchuang":["扶正与祛邪需斟酌。痰饮为病，阴盛阳虚者，健脾温肾为正治之法，发汗、利水、攻逐，乃属治标权宜，待水饮渐去，仍当温补脾肾，扶正固本。若痰饮壅盛，其证属实，可相机采用攻下逐饮、理气分消等法，以祛其邪。攻下伤正，因此在攻下之后又当扶脾益气以固其本。还当注意区分痰饮是病理产物，还是导致当前病证的因素。素有伏饮而发病者，是因饮而致病；先病而后出现痰饮者，是因病生饮，临证需分清主次。","注意病证转化。痰饮的病机常表现为脾病及肺、脾病及肾、肺病及肾。若肾虚开阖不利，痰饮也可凌心、射肺、犯脾。此外，痰饮多为慢性病，病程日久，常有寒热虚实之间的相互转化。而且饮积可以生痰，痰瘀互结，证情更加缠绵。故应注意对本病的早期治疗，久病者应痰瘀并治。","辨别痰的形质。痰的形质，可分为有形之痰和无形之痰。本节之痰饮属有形之痰。无形之痰，亦由体内水液不归正化所致，并以无形的形式反映疾病过程中多种复杂症状、体征的内在本质。如痰滞在经所导致的或痒或麻或痛痹，痰浊上犯清窍所致头昏、眩晕、耳鸣、口眼歪斜，痰闭胸阳所致胸痹胸痛等，均属无形之痰。古人所谓百病多有兼痰者、怪病多从痰治等，多指无形之痰。"],"yufang":["预防痰饮发生，宜顾护脾胃阳气，避免进食生冷油腻、炙煿厚味及过度饮酒，以免助湿生痰。居处应避免潮湿阴冷，适时增减衣物，防范外邪侵袭。同时需调畅情志，避免忧思气结。","既病之后，应及早诊治，辨明停饮的部位与性质。饮食忌生冷及黏腻。保持心境平和，起居需保暖防寒，居住环境宜干燥通风，适当进行和缓的运动。若见咳喘剧烈、胸闷气急、不得平卧或腹大如鼓、尿闭呕恶等危重征象，应卧床休息，采取半卧位或坐位，密切观察神志、呼吸、脉象及二便情况，及时采取综合治疗，以防发生喘脱、神昏等危急变证。"],"attachIds":[]},{"id":"d042","name":"消渴","kind":"main","parent":null,"chapterNo":"第四十五章","chapterName":"消渴","yinbing":[{"t":"p","x":"消渴是禀赋不足、饮食不节、情志失调、劳欲过度等原因，引起人体阴津亏损，燥热偏盛所致。"},{"t":"b","x":"1. 禀赋不足"},{"t":"p","x":"先天禀赋不足，肾精亏虚，易发消渴。"},{"t":"p","x":"先天禀赋不足，阴虚体质者最易罹患本病。"},{"t":"p","x":"《灵枢·五变》云：“五脏皆柔弱者，善病消瘅。”"},{"t":"b","x":"2. 饮食不节"},{"t":"p","x":"过食肥甘厚味、辛辣香燥之品，易伤脾胃，致运化失职，湿浊内生，湿热内蕴，伤津耗液，而致口渴多饮。"},{"t":"b","x":"3. 情志失调"},{"t":"p","x":"长期情志刺激，如郁怒伤肝，肝气郁结不得疏泄，或劳心竭虑，营谋强思等，郁久化火伤阴，或木旺克土，脾胃损伤，积热化燥，或消灼肺胃阴津，发为消渴。"},{"t":"b","x":"4. 劳欲过度"},{"t":"p","x":"房事不节，精气亏损，虚火内生，火因水竭益烈，水因火烈益干，终致肾虚、肺燥、胃热俱现、可见“三多一少”表现。"},{"t":"p","x":"《外台秘要·卷十一》云：“房室过度，致令肾气虚耗，下焦生热，热则肾燥，肾燥则渴。”"}],"bingji":[{"t":"p","x":"消渴的基本病机为阴虚燥热。"},{"t":"p","x":"病位主要在肺、脾胃、肾，但以肾为关键，三者之间互相影响，又有所侧重。"},{"t":"p","x":"病理性质为本虚标实，阴虚为本，燥热为标，且二者互为因果，阴愈虚则燥热愈盛，燥热愈盛则阴愈虚。"},{"t":"p","x":"肺燥津伤，脾胃失养，肾精不得滋助；脾湿胃燥，上灼肺津，下耗肾阴；肾阴虚火旺，上灼肺胃，终致肺燥、胃热、肾亏，故三多之症常并见。"},{"t":"p","x":"《临证指南医案·三消》云：“三消一证，虽有上、中、下之分，其实不越阴亏阳亢，津涸热淫而已。”"},{"t":"p","x":"消渴为患，热伤津液，可为湿热、痰热；煎熬血液，则为瘀热。"},{"t":"p","x":"因此，消渴病理因素有燥、热、湿、痰、瘀等。"},{"t":"p","x":"消渴的病机转化主要有二：一为燥热耗伤阴津，阴阳互根互用，阴损及阳，转化为气阴两伤，或阴阳俱虚，甚则肾阳虚衰。"},{"t":"p","x":"血瘀与燥热相合，瘀热相搏，导致病情加重或变证丛生。"},{"t":"p","x":"《血证论·发渴》云：“瘀血发渴者，以津液之生，其根出于肾水……胞中有瘀血，则气为血阻，不得上升，水津因不能随气上布。”"},{"t":"p","x":"消渴日久可发生多种变证，涉及多个脏腑经络。"}],"zhenduan":[{"t":"ol","items":["1. 以口渴多饮、多食易饥、尿频量多、形体消瘦或尿有甜味等为主症。","2. 如“三多”症状不显著，但中年之后，嗜食膏粱厚味、醇酒炙煿，出现眩晕、肺痨、胸痹、中风、雀目、疮痈等病证者，应考虑消渴的可能性。","3. 本病的发生与禀赋不足有关。"]}],"jianbie":[{"t":"b","x":"1. 口渴症"},{"t":"p","x":"两者均可出现口渴多饮的表现，但口渴症指口渴饮水的一个临床症状，可出现于多种疾病过程中，尤以外感热病多见，随其所患病证的不同而出现相应伴随症状，不伴多食、多尿、尿有甜味、消瘦等消渴的特点。"},{"t":"b","x":"2. 瘿病"},{"t":"p","x":"消渴之中消与瘿病之气郁化火、阴虚火旺证均可出现多食易饥、消瘦等表现，瘿病以情绪激动、心悸、眼突、颈部一侧或两侧肿大为特征，且无消渴病的多饮、多尿、尿有甜味等症。"}],"bianzheng":[{"t":"ol","items":["1. 辨病位消渴如有典型“三多”症状，可根据其程度的轻重不同，分为上、中、下三消，病机分别为肺燥、胃热脾虚、肾虚。肺燥以多饮症显著，称为上消；胃热脾虚以多食症显著，称为中消；肾虚以多尿症显著，称为下消。如临床三消症状不明显，可从体质和主症特点详辨病位所属。","2. 辨标本本病以阴虚为本，燥热为标，且两者互为因果。随着病程及病情的变化，阴虚与燥热表现可出现不同侧重。一般初病多以燥热为主，久则以阴虚为主，进而由于阴损及阳，导致阴阳俱虚。病程较长者则阴虚与燥热互见，且常见耗气津伤，脉络瘀阻。此外，本病亦有初起即见脾气亏虚者。","3. 辨本症与并发症多饮、多食、多尿、乏力、消瘦为消渴的本症表现，但其显著程度有较大的个体差异，临证当注意细心分析辨别。多数患者先见本症，随着病情的发展而出现并发症。少数中老年患者，本症不明显，常以痈疽、眼疾、心脑病证等为线索，确诊为本病。"]}],"zhize":"消渴以清热润燥、养阴生津为基本治则。《医学心悟·三消》云：“治上消者，宜润其肺，兼清其胃”，“治中消者，宜清其胃，兼滋其肾”，“治下消者，宜滋其肾，兼补其肺”。其深得治疗消渴要旨。此外，针对消渴不同阶段及并发症的病机特点，合理选用益气养阴、健脾补肾、清热燥湿、凉血化瘀、清热解毒等治法。","syndrome":[{"id":"s293","name":"肺热津伤证","label":"肺热津伤证","group":"上消","clinic":"口渴多饮，口舌干燥，尿频量多，烦热多汗，舌边尖红，苔薄黄，脉洪数。","analysis":"肺主治节，为水之上源，肺热津伤，津液敷布失常，故口渴多饮，口舌干燥；水液不能输布而直趋下行，随小便排出体外，见尿频量多；烦热多汗，舌边尖红，苔薄黄，脉洪数，均为肺热炽盛之象。","treat":"清热润肺，生津止渴。","formulaRaw":"消渴方（《丹溪心法》）加减。","formulaName":"消渴方加减","fangjie":"天花粉、葛根、麦冬、生地黄、藕汁生津清热，养阴增液；黄连、黄芩、知母清热降火。若烦渴不止，小便频数，脉数乏力者，可用玉泉丸或二冬汤。"},{"id":"s294","name":"胃热炽盛证","label":"1.胃热炽盛证","group":"中消","clinic":"多食易饥，口渴，尿多，形体消瘦，大便干燥，舌红苔黄，脉滑实有力。","analysis":"胃火内盛，消谷善饥，故多食易饥；胃热炽盛，灼伤津液，则口渴；热邪下移小肠与膀胱，水液输布失司，故尿多；胃火亢盛，壮火食气，消谷耗精，故消瘦；胃火下传大肠，肠热津亏，肠道失润，出现大便干燥；胃火内炽，蒸腾胃中浊气上泛，则见舌红苔黄；脉滑实有力，为胃火旺盛之象。","treat":"清胃泻火，养阴增液。","formulaRaw":"玉女煎（《景岳全书》）加减。","formulaName":"玉女煎加减","fangjie":"生石膏、知母、黄连、栀子清胃泻火；玄参、生地黄、麦冬滋肺胃之阴；川牛膝活血化瘀，引热下行。若大便秘结不行，加大黄，待大便通后再转上方治疗；若口渴难耐，舌红少津，加乌梅；若火旺伤阴，舌红而干，脉细数，方用竹叶石膏汤。本证亦可选用白虎加人参汤，益气养胃，清热生津。"},{"id":"s295","name":"气阴亏虚证","label":"2.气阴亏虚证","group":"中消","clinic":"口渴引饮，能食与便溏并见，或饮食减少，精神不振，四肢乏力，体瘦，舌质淡红，苔白而干，脉弱。","analysis":"阴虚津亏，故口渴引饮；胃强脾弱，故能食与便溏并见；脾气不健，则饮食减少，精神不振，四肢乏力，体瘦；舌质淡红，苔白而干，为气阴两虚，津液不足之象；脉弱，为气虚血行无力之征。","treat":"益气健脾，生津止渴。","formulaRaw":"七味白术散（《小儿药证直诀》）加减。","formulaName":"七味白术散加减","fangjie":"黄芪、党参、白术、茯苓、山药、甘草益气健脾；木香、藿香醒脾行气散津；葛根升清生津；天冬、麦冬养阴生津。若肺有燥热，加地骨皮、知母、黄芩；若口渴明显，加天花粉、生地黄、乌梅；若气短汗多，加五味子、山茱萸；若食少腹胀，加砂仁、鸡内金。"},{"id":"s296","name":"肾阴亏虚证","label":"1.肾阴亏虚证","group":"下消","clinic":"尿频量多，浑浊如脂膏，或尿有甜味，腰膝酸软，乏力，头晕耳鸣，口干唇燥，皮肤干燥、瘙痒，舌红苔少，脉细数。","analysis":"肾阴不足，虚火内炽，下焦热盛，煎熬津液，则尿频量多；肾阴亏虚，虚热内生，封藏失司，精微失运，故尿浑浊如脂膏或尿有甜味；肾精不足，腰府失养，故腰膝酸软，乏力；肾阴亏虚，髓海失充，清窍失养，见头晕耳鸣；阴虚火旺，灼伤津液，肌肤失养，见口干唇燥，皮肤干燥、瘙痒；舌红苔少，脉细数，为阴虚火旺之象。","treat":"滋阴固肾。","formulaRaw":"六味地黄丸（《小儿药证直诀》）加减。","formulaName":"六味地黄丸加减","fangjie":"熟地黄、山茱萸固肾益精；山药滋补脾阴，固摄精微；茯苓健脾渗湿；泽泻、牡丹皮清泄火热。五心烦热，盗汗，失眠者，加知母、黄柏；尿量多而浑浊者，加益智仁、桑螵蛸；神昏，肢厥，脉微细者，合参附龙牡汤。烦渴，头痛，唇红舌干，呼吸深快者，用生脉散加天冬、鳖甲、龟甲。"},{"id":"s297","name":"阴阳两虚证","label":"2.阴阳两虚证","group":"下消","clinic":"小便频数，浑浊如膏，甚至饮一溲一，面容憔悴，耳轮干枯，腰膝酸软，四肢欠温，畏寒肢冷，阳痿或月经不调，舌苔淡白而干，脉沉细无力。","analysis":"肾气不固，固摄无权，故而小便频数，甚则饮一溲一，浑浊如膏；阴液耗伤，则面容憔悴，耳轮干枯；肾气不足，肾阳虚衰，不能温煦四肢，可见腰膝酸软，四肢欠温，畏寒肢冷，阳痿或月经不调；舌苔淡白而干，脉沉细无力，均为阴阳两虚，阴液不足，阳气衰微之象。","treat":"滋阴温阳，补肾固涩。","formulaRaw":"金匮肾气丸（《金匮要略》）加减。","formulaName":"金匮肾气丸加减","fangjie":"熟地黄、山茱萸、枸杞子、五味子补肾固精；山药滋补脾阴，固摄精微；茯苓健脾渗湿；附子(制）、肉桂温肾助阳。尿多而浑浊者，加益智仁、桑螵蛸、覆盆子、金樱子；肢体困倦，气短乏力者，加党参、黄芪、黄精；阳痿者，加巴戟天、淫羊藿、肉苁蓉；畏寒者，加鹿茸粉（0.5g冲服）。"}],"linchuang":["消渴与糖尿病关系密切。糖尿病多起病隐匿，不少患者开始“三多一少”症状并不显著，甚至出现并发症后方被确诊，失去防治先机，故强调早诊断、早治疗。中医药在改善消渴症状、防治并发症方面有自身特色与优势，但单就降低血糖效果而言不如西药见效迅速，对于血糖难以控制的患者，常需配合降糖药物综合治疗，避免因血糖过高而发生呕吐、痉证、厥证等危象。","消渴不同阶段的辨治。消渴的基本病机是阴虚燥热，但在不同阶段尚有湿热、瘀热等病机，应重视清热燥湿、凉血化瘀法的配伍使用，前者药如黄连、黄柏、苍术，或葛根芩连汤等，后者药如丹参、川芎、郁金、红花、泽兰、鬼箭羽等，甚者加水蛭等虫类中药以通络，可提高疗效。并发白内障、雀盲、耳聋者，病机为肝肾精血不足，不能上承耳目，宜滋补肝肾，益精补血，可选用杞菊地黄丸治疗。并发疮毒痈疽者，治宜清热解毒，消痈散结，可选用五味消毒饮加减治疗。并发肺痨、水肿、胸痹、中风者，可参考相关章节辨证论治。此外，本病治疗应注意清热不可过用苦寒，避免损伤脾胃，耗津伤气；对脾气亏虚者，益气不可过用温燥，可甘温益气与养阴合用，重在健脾升清，益肾摄精。","注重生活方式调摄。饮食不节是消渴病的重要病因，控制饮食对于消渴病的治疗具有重要意义。严格且合理的饮食控制，是治疗本病的基础。《素问·腹中论》云：“夫子数言热中消中，不可服膏粱、芳草、石药。”《景岳全书》云：“消渴病，其为病之肇端，皆膏粱肥甘之变，酒色伤劳之过，皆富贵人病之，而贫贱者少有也。”合理运动是防治消渴病的有效措施，应以不疲劳为度，根据病情选择散步、导引、游泳、舞蹈等健身方式。此外，要注重情志调理，保持心情舒畅，节喜怒，减思虑，有利于病情的控制和康复。"],"yufang":["预防消渴的发生，调理脾胃、保护胃气十分重要。平日应注意饮食，不饮酒，少食肥甘，并适当多食健脾利湿的食物。日常生活中注意调节情志，保持乐观的精神状态。对于中年肥胖之人，加强运动，改善痰湿体质，对消渴的预防也具有积极的意义。","已发消渴，宜注重生活调摄，长期坚持合理的饮食调控，制订适合的食疗方案。养成良好的饮食习惯，不偏食，不挑食。副食荤素搭配，种类要多；主食粗细搭配，数量应少。少食多餐，不饮酒，不吃零食。平素应适当多食用豆类和新鲜蔬菜等食物。适当运动，保持情志平和。"],"attachIds":[]},{"id":"d043","name":"汗证","kind":"main","parent":null,"chapterNo":"第四十六章","chapterName":"汗证","yinbing":[{"t":"p","x":"汗证的发生主要是由体虚久病、情志失调、饮食不节等导致肌表疏松，表虚不固，腠理开泄，津液不能自藏，或火热逼迫津液，而成本病。"},{"t":"b","x":"1. 体虚久病"},{"t":"p","x":"肺虚气弱之人，肌表疏松，表虚不固，腠理开泄，而致自汗；营阴不足，阴虚生内热，虚热迫津外泄，可见盗汗。"},{"t":"p","x":"表虚之人微受风邪，导致营卫不和，卫外失司，亦致汗出。"},{"t":"b","x":"2. 情志失调"},{"t":"p","x":"若情志不舒，肝郁化火，邪热郁蒸，迫津外泄，表现为腋下、阴部汗出，甚或衣服黄染。"},{"t":"p","x":"心气不足，固守不及，则自汗出；血不养心，心液不藏，导致自汗或盗汗。"},{"t":"b","x":"3. 饮食不节"},{"t":"p","x":"嗜食辛辣厚味，损伤脾胃，酿湿成热，湿热内蕴，迫津外泄，表现为蒸蒸汗出，头面部汗出较甚，食后尤显。"}],"bingji":[{"t":"p","x":"汗证的基本病机是阴阳失调，腠理不固，营卫失和，津液外泄为汗。"},{"t":"p","x":"病变部位主要在心、肺、脾、胃、肝、肾。"},{"t":"p","x":"病理因素有气虚、血虚、阴虚、湿热。"},{"t":"p","x":"病理性质有虚实之分，但以虚居多。"},{"t":"p","x":"一般自汗多为气虚，盗汗多为阴虚。"},{"t":"p","x":"属实证者，多由肝火或湿热郁蒸所致。"},{"t":"p","x":"但虚实之间每可兼见，或相互转化。"},{"t":"p","x":"虚证自汗日久可伤阴，盗汗久延则伤阳，以致出现虚实兼夹之证。"},{"t":"p","x":"汗证的病机转化多端，如邪热郁蒸日久，伤阴耗气，转为虚证；虚证亦可兼有火旺或湿热症状。"}],"zhenduan":[{"t":"ol","items":["1. 不因外界环境的影响，头面、颈胸、四肢或全身汗出为本病的主要临床症状。","2. 寤时汗出，动辄益甚者为自汗；寐中汗出，醒来即止者为盗汗。","3. 有病后体虚、表虚受风、情志不舒、嗜食辛辣等易引起自汗、盗汗的病因存在。"]}],"jianbie":[{"t":"b","x":"1. 脱汗"},{"t":"p","x":"脱汗发生于病情危重之时，正气欲脱，阳不敛阴，以致汗液大泄，表现为大汗淋漓或汗出如珠，常同时伴有声低息短、精神疲惫、四肢厥冷、脉微欲绝或散大无力等症状，为病势危急的征象，又称“绝汗”。"},{"t":"p","x":"其汗出的情况及病情的程度均较汗证为重。"},{"t":"b","x":"2. 战汗"},{"t":"p","x":"战汗发生于急性热病过程中，症见发热烦渴，突然全身恶寒战栗，继而汗出，热势渐退，为正气抗邪的表现。"},{"t":"p","x":"若正胜邪退，则病趋好转。"},{"t":"p","x":"与阴阳失调、营卫不和之汗证迥然有别。"},{"t":"b","x":"3. 黄汗"},{"t":"p","x":"黄汗以汗出色黄如柏汁、染衣着色为特点，多因湿热内蕴所致。"},{"t":"p","x":"可以为汗证中的邪热郁蒸型，但汗出色黄的程度较重。"}],"bianzheng":[{"t":"ol","items":["1. 辨阴阳虚实自汗多属气虚不固，盗汗多属阴虚内热。因肝火、湿热等邪热郁蒸所致者，则属实证。病程较久或病重者，会出现阴阳虚实错杂的情况。自汗久则伤阴，盗汗久则伤阳，出现气阴两虚或阴阳两虚之证。","2. 辨自汗、盗汗不因外界环境因素的影响，寤时汗出，动辄益甚者为自汗；寐中汗出，醒来自止者为盗汗。","3. 辨伴随症状动辄汗出，气短，平时易患感冒，属肺卫气虚；汗出，伴有恶风，周身酸楚，时寒时热，属营卫不和；盗汗，伴有五心烦热，潮热，颧红，口干，属阴虚火旺；自汗或盗汗，伴有心悸失眠，头晕乏力，面色不华，属心血不足；汗出，伴有脘腹胀闷，大便燥结，或口苦，烦躁，多属肝经湿热。","4. 辨汗出部位头面汗出，食后尤甚，手足汗出，多为湿热蕴蒸；腋下、阴部汗出，多属肝经有热；半身或局部汗出，多为营卫不和；心胸部汗出，多为心脾两虚，心血不足；遍身汗出，鼻尖尤甚，多为肺气不足。"]}],"zhize":"汗证以虚为主者，当根据证候的不同而治以益气、养阴、补血、调和营卫；以实为主者，治当清肝泄热、化湿和营；虚实夹杂者，则根据虚实的主次而适当兼顾。此外，汗证均以腠理不固、津液外泄为共同病理变化，故皆可配伍固涩、敛汗之法，以增强止汗的功能。","syndrome":[{"id":"s298","name":"肺卫不固证","label":"1. 肺卫不固证","group":"","clinic":"汗出恶风，稍劳尤甚，易于感冒，体倦乏力，面色少华，舌淡，苔薄白，脉细弱","analysis":"肺气亏虚，肌表疏松，表卫不固，故汗出恶风，易于感冒；劳则耗气，气不摄汗，故稍劳汗出尤甚；体倦乏力，面色少华，舌淡，苔薄白，脉细弱，为气虚之象。","treat":"益气固表。","formulaRaw":"玉屏风散（《究原方》）加减。","formulaName":"玉屏风散加减","fangjie":"黄芪益气固表止汗；生白术健脾益气，助黄芪益气固表；少佐防风走表散邪，且助黄芪固表。气虚者，加党参；阴虚，舌红少苔，脉细数者，加麦冬、五味子。阳虚，面色㿠白，畏寒肢冷，脉沉细迟缓者，用黄芪附子汤或桂枝加附子汤加减；半身或局部出汗者，用桂枝汤合甘麦大枣汤。"},{"id":"s299","name":"阴虚火旺证","label":"2. 阴虚火旺证","group":"","clinic":"夜寐盗汗，或有自汗，五心烦热，或兼午后潮热，两颧色红，口渴，舌红少苔，脉细数。","analysis":"虚火内灼，迫津外泄，故夜寐盗汗，或有自汗；虚热内蒸，故五心烦热，或午后潮热明显，两颧色红；阴液不足，故口渴；舌红少苔，脉细数，为阴虚火旺之象。","treat":"滋阴降火。","formulaRaw":"当归六黄汤（《兰室秘藏》）加减。","formulaName":"当归六黄汤加减","fangjie":"当归、生地黄、熟地黄滋阴养血，壮水之主，以制阳光；黄连、黄芩、黄柏苦寒清热，泻火坚阴；黄芪益卫固表。汗出多者，加牡蛎、浮小麦、糯稻根；潮热者，加秦艽、银柴胡、白薇。以阴虚为主，火热不甚，潮热、脉数等不显者，用麦味地黄丸加减。"},{"id":"s300","name":"心血不足证","label":"3. 心血不足证","group":"","clinic":"自汗或盗汗，心悸怔忡，失眠多梦，神疲气短，面色少华，舌淡苔白，脉细。","analysis":"血不养心，以致心液不藏，心神不宁，故自汗或盗汗，心悸怔忡，失眠多梦；血虚不能濡养经脉及上荣头面，故神疲气短，面色少华；舌淡苔白，脉细为血虚之象。","treat":"养血补心。","formulaRaw":"归脾汤（《济生方》）加减。","formulaName":"归脾汤加减","fangjie":"黄芪、人参、白术益气健脾；当归、酸枣仁、龙眼肉、远志养血安神，酸收止汗；生姜、甘草、大枣、木香理气调中。心悸甚者，加龙骨、琥珀粉；不寐者，加柏子仁、合欢皮；气虚者，加生黄芪、浮小麦；血虚甚者，加制何首乌、枸杞子、熟地黄。"},{"id":"s301","name":"湿热郁蒸证","label":"4. 湿热郁蒸证","group":"","clinic":"蒸蒸汗出，汗黏，汗出色黄染衣，面赤烘热，烦躁，口苦，小便色黄，舌红，苔薄黄，脉弦数。","analysis":"湿热内蕴，迫津外泄，故见蒸蒸汗出；湿热蒸腾，外阻肌表，则汗黏；肝胆疏泄失司、胆汁随汗液外泄，则汗出色黄；邪热扰乱心神，故面赤烘热，烦躁；湿热下注膀胱，则尿黄；舌红、苔薄黄，脉弦数，为内有积热之象。","treat":"清肝泄热，化湿和营。","formulaRaw":"龙胆泻肝汤（《医方集解》)加减。","formulaName":"龙胆泻肝汤加减","fangjie":"龙胆草、黄芩、栀子、柴胡清肝泄热；泽泻、木通、车前子清利湿热；当归、生地黄滋阴养血和营；糯稻根敛阴止汗。里热较甚，小便短赤者，加茵陈、黄柏。湿热内蕴而热势不盛者，用四妙丸加减；胃火上攻，头部蒸蒸汗出者，用竹叶石膏汤加减。"}],"linchuang":["注重原发病的治疗汗证是临床杂病中较为常见的病证，也可作为虚劳、痨瘵、失血、妇人产后血虚等病证中的常见症状出现，在辨证论治时要加以区别。对于后者的治疗，在止汗的同时更应侧重于原发病的控制。","重视准确辨证自汗多属气虚，盗汗多属阴虚，但亦有阳虚盗汗、阴虚自汗者，因此，必须四诊合参，才能辨证准确。此外，应注意临床由郁火、湿热、瘀血等导致的汗证并不少见，故清泄郁火、清热化湿、活血化瘀等法也应应用。","正确应用收敛止汗法自汗、盗汗治疗时除辨证论治外，常酌加麻黄根、浮小麦、糯稻根、五味子、牡蛎等固涩止汗之品，以增强止汗功效。邪热郁蒸者汗出虽多，但证候属实证，收敛药物必须慎用，以免留邪。"],"yufang":["加强体育锻炼，注意劳逸结合，避免思虑烦劳过度，保持精神愉快，少食辛辣厚味，是预防汗证的重要措施。","汗出之时，当避风寒，以防感冒。汗出之后，应及时用干毛巾将汗擦干。汗多者，需经常更换衣物，注意保持衣服、卧具干燥清洁。由热邪而引起的汗证，应按发热患者观察和护理。"],"attachIds":[]},{"id":"d044","name":"内伤发热","kind":"main","parent":null,"chapterNo":"第四十七章","chapterName":"内伤发热","yinbing":[{"t":"b","x":"1. 久病体虚"},{"t":"p","x":"由于久病或原本体虚，失于调理，以致机体气、血、阴、阳亏虚，阴阳失衡，而引起发热。"},{"t":"b","x":"2. 饮食劳倦"},{"t":"p","x":"由于饮食不节，劳倦过度，使脾胃受损，水谷精气不充，以致中气不足，阴火内生，导致气虚发热，或脾虚不能化生阴血，阴虚内热，而引起阴虚发热；脾胃受损，运化失职，可致痰湿内生，郁而化热，进而引起湿郁发热。"},{"t":"b","x":"3. 情志失调"},{"t":"p","x":"情志抑郁，肝气不能条达，郁而化火，或恼怒过度，肝火内盛，导致气郁发热。"},{"t":"p","x":"《丹溪心法·火》言：“凡气有余便是火。”"},{"t":"p","x":"情志失调亦是导致瘀血发热的原因之一。"},{"t":"b","x":"4. 外伤、出血"},{"t":"p","x":"外伤、出血等原因导致发热主要有两个方面：一是外伤、出血导致血行不畅，瘀血阻滞经络，气血壅遏不通，因而引起瘀血发热；二是外伤以及血证时出血过多，或长期慢性失血，以致阴血不足，无以敛阳，而引起血虚发热。"}],"bingji":[{"t":"p","x":"内伤发热的基本病机是脏腑功能失调，气血阴阳失衡。"},{"t":"p","x":"病位涉及多个脏腑，包括肺、脾（胃）、心、肝、肾，而以肝、脾、肾为主。"},{"t":"p","x":"由气机郁结、瘀血阻滞及痰湿停聚引起的发热，属实；由阴血不足，阴不制阳，水不济火引起的发热，或由中气不足，阴火内生引起的发热，或由阳气虚衰，虚阳外浮引起的发热，属虚。"},{"t":"p","x":"病理因素为郁热、瘀血、痰湿。"},{"t":"p","x":"在本病的病变过程中，不同病机可以相互转化，久病往往由实转虚，或因虚致实，后期常见虚实夹杂，疾病由轻转重。"},{"t":"p","x":"虚证亦可转为实证，如阴虚内热，血津瘀滞，运行不畅，或气虚发热，气虚无力推动血行，或阳虚寒凝，均可致瘀血形成，而成虚实夹杂之证。"},{"t":"p","x":"若病程较短，胃气尚未衰败者，预后较佳；若病程迁延，病势缠绵，证候兼夹转化，正虚邪恋，"}],"zhenduan":[{"t":"ol","items":["1. 内伤发热起病缓慢，病程较长，多为低热，或自觉发热而体温并不升高，表现为高热者较少。不恶寒，或虽有怯冷，但得衣被则温。","2. 常兼见头晕、神疲、自汗、盗汗、脉弱等症。无感受外邪所致的头身疼痛、鼻塞、流涕、脉浮等症。","3. 多有气、血、阴、阳亏虚，或气郁、血瘀、湿阻的病史，或有反复发热史。"]}],"jianbie":[{"t":"p","x":"主要与外感发热相鉴别。"},{"t":"p","x":"外感发热起病较急，病程较短，发热初期大多伴有恶寒，其恶寒得衣被而不减。"},{"t":"p","x":"发热的程度（体温）大多较高，发热的类型随病种的不同而有所差异。"},{"t":"p","x":"初起常兼有头身疼痛、鼻塞、流涕、咳嗽、脉浮等表证。"},{"t":"p","x":"外感发热由感受外邪，正邪相争所致，属实证者居多。"},{"t":"p","x":"《医宗金鉴·杂病心法要诀·内伤外感辨似》曰：“内伤外感皆发热，内伤之发热、热在肌肉，以手扪之，热从内泛，不似外感之发热，热在皮肤，以手扪之，热自内轻也。”"},{"t":"table","caption":"表 47-1 外感发热与内伤发热鉴别表","head":["","外感发热","内伤发热"],"rows":[["病因","感受外邪","内伤因素"],["虚实","实证居多","虚证居多"],["发热特点","起病急，病程较短","起病缓，病程较长，或反复发作"],["临床表现","发热程度较高，病初多恶寒，得衣被不减，常兼有头身疼痛、鼻塞、流涕、咳嗽、脉浮等症","以低热为主，或自觉发热而体温并不升高，不恶寒，或虽有怯冷，但得衣被则温，常兼见头晕、神疲、自汗、盗汗、脉弱等症"]]}],"bianzheng":[{"t":"ol","items":["1. 辨证候虚实应依据病史、症状、脉象等辨明证候虚实，由气郁、血瘀、痰湿所致的内伤发热属实，由气虚、血虚、阴虚、阳虚所致的内伤发热属虚。若邪实伤正或因虚致实，表现虚实夹杂证候者，应分辨其主次。","2. 辨气血病位内伤发热，有病在气分、血分之别。病在气分者，如虚热中的气虚、阳虚发热.实热中的气郁、痰郁发热；病在血分者，如虚热中的血虚发热，实证中的瘀血发热。气血分之间亦可相兼出现。气分病变主要关乎脾、肾、肝及胃肠，血分病变涉及心、肝，其虚证与脾相关。","3. 辨病情轻重病程长久，热势亢盛，持续发热，或反复发作，经治不愈，胃气衰败，正气虚甚，兼夹证多，均为病情较重的表现，反之则病情较轻。若内脏无实质性病变，仅属一般体虚所致者、病情亦轻。"]}],"zhize":"实火宜泻、虚火宜补为内伤发热治疗的基本原则。属实者，治宜解郁、活血、除湿、化痰，适当配伍清热之法。属虚者，治宜益气、养血、滋阴、温阳，除阴虚发热可适当配伍清退虚热的药物外，其余均应以补为主。虚实夹杂者，当两者兼顾，临证时应综合分析，分主次处理。《景岳全书·火证》云：“实火宜泻，虚火宜补，固其法也。然虚中有实者，治宜以补为主，而不得不兼乎清……若实中有虚者，治宜以清为主，而酌兼乎补。”","syndrome":[{"id":"s302","name":"阴虚发热证","label":"1. 阴虚发热证","group":"","clinic":"午后潮热，或夜间发热，不欲近衣，手足心热，烦躁，少寐多梦，盗汗，口干咽燥，舌质红或有裂纹，苔少甚至无苔，脉细数。","analysis":"阴液亏损，阴不制阳，虚热内生，故见午后潮热，或夜间发热，不欲近衣，手足心热；虚火上炎，扰乱心神，故见烦躁，少寐多梦；热迫津泄，而见盗汗；热灼津伤，而见口舌干燥；舌质红或有裂纹，苔少甚至无苔，脉细数，为阴虚火旺之象。","treat":"滋阴清热。","formulaRaw":"清骨散（《证治准绳》）加减。","formulaName":"清骨散加减","fangjie":"鳖甲、知母、当归滋阴养血；秦艽、银柴胡、胡黄连、地骨皮、青蒿清热除蒸；乌梅敛阴。盗汗较甚者，去青蒿，加牡蛎、浮小麦、糯稻根；阴虚较甚者，加玄参、生地黄、白薇；失眠者，加酸枣仁、柏子仁、夜交藤；气虚而见头晕气短、体倦乏力者，加人参、麦冬、五味子。"},{"id":"s303","name":"血虚发热证","label":"2. 血虚发热证","group":"","clinic":"发热，多为低热，头晕眼花，身倦乏力，心悸不宁，面白少华，唇甲色淡，舌质淡，脉细弱。","analysis":"血虚失养，阴不配阳，故见发热；血虚不能上滋头目，外濡肢体，故见头晕眼花，身倦乏力；血虚不能养心，故见心悸不宁；血虚不能上荣于面及充盈血脉，故见面白少华，唇甲色淡；舌质淡，脉细弱，为血虚之象。","treat":"益气养血。","formulaRaw":"归脾汤（《济生方》）加减。","formulaName":"归脾汤加减","fangjie":"黄芪、人参、白术、茯苓益气健脾；当归、龙眼肉补血养血；酸枣仁、远志养心安神；木香理气醒脾；炙甘草补气调中；姜、枣调和脾胃，以资化源。血虚较甚者，加熟地黄、枸杞子、制首乌；由慢性失血所致的血虚，仍有少许出血者，加三七粉、仙鹤草、茜草、棕榈炭；脾虚失健，纳差腹胀者，去黄芪，加陈皮、神曲、谷芽、麦芽。"},{"id":"s304","name":"气虚发热证","label":"3. 气虚发热证","group":"","clinic":"发热，热势或低或高，常在劳累后发作或加剧，倦怠乏力，气短懒言，自汗，易于感冒，食少便溏，舌质淡，苔薄，脉细弱。","analysis":"中气不足，阴火内生，故见发热；劳则气耗，故见发热常在劳累后发作或加剧；脾气亏虚，气血生化不足，脏腑经络无以充养，故见倦怠乏力，气短懒言；脾虚失于健运，而见食少便溏；气虚卫外不固，故见自汗，易于感冒；舌质淡，苔薄，脉细弱，为气虚之象。","treat":"益气健脾，甘温除热。","formulaRaw":"补中益气汤（《内外伤辨惑论》)加减。","formulaName":"补中益气汤加减","fangjie":"黄芪补中益气，升阳固表；人参、炙甘草、白术补气健脾；当归养血和营；陈皮理气和胃；升麻、柴胡升阳举陷。自汗甚者，加牡蛎、浮小麦、糯稻根；时冷时热，汗出恶风者，加桂枝、芍药；胸闷脘痞，舌苔白腻者，加苍术、厚朴、藿香。"},{"id":"s305","name":"阳虚发热证","label":"4. 阳虚发热证","group":"","clinic":"发热而欲近衣，形寒怯冷，四肢不温，少气懒言，头晕嗜卧，腰膝酸软，纳少便溏，面色㿠白，舌质淡胖或有齿痕，苔白润，脉沉细无力。","analysis":"肾阳亏虚，火不归原，故见发热；阳虚失于温煦，故见形寒怯冷，四肢不温，腰膝酸软；脾阳亏虚，运化无力，故见少气懒言，头晕嗜卧，纳少便溏，面色㿠白；舌质淡胖或有齿痕，苔白润，脉沉细无力，为阳虚之象。","treat":"温补阳气，引火归原。","formulaRaw":"肾气丸（《金匮要略》）加减。","formulaName":"肾气丸加减","fangjie":"附子（制）、桂枝温补阳气；山茱萸、地黄补养肝肾；山药、茯苓补肾健脾；牡丹皮、泽泻清泄肝肾。阳虚甚者，加仙茅、淫羊藿；短气甚者，加人参；便溏者，加白术、干姜。"},{"id":"s306","name":"气郁发热证","label":"5. 气郁发热证","group":"","clinic":"发热，多为低热或潮热，热势常随情绪波动而起伏，精神抑郁，胁肋胀满，烦躁易怒，口干而苦，纳呆，舌红，苔黄，脉弦数。","analysis":"情志抑郁，肝失条达，郁而化火，故见发热，烦躁易怒，口干而苦；因情志致热，故见热势常随情绪波动而起伏；肝失疏泄，气机不畅，故见精神抑郁，胁肋胀满；肝木乘脾土，而见纳呆；舌红，苔黄，脉弦数，为气郁化热之象。","treat":"疏肝理气，解郁泄热。","formulaRaw":"丹栀逍遥散（《内科摘要》）加减。","formulaName":"丹栀逍遥散加减","fangjie":"牡丹皮、栀子清肝泄热；柴胡、薄荷疏肝解热；当归、白芍养血柔肝；白术、茯苓、甘草培补脾土。气郁较甚者，加郁金、香附、青皮；口干便秘，舌红者，去白术，加龙胆草、黄芩；妇女兼有月经不调者，加泽兰、益母草。"},{"id":"s307","name":"痰湿郁热证","label":"6. 痰湿郁热证","group":"","clinic":"发热，午后热甚，心内烦热，胸闷脘痞，不思饮食，渴不欲饮，呕恶，大便稀薄或黏滞不爽，舌苔白腻或黄腻，脉濡数。","analysis":"痰湿内蕴，壅遏化热，故见发热；痰湿属阴，旺于阴分，故见午后热甚；痰热扰心，而见心内烦热；痰湿阻滞气机，故见胸闷脘痞；痰湿中阻，故见不思饮食，呕恶；湿停于内，则见渴不欲饮；湿邪下趋，而见大便稀薄；湿与热合停滞肠中，故见大便黏滞不爽；舌苔白腻或黄腻，脉濡数，为痰湿郁热之象。","treat":"燥湿化痰，清热和中。","formulaRaw":"黄连温胆汤（《六因条辨》）合中和汤（《鸡峰普济方》）加减。前方理气化痰，燥湿清热；后方健脾理气，燥湿化痰。","formulaName":"黄连温胆汤合中和汤加减","fangjie":"半夏、厚朴燥湿化痰；枳实、陈皮理气和中；茯苓、通草、竹叶清热利湿；黄连、竹茹清热除烦。若呕恶，加藿香、白蔻仁；寒热往来如疟，寒轻热重，口苦呕逆者，加青蒿、黄芩。湿热所致者，症见胸闷脘痞，身热不扬，苔腻，用三仁汤或甘露消毒丹加减。"},{"id":"s308","name":"血瘀发热证","label":"7. 血瘀发热证","group":"","clinic":"午后或夜晚发热，或自觉身体某些部位发热，口燥咽干，但不多饮，肢体或躯干有固定痛处或肿块，面色萎黄或晦暗，舌质青紫或有瘀点、瘀斑，脉弦或涩。","analysis":"血行瘀滞，瘀热内生，故见发热；血属阴，瘀在血分，故午后或夜晚发热；瘀血内停，津液输布障碍，故口燥咽干，但不多饮；经络阻滞，气血瘀阻，故肢体或自觉身体某些部位发热，肢体或躯干有固定痛处或肿块；瘀血阻滞，新血不生，气血不能濡养，故面色萎黄或晦暗；舌质青紫或有瘀点、瘀斑，脉弦或涩，为瘀血之象。","treat":"活血化瘀。","formulaRaw":"血府逐瘀汤（《医林改错》）加减。","formulaName":"血府逐瘀汤加减","fangjie":"当归、川芎、赤芍、地黄养血活血；桃仁、红花、牛膝活血祛瘀；柴胡、枳壳、桔梗调畅气机。发热较甚者，加秦艽、白薇、牡丹皮；肢体肿痛者，加丹参、郁金、延胡索。"}],"linchuang":["补虚泻实，调整阴阳。《医学心悟·火字解》将外邪引起的发热称为“贼火”，认为“贼可驱而不可留”；由久病伤正、情志不舒、饮食失调、劳倦过度等引起的内伤发热称为“子火”，“子可养而不可害”。这提示内伤发热有因“邪气实”者，与气、血、津液郁遏有关，有因“正气虚”者，多由气、血、阴、阳亏虚所致。应针对病情补虚泻实，调整气血，促进脏腑功能及阴阳平衡的恢复。","甘温除热法的应用。该法源于《黄帝内经》，创于李东垣，为中医治疗气虚发热的有效方法。多见于体质偏弱者，常兼有多汗、怕冷、心悸、失眠等气血不足的症状。中医学认为，气血相关，阴阳互根，血虚者多兼气虚，阳虚为气虚之极，阳虚者必见气虚。故对相当部分体质偏弱的内伤发热患者，在甘温除热法的基础上，针对病情加减化裁，常能收到较好的效果。","“无名热”的辨治。对于临床不明原因的发热，经多系统检查，无病可辨，排除外感、内伤疾病及药源性发热，大多患者并无明显自觉痛苦，体温类型不一，有医家称之为“无名热”，其核心病机是湿热郁蒸，少阳枢机不和，邪在半表半里，可用小柴胡汤、蒿芩清胆汤，以和解清化为基础，合桂枝汤、玉屏风散调和营卫，柴前连梅煎清热除蒸，丹栀逍遥丸疏泄郁火，血府逐瘀汤行气逐瘀等法，综合辨治。"],"yufang":["内伤发热患者应注意休息，体温高者应卧床，部分长期低热的患者，在体力允许的情况下，可做适当户外活动以增强体质。要保持情绪乐观，避免不良情绪的刺激。饮食宜进清淡、富含营养而易于消化之品。若因卫表不固而有自汗、盗汗，应注意保暖、避风，防止感受外邪。"],"attachIds":[]},{"id":"d045","name":"厥证","kind":"main","parent":null,"chapterNo":"第四十八章","chapterName":"厥证","yinbing":[{"t":"b","x":"1. 情志内伤"},{"t":"p","x":"七情中尤以暴怒引发本病者最为多见，如《素问·生气通天论》谓：“阳气者，大怒则形气绝，而血菀于上，使人薄厥。”"},{"t":"p","x":"或所愿不遂，肝气郁结，郁久化火，肝火上炎，致气血郁滞，以致阴阳不相顺接，而发为厥证。"},{"t":"p","x":"此外，若平素体弱胆怯，加上突如其来的外界影响，如见死尸，或见鲜血喷涌，或闻巨响等，亦可使气血逆乱，发为厥证。"},{"t":"b","x":"2. 体虚劳倦"},{"t":"p","x":"元气素虚，复加饥饿劳累，以致中气不足，髓海失养，或长期睡眠不足，气血阴阳暗耗，而发为厥证。"},{"t":"b","x":"3. 亡血失津"},{"t":"p","x":"因大汗吐下，气随液耗，或因创伤出血，或血证失血过多，以致气随血脱，阳随阴消，津血亏虚，不能上荣，神明失主，而发为厥证。"},{"t":"p","x":"如《伤寒论·辨厥阴病脉证并治》云：“大汗出，热不去，内拘急，四肢疼，又下利厥逆而恶寒者，四逆汤主之。”"},{"t":"b","x":"4. 饮食不节"},{"t":"p","x":"暴饮暴食，饮食积滞，停于中焦，气机阻滞，胃失和降，脾失升清，上下痞隔，发为厥证；或嗜食酒酪肥甘，脾胃受损，运化失常，以致聚湿生痰，痰浊阻滞，气机不畅，日积月累，痰愈多则气愈阻，气愈滞则痰更盛，如痰浊一时上壅，清阳被阻，则可发为厥证。"}],"bingji":[{"t":"p","x":"厥证的基本病机是气机逆乱，升降乖戾，气血阴阳不相顺接。"},{"t":"p","x":"《景岳全书·厥逆》言：“盖厥者尽也，逆者乱也，即气血败乱之谓也。”"},{"t":"p","x":"情志异常、精神刺激、素体虚弱等致气机逆乱，清窍壅塞，神明失养，发为气厥；肝阳偏亢，遇暴怒肝之气血逆乱于上，或大量失血后血不荣窍，发为血厥；体虚湿盛，饮食不节，痰浊内生，阻遏气机，中焦斡旋失司，以致气机升降失调，或痰随气升，蒙蔽清窍，发为痰厥。"},{"t":"p","x":"由于体质和病机转化的不同，病理性质有虚实之别。"},{"t":"p","x":"大凡气盛有余，气逆上冲，血随气逆或夹痰浊、瘀血壅滞于上，以致清窍闭塞，不省人事，皆为厥之实证；气虚不足，清阳不升，气陷于下，或大量出血，气随血脱，血不上达，气血一时不相顺接，以致神明失养，不省人事，为厥之虚证。"},{"t":"p","x":"病变所属脏腑主要在于心、肝，涉及脑（清窍），与肺、脾、肾密切相关。"},{"t":"p","x":"厥之虚证与肺脾的关系密切，肺脾气虚，清阳不升，气陷于下，血不上达，致神明失主，而发为厥证。"},{"t":"p","x":"肾为元气之根，肾虚精气不能上注，导致神明失养，亦可发为厥证。"},{"t":"p","x":"厥证之病理转归主要有三：一是阴阳气血相失，进而阴阳离决，发展为一厥不复之死证。"},{"t":"p","x":"二是阴阳气血失常，或为气血上逆，或为中气下陷，或气血痰浊内闭，气机逆乱，而阴阳尚未离决；若正气来复，治疗得当，则气复返而生，反之，气不复返而死。"},{"t":"p","x":"如气厥和血厥之实证，常转化为气滞血瘀之证；失血致厥的血厥虚证，严重者转化为气随血脱之脱证等。"},{"t":"p","x":"本病预后主要取决于正气的强弱、病情的轻重以及抢救治疗是否及时得当。"},{"t":"p","x":"发病之后，若呼吸比较平稳，脉象有根，表示正气尚强，预后良好；若气息微弱，脉象沉伏，多属危候，预后不良。"}],"zhenduan":[{"t":"ol","items":["1. 厥证以突然昏仆，不省人事，或伴四肢逆冷等为主要临床特征，具有急骤性、突发性和一时性的特点。","2. 发病前常有先兆症状，如头晕、恶心、心悸、出汗、视物模糊、面色苍白等，而后突然发生昏仆，不省人事，移时苏醒。发病时或伴有四肢逆冷，醒后感头晕、疲乏、口干，但无失语、偏等后遗症。","3. 发病前多有明显的诱发因素，如精神刺激、情绪波动等，或有失血病史，或有饮食不节史，或有痰盛宿疾，应详细了解既往有无类似情况发生。注意询问发作时的体位、持续时间以及昏厥前后的表现。"]}],"jianbie":[{"t":"b","x":"1. 中风"},{"t":"p","x":"中风的中脏腑者可表现为猝然昏仆，与厥证存在相似之处。"},{"t":"p","x":"但中风以中老年人为多见，常有素体肝阳亢盛，其中脏腑者，突然昏仆，并伴有口眼㖞斜、偏瘫等症；若神昏时间较长，苏醒后有偏瘫、口眼㖞斜及失语等后遗症。"},{"t":"p","x":"厥证可发生于任何年龄，昏倒时间较短，醒后无后遗症，但血厥之实证重者可发展为中风。"},{"t":"b","x":"2. 昏迷"},{"t":"p","x":"昏迷与厥证均有意识丧失的临床表现。"},{"t":"p","x":"但昏迷为多种疾病发展到一定阶段所出现的危重证候，多发生缓慢，存在昏迷前的临床过程，先轻后重，多由烦躁、嗜睡渐次发展，昏迷后持续时间一般较长，恢复较难，苏醒后原发病仍然存在。"},{"t":"p","x":"厥证多为突然发生，昏倒时间较短，常因情志刺激、饮食不节、劳倦过度、亡血失津等诱发。"}],"bianzheng":[{"t":"ol","items":["1. 辨病因厥证的发生常有明显的病因可寻。如气厥虚证，多发生于平素体质虚弱者，厥前常有过度疲劳、睡眠不足、饥饿受寒、突受惊恐等诱因；血厥虚证，则与失血有关，常继发于急性或慢性大量出血之后；气厥实证及血厥实证，多发生于形壮体实者、发作多与急躁恼怒、情志过极等密切相关；痰厥好发于恣食肥甘、体丰湿盛之人，而恼怒及剧烈咳嗽常为其诱因。","2. 辨虚实厥证不外虚实两端。实证者表现为突然昏仆，面红气粗，声高息促，口噤握拳，痰涎壅盛，舌红苔黄膩，脉洪大有力。虚证者表现为眩晕昏厥，面色苍白，声低息微，口开手撤，汗出肢冷，舌胖或淡，脉细弱无力。","3. 分气血厥证以气厥、血厥为多见，应重点辨别气厥实证及血厥实证之不同。气厥实者乃肝气升发太过所致。体质壮实之人，肝气上逆，由惊恐诱发，表现为突然昏仆，呼吸气粗，口噤握拳，头晕头痛，舌红苔黄，脉沉而弦。血厥实者，乃肝阳上亢，阳气暴张，血随气升，气血并走于上，表现为突然昏仆，牙关紧闭，四肢厥冷，面赤，或鼻衄，舌质暗红，脉弦有力。"]}],"zhize":"厥证乃危急之候，当以及时救治为要，发作时的治疗原则是回厥醒神，醒后则需辨证论治，调治气血。气厥实证顺气开郁，气厥虚证补气回阳；血厥实证活血顺气，血厥虚证补养气血；痰厥行气豁痰；食厥和中消导。对于失血、失津过急过多者，还应配合止血、输血、补液等急救治疗，以挽其危。","syndrome":[{"id":"s309","name":"实证","label":"(1) 实证","group":"气厥","clinic":"常由情志异常、精神刺激而诱发，突然昏倒，不省人事，或四肢厥冷，呼吸气粗，口噤握拳，舌苔薄白，脉伏或沉弦。","analysis":"患者素体气盛有余，突发情志异常或精神刺激导致肝郁不舒，气机上逆，壅阻心胸，内闭神机，故突然昏倒，不省人事，口噤握拳；气机逆乱于上而不达四末，故四肢厥冷；气机壅滞于上，肺气宣肃不利，故呼吸气粗；舌苔薄白，脉伏或沉弦，均为气机闭塞之征。","treat":"开窍，顺气，解郁。","formulaRaw":"通关散（《中国药典》）合五磨饮子（《医便》）加减。前方辛香通窍，散剂吹鼻以促其苏醒，后方开郁畅中，调肝降气。","formulaName":"通关散合五磨饮子加减","fangjie":"猪牙皂、细辛辛香通窍醒神；沉香、乌药降气调肝；槟榔、枳实、木香行气破滞。必要时可先鼻饲苏合香丸宣郁理气，开闭醒神。肝阳偏亢，头晕而痛，面赤躁扰者，加钩藤、石决明、磁石；兼有痰热，见喉中痰鸣，痰壅气塞者，加胆南星、贝母、橘红、竹沥；醒后哭笑无常，睡眠不宁者，加茯神、远志、酸枣仁。"},{"id":"s310","name":"虚证","label":"(2) 虚证","group":"气厥","clinic":"发病前有明显的情绪紧张、恐惧、疼痛或站立过久等诱发因素，发作时眩晕昏仆，面色苍白，呼吸微弱，汗出肢冷，舌淡，脉沉细微。","analysis":"患者素体元气亏虚，遇紧张、恐惧、疼痛等刺激，导致清阳不升，神明失养，故眩晕昏仆；气为血之帅，气不能行血上荣，故面色苍白；肺气下陷，故呼吸微弱；卫气不固，阳气不温，故汗出肢冷；舌淡，脉沉细微，均为气虚之征。","treat":"补气，回阳，醒神。","formulaRaw":"生脉散（《医学启源》)、参附汤（《济生方》)、四味回阳饮（《景岳全书》）加减。三方均能补益正气，生脉散重在益气生津，参附汤及四味回阳饮重在益气固阳。","formulaName":"生脉散、参附汤、四味回阳饮加减","fangjie":"人参大补元气，复脉固脱；麦冬生津固脱；五味子敛汗固脱；附子（制）散寒回阳固脱；炮姜温中回阳；甘草调中缓急。临床可先急用生脉注射液或参附注射液静脉推注或滴注，补气摄津醒神。苏醒后用四味回阳饮加减补气温阳。汗出多者，加黄芪、白术、煅龙骨、煅牡蛎；心悸不宁者，加远志、柏子仁、酸枣仁；纳谷不香，食欲不振者，加白术、茯苓、陈皮。"},{"id":"s311","name":"实证","label":"(1) 实证","group":"血厥","clinic":"多因急躁恼怒而诱发，突然昏倒，不省人事，牙关紧闭，面赤，舌质暗红，脉弦有力。","analysis":"患者素体气盛有余，怒而肝气上冲，气为血之帅，血随气升，闭阻清窍，故突然昏倒，不省人事，牙关紧闭；气血上壅于头面，故面赤；舌质暗红，脉弦有力，为血郁于上之征。","treat":"平肝潜阳，理气通瘀。","formulaRaw":"羚角钩藤汤（《通俗伤寒论》）或通瘀煎（《景岳全书》）加减。前方平肝潜阳息风，后方活血顺气。","formulaName":"羚角钩藤汤或通瘀煎加减","fangjie":"羚羊角（可研粉服）清心肝，息风潜阳；钩藤、桑叶、菊花、泽泻平肝息风；白芍、生地黄柔肝养阴；贝母、竹茹清热化痰；茯神健脾安神；当归、山楂、红花活血通瘀；香附、乌药、青皮、木香理气解郁。急躁易怒者，加菊花、牡丹皮、龙胆草；眩晕头痛者，加枸杞子、珍珠母、石决明。"},{"id":"s312","name":"虚证","label":"(2) 虚证","group":"血厥","clinic":"常因失血过多诱发，突然昏厥，面色苍白，口唇无华，四肢震颤，自汗肢冷，目陷口张，呼吸微弱，舌质淡，脉芤或细数无力。","analysis":"患者素体亏虚，急性或慢性大量出血后，气随血脱，神明失养，故突然昏厥；血少不荣，故面色苍白，口唇无华；血少津亏，筋失所养，故四肢震颤；气随血脱，不能固摄，故自汗肢冷，目陷口张，呼吸微弱；舌质淡，脉芤或细数无力，均为气血衰少之征。","treat":"补养气血。","formulaRaw":"急用独参汤灌服（《景岳全书》)，继服人参养荣汤（《太平惠民和剂局方》）加减。前方益气固脱，后方补益气血。","formulaName":"独参汤灌服，继服人参养荣汤加减","fangjie":"独参汤即重用一味人参，大补元气，所谓“有形之血不能速生，无形之气所当急固”。后以人参养荣汤补养气血。人参、黄芪益气；当归、熟地黄养血；白芍、五味子敛阴；白术、茯苓、远志、甘草健脾安神；肉桂温养气血；生姜、大枣和中补益；陈皮理气。自汗肤冷，呼吸微弱者，加附子（生）、干姜；口干少津者，加麦冬、玉竹、沙参；心悸少寐者，加龙眼肉、酸枣仁。"},{"id":"s313","name":"痰厥","label":"3. 痰厥","group":"","clinic":"素有咳喘宿痰，多湿多痰，恼怒或剧烈咳嗽后，突然昏厥，喉有痰声，或呕吐涎沫，呼吸气粗，舌苔白腻，脉沉滑。","analysis":"患者素有宿痰，恼怒或剧咳导致肝郁肺痹，痰随气升，上闭清窍，故突然昏厥；痰阻气道，故喉有痰声，呼吸气粗；痰阻中焦上逆，故呕吐涎沫；舌苔白腻，脉沉滑，均为痰涎壅盛之征。","treat":"行气豁痰。","formulaRaw":"导痰汤加减（《校注妇人良方》）。","formulaName":"导痰汤加减","fangjie":"半夏、胆南星、茯苓燥湿祛痰；苏子、白芥子化痰降气；陈皮、枳实理气降逆。若痰湿化热，症见便秘，舌苔黄腻，脉滑数者，加黄芩、栀子、竹茹、瓜蒌仁。"},{"id":"s314","name":"食厥","label":"4. 食厥","group":"","clinic":"暴饮暴食，突然昏厥，脘腹胀满，呕呃酸腐，头晕，舌苔厚腻，脉滑。","analysis":"食滞中脘，中焦壅塞，胃气不降，气逆于上，清窍闭塞，故突然昏厥，头晕；食滞胃脘，气机阻滞，浊气不降，腐浊之气外泛，故脘腹胀满，呕呃酸腐；舌苔厚腻，脉滑，均为食滞中脘之征。","treat":"和中消导。","formulaRaw":"昏厥若在食后不久，应用盐汤探吐以去实邪，再用神术散（《太平惠民和剂局方》）合保和丸（《丹溪心法》）加减治疗。","formulaName":"神术散合保和丸加减","fangjie":"山楂、神曲、莱菔子消食积；半夏、厚朴、陈皮、茯苓、藿香、砂仁和胃化湿；连翘轻清透热、防食积郁而化热。若腹胀而大便不通者，用小承气汤导滞通腑。"}],"linchuang":["尽早诊断，综合救治。本病的发病有急骤性、突发性和一时性的特点。急骤发病，突然昏倒，移时苏醒。往往在发病前有明显的诱发因素，如暴怒、紧张、恐惧、惊吓等。发作前有头晕、恶心、面色苍白、出汗等先期症状。发作时昏仆，不知人事，或伴有四肢逆冷。除四诊合参外，还应及时全面检查，迅速诊断，明确病因，辨虚实之证，而及时正确施治尤为重要。重症患者应采取中西医结合疗法，即中成药、针灸等综合应急措施，及时救治。由于厥证的发生常由情志精神因素诱发，且部分患者有类似既往病史，平时可服用柴胡疏肝散、逍遥散、越鞠丸之类，理气解郁，调和肝脾。","不同类型厥证辨治应互相参考，气血兼顾。各型之厥，特点不同，但均有其内在联系，体现在脏腑气血的关联和阴阳气血不相顺接的共性。例如气厥与血厥，因气为血之帅，血为气之母，而互相影响；又如痰厥与气厥，由于痰随气动而互相联系。至于情志过极以致气血逆乱而发厥，则与气厥、血厥、痰厥均有密切关系。因此临床上既要注意厥证不同类型的特点，又要把握厥证的共性，全面兼顾，方能提高疗效。","活用开窍法。开窍法适用于邪实窍闭之厥证，以辛香走窜之品通关开窍，通过开泄痰浊闭阻。温通辟秽化浊、宣窍通利气机而达到苏醒神志的目的。在使用剂型上应选择丸、散、气雾、含化以及注射类药物，宜口服、鼻饲、注射。本法系急救治标之法，苏醒后应按病情辨证治疗。注意气血亏虚者不可妄用辛香开窍之品。"],"yufang":["预防厥证，应避免情志过极，保持心情舒畅。对于情绪容易激动，思想狭隘者，平时注意加强思想修养，避免病情反复发作或加重。改变不良饮食、起居习惯，加强锻炼，增强体质。注意劳逸结合，保持充足的睡眠，避免过度疲劳或饥饿等。","已发厥证者，宜采取针对性调护措施，密切观察病情的发展变化，注意保持呼吸道通畅，促进排痰，防止窒息。患者苏醒后，要消除其紧张情绪，针对不同的病因予以不同的康复指导。厥证患者应戒烟，忌食醇酒及辛辣香燥之品，以免助热生痰，加重病情。"],"attachIds":[]},{"id":"d046","name":"虚劳","kind":"main","parent":null,"chapterNo":"第四十九章","chapterName":"虚劳","yinbing":[{"t":"b","x":"1. 先天不足"},{"t":"p","x":"且患病后易致久病不复，使脏腑气血阴阳亏虚日甚，发为虚劳。"},{"t":"b","x":"2. 重病久病，失于调理"},{"t":"p","x":"罹患大病重病，邪气偏盛，耗伤脏气，气血阴阳亏损，或久病迁延不愈，精气耗伤，或病后失于调养，正气难复，均可演变为虚劳。"},{"t":"p","x":"如此迁延，阴精或者阳气受损难复，导致虚劳。"},{"t":"b","x":"3. 误治失治"},{"t":"p","x":"辨治失误，或用药不当，可使精气损伤。"},{"t":"p","x":"不当使用金石、虫类、有毒之品，或长期、过度接触化学有害物质，使阴精气血耗损，渐成虚劳。"},{"t":"b","x":"4. 劳烦过度，损伤五脏"},{"t":"p","x":"烦劳过度，因劳致虚，日久成损，以劳神过度及房劳为多见。"},{"t":"p","x":"如忧郁思虑、积思不解、所欲未遂等过度劳神，易使心失所养，脾失健运，心脾两伤，气血亏损，久则成劳。"},{"t":"p","x":"或早婚多育、恣情纵欲、房事不节、频繁手淫等，易致肾精亏虚，肾气不足，阴阳两损，渐成虚劳。"},{"t":"b","x":"5. 饮食不节"},{"t":"p","x":"暴饮暴食，饥饱不调，饮食偏嗜，营养不良，或饮酒过度，均致脾胃损伤，不能化生水谷精微，气血来源不充，脏腑经络失于濡养，日久形成虚劳之病。"}],"bingji":[{"t":"p","x":"虚劳的基本病机是五脏气血阴阳亏损。"},{"t":"p","x":"虚劳虽有因虚致病，因病成劳，或因病致虚，久虚不复成劳的不同，而其病理性质，以本虚为主，表现为气、血、阴、阳的亏损，并可兼见同病。"},{"t":"p","x":"病位涉及五脏，可互相传变。"},{"t":"p","x":"病变部位不一，常见多脏同病。"},{"t":"p","x":"由于虚劳的病因不一，常先发生某脏腑气血阴阳的亏损，但由于五脏相关，气血同源，阴阳互根，所以在病变过程中常相互影响，出现一脏受病，累及他脏，互相转化的状况。"},{"t":"p","x":"《难经》谓：“上损及下，下损及上。”"},{"t":"p","x":"如气虚日久阳也渐衰，血虚日久阴也不足，阳损日久累及于阴，阴虚日久累及于阳，以致病势日渐发展，病情趋于复杂。"},{"t":"p","x":"虚劳以虚证居多，也可见正虚邪实等错杂之候。"}],"zhenduan":[{"t":"ol","items":["1. 脏腑气血阴阳的亏虚以一组或多组有内在联系的症候群呈现，并呈慢性演变的过程。起病多缓慢或隐匿，亦可明显、急骤，但以前者为多见。","2. 可见消瘦憔悴，面色无华，身体羸弱，甚或形神衰败，大肉尽脱，食少便溏，心悸气促、呼多吸少，自汗盗汗，或五心烦热，或畏寒肢冷，男性阳痿遗精，女性不孕，白带如水，质清稀、量多、舌质淡胖，或伴舌边有齿痕，脉虚无力等。","3. 有长期慢性病史，或存在引起虚劳的其他致病因素，多见于大病、久病之后。","4. 应排除内科其他疾病中出现的虚证。"]}],"jianbie":[{"t":"p","x":"主要与内科其他疾病中的虚证相鉴别。"},{"t":"p","x":"内科其他病证中出现的虚证属“证”的范畴，为证候诊断，有其固定的主症，以脏腑气血阴阳某一部分的损害为主，病变脏腑单一，以该病的主要症状为突出表现。"},{"t":"p","x":"如泄泻病的脾胃虚弱证，虽有脾胃亏虚的症状，但以泄泻为最突出、最基本的表现，治疗相对容易，预后亦良好。"},{"t":"p","x":"虚劳属“病”的范畴，为病名诊断、无固定的主症，为脏腑气血阴阳多方位、多层次的损害，以出现一系列精气亏虚的症状为特征，往往呈慢性演变性发展，治疗难取速效，甚或难以取效，故预后较差。"},{"t":"p","x":"虚劳病的辨治以虚证为基础，虚证是组成虚劳病的基本单位，证与证之间的多种组合方式呈现虚劳病的本质。"},{"t":"p","x":"若虚证病情不断发展至脏腑精气亏损时，可转化为虚劳。"}],"bianzheng":[{"t":"ol","items":["1. 辨别五脏气血阴阳亏虚虚劳的证候虽多，但总不离乎五脏，而五脏之辨，又不外乎气、血、阴、阳，因此，虚劳的辨证应以气、血、阴、阳为纲，五脏虚证为目。结合五脏相关、气血同源、阴阳互根的理论，判断病位及脏腑虚损的性质。"]},{"t":"p","x":"《杂病源流犀烛·虚损痨察源流》云：“五脏虽分，而五脏所藏无非精气，其所以致损者有四，曰气虚，曰血虚，曰阳虚，曰阴虚。”"},{"t":"p","x":"所以各种原因所致的虚损往往互相影响，由一虚渐致多虚，由一脏而累及他脏，使病情趋于复杂和严重，辨证时须悉心分析。"},{"t":"ol","items":["2. 辨证候的标本主次虚劳之病，阳损及阴者，阳虚为本，阴虚为标；气虚及血者，气病为本，血病为标；若血虚及气者，血病为本，气病为标；虚损及于脾肾者，脾肾之损为本，他脏之损为标；虚劳复有新感外邪者，虚损为本，新感为标；虚损不甚而又兼有积聚、痰瘀等宿病者，宿病为本，虚损为标。","3. 辨有无兼夹病证虚劳多有较长的病程，可存在兼夹病证，辨治时应注意几种情况：其一，对因病致虚、久虚不复者，应辨明原有疾病是否还继续存在，如因热病、寒病、瘀结致虚者，原发疾病是否已经治愈。其二，有无因虚致实的表现，如因气虚运血无力，形成瘀血，或阳虚水气不化，以致水饮停滞，发为水肿，或脾气虚不能运化水湿，以致水湿内停等。其三，是否兼夹外邪，因虚劳之人卫外不固，易感外邪，且感邪之后不易恢复，治疗用药也与常人感邪有所不同。"]}],"zhize":"根据“虚则补之”“损则益之”的理论，虚劳的治疗以补益为基本治则，同时还需根据病之不同，分别采取益气、养血、滋阴、温阳等治法，并要结合五脏病位的不同而选方用药，以加强治疗的针对性。\n重视补益脾肾。因脾胃为后天之本，为气血生化之源，脾胃健运，五脏六腑、四肢百骸方能得以滋养；肾为先天之本，寓元阴元阳，为生命的本源。只有重视补益脾肾，方能促进各脏虚损的恢复。\n因虚感邪或因虚致实，虚实夹杂时，治当权衡标本、轻重、缓急，选用扶正祛邪、攻补兼施等法。虚不受补者，应先扶养脾胃之气，用药尤贵轻灵不滞。因病致虚者既要补正以复其虚，又要求因以治其病。","syndrome":[{"id":"s315","name":"肺气虚","label":"(1) 肺气虚","group":"气虚","clinic":"咳嗽无力，痰液清稀，短气自汗，声音低怯，时寒时热，平素易于感冒，面白，舌质淡，脉弱。","analysis":"肺气不足，表虚不固，故短气自汗，声音低怯，咳嗽无力；肺气亏虚，营卫失和，则时寒时热；肺主皮毛，肺虚则腠理不密，故易感受外邪，平素易于感冒；肺气亏虚，不能贯心脉而通达全身，气血不能充沛于血脉，故见面白、舌淡、脉弱之象。","treat":"补益肺气。","formulaRaw":"补肺汤（《永类铃方》）加减。","formulaName":"补肺汤加减","fangjie":"人参、黄芪、沙参益气补肺；熟地黄、五味子、百合益肾敛肺。肺卫不固，易于感冒者，加防风、白术；自汗甚者，加牡蛎、麻黄根；气阴两虚，见潮热、盗汗者，加鳖甲、地骨皮、秦艽。"},{"id":"s316","name":"心气虚","label":"(2) 心气虚","group":"气虚","clinic":"心悸，气短，劳则尤甚，神疲体倦，自汗，舌质淡，脉弱。","analysis":"心气不足，鼓动无力，心神不宁，故心悸，气短，劳则尤甚；心气虚，宗气生成不足，无法充养周身，故神疲体倦；心气虚弱，不能固摄津液，故自汗出；气血不能上荣于舌，脉道充盈无力，故见舌质淡，脉弱。","treat":"益气养心。","formulaRaw":"七福饮（《景岳全书》)加减。","formulaName":"七福饮加减","fangjie":"人参、白术、炙甘草益气养心；熟地黄、当归滋补阴血；酸枣仁、远志宁心安神。自汗甚者，加黄芪、五味子；食少便溏者，加山药、砂仁。"},{"id":"s317","name":"脾气虚","label":"(3) 脾气虚","group":"气虚","clinic":"饮食减少，食后胃脘不舒，倦怠乏力，大便溏薄，面色萎黄，舌淡，苔薄，脉弱。","analysis":"脾虚失于健运，胃肠的纳谷及传化功能失常，故饮食减少，食后胃脘不舒，大便溏薄；脾虚不能化生水谷精微，气血来源不充，形体失养，故见倦怠乏力，面色萎黄，舌淡，脉弱。","treat":"健脾益气。","formulaRaw":"加味四君子汤（《三因极一病证方论》）加减。","formulaName":"加味四君子汤加减","fangjie":"人参、黄芪、白术、甘草益气健脾；茯苓、扁豆健脾除湿。胃失和降，见胃脘满闷，恶心呕吐，暖气者，加半夏、陈皮；脘腹胀满，食积不化者，加神曲、麦芽、山楂、鸡内金；气虚及阳，脾阳渐虚，见腹痛即泻，手足欠温者，加肉桂、炮姜。中气不足，气虚下陷，见脘腹坠胀，气短，脱肛者，用补中益气汤。伴各种出血者，用归脾汤。"},{"id":"s318","name":"肾气虚","label":"(4) 肾气虚","group":"气虚","clinic":"神疲乏力，腰膝酸软，小便频数而清，白带清稀，舌质淡，脉弱。","analysis":"肾为先天之本，主骨生髓，肾气虚，故神疲乏力，腰膝酸软；肾气虚累及任带二脉，且气虚常伴阳虚，故可见小便频数而清，白带清稀；肾气虚鼓动无力，气血不能上荣，脉道不充盈，故见舌质淡，脉弱。","treat":"益气补肾。","formulaRaw":"大补元煎（《景岳全书》）加减。","formulaName":"大补元煎加减","fangjie":"人参、山药、炙甘草益气固肾；杜仲、山茱萸温补肾气；熟地黄、枸杞子、当归补养精血。神疲乏力甚者，加黄芪；尿频较甚及小便失禁者，加菟丝子、五味子、益智仁；大便溏薄者，去熟地黄、当归，加肉豆蔻、补骨脂。"},{"id":"s319","name":"心血虚","label":"(1) 心血虚","group":"血虚","clinic":"心悸怔忡，健忘，失眠，多梦，面色不华，舌质淡，脉细或结代。","analysis":"心血亏虚，血不养心，心失所养，心神不宁，致心悸怔忡，健忘，失眠，多梦；血虚不能上荣头面，故面色不华，舌质淡；血虚则血脉不充，故见脉细或结代。","treat":"养血宁心。","formulaRaw":"养心汤（《证治准绳》）加减。","formulaName":"养心汤加减","fangjie":"人参、黄芪、茯苓、五味子、甘草益气生血；当归、川芎、柏子仁、酸枣仁、远志养血宁心；肉桂、半夏曲温中健脾。由于心血虚往往与脾血虚并存，称为心脾血虚，临证时常用归脾汤加减治疗，使得补脾与养心并进，益气与养血相融。"},{"id":"s320","name":"肝血虚","label":"(2) 肝血虚","group":"血虚","clinic":"头晕目眩，胁痛，肢体麻木，筋脉拘急，或肌肉腘动，妇女月经不调甚则闭经，面色不华，舌质淡，脉弦细或细涩。","analysis":"肝血亏虚，不能上养头目，致头晕目眩；血不养肝，肝气郁滞，故胁痛；血虚生风，筋脉失养，致肢体麻木，筋脉拘急，或肌肉腘动；肝血不足，妇女冲任空虚，则月经不调甚或闭经；面色不华，舌淡，脉弦细或细涩，为肝血不足、血脉不充之象。","treat":"补血养肝。","formulaRaw":"四物汤（《仙授理伤续断秘方》）加减。","formulaName":"四物汤加减","fangjie":"熟地黄、当归补血养肝；芍药、川芎和营调血。血虚甚者，加制何首乌、枸杞子、阿胶；胁痛者，加柴胡、郁金、香附、丝瓜络；目失所养，视物模糊者，加楮实子、枸杞子、决明子；干血瘀结，新血不生，症见羸瘦，腹满，腹部触有癥块，肌肤甲错，经闭，两目暗黑，舌紫暗有瘀点瘀斑，脉细涩者，可同服大黄䗪虫丸。"},{"id":"s321","name":"肺阴虚","label":"(1) 肺阴虚","group":"阴虚","clinic":"干咳，咽燥，甚或失音，咳血，潮热，盗汗，面色潮红，舌红少津，脉细数。","analysis":"肺阴亏耗，肺失濡润，清肃之令不行，故干咳；肺络损伤，则咳血；阴虚津不上承，故咽喉干燥，甚则失音；阴虚火旺，则潮热；虚热迫津液外泄，则盗汗；面颧潮红，舌红少津，均为阴虚内热、津液不足之象。","treat":"养阴润肺。","formulaRaw":"沙参麦冬汤（《温病条辨》)加减。","formulaName":"沙参麦冬汤加减","fangjie":"沙参、麦冬、玉竹滋养肺阴；天花粉、桑叶、甘草清热润燥。咳嗽甚者、加百部、款冬花；咳血者，加白及、仙鹤草、小蓟；潮热者，加地骨皮、银柴胡、秦艽、鳖甲；盗汗者，加牡蛎、浮小麦。肺阴虚日久，出现肺肾阴虚者，用麦味地黄丸。"},{"id":"s322","name":"心阴虚","label":"(2) 心阴虚","group":"阴虚","clinic":"心悸，失眠，烦躁，潮热，盗汗，或口舌生疮，面色潮红，舌红少津，脉细数。","analysis":"心阴亏虚，心失濡养，心神不宁，故心悸，失眠；阴虚生内热，虚火亢盛，故烦躁，面色潮红，口舌生疮；虚热迫津液外泄，则盗汗；舌红少津，脉细数，为阴虚内热、津液不足之象。","treat":"滋阴养心。","formulaRaw":"天王补心丹（《校注妇人良方》）加减。","formulaName":"天王补心丹加减","fangjie":"生地黄、玄参、麦冬、天冬养阴清热；人参、茯苓、五味子、当归益气养血；丹参、柏子仁、酸枣仁、远志养心安神。若火热偏盛，见烦躁不安，口舌生疮者，去当归、远志，加黄连、淡竹叶、莲子心；潮热者，加银柴胡、地骨皮、秦艽。"},{"id":"s323","name":"脾胃阴虚","label":"(3) 脾胃阴虚","group":"阴虚","clinic":"口渴，唇舌干燥，不思饮食，甚则干呕，呃逆，大便燥结，面色潮红，舌红少苔，脉细数。","analysis":"脾胃阴虚，运化失常，故不思饮食；津亏不能上承，故口渴，唇舌干燥；阴亏较甚，胃气失于和降，则干呕，呃逆；胃肠失于滋润，则大便秘结；面色潮红，舌红，少苔，脉细数，均为阴虚内热之象。","treat":"养阴和胃。","formulaRaw":"益胃汤（《温病条辨》）加减。","formulaName":"益胃汤加减","fangjie":"沙参、麦冬、生地黄、玉竹滋阴养液。津亏甚者，加石斛、天花粉；呃逆者，加刀豆、柿蒂；大便干结甚者，加蜂蜜。"},{"id":"s324","name":"肝阴虚","label":"(4) 肝阴虚","group":"阴虚","clinic":"头痛，眩晕，耳鸣，目干畏光，视物不明，急躁易怒，或肢体麻木，筋惕肉腘，面色潮红，舌干红，脉弦细数。","analysis":"肝阴不足，肝阳偏亢，上扰清窍，故头痛，眩晕，耳鸣；肝阴不能上荣于目，故目干畏光，视物不明；阴血不能濡养筋脉，虚风内动，则出现肢体麻木，筋惕肉锏；阴亏火旺，肝火上炎，则面色潮红；舌红少津，脉弦细数，为阴虚肝旺之象。","treat":"滋养肝阴。","formulaRaw":"补肝汤（《医宗金鉴》）加减。","formulaName":"补肝汤加减","fangjie":"地黄、当归、芍药、川芎、酸枣仁养血柔肝；木瓜、甘草酸甘化阴。若风阳内盛，症见头痛，眩晕，耳鸣，或筋惕肉腘较甚者，加石决明、菊花、钩藤、刺蒺藜；肝火亢盛，症见急躁易怒，尿赤便秘者，加夏枯草、牡丹皮、栀子。肝络失养，症见胁痛隐隐，口燥咽干，烦热，舌红少苔者，用一贯煎加减。"},{"id":"s325","name":"肾阴虚","label":"(5) 肾阴虚","group":"阴虚","clinic":"腰酸，遗精，两足痿弱，眩晕，耳鸣，甚则耳聋，口干，咽痛，颧红，舌红少津，脉沉细。","analysis":"腰为肾之府，肾虚失养，故感腰酸；肾阴亏虚，虚火易动，精关不固，则遗精；肾阴亏虚，髓海不足，脑失濡养，则眩晕，耳鸣；虚火上炎，故口干，咽痛，颧红；舌红少津，脉沉细，为肾阴亏虚之象。","treat":"滋补肾阴。","formulaRaw":"左归丸（《景岳全书》）加减。","formulaName":"左归丸加减","fangjie":"熟地黄、龟甲胶、枸杞子、山药、菟丝子、牛膝滋补肾阴；山茱萸、鹿角胶温补肾气。若潮热、口干、咽痛等虚火甚者，去鹿角胶、山茱萸，加知母、黄柏、地骨皮；腰酸，遗精甚者，加牡蛎、金樱子、芡实、莲须。"},{"id":"s326","name":"心阳虚","label":"(1) 心阳虚","group":"阳虚","clinic":"心悸，自汗，神倦嗜卧，心胸憋闷疼痛，形寒肢冷，面色苍白，舌淡或紫暗，脉细弱或沉迟。","analysis":"心阳不足，心气亏虚，故心悸，自汗，神倦嗜卧；阳虚不能温养四肢百骸，故形寒肢冷；阳虚气弱，不能推动血液运行，心脉瘀阻，气机滞塞，故心胸憋闷疼痛；舌质紫暗，面色苍白，舌淡，脉细弱或沉迟，均属心阳亏虚、运血无力之象。","treat":"益气温阳。","formulaRaw":"保元汤（《博爱心鉴》）加减。","formulaName":"保元汤加减","fangjie":"人参、黄芪益气扶正；肉桂、甘草、生姜温通阳气。若心胸疼痛者，加郁金、川芎、丹参、三七；阳虚较甚，形寒肢冷者，加附子（制）、巴戟天、仙茅、淫羊藿、鹿茸。"},{"id":"s327","name":"脾阳虚","label":"(2) 脾阳虚","group":"阳虚","clinic":"面色萎黄，食少，形寒，神倦乏力，少气懒言，大便溏薄，肠鸣腹痛，每因受寒或饮食不慎而加剧，舌淡，苔白，脉弱。","analysis":"脾阳亏虚，不能运化水谷，助长体力，故食少，形寒，神倦乏力，少气懒言；气虚中寒，清阳不展，寒凝气滞，故肠鸣腹痛，大便溏薄；感受寒邪或饮食不慎，以致中阳更虚，易使病情加重；面色萎黄，舌淡，苔白，脉弱，均为中阳虚衰之象。","treat":"温中健脾。","formulaRaw":"附子理中丸（《太平惠民和剂局方》）加减。","formulaName":"附子理中丸加减","fangjie":"人参、白术、甘草益气健脾；附子（制）、干姜温中祛寒。若寒凝气滞，腹中冷痛较甚者，加高良姜、香附，或丁香、吴茱萸；胃寒气逆，症见食后腹胀及呕逆者，加砂仁、半夏、陈皮；阳虚寒甚，腹胀冷痛，便溏，完谷不化者，加肉豆蔻、补骨脂、薏苡仁。"},{"id":"s328","name":"肾阳虚","label":"(3) 肾阳虚","group":"阳虚","clinic":"腰背酸痛，遗精，阳痿，多尿或不禁，面色苍白，畏寒肢冷，下利清谷或五更泄泻，舌淡胖，舌边有齿痕，脉沉迟。","analysis":"腰为肾之府，督脉贯脊络肾而督诸阳，肾阳不足，失于温煦，故腰背酸痛，畏寒肢冷；阳气衰微，精关不固，故遗精阳痿；肾气不固，则小便不禁，或多尿；命门火衰，火不生土，不能蒸化腐熟水谷，故下利清谷或五更泄泻；面色苍白，舌淡胖，舌边有齿痕，脉沉迟，均为阳气亏虚、阴寒内盛之象。","treat":"温补肾阳。","formulaRaw":"右归丸（《景岳全书》）加减。","formulaName":"右归丸加减","fangjie":"附子（制）、肉桂温补肾阳；杜仲、山茱萸、菟丝子、鹿角胶温补肾气；熟地黄、山药、枸杞子、当归补益精血。遗精甚者，加金樱子、桑螵蛸，或合金锁固精丸；脾虚而致下利清谷者，去熟地黄、当归，加党参、白术、薏苡仁；命门火衰而致五更泄泻者，合用四神丸；阳虚水泛，见浮肿、尿少者，加茯苓、泽泻、白术、车前子，或合五苓散；肾不纳气，喘促，短气，动则更甚者，加补骨脂、五味子、蛤蚧。"}],"linchuang":["虚劳病虽归纳为气、血、阴、阳亏损四类，但临证常有错综复杂的状况。病程短者，多伤气血，可见气虚、血虚及气血两虚之证；病程长者，多伤及阴阳，可见阴虚、阳虚及阴阳两虚证。气血与阴阳的亏损既有联系，又有区别。如津液、血液都属于阴的范畴，但血虚主要表现为血脉不充，失于濡养的症状，阴虚则多表现为阴虚生内热的症状。而阳虚可以包括气虚在内，且往往由气虚进一步发展而成，但气虚表现为短气乏力、自汗、舌淡、脉弱等症，阳虚则症状进一步加重，且出现阳虚里寒的症状，如倦怠嗜卧、形寒肢冷、舌质淡胖、脉虚弱或沉迟等。","虚劳病常两脏或多脏气血阴阳亏损合并出现，常采取复合证辨治。如心肺气虚，症见久咳、心悸、气短、咳痰，治以补心益肺，化痰通脉；肺肾阴虚，症见咳嗽痰少、形体消瘦、腰膝酸软、潮热盗汗，治以滋肾养肺，清热止咳；心脾肾阳俱虚，症见心悸惕动、面浮踝肿、小便不利、畏寒肢冷、唇舌暗紫，治以扶助心阳，温补脾肾等。对气血同病，阴阳两虚，或数脏均损者，须分清主次，兼顾治疗。","虚劳的治疗应以平调阴阳为主，即用药不可峻烈，剂量宜因病、因人、因时而异，不可墨守，亦不可过激，目的是以平为期，不可因温伤阴、因凉伤阳。虚劳病兼外感时，不可独补其虚，以防留寇之弊，可借鉴吴氏解托法或补托法。","补血需兼补气。补血养血是治疗血虚的治则，但由于血为气之母，故血虚均会伴有不同程度的气虚症状，《脾胃论》云：“血不自生，须得生阳气之药，血自旺矣。”所以血虚不宜单用补血药，应适当配伍黄芪、人参、党参、白术等补气药，以达到益气生血的目的。","在补阴补阳时注意阴阳互根。阴虚应补阴，阳虚应补阳，此为治疗常法，但须注意“阴阳互根”的问题。《景岳全书·新方八略》云：“善补阳者，必于阴中求阳，则阳得阴助而生化无穷；善补阴者，必于阳中求阴，则阴得阳升而泉源不竭。”张介宾所创治肾阴虚的左归丸及治肾阳虚的右归丸正体现了这一治疗原则。"],"yufang":["消除并避免诱因是预防虚劳的重要措施。因此，须顺应四时，调节情志，不妄劳作，保养正气，以防止病邪侵袭。对已病患者及早施治，防止病情传变。治疗以顾护脾肾为本，积极照顾未受邪之脏。此外，初愈之时气血未充，谨防调治不当而致反复。","由于正气不足，卫外不固，虚劳患者易感受外邪，应尽量减少外邪感触。饮食调理以富含营养、易于消化、不伤脾胃为原则，戒除烟酒，少食辛辣厚味、黏腻、生冷之物。起居规律，动静结合，节制房事，劳逸适度，调畅情志，均有助于虚劳的康复。"],"attachIds":[]},{"id":"d047","name":"癌病","kind":"main","parent":null,"chapterNo":"第五十章","chapterName":"癌病","yinbing":[{"t":"p","x":"癌病的发生，多由正气亏虚、六淫邪毒、饮食失调、七情内伤等病因导致脏腑功能失调，气血津液瘀滞，产生气郁、血瘀、痰凝、癌毒等病理因素，相互搏结，日久而成。"},{"t":"b","x":"1. 正气亏虚"},{"t":"p","x":"素体虚弱，或年高体衰，或宿有旧疾，久病正虚，阴阳失衡，脏腑失调，客邪留滞不去，邪蕴久腾不解成毒，与痰瘀互结，终致肿块。"},{"t":"p","x":"《医宗必读·积聚》曰：“积之成也，正气不足，而后邪气踞之。”"},{"t":"b","x":"2. 六淫邪毒"},{"t":"p","x":"外感六淫之邪，或烟毒、工业废气、放射性物质等邪毒之气，由外人里，深伏久滞，酿生癌毒，正不胜邪，脏腑气血阴阳失调，气郁、痰浊、血瘀等与癌毒互结，形成肿块。"},{"t":"b","x":"3. 饮食失调"},{"t":"p","x":"饮食不节，饥饱失常，如嗜食醇甘、辛辣、腌炸、烧烤、或海腥发物，或食物过热过冷霉变等，久伤脾胃，痰湿内生，浊毒郁热，日久耗气伤阴，脏腑功能失调，气血津液紊乱，邪盛生毒而致癌。"},{"t":"b","x":"4. 七情内伤"},{"t":"p","x":"情志不遂，七情怫郁，气机郁结，或气不布津，痰湿内生，或气滞血瘀，或郁热伤阴，虚实夹杂，终致痰湿与血瘀互结，渐成肿块。"}],"bingji":[{"t":"p","x":"癌病是在内外多种因素影响下，脏腑功能失调，气血津液瘀滞，癌毒内生，以致正气亏虚，痰瘀郁毒。"},{"t":"p","x":"如脑瘤病位在脑，肺癌病位在肺，大肠癌病位在肠，肾癌病位在肾等。"},{"t":"p","x":"病理性质为标实本虚，虚实夹杂，常见全身属虚而局部属实的情况。"},{"t":"p","x":"主要病理因素为虚、痰、瘀、毒等，其中癌毒是导致癌病发生发展的关键。"},{"t":"p","x":"癌病发病初期，癌毒偏盛而正虚不显；中晚期由于癌毒耗伤人体气血津液，多出现气虚、阴伤、气血亏虚或阴阳两虚等。"},{"t":"p","x":"随着病情的进展，毒恋正虚，胶着难解，恶化迅速，形体逐渐消瘦，神疲乏力，食欲不振，甚至出现大肉下陷、大骨枯槁、面枯神衰等危重症状，则为气血阴阳俱衰，病情危重，预后不良。"}],"zhenduan":[{"t":"ol","items":["1. 以病变局部出现坚硬、表面不平的肿块为最基本的临床特征，肿块常进行性增大，触诊质地坚硬，活动度差。早期可能产生与病变部位有关的局部表现。如脑癌患者出现头痛、呕吐、视力障碍等；肺癌患者出现顽固性干咳或痰中带血、胸痛、气急、发热等；肝癌患者出现右胁疼痛、乏力、纳差、黄疸等；大肠癌患者出现腹泻或便秘等大便习惯改变；肾癌患者出现腰部不适、尿血等。","2. 癌病中晚期常伴见乏力、纳差、不明原因发热、消瘦，并进行性加重；肿块增大致局部压迫可引起疼痛等症；癌毒流注他处出现相应症状，如骨转移致骨痛、脑转移致神经功能障碍等。","3. 癌病多见于中老年人，不同癌病在发病年龄和性别方面存在明显差异。"]}],"jianbie":[{"t":"p","x":"癌病的有关鉴别诊断复杂，不同癌病需要与之鉴别的病证不同，但癌病与良性肿瘤的鉴别尤为重要（表50-1）。"},{"t":"table","caption":"表 50-1 癌病与良性肿瘤鉴别表","head":["鉴别要点","良性肿瘤","恶性肿瘤（癌病）"],"rows":[["发展速度","生长缓慢，可几年甚至十几年","生长较快，呈进行性、倍数级生长"],["皮肤改变","除皮脂腺囊肿外，与皮肤无粘连","常与皮肤粘连，凹陷，或形成溃疡"],["肿块表面","光滑，与周围组织不粘连，边界清，活动度好","表面粗糙，无包膜，常与周围组织或皮肤粘连，活动度差或固定"],["肿块硬度","一般质地较软","质地硬，无弹性"],["全身状况","一般无症状，肿瘤体积较大或发生于特殊部位，可产生压迫症状","早期症状隐匿，可见不明原因的消瘦、发热、出血，或发病部位的相应症状"]]}],"bianzheng":[{"t":"ol","items":["1. 辨疾病分期见表 50-2。"]},{"t":"table","caption":"表 50-2 癌病不同分期辨证要点","head":["病期","证候特点"],"rows":[["早期","邪实为主，痰瘀郁毒互结成癌块，正虚不显"],["中期","正虚渐甚，癌块增大，变硬，侵及范围增大"],["晚期","正衰为主，癌毒侵凌范围广泛，或有远处转移，呈大实大虚状态"]]},{"t":"ol","items":["2. 辨正虚见表 50-3。"]},{"t":"table","caption":"表 50-3 癌病正虚辨证要点","head":["病性","证候特点"],"rows":[["阴虚","干咳或痰少，口咽干燥，形体消瘦，潮热盗汗，颧红目涩，舌红少津，脉细数。多见于放疗之后"],["气虚","咳喘无力，短气，动则加重，声怯神疲，自汗，纳差腹胀，腰膝酸软。多见于放化疗或手术之后"],["血虚","面黄无华，口唇淡白，乏力头昏，心悸不寐，舌淡，脉细或弱。多见于癌病中晚期或手术、放化疗之后"],["阳虚","形寒肢冷，面色㿠白，小便清长，夜尿频多，五更腹泻，舌淡胖有齿印，脉沉细。多见于癌病晚期"]]},{"t":"ol","items":["3. 辨邪实见表 50-4。"]},{"t":"table","caption":"表 50-4 癌病邪实辨证要点","head":["病性","证候特点"],"rows":[["郁毒","情绪抑郁或急躁，胁肋胀痛，胸闷，咽部有异物感，嗳气，泛恶，纳少，乳房胀痛。多见于甲状腺癌、乳腺癌等"],["痰毒","咳嗽咳痰（注意痰的颜色、性状、稀稠度、气味等），肿块部位固定，质地不坚，形体肥胖，肢体关节僵硬或疼痛，舌胖苔白腻，脉滑。多见于肺癌、甲状腺癌、淋巴癌等"],["湿毒","口黏，身重，苔厚浊腻，大便溏烂不爽，小便不畅，白带偏多等。多见于胃癌、肠癌、膀胱癌、子宫颈癌等"],["瘀毒","肿块部位固定，疼痛，出血，发绀，舌质紫暗或有瘀点瘀斑，脉涩等。多见于癌病中晚期或手术之后"],["热毒","发热，口苦，口干多饮，大便干结，体表病变局部红肿灼热，舌质深红，舌苔黄燥等。多见于头面部癌、肺癌等，或放疗之后"],["寒毒","畏寒，脘腹冷痛，便溏，小便清长，面黄晦暗，肿块色白或暗，舌质暗淡，舌苔白腻水滑等。多见于癌病晚期，或素体阳虚，或久用苦寒者"],["风毒","头痛，眩晕，口眼喎斜，舌强不语，肢体麻木，肢体不遂，手足抽搐，行路不稳等。常见于脑瘤"]]}],"zhize":"基本治则为祛邪解毒，扶正固本。把握不同癌病及不同病程阶段，扶正与祛邪的主次先后。早期重在祛邪解毒，重攻轻补；中期宜攻补兼施；晚期重在补虚扶正，辅以祛邪解毒。手术、放化疗后机体正气亏虚，癌毒残留，易于复发转移，仍当扶正与祛邪结合。\n扶正分别采用补气、养血、滋阴、温阳等治法；祛邪分别采用理气解毒、祛风解毒、清热解毒、祛湿解毒、化痰解毒、祛瘀解毒、温阳解毒、以毒攻毒等治法。同时，顾护脾胃应贯穿治疗始终，运脾健胃，调畅腑气，确保气血生化有源。切忌过度治疗，伤脾败胃损中。","syndrome":[{"id":"s329","name":"痰瘀郁毒证","label":"1. 痰瘀郁毒证","group":"","clinic":"脘腹或颈部或皮下或乳房结块，逐渐增大，或胀痛或隐痛或刺痛，脘闷腹胀，善太息，神疲乏力，纳呆食少，或咳嗽咳痰，痰质稠黏，痰白或黄白相兼，舌质暗隐紫，苔腻，脉弦滑或细涩。","analysis":"气滞日久，津血运行不畅，痰瘀内生，留而不去，积而成块；气机郁滞，升降失司，故脘闷腹胀，善太息，神疲纳呆；气不化痰，痰气上逆，则咳嗽咳痰；舌质暗隐紫，苔腻，脉弦滑或细涩，均为气滞郁结、痰瘀内停之象。","treat":"化痰祛瘀，理气解毒。","formulaRaw":"越鞠丸（《丹溪心法》）合化积丸（《杂病源流犀烛》）加减。前方行气解郁，化痰散结；后方活血化瘀，软坚消积。","formulaName":"越鞠丸合化积丸加减","fangjie":"香附、槟榔行气活血；苍术、阿魏、海浮石化痰散结；三棱、莪术、瓦楞子、五灵脂、川芎、苏木活血化瘀，行气消癥；栀子清解郁火；神曲消食行气。疼痛明显者，加郁金、延胡索、石见穿；肿块明显者，加桃仁、半夏、浙贝母、土鳖虫；呕血或黑便者，加三七粉、白及、仙鹤草。"},{"id":"s330","name":"热毒炽盛证","label":"2. 热毒炽盛证","group":"","clinic":"局部肿块灼热疼痛，或伴溃烂流脓，身热持续，热势或高或低，口咽干燥，心烦寐差，咳嗽，无痰或少痰，或痰中带血，甚则咳血不止，胸痛或腰背痛，小便短赤，大便秘结，带下腥臭或夹脓血，舌质红绛，苔黄少津，脉洪数或细数。","analysis":"热毒凝滞脉络，故肿块灼热疼痛；血气腐败，故酿毒成脓；热炽于内，故身热，口咽干燥，心烦寐差；灼津生痰，故咳嗽少痰；热伤血络，则咳血；热注于前后二阴，故小便短赤，大便秘结，带下异常；舌质红绛，苔黄少津，脉洪数，均为热毒炽盛、阴津亏耗之象。","treat":"清热泻火，凉血解毒。","formulaRaw":"犀角地黄汤（《备急千金要方》）合黄连解毒汤（《外台秘要》）加减。前方清热解毒，凉血散瘀；后方泻火解毒。","formulaName":"犀角地黄汤合黄连解毒汤加减","fangjie":"水牛角（代犀角）清热凉血解毒；生地黄凉血生津；丹皮、赤芍凉血散瘀；黄连、黄芩、黄柏、栀子清泻脏腑火热毒邪。热毒伤阴，口咽干燥，咳嗽少痰者，加天冬、麦冬、北沙参；热毒久稽，损伤络脉，痰中带血或尿血者，加大蓟、小蓟、藕节、侧柏叶、白茅根；热毒壅盛，腑气不通者，加生大黄、芒硝。本证可合犀黄丸（《外科证治全生集》）加减。"},{"id":"s331","name":"湿热毒蕴证","label":"3. 湿热毒蕴证","group":"","clinic":"身热不扬，恶心，胸闷，口干口苦，心烦易怒，或身黄，目黄，尿黄，胁痛或腹痛，腰部或腹部肿块，便中带血或黏液脓血便，里急后重，或大便干稀不调，肛门灼热，或带下量多腥臭，舌质红，苔黄腻，脉弦滑或滑数。","analysis":"湿郁化热，故发热，恶心，口干口苦，心烦易怒；湿热搏结，阻滞气机，故胸闷，胁痛或腹痛；湿热阻滞肝胆，故身黄，目黄，尿黄；湿热阻滞经络，气滞血瘀，则见肿块，疼痛；湿热蕴结肠腑，故便中带血或黏液脓血便，里急后重，肛门灼热；湿热阻于胞宫，则带下量多腥臭；舌质红，苔黄腻，脉弦滑或滑数，均为湿热熏蒸、癌毒内蕴之象。","treat":"清热散结，祛湿解毒。","formulaRaw":"龙胆泻肝汤（《医方集解》）合五味消毒饮（《医宗金鉴》）加减。前方泻肝胆实火，清下焦湿热；后方清热解毒，消肿散结。","formulaName":"龙胆泻肝汤合五味消毒饮加减","fangjie":"龙胆草、黄芩、栀子清热除湿，泻火解毒，兼以利胆退黄；泽泻、木通、车前子清热利湿；当归、生地黄滋养肝血，防止苦燥伤正；柴胡、生甘草引经调和；金银花、野菊花、蒲公英、紫花地丁、天葵子清热解毒，消肿散结。大便脓血黏液，泻下臭秽者，合用槐角丸，加白头翁、败酱草、苦参、马齿苋；身目发黄，尿黄，便秘者，合用茵陈蒿汤，加金钱草、田基黄。"},{"id":"s332","name":"瘀毒内阻证","label":"4. 瘀毒内阻证","group":"","clinic":"局部肿块，质地坚硬，痛有定处，如锥如刺，面色晦暗，或肌肤甲错，口唇紫暗，或咳血，或吐血，或尿血，或便血，血色暗红，舌质暗或有瘀点、瘀斑，苔薄，脉涩或细弦或细涩。","analysis":"瘀血与癌毒搏结，瘢积内生，故肿块质坚，痛有定处；瘀血阻滞，经脉不通，故面色晦暗，或肌肤甲错，口唇紫暗；瘀血阻滞，血不归经，溢出脉外，故见出血；舌质暗或有瘀点、瘀斑，苔薄，脉涩或细弦或细涩，均为瘀血结滞、血脉不畅之象。","treat":"行气活血，祛瘀解毒。","formulaRaw":"血府逐瘀汤（《医林改错》)加减。","formulaName":"血府逐瘀汤加减","fangjie":"桃仁、红花、赤芍、川芎、当归、牛膝活血通经，化瘀止痛；生地黄滋阴凉血；柴胡、枳壳、桔梗调畅气机；甘草调和诸药。发热者，加丹皮、丹参、白薇；反复咳血者，去桃仁、红花，加蒲黄、三七、藕节、仙鹤草、茜草根；肢体麻木疼痛者，加桂枝、鸡血藤。"},{"id":"s333","name":"气阴两虚证","label":"5. 气阴两虚证","group":"","clinic":"神疲乏力，气少懒言，口咽干燥，头晕耳鸣，视物昏花，五心烦热，腰膝酸软，纳差，大便秘结或溏烂，舌质淡红，少苔，脉细或细数。","analysis":"癌病日久，或因手术、放疗等治疗伤正，阴伤气耗，不能充养机体，甚则阴虚生火。不同脏腑受累，表现各异：在脾可见神疲乏力，纳差，大便秘结或溏烂；在肺可见少气懒言，口咽干燥；在肾可见头晕耳鸣，视物昏花，五心烦热，腰膝酸软。舌质淡红，少苔，脉细或细数，为气阴耗伤之象。","treat":"益气养阴，扶正抗癌。","formulaRaw":"生脉地黄汤（《医宗金鉴》）加减。","formulaName":"生脉地黄汤加减","fangjie":"人参大补元气；麦冬养阴生津；五味子敛气滋阴；熟地黄、山茱萸、山药滋阴补肾，填精益髓；泽泻、丹皮、茯苓清火利湿，并使补而不滞。阴虚甚者，加沙参、石斛、炙鳖甲；气虚甚者，加生黄芪、太子参、白术；口渴明显者，加芦根、天花粉、知母；咳痰不利，痰少而黏者，加贝母、百部、杏仁；五心烦热，潮热盗汗者，加知母、地骨皮、煅龙骨、煅牡蛎。"},{"id":"s334","name":"气血双亏证","label":"6. 气血双亏证","group":"","clinic":"病延日久，形体消瘦，面色无华，唇甲色淡，气短乏力，动则尤甚，伴头昏心悸，目眩眼花，动则多汗，口干舌燥，纳呆食少，舌质红或淡，脉细或细弱。","analysis":"久病消耗，或因手术、化疗等治疗伤正，气虚血亏，形体消瘦。气虚为著，可见纳呆食少，气短乏力，动则尤甚，头昏心悸，动则多汗；血虚为著，可见面色无华，唇甲色淡，目眩眼花，口干舌燥。舌质红或淡，脉细或细弱，为气血双亏之象。","treat":"补益气血，扶正抗癌。","formulaRaw":"十全大补汤（《太平惠民和剂局方》)加减。","formulaName":"十全大补汤加减","fangjie":"人参、黄芪大补元气；炒白术、茯苓、甘草健脾益气；熟地黄、当归、白芍、川芎滋阴养血和血；肉桂温助阳气；生姜、大枣调和脾胃，以助生化气血。血虚甚者，加阿胶、制首乌、鸡血藤；纳呆食少者，加砂仁、薏苡仁、焦山楂、神曲、炒谷麦芽；下利清谷，腰酸膝冷者，加补骨脂、肉豆蔻、吴茱萸、五味子。"}],"linchuang":["综合施策，中西整合。首先，重视对癌病的早期诊断，明确病情程度、病程分期及预后。熟知当下国内外中西医各种治疗手段和规范化治疗方案，及时采取个体化综合治疗措施。其次，癌病的治疗包括手术、放疗、化疗、靶向治疗、中医药治疗等多种手段，根据患者的具体情况选择不同的方法，强调综合治疗。最后，根据中医与西医的治疗优势，明确中西医在综合治疗中的主次关系。根据疾病分期动态调整中西医主次，实现全程有机融合与优势互补。","病证结合，态靶辨治。在整体观念下，辨病辨证相结合，调态打靶相补充，是优选肿瘤用药的理论基础。辨病用药是采用抗癌通用性药物的依据，应与传统辨证用药融为一体。调态指以中药调整疾病某一阶段的核心病机，恢复人体阴阳平衡；打靶是在调态的基础上，选用现代药理研究证实对特定“靶点”有明确作用的药物，以直击病所。在肿瘤辨治中，根据其核心病机中不同类别的癌毒选药，使治疗更具有针对性。如风毒常选用白附子、露蜂房、地龙、全蝎、蜈蚣等；寒毒选用制川乌、制草乌、肉桂、细辛等；火（热）毒选用白花蛇舌草、半枝莲、蜀羊泉、麋梨根、龙葵、重楼、山豆根等；痰毒选用山慈菇、制南星、夏枯草、炙僵蚕、白芥子、猫爪草、泽漆等；瘀毒选用莪术、片姜黄、水蛭、刺猬皮、薜荔、王不留行、凌霄花等；湿毒选用苦参、茯苓、猪苓、意苡仁、土茯苓、墓头回、椿根白皮等；郁毒选用八月札、枸橘李、鸟药、合欢皮等。","以毒攻毒，谨慎用药。癌病形成缓慢，癌毒深伏脏腑经隧，潜藏骨髓血脉，胶着难解，除常规抗癌解毒法外，可考虑以毒攻毒法，即采用性峻力猛的有毒之品，尤其是虫类药，搜毒剔毒，以毒攻毒，适用于癌毒较甚且正气尚能耐受攻伐之时。常用药如红豆杉、蟾皮、蜈蚣、露蜂房、全蝎、土鳖虫、蜣螂、守宫、斑蝥、水蛭等。可依据中医理论，结合患者病情、体质因素，掌握好攻毒药的剂量和使用时间，辨证选用，合理配伍与炮制，使其更好地发挥抗癌作用。"],"yufang":["针对癌病的病因，采取相应的预防措施，减少或消除已知的危险因素，如戒烟、限酒、减少腌制食品摄入，保持起居有节、心情愉快、饮食适宜、不妄作劳等。同时加强筛检普查工作，早期发现、早期诊断、早期治疗对本病的预后有积极意义，及时治疗癌前病变。","既病之后，要使患者树立战胜疾病的信心，积极配合治疗，调畅情志，饮食清淡，易于消化，适当参加锻炼。治疗用药要“衰其大半而止”，“缓缓图之”，防止放化疗药物或中药攻邪之品过度使用耗伤正气，最大限度地提高患者生活质量，延长生存期。"],"attachIds":[]},{"id":"d048","name":"肥胖","kind":"main","parent":null,"chapterNo":"第五十一章","chapterName":"肥胖","yinbing":[{"t":"p","x":"肥胖主要是由先天禀赋不足、饮食不节、劳逸失调、情志所伤及年老体弱等因素引起，脏腑功能失调，三焦气化失常，痰湿壅盛，膏脂堆积，形成肥胖。"},{"t":"b","x":"1. 先天禀赋"},{"t":"p","x":"禀赋不足，脾肾阳气素弱，多为痰湿体质，后天多易发生肥胖。"},{"t":"p","x":"或素为阳热之体，胃强脾弱，脾运化不及，痰浊内生，膏脂堆积，可致肥胖。"},{"t":"b","x":"2. 饮食不节"},{"t":"p","x":"饮食过量，或嗜食肥甘厚味，易伤脾胃，水谷精微输布失常，郁滞为浊脂痰湿，随气流行，淤积于肌肉筋膜或腔隙，形成肥胖。"},{"t":"p","x":"某些药物，伤脾生湿，可致痰湿浊瘀内蕴，而成肥胖。"},{"t":"b","x":"3. 劳逸失调"},{"t":"p","x":"平素久坐久卧，失于运动，或足不出户，日夜颠倒，可致脾气虚弱，运化失司，内生湿痰，膏脂堆积，形成肥胖。"},{"t":"p","x":"《素问·宣明五气》谓：“久卧伤气，久坐伤肉。”"},{"t":"b","x":"4. 情志所伤"},{"t":"p","x":"七情内伤，脏腑失调，如情志抑郁，肝失疏泄，脾失健运，水谷精微运化输布不利，水湿痰浊聚积体内，发为肥胖。"},{"t":"b","x":"5. 年老体弱"},{"t":"p","x":"中年以后，或妇女产后，脏腑气弱，浊阴内生；或脾失健运，聚湿生痰，痰湿壅结；或肾阳虚衰，不能化气行水，酿生水湿痰浊，故而肥胖。"}],"bingji":[{"t":"p","x":"肥胖的基本病机是脏腑功能失调，三焦气化失常，痰湿壅盛，膏脂堆积。"},{"t":"p","x":"病位主要责之于脾胃与肌肉，与肾密切相关，涉及肝、心、肺、三焦。"},{"t":"p","x":"病理因素以痰湿为主，常见胃热、气滞、血瘀或痰饮等兼夹为病。"},{"t":"p","x":"本虚多为脾肾阳气虚衰，或兼心肺气虚；标实为痰湿膏脂内停，或兼痰饮、血瘀、气滞、郁热等。"},{"t":"p","x":"如因实致虚，初期多以胃热实证为主，若长期饮食不节，痰湿壅遏日久不解，可致脾阳不振，运化失职，由实转虚。"},{"t":"p","x":"久病则由脾及肾，形成脾肾两虚之候。"},{"t":"p","x":"或因虚致实，脾虚不运，水湿内停，痰浊壅盛，内停脏腑，阻滞经络，引起气滞、痰湿、血瘀并见，形成虚实错杂的病理状态。"},{"t":"p","x":"肥胖常与消渴、胸痹、中风、肝积等病有关。"}],"zhenduan":[{"t":"ol","items":["1. 以形体肥胖为主要表现。","2. 起病缓慢，病程长，常伴有身体沉重、头晕乏力、行动迟缓甚或动则喘促等症状。一旦形成肥胖，不易短时间内减轻体重。","3. 常有嗜食肥甘、缺乏运动的习惯，或有肥胖症的家族史。可因长期过度的精神压力以及不适当地服用药物诱发。"]}],"jianbie":[{"t":"b","x":"1. 水肿"},{"t":"p","x":"两者均形体肥胖甚则臃肿。"},{"t":"p","x":"肥胖多因饮食不节、缺乏运动、先天禀赋等原因引起，经治疗体重可减轻，但较缓慢。"},{"t":"p","x":"水肿多因风邪袭表、疮毒内犯、外感水湿、久病劳倦等导致，以颜面、四肢浮肿为主，严重者可见腹部胀满、全身皆肿，经治疗体重可迅速减轻并降至正常。"},{"t":"b","x":"2. 黄胖"},{"t":"p","x":"两者均有面部肥胖。"},{"t":"p","x":"肥胖多由于年老体弱、饮食不节、缺乏运动、情志所伤、先天禀赋等原因引起。"},{"t":"p","x":"黄胖则由肠道寄生虫所致，诸虫尤其是钩虫居于肠内，耗伤气血，脾虚生湿，导致水湿停聚，肌肤失养，以面部肿胖色黄、好食异物为特征。"}],"bianzheng":[{"t":"ol","items":["1. 辨实胖虚胖实胖者，多为中焦壅滞，气滞痰阻，以青少年为主，食欲旺盛，不节饮食，喜食甜食，运动量较少，虽胖但皮肉结实，腹部坚实，.体质较好，精力充沛；虚胖者，多为脾肾气虚，中老年居多，食量不大，毛发的浓密程度及光泽度欠佳，体重指数高，腹型肥胖多，体质欠佳，精力较差，常伴胸闷、腰膝酸软、肢体沉重、气短乏力等。","2. 辨标本虚实如食多肥胖者，多为痰湿郁热中焦，标实为主；食少肥胖者，多属脾胃虚弱，痰湿内停，本虚标实并重；青少年肥胖多在痰湿之中兼有胃热；中老年肥胖多为脾肾阳气偏虚，阳不化气，痰湿浊瘀内停；肥胖久病，多伴有气滞、血瘀等。","3. 辨脏腑病位肥胖而多食，或伴口干、大便偏干，病多在胃。肥胖伴乏力、少气懒言、疲倦少动，或伴大便溏薄、四肢欠温，病多在脾。伴腰酸背痛或腿膝酸软、尿频清长、畏寒足冷，病多及肾。伴心悸气短、少气懒言、神疲自汗等，则常病及心肺。伴胸胁胀闷、烦躁眩晕、口干口苦、大便秘结、脉弦等，则常病及肝胆。"]}],"zhize":"治疗肥胖应以补虚泻实为基本原则。补虚有健脾益气、益气温阳、脾肾并补等法。泻实常以清胃降浊法、祛湿化痰法为主，结合消导通腑、行气化痰、行气利水或痰瘀同治等法，以消除膏脂、痰浊、水湿、瘀血及郁热。肥胖虚实夹杂者居多，应标本兼治，补虚泻实并举，复法组方。","syndrome":[{"id":"s335","name":"胃热火郁证","label":"1. 胃热火郁证","group":"","clinic":"肥胖多食，消谷善饥，可有大便不爽，甚或干结，尿黄，或有口干口苦，喜饮水，舌质红，苔黄，脉数。","analysis":"过食辛辣肥甘，致胃热内郁，火灼津液。胃火盛，则食欲亢进，消谷善饥，热耗精微生脂膏致肥胖；热移肠道灼津，则便结或不爽；火灼津液，则尿黄，口干喜饮；胆热随胃气上逆，则口苦；舌红苔黄，脉数，为胃热内盛之象。","treat":"清胃泻火，佐以消导。","formulaRaw":"白虎汤（《伤寒论》）合厚朴三物汤（《金匮要略》）加减。前方清泄阳明胃腑郁热；后方行气除满，去积通便。","formulaName":"白虎汤合厚朴三物汤加减","fangjie":"生石膏、知母、甘草、粳米清泄阳明胃腑郁热；厚朴、枳实、大黄行气除满，去积通便。消谷善饥较重，口苦，嘈杂者，可合泻心汤加减；口干多饮较重者，加天花粉、葛根。少阳阳明合病者，症见胸胁苦满，心下痞硬或胀满，便秘，可用大柴胡汤。"},{"id":"s336","name":"痰湿中阻证","label":"2. 痰湿中阻证","group":"","clinic":"形体肥胖，身体沉重，肢体困倦，脘痞胸满，可伴头晕，口干而不欲饮，大便黏滞不爽，嗜食肥甘醇酒，喜卧懒动，舌质红，舌体胖大，苔白腻或黄腻，脉滑。","analysis":"过食肥甘厚味，损伤脾胃，运化失司，致水湿内停，聚湿成痰。痰湿内盛，则形体肥胖；泛溢肌肤经络，则身重困倦；气机中阻，则脘痞胸满；清阳不升，则头晕；津布失常，则口干不欲饮；湿注大肠，则便黏；脾虚湿困，则喜卧懒动；舌胖，苔腻，脉滑，为痰湿内盛之象。","treat":"化痰利湿，理气消脂。","formulaRaw":"导痰汤（《校注妇人良方》）合四苓散（《丹溪心法》）加减。前方燥湿化痰和胃，理气开郁消痞；后方利水渗湿。","formulaName":"导痰汤合四苓散加减","fangjie":"茯苓、白术、甘草、生姜健脾和胃；半夏、天南星、橘红、枳实理气化痰；猪苓、泽泻利水渗湿。若湿邪偏盛，加苍术、厚朴、枳实、薏苡仁、防已、车前子；痰湿化热，症见心烦少寐，纳少便秘，舌红苔黄，脉滑数，加竹茹、浙贝母、黄芩、黄连、瓜蒌仁等。如表里俱实，症见体格粗壮，面油腹大，喜食肥甘厚味，便秘，可用防风通圣丸。"},{"id":"s337","name":"肝郁血瘀证","label":"3. 肝郁血瘀证","group":"","clinic":"肥胖懒动，喜太息，胸闷胁满，面晦唇暗，肢端色泽不鲜，甚或青紫，可伴便干，失眠，男子阳痿，女子月经不调，经血色暗或有血块，甚或闭经，舌质暗或有瘀斑、瘀点，舌苔薄，脉弦或涩。","analysis":"情志不舒，致肝失疏泄，气机郁滞，气滞则血瘀。气滞易见喜太息，胸闷胁满；气滞血瘀，致膏脂堆积，肥胖懒动；瘀阻则面晦唇暗，肢端色暗或青紫；气郁化火则便干；瘀血扰心则失眠；瘀阻宗筋、血海，或见男子阳痿、女子月经不调；舌质暗或有瘀斑、瘀点，脉弦或涩，为血瘀之象。","treat":"理气解郁，活血化瘀。","formulaRaw":"血府逐瘀汤（《医林改错》）加减。","formulaName":"血府逐瘀汤加减","fangjie":"枳壳、柴胡、赤芍理气疏郁；桃仁、当归、红花、川芎、牛膝活血化瘀；生地黄、赤芍养血活血。本证易于化热，若舌苔偏黄，可加栀子、知母；兼气虚痰湿者，加黄芪、苍术、白术、茯苓、泽泻、荷叶等；兼见便干难排者，加姜黄、槟榔、虎杖、大黄；阳痿者，加水蛭；月经稀少者，加月季花、泽兰、益母草。"},{"id":"s338","name":"脾虚湿郁证","label":"4. 脾虚湿郁证","group":"","clinic":"肥胖臃肿，神疲乏力，身体困重，脘腹痞闷，或有四肢轻度浮肿，晨轻暮重，劳累后更为明显，饮食如常或偏少，既往多有暴饮暴食史，小便不利，大便溏或便秘，舌质淡胖，边有齿痕，苔薄白或白腻，脉濡细。","analysis":"饮食不节，致脾失健运，或素体脾虚，水谷精微与水湿聚为膏脂痰湿，发为肥胖臃肿；脾虚气弱，则神疲乏力；水湿泛溢，则身困浮肿；湿阻中焦则脘痞；湿注大肠则便溏；脾虚运化乏力则便秘；水湿不行，则小便不利；舌淡胖，有齿痕，苔白腻，脉濡细，为脾虚湿阻之象。","treat":"健脾益气，渗利水湿。","formulaRaw":"参苓白术散（《太平惠民和剂局方》）合防已黄芪汤（《金匮要略》）加减。前方健脾益气渗湿，后方益气健脾利水。","formulaName":"参苓白术散合防已黄芪汤加减","fangjie":"人参、白术、黄芪、山药健脾益气；茯苓、莲子、扁豆、薏苡仁淡渗利湿以实脾；砂仁、陈皮燥湿醒脾。身体困重明显者，加佩兰、广藿香；若浮肿明显者，加泽泻、猪苓；兼脘腹痞闷者，加半夏，或合用平胃散。"},{"id":"s339","name":"脾肾阳虚证","label":"5. 脾肾阳虚证","group":"","clinic":"形体肥胖，易于疲劳，四肢不温，甚或四肢厥冷，喜食热饮，小便清长，舌淡胖，苔薄白，脉沉细。","analysis":"脾阳虚运化无权，肾阳虚气化失司，水谷精微与水液聚为湿浊脂膏，发为肥胖；阳虚温煦不足，则易疲劳，四肢不温，喜热饮；肾阳虚，膀胱气化失常，则小便清长；舌淡胖，苔薄白，脉沉细，为脾肾阳虚之象。","treat":"补益脾肾，温阳化气。","formulaRaw":"真武汤（《伤寒论》）合苓桂术甘汤（《伤寒论》）加减。前方温阳利水；后方健脾利湿，温阳化饮。","formulaName":"真武汤合苓桂术甘汤加减","fangjie":"附子（制）、桂枝温肾阳，补脾阳，化气行水；白术、茯苓健脾益气行水；生姜温阳散寒；白芍敛阴而制姜、桂、附之燥性；甘草和中。嗜热食而恶冷饮者，加炮姜；气虚明显，乏力困倦者，加太子参、黄芪。"}],"linchuang":["肥胖病机因于痰湿，不止于痰湿。肥胖的病机以痰湿为核心。一方面，虽脾主运化，痰湿的形成关键在于脾虚，但水谷精微的运化涉及三焦，故应从五脏整体辨治肥胖。另一方面，痰湿每多郁而化热，热盛伤阴。痰阻则气滞，气滞则血瘀，久病多为痰湿瘀郁之证。临床有以痰湿郁阻为主者，或兼肝胆郁热、湿热内蕴、肾虚生痰等不同转归。如胃腑郁热者，常易耗伤阴液。总之，辨治肥胖不能止于治痰祛湿，而应治脾、治肝、治肾，与理气、清热、活血、益气、温阳等法合用，随症化裁。病变后期，肥胖与中风、消渴、胸痹、肝积等并见者，应病证结合，综合治疗。","重视药食结合。肥胖属于难治病证，受到先天禀赋、饮食、七情等多因素的影响，在辨证论治的基础上，注重食疗很必要。可酌情选用具有健脾祛湿、利水消浊之功的药物与食材，如荷叶、泽泻、赤小豆、薏苡仁、茯苓、猪苓、决明子、冬瓜皮、车前子、红曲等。此类药食两用之品可配伍于茶方、药膳或日常膳食中，以增强疗效。","综合应用非药物疗法。健康的生活方式为治疗肥胖的基础，必须积极控制饮食，规律作息，结合科学运动，并且需要长期坚持。此外，还可配合针灸、穴位贴敷、穴位埋线、推拿点穴、循经刮痧等中医非药物疗法，以协同改善肥胖。"],"yufang":["预防肥胖，饮食宜清淡而均衡，增加蔬菜、水果及粗杂粮的摄入，避免进食肥甘厚味、煎炸油腻，不过量饮酒，调整进食时间，遵循定时定量原则，严禁暴饮暴食，控制高热量零食的摄入。选择适合自身的锻炼方式，如导引、快走、骑行、游泳等。保持情绪稳定，作息有序，睡眠充足，避免长期精神紧张与作息颠倒，以维持气血调畅。","肥胖的调护是取得治疗效果的关键。应在身体耐受范围内，逐步、合理地增加运动强度。体重控制目标应切实可行，追求平稳、渐进的减轻趋势，逐步恢复至正常范围，切忌急功近利，以免耗伤正气或引发体重反弹。依据体质情况配合药膳调理，酌情选用药食两用之品。"],"attachIds":[]},{"id":"d049","name":"痹证","kind":"main","parent":null,"chapterNo":"第五十二章","chapterName":"痹证","yinbing":[{"t":"p","x":"痹证的发生是因正气不足，感受风、寒、湿、热之邪所致。风寒湿热之邪，乘虚侵袭机体，痹阻经络，气血运行不畅，或内伤痰浊瘀血，阻于经络，深入关节筋骨，甚则影响脏腑。"},{"t":"b","x":"1. 感受外邪"},{"t":"p","x":"久处湿地，涉水淋雨，或长期水下作业，或出入于冷库，或阴雨潮湿季节汗出入水，三气杂合外袭，气血痹阻，发为风寒湿痹。"},{"t":"p","x":"《素问·痹论》云：“所谓痹者，各以其时，重感于风寒湿之气也。”"},{"t":"p","x":"如外感风热，与湿相并，或风寒湿痹，郁久化热，痹阻经络、关节，发为风湿热痹。"},{"t":"b","x":"2. 饮食不节"},{"t":"p","x":"过食肥甘厚味，嗜酒或辛辣，脾失运化，痰湿或湿热内生，流注肢体关节，发为痹证。"},{"t":"p","x":"《中藏经·论肉痹第三十六》云：“肉痹者，饮食不节，膏粱肥美之所为也。”"},{"t":"b","x":"3. 劳逸不当"},{"t":"p","x":"劳倦过度，耗伤正气，机体防御功能低下，或劳后汗出当风，或汗后用冷水淋浴，外邪乘虚入侵，痹阻经络，发为痹证。"},{"t":"b","x":"4. 体质亏虚"},{"t":"p","x":"禀赋不足，素体虚弱，病后或产后气血不足，腠理空疏，卫外不固，外邪乘虚而入，痹阻经络，发为痹证。"},{"t":"p","x":"《灵枢·五变》云：“粗理而肉不坚者，善病痹。”"},{"t":"p","x":"《证治汇补·痹症》谓：“由元精内虚，而三气所袭，不能随时祛散，流注经络，久而成痹。”"}],"bingji":[{"t":"p","x":"痹证的基本病机为风、寒、湿、热外邪侵袭肢节、肌肉，经脉痹阻，气血运行失畅，不通则痛。"},{"t":"p","x":"病变部位初在肌表经络，久则深入筋骨，病及五脏。"},{"t":"p","x":"如《素问·痹论》云：“心痹者，脉不通，烦则心下鼓，暴上气而喘。”"},{"t":"p","x":"病理性质病初以邪实为主，久则虚实夹杂。"},{"t":"p","x":"病理因素以风、寒、湿、热、痰、瘀为主。"},{"t":"p","x":"痹证日久，常有三类病机演变：一是风寒湿痹或风湿热痹日久不愈，气血运行不畅，出现瘀血痰浊，痹阻经络，可见皮肤瘀斑，关节周围结节，关节肿大、变形、屈伸不利；二是病久耗伤阴阳气血津液，可致气血亏虚，肝肾不足；三是病邪由经络而内舍脏腑，出现脏腑痹，以心痹、肺痹等较为常见。"},{"t":"p","x":"痹证预后与先天禀赋、感邪轻重、体质强弱和治疗是否得当有关。"},{"t":"p","x":"若病情迁延不愈，可见关节肿胀变形，肢体功能障碍，甚则损伤内脏，预后多不佳。"}],"zhenduan":[{"t":"ol","items":["1. 痹证以肢体关节、肌肉疼痛、酸楚、麻木、重着、屈伸不利，或疼痛游走不定，甚则关节剧痛、肿大、强硬、变形、活动障碍等为主要临床表现。","2. 发病及病情的轻重常与劳累以及天气寒冷、环境潮湿、饮食不当等有关。","3. 不同年龄、性别的发病与疾病的类型有一定的关系。某些痹证的发病与先天禀赋有关。"]}],"jianbie":[{"t":"p","x":"主要与痿证鉴别。"},{"t":"p","x":"痹证与痿证均存在肢体功能障碍的临床表现。"},{"t":"p","x":"痹证是由风、寒、湿、热之邪侵袭肌肤经络，痹阻筋脉关节而致；痿证则以邪热伤阴，五脏精血亏损，经脉肌肉失养为患。"},{"t":"p","x":"鉴别要点首先在于痛与不痛，痹证以关节疼痛为主，而痿证则为肢体痿弱不用，一般无疼痛症状。"},{"t":"p","x":"其次要观察肢体的活动障碍，痿证是无力运动，痹证是因痛而影响活动。"},{"t":"p","x":"此外，部分痿证病初即有肌肉萎缩，而痹证则是由于疼痛甚或关节僵直不能活动，日久废而不用导致肌肉萎缩。"}],"bianzheng":[{"t":"ol","items":["1. 辨病邪偏盛大凡痹痛，游走不定者为行痹，属风邪盛；痛势较甚，痛有定处，遇寒加重者为痛痹，属寒邪盛；关节酸痛、重着、漫肿者为着痹，属湿邪盛；关节肿胀，肌肤发红，灼热疼痛者为热痹，属热邪盛。关节疼痛日久，肿胀局限，或见皮下结节者为痰；疼痛部位固定，关节僵硬、变形，肌肤紫暗或有瘀斑者为瘀。","2. 辨虚实痹证初起，多以邪实为主，有风寒湿与风湿热之不同；病久多属正虚邪实，虚中夹实。正虚者，有气血亏虚、肝肾不足之主次不同；邪实者，痰瘀互结，或兼风寒湿热之邪。"]}],"zhize":"痹证的治疗以祛邪通络、宣痹止痛为基本原则。根据邪气的偏盛，分别予祛风、散寒、除湿、清热、化痰、行瘀，兼以舒筋通络。久痹正虚者，应重视扶正，以补益肝肾、益气养血为法。虚实夹杂者，宜标本兼顾。李中梓《医宗必读·痹》提出“治风先治血，血行风自灭”的思想，可供临床参考。","syndrome":[{"id":"s340","name":"风寒湿痹证","label":"1. 风寒湿痹证","group":"","clinic":"肢体关节、肌肉疼痛，或游走不定，或遇寒加重，得热痛缓，或关节重着，肿胀散漫，肌肤麻木不仁，关节屈伸不利，舌质淡，苔薄白或白腻，脉弦紧或濡缓。","analysis":"风寒湿邪留滞经络，气血运行不畅，不通则痛，故见肢体关节、肌肉疼痛；疼痛影响关节活动，故见屈伸不利；若风邪偏盛，则关节疼痛游走不定；若寒邪偏盛，则疼痛遇寒加重，得热痛缓；若湿邪偏盛，则关节重着，肿胀散漫，肌肤麻木不仁；舌质淡，苔薄白或白腻，脉弦紧或濡缓，为风寒湿邪侵袭之象。","treat":"祛风散寒，除湿通络。","formulaRaw":"蠲痹汤（《医学心悟》)加减。","formulaName":"蠲痹汤加减","fangjie":"羌活、独活、秦艽、海风藤、桑枝祛风除湿通络；木香健脾理气；当归、川芎、乳香活血通络；炙甘草缓急止痛。如为行痹者，可合防风汤；痛痹者，可合乌头汤；着痹者，可合薏苡仁汤；痛在颈项、上肢者，加姜黄、葛根；痛在下肢者，加牛膝、木瓜等；病久气虚者，可加黄芪。"},{"id":"s341","name":"风湿热痹证","label":"2. 风湿热痹证","group":"","clinic":"关节疼痛，活动不利，局部灼热红肿，痛不可触，得冷则舒，或见肌肤红斑，常有发热，汗出，口渴，烦躁，溲赤，舌质红，苔黄或黄腻，脉滑数或浮数。","analysis":"风湿热邪壅滞经脉，气血郁滞不通，故见关节疼痛，活动不利，局部灼热红肿，痛不可触，得冷则舒；若热入营血，则肌肤红斑；热盛津伤，则发热，汗出，口渴，烦躁，溲赤；舌质红，苔黄或黄腻，脉滑数或浮数，为风湿热邪壅滞之象。","treat":"清热通络，祛风除湿。","formulaRaw":"白虎加桂枝汤（《金匮要略》）或宣痹汤（《温病条辨》）加减。前方清热宣痹，适用于热象明显者；后方清热利湿，宣痹通络，适用于关节疼痛明显者。","formulaName":"白虎加桂枝汤或宣痹汤加减","fangjie":"生石膏、知母、连翘、生山栀清热泻火；桂枝疏风解肌通络；防已、杏仁、薏苡仁、滑石祛风除湿，清热止痛；半夏、晚蚕砂燥湿和胃，化浊通络；赤小豆皮利水消肿；甘草、粳米益胃生津。发热、咽痛者，加薄荷、牛蒡子、桔梗；关节肿痛甚者，加桑枝、忍冬藤、肿节风；湿热偏盛者，加土获苓、草、豨签草，或合四妙丸；皮肤有红斑者，加丹皮、赤芍、生地黄、凌霄花等；邪热化火，热毒炽盛者，加犀角散。"},{"id":"s342","name":"寒热错杂证","label":"3. 寒热错杂证","group":"","clinic":"关节灼热肿痛，遇寒加重，恶风怕冷，或关节冷痛喜温，手心灼热，口干口苦，尿黄，舌红，苔白或黄，脉弦或紧或数。","analysis":"经络蓄热，客寒外侵，闭阻经脉，故见关节灼热肿痛，遇寒加重，恶风怕冷；寒郁化热，则见关节冷痛喜温，手心灼热，口干口苦，尿黄；舌红，苔白或黄，脉弦或紧或数，为寒热错杂之象。","treat":"温经散寒，清热除湿。","formulaRaw":"桂枝芍药知母汤（《金匮要略》）加减。","formulaName":"桂枝芍药知母汤加减","fangjie":"桂枝、附子（制）温通经脉，散寒止痛；防风祛风胜湿；麻黄温经散寒；白术健脾燥湿宣痹；生姜祛邪散寒；芍药、知母清热滋阴，缓急止痛；甘草调和诸药。寒重热轻者，加制川乌、威灵仙；热重于寒者，加生石膏、络石藤、豨签草；关节疼痛，恶风怕冷明显，加淫羊藿；手心灼热，舌红少苔者，加生地黄、地骨皮等。"},{"id":"s343","name":"痰瘀痹阻证","label":"4. 痰瘀痹阻证","group":"","clinic":"关节肌肉刺痛，固定不移，或关节肌肤紫暗、肿胀，按之较硬，肢体顽麻或重着，甚则关节僵硬变形，屈伸不利，有硬结、瘀斑，舌质紫暗或有瘀斑，舌苔白腻，脉弦滑或涩。","analysis":"痰瘀互结，闭阻经络，故见关节肌肉刺痛，固定不移，肢体顽麻或重着；邪气深入筋骨，则关节僵硬变形，屈伸不利；痰瘀留滞肌肤，则关节肌肤紫暗、肿胀，按之较硬，有硬结、瘀斑；舌质紫暗或有瘀斑，舌苔白腻，脉弦滑或涩，为痰瘀痹阻之象。","treat":"化痰行瘀，蠲痹通络。","formulaRaw":"双合汤（《杂病源流犀烛》）加减。","formulaName":"双合汤加减","fangjie":"桃仁、红花活血化瘀，通络止痛；当归、川芎、白芍养血活血；生地黄滋阴养血；法半夏、陈皮、茯苓、白芥子、姜汁健脾化痰，通络止痛；竹沥清热化痰；甘草调和诸药。痰浊滞留，皮下有结节者，加制南星、僵蚕；瘀血偏重，关节疼痛、肿大、强直、畸形，活动不利，加莪术、三七、土鳖虫，或合身痛逐瘀汤；疼痛久治不已者，加白花蛇、全蝎、蜈蚣等。"},{"id":"s344","name":"气血亏虚证","label":"5. 气血亏虚证","group":"","clinic":"关节疼痛、酸楚，时轻时重，气候变化、劳倦或活动后加重，神疲乏力，面色少华，形体消瘦，肌肤麻木，短气自汗，唇甲淡白，头晕目花，舌淡苔薄，脉细弱。","analysis":"风寒湿邪久留，经脉失养，故见关节疼痛、酸楚，时轻时重；气血亏虚，则神疲乏力，面色少华，形体消瘦，肌肤麻木，短气自汗，唇甲淡白，头晕目花；气虚卫外不固，劳则愈加耗伤气血，故病情随气候变化、劳倦或活动后加重；舌淡苔薄，脉细弱，为气血亏虚之象。","treat":"益气养血，和营通络。","formulaRaw":"黄芪桂枝五物汤（《金匮要略》）加减。","formulaName":"黄芪桂枝五物汤加减","fangjie":"黄芪益气；白芍养血和营；桂枝和营通络；生姜、大枣调和脾胃。血虚明显者，重用当归，加生地黄、熟地黄；阴虚者，加玄参、石斛、山茱萸；兼有寒象者，加附子（制）；便潴者，加炒白术、苍术、茯苓、炒薏苡仁；肢体麻木者，加苏木、路路通等。"},{"id":"s345","name":"肝肾不足证","label":"6. 肝肾不足证","group":"","clinic":"关节疼痛时轻时重，腰膝酸软，疲劳时加重，关节屈伸不利，肌肉瘦削，或伴畏寒肢冷，阳痿，遗精，或伴骨蒸劳热，心烦，口干，舌质淡红，苔薄白或少津，脉沉细或细数。","analysis":"肝肾不足，筋骨失养，故见关节疼痛时轻时重，腰膝酸软，疲劳时加重，关节屈伸不利，肌肉瘦削；若偏阳虚者，则伴畏寒肢冷，阳痿，遗精；若偏阴虚者，则伴骨蒸劳热，心烦，口干；舌质淡红，苔薄白或少津，脉沉细或细数，为肝肾不足之象。","treat":"补益肝肾，通络止痛。","formulaRaw":"独活寄生汤（《备急千金要方》）加减。","formulaName":"独活寄生汤加减","fangjie":"独活、桑寄生祛风湿，补肝肾，强筋骨，除痹痛；防风、秦艽祛风化湿止痛；杜仲、牛膝补益肝肾；桂心、细辛温经通络；当归、川芎、干地黄、芍药养血活血；人参、茯苓、甘草健脾益气。若肾气虚，腰膝酸软甚，加鹿角霜、续断；肾阳虚，加附子（制）、鹿角片、淫羊藿；肝肾阴虚，腰膝疼痛，低热心烦，或午后潮热，加生地黄、青蒿、地骨皮等；兼有气虚者，可合用三痹汤。"}],"linchuang":["辨病位用药。根据痹证的病位不同，在辨证的基础上有针对性地使用药物，以提高疗效。痹在上肢可选用片姜黄、羌活、桂枝、桑枝、秦艽以通经达络，祛风胜湿；痹在下肢者可选用独活、川牛膝、木爪以引药下行；累及颈项，出现颈部僵硬不适、疼痛者，可选用葛根、伸筋草、桂枝以舒筋通络，祛风止痛；腰部疼痛、僵硬，弯腰活动受限者，可选用桑寄生、杜仲、巴戟天、广虫以补肾强腰，化瘀止痛；两膝关节肿胀，或有积液者，可用土茯苓、薏苡仁、天仙藤以清热除湿，消肿止痛。","重视舒筋通络药物。在辨证治疗的基础上，加用有舒筋通络止痛的药物，有助于提高疗效。①藤类中药：鸡血藤、海风藤、络石藤、忍冬藤、钩藤、青风藤、穿山龙、天仙藤、鸡矢藤、大血藤等。藤类药物盘根错节，缠绕蔓延，形如络脉，具舒展、蔓延之性，多善走经络，有“引经通络止痛”之用。如《本草便读》云：“藤蔓之属，皆可通经入络。此物味苦平，善治风疾，故一切历节麻痹皆治之。”②虫类中药：全蝎、蜈蚣、地龙、水蛭、白花蛇、乌梢蛇、露蜂房等。痹证久病入络，抽掣疼痛，肢体拘挛者，选用虫类药，可搜风通络止痛。如叶天士《临证指南医案·痹》云：“邪留经络，须以搜剔动药。”但虫类药物性多辛温，作用较猛，有一定毒性，故用量不可太大，不宜久服。","谨慎应用有毒药物。治疗顽固性痹痛，常选用有一定毒性的药物，如附子、川乌、草乌、马钱子、雷公藤等，可提高疗效，但在运用时，应注意以下几点：①注意炮制方法：如雷公藤须去皮，马钱子一般不入煎剂，附子、川乌、草乌应制用，先煎3小时以上以减毒。②严格掌握用量：药量应根据病情、体质而定，宜从小剂量开始递增，如制川乌、制草乌初用3～5g，无不良反应者，可渐增至6～12g，为防止中毒，可加甘草同煎，可缓解毒性。③注意药后反应：若有唇舌发麻、恶心、头晕、心悸、脉迟有歇止者，为中毒反应，应立即停药，并予解毒处理。","注重内外、动静结合。①内外结合：除内服汤药外，还可应用膏剂、丸剂、散剂、酒剂等剂型，配合外治疗法，如中药封包、中药熏蒸、中药热罨包、针灸、推拿、按摩及小针刀等多法综合应用，杂合以治，可提高疗效。②动静结合：急性期，病情较重，宜以静卧休息为主；病情缓解后，可逐步增加活动；恢复期，宜以动为主，加强关节功能锻炼，使经络气血流通，体质增强，有助于关节功能的恢复。"],"yufang":["改善生活与工作环境，避免久处湿地，防止感受风寒湿邪。对于在水下或潮湿环境中作业者，平时应注意生活调摄，多晒太阳，防寒保暖，加强锻炼，调护正气。","痹证初发，应积极治疗，防止病邪传变。疼痛剧烈、病情较重者，应卧床休息，适当对患处进行药物热熨、冷敷等，亦可配合针灸、推拿等进行治疗；关节畸形、活动不利者，应防止跌仆，以免发生骨折。鼓励和帮助患者对病变肢体进行功能锻炼，有助于痹证康复。"],"attachIds":[]},{"id":"d050","name":"痿证","kind":"main","parent":null,"chapterNo":"第五十三章","chapterName":"痿证","yinbing":[{"t":"p","x":"外感温毒、湿热之邪，内伤情志、饮食劳倦、先天不足、房事不节、跌仆瘀阻及接触毒（药）物等，引起五脏受损，精津不足，气血亏耗，肌肉筋脉失养，发为痿证。"},{"t":"b","x":"1. 感受温毒"},{"t":"p","x":"温热毒邪内侵，或病后余邪未尽，内热燔灼，伤津耗气，肺热叶焦，津伤失布，不能润泽五脏，五体失养，而痿弱不用，"},{"t":"p","x":"此即《素问·痿论》所云“五脏因肺热叶焦，发为痿壁”。"},{"t":"b","x":"2. 湿热浸淫"},{"t":"p","x":"久处湿地或冒雨涉水，感受外来湿邪，郁遏化热，湿热浸淫经脉，营卫运行受阻、气血运行不畅，致筋脉失于滋养而成痿。"},{"t":"p","x":"正如《素问·瘘论》所云：“有渐于湿，以水为事，若有所留，居处相湿，肌肉濡渍，痹而不仁，发为肉痿。”"},{"t":"b","x":"3. 饮食、毒（药）物所伤"},{"t":"p","x":"素体脾胃虚弱，或劳倦思虑过度，中气受损，脾胃受纳、运化、输布功能失常，气血津液生化不足，无以濡养五脏，以致筋骨肌肉失养，或饮食不节，嗜酒辛辣，损伤脾胃，运化失职，痰湿或湿热内生，阻于经脉，肢体失养，均可致痿。"},{"t":"p","x":"此外，服用或接触毒（药）物，损伤气血经脉，经气运行不利，脉道失畅，亦可致痿。"},{"t":"b","x":"4. 劳病体虚"},{"t":"p","x":"先天不足，或久病体虚，伤及肝肾，精血亏虚，或劳役、房事太过而伤肾，耗损阴精，肾水亏虚，筋脉失于濡养，发为痿证。"},{"t":"b","x":"5. 跌仆瘀阻"},{"t":"p","x":"跌仆损伤，瘀血阻络，新血不生，肢体失养，或产后恶露未尽，瘀血流注于腰膝，气血瘀阻不畅，脉道不利，四肢失于濡润滋养，发为痿证。"}],"bingji":[{"t":"p","x":"痿证的基本病机是五脏受损，精津不足，气血亏耗，肌肉筋脉失养。"},{"t":"p","x":"病变部位在筋脉肌肉，但根柢在于五脏虚损。"},{"t":"p","x":"病理性质以热证、虚证为多，亦有虚实夹杂者。"},{"t":"p","x":"外感温毒、湿热所致者，病初阴津耗伤不甚，邪热偏重，故属实证；但日久肺胃津伤，肝肾阴血耗损，则由实转虚，或虚实夹杂。"},{"t":"p","x":"内伤致病，脾胃虚弱，肝肾亏损，气血阴精亏耗，则以虚证为主，但可夹湿、热、痰、瘀等病理因素，表现本虚标实之候。"},{"t":"p","x":"故临床常呈现因实致虚、因虚致实和虚实错杂的复杂病机。"},{"t":"p","x":"五脏病变，皆能致痿，且可相互传变。"},{"t":"p","x":"肾水亏虚，津液匮乏，津血同源，津亏血瘀，或跌仆瘀阻，均可导致脉络失畅，筋脉失养，致使病程缠绵难愈。"},{"t":"p","x":"此外，久痿虚极，脾肾精气衰败，病情危笃。"},{"t":"p","x":"病情迁延，出现呼吸、吞咽困难，危及生命，则属痿之重症，预后极差。"}],"zhenduan":[{"t":"ol","items":["1. 肢体筋脉弛缓不收，下肢或上肢，一侧或双侧，软弱无力，甚则瘫痪，部分患者伴有肌肉萎缩。","2. 由于肌肉痿软无力，可有睑废、视歧、声嘶喑哑、抬头无力等症状，甚则影响呼吸、吞咽。","3. 部分患者发病前有感冒、腹泻病史，有的患者有神经毒性药物接触史或家族遗传史。"]}],"jianbie":[{"t":"b","x":"1. 偏枯"},{"t":"p","x":"痿证和偏枯都是以肢体软弱无力为主要表现的病证。"},{"t":"p","x":"偏枯亦称半身不遂，是中风症状，病见一侧上下肢偏废不用，常伴有语言謇涩、口眼喝斜，久则患肢肌肉萎缩。"},{"t":"p","x":"其瘫痪是由中风所致，二者临床不难鉴别。"},{"t":"b","x":"2. 痱证"},{"t":"p","x":"痿证和痱证均有肢体无力的临床表现。"},{"t":"p","x":"《灵枢·热病》云：“痱之为病也，身无痛者，四肢不收，智乱不甚，其言微知，可治；甚则不能言，不可治也。”"},{"t":"p","x":"由此可见，痱证除四肢无力外，还有神志病变，语声不出，可资鉴别。"}],"bianzheng":[{"t":"b","x":"1. 辨脏腑病位"},{"t":"p","x":"痿证初起，症见发热，咳嗽，咽痛，或在热病之后出现肢体软弱不用者，病位多在肺；症见四肢痿软无力，神疲肢倦，纳呆便溏，下肢微肿，病位多在脾胃；下肢痿软无力明显，甚则不能站立，腰脊酸软，头晕耳鸣，遗精阳痿，月经不调，病位多在肝肾。"},{"t":"b","x":"2. 辨标本虚实"},{"t":"p","x":"因感受温热毒邪或湿热浸淫者，多急性发病，病情进展较快，属实证。因热邪最易耗津伤正，故疾病早期也可见虚实错杂之证。因内伤积损，久病不愈，常见脾胃虚弱和肝肾阴虚，多属虚证，但又常兼夹郁热、湿热、痰浊、瘀血，而虚中有实。跌打损伤，瘀阻脉络，或痿证日久，气虚血瘀，也属常见。"}],"zhize":"痿证的治疗当分虚实。虚证宜以扶正补虚为主。脾胃虚弱者，宜益气健脾；肝肾亏虚者，宜滋养肝肾。实证宜以祛邪和络为主。肺热伤津者，宜清热润燥；湿热浸淫者，宜清热利湿；瘀阻脉络者，宜活血行瘀。虚实兼夹者，又当扶正与祛邪兼顾。《素问·痿论》言“治痿者独取阳明”，意为须重视调治脾胃。痿证不可妄用辛温发散风药，因辛温发散治风之剂，皆发散风邪、开通媵理之药，若误用之，阴血愈燥，酿成坏病。","syndrome":[{"id":"s346","name":"肺热津伤证","label":"1. 肺热津伤证","group":"","clinic":"发病急，病起发热，或热后突然出现肢体软弱无力，可较快出现肌肉瘦削，皮肤干燥，心烦口渴，咳呛少痰，咽干不利，小便黄少，大便干燥，舌质红，苔黄，脉细数。","analysis":"温热之邪犯肺，致病迅速，肺脏气阴受伤，津液不足以敷布全身，筋脉肌肤失养，故见发病急，发热，肢体软弱无力，肌肉瘦削，皮肤干燥；热邪伤津，故心烦口渴，溲短便燥；肺津不能上润肺系，故咳呛少痰，咽干不利；舌质红，苔黄，脉细数，为阴伤津涸、虚热内炽之象。","treat":"清热润燥，养阴生津。","formulaRaw":"清燥救肺汤（《医门法律》）加减。","formulaName":"清燥救肺汤加减","fangjie":"人参、麦冬、生甘草甘润生津养阴；阿胶、胡麻仁养阴血以润燥；生石膏、桑叶、苦杏仁、炙枇杷叶清热宣肺。若身热未退，高热，口渴有汗，重用生石膏，加金银花、连翘、知母；咳嗽痰多，加瓜蒌、桑白皮、川贝母；咳呛少痰，咽喉干燥，加玄参、天花粉、芦根。身热已退，食欲减退，口干咽干较甚，此胃阴亦伤，宜用益胃汤加石斛、天冬、麦芽等。"},{"id":"s347","name":"湿热浸淫证","label":"2. 湿热浸淫证","group":"","clinic":"起病较缓，逐渐出现肢体困重，痿软无力，尤以下肢或两足痿弱为甚，兼见微肿，手足麻木，足胫蒸热，或有全身发热，胸脘痞闷，小便赤涩热痛，舌质红，舌苔黄腻，脉濡数或滑数","analysis":"湿热浸淫肌肤，其性黏滞，起病较缓，逐渐出现肢体困重或微肿；气血运行不畅，故手足麻木；湿热浸淫筋脉，气血阻滞，故肢体痿软无力，以下肢或两足痿弱为甚；湿热郁蒸，故足胫蒸热，或全身发热；湿热阻滞气机，故胸脘痞闷；湿热下注，则小便赤涩热痛；舌质红，舌苔黄腻，脉濡数或滑数，为湿热内蕴之象。","treat":"清热利湿，通利经脉。","formulaRaw":"加味二妙丸（《寿世保元》）加减。","formulaName":"加味二妙丸加减","fangjie":"苍术、黄柏清热燥湿；草、防已渗湿分利；牛膝利湿通络；当归尾活血化瘀；龟甲滋阴壮骨。若湿邪偏盛，胸脘痞闷，肢重且肿，加厚朴、茯苓、枳壳、陈皮；热邪偏盛，身热肢重，小便赤涩热痛，加忍冬藤、连翘、蒲公英；湿热伤阴，两足热，心烦口干，舌质红或舌苔中剥，脉细数，去苍术，重用龟甲，加玄参、山黄肉、生地黄；若兼有瘀血阻滞，肌肉顽痹不仁，关节活动不利或有痛感，舌质紫暗，脉涩，加丹参、鸡血藤、赤芍、桃仁、红花等。"},{"id":"s348","name":"脾胃虚弱证","label":"3. 脾胃虚弱证","group":"","clinic":"起病缓慢，肢体软弱无力逐渐加重，肌肉萎缩，神疲肢倦，少气懒言，纳呆便溏，面色萎黄无华，面浮，舌淡，苔薄白，脉细弱。","analysis":"脾胃虚弱，气血化源不足，筋脉渐失荣养，故起病缓慢，肢体软弱无力逐渐加重，肌肉萎缩；气血不足，故神疲肢倦，少气懒言，面色萎黄无华；脾虚清阳不升，水湿不化，故纳果便溏，面浮；舌淡，苔薄白，脉细弱，为脾胃虚弱、气血亏虚之象。","treat":"补中益气，健脾升清。","formulaRaw":"参苓白术散（《太平惠民和剂局方》）合补中益气汤（《内外伤辨惑论》）加减。前方以健脾益气利湿为主，后方重在健脾益气养血。","formulaName":"参苓白术散合补中益气汤加减","fangjie":"人参、白术、山药、白扁豆、莲子肉、甘草、大枣补脾益气；黄芪、当归益气养血；薏苡仁、获苓、砂仁、陈皮健脾和胃，理气化湿；升麻、柴胡升举清阳；桔梗宣利肺气。脾胃虚弱，食积不运者，加谷芽、麦芽、山楂、神曲；气血虚甚者，加西洋参、黄精、阿胶；气血不足兼有血瘀者，唇舌紫暗，脉兼涩象，加丹参、川芎、赤芍、川牛膝等。"},{"id":"s349","name":"肝肾亏损证","label":"4. 肝肾亏损证","group":"","clinic":"起病缓慢，渐见肢体痿软无力，尤以下肢明显，腰膝酸软，不能久立，甚至步履全废，腿胫大肉渐脱，或伴有眩晕耳鸣，舌咽干燥，遗精或遗尿，妇女月经不调，舌红少苔，脉细数。","analysis":"肝肾亏虚，精血不能濡养筋骨经脉，故渐成痿证，肢体痿软无力，尤以下肢明显；腰为肾之府，肾主骨，精髓不足，故腰膝酸软，不能久立；久则髓枯筋燥，甚至步履全废，腿胫大肉渐脱；肝肾精血亏虚，不能上承，故或伴有眩晕耳鸣，舌咽干燥；肾司二便，主藏精，肾虚不能藏精，故见遗精或遗尿；肝肾亏虚，冲任失调，故见月经不调；舌红少苔，脉细数，为阴虚内热之象。","treat":"补益肝肾，滋阴清热。","formulaRaw":"虎潜丸（《丹溪心法》）加减。","formulaName":"虎潜丸加减","fangjie":"狗骨（代虎胫骨）强筋骨，利关节；熟地黄、龟甲、知母、黄柏滋阴清热；锁阳温肾益精；白芍养血柔肝；干姜、陈皮温中理气和胃，既防苦寒败胃，又使滋而不腻。若阴损及阳，阴阳两虚，兼有神疲，怯寒怕冷，阳痿早泄，尿频而清，脉沉细无力，去黄柏、知母，加淫羊藿、鹿角霜、紫河车、附子（制）、肉桂；腰脊酸软甚者，加杜仲、续断、补骨脂、狗脊；热甚者，去锁阳、干姜，或用六味地黄丸加牛骨髓、鹿角胶、构杞子滋阴补肾；遗精遗尿甚者，加金樱子、桑螺蛸、覆盆子等。"},{"id":"s350","name":"脉络瘀阻证","label":"5. 脉络瘀阻证","group":"","clinic":"久病体虚，四肢瘘弱，肌肉瘦削，手足麻木不仁，四肢青筋显露，肌肤甲错，舌痿伸纵不利，舌质暗淡或有瘀点瘀斑，脉细涩。","analysis":"久病入络，气虚血瘀，阻滞经络，肢体筋脉失养，故四肢痰弱，肌肉瘦削，手足麻木不仁；瘀血阻滞，经络不通，故四肢青筋显露，肌肤甲错；气虚血瘀，舌体筋脉失于气血濡养，故舌痰伸缩不利；舌质暗淡或有瘀点瘀斑，脉细涩，为气虚血瘀之象。","treat":"益气养营，活血行瘀。","formulaRaw":"圣愈汤（《兰室秘藏》）合补阳还五汤（《医林改错》）加减。前方以益气养血为主，后方重在补气活血通络。","formulaName":"圣愈汤合补阳还五汤加减","fangjie":"人参、黄芪益气；当归（尾）、熟地黄、白芍养血和血；赤芍、川芎、地龙、桃仁、红花活血化瘀通络。若手足麻木，舌苔厚腻者，加薏苡仁、木瓜；下肢痿软无力，加杜仲、补骨脂、桑寄生；形体消瘦，手足痰弱，为瘀血久留，用圣愈汤送服大黄应虫丸。"}],"linchuang":["扶正不助邪，祛邪不伤正。本病虚证居多，或虚实错杂。扶正补虚要分清气虚还是阴虚，气虚洽阳明、阴虚补肝肾，补虚扶正时应当防止恋邪助邪。此外，本病常有湿热、痰湿为患，用苦寒、燥湿、辛温等药物时要时时注意护阴，避免伤正。","重视调畅气血。痰证日久，坐卧少动，气血亏虚，运行不畅，治疗可酌情配合养血活血通络之品，即如吴师机所言“气血流通即是补。“若元气亏损，气虚血滞成痿，又当补气化瘀。若因情志太过而成痰者，宜调理气机为法，盖气化正常，气机畅顺，百脉皆通，其病可愈。","洽痿者独取阳明。《素问·痿论》原意指针刺治疗“取阳明”，但作为方药论洽同样具有重要价值，主要是指采用补益脾胃的方法治疗痿证。肺之津液来源于脾胃，肝肾的精血亦有赖于脾胃的生化，脾胃功能健旺，则气血津液充足，脏腑功能旺盛，筋脉得以濡养，有利于痿证恢复。“独取阳明”尚包括法除邪气，调理脾胃。如《灵枢·根结》云：“故痿疾者取之阳明，视有余不足，无所止息者，真气稽留，邪气居之也。”明·秦景明《症因脉治·痿证论》谓：“今言独取阳明者，以痿证乃阳明实热致病耳……故清除积热，则二便如常，脾胃清和，输化水谷，生精养血，主润宗筋，而利机关。”可见，清阳明之热亦属“独取阳明”范畴。总之，治痿独取阳明，临床可以从以下三方面来理解：一是不论选方用药，针灸取穴，都应重视补益脾胃；二是“独取阳明”尚包括清胃火、祛湿热，以调理脾胃；三是临证时要重视辨证施治。","内外合法，杂合以洽。《素间·痿论》云：“各补其荥而通其俞，调其虚实，和其逆顺，筋脉骨肉，各以其时受月，则病已矣。”提示治痿还需根据痿证的病变部位、虚实顺逆进行辨证论治。诚如张介宾《类经·痿证》所注：“如筋痿者，取阳明厥阴之荥俞；脉痿者，取阳明少阴之荣俞；肉痿骨痿，其洽皆然。”临床上对痰证的治疗除内服药物外，还应配合针灸、推拿、康复等综合疗法，并应加强肢体活动，有助于提高疗效。"],"yufang":["避居湿地，防御外邪侵袭，注意精神和饮食调养。如《素间·痿论》云：“思想无穷，所愿不得，意淫于外，人房太甚，宗筋弛纵，发为筋痿。”故应注意精神调养，清心寡欲，避免过劳，生活规律，饮食宜清淡而富有营养，忌食辛辣及肥甘厚味。","生活自理者，可散步、打太极拳、练五禽戏。病情较重者，可经常用手轻轻拍打患肢，进行四肢屈伸锻炼。病情危重，吞咽呛咳、呼吸困难者，要常翻身拍背，鼓励患者咳痰，以防痰湿壅肺、压疮发生。对瘫痪者，嘱家属帮助其疏理筋骨，防止肢体挛缩和关节僵硬。"],"attachIds":[]},{"id":"d051","name":"颤证","kind":"main","parent":null,"chapterNo":"第五十四章","chapterName":"颤证","yinbing":[{"t":"p","x":"颤证的发生主要因年老体虚、情志过极、饮食不节、劳逸失当等，引起风阳内动，或痰热动风，或瘀血夹风，或虚风内动，或肾精气血亏虚，进而筋脉失约，而发为颤证。"},{"t":"b","x":"1. 年老体虚"},{"t":"p","x":"中年之后，脾胃渐损，肝肾亏虚，精气暗衰，筋脉失养；或禀赋不足，肾精虚损，脏气失调；或罹患沉疴，久病体弱，脏腑功能紊乱，气血阴阳不足，筋脉失养，虚风内动。"},{"t":"b","x":"2. 情志过极"},{"t":"p","x":"情志失调，郁怒忧思太过，脏腑气机失于调畅。郁怒伤肝，肝失疏泄，肝气郁结，气滞则血瘀，筋脉失养；或肝郁化火伤阴，阴亏阳亢化风，风阳暴张，窜经入络，扰动筋脉；或思虑太过，损伤心脾，气血生化乏源，筋脉失养；或因肝失疏泄，脾虚不运，津液失于输布，聚湿生痰，痰浊流窜，扰动筋脉，引起颤证。"},{"t":"b","x":"3. 饮食不节"},{"t":"p","x":"恣食膏粱厚味或嗜酒成癖，损伤脾胃，脾失健运，聚湿生痰，痰浊阻滞经络而动风；或滋生内热，痰热互结，壅阻经脉而动风；或因饥饱无常，过食生冷，损伤脾胃，气血化源不足，而致筋脉失养，发为颤证。"},{"t":"b","x":"4. 劳逸失当"},{"t":"p","x":"行役劳苦，动作不休，肌肉筋膜疲极损伤，虚风内动；或贪逸少动，气缓脾滞，气血日减，筋脉失于濡养而不得任持自主；或房劳太过，肝肾亏虚，阴血耗伤，筋脉失于濡养，阴虚风动，发为颤证。"}],"bingji":[{"t":"p","x":"颤证的基本病机是肝风内动，筋脉失约。"},{"t":"p","x":"病变部位在筋脉，与肝、脾、肾等脏关系密切。"},{"t":"p","x":"病理性质总属本虚标实。"},{"t":"p","x":"本虚包括气血阴阳亏虚，以阴津精血亏虚为主；标实常见风、火、痰、瘀等病理因素。"},{"t":"p","x":"虚实之间常相互影响，相互转化。"},{"t":"p","x":"如风火相扇，气血阴精耗伤，不能濡养筋脉，或痰浊、瘀血壅阻经脉，气血运行不畅，筋脉失养，或热甚动风，扰动筋脉，而致肢体拘急颤动，发为颤证。"},{"t":"p","x":"颤证日久可导致气血不足，络脉瘀阻，表现为肢体拘急僵硬，动作迟滞乏力，甚则活动困难，肢体痿废。"}],"zhenduan":[{"t":"ol","items":["1. 头部及肢体颤抖、摇动，不能自制，甚者颤动不止，四肢强急。","2. 常伴动作笨拙、活动减少、多汗流涎、说话缓慢不清、烦躁不寐、神志呆滞等症状。","3. 多发生于中老年人，一般隐匿起病，逐渐加重，不能自行缓解。部分患者发病与情志有关，或继发于脑部病变。"]}],"jianbie":[{"t":"p","x":"主要与瘛疭鉴别。"},{"t":"b","x":"1. 瘛疭"},{"t":"p","x":"颤证及瘛疭均可出现肢体或头部的非自主性运动。"},{"t":"p","x":"瘛疭即抽搐，抽动幅度大、频率低且不规则，抽搐多呈持续性，有时伴短阵性间歇，手足屈伸牵引，张弛交替，部分患者可有发热、两目上视、神昏等症状；起病急骤，多因热盛动风或阴虚风动引发，常见于急性热病或某些慢性疾病急性发作。"},{"t":"p","x":"颤证手足颤抖动作幅度小，频率高，情绪紧张时加重，自主运动时减轻，无肢体抽搐牵引及发热、神昏等症状，是一种慢性疾病过程，多伴随肝肾亏虚、气血两虚等虚证表现。"}],"bianzheng":[{"t":"p","x":"辨清标本虚实。本虚为肝肾阴虚、气血不足；标实为风、火、痰、瘀等。一般震颤较剧，肢体僵硬，烦躁不宁，胸闷体胖，遇怒而发者，多为实证；颤抖无力，缠绵难愈，腰膝酸软，体瘦眩晕，遇烦劳而加重者，多为虚证。病久常标本虚实夹杂，临证须仔细辨别其主次偏重、邪正盛衰。"}],"zhize":"颜证的治疗以息风柔筋、补虚泻实为基本治则。初期，本虚之象并不明显，常见风火相扇、痰热壅阻之标实证，治以清热、化痰、息风为主；病程较长，年老体弱，治以滋补肝肾、益气养血、调补阴阳为主，兼以息风通络。中老年人多因虚致实，应重视补益肝肾。","syndrome":[{"id":"s351","name":"风阳内动证","label":"1. 风阳内动证","group":"","clinic":"肢体颤动，程度较重，不能自制，头晕耳鸣，头胀，面赤烦躁，易激动，心情紧张时颜动加重，伴有肢体麻木，口苦而干，语言迟缓不清，流涎，尿赤，大便干，舌质红，苔黄，脉弦数。","analysis":"肝郁化火，肝阳上亢，风阳内动，筋脉挛急，故见头晕，头胀，面红，渐见头摇肢颤，不能自主，且紧张时颤动加重；阳亢火旺，则烦躁易怒，口苦口干，尿赤，大便干，舌质红，苔黄，脉弦数，为肝郁阳亢之象。","treat":"镇肝息风，舒筋止颤。","formulaRaw":"天麻钩藤饮（《杂病证治新义》）合镇肝息风汤（《医学衷中参西录》）加减。前方平肝息风，清热安神，后方镇肝息风，育阴潜阳，舒筋止颜。","formulaName":"天麻钩藤饮合镇肝息风汤加减","fangjie":"天麻、钩藤、石决明、代赭石、生龙骨、生牡蛎镇肝息风止颜；白芍、玄参、龟甲、天冬育阴清热，潜阳息风；怀牛膝、杜仲、桑寄生滋补肝肾；川棟子疏肝理气；黄芩、栀子清热泻火；夜交藤、茯神宁心安神。若肝火偏盛，焦虑心烦，加龙胆草、夏枯草；咳吐痰涎，痰湿内蕴，加竹沥、天竺黄；阴虚火旺，眩晕耳鸣，烦躁，加知母、黄柏、牡丹皮；烦躁失眠，加琥珀、磁石、酸枣仁、柏子仁、丹参；颤动不止，加僵蚕、全蝎。"},{"id":"s352","name":"痰热风动证","label":"2. 痰热风动证","group":"","clinic":"头摇不止，肢麻震颜，重则手不能持物，头晕目眩，胸脘痞闷，口苦口黏，甚则口吐痰涎，舌体胖大，有齿痕，舌质红，舌苔黄腻，脉弦滑数。","analysis":"脾失健运，聚湿生痰，肝郁化火，痰热内蕴，阳盛风动，筋脉失约，以致头摇不止，肢麻震颤；痰热蕴脾，则胸脘痞闷，口苦口黏；痰湿内盛，则口吐痰涎；舌体胖大，有齿痕，舌质红，舌苔黄腻，脉弦滑数，均为痰热内蕴、热极生风之象。","treat":"清热化痰，平肝息风。","formulaRaw":"导痰汤（《传信适用方》）合羚角钩藤汤（《通俗伤寒论》）加减。前方化痰行气，后方清热平肝息风。","formulaName":"导痰汤合羚角钩藤汤加减","fangjie":"法半夏、胆南星、竹茹、川贝母清热化痰；羚羊角、桑叶、钩藤、菊花、茯神平肝息风止颤；生地黄、生白芍、甘草育阴清热，缓急止颤；橘红、茯苓、枳实、生姜健脾化痰理气。若痰湿内聚，胸闷恶心，咳吐痰涎，苔厚腻，脉滑，加皂角、白芥子；震颤较重，加珍珠母、石决明、全蝎；心烦易怒，加天竺黄、牡丹皮、郁金；胸闷脘痞，加爪蒌皮、厚朴、苍术；肌肤麻木不仁，加地龙、丝瓜络、竹沥；痰迷心窍，神识呆滞，加石菖蒲、远志。"},{"id":"s353","name":"气血亏虚证","label":"3. 气血亏虚证","group":"","clinic":"头摇肢颤，面色㿠白，表情淡漠，神疲乏力，动则气短，心悸健忘，眩晕，纳呆，舌体胖大，舌质淡红，舌苔薄白滑，脉沉濡无力或沉细弱。","analysis":"脾胃受损，气血生化乏源，气血两虚，筋脉失养，虚风内动，故头摇肢颤；气血两虚，虚风内动，故面色㿠白，表情淡漠，神疲乏力，动则气短，心悸健忘，眩晕；舌体胖大，舌质淡红，舌苔薄白滑，脉沉濡无力或沉细弱，皆为气血两虚之象。","treat":"益气养血，濡养筋脉。","formulaRaw":"人参养荣汤(《太平惠民和剂局方》）加减。","formulaName":"人参养荣汤加减","fangjie":"熟地黄、当归、白芍、人参、白术、黄芪、茯苓、炙甘草健脾益气养血；肉桂助阳，鼓舞气血生长；五味子、炒远志养心安神；陈皮理气和胃。若气虚运化无力，湿聚成痰，应化痰通络止颤，加半夏、白芥子、胆南星；血虚心神失养，心悸，失眠，健忘，加炒酸枣仁、柏子仁；肢体颤抖，疼痛麻木，气虚血滞，加鸡血藤、丹参、桃仁、红花。"},{"id":"s354","name":"髓海不足证","label":"4. 髓海不足证","group":"","clinic":"头摇肢颤，持物不稳，腰膝酸软，失眠心烦，头晕耳鸣，善忘，或神识呆滞，舌质红，舌苔薄白，或红绛无苔，脉细数。","analysis":"年老肝肾亏虚，筋脉失养，虚风内动，则头摇肢颤，持物不稳，腰膝酸软；髓海失充，神机失用，不能上荣头目，故头晕耳鸣，善忘，神识呆滞；舌质红，舌苔薄白，或红绛无苔，脉细数，均为髓海不足之象。","treat":"填精补髓，育阴息风。","formulaRaw":"龟鹿二仙膏（《医便》）合大定风珠（《温病条辨》）加减。前方重在补气填精益髓；后方滋补肝肾、育阴息风。","formulaName":"龟鹿二仙膏合大定风珠加减","fangjie":"龟甲、鳖甲、鸡子黄、阿胶、生地黄、枸杞子填补精髓，养血滋阴；人参益气；鹿角温肾益精；生牡蛎、白芍育阴潜阳，平肝息风；麦冬、麻仁滋阴养血润燥；五味子、甘草酸甘化阴以安神。若肢体颤抖、眩晕较甚，加天麻、全蝎、石决明；肢体麻木，拘急强直，加木瓜、僵蚕、地龙，重用白芍、甘草；神呆愚痴者，加胡桃肉、石菖蒲；善忘者，加远志、茯神；兼见五心烦热，躁动失眠，为阴虚火旺、加黄柏、知母、牡丹皮、玄参。"},{"id":"s355","name":"阳气虚衰证","label":"5. 阳气虚衰证","group":"","clinic":"头摇肢颤，筋脉拘挛，畏寒肢冷，四肢麻木，心悸懒言，动则气短，自汗，小便清长或失禁，大便溏，或腰膝酸软，步态拖沓，行走不稳，阳痿，舌质淡，舌苔薄白，脉沉迟无力。","analysis":"久病阴损及阳，阳气虚衰，温煦失职，筋脉不用，虚风内动，则头摇肢颤，筋脉拘挛，表情呆滞，反应迟缓，头晕耳鸣；肾虚不能作强，而见腰膝酸软，步态拖沓，行走不稳；阳气虚衰，则畏寒肢冷，心悸懒言，动则气短，自汗，小便清长或失禁，便溏，阳痿；舌质淡，舌苔薄白，脉沉迟无力，为阳气虚衰之象。","treat":"补肾助阳，温煦筋脉。","formulaRaw":"地黄饮子（《宣明论方》）加减。","formulaName":"地黄饮子加减","fangjie":"附子（制）、肉桂温阳通络；巴戟天、肉从蓉温补肾阳；山萸肉、熟地黄补肾填精；石斛、麦冬、五味子滋阴敛液，并制约温燥之性；石菖蒲、远志、薄荷、茯苓上行头目，化痰利窍，交通心肾；生姜、大枣调和脾胃。若大便稀溏，加干姜、肉豆蔻；心悸，加柏子仁；神疲乏力，加黄芪、黄精；小便自遗，加益智仁、桑螵蛸。面浮身肿，四肢厥冷，筋脉拘急，为肾阳衰微，可用真武汤。"}],"linchuang":["本虚标实，多法并用。颤证的病理性质属本虚标实，多属肾虚肝旺，临床应根据虚实偏重不同施治。如震颤较甚，风邪较盛者，治疗重在平肝息风，治标为先；若年高久病，以虚为主者，以补虚为要，治本为主，使肝肾得养，则肝风自平。因“风为百病之长”，肝为风木之脏，肝风常伴肝阳上亢、肝火上炎，或夹痰、夹瘀等，阻遏脑窍，神机失用，因此，要在滋肾平肝、息风柔筋的基础上，注意随证治之。","息风定颤，搜风通络。颤证属“风病”范畴，各证型均可在辨证的基础上配合息风之法。在息风定颤、搜风通络治疗中，虫类药物具有一定优势，可酌情配伍使用。叶天士谓：“藉虫蚁血中搜逐，以攻通邪结。”","年高病久者，治宜缓图。因老年体衰，脏腑气血失调，病机复杂，往往难以迅速收效，欲过分求速反易招致诸多变证，故治疗只宜缓缓图之，慎用耗伤气血阴阳等攻伐之品，可用填精补髓之品，如能减轻症状，控制发展，则应坚持治疗。"],"yufang":["预防颤证，应注意生活调摄，保持心情舒畅，要劳逸适度，节制房事，饮食宜清淡而富有营养，忌暴饮暴食及嗜食肥甘厚味，戒除烟酒等不良嗜好。避免中毒、中风、颅脑损伤对预防颤证发生有重要意义。","颤证患者平时应注意加强肢体功能锻炼，适当参加力所能及的体育活动，如打太极拳、练八段锦及内养功等。保持心情舒畅，避免忧思郁怒不良情绪刺激。病情较重者，需注意进行语言、进食、行走及各种日常生活能力的训练和指导。卧床不起者，注意帮助患者翻身，经常进行肢体按摩及活动关节，以防发生压疮及关节粘连。"],"attachIds":[]},{"id":"d052","name":"痉证","kind":"main","parent":null,"chapterNo":"第五十五章","chapterName":"痉证","yinbing":[{"t":"p","x":"痉证的病因分为外感和内伤两个方面。外感因感受风、寒、湿、热之邪，壅阻经络，气血不畅，或热盛动风而致痉。内伤因肝肾阴虚，肝阳上亢，阳亢化风，或阴虚血少，筋脉失养，虚风内动而致痉。"},{"t":"b","x":"1. 感受外邪"},{"t":"p","x":"外感风、寒、湿邪，壅阻脉络，以致气血不畅，筋脉失于濡养，拘挛抽搐而成痉；外感温热之邪，或寒邪入里，郁而化热，邪热灼伤津液，筋脉失养，而发为痉证。"},{"t":"b","x":"2. 久病过劳"},{"t":"p","x":"久病不愈，气血耗伤，气虚血行不畅，瘀血内阻，血虚则不能濡养筋脉；久病脏腑功能失调，或脾虚不化水湿，或肝火灼伤津液，或肺失通调，肺气不宣等，皆能产生痰浊，痰浊阻滞经脉，筋脉失养而致痉。先天禀赋不足，操劳过度，久之致肝肾阴虚，阴不制阳，水不涵木，肝阳上亢；或情志不畅，肝郁化火，阳亢化风而致痉。"},{"t":"b","x":"3. 失治误治"},{"t":"p","x":"汗、吐、下法误用或太过，如疮家误汗、表证过汗或误下、体虚之人误用吐法等，导致津液耗散；汗证、血证等病证失治，伤津损液，导致津伤液脱，亡血失精，筋脉失养，均可致痉。"}],"bingji":[{"t":"p","x":"痉证的基本病机是阴阳失调，阳动而阴不濡，筋脉失养。"},{"t":"p","x":"病位在筋脉，由肝所主，与心、脾、胃、肾等脏腑密切相关。"},{"t":"p","x":"明·汪机《医学原理·痓门》曰：“虽有数因不同，其于津血有亏，无以滋荣经脉则一。”"},{"t":"p","x":"病理性质有虚实两方面，虚为脏腑虚损，阴阳、气血、津液不足，实为邪气壅盛。"},{"t":"p","x":"病理因素有风、寒、湿、热、痰、瘀、虚等。"},{"t":"p","x":"此外，痰瘀阻滞，筋脉失养，或气血津液亏虚，阴不制阳，致筋脉失于濡养而发痉。"},{"t":"p","x":"本病日久，病机演变常见虚实夹杂，或因实致虚，或因虚致实。"},{"t":"p","x":"若久治不当，可出现肢体不利、半身不遂、头痛、痴呆等症状，甚则危及生命。"}],"zhenduan":[{"t":"ol","items":["1. 多突然起病，以项背强直、四肢抽搐甚至角弓反张为其证候特征。","2. 部分危重患者可有神昏谵语等意识障碍。","3. 发病前多有外感或内伤等病史。"]}],"jianbie":[{"t":"b","x":"1. 痫证"},{"t":"p","x":"痉证与痫证均存在四肢抽搐的临床表现。"},{"t":"p","x":"痫证是一种发作性的神志异常疾病，以突然仆倒、昏不知人、口吐涎沫、两目上视、四肢抽搐，或口中如作猪羊声为特征，大多发作片刻即自行苏醒，醒后如常人，既往有类似发病史。"},{"t":"p","x":"而痉证的抽搐、痉挛发作多呈持续性，不经治疗常难以恢复。"},{"t":"b","x":"2. 厥证"},{"t":"p","x":"痉证和厥证均可见突然仆倒，昏不识人。"},{"t":"p","x":"厥证是由气机逆乱引起，以突然昏倒、不省人事、四肢逆冷为主要表现的一种疾病，一般无项背强直、四肢抽搐等表现。"},{"t":"b","x":"3. 颤证"},{"t":"p","x":"颤证和痉证均可见肢体颤动。"},{"t":"p","x":"颤证通常起病较慢，以头颈、手足不自主颤动、振摇为主要症状，手足颤抖幅度小，频率较高，多呈持续性，无发热、神昏等症状。"},{"t":"p","x":"痉证肢体抽搐幅度大，多呈持续性，有时伴短阵性间歌，手足屈伸牵引，部分患者可有发热、两目上视、神昏等症状。"},{"t":"b","x":"4. 破伤风"},{"t":"p","x":"破伤风和痉证均可见口噤、肢体痉挛。"},{"t":"p","x":"破伤风古称“金疮痉”，属外科疾病范畴。"},{"t":"p","x":"因金疮破伤，伤口不洁，感受风毒之邪致痉，发痉多始于头面部，肌肉痉挛，口噤，苦笑面容，逐渐延及四肢或全身。"},{"t":"p","x":"病前有金疮破伤、伤口不洁病史，可与痉证鉴别。"}],"bianzheng":[{"t":"b","x":"1. 辨外感与内伤"},{"t":"p","x":"外感致痉多有恶寒、发热、脉浮等表证，即使热邪直中，可无恶寒，但必有发热；内伤发痉则多无恶寒、发热。"},{"t":"b","x":"2. 辨实证与虚证"},{"t":"p","x":"颈项强直，牙关紧闭，角弓反张，四肢抽搐频繁有力而幅度较大者，多属实证；手足蠕动，或抽搐时作时止，神疲倦怠者，多属虚证。"}],"zhize":"急则治其标，缓则治其本，是痉证治疗的基本原则。痉证的治疗常用祛风散寒、清热祛湿、清肝息风、清胃存阴、活血通窍、豁痰息风等法。津伤血少者，应以滋阴养血、舒筋止痉等为主。本虚标实者，应标本兼顾。","syndrome":[{"id":"s356","name":"邪壅经络证","label":"1. 邪壅经络证","group":"","clinic":"头痛，项背强直，恶寒发热，无汗或汗出，肢体酸重，甚至口噤不语，四肢抽搐，苔薄白或白腻，脉浮紧。","analysis":"风寒湿邪，壅滞经络，故头痛，项背强直；外邪侵于肌表，营卫不和，则恶寒发热，无汗或汗出；湿阻经络肌肉，故肢体酸重；邪壅筋脉挛急，故口噤不语，四肢抽搐；苔薄白或白腻，脉浮紧，为风寒湿邪侵袭之象。","treat":"祛风散寒，燥湿和营。","formulaRaw":"羌活胜湿汤（《内外伤辨惑论》）加减。","formulaName":"羌活胜湿汤加减","fangjie":"羌活、独活祛风除湿，通利关节；防风、本祛风胜湿；川芎、蔓荆子祛风止痛；甘草解肌和营，缓急止痉。若寒邪较重，项背强直，肢痛拘挛，苔薄白，脉浮紧，病属“刚痉”，治疗以葛根汤为主；风邪偏盛，项背强直，发热不恶寒，汗出头痛，苔薄白，脉沉细，病属“柔痉”，治疗以栝蒌桂枝汤为主；湿热偏盛，筋脉拘急，胸脘痞闷，身热，渴不欲饮、小便短赤，苔黄腻，脉滑数，用三仁汤加地龙、丝瓜络、威灵仙。"},{"id":"s357","name":"肝经热盛证","label":"2. 肝经热盛证","group":"","clinic":"高热头痛，口噤龄齿，手足躁动，项背强直，四肢抽搐，角弓反张，舌质红绛，苔薄黄或少苔，脉弦细而数。","analysis":"肝经热盛，阳亢于上，故高热头痛；热极引动肝风，故见项背强直，四肢抽搐，角弓反张，口噤龄齿，手足躁动；舌质红绛，苔薄黄，为热盛表现；少苔，脉弦细而数，为肝经热盛伤津之象。","treat":"清肝潜阳，息风镇痉。","formulaRaw":"羚角钩藤汤（《通俗伤寒论》）加减。","formulaName":"羚角钩藤汤加减","fangjie":"羚羊角、钩藤、桑叶、菊花凉肝息风止痉；川贝母、竹茹清热化痰以通络；获神宁神定志；白芍、生地黄、甘草酸甘化阴，补养肝血，缓急止痉。若口苦，苔黄，加龙胆草、栀子、黄芩；口干渴甚，加南沙参、天花粉、麦冬；痉证反复发作，加全蝎、蜈蚣、僵蚕、蝉蜕；神昏痉厥，用安宫牛黄丸、至宝丹或紫雪丹。"},{"id":"s358","name":"阳明热盛证","label":"3. 阳明热盛证","group":"","clinic":"壮热汗出，项背强直，手足挛急，甚则角弓反张，腹满便结，口渴喜冷饮，舌质红，苔黄燥，脉弦数。","analysis":"阳明热盛，故壮热汗出；热盛伤津，筋脉失养，则项背强直，手足挛急，甚则角弓反张；邪热熏蒸阳明气分，宿滞中焦，阳明燥热内结，腑气不通，故腹满便结；热盛津伤，可见口渴喜冷饮；舌质红，苔黄燥，脉弦数，为热盛伤津之象。","treat":"清泄胃热，增液止痉。","formulaRaw":"白虎汤（《伤寒论》）合增液承气汤（《温病条辨》）加减。前方以清泄阳明实热为主，后方重在滋阴增液，泄热通便。","formulaName":"白虎汤合增液承气汤加减","fangjie":"生石膏、知母、玄参、生地黄、麦冬清热养阴生津，濡润筋脉；大黄、芒硝荡涤胃腑积热，软坚润燥；粳米、甘草和胃养阴。若热邪伤津而无腑实证者，用白虎加人参汤；抽搐甚者，加天麻、钩藤、地龙、全蝎、菊花；热甚心烦者，加淡竹叶、栀子、黄芩；若热人营血，斑疹显现者，加水牛角、牡丹皮。"},{"id":"s359","name":"心营热盛证","label":"4. 心营热盛证","group":"","clinic":"高热烦躁，神昏谵语，项背强直，四肢抽搐，甚则角弓反张，舌质红绛，苔黄少津，脉细数。","analysis":"热入心营，扰动神明，故见高热烦躁，神昏谵语；灼伤阴津，筋脉失养，故见项背强直，四肢抽搐，甚则角弓反张；舌质红绛，苔黄少津，脉细数，为热盛伤津之象。","treat":"清心透营，开窍止痉。","formulaRaw":"清营汤（《温病条辨》）加减。","formulaName":"清营汤加减","fangjie":"水牛角（代犀角）清营凉血解毒；玄参、生地黄、麦冬清热凉血，养阴生津；淡竹叶、连翘、银花清热解毒，使营分之邪外达；黄连清心解毒；丹参凉血散瘀。若高热烦躁，加丹皮、栀子、生石膏、知母；四肢抽搐，角弓反张，加全蝎、蜈蚣、僵蚕、蝉衣；神昏谵语，躁动不安，四肢挛急抽搐，角弓反张，酌情选用安宫牛黄丸、至宝丹或紫雪丹。营血热毒重者，用化斑汤、神犀丹加减；肢体抽搐无力，面色苍白，四肢厥冷，气短汗出，舌淡，脉细弱，属亡阳脱证，当急服独参汤、生脉散。"},{"id":"s360","name":"瘀血内阻证","label":"5. 瘀血内阻证","group":"","clinic":"头痛如刺，痛有定处，项背强直，四肢抽搐，舌质紫暗，边有瘀斑、瘀点，脉细涩。","analysis":"瘀血内阻脑窍，不通则痛，故见头痛如刺，痛有定处；瘀血阻滞，筋脉失养，故见项背强直，四肢抽搐；舌质紫暗，边有瘀斑、瘀点，脉细涩，均为瘀血内阻之象。","treat":"活血化瘀，通窍止痉。","formulaRaw":"通窍活血汤（《医林改错》）加减。","formulaName":"通窍活血汤加减","fangjie":"桃仁、红花、川芎、赤芍、黄酒活血通络；麝香开窍通闭，解毒活血；老葱、生姜通阳入络；大枣调和诸药。若筋脉拘急，瘀血较重，加郁金、地龙、当归尾、水蛭、鸡血藤等。"},{"id":"s361","name":"痰浊阻滞证","label":"6. 痰浊阻滞证","group":"","clinic":"头痛昏蒙，神识呆滞，项背强直，四肢抽搐，胸脘满闷，呕吐痰涎，苔白腻，脉滑或","analysis":"痰浊上蒙清窍，见头痛昏蒙，神识呆滞；痰浊阻滞经脉，筋脉失养，故项背强直，四肢抽搐；痰浊困中，运化失健，气机升降失常，见胸脘满闷，呕吐痰涎；苔白腻，脉滑或弦滑，为痰","treat":"豁痰开窍，息风止痉。","formulaRaw":"涤痰汤（《奇效良方》）加减。","formulaName":"涤痰汤加减","fangjie":"半夏、胆南星、陈皮、茯苓、竹茹豁痰化浊；石菖蒲开窍豁痰；枳实破气化痰；人参、大枣、生姜益气健脾，调和脾胃；甘草调和诸药。若言语不利，加白芥子、远志；若痰郁化热，身热，烦躁，舌苔黄腻，脉滑数，加瓜萎、黄芩、天竺黄、竹茹、青磔石；若痰浊上壅，蒙蔽清窍，突然昏厥抽搐，可急用竹沥加姜汁冲服安宫牛黄丸。"},{"id":"s362","name":"阴血亏虚证","label":"7. 阴血亏虚证","group":"","clinic":"项背强直，四肢麻木，抽搦或筋惕肉腘，直视口噤，头目昏眩，自汗，神疲气短，或低热，舌质淡或舌红无苔，脉细数。","analysis":"阴血亏虚，不能濡养筋脉，故项背强直，四肢麻木，抽搦或筋惕肉腘，直视口噤；血虚不能上奉于脑，故头目昏眩；阴血亏虚，气亦耗伤，卫外不固，故神疲气短，自汗；阴虚则内热，见低热；舌质淡或舌红无苔，脉细数，为阴血亏虚之象。","treat":"滋阴养血，息风止痉。","formulaRaw":"四物汤（《仙授理伤续断秘方》）合大定风珠（《温病条辨》）加减。前方以补血和血为主，后方重在滋液育阴，柔肝息风。","formulaName":"四物汤合大定风珠加减","fangjie":"生地黄、熟地黄、白芍、麦冬、阿胶、五味子、当归、麻子仁补血滋阴，柔肝荣筋；生龟甲、生鳖甲、生牡蛎息风止痉；鸡子黄养阴宁心；川芎行气活血；甘草调和诸药。若五心烦热，加白薇、青蒿、黄连、淡竹叶；阴虚多汗，时时欲脱，加生脉饮；气虚自汗，加黄芪、浮小麦；疾病日久，阴血不足，气虚血滞，瘀血阻络，加黄芪、丹参、川芎、赤芍、鸡血藤，或用补阳还五汤加减；虚风内动，肢体拘急挛缩，重用生龟甲、生鳖甲、白芍等养阴润筋之品，加全蝎、天麻、钩藤。"}],"linchuang":["详辨外感内伤、虚实主次。外感发痉多属实证，内伤发痉多为虚证。另外，可从其发作的程度、频度、幅度辨别虚实。外感者，宜祛风、散寒、除湿；若邪热入里，消灼津液，当泄热存阴。内伤者，多属阴伤血少，治疗以滋阴养血为主。此外，肝主筋，主风主动，故治疗时，在辨证用药的基础上，可酌加天麻、钩藤、石决明、代猪石、蜈蚣、全蝎等平肝息风止痉之品。","病证结合，综合治疗。痉证大多发病较急，变化迅速，预后较差。除对症治疗外，要尽快明确诊断，如流行性乙型脑炎、流行性脑脊髓膜炎等，均可出现项背强急、四肢抽搐、角弓反张等表现，应充分发挥中西医结合的优势，积极治疗原发病，防止病情恶化。","观察痉证先兆，早期采取措施预防。如发现双目不瞬、眼球活动不灵活、口角肌肉抽动等先兆表现，即可用全蝎、僵蚕等止痉药物研粉顿服，或配合针刺治疗，防止痉证发作。一旦发生痉证，则应积极救治，以挽救患者的生命。病情较轻者，可根据辨证给予相应的方药口服；病情急重者，则立即选用紫雪丹、安宫牛黄丸，并采取相应的急救措施，以免贻误病情。"],"yufang":["锻炼身体，增强体质，防止外邪侵袭和久病内伤。劳逸结合，放松精神，起居有节，减少痉证诱发因素。","痉证患者多属急重症，病床要平整松软，并设床栏，应有专人护理。急性发作时注意保护舌体，清除义齿及呼吸道异物，以防窒息。对频繁肢体抽动者，避免强行按压和捆绑，以防骨折。因高热发痉者，要及时降温，保持水及电解质平衡，以利康复。"],"attachIds":[]},{"id":"d053","name":"腰痛","kind":"main","parent":null,"chapterNo":"第五十六章","chapterName":"腰痛","yinbing":[{"t":"p","x":"腰痛的发生主要因外邪侵袭引起经脉受阻，气血不畅，或年老体虚，肾气亏虚，腰府失养。跌仆闪挫，气血阻滞，瘀血留着，痹阻经脉，气血不通，亦可发为腰痛。"},{"t":"b","x":"1. 外邪侵袭"},{"t":"p","x":"多由居处潮湿，或劳作汗出当风，衣着单薄，或冒雨着凉，或暑夏贪凉，风、寒、湿、热之邪乘虚侵人，导致经脉受阻，气血运行不畅而发腰痛。"},{"t":"p","x":"《素问·六元正纪大论》云：“感于寒，则病人关节禁固，腰雕痛，寒湿推于气交而为疾也。”"},{"t":"b","x":"2. 年老体虚"},{"t":"p","x":"先天禀赋不足，或久病体虚，或年老体衰，或房事不节，以致肾之精气亏虚，不能濡养经脉而致腰痛。"},{"t":"b","x":"3. 跌仆闪挫"},{"t":"p","x":"举重抬异，屏气闪挫，暴力扭转，坠落跌打，或体位不正，用力不当，导致腰部经络气血运行不畅，气血阻滞不通，瘀血留着而发生疼痛。"},{"t":"p","x":"《景岳全书·腰痛》云：“跌仆伤而腰痛者，此伤在筋骨而血脉凝滞也。”"}],"bingji":[{"t":"p","x":"腰痛的基本病机是经脉痹阻，腰府失养。"},{"t":"p","x":"病变部位在腰，与肾及足太阳、足少阴、任脉、督脉、带脉等经脉密切相关。"},{"t":"p","x":"病理性质虚实不同，但以虚为多，或见本虚标实。"},{"t":"p","x":"但腰痛以肾虚为主，因肾藏精，主封藏，若肾之精气亏虚，最易导致腰痛。"},{"t":"p","x":"腰痛实证延久不愈，邪留伤肾可由实转虚；虚证腰痛，常因肾虚易感外邪而加重，多见本虚标实错杂之候。"},{"t":"p","x":"寒湿久郁，可以化热；寒湿、湿热邪痹日久，络脉不利，多致气滞血瘀。"}],"zhenduan":[{"t":"ol","items":["1. 急性腰痛，病程较短，轻微活动即可引起一侧或两侧腰部疼痛加重，脊柱两侧常有明显的压痛点。","2. 慢性腰痛，病程较长，缠绵难愈，遇劳则剧，按之则舒。常因体位不当、劳累过度、天气变化等因素诱发或加重。","3. 常有居处潮湿阴冷、涉水冒雨、跌仆闪挫、劳累过度等相关病史。"]}],"jianbie":[{"t":"b","x":"1. 背痛、尻痛、胯痛"},{"t":"p","x":"腰痛是指腰脊或脊旁部位疼痛，背痛为背膂以上部位疼痛，尻痛是尻骶部位的疼痛，胯痛指尻尾以下及两侧胯部的疼痛。"},{"t":"p","x":"疼痛的部位不同，应予区别。"},{"t":"b","x":"2. 肾痹"},{"t":"p","x":"肾痹是指腰背强直弯曲、不能屈伸、行动困难而言，多由骨痹日久发展而成。"}],"bianzheng":[{"t":"b","x":"1. 辨虚实"},{"t":"p","x":"外感腰痛，多起病较急，腰痛明显，常伴表证，多属实；内伤者，多起病隐袭，腰部酸痛，病程缠绵，常伴有脏腑症状，多属虚；跌仆闪挫所致者，起病急，疼痛部位固定，多属瘀血为患，亦以实证为主。"},{"t":"b","x":"2. 辨病性"},{"t":"p","x":"腰部冷痛，得热则舒，足寒肢冷，为寒；腰部疼痛重着，难以转侧，身体困重，为湿；腰部热痛，身热汗出，小便热赤，为热；腰痛如刺，痛处拒按，多为闪挫或瘀血；腰痛酸软无力，劳则为甚，多属肾虚。"}],"zhize":"腰痛的治疗当分清标本缓急。邪实者，当祛邪通络，并根据病理因素的不同，予以不同治法，寒湿宜温化，湿热宜清利，血瘀当活血。正虚者，当补肾益精，或温阳益气，或滋阴养血。本虚标实，虚实夹杂者，应分清主次，兼顾用药。实证经治邪去大半后，酌予补肾培本，以求巩固。","syndrome":[{"id":"s363","name":"寒湿腰痛","label":"1. 寒湿腰痛","group":"","clinic":"腰部冷痛重着，转侧不利，静卧病痛不减，寒冷或阴雨天加重，舌质淡，苔白腻，脉沉而迟缓。","analysis":"寒湿邪气，侵袭腰部，痹阻经络，气血不畅，复因寒性收引，湿性凝滞，故腰部冷痛重着，转侧不利；湿为阴邪，得阳始化，卧则伤气，则湿邪更易停滞，故卧而痛不减；遇阴雨冷天，则寒湿更甚，故疼痛加剧；舌质淡，舌苔白腻，脉沉迟缓，均属寒湿停聚之象。","treat":"散寒行湿，温经通络。","formulaRaw":"甘姜苓术汤（《金匮要略》）加减。","formulaName":"甘姜苓术汤加减","fangjie":"干姜、甘草散寒暖中；茯苓、白术健脾胜湿。若寒邪偏盛，可加附子（制）、川乌、细辛等；湿邪偏盛，痛引下肢，酸重无力，加苍术、厚朴、薏苡仁、防已、五加皮、蚕砂等；风湿相合，腰痛引及肩背、腿膝，加防风、独活、秦艽等。"},{"id":"s364","name":"湿热腰痛","label":"2. 湿热腰痛","group":"","clinic":"腰部疼痛，重着而热，暑湿阴雨天气加重，活动后或可减轻，小便短赤，舌质红，苔黄腻，脉濡数或弦数。","analysis":"湿热之邪，壅滞腰部，筋脉弛缓，经气不通，故腰痛重着而热；暑湿阴雨天气，湿热得增，故疼痛加剧；活动后气机得以舒展，故疼痛或可减轻；湿热下注，郁蒸膀胱，故小便短赤；舌质红，苔黄腻，脉濡数或弦数，均属湿热内郁之象。","treat":"清热利湿，舒筋止痛。","formulaRaw":"四妙丸（《成方便读》）加减。","formulaName":"四妙丸加减","fangjie":"苍术、黄柏清利下焦湿热；薏苡仁健脾渗湿；牛膝益肾利腰，通利经脉，引药下行。若小便热赤，量少，加泽泻、白茅根、车前草等；湿热蕴久，耗伤阴津，口咽干燥，手足心热，舌质红，可加生地黄、知母、女贞子、墨旱莲等。"},{"id":"s365","name":"瘀血腰痛","label":"3. 瘀血腰痛","group":"","clinic":"腰痛如刺，痛有定处，痛处拒按，日轻夜重，轻者俯仰不便，重者不能转侧，舌质暗紫，或有瘀斑，脉涩。部分患者有跌仆闪挫病史。","analysis":"瘀血阻滞经脉，气血运行不畅，故腰痛如刺，痛有定处，痛处拒按；夜晚阴气较盛，血行迟缓，瘀阻加甚，故疼痛夜重；舌质紫暗，或有瘀斑，脉涩，均属瘀血阻滞之象。","treat":"活血化瘀，通络止痛。","formulaRaw":"身痛逐瘀汤（《医林改错》）加减。","formulaName":"身痛逐瘀汤加减","fangjie":"当归、川芎、桃仁、红花活血祛瘀通络；没药、五灵脂、地龙破瘀通络；秦艽、羌活祛风除湿；香附行气活血；牛膝引药下行，活血祛瘀，补益肝肾；甘草调和诸药。若腰痛日久，肾虚者，加杜仲、续断、狗脊、桑寄生等；腰痛连胁，可加柴胡、郁金等；有跌仆闪挫病史，加乳香、青皮等。"},{"id":"s366","name":"肾阴虚","label":"(1) 肾阴虚","group":"肾虚腰痛","clinic":"腰部隐隐作痛，酸软无力，心烦少寐，口燥咽干，面色潮红，手足心热，舌红少苔，脉弦细数。","analysis":"肾阴不足，腰脊失于濡养，故腰部隐隐作痛，酸软无力；肾阴不足，虚火上炎，则心烦失眠，面色潮红，手足心热；虚热耗津，故口燥咽干；舌红少苔，脉弦细数，均属阴虚内热之象。","treat":"滋补肾阴，濡养筋脉。","formulaRaw":"左归丸（《景岳全书》）加减。","formulaName":"左归丸加减","fangjie":"熟地黄、山萸肉、山药、枸杞子、龟甲胶滋阴补肾，填精益髓；鹿角胶、牛膝、菟丝子温肾壮腰，阳中求阴。若肾阴不足，相火偏亢，用知柏地黄丸或大补阴丸加减；虚劳腰痛，日久不愈，阴阳俱虚，阴虚内热者，用杜仲丸（《医学入门》）加减。"},{"id":"s367","name":"肾阳虚","label":"(2) 肾阳虚","group":"肾虚腰痛","clinic":"腰部隐隐作痛，酸软无力，遇劳痛甚，局部发凉，喜温喜按，面色㿠白，肢冷畏寒，舌质淡，苔薄白，脉沉细无力。","analysis":"肾阳不足，腰府失于温煦，故腰部隐隐作痛，酸软无力；劳则气耗，故遇劳更甚；肾阳不足，腰府失于温煦，则局部发凉，喜温喜按；阳虚不能温养经脉，阳气不达四末，则肢冷畏寒，面色㿠白；舌质淡，脉沉细无力，均属阳气虚寒之候。","treat":"补肾壮阳，温煦经脉。","formulaRaw":"右归丸（《景岳全书》）加减。","formulaName":"右归丸加减","fangjie":"附子（制）、肉桂、鹿角胶、杜仲、菟丝子温补肾阳，强壮腰脊；熟地黄、山茱萸、山药、枸杞子、当归补肾滋阴养血，阴中求阳。若脾气亏虚，甚或脏器下垂者，加黄芪、党参、白术、升麻等。无明显阴阳偏盛者，用青娥丸（《太平惠民和剂局方》）加减；房劳过度而致肾虚腰痛者，用血肉有情之品调理，如河车大造丸等。"}],"linchuang":["重视原发疾病的针对性治疗。腰痛的病因较多，外感、内伤、跌仆闪挫均常见。腰痛又与多种疾病相关。因此，临床既要辨证治疗，又应针对原发疾病，采用不同的治疗方法。如泌尿系统感染、结石可引起腰痛，肝胆系统疾病、骨伤科疾病、妇科疾病等也引起腰痛，治疗应首先考虑原发疾病的诊断与鉴别诊断，切忌腰痛治腰，贻误病情。","详辨腰痛虚实标本。辨虚实对于腰痛的治疗极为重要。感受外邪属实，宜祛邪通络，根据寒湿、湿热的不同，分别予以温散或清利；外伤腰痛属实，宜活血祛瘀，通络止痛；内伤致病多属虚，宜补肾固本。值得注意的是，治疗腰痛虽以补肾为主，但在外感较著时，应急治其标，先祛邪，后治本。","善用活血化瘀通络药。活血化瘀药可用于腰痛的不同证型，但疾病的不同阶段，所选药物和剂量应该不同。初发或者急性期，常用小剂量的当归、川芎等养血和血，温经通脉；病情相对缓解期，可适当加大活血化瘀药的剂量；腰痛病久，屡次复发者，活血化瘀可配伍虫类药搜风通络祛邪，如桃仁、红花、三七、水蛭、土鳖虫、全蝎、蜈蚣、制大黄等。","临证强调综合治疗。根据病情可适当选用牵拉复位、推拿、针灸、拔火罐、膏药外敷、理疗、穴位注射、中药离子导入等外治方法，有助于疾病的治疗与康复。寒湿腰痛、肾虚腰痛、瘀血腰痛在内服药物的基础上，可配合熨法治疗，如将肉桂、吴茱萸、葱白、花椒四味捣匀，炒热，以绢帕裹包熨痛处，冷则再炒再熨。"],"yufang":["预防腰痛，在日常生活中要保持正确的坐、卧、行体位，劳逸适度，不可强力负重，避免腰部跌仆闪挫，减少腰痛的发生。注意居处环境，避免坐卧湿地。暑季湿热蕴蒸时，应避免夜宿室外，贪冷喜凉。涉水冒雨或运动汗出后即应换衣擦身，免受风寒湿邪侵袭。","急性腰痛应及时治疗，注意休息调养。慢性腰痛除药物治疗外，需注意腰部保暖，或加用腰托固护，避免腰部损伤。避免劳欲太过，防止感受外邪。经常活动腰部，如进行腰部自我按摩、打太极拳等活动，有助于腰痛的康复。"],"attachIds":[]}],"attaches":[{"id":"a001","name":"多寐","kind":"attach","parent":"d012","parentName":"不寐","chapterNo":"第十五章","raw":[{"t":"p","x":"多寐是由于阳气困滞不振或阳虚气弱，以不分昼夜，时时欲睡，呼之即醒，醒后复睡为主要表现的病证。多寐的基本病机是湿（浊）、痰、瘀困滞阳气，心阳不振，或阳虚气弱，心神失荣。病变部位主要在心、脾，与肾关系密切，病理性质多属本虚标实。"},{"t":"h","lv":5,"x":"1. 湿盛困脾"},{"t":"p","x":"临床表现：昏昏嗜睡，头蒙如裹，肢体沉重，偶伴浮肿，胸脘痞满，纳少，泛恶，舌淡苔腻，脉濡。"},{"t":"p","x":"证候分析：昏昏嗜睡，头蒙如裹，为湿邪困遏中焦，脾失健运，清阳不升，浊阴蒙蔽清窍所致；肢体沉重，偶伴浮肿，系湿邪重浊黏滞阻碍气机、水运所致；胸脘痞满，纳少，皆因湿阻脾胃，纳运功能失常；泛恶，乃湿浊困脾，胃气上逆表现；舌淡苔腻，脉濡，均为湿邪困脾之象。"},{"t":"p","x":"治法：燥湿健脾，醒神开窍。"},{"t":"p","x":"代表方：平胃散（《简要济众方》）加减。"},{"t":"p","x":"苍术除湿运脾；厚朴、生姜行气宽中，化湿除满；陈皮理气燥湿；甘草、大枣调和诸药。"},{"t":"p","x":"若湿邪久蕴而化热者，加黄芩、通草、薏苡仁。"},{"t":"h","lv":5,"x":"2. 瘀血阻滞"},{"t":"p","x":"临床表现：神倦嗜睡，头痛头晕，病程较久，或有外伤史，舌质紫暗或有瘀斑，苔薄，脉涩。"},{"t":"p","x":"证候分析：神倦嗜睡，头痛头晕，为瘀血阻滞，阳气受遏，气血运行不畅所致；病程较久，久病入络，外伤亦易产生瘀血；舌质紫暗或有瘀斑，脉涩，均为瘀血内阻之象。"},{"t":"p","x":"治法：活血通络。"},{"t":"p","x":"代表方：通窍活血汤（《医林改错》）加减。"},{"t":"p","x":"麝香开窍醒神；赤芍清热活血；川芎、桃仁、红花养血活血行血，祛瘀生新；黄酒、老葱、生姜辛温通阳，行散药力；大枣补血养血，调和诸药。"},{"t":"p","x":"若兼气滞者，加青皮、陈皮、枳壳、香附；有热象者，加黄芩、山栀；阴虚者，加生地黄、丹皮；气虚者，加黄芪、党参；阳虚者，加肉桂、附子（制）；有痰浊者，加半夏、陈皮、白芥子。"},{"t":"h","lv":5,"x":"3. 脾气虚弱"},{"t":"p","x":"临床表现：嗜睡多卧，倦怠乏力，食后尤甚，伴纳少便溏，面色萎黄，舌淡胖，苔薄白，脉虚弱。"},{"t":"p","x":"证候分析：嗜睡多卧，倦怠乏力，因脾气虚弱，气血乏源，清阳不升；食后尤甚，系脾运失健所致；纳少便溏，为脾虚湿困表现；面色萎黄，为脾之本色，因气血不能上荣所致；舌淡胖，苔薄白，脉虚弱，均为脾气不足之象。"},{"t":"p","x":"治法：健脾益气。"},{"t":"p","x":"代表方：香砂六君子汤（《古今名医方论》）加减。"},{"t":"p","x":"人参、白术、茯苓、甘草益气健脾；半夏、陈皮、砂仁、木香理气化痰。"},{"t":"p","x":"若脾虚下陷者，加黄芪、升麻、柴胡，或合补中益气汤，益气升阳。"},{"t":"h","lv":5,"x":"4. 阳气虚衰"},{"t":"p","x":"临床表现：心神昏浊，倦怠嗜卧，精神疲乏，懒言，畏寒肢冷，面色㿠白，健忘，舌淡苔薄，脉沉细无力。"},{"t":"p","x":"证候分析：心神昏浊，倦怠嗜卧，精神疲乏，健忘，为阳气虚衰，清窍失于温养所致；懒言，畏寒肢冷，均因阳气虚弱，失于温煦；面色㿠白，因阳气不足，气血不能上荣头面；舌淡苔薄，脉沉细无力，均为阳气虚弱之象。"},{"t":"p","x":"治法：益气温阳。"},{"t":"p","x":"代表方：附子理中丸(《太平惠民和剂局方》）加减。"},{"t":"p","x":"附子（制）、干姜辛热温阳，附子（制）重在温肾，干姜重在温脾；人参益气健脾，振奋元气；白术健脾燥湿；甘草调和诸药。"},{"t":"p","x":"若气散不收，多汗，加五味子。"}],"syndrome":[{"id":"s073","name":"湿盛困脾","label":"1. 湿盛困脾","group":"","clinic":"昏昏嗜睡，头蒙如裹，肢体沉重，偶伴浮肿，胸脘痞满，纳少，泛恶，舌淡苔腻，脉濡。","analysis":"昏昏嗜睡，头蒙如裹，为湿邪困遏中焦，脾失健运，清阳不升，浊阴蒙蔽清窍所致；肢体沉重，偶伴浮肿，系湿邪重浊黏滞阻碍气机、水运所致；胸脘痞满，纳少，皆因湿阻脾胃，纳运功能失常；泛恶，乃湿浊困脾，胃气上逆表现；舌淡苔腻，脉濡，均为湿邪困脾之象。","treat":"燥湿健脾，醒神开窍。","formulaRaw":"平胃散（《简要济众方》）加减。","formulaName":"平胃散加减","fangjie":"苍术除湿运脾；厚朴、生姜行气宽中，化湿除满；陈皮理气燥湿；甘草、大枣调和诸药。\n若湿邪久蕴而化热者，加黄芩、通草、薏苡仁。"},{"id":"s074","name":"瘀血阻滞","label":"2. 瘀血阻滞","group":"","clinic":"神倦嗜睡，头痛头晕，病程较久，或有外伤史，舌质紫暗或有瘀斑，苔薄，脉涩。","analysis":"神倦嗜睡，头痛头晕，为瘀血阻滞，阳气受遏，气血运行不畅所致；病程较久，久病入络，外伤亦易产生瘀血；舌质紫暗或有瘀斑，脉涩，均为瘀血内阻之象。","treat":"活血通络。","formulaRaw":"通窍活血汤（《医林改错》）加减。","formulaName":"通窍活血汤加减","fangjie":"麝香开窍醒神；赤芍清热活血；川芎、桃仁、红花养血活血行血，祛瘀生新；黄酒、老葱、生姜辛温通阳，行散药力；大枣补血养血，调和诸药。\n若兼气滞者，加青皮、陈皮、枳壳、香附；有热象者，加黄芩、山栀；阴虚者，加生地黄、丹皮；气虚者，加黄芪、党参；阳虚者，加肉桂、附子（制）；有痰浊者，加半夏、陈皮、白芥子。"},{"id":"s075","name":"脾气虚弱","label":"3. 脾气虚弱","group":"","clinic":"嗜睡多卧，倦怠乏力，食后尤甚，伴纳少便溏，面色萎黄，舌淡胖，苔薄白，脉虚弱。","analysis":"嗜睡多卧，倦怠乏力，因脾气虚弱，气血乏源，清阳不升；食后尤甚，系脾运失健所致；纳少便溏，为脾虚湿困表现；面色萎黄，为脾之本色，因气血不能上荣所致；舌淡胖，苔薄白，脉虚弱，均为脾气不足之象。","treat":"健脾益气。","formulaRaw":"香砂六君子汤（《古今名医方论》）加减。","formulaName":"香砂六君子汤加减","fangjie":"人参、白术、茯苓、甘草益气健脾；半夏、陈皮、砂仁、木香理气化痰。\n若脾虚下陷者，加黄芪、升麻、柴胡，或合补中益气汤，益气升阳。"},{"id":"s076","name":"阳气虚衰","label":"4. 阳气虚衰","group":"","clinic":"心神昏浊，倦怠嗜卧，精神疲乏，懒言，畏寒肢冷，面色㿠白，健忘，舌淡苔薄，脉沉细无力。","analysis":"心神昏浊，倦怠嗜卧，精神疲乏，健忘，为阳气虚衰，清窍失于温养所致；懒言，畏寒肢冷，均因阳气虚弱，失于温煦；面色㿠白，因阳气不足，气血不能上荣头面；舌淡苔薄，脉沉细无力，均为阳气虚弱之象。","treat":"益气温阳。","formulaRaw":"附子理中丸(《太平惠民和剂局方》）加减。","formulaName":"附子理中丸加减","fangjie":"附子（制）、干姜辛热温阳，附子（制）重在温肾，干姜重在温脾；人参益气健脾，振奋元气；白术健脾燥湿；甘草调和诸药。\n若气散不收，多汗，加五味子。"}]},{"id":"a002","name":"吐酸","kind":"attach","parent":"d019","parentName":"胃痛","chapterNo":"第二十二章","raw":[{"t":"p","x":"吐酸，又称泛酸，是指以胃中酸水上泛为主症的疾病。若随即咽下称为吞酸，若随即吐出称为吐酸。本病的基本病机为肝胃失和，有寒热之分：属热者多由肝郁化热，邪热犯胃，胃气上逆所致；因寒者多因脾胃虚弱，肝气犯胃而成。"},{"t":"h","lv":5,"x":"1. 热证"},{"t":"p","x":"临床表现：吞酸时作，暖腐气秽，胃脘闷胀，两胁胀满，时有呛咳，心烦易怒，口干口苦，咽干，舌质红，苔黄，脉弦数。"},{"t":"p","x":"证候分析：肝郁化火，横逆犯胃，胃失和降，故吞酸时作，暖腐气秽，胃脘闷胀；肝郁气滞，故两胁胀满；肝胃郁热，胃气上逆，故口干口苦，咽干；舌质红，苔黄，脉弦数，均为肝胃郁热的表现。"},{"t":"p","x":"治法：清泻肝火，和胃降逆。"},{"t":"p","x":"代表方：左金丸（《丹溪心法》）加减。"},{"t":"p","x":"黄连、吴茱萸、黄芩、栀子清肝泄热；乌贼骨、煅瓦楞子制酸。"},{"t":"p","x":"若呛咳、痰多者，加瓜萎、射干、枇杷叶降肺利气。"},{"t":"h","lv":5,"x":"2. 寒证"},{"t":"p","x":"临床表现：吐酸时作，暖气酸腐，胸脘胀闷，喜唾涎沫，饮食喜热，四肢不温，大便溏泄，舌质淡，苔白，脉沉迟。"},{"t":"p","x":"证候分析：脾胃虚寒，胃失和降，故吐酸时作，暖气酸腐，胸脘胀闷；脾胃阳虚，不能温化水谷，故喜唾涎沫，饮食喜热；水湿内盛，流注肠中，故大便溏薄；脾阳不足，四肢失养，故四肢不温；舌质淡，苔薄白，脉沉迟无力，均为脾胃虚寒的表现。"},{"t":"p","x":"治法：温中散寒，宽胸下气。"},{"t":"p","x":"代表方：香砂六君子汤（《古今名医方论》)加减。"},{"t":"p","x":"党参、白术、茯苓健脾益气；木香、砂仁行气和胃；半夏、陈皮和胃降逆；干姜、吴茱萸温中散寒；甘草调和诸药。"},{"t":"p","x":"若脾虚，吐涎多者，加益智仁、炒苍术、乌药。"}],"syndrome":[{"id":"s127","name":"热证","label":"1. 热证","group":"","clinic":"吞酸时作，暖腐气秽，胃脘闷胀，两胁胀满，时有呛咳，心烦易怒，口干口苦，咽干，舌质红，苔黄，脉弦数。","analysis":"肝郁化火，横逆犯胃，胃失和降，故吞酸时作，暖腐气秽，胃脘闷胀；肝郁气滞，故两胁胀满；肝胃郁热，胃气上逆，故口干口苦，咽干；舌质红，苔黄，脉弦数，均为肝胃郁热的表现。","treat":"清泻肝火，和胃降逆。","formulaRaw":"左金丸（《丹溪心法》）加减。","formulaName":"左金丸加减","fangjie":"黄连、吴茱萸、黄芩、栀子清肝泄热；乌贼骨、煅瓦楞子制酸。\n若呛咳、痰多者，加瓜萎、射干、枇杷叶降肺利气。"},{"id":"s128","name":"寒证","label":"2. 寒证","group":"","clinic":"吐酸时作，暖气酸腐，胸脘胀闷，喜唾涎沫，饮食喜热，四肢不温，大便溏泄，舌质淡，苔白，脉沉迟。","analysis":"脾胃虚寒，胃失和降，故吐酸时作，暖气酸腐，胸脘胀闷；脾胃阳虚，不能温化水谷，故喜唾涎沫，饮食喜热；水湿内盛，流注肠中，故大便溏薄；脾阳不足，四肢失养，故四肢不温；舌质淡，苔薄白，脉沉迟无力，均为脾胃虚寒的表现。","treat":"温中散寒，宽胸下气。","formulaRaw":"香砂六君子汤（《古今名医方论》)加减。","formulaName":"香砂六君子汤加减","fangjie":"党参、白术、茯苓健脾益气；木香、砂仁行气和胃；半夏、陈皮和胃降逆；干姜、吴茱萸温中散寒；甘草调和诸药。\n若脾虚，吐涎多者，加益智仁、炒苍术、乌药。"}]},{"id":"a003","name":"嘈杂","kind":"attach","parent":"d019","parentName":"胃痛","chapterNo":"第二十二章","raw":[{"t":"p","x":"嘈杂是以胃中空虚，似饥非饥，似辣非辣，似痛非痛，莫可名状，时作时止为主症的疾病。嘈杂有胃热、胃虚之不同，又与胃痛、胃痞等多种病证兼见，故可参照胃痛、胃痞等进行辨证论治。"},{"t":"h","lv":5,"x":"1. 胃热"},{"t":"p","x":"临床表现：嘈杂而兼恶心吞酸，口渴喜冷，口臭心烦，脘闷痰多，多食易饥，或似饥非饥，舌质红，苔黄干，脉滑数。"},{"t":"p","x":"证候分析：痰热阻胃，气机壅滞，故胃脘嘈杂，恶心吞酸，口渴喜冷；胃火上炎，故口臭心烦；胃中有热，故多食易饥，或似饥非饥；舌质红，苔黄干，脉滑数，均为胃热炽盛的表现。"},{"t":"p","x":"治法：清热化痰，降逆和中。"},{"t":"p","x":"代表方：黄连温胆汤（《六因条辨》)加减。"},{"t":"p","x":"半夏燥湿化痰降逆，陈皮理气燥湿，竹茹清热化痰降逆，枳实行气导滞，生姜和胃降逆，甘草调和诸药，黄连、栀子清泄胃热。"},{"t":"p","x":"烧心、反酸明显者，加煅瓦楞子、乌贼骨、浙贝母、刺猬皮制酸；口渴甚者，加麦冬、玉竹养阴生津；口中异味重者，加蒲公英、公丁香、佩兰等清热化湿。"},{"t":"h","lv":5,"x":"2. 胃虚"},{"t":"p","x":"临床表现：嘈杂时作时止，口淡无味，食后脘胀，体倦乏力，不思饮食，舌质淡，苔薄白，脉虚弱。"},{"t":"p","x":"证候分析：脾胃气虚，气机不畅，故胃脘嘈杂，时作时止；脾气虚弱，四肢失养，故体倦乏力；脾失健运，胃失受纳，故口淡无味，不思饮食；舌质淡，苔薄白，脉虚弱，均为脾胃虚弱的表现。"},{"t":"p","x":"治法：益气健脾，调畅气机。"},{"t":"p","x":"代表方：四君子汤（《太平惠民和剂局方》)加减。"},{"t":"p","x":"党参益气补中，白术健脾燥湿，茯苓渗湿健脾，甘草甘缓和中，山药补脾养胃，白蔻仁温中行气。"},{"t":"p","x":"若腹胀明显者，加炒枳壳、木香、砂仁行气消胀；呕吐、暖气者，加半夏、生姜、石菖蒲和胃降逆，宣通气机。"},{"t":"p","x":"若胃阴不足，饥不欲食，大便干结，舌红脉细者，用益胃汤养阴益胃。"},{"t":"h","lv":5,"x":"3. 血虚"},{"t":"p","x":"临床表现：嘈杂时作，面白唇淡，头晕心悸，失眠多梦，舌质淡，苔薄白，脉细弱。"},{"t":"p","x":"证候分析：气血两虚，胃失所养，故胃脘嘈杂，时作时止；血虚，头面失于濡养，故面白唇淡，头晕；血虚心神失养，故心悸，失眠多梦；舌质淡，苔薄白，脉细弱，均为血虚的表现。"},{"t":"p","x":"治法：益气养血，健脾和胃。"},{"t":"p","x":"代表方：归脾汤（《济生方》）加减。"},{"t":"p","x":"黄芪、党参补气健脾；当归、龙眼肉养血和营；木香健脾理气；茯神、远志、酸枣仁养心安神；生姜、大枣、甘草和胃健脾，以资化源。"}],"syndrome":[{"id":"s129","name":"胃热","label":"1. 胃热","group":"","clinic":"嘈杂而兼恶心吞酸，口渴喜冷，口臭心烦，脘闷痰多，多食易饥，或似饥非饥，舌质红，苔黄干，脉滑数。","analysis":"痰热阻胃，气机壅滞，故胃脘嘈杂，恶心吞酸，口渴喜冷；胃火上炎，故口臭心烦；胃中有热，故多食易饥，或似饥非饥；舌质红，苔黄干，脉滑数，均为胃热炽盛的表现。","treat":"清热化痰，降逆和中。","formulaRaw":"黄连温胆汤（《六因条辨》)加减。","formulaName":"黄连温胆汤加减","fangjie":"半夏燥湿化痰降逆，陈皮理气燥湿，竹茹清热化痰降逆，枳实行气导滞，生姜和胃降逆，甘草调和诸药，黄连、栀子清泄胃热。\n烧心、反酸明显者，加煅瓦楞子、乌贼骨、浙贝母、刺猬皮制酸；口渴甚者，加麦冬、玉竹养阴生津；口中异味重者，加蒲公英、公丁香、佩兰等清热化湿。"},{"id":"s130","name":"胃虚","label":"2. 胃虚","group":"","clinic":"嘈杂时作时止，口淡无味，食后脘胀，体倦乏力，不思饮食，舌质淡，苔薄白，脉虚弱。","analysis":"脾胃气虚，气机不畅，故胃脘嘈杂，时作时止；脾气虚弱，四肢失养，故体倦乏力；脾失健运，胃失受纳，故口淡无味，不思饮食；舌质淡，苔薄白，脉虚弱，均为脾胃虚弱的表现。","treat":"益气健脾，调畅气机。","formulaRaw":"四君子汤（《太平惠民和剂局方》)加减。","formulaName":"四君子汤加减","fangjie":"党参益气补中，白术健脾燥湿，茯苓渗湿健脾，甘草甘缓和中，山药补脾养胃，白蔻仁温中行气。\n若腹胀明显者，加炒枳壳、木香、砂仁行气消胀；呕吐、暖气者，加半夏、生姜、石菖蒲和胃降逆，宣通气机。\n若胃阴不足，饥不欲食，大便干结，舌红脉细者，用益胃汤养阴益胃。"},{"id":"s131","name":"血虚","label":"3. 血虚","group":"","clinic":"嘈杂时作，面白唇淡，头晕心悸，失眠多梦，舌质淡，苔薄白，脉细弱。","analysis":"气血两虚，胃失所养，故胃脘嘈杂，时作时止；血虚，头面失于濡养，故面白唇淡，头晕；血虚心神失养，故心悸，失眠多梦；舌质淡，苔薄白，脉细弱，均为血虚的表现。","treat":"益气养血，健脾和胃。","formulaRaw":"归脾汤（《济生方》）加减。","formulaName":"归脾汤加减","fangjie":"黄芪、党参补气健脾；当归、龙眼肉养血和营；木香健脾理气；茯神、远志、酸枣仁养心安神；生姜、大枣、甘草和胃健脾，以资化源。"}]},{"id":"a004","name":"反胃","kind":"attach","parent":"d023","parentName":"噎膈","chapterNo":"第二十六章","raw":[{"t":"p","x":"反胃是由多种原因导致胃气失和，气逆于上，以脘腹痞胀、宿食不化、朝食暮吐、暮食朝吐为主要临床表现的病证。病因多由饮食不节，饥饱无常，暴饮暴食，致饮食停滞，或嗜食生冷，损伤脾阳，或忧愁思虑，伤及脾胃，中焦阳气不振，寒从内生，日久脾胃衰败，胃中无火，不能腐熟水谷，饮食入胃，停留不化，逆而向上，尽吐而出。"},{"t":"h","lv":5,"x":"脾胃虚寒证"},{"t":"p","x":"临床表现：食后脘腹胀满，朝食暮吐，暮食朝吐，宿谷不化，吐后则舒，神疲乏力，面色清白，手足不温，大便溏少，舌质淡，苔白腻，脉细缓无力。"},{"t":"p","x":"证候分析：脾胃阳虚，不能受纳、腐熟水谷，故食后脘腹胀满，朝食暮吐，暮食朝吐，宿谷不化；宿食停滞，阻碍胃中气机，故吐后则舒；水谷不化，生化乏源，故神疲乏力；机体阳虚，失于温煦，故面色清白，手足不温；脾虚失于运化，故大便溏少；舌质淡，苔白腻，脉细缓无力，为脾胃虚寒之象。"},{"t":"p","x":"治法：温中健脾，和胃降逆。"},{"t":"p","x":"代表方：丁香透膈汤（《医门法律》）加减。"},{"t":"p","x":"人参、白术、炙甘草健脾益气；丁香、半夏、木香、香附温中和胃降逆；砂仁、白豆蔻、神曲、麦芽醒脾化食。"},{"t":"p","x":"若胃虚气逆，呕吐甚者，加旋覆花、代赭石；吐甚而气阴耗伤者，去丁香、砂仁、白豆蔻，加沙参、麦冬；阳虚停饮，胸膈不利者，加桂枝、附子（制）、生姜；脘腹满闷，肢体困重者，加苍术、厚朴、茯苓、泽泻；畏寒肢冷，腰膝酸软重者，加肉桂、补骨脂。"}],"syndrome":[{"id":"s153","name":"脾胃虚寒证","label":"脾胃虚寒证","group":"","clinic":"食后脘腹胀满，朝食暮吐，暮食朝吐，宿谷不化，吐后则舒，神疲乏力，面色清白，手足不温，大便溏少，舌质淡，苔白腻，脉细缓无力。","analysis":"脾胃阳虚，不能受纳、腐熟水谷，故食后脘腹胀满，朝食暮吐，暮食朝吐，宿谷不化；宿食停滞，阻碍胃中气机，故吐后则舒；水谷不化，生化乏源，故神疲乏力；机体阳虚，失于温煦，故面色清白，手足不温；脾虚失于运化，故大便溏少；舌质淡，苔白腻，脉细缓无力，为脾胃虚寒之象。","treat":"温中健脾，和胃降逆。","formulaRaw":"丁香透膈汤（《医门法律》）加减。","formulaName":"丁香透膈汤加减","fangjie":"人参、白术、炙甘草健脾益气；丁香、半夏、木香、香附温中和胃降逆；砂仁、白豆蔻、神曲、麦芽醒脾化食。\n若胃虚气逆，呕吐甚者，加旋覆花、代赭石；吐甚而气阴耗伤者，去丁香、砂仁、白豆蔻，加沙参、麦冬；阳虚停饮，胸膈不利者，加桂枝、附子（制）、生姜；脘腹满闷，肢体困重者，加苍术、厚朴、茯苓、泽泻；畏寒肢冷，腰膝酸软重者，加肉桂、补骨脂。"}]},{"id":"a005","name":"萎黄","kind":"attach","parent":"d029","parentName":"黄疸","chapterNo":"第三十二章","raw":[{"t":"p","x":"萎黄是由脾土虚弱，水谷不能生化精微及气血引起的，以肌肤萎黄无光泽为主要临床表现的病证。本病是由于虫积食滞或劳伤过度导致脾土虚弱，运化失职，水谷不能化精微而生气血，气血衰少，肌肤失养，以致肌肤萎黄无光泽。此外，失血过多，或大病之后，血亏气耗，肌肤失养，而发本病，临床亦属常见。"}],"syndrome":[]},{"id":"a006","name":"尿浊","kind":"attach","parent":"d035","parentName":"淋证","chapterNo":"第三十八章","raw":[{"t":"p","x":"尿浊是以小便浑浊、白如泪浆、尿时无涩痛不利感为主症的疾病。尿浊病机为湿热下注，脾肾亏虚。多由过食肥甘厚味食物，脾失健运，酿湿生热，或某些疾病（如血丝虫病）病后，湿热余邪未清，蕴结下焦，清浊相混，而成尿浊。"},{"t":"h","lv":5,"x":"1. 湿热下注证"},{"t":"p","x":"临床表现：小便浑浊，色白或黄或红，或夹凝块，上有浮油，或伴血块，尿道有灼热感，口苦，口干，舌质红，苔黄腻，脉濡数。"},{"t":"p","x":"证候分析：湿热下注膀胱，气化不利，清浊不分，脂液失摄，随尿而下，故见尿液浑浊；若热重于湿，湿热熏蒸，则尿色偏黄；若湿热灼伤血络，络损血溢，则尿色泛红或夹血块；湿热煎熬津液，结成凝块，脂液上浮，故见上有浮油；湿热蕴结膀胱，循经灼伤尿道，故见灼热疼痛；湿热内蕴，蒸腾上泛，津液不上承，故口苦口干；舌质红，苔黄腻，脉濡数，均为湿热内蕴之象。"},{"t":"p","x":"治法：清热利湿，分清泄浊。"},{"t":"p","x":"代表方：草薜分清饮（《医学心悟》）加减。"},{"t":"p","x":"革利湿，分清化浊；黄柏、车前子清热利湿泄浊；石菖蒲芳香化浊，分利小便；茯苓、白术健脾渗湿；莲子心、丹参清心泻热。"},{"t":"p","x":"若小腹胀，尿涩不畅，加鸟药、青皮、郁金；伴有血尿，加小蓟、侧柏叶、藕节、白茅根。"},{"t":"h","lv":5,"x":"2. 脾虚气陷证"},{"t":"p","x":"临床表现：尿浊反复发作，日久不愈，状如白浆，小腹坠胀，神倦无力，面色无华，劳累后发作或加重，舌淡，苔白，脉虚软。"},{"t":"p","x":"证候分析：脾胃虚弱，中气不足，升举无力，清气下陷，则水谷精微不得上输而反下注膀胱，混杂于尿液中，故见尿浊如白浆；中气下陷，升提无权，下焦气机壅滞，故见小腹坠胀；脾虚气血生化乏源，四肢百骸失养，故神疲乏力，面色无华；劳则气耗，故劳累后发作或加重；舌淡，苔白，脉虚软，均为脾虚之象。"},{"t":"p","x":"治法：健脾益气，升清固摄。"},{"t":"p","x":"代表方：补中益气汤（《内外伤辨惑论》）加减。"},{"t":"p","x":"黄芪补中益气，升阳；人参、白术补气健脾；当归养血和营；陈皮理气和胃；升麻、柴胡升阳举陷；炙甘草补脾和中，调和诸药。"},{"t":"p","x":"若尿浊夹血，加仙鹤草、藕节、阿胶、墨旱莲；肢冷便溏，加附子（制）、炮姜。"},{"t":"h","lv":5,"x":"3. 肾虚不固证"},{"t":"p","x":"临床表现：尿浊日久不愈，小便乳白如脂膏，精神萎靡，消瘦无力，头晕耳鸣，腰膝酸软。肾阴亏虚者，兼见烦热，口干，舌质红，脉细数；肾阳亏虚者，可见面色㿠白，形寒肢冷，舌质淡红，脉沉细。"},{"t":"p","x":"证候分析：久病或劳损伤及肾元，致肾气亏虚，固摄无权，精微物质随尿液下泄，故见尿浊日久不愈，小便乳白如脂膏；肾精亏虚，元气不足，脏腑形体失于充养，故见精神不振，疲惫萎靡，形体消瘦，周身无力；肾精亏虚，不能上充于脑窍，髓海空虚，故头晕；肾开窍于耳，耳失所养，故耳鸣；腰为肾之府，肾精亏虚，府邸失养，故腰膝酸软；舌红，脉细数，为肾阴亏虚之象；舌淡，脉沉细，为肾阳亏虚之象。"},{"t":"p","x":"治法：偏肾阴虚者，宜滋阴益肾；偏肾阳虚者，宜温肾固摄。"},{"t":"p","x":"代表方：偏肾阴虚者，用知柏地黄丸（《医方考》）加减；偏肾阳虚者，用鹿茸补涩丸（《杂病源流犀烛》)加减。"},{"t":"p","x":"前方滋阴益肾，后方温肾固摄。"},{"t":"p","x":"前方熟地黄、山茱萸、山药滋补肾阴；泽泻、茯苓、牡丹皮利湿泄浊；知母、黄柏清泻虚火。"},{"t":"p","x":"后方附子（制）、肉桂、鹿茸、补骨脂、菟丝子温补肾阳；人参、黄芪、茯苓补脾肾之气；五味子、莲肉养心滋肾，补脾涩精；龙骨、桑螵蛸益肾固涩。"},{"t":"p","x":"若尿浊夹血者，加阿胶、生地黄、墨旱莲；脾气不足者，加黄芪、党参、白术。"},{"t":"p","x":"上述诸证的治疗，不论虚实，均可加玉米须、马鞭草、飞廉、葵花秆心以增强疗效。"}],"syndrome":[{"id":"s229","name":"湿热下注证","label":"1. 湿热下注证","group":"","clinic":"小便浑浊，色白或黄或红，或夹凝块，上有浮油，或伴血块，尿道有灼热感，口苦，口干，舌质红，苔黄腻，脉濡数。","analysis":"湿热下注膀胱，气化不利，清浊不分，脂液失摄，随尿而下，故见尿液浑浊；若热重于湿，湿热熏蒸，则尿色偏黄；若湿热灼伤血络，络损血溢，则尿色泛红或夹血块；湿热煎熬津液，结成凝块，脂液上浮，故见上有浮油；湿热蕴结膀胱，循经灼伤尿道，故见灼热疼痛；湿热内蕴，蒸腾上泛，津液不上承，故口苦口干；舌质红，苔黄腻，脉濡数，均为湿热内蕴之象。","treat":"清热利湿，分清泄浊。","formulaRaw":"草薜分清饮（《医学心悟》）加减。","formulaName":"草薜分清饮加减","fangjie":"革利湿，分清化浊；黄柏、车前子清热利湿泄浊；石菖蒲芳香化浊，分利小便；茯苓、白术健脾渗湿；莲子心、丹参清心泻热。\n若小腹胀，尿涩不畅，加鸟药、青皮、郁金；伴有血尿，加小蓟、侧柏叶、藕节、白茅根。"},{"id":"s230","name":"脾虚气陷证","label":"2. 脾虚气陷证","group":"","clinic":"尿浊反复发作，日久不愈，状如白浆，小腹坠胀，神倦无力，面色无华，劳累后发作或加重，舌淡，苔白，脉虚软。","analysis":"脾胃虚弱，中气不足，升举无力，清气下陷，则水谷精微不得上输而反下注膀胱，混杂于尿液中，故见尿浊如白浆；中气下陷，升提无权，下焦气机壅滞，故见小腹坠胀；脾虚气血生化乏源，四肢百骸失养，故神疲乏力，面色无华；劳则气耗，故劳累后发作或加重；舌淡，苔白，脉虚软，均为脾虚之象。","treat":"健脾益气，升清固摄。","formulaRaw":"补中益气汤（《内外伤辨惑论》）加减。","formulaName":"补中益气汤加减","fangjie":"黄芪补中益气，升阳；人参、白术补气健脾；当归养血和营；陈皮理气和胃；升麻、柴胡升阳举陷；炙甘草补脾和中，调和诸药。\n若尿浊夹血，加仙鹤草、藕节、阿胶、墨旱莲；肢冷便溏，加附子（制）、炮姜。"},{"id":"s231","name":"肾虚不固证","label":"3. 肾虚不固证","group":"","clinic":"尿浊日久不愈，小便乳白如脂膏，精神萎靡，消瘦无力，头晕耳鸣，腰膝酸软。肾阴亏虚者，兼见烦热，口干，舌质红，脉细数；肾阳亏虚者，可见面色㿠白，形寒肢冷，舌质淡红，脉沉细。","analysis":"久病或劳损伤及肾元，致肾气亏虚，固摄无权，精微物质随尿液下泄，故见尿浊日久不愈，小便乳白如脂膏；肾精亏虚，元气不足，脏腑形体失于充养，故见精神不振，疲惫萎靡，形体消瘦，周身无力；肾精亏虚，不能上充于脑窍，髓海空虚，故头晕；肾开窍于耳，耳失所养，故耳鸣；腰为肾之府，肾精亏虚，府邸失养，故腰膝酸软；舌红，脉细数，为肾阴亏虚之象；舌淡，脉沉细，为肾阳亏虚之象。","treat":"偏肾阴虚者，宜滋阴益肾；偏肾阳虚者，宜温肾固摄。","formulaRaw":"偏肾阴虚者，用知柏地黄丸（《医方考》）加减；偏肾阳虚者，用鹿茸补涩丸（《杂病源流犀烛》)加减。","formulaName":"知柏地黄丸加减；鹿茸补涩丸加减","fangjie":"前方滋阴益肾，后方温肾固摄。\n前方熟地黄、山茱萸、山药滋补肾阴；泽泻、茯苓、牡丹皮利湿泄浊；知母、黄柏清泻虚火。\n后方附子（制）、肉桂、鹿茸、补骨脂、菟丝子温补肾阳；人参、黄芪、茯苓补脾肾之气；五味子、莲肉养心滋肾，补脾涩精；龙骨、桑螵蛸益肾固涩。\n若尿浊夹血者，加阿胶、生地黄、墨旱莲；脾气不足者，加黄芪、党参、白术。\n上述诸证的治疗，不论虚实，均可加玉米须、马鞭草、飞廉、葵花秆心以增强疗效。"}]},{"id":"a007","name":"关格","kind":"attach","parent":"d036","parentName":"癃闭","chapterNo":"第三十九章","raw":[{"t":"p","x":"关格是由脾肾虚衰，气化不利，浊邪塞三焦引起的，以小便不通与呕吐并见为主要临床表现的病证，属危重病证范围。小便不通谓之关，呕吐时作称之格。关格的基本病机是脾肾衰惫，气化不利，湿浊毒邪内蕴三焦，多因水肿、淋证、癫闭等病证久治不愈，或失治误治，迁延日久而致。病位在脾（胃）、肾（膀胱)，以肾为关键，涉及肺、肝、心等多脏。"},{"t":"h","lv":5,"x":"1. 脾肾阳虚，湿浊内蕴"},{"t":"p","x":"临床表现：小便短少，色清，甚则尿闭，面色晦滞，形寒肢冷，神疲乏力，浮肿腰以下为主，纳差，腹胀，泛恶呕吐，大便溏薄，舌淡胖，有齿痕，苔白腻，脉沉细。"},{"t":"p","x":"证候分析：脾肾阳虚，气化无力，水液无以输布，故见小便短少，色清，甚则尿闭；阳虚不能温煦形体，故形寒肢冷，神疲乏力；湿浊内停，泛溢肌肤，则见浮肿；湿浊趋下，故腰以下为甚；湿浊困阻中焦，脾胃纳运失常，故纳差，腹胀，泛恶呕吐，大便溏薄；阳气亏虚，浊阴弥漫，气血失荣，故面色晦滞；舌淡胖，有齿痕，苔白腻，脉沉细，为脾肾阳虚、湿浊内蕴之象。"},{"t":"p","x":"治法：温补脾肾，化湿降浊。"},{"t":"p","x":"代表方：温脾汤（《备急千金要方》）合吴茱萸汤（《伤寒论》）加减。"},{"t":"p","x":"附子（制）、干姜、淫羊藿温补肾阳；人参、白术、茯苓益气健脾；姜半夏、陈皮、制大黄、六月雪化湿降浊；吴茱萸、生姜降逆止呕。"},{"t":"p","x":"痰湿壅肺者，合用小青龙汤；水气凌心者，加用已椒劳黄丸；尿少或小便不通者，合用滋肾通关丸。"},{"t":"h","lv":5,"x":"2. 肝肾阴虚，虚风内动"},{"t":"p","x":"临床表现：小便短少，呕恶频作，头晕头痛，面部烘热，腰膝酸软，手足抽搐，舌红，苔黄腻，脉弦细。"},{"t":"p","x":"证候分析：肾阴亏耗，水不涵木，以致肝阳上亢，虚风内动，故见头晕头痛，面部烘热，手足抽搐；肾虚则腰府失养，骨髓不充，故腰膝酸软；溺毒内停，上干于胃，胃失和降，故呕恶频作；肾阳虚衰，气化无权，湿浊内蕴，故小便短少；舌红，苔黄腻，脉弦细，为阴虚阳亢、湿浊未化之象。"},{"t":"p","x":"治法：滋补肝肾，平肝息风。"},{"t":"p","x":"代表方：杞菊地黄丸（《医级》）合羚角钩藤汤（《通俗伤寒论》)加减。"},{"t":"p","x":"熟地黄、山药、山茱萸、枸杞子滋补肝肾；泽泻、茯苓利湿泄浊；丹皮清肝泻火；羚羊角、钩藤、石决明平肝息风；贝母、竹茹、胆南星、竹沥化痰止呕；制大黄、败酱草、六月雪降浊解毒。"},{"t":"p","x":"大便秘结者，加生大黄；浊邪入营动血者，合用犀角地黄汤、清营汤等，同时配合至宝丹或紫雪丹。"},{"t":"p","x":"风阳内动导致中风者，按中风论治。"},{"t":"h","lv":5,"x":"3. 肾气衰微，邪陷心包"},{"t":"p","x":"临床表现：无尿或少尿，全身浮肿，面白唇暗，四肢厥冷，口中尿臭，神志昏蒙，循衣摸床，舌卷缩，淡胖，苔白腻或灰黑，脉沉细欲绝。"},{"t":"p","x":"证候分析：肾气衰微，气化功能丧失，故见无尿或少尿；水液泛滥肌肤，则全身浮肿；阳气衰极，不能温煦四末、荣润颜面，故四肢厥冷，面白唇暗；湿浊毒邪内蕴，随胃气上逆，则口中尿臭；浊毒深重，内陷心包，蒙蔽心神，故见神志昏蒙，循衣摸床；舌卷缩，淡胖，苔白腻或灰黑，脉沉细欲绝均为阳气衰败、浊毒内陷、阴阳离决之危象。"},{"t":"p","x":"治法：温阳固脱，豁痰开窍。"},{"t":"p","x":"代表方：急用参附汤（《正体类要》）合苏合香丸（《开元广济方》），继用涤痰汤（《奇效良方》）加减。"},{"t":"p","x":"人参、附子（制）回阳固脱；苏合香丸开窍醒神；胆南星、石菖蒲、半夏、竹茹豁痰开窍。"},{"t":"p","x":"昏迷不醒者，用醒脑静注射液静脉滴注；见气阴耗竭征象者，用生脉散；狂躁痉厥，服紫雪丹；心阳欲脱者，急用参附龙牡汤。"},{"t":"p","x":"此外，对于关格患者，还可用保留灌肠法，以加强通腑降浊解毒的作用。"}],"syndrome":[{"id":"s239","name":"脾肾阳虚，湿浊内蕴","label":"1. 脾肾阳虚，湿浊内蕴","group":"","clinic":"小便短少，色清，甚则尿闭，面色晦滞，形寒肢冷，神疲乏力，浮肿腰以下为主，纳差，腹胀，泛恶呕吐，大便溏薄，舌淡胖，有齿痕，苔白腻，脉沉细。","analysis":"脾肾阳虚，气化无力，水液无以输布，故见小便短少，色清，甚则尿闭；阳虚不能温煦形体，故形寒肢冷，神疲乏力；湿浊内停，泛溢肌肤，则见浮肿；湿浊趋下，故腰以下为甚；湿浊困阻中焦，脾胃纳运失常，故纳差，腹胀，泛恶呕吐，大便溏薄；阳气亏虚，浊阴弥漫，气血失荣，故面色晦滞；舌淡胖，有齿痕，苔白腻，脉沉细，为脾肾阳虚、湿浊内蕴之象。","treat":"温补脾肾，化湿降浊。","formulaRaw":"温脾汤（《备急千金要方》）合吴茱萸汤（《伤寒论》）加减。","formulaName":"温脾汤合吴茱萸汤加减","fangjie":"附子（制）、干姜、淫羊藿温补肾阳；人参、白术、茯苓益气健脾；姜半夏、陈皮、制大黄、六月雪化湿降浊；吴茱萸、生姜降逆止呕。\n痰湿壅肺者，合用小青龙汤；水气凌心者，加用已椒劳黄丸；尿少或小便不通者，合用滋肾通关丸。"},{"id":"s240","name":"肝肾阴虚，虚风内动","label":"2. 肝肾阴虚，虚风内动","group":"","clinic":"小便短少，呕恶频作，头晕头痛，面部烘热，腰膝酸软，手足抽搐，舌红，苔黄腻，脉弦细。","analysis":"肾阴亏耗，水不涵木，以致肝阳上亢，虚风内动，故见头晕头痛，面部烘热，手足抽搐；肾虚则腰府失养，骨髓不充，故腰膝酸软；溺毒内停，上干于胃，胃失和降，故呕恶频作；肾阳虚衰，气化无权，湿浊内蕴，故小便短少；舌红，苔黄腻，脉弦细，为阴虚阳亢、湿浊未化之象。","treat":"滋补肝肾，平肝息风。","formulaRaw":"杞菊地黄丸（《医级》）合羚角钩藤汤（《通俗伤寒论》)加减。","formulaName":"杞菊地黄丸合羚角钩藤汤加减","fangjie":"熟地黄、山药、山茱萸、枸杞子滋补肝肾；泽泻、茯苓利湿泄浊；丹皮清肝泻火；羚羊角、钩藤、石决明平肝息风；贝母、竹茹、胆南星、竹沥化痰止呕；制大黄、败酱草、六月雪降浊解毒。\n大便秘结者，加生大黄；浊邪入营动血者，合用犀角地黄汤、清营汤等，同时配合至宝丹或紫雪丹。\n风阳内动导致中风者，按中风论治。"},{"id":"s241","name":"肾气衰微，邪陷心包","label":"3. 肾气衰微，邪陷心包","group":"","clinic":"无尿或少尿，全身浮肿，面白唇暗，四肢厥冷，口中尿臭，神志昏蒙，循衣摸床，舌卷缩，淡胖，苔白腻或灰黑，脉沉细欲绝。","analysis":"肾气衰微，气化功能丧失，故见无尿或少尿；水液泛滥肌肤，则全身浮肿；阳气衰极，不能温煦四末、荣润颜面，故四肢厥冷，面白唇暗；湿浊毒邪内蕴，随胃气上逆，则口中尿臭；浊毒深重，内陷心包，蒙蔽心神，故见神志昏蒙，循衣摸床；舌卷缩，淡胖，苔白腻或灰黑，脉沉细欲绝均为阳气衰败、浊毒内陷、阴阳离决之危象。","treat":"温阳固脱，豁痰开窍。","formulaRaw":"急用参附汤（《正体类要》）合苏合香丸（《开元广济方》），继用涤痰汤（《奇效良方》）加减。","formulaName":"参附汤合苏合香丸，继用涤痰汤加减","fangjie":"人参、附子（制）回阳固脱；苏合香丸开窍醒神；胆南星、石菖蒲、半夏、竹茹豁痰开窍。\n昏迷不醒者，用醒脑静注射液静脉滴注；见气阴耗竭征象者，用生脉散；狂躁痉厥，服紫雪丹；心阳欲脱者，急用参附龙牡汤。\n此外，对于关格患者，还可用保留灌肠法，以加强通腑降浊解毒的作用。"}]},{"id":"a008","name":"早泄","kind":"attach","parent":"d038","parentName":"遗精","chapterNo":"第四十一章","raw":[{"t":"p","x":"早泄是指性交时射精过早，甚至未交即泄或乍交即泄，以致不能进行正常性交为主要表现的一种病证。早泄多因情志内伤、湿热侵袭、纵欲过度、久病体虚所致。精关封藏失职为基本病机，责之于心、肝、肾。"},{"t":"h","lv":5,"x":"1. 肝经湿热证"},{"t":"p","x":"临床表现：早泄，阳强易举，伴口苦咽干，胸闷胁痛，阴囊湿痒，小便黄浊，舌红，苔黄腻，脉弦滑而数。"},{"t":"p","x":"证候分析：肝胆实火，循经上炎，则口苦咽干；肝火郁结，经脉不舒，则胸闷胁痛；湿热下注，扰动精室，精关不固，故发为早泄；湿热下注于前阴，则为阴囊湿痒，小便黄浊；舌红苔黄腻，脉弦滑而数，均为肝经湿热内盛之象。"},{"t":"p","x":"治法：清泻肝经湿热。"},{"t":"p","x":"代表方：龙胆泻肝汤（《医方集解》）加减。"},{"t":"p","x":"龙胆草泻肝胆实火；黄芩、栀子苦寒清热燥湿；泽泻、木通、车前子清利湿热；当归、生地黄养血益阴；柴胡疏达肝气；甘草益气和中，调和诸药。"},{"t":"p","x":"湿热壅盛者，加苦参、白花蛇舌草、黄柏；阴囊潮湿、瘙痒者，加土茯苓、地肤子、蛇床子。"},{"t":"h","lv":5,"x":"2. 心脾两虚证"},{"t":"p","x":"临床表现：早泄，心悸怔忡，健忘多梦，食少，腹胀便溏，神疲乏力，舌淡，脉细弱。"},{"t":"p","x":"证候分析：思虑过度，心脾两虚，气血双亏，宗筋失养，故见早泄；气血生化不足，心失所养，心神不宁，则心悸怔忡，健忘多梦；气血亏虚，机体失养，故神疲乏力；脾气虚弱，运化失职，故食少，腹胀便溏；舌淡，脉细弱，均为气血不足之象。"},{"t":"p","x":"治法：补益心脾。"},{"t":"p","x":"代表方：归脾汤（《济生方》）加减。"},{"t":"p","x":"黄芪补脾益气；龙眼肉补脾气，养心血；人参、白术健脾益气；当归补血养心；酸枣仁宁心安神；茯神养心安神；远志宁神益智；木香理气醒脾；生姜、大枣调和脾胃；炙甘草补益心脾之气，调和诸药。"},{"t":"p","x":"若伴有肾虚，加山萸肉、杜仲、菟丝子、金樱子、芡实；心阴不足者，合用生脉散。"},{"t":"h","lv":5,"x":"3. 相火妄动证"},{"t":"p","x":"临床表现：早泄，阳事易举，腰膝酸软，五心烦热，潮热盗汗，舌红少苔，脉细数。"},{"t":"p","x":"证候分析：肾阴不足，腰膝失养，故腰膝酸软；阴虚火旺，相火妄动，扰动精室，精关不固，则早泄，阳事易举；虚火内扰，灼伤津液，故五心烦热，潮热盗汗；舌红少苔，脉细数，均为阴虚内热之象。"},{"t":"p","x":"治法：滋阴降火。"},{"t":"p","x":"代表方：知柏地黄丸（《医宗金鉴》）加减。"},{"t":"p","x":"熟地黄、山菜萸、山药滋补肝肾之阴，填精益髓；知母、黄柏苦寒沉降，清泻相火，坚阴除热；丹皮清泄肝火；泽泻清泄肾经虚火；茯苓健脾渗湿。"},{"t":"p","x":"若遗精明显者，加金樱子、沙苑子、女贞子、旱莲草、龟甲；五心烦热明显者，加鳖甲、地骨皮；肾虚腰酸者，加续断、狗脊、杜仲。"},{"t":"h","lv":5,"x":"4. 肾气不固证"},{"t":"p","x":"临床表现：早泄遗精，性欲减退，腰膝酸软，小便清长，夜尿多，面色㿠白，舌淡苔白，脉沉弱。"},{"t":"p","x":"证候分析：肾主藏精，司二阴。肾气亏虚，固摄无权，精关不固，故见早泄遗精；肾气不足，命门火衰，鼓动无力，故性欲减退；腰为肾之府，肾虚失于濡养，故腰膝酸软；肾虚膀胱气化失司，水液代谢失常，膀胱失约，故小便清长，夜尿多；面色㿠白，舌淡苔白，脉沉弱，均为肾气亏虚、温煦失职之象。"},{"t":"p","x":"治法：益肾固精。"},{"t":"p","x":"代表方：金匮肾气丸（《金匮要略》）加减。"},{"t":"p","x":"附子（制）、桂枝温补肾阳，助命门之火，以鼓舞肾气；干地黄滋阴补肾，填精益髓；山茱萸、山药补肝脾，益精血；泽泻、茯苓利水渗湿；丹皮清泄肝火。"},{"t":"p","x":"若遗精明显者，加龙骨、牡蛎、杜仲、肉从蓉、菟丝子、金樱子、芡实；夜尿频多者，加益智仁、乌药。"},{"t":"p","x":"早泄而精冷，改用赞育丹。"}],"syndrome":[{"id":"s251","name":"肝经湿热证","label":"1. 肝经湿热证","group":"","clinic":"早泄，阳强易举，伴口苦咽干，胸闷胁痛，阴囊湿痒，小便黄浊，舌红，苔黄腻，脉弦滑而数。","analysis":"肝胆实火，循经上炎，则口苦咽干；肝火郁结，经脉不舒，则胸闷胁痛；湿热下注，扰动精室，精关不固，故发为早泄；湿热下注于前阴，则为阴囊湿痒，小便黄浊；舌红苔黄腻，脉弦滑而数，均为肝经湿热内盛之象。","treat":"清泻肝经湿热。","formulaRaw":"龙胆泻肝汤（《医方集解》）加减。","formulaName":"龙胆泻肝汤加减","fangjie":"龙胆草泻肝胆实火；黄芩、栀子苦寒清热燥湿；泽泻、木通、车前子清利湿热；当归、生地黄养血益阴；柴胡疏达肝气；甘草益气和中，调和诸药。\n湿热壅盛者，加苦参、白花蛇舌草、黄柏；阴囊潮湿、瘙痒者，加土茯苓、地肤子、蛇床子。"},{"id":"s252","name":"心脾两虚证","label":"2. 心脾两虚证","group":"","clinic":"早泄，心悸怔忡，健忘多梦，食少，腹胀便溏，神疲乏力，舌淡，脉细弱。","analysis":"思虑过度，心脾两虚，气血双亏，宗筋失养，故见早泄；气血生化不足，心失所养，心神不宁，则心悸怔忡，健忘多梦；气血亏虚，机体失养，故神疲乏力；脾气虚弱，运化失职，故食少，腹胀便溏；舌淡，脉细弱，均为气血不足之象。","treat":"补益心脾。","formulaRaw":"归脾汤（《济生方》）加减。","formulaName":"归脾汤加减","fangjie":"黄芪补脾益气；龙眼肉补脾气，养心血；人参、白术健脾益气；当归补血养心；酸枣仁宁心安神；茯神养心安神；远志宁神益智；木香理气醒脾；生姜、大枣调和脾胃；炙甘草补益心脾之气，调和诸药。\n若伴有肾虚，加山萸肉、杜仲、菟丝子、金樱子、芡实；心阴不足者，合用生脉散。"},{"id":"s253","name":"相火妄动证","label":"3. 相火妄动证","group":"","clinic":"早泄，阳事易举，腰膝酸软，五心烦热，潮热盗汗，舌红少苔，脉细数。","analysis":"肾阴不足，腰膝失养，故腰膝酸软；阴虚火旺，相火妄动，扰动精室，精关不固，则早泄，阳事易举；虚火内扰，灼伤津液，故五心烦热，潮热盗汗；舌红少苔，脉细数，均为阴虚内热之象。","treat":"滋阴降火。","formulaRaw":"知柏地黄丸（《医宗金鉴》）加减。","formulaName":"知柏地黄丸加减","fangjie":"熟地黄、山菜萸、山药滋补肝肾之阴，填精益髓；知母、黄柏苦寒沉降，清泻相火，坚阴除热；丹皮清泄肝火；泽泻清泄肾经虚火；茯苓健脾渗湿。\n若遗精明显者，加金樱子、沙苑子、女贞子、旱莲草、龟甲；五心烦热明显者，加鳖甲、地骨皮；肾虚腰酸者，加续断、狗脊、杜仲。"},{"id":"s254","name":"肾气不固证","label":"4. 肾气不固证","group":"","clinic":"早泄遗精，性欲减退，腰膝酸软，小便清长，夜尿多，面色㿠白，舌淡苔白，脉沉弱。","analysis":"肾主藏精，司二阴。肾气亏虚，固摄无权，精关不固，故见早泄遗精；肾气不足，命门火衰，鼓动无力，故性欲减退；腰为肾之府，肾虚失于濡养，故腰膝酸软；肾虚膀胱气化失司，水液代谢失常，膀胱失约，故小便清长，夜尿多；面色㿠白，舌淡苔白，脉沉弱，均为肾气亏虚、温煦失职之象。","treat":"益肾固精。","formulaRaw":"金匮肾气丸（《金匮要略》）加减。","formulaName":"金匮肾气丸加减","fangjie":"附子（制）、桂枝温补肾阳，助命门之火，以鼓舞肾气；干地黄滋阴补肾，填精益髓；山茱萸、山药补肝脾，益精血；泽泻、茯苓利水渗湿；丹皮清泄肝火。\n若遗精明显者，加龙骨、牡蛎、杜仲、肉从蓉、菟丝子、金樱子、芡实；夜尿频多者，加益智仁、乌药。\n早泄而精冷，改用赞育丹。"}]}],"stats":{"diseases":53,"attaches":8,"syndromes":367,"tables":12}};